def _xml_dir_rel(id_empresa, when=None, id_cliente=None):
    """Caminho relativo dentro do bucket: YYYY/YYYY-MM/CLIENTE/EMPRESA.

    id_cliente: se não fornecido, busca em session['id_cliente'].
                Cai para '000000' se nenhum estiver disponível.
    """
    when = when or datetime.now()
    if id_cliente is None:
        try:
            id_cliente = session.get("id_cliente")
        except Exception:
            id_cliente = None
    return (f"{when.strftime('%Y')}/{when.strftime('%Y-%m')}/"
            f"{str(id_cliente or 0).zfill(6)}/"
            f"{str(id_empresa).zfill(6)}")

def _xml_erro_save(_pref, etapa, msg, exc=None):
    """Grava um XML pequeno com a mensagem de erro do envio.
    Permite rastrear no viewer onde o fluxo de envio parou.
    etapa: número da etapa em que o erro aconteceu (2, 3, 4, 5...)."""
    tipo  = f"\n  <tipo>{type(exc).__name__}</tipo>" if exc else ""
    ts    = datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
    safe  = str(msg).replace("]]>", "]]&gt;")
    xml   = (f'<?xml version="1.0" encoding="UTF-8"?>\n'
             f'<erro etapa="{etapa}">\n'
             f'  <msg><![CDATA[{safe}]]></msg>{tipo}\n'
             f'  <ts>{ts}</ts>\n'
             f'</erro>\n')
    _xml_save(f"{_pref}_{etapa}_erro.xml", xml)


def _xml_save(rel_path, content):
    """
    Sobe XML para o Supabase Storage (bucket 'esocial-xml').
    Em dev (fora do Render) também grava cópia local em ./eSocial_XML para debug.
    rel_path: caminho relativo (ex: '2026/2026-06/000001/S2220_xxx_1_evento.xml')
    content : str ou bytes
    Retorna True se subiu pro Storage com sucesso.
    """
    data = content.encode("utf-8") if isinstance(content, str) else content
    ok = False
    # 1) Sobe para o Supabase Storage
    try:
        _supabase_storage.storage.from_(_ESOC_BUCKET).upload(
            path=rel_path, file=data,
            file_options={"content-type": "application/xml", "upsert": "true"})
        ok = True
        print(f"[XML] OK Storage: {rel_path}")
    except Exception as e:
        print(f"[XML] ERRO Storage '{rel_path}': {type(e).__name__}: {e}")
        _log_xml.warning(f"_xml_save: falha upload Storage '{rel_path}': {e}")
    # 2) Sempre tenta também no disco local do servidor (cópia / debug)
    try:
        full = _os_xml.path.join(
            _os_xml.path.dirname(__file__), "eSocial_XML", rel_path)
        _os_xml.makedirs(_os_xml.path.dirname(full), exist_ok=True)
        with open(full, "wb") as _f:
            _f.write(data)
        print(f"[XML] OK Local:   {full}")
    except Exception as e:
        print(f"[XML] ERRO Local '{rel_path}': {type(e).__name__}: {e}")
    return ok

# =========================================================
# CERTIFICADO DIGITAL — HELPERS
# =========================================================
def _cert_fernet():
    from cryptography.fernet import Fernet
    raw = (os.getenv("FLASK_SECRET_KEY", "F10default") + "_cert_v1").encode()
    key = base64.urlsafe_b64encode(hashlib.sha256(raw).digest())
    return Fernet(key)

def _cert_encrypt(text):
    return _cert_fernet().encrypt(text.encode()).decode()

def _cert_decrypt(token):
    return _cert_fernet().decrypt(token.encode()).decode()

def _cert_info(pfx_bytes, senha_str):
    """Valida o .pfx e retorna dict com titular, CNPJ e validade."""
    from cryptography.hazmat.primitives.serialization import pkcs12
    from cryptography import x509
    from cryptography.x509.oid import NameOID, ExtensionOID

    senha = senha_str.encode("utf-8") if isinstance(senha_str, str) else senha_str
    try:
        _pk, cert, _chain = pkcs12.load_key_and_certificates(pfx_bytes, senha)
    except Exception as e:
        raise ValueError(f"Senha incorreta ou arquivo inválido: {e}")

    # Validade
    try:
        not_after = cert.not_valid_after_utc   # cryptography >= 42
    except AttributeError:
        not_after = cert.not_valid_after
    validade     = not_after.strftime("%Y%m%d")
    validade_fmt = not_after.strftime("%d/%m/%Y")

    # Common Name
    try:
        cn = cert.subject.get_attributes_for_oid(NameOID.COMMON_NAME)[0].value
    except Exception:
        cn = ""

    # CNPJ — tenta serialNumber (ICP-Brasil padrão)
    cnpj = ""
    try:
        sn = cert.subject.get_attributes_for_oid(NameOID.SERIAL_NUMBER)[0].value
        digits = re.sub(r"\D", "", sn)
        if len(digits) in (11, 14):
            cnpj = digits
    except Exception:
        pass

    # Fallback: OID ICP-Brasil 2.16.76.1.3.3 (CNPJ na SAN Other Name)
    if not cnpj:
        try:
            san = cert.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME)
            for name in san.value:
                val = getattr(name, "value", b"")
                digits = re.sub(r"\D", "", val.decode("latin-1") if isinstance(val, bytes) else str(val))
                if len(digits) == 14:
                    cnpj = digits
                    break
        except Exception:
            pass

    # Último recurso: 14 dígitos consecutivos no CN
    if not cnpj:
        m = re.search(r"\d{14}", cn)
        if m:
            cnpj = m.group(0)

    # Titular: parte antes dos ":" que alguns CAs colocam no CN
    titular = cn.split(":")[0].strip() if ":" in cn else cn.strip()

    return {
        "titular":     titular,
        "cnpj":        cnpj,
        "validade":    validade,
        "validade_fmt": validade_fmt,
    }


def _aplicar_cert_esocial(empresa):
    """Resolve o certificado EFETIVO usado para assinar/transmitir ao eSocial.

    Trata o caso de o cliente transmitir com certificado de TERCEIROS via
    procuração eletrônica (escritório/contador). Muta o dict `empresa` in-place:

      • cert_modo == 'procuracao' + id_procurador válido  → injeta o cert do
        procurador em cert_pfx_b64/cert_senha_enc e define o transmissor
        (_tra_tpinsc/_tra_nrinsc) com a inscrição do procurador (CNPJ=1 ou CPF=2).
      • qualquer outro caso  → mantém o cert próprio e transmissor = próprio
        empregador (tpInsc=1, CNPJ da empresa). Comportamento 100% atual.

    Sempre define empresa["_tra_tpinsc"] e empresa["_tra_nrinsc"], consumidos por
    _montar_lote/_montar_lote_multi para preencher o <ideTransmissor> do lote.
    Retorna o próprio dict (para encadear). Nunca lança — em falha, cai no fallback.
    """
    cnpj_emp_raw = re.sub(r"\D", "", empresa.get("cnpj") or "")
    modo = (empresa.get("cert_modo") or "proprio").strip().lower()

    if modo == "procuracao" and empresa.get("id_procurador"):
        try:
            proc = (supabase.table("tab_procurador").select("*")
                    .eq("id_procurador", int(empresa["id_procurador"]))
                    .limit(1).execute().data or [None])[0]
        except Exception:
            proc = None
        if proc and proc.get("cert_pfx_b64"):
            empresa["cert_pfx_b64"]  = proc.get("cert_pfx_b64")
            empresa["cert_senha_enc"] = proc.get("cert_senha_enc")
            if proc.get("cert_validade"):
                empresa["cert_validade"] = proc.get("cert_validade")
            tra_nr = re.sub(r"\D", "", proc.get("nrinsc") or "")
            # tpInsc do transmissor: 1=CNPJ (14) / 2=CPF (11); usa o gravado se houver
            empresa["_tra_tpinsc"] = str(proc.get("tpinsc")
                                         or ("2" if len(tra_nr) == 11 else "1"))
            empresa["_tra_nrinsc"] = tra_nr
            return empresa

    # Fallback: certificado próprio, transmissor = próprio empregador (atual)
    empresa["_tra_tpinsc"] = "1"
    empresa["_tra_nrinsc"] = cnpj_emp_raw
    return empresa

