# TROCAR EMPRESA (atalho: 2 empresas → alterna direto; >2 → lista)
# =========================================================
@app.route("/trocar_empresa")
def trocar_empresa():
    if not session.get("logado"):
        return redirect("/")
    id_cliente = session.get("id_cliente")
    empresas   = _listar_empresas(id_cliente)
    if len(empresas) <= 1:
        return redirect("/menu")
    if len(empresas) > 2:
        return redirect("/selecionar_empresa")

    # Exatamente 2: troca para a outra
    id_atual = session.get("id_empresa")
    outra = next((e for e in empresas if e["id_empresa"] != id_atual), None)
    if not outra:
        return redirect("/selecionar_empresa")

    id_empresa = outra["id_empresa"]
    r = (supabase.table("tab_empresa")
         .select("id_empresa, cnpj, razaosocial, nome_fantasia, anomes_atual, anomes_tipo")
         .eq("id_empresa", id_empresa)
         .eq("id_cliente", id_cliente)
         .limit(1)
         .execute())
    if not r.data:
        return redirect("/selecionar_empresa")

    row          = r.data[0]
    anomes_atual = str(row.get("anomes_atual") or "")
    anomes_tipo  = str(row.get("anomes_tipo")  or "")
    situacao     = ""
    if anomes_atual and anomes_tipo:
        try:
            r2 = (supabase.table("tab_anomes")
                  .select("situacao")
                  .eq("id_empresa", id_empresa)
                  .eq("ano_mes",    anomes_atual)
                  .eq("tipo",       anomes_tipo)
                  .limit(1)
                  .execute())
            situacao = (r2.data[0].get("situacao") or "") if r2.data else ""
        except Exception:
            pass

    session["empresa_info"]    = row.get("razaosocial") or row.get("nome_fantasia") or "Empresa"
    session["cnpj_empresa"]    = row.get("cnpj", "")
    session["id_empresa"]      = id_empresa
    session["anomes_atual"]    = anomes_atual
    session["anomes_tipo"]     = anomes_tipo
    session["anomes_situacao"] = situacao
    return redirect("/menu")


# =========================================================
# LICENÇA — VERIFICAÇÃO DE LIMITES CONTRATUAIS
# =========================================================
def _estado_licenca(id_cliente):
    """Retorna dict com limites contratuais do cliente e uso atual.

    Chaves:
      qtd_empresas, qtd_funcionarios      — limites em tab_cliente (0 = SEM licenca)
      atual_empresas, atual_funcionarios  — contagens reais
      sem_licenca                          — True se qtd_empresas ou qtd_funcionarios = 0
      excedeu_empresas, excedeu_funcionarios — atual > limite (limite>0)

    Funcionarios contam por id_cliente excluindo demitidos (situacao='D').
    Empresas contam por id_cliente (sem filtro de status).
    """
    out = {"qtd_empresas": 0, "qtd_funcionarios": 0,
           "atual_empresas": 0, "atual_funcionarios": 0,
           "sem_licenca": True,
           "excedeu_empresas": False, "excedeu_funcionarios": False}
    if not id_cliente:
        return out
    try:
        rl = (supabase.table("tab_cliente")
              .select("qtd_empresas, qtd_funcionarios")
              .eq("id_cliente", id_cliente)
              .limit(1).execute())
        row = (rl.data or [{}])[0]
        out["qtd_empresas"]     = int(row.get("qtd_empresas") or 0)
        out["qtd_funcionarios"] = int(row.get("qtd_funcionarios") or 0)
    except Exception:
        pass
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("id_empresa")
                 .eq("id_cliente", id_cliente).execute())
        out["atual_empresas"] = len(r_emp.data or [])
    except Exception:
        pass
    try:
        r_fun = (supabase.table("tab_cad")
                 .select("matricula")
                 .eq("id_cliente", id_cliente)
                 .neq("situacao", "D").execute())
        out["atual_funcionarios"] = len(r_fun.data or [])
    except Exception:
        pass
    out["sem_licenca"] = (out["qtd_empresas"] == 0 or out["qtd_funcionarios"] == 0)
    if out["qtd_empresas"] > 0:
        out["excedeu_empresas"] = out["atual_empresas"] > out["qtd_empresas"]
    if out["qtd_funcionarios"] > 0:
        out["excedeu_funcionarios"] = out["atual_funcionarios"] > out["qtd_funcionarios"]
    return out


