@app.route("/menu")
def menu():
    if not session.get("logado"):
        return redirect("/")
    if not session.get("id_empresa"):
        return redirect("/selecionar_empresa")
    id_cliente = session.get("id_cliente")
    # Bloqueia acesso ao menu se a licenca esta zerada (qtd_empresas=0 ou
    # qtd_funcionarios=0 em tab_cliente). Redireciona para tela de comprar.
    _lic = _estado_licenca(id_cliente)
    if _lic["sem_licenca"]:
        return redirect("/comprar_licenca?bloqueio=sem_licenca")
    qtd_empresas = len(_listar_empresas(id_cliente)) if id_cliente else 1

    # Data limite da licença (tab_cliente.data_limite, formato "YYYY-MM")
    licenca_fmt = ""
    licenca_classe = ""
    try:
        rl = (supabase.table("tab_cliente")
              .select("data_limite")
              .eq("id_cliente", id_cliente)
              .limit(1).execute())
        dl = (rl.data or [{}])[0].get("data_limite") or ""
        if dl and len(dl) >= 7:
            ano_l, mes_l = dl[:4], dl[5:7]
            licenca_fmt  = f"{mes_l}/{ano_l}"
            limite_am    = ano_l + mes_l
            anomes_atual = str(session.get("anomes_atual") or "")
            if anomes_atual and limite_am > anomes_atual:
                licenca_classe = "lic-ok"     # licença vai além da folha atual
            else:
                licenca_classe = "lic-alerta"  # licença até a folha atual ou expirada
    except Exception:
        pass

    # S-1299 do período atual já enviado com recibo? (libera card Verificação)
    s1299_enviado = False
    try:
        _am = str(session.get("anomes_atual") or "")
        _tp = str(session.get("anomes_tipo")  or "N")
        if _am and len(_am) == 6:
            _r = (supabase.table("tab_esocial")
                  .select("recibo")
                  .eq("id_empresa", session.get("id_empresa"))
                  .eq("layout", "1299")
                  .eq("ano_mes", int(_am))
                  .eq("folha_tipo", _tp)
                  .not_.is_("recibo", "null")
                  .neq("recibo", "")
                  .limit(1).execute())
            s1299_enviado = bool(_r.data)
    except Exception:
        pass

    # Pendências de envio eSocial POR LAYOUT, apenas do mês/ano da folha ativa.
    # Pendente = registro em tab_esocial sem recibo e não EXCLUÍDO (S-3000).
    # Usado no menu para destacar os cards/linhas com remessa pendente.
    esocial_pend = {}
    try:
        _am = str(session.get("anomes_atual") or "")
        if _am and len(_am) == 6:
            _rows_p = (supabase.table("tab_esocial")
                       .select("layout, recibo, observacao_erro")
                       .eq("id_empresa", session.get("id_empresa"))
                       .eq("ano_mes", int(_am))
                       .execute().data or [])
            for _rp in _rows_p:
                rec = (_rp.get("recibo") or "").strip()
                obs = (_rp.get("observacao_erro") or "").strip().upper()
                if not rec and obs != "EXCLUIDO":
                    lay = str(_rp.get("layout") or "")
                    if lay:
                        esocial_pend[lay] = esocial_pend.get(lay, 0) + 1
    except Exception:
        esocial_pend = {}

    # Status do certificado digital A1 da empresa atual (para banner no menu)
    cert_status       = "ok"     # ok | ausente | vence_em | vencido
    cert_dias         = None
    cert_validade_fmt = ""
    try:
        _cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
        if _cnpj_emp:
            _rc = (supabase.table("tab_empresa")
                   .select("cert_pfx_b64, cert_validade")
                   .eq("cnpj", _cnpj_emp)
                   .limit(1).execute())
            _row = (_rc.data or [{}])[0]
            _pfx = _row.get("cert_pfx_b64") or ""
            _val = _row.get("cert_validade") or ""
            if not _pfx:
                cert_status = "ausente"
            elif _val and len(_val) == 8:
                from datetime import date as _date
                _hoje = _date.today()
                _v_dt = _date(int(_val[:4]), int(_val[4:6]), int(_val[6:8]))
                cert_dias = (_v_dt - _hoje).days
                cert_validade_fmt = f"{_val[6:8]}/{_val[4:6]}/{_val[:4]}"
                if cert_dias < 0:
                    cert_status = "vencido"
                elif cert_dias <= 30:
                    cert_status = "vence_em"
    except Exception:
        pass

    return render_template(
        "F10_Menu.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        folha_situacao=str(session.get("anomes_situacao") or ""),
        cpf_usuario=str(session.get("cpf") or ""),
        qtd_empresas=qtd_empresas,
        licenca_fmt=licenca_fmt,
        licenca_classe=licenca_classe,
        menu_numerado=_get_pref("menu_num", "S"),
        s1299_enviado=s1299_enviado,
        esocial_pend=esocial_pend,
        cert_status=cert_status,
        cert_dias=cert_dias,
        cert_validade_fmt=cert_validade_fmt,
        eh_admin_f10=(_is_admin_f10() or bool(session.get("cpf_admin_original"))),
    )

