# PIX — gera BR Code (copia-e-cola) e QR code PNG em base64
# =========================================================
PIX_CHAVE         = "59a207ae-ade1-42fa-bf9f-f790aa78618e"  # chave aleatoria (EVP) do Banco Asaas
PIX_RECEBEDOR     = "Comsist Computacao Ltda"         # max 25 chars (tag 59 BR Code), sem acento. Nome legal completo: "Comsist Computacao & Sistemas Ltda" (nao cabe).
PIX_CIDADE        = "RECIFE"                          # max 15
PIX_WA_NOTIF_TEL  = "81988582000"                     # WhatsApp p/ notificar intencao de compra

def _zapi_conectada():
    """Verifica se a instancia Z-API esta conectada ao WhatsApp.
    Retorna (conectada: bool, info: dict). info contem o JSON da Z-API ou {error}.
    A Z-API aceita /send-text mesmo desconectada (retorna 200 + messageId),
    mas as mensagens NAO sao entregues — por isso esta checagem previa eh necessaria.
    """
    try:
        if not ZAPI_INSTANCE or not ZAPI_TOKEN or not ZAPI_CLIENT_TOKEN:
            return False, {"error": "Z-API nao configurada"}
        url = f"https://api.z-api.io/instances/{ZAPI_INSTANCE}/token/{ZAPI_TOKEN}/status"
        r = requests.get(url, headers={"Client-Token": ZAPI_CLIENT_TOKEN}, timeout=10)
        if r.status_code != 200:
            return False, {"error": f"HTTP {r.status_code}", "body": r.text[:200]}
        info = r.json()
        connected = bool(info.get("connected") and info.get("smartphoneConnected", True))
        return connected, info
    except Exception as e:
        return False, {"error": str(e)}

def _enviar_whatsapp_texto(destinatario, mensagem):
    """Envia mensagem de texto livre via Z-API. Retorna (ok, erro).
    Verifica conexao antes de enviar para evitar 'envio fantasma' (Z-API
    aceita /send-text desconectada e retorna 200 sem entregar a mensagem)."""
    try:
        if not ZAPI_INSTANCE or not ZAPI_TOKEN or not ZAPI_CLIENT_TOKEN:
            return False, "Z-API nao configurada"

        conectada, status_info = _zapi_conectada()
        if not conectada:
            err = status_info.get("error") or "instancia Z-API desconectada do WhatsApp"
            print(f"[ZAPI/intencao] DESCONECTADA: {status_info}")
            return False, (
                f"WhatsApp indisponivel (instancia Z-API desconectada). "
                f"Reconecte em https://app.z-api.io. Detalhe: {err}"
            )

        telefone = normalizar_telefone(destinatario)
        headers = {
            "Client-Token":  ZAPI_CLIENT_TOKEN,
            "Content-Type":  "application/json",
            "User-Agent":    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3",
        }
        print(f"[ZAPI/intencao] URL: {ZAPI_URL}")
        print(f"[ZAPI/intencao] Telefone: {telefone}")
        r = requests.post(ZAPI_URL, headers=headers,
                          json={"phone": telefone, "message": mensagem}, timeout=30)
        print(f"[ZAPI/intencao] Status: {r.status_code} | Resposta: {r.text[:300]}")
        if r.status_code not in (200, 201):
            return False, f"HTTP {r.status_code}: {r.text[:200]}"
        return True, ""
    except Exception as e:
        print(f"[ZAPI/intencao] Excecao: {e}")
        return False, str(e)

def _enviar_whatsapp_documento(destinatario, pdf_bytes, filename, caption=""):
    """Envia um PDF como documento via Z-API (send-document/pdf), em base64.
    Verifica a conexao antes (mesma logica de _enviar_whatsapp_texto).
    Retorna (ok, erro)."""
    try:
        if not ZAPI_INSTANCE or not ZAPI_TOKEN or not ZAPI_CLIENT_TOKEN:
            return False, "Z-API nao configurada"
        conectada, status_info = _zapi_conectada()
        if not conectada:
            err = status_info.get("error") or "instancia Z-API desconectada do WhatsApp"
            return False, (f"WhatsApp indisponivel (instancia Z-API desconectada). "
                           f"Reconecte em https://app.z-api.io. Detalhe: {err}")
        telefone = normalizar_telefone(destinatario)
        b64 = base64.b64encode(pdf_bytes).decode("ascii")
        url = (f"https://api.z-api.io/instances/{ZAPI_INSTANCE}/token/{ZAPI_TOKEN}"
               f"/send-document/pdf")
        headers = {
            "Client-Token":  ZAPI_CLIENT_TOKEN,
            "Content-Type":  "application/json",
            "User-Agent":    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3",
        }
        payload = {"phone": telefone, "document": f"data:application/pdf;base64,{b64}",
                   "fileName": filename}
        if caption:
            payload["caption"] = caption
        r = requests.post(url, headers=headers, json=payload, timeout=60)
        print(f"[ZAPI/doc] {telefone} status={r.status_code} resp={r.text[:200]}")
        if r.status_code not in (200, 201):
            return False, f"HTTP {r.status_code}: {r.text[:200]}"
        return True, ""
    except Exception as e:
        print(f"[ZAPI/doc] Excecao: {e}")
        return False, str(e)

def _pix_tlv(id_, value):
    return f"{id_}{len(value):02d}{value}"

def _pix_crc16(payload):
    crc = 0xFFFF
    for ch in payload.encode("utf-8"):
        crc ^= ch << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if (crc & 0x8000) else (crc << 1)
            crc &= 0xFFFF
    return f"{crc:04X}"

def _pix_brcode(chave, valor_reais, nome, cidade, txid="***", descricao=""):
    gui  = _pix_tlv("00", "BR.GOV.BCB.PIX")
    chv  = _pix_tlv("01", chave)
    mai_content = gui + chv
    if descricao:
        # ATENCAO: tag 26 inteira nao pode passar de 99 chars (limite de length 2-digit).
        # GUI(18) + chave PIX EVP/UUID(40) = 58 chars; sobra ~41 chars para descricao+TLV.
        # Trunca a descricao para max 37 chars de conteudo (+4 do TLV = 41).
        # Sem esse limite, bancos estritos (BB, Caixa) rejeitam com "Parametro Invalido".
        desc_safe = descricao[:37]
        mai_content += _pix_tlv("02", desc_safe)
    mai  = _pix_tlv("26", mai_content)
    adic = _pix_tlv("62", _pix_tlv("05", txid))
    payload = (
        _pix_tlv("00", "01")
      + _pix_tlv("01", "11")              # 11 = QR estatico (reutilizavel). "12" dinamico exige cobranca registrada no PSP — Asaas rejeita com "Pagamento rejeitado pelo PSP do recebedor".
      + mai
      + _pix_tlv("52", "0000")            # MCC
      + _pix_tlv("53", "986")             # BRL
      + _pix_tlv("54", f"{valor_reais:.2f}")
      + _pix_tlv("58", "BR")
      + _pix_tlv("59", nome[:25])
      + _pix_tlv("60", cidade[:15])
      + adic
      + "6304"
    )
    return payload + _pix_crc16(payload)

def _strip_acentos(s):
    """Remove acentos/cedilha e caracteres nao-ASCII (PIX nao aceita acento)."""
    import unicodedata
    return unicodedata.normalize("NFKD", s or "").encode("ASCII", "ignore").decode("ASCII")

def _data_limite_somar_meses(data_limite_atual, meses):
    """Soma N meses a uma data 'YYYY-MM' ou 'YYYY-MM-DD'. Retorna 'MM/YYYY'.
    Se data_limite_atual estiver vazia, soma a partir do mes corrente.
    """
    from datetime import datetime
    try:
        if data_limite_atual and len(data_limite_atual) >= 7:
            ano = int(data_limite_atual[:4])
            mes = int(data_limite_atual[5:7])
        else:
            agora = datetime.now()
            ano, mes = agora.year, agora.month
        total = mes + int(meses)
        novo_ano = ano + (total - 1) // 12
        novo_mes = ((total - 1) % 12) + 1
        return f"{novo_mes:02d}/{novo_ano:04d}"
    except Exception:
        return "??/????"

def _data_limite_iso_somar_meses(data_limite_atual, meses):
    """Igual a _data_limite_somar_meses, mas retorna 'YYYY-MM' (formato gravado
    em tab_cliente.data_limite). Usado pelo webhook do Asaas ao creditar a licenca."""
    from datetime import datetime
    try:
        if data_limite_atual and len(data_limite_atual) >= 7:
            ano = int(data_limite_atual[:4]); mes = int(data_limite_atual[5:7])
        else:
            agora = datetime.now(); ano, mes = agora.year, agora.month
        total = mes + int(meses)
        novo_ano = ano + (total - 1) // 12
        novo_mes = ((total - 1) % 12) + 1
        return f"{novo_ano:04d}-{novo_mes:02d}"
    except Exception:
        return data_limite_atual or ""

@app.route("/api/zapi_status")
def api_zapi_status():
    """Endpoint de diagnostico — abre no navegador para ver se Z-API esta conectada."""
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessao expirada"}), 401
    conectada, info = _zapi_conectada()
    return jsonify({"conectada": conectada, "info": info})

# =========================================================
# ASAAS — integracao para gerar cobrancas PIX dinamicas
# Diferente do BR Code estatico, a cobranca Asaas suporta descricao rica
# que aparece no app do banco do pagador, e dispara webhook ao ser paga.
# Docs: https://docs.asaas.com/reference
# =========================================================
def _asaas_request(method, path, json_body=None, params=None, timeout=20):
    """Wrapper para chamadas HTTP a API Asaas. Retorna (ok, status, data_or_error)."""
    if not ASAAS_API_KEY:
        return False, 0, {"error": "ASAAS_API_KEY nao configurada no .env"}
    url = f"{ASAAS_API_URL}{path}"
    headers = {
        "access_token": ASAAS_API_KEY,
        "Content-Type": "application/json",
        "User-Agent":   "Folha10-Simples/1.0",
    }
    try:
        r = requests.request(method, url, headers=headers, json=json_body, params=params, timeout=timeout)
        try:
            data = r.json()
        except Exception:
            data = {"raw": r.text[:500]}
        if r.status_code >= 400:
            return False, r.status_code, data
        return True, r.status_code, data
    except Exception as e:
        return False, 0, {"error": str(e)}

def _asaas_obter_ou_criar_customer(id_cliente, nome, cpf, email=None, celular=None):
    """Obtem ou cria customer Asaas idempotentemente via externalReference.
    Retorna (ok, customer_id, info)."""
    ext_ref = f"folha10_{id_cliente:06d}"
    # 1) Tenta achar customer existente pela externalReference
    ok, status, data = _asaas_request("GET", "/customers", params={"externalReference": ext_ref})
    if ok:
        lista = (data or {}).get("data") or []
        if lista:
            return True, lista[0].get("id"), {"reused": True}
    # 2) Cria novo
    cpf_num = re.sub(r"\D", "", cpf or "")
    payload = {
        "name":              (nome or "Cliente Folha10")[:100],
        "cpfCnpj":           cpf_num,
        "externalReference": ext_ref,
    }
    if email:
        payload["email"] = email
    if celular:
        payload["mobilePhone"] = re.sub(r"\D", "", celular)
    ok, status, data = _asaas_request("POST", "/customers", json_body=payload)
    if not ok:
        return False, None, {"erro": "Falha ao criar customer Asaas", "status": status, "detalhe": data}
    return True, (data or {}).get("id"), {"created": True}

def _asaas_criar_cobranca_pix(customer_id, valor, descricao, due_date, external_reference):
    """Cria cobranca PIX no Asaas. Retorna (ok, payment_id, info_or_error).
    due_date no formato 'YYYY-MM-DD' (validade do QR Code; Asaas exige)."""
    payload = {
        "customer":          customer_id,
        "billingType":       "PIX",
        "value":             round(float(valor), 2),
        "dueDate":           due_date,
        "description":       (descricao or "")[:500],
        "externalReference": external_reference,
    }
    ok, status, data = _asaas_request("POST", "/payments", json_body=payload)
    if not ok:
        return False, None, {"erro": "Falha ao criar cobranca PIX", "status": status, "detalhe": data}
    return True, (data or {}).get("id"), data

def _asaas_get_pix_qrcode(payment_id):
    """Retorna (ok, {encodedImage, payload, expirationDate} | error)."""
    ok, status, data = _asaas_request("GET", f"/payments/{payment_id}/pixQrCode")
    if not ok:
        return False, {"erro": "Falha ao obter QR Code Asaas", "status": status, "detalhe": data}
    return True, data

@app.route("/api/pix_qr", methods=["POST"])
def api_pix_qr():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessao expirada"}), 401
    try:
        import time
        from datetime import datetime
        data = request.get_json(silent=True) or {}
        valor = float(data.get("valor") or 0)
        if valor <= 0:
            return jsonify({"ok": False, "msg": "Valor invalido"}), 400

        empresas     = int(data.get("empresas")     or 0)
        funcionarios = int(data.get("funcionarios") or 0)
        meses        = int(data.get("meses")        or 1)
        id_cliente   = int(session.get("id_cliente") or 0)

        # Busca dados completos do cliente (precisamos de cpf, email, celular para criar customer Asaas)
        nome_cli = session.get("nome", "") or ""
        data_limite_atual = ""
        cpf_cli = ""
        email_cli = ""
        celular_cli = ""
        try:
            r = (supabase.table("tab_cliente")
                 .select("nome, data_limite, cpf, email, celular")
                 .eq("id_cliente", id_cliente)
                 .limit(1).execute())
            row = (r.data or [{}])[0]
            if not nome_cli:
                nome_cli = (row.get("nome") or "").strip()
            data_limite_atual = (row.get("data_limite") or "").strip()
            cpf_cli     = (row.get("cpf") or "").strip()
            email_cli   = (row.get("email") or "").strip()
            celular_cli = (row.get("celular") or "").strip()
        except Exception:
            pass

        nome_limpo = _strip_acentos(nome_cli).upper().strip()[:13]
        nova_dl    = _data_limite_somar_meses(data_limite_atual, meses)
        agora_str  = datetime.now().strftime("%d/%m/%Y %H:%M")
        valor_brl  = f"R$ {valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

        # Descricao rica que vai aparecer no app do banco do pagador e no painel do Asaas.
        # Com a cobranca dinamica (via API Asaas) nao temos os limites da tag 26 do BR Code.
        descricao_asaas = _strip_acentos(
            f"Licenca Folha10-Simples\n"
            f"Cliente: {id_cliente:06d} - {nome_cli}\n"
            f"Empresas: {empresas} | Funcionarios: {funcionarios}\n"
            f"Periodo: {meses} mes(es) - Nova data limite: {nova_dl}\n"
            f"Solicitado em: {agora_str}"
        )

        # externalReference: identifica a cobranca para webhook/reconciliacao
        ext_ref = f"lic_{id_cliente:06d}_{int(time.time())}_E{empresas}_F{funcionarios}_M{meses}"

        # 1) Obtem ou cria customer Asaas para esse cliente Folha10
        ok_cus, customer_id, info_cus = _asaas_obter_ou_criar_customer(
            id_cliente, nome_cli, cpf_cli, email=email_cli, celular=celular_cli
        )
        if not ok_cus:
            print(f"api_pix_qr: erro Asaas customer: {info_cus}")
            return jsonify({"ok": False, "msg": "Falha ao registrar cliente no Asaas. Tente novamente."}), 500

        # 2) Cria cobranca PIX com validade de 7 dias
        # Frontend valida valor minimo do Asaas (R$ 5,00). Backend confia no que
        # foi calculado; se chegar abaixo do minimo (ataque ou bug), Asaas rejeita.
        from datetime import date, timedelta as _td
        due_date = (date.today() + _td(days=7)).isoformat()
        ok_pay, payment_id, info_pay = _asaas_criar_cobranca_pix(
            customer_id, round(float(valor), 2), descricao_asaas, due_date, ext_ref
        )
        if not ok_pay:
            print(f"api_pix_qr: erro Asaas cobranca: {info_pay}")
            return jsonify({"ok": False, "msg": "Falha ao gerar cobranca PIX no Asaas. Tente novamente."}), 500

        # 3) Obtem QR Code da cobranca
        ok_qr, info_qr = _asaas_get_pix_qrcode(payment_id)
        if not ok_qr:
            print(f"api_pix_qr: erro Asaas QR: {info_qr}")
            return jsonify({"ok": False, "msg": "Falha ao gerar QR Code PIX. Tente novamente."}), 500

        png_b64    = info_qr.get("encodedImage", "")
        brcode     = info_qr.get("payload", "")
        expira_em  = info_qr.get("expirationDate", "")
        txid       = payment_id  # ID da cobranca Asaas vira nosso TXID de reconciliacao

        # Mensagem completa (vai no WhatsApp e na tela)
        notif_msg = (
            f"*INTENCAO DE COMPRA - Folha10-Simples*\n\n"
            f"*Cliente:* {id_cliente:06d} - {nome_limpo}\n"
            f"*Solicitado em:* {agora_str}\n"
            f"*Empresas:* {empresas}\n"
            f"*Funcionarios:* {funcionarios}\n"
            f"*Periodo:* {meses} mes(es)\n"
            f"*Nova Data Limite:* {nova_dl}\n"
            f"*Valor:* {valor_brl}\n"
            f"*Cobranca Asaas:* {payment_id}"
        )
        descricao_full = _strip_acentos(
            f"Licenca Folha10: Cliente {id_cliente:06d}-{nome_limpo}"
            f" em {agora_str} Empresas: {empresas}"
            f" Funcionarios: {funcionarios} Nova Data Limite {nova_dl}"
        )
        ok_wa, err_wa = _enviar_whatsapp_texto(PIX_WA_NOTIF_TEL, notif_msg)
        if not ok_wa:
            print(f"api_pix_qr: aviso - WhatsApp nao enviado para {PIX_WA_NOTIF_TEL}: {err_wa}")
            # Fallback: manda email para o suporte com o conteudo da intencao
            # (silencioso pro cliente — ele nao sabe que o WhatsApp falhou)
            try:
                fb_assunto = "ZAPI DESCONECTADO - Folha10-Simples"
                fb_corpo = (
                    "ZAPI DESCONECTADO\n\n"
                    f"O WhatsApp nao foi enviado para {PIX_WA_NOTIF_TEL}.\n"
                    f"Motivo: {err_wa}\n\n"
                    "--- Conteudo da intencao de compra (que seria enviada) ---\n\n"
                    + notif_msg
                )
                ok_em, err_em = _enviar_email_texto(
                    "sergiomoraesvieira@outlook.com", fb_assunto, fb_corpo
                )
                if not ok_em:
                    print(f"api_pix_qr: tambem falhou ao enviar email de fallback: {err_em}")
            except Exception as ex_fb:
                print(f"api_pix_qr: excecao no fallback de email: {ex_fb}")

        return jsonify({
            "ok":         True,
            "brcode":     brcode,
            "qr_png":     png_b64,
            "txid":       txid,
            "valor":      valor,
            "descricao":  descricao_full,
            "mensagem":   notif_msg,
            "wa_ok":      ok_wa,
            "expira_em":  expira_em,
            "payment_id": payment_id,
        })
    except Exception as e:
        print(f"api_pix_qr: {e}")
        return jsonify({"ok": False, "msg": str(e)}), 500

# =========================================================
# WEBHOOK ASAAS — credita a licenca quando o PIX e pago
# =========================================================
# Configurar no painel do Asaas:
#   URL:  https://folha10-simples.com.br/webhook/asaas
#   Auth: mesmo valor de ASAAS_WEBHOOK_TOKEN no .env (Asaas envia no header
#         'asaas-access-token' a cada notificacao).
@app.route("/webhook/asaas", methods=["POST"])
def webhook_asaas():
    """Recebe notificacoes do Asaas. Em PAYMENT_RECEIVED/CONFIRMED de uma cobranca
    de licenca (externalReference 'lic_NNNNNN_epoch_E#_F#_M#'), atualiza tab_cliente:
    data_limite (+meses), qtd_empresas e qtd_funcionarios.
    Idempotente por payment_id via marca em tab_log (menu='PAGAMENTO_ASAAS')."""
    import re
    from datetime import datetime

    # 0) DIAGNOSTICO SEGURO — nao expoe o segredo, so tamanho e fingerprint.
    #    Permite comparar remotamente se o ASAAS_WEBHOOK_TOKEN do Render bate
    #    com o esperado. Remover apos validar a integracao.
    _body0 = request.get_json(silent=True) or {}
    if (_body0.get("event") or "") == "DIAG_F10":
        import hashlib
        _t = ASAAS_WEBHOOK_TOKEN or ""
        _th = request.headers.get("asaas-access-token", "") or ""
        return jsonify({
            "ok": True,
            "token_set":     bool(_t),
            "token_len":     len(_t),
            "token_fp":      hashlib.sha256(_t.encode()).hexdigest()[:12] if _t else None,
            "header_len":    len(_th),
            "header_fp":     hashlib.sha256(_th.encode()).hexdigest()[:12] if _th else None,
            "match":         (_t != "" and _t == _th),
        }), 200

    # 1) Autenticacao — Asaas envia o token configurado no painel neste header
    token_recebido = request.headers.get("asaas-access-token", "")
    if not ASAAS_WEBHOOK_TOKEN or token_recebido != ASAAS_WEBHOOK_TOKEN:
        return jsonify({"ok": False, "msg": "unauthorized"}), 401

    body      = request.get_json(silent=True) or {}
    evento    = (body.get("event") or "").upper()
    pagamento = body.get("payment") or {}
    payment_id = str(pagamento.get("id") or "")
    ext_ref    = str(pagamento.get("externalReference") or "")

    # 2) So agimos quando o dinheiro entrou de fato
    if evento not in ("PAYMENT_RECEIVED", "PAYMENT_CONFIRMED"):
        return jsonify({"ok": True, "ignored": evento}), 200

    # 3) So cobrancas de licenca geradas por nos (padrao lic_NNNNNN_epoch_E#_F#_M#)
    m = re.match(r"^lic_(\d{6})_\d+_E(\d+)_F(\d+)_M(\d+)$", ext_ref)
    if not m:
        return jsonify({"ok": True, "ignored": "ext_ref"}), 200
    id_cliente   = int(m.group(1))
    empresas     = int(m.group(2))
    funcionarios = int(m.group(3))
    meses        = int(m.group(4))

    try:
        # 4) Idempotencia — se ja processamos esse payment_id, nao aplica de novo
        if payment_id:
            ja = (supabase.table("tab_log")
                  .select("id_cliente")
                  .eq("menu", "PAGAMENTO_ASAAS")
                  .ilike("observacao", f"%{payment_id}%")
                  .limit(1).execute())
            if ja.data:
                return jsonify({"ok": True, "duplicate": payment_id}), 200

        # 5) Le data_limite atual e calcula a nova (YYYY-MM, formato do banco)
        r = (supabase.table("tab_cliente")
             .select("data_limite, cpf, nome, email, celular")
             .eq("id_cliente", id_cliente).limit(1).execute())
        row = (r.data or [{}])[0]
        dl_atual    = (row.get("data_limite") or "").strip()
        nova_dl     = _data_limite_iso_somar_meses(dl_atual, meses)
        nome_cli    = (row.get("nome") or "").strip()
        email_cli   = (row.get("email") or "").strip()
        celular_cli = (row.get("celular") or "").strip()

        # 6) Update — so mexe em qtd se veio valor > 0 (evita zerar licenca)
        upd = {"data_limite": nova_dl}
        if empresas > 0:
            upd["qtd_empresas"] = empresas
        if funcionarios > 0:
            upd["qtd_funcionarios"] = funcionarios
        supabase.table("tab_cliente").update(upd).eq("id_cliente", id_cliente).execute()

        # 7) Marca de auditoria/idempotencia
        valor = pagamento.get("value")
        try:
            supabase.table("tab_log").insert({
                "id_cliente":      id_cliente,
                "id_empresa":      None,
                "cpf_usuario":     row.get("cpf") or "",
                "menu":            "PAGAMENTO_ASAAS",
                "observacao":      (f"Pagamento Asaas {payment_id} valor={valor} "
                                    f"E{empresas} F{funcionarios} M{meses} "
                                    f"nova_data_limite={nova_dl}")[:200],
                "ano_mes":         None,
                "data_hora_grava": datetime.now().strftime("%Y%m%d %H%M"),
            }).execute()
        except Exception as ex_log:
            print(f"webhook_asaas: falha ao gravar marca em tab_log: {ex_log}")

        # 8) Notificacoes (best-effort, nunca quebram a resposta 200)
        #    Nova data em formato amigavel MM/YYYY para o cliente.
        try:
            _p = (nova_dl or "").split("-")
            nova_dl_br = f"{_p[1]}/{_p[0]}" if len(_p) >= 2 else nova_dl
        except Exception:
            nova_dl_br = nova_dl
        valor = pagamento.get("value")

        # 8.1) WhatsApp para o CLIENTE (confirmacao amigavel)
        try:
            if celular_cli:
                msg_cli = (f"Ola{(' ' + nome_cli) if nome_cli else ''}! ✅\n\n"
                           f"Recebemos o pagamento da sua licenca do *Folha10-Simples*.\n\n"
                           f"*Validade atualizada ate:* {nova_dl_br}\n"
                           f"*Empresas:* {empresas} | *Funcionarios:* {funcionarios}\n\n"
                           f"Obrigado por usar o Folha10-Simples!")
                _enviar_whatsapp_texto(celular_cli, msg_cli)
        except Exception:
            pass

        # 8.2) WhatsApp para o admin (numero fixo de notificacao)
        try:
            msg_adm = (f"*PAGAMENTO CONFIRMADO - Folha10-Simples*\n\n"
                       f"*Cliente:* {id_cliente:06d}{(' - ' + nome_cli) if nome_cli else ''}\n"
                       f"*Empresas:* {empresas} | *Funcionarios:* {funcionarios}\n"
                       f"*Periodo:* {meses} mes(es)\n"
                       f"*Valor:* {valor}\n"
                       f"*Nova Data Limite:* {nova_dl_br}\n"
                       f"*Cobranca Asaas:* {payment_id}")
            _enviar_whatsapp_texto(PIX_WA_NOTIF_TEL, msg_adm)
        except Exception:
            pass

        # 8.3) E-mail para o admin
        try:
            corpo = (f"Pagamento confirmado no Folha10-Simples.\n\n"
                     f"Cliente: {id_cliente:06d}{(' - ' + nome_cli) if nome_cli else ''}\n"
                     f"Empresas: {empresas} | Funcionarios: {funcionarios}\n"
                     f"Periodo: {meses} mes(es)\n"
                     f"Valor: {valor}\n"
                     f"Nova Data Limite: {nova_dl_br}\n"
                     f"Cobranca Asaas: {payment_id}\n")
            ok_em, err_em = _enviar_email_texto("sergiomoraesvieira@outlook.com",
                                f"Pagamento confirmado - Cliente {id_cliente:06d}",
                                corpo)
            if not ok_em:
                print(f"webhook_asaas: email admin NAO enviado (cliente {id_cliente:06d}): {err_em}")
        except Exception as ex_em:
            print(f"webhook_asaas: excecao ao enviar email admin (cliente {id_cliente:06d}): {ex_em}")

        return jsonify({"ok": True, "cliente": id_cliente, "data_limite": nova_dl}), 200
    except Exception as e:
        # 500 faz o Asaas re-tentar; a marca em tab_log evita credito duplicado.
        print(f"webhook_asaas: erro ao processar {payment_id}: {e}")
        return jsonify({"ok": False, "msg": str(e)}), 500

