@app.route("/rel_lista_funcionarios")
def rel_lista_funcionarios():
    if not session.get("logado"):
        return redirect("/")
    id_empresa     = _get_id_empresa()
    classificacao  = _def_classificacao()  # A=Alfabética N=Numérica
    situacao_filtro = request.args.get("situacao", "A").strip()       # A=Ativos D=Desligados T=Todos

    order_col = "nome" if classificacao == "A" else "matricula"

    try:
        q = supabase.table("tab_cad").select("matricula, nome, nomer, situacao, dtadm") \
            .eq("id_empresa", id_empresa).order(order_col)
        if situacao_filtro != "T":
            q = q.eq("situacao", situacao_filtro)
        funcs = q.execute().data or []
    except Exception:
        funcs = []

    for f in funcs:
        # Nome completo (tab_cad.nome); cai no abreviado so se o completo faltar.
        f["nome_fmt"]  = (f.get("nome") or f.get("nomer") or "").strip()
        _adm = str(f.get("dtadm") or "").zfill(8)
        f["dtadm_fmt"] = _fmt_dt(_adm) if _adm != "00000000" else "—"

    return render_template(
        "F10_Rel_Lista_Funcionarios.html",
        **_ctx_relatorio(),
        funcs=funcs,
        classificacao=classificacao,
        situacao_filtro=situacao_filtro,
    )


@app.route("/rel_lista_funcionarios_pdf")
def rel_lista_funcionarios_pdf():
    if not session.get("logado"):
        return redirect("/")

    from io import BytesIO
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle

    id_empresa      = _get_id_empresa()
    classificacao   = _def_classificacao()
    situacao_filtro = request.args.get("situacao", "A").strip()

    order_col = "nome" if classificacao == "A" else "matricula"
    try:
        q = supabase.table("tab_cad").select("matricula, nome, nomer, situacao, dtadm") \
            .eq("id_empresa", id_empresa).order(order_col)
        if situacao_filtro != "T":
            q = q.eq("situacao", situacao_filtro)
        funcs = q.execute().data or []
    except Exception:
        funcs = []

    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))
    sit_label  = {"A": "Ativos", "D": "Desligados", "T": "Todos"}.get(situacao_filtro, "")
    ord_label  = "Ordem Alfabética" if classificacao == "A" else "Ordem Numérica"
    titulo     = f"Lista de Funcionários — {sit_label} · {ord_label}"

    def P(txt, fn="Helvetica", fs=8, align=0, col=colors.HexColor("#1f2937")):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, alignment=align,
                            textColor=col, leading=fs + 2)
        return Paragraph(str(txt), st)

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=2*cm, rightMargin=2*cm,
                            topMargin=1.5*cm, bottomMargin=1.5*cm)

    tbl_data = [[P("Matrícula", fn="Helvetica-Bold"),
                 P("Nome completo", fn="Helvetica-Bold"),
                 P("Admissão", fn="Helvetica-Bold", align=1)]]
    lt_gray  = colors.HexColor("#f8fafc")
    for f in funcs:
        mat_i = int(f.get("matricula") or 0)
        mat   = f"{mat_i:06d}"
        nome  = (f.get("nome") or f.get("nomer") or "").strip()
        _adm  = str(f.get("dtadm") or "").zfill(8)
        adm   = _fmt_dt(_adm) if _adm != "00000000" else "—"
        tbl_data.append([P(mat, fn="Courier"), P(nome),
                         P(adm, fn="Courier", align=1)])

    tbl = Table(tbl_data, colWidths=[2.6*cm, 11.0*cm, 3.4*cm], repeatRows=1)
    row_bg = []
    for i in range(1, len(tbl_data)):
        bg = lt_gray if i % 2 == 0 else colors.white
        row_bg.append(("BACKGROUND", (0, i), (-1, i), bg))

    tbl.setStyle(TableStyle([
        ("BACKGROUND",    (0, 0), (-1, 0), colors.HexColor("#eaf1fb")),
        ("LINEBELOW",     (0, 0), (-1, 0), 0.5, colors.HexColor("#dbe3ee")),
        ("LINEBELOW",     (0, 1), (-1, -1), 0.3, colors.HexColor("#f1f5f9")),
        ("TOPPADDING",    (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
        ("LEFTPADDING",   (0, 0), (-1, -1), 4),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 4),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
    ] + row_bg))

    total_linha = P(f"Total: {len(funcs)} funcionário(s)", fn="Helvetica", fs=8,
                    col=colors.HexColor("#64748b"), align=2)
    story = [_pdf_cabecalho(titulo, cnpj_fmt, empresa_nm, data_label="Emitido em"),
             Spacer(1, 8), tbl, Spacer(1, 6), total_linha]
    doc.build(story, onFirstPage=_pdf_num_pagina, onLaterPages=_pdf_num_pagina)
    buf.seek(0)

    from flask import make_response
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = 'inline; filename="ListaFuncionarios.pdf"'
    return resp


# ─────────────────────────────────────────────────────────────────────────────
# PDF helper — generic table PDF (retorna Flask response inline)
# ─────────────────────────────────────────────────────────────────────────────
def _pdf_tabela(titulo, headers, col_widths_cm, data_rows, empresa_nm, cnpj_fmt,
                subtitulo="", landscape=False, filename="relatorio.pdf", notas=""):
    from io import BytesIO
    from flask import make_response
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.pagesizes import A4, landscape as rl_landscape
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle

    def P(txt, fn="Helvetica", fs=7, align=0, col=colors.HexColor("#1f2937")):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, alignment=align,
                            textColor=col, leading=fs + 2)
        return Paragraph(str(txt), st)

    pagesize = rl_landscape(A4) if landscape else A4
    page_w   = pagesize[0] - 4*cm
    buf      = BytesIO()
    doc      = SimpleDocTemplate(buf, pagesize=pagesize,
                                 leftMargin=2*cm, rightMargin=2*cm,
                                 topMargin=1.5*cm, bottomMargin=1.5*cm)

    tbl_data = [[P(h, fn="Helvetica-Bold") for h in headers]]
    lt_gray  = colors.HexColor("#f8fafc")
    for row in data_rows:
        tbl_data.append([P(str(c) if c is not None else "—") for c in row])

    tbl    = Table(tbl_data, colWidths=[w*cm for w in col_widths_cm], repeatRows=1)
    row_bg = [("BACKGROUND", (0, i), (-1, i), lt_gray if i % 2 == 0 else colors.white)
              for i in range(1, len(tbl_data))]
    tbl.setStyle(TableStyle([
        ("BACKGROUND",    (0, 0), (-1, 0), colors.HexColor("#eaf1fb")),
        ("LINEBELOW",     (0, 0), (-1, 0), 0.5, colors.HexColor("#dbe3ee")),
        ("LINEBELOW",     (0, 1), (-1, -1), 0.3, colors.HexColor("#f1f5f9")),
        ("TOPPADDING",    (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
        ("LEFTPADDING",   (0, 0), (-1, -1), 4),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 4),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
    ] + row_bg))

    rodape = P(f"Total: {len(data_rows)} registro(s)", fn="Helvetica", fs=7,
               col=colors.HexColor("#64748b"), align=2)
    story  = [_pdf_cabecalho(titulo, cnpj_fmt, empresa_nm, page_width=page_w)]
    if subtitulo:
        story += [Spacer(1, 4), P(subtitulo, fn="Helvetica", fs=8, col=colors.HexColor("#64748b"))]
    story += [Spacer(1, 8), tbl, Spacer(1, 6), rodape]
    if notas:
        story += [Spacer(1, 4), P(notas, fn="Helvetica", fs=7,
                                  col=colors.HexColor("#64748b"))]
    doc.build(story, onFirstPage=_pdf_num_pagina, onLaterPages=_pdf_num_pagina)
    buf.seek(0)

    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{filename}"'
    return resp


