@app.route("/rel_mov_pdf")
def rel_mov_pdf():
    if not session.get("logado"):
        return redirect("/")

    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes_sess = str(session.get("anomes_atual") or "")
    mats_str    = request.args.get("mats",        "").strip()
    competencia = request.args.get("competencia", "").strip()
    cod_verba_s = request.args.get("cod_verba",   "").strip()

    if competencia and len(competencia) == 7:
        folha_int     = int(competencia.replace("-", ""))
        periodo_label = f"{competencia[5:7]}/{competencia[:4]}"
    elif anomes_sess:
        folha_int     = int(anomes_sess)
        periodo_label = f"{anomes_sess[4:6]}/{anomes_sess[:4]}"
    else:
        folha_int     = 0
        periodo_label = ""

    mats_filtro      = [int(m) for m in mats_str.split(",") if m.strip().isdigit()] if mats_str else []
    cod_verba_filtro = int(cod_verba_s) if cod_verba_s.isdigit() else None

    if not folha_int:
        from flask import make_response as _mr
        r = _mr("Nenhuma competência definida."); r.headers["Content-Type"] = "text/plain"
        return r, 400

    try:
        q = supabase.table("tab_mov") \
            .select("matricula, cod_verba, qtd, valor, folha_tipo, folha") \
            .eq("id_empresa", id_empresa).eq("id_cliente", id_cliente) \
            .eq("situacao", "A").eq("folha", folha_int)
        if mats_filtro:
            q = q.in_("matricula", mats_filtro)
        if cod_verba_filtro:
            q = q.eq("cod_verba", cod_verba_filtro)
        registros_raw = q.order("matricula").order("cod_verba").execute().data or []
    except Exception:
        registros_raw = []

    nomes_map  = {}
    verbas_map = {}
    try:
        all_mats = list({r["matricula"] for r in registros_raw if r.get("matricula")})
        if all_mats:
            r_cad = supabase.table("tab_cad").select("matricula, nome, nomer") \
                .eq("id_empresa", id_empresa).in_("matricula", all_mats).execute()
            for f in (r_cad.data or []):
                nomes_map[f["matricula"]] = (f.get("nomer") or f.get("nome") or "").strip()
    except Exception:
        pass
    try:
        all_cods = list({r["cod_verba"] for r in registros_raw if r.get("cod_verba") is not None})
        if all_cods:
            r_v = supabase.table("tab_rubrica") \
                .select("cod_rubr, dsc_rubr, unid_verba, tp_rubr, id_cliente") \
                .in_("id_cliente", [0, id_cliente]).in_("cod_rubr", all_cods).execute()
            for v in (r_v.data or []):
                cod = v.get("cod_rubr")
                if cod not in verbas_map or v.get("id_cliente") != 0:
                    verbas_map[cod] = {"dsc_rubr":   v.get("dsc_rubr")   or "",
                                       "unid_verba": v.get("unid_verba") or "V",
                                       "tp_rubr":    v.get("tp_rubr")    or "1"}
    except Exception:
        pass

    def fmt_brl(c):
        return f"{c / 100:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    TIPO_LABEL = {"N": "Normal", "F": "Férias", "R": "Rescisão"}
    rows = []
    for reg in registros_raw:
        mat  = reg.get("matricula")
        cod  = reg.get("cod_verba")
        vi   = verbas_map.get(cod, {"dsc_rubr": "", "unid_verba": "V", "tp_rubr": "1"})
        unid = vi["unid_verba"]
        qtd_raw   = reg.get("qtd")   or 0
        valor_raw = reg.get("valor") or 0
        ft        = reg.get("folha_tipo", "N")
        fraw      = str(reg.get("folha") or folha_int)
        folha_fmt = f"{fraw[4:6]}/{fraw[:4]}" if len(fraw) == 6 else fraw
        if unid == "H":
            h, m = qtd_raw // 60, qtd_raw % 60
            entrada = f"{h:02d}:{m:02d}"
        elif unid == "D":
            entrada = str(qtd_raw)
        else:
            entrada = fmt_brl(valor_raw)
        rows.append([f"{int(mat or 0):06d}", nomes_map.get(mat, "—"),
                     f"{int(cod or 0):04d}", vi["dsc_rubr"], unid,
                     TIPO_LABEL.get(ft, ft), entrada, folha_fmt])

    return _pdf_tabela("Movimento Mensal",
                       ["Mat.", "Funcionário", "Cód.", "Descrição", "Unid.",
                        "Tipo", "Valor/Qtd.", "Folha"],
                       [2.0, 6.0, 1.5, 7.0, 1.5, 2.0, 2.5, 3.2], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       subtitulo=periodo_label, landscape=True, filename="Movimento.pdf")


@app.route("/rel_log_pdf")
def rel_log_pdf():
    if not session.get("logado"):
        return redirect("/")

    from datetime import datetime as _dtt

    id_cliente  = session.get("id_cliente")
    f_matricula = request.args.get("matricula",   "").strip()
    f_ano_mes   = request.args.get("ano_mes",     "").strip()
    f_dt_inicio = request.args.get("dt_inicio",   "").strip()
    f_dt_fim    = request.args.get("dt_fim",      "").strip()
    f_cpf       = request.args.get("cpf_usuario", "").strip()
    f_menu      = request.args.get("menu",        "").strip()

    registros = []
    try:
        q = supabase.table("tab_log").select("*").eq("id_cliente", id_cliente)
        # Logs de impersonação (admin entrando no cliente) só o admin pode ver.
        if not _pode_impersonar():
            q = q.neq("menu", "IMPERSONAR").neq("menu", "IMPERSONAR-FIM")
        if f_matricula:
            q = q.eq("matricula", int(f_matricula))
        if f_ano_mes:
            q = q.eq("ano_mes", int(f_ano_mes.replace("-", "")))
        if f_cpf:
            q = q.eq("cpf_usuario", so_numeros(f_cpf))
        if f_menu:
            q = q.ilike("menu", f"%{f_menu}%")
        if f_dt_inicio:
            q = q.gte("data_hora_grava", f_dt_inicio.replace("-", "") + " 0000")
        if f_dt_fim:
            q = q.lte("data_hora_grava", f_dt_fim.replace("-", "") + " 2359")
        registros = q.order("data_hora_grava", desc=True).limit(500).execute().data or []
    except Exception:
        pass

    def _fdt(v):
        if not v:
            return "—"
        try:
            return _dtt.strptime(str(v).replace(" ", ""), "%Y%m%d%H%M").strftime("%d/%m/%Y %H:%M")
        except Exception:
            return str(v)

    def _fam(v):
        s = str(v or "").replace("-", "")
        return f"{s[4:6]}/{s[0:4]}" if len(s) == 6 else (s or "—")

    def _fcpf(v):
        d = so_numeros(str(v or ""))
        return f"{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}" if len(d) == 11 else (v or "—")

    rows = []
    for reg in registros:
        mat = str(reg.get("matricula") or "").zfill(6) if reg.get("matricula") else "—"
        # Sem corte: a celula do PDF e um Paragraph, que quebra linha sozinho.
        rows.append([_fdt(reg.get("data_hora_grava")), reg.get("menu") or "—",
                     mat, _fam(reg.get("ano_mes")), _fcpf(reg.get("cpf_usuario")),
                     (reg.get("observacao") or "")])

    return _pdf_tabela("Log de Operações",
                       ["Data/Hora", "Módulo", "Mat.", "Mês/Ano", "CPF", "Operação"],
                       [3.5, 3.5, 2.0, 1.8, 3.2, 11.7], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       landscape=True, filename="Log.pdf")


@app.route("/rel_esocial_remessas_pdf")
def rel_esocial_remessas_pdf():
    if not session.get("logado"):
        return redirect("/")

    id_empresa    = _get_id_empresa()
    f_ano_mes     = request.args.get("ano_mes",     "").strip()
    f_matricula   = request.args.get("matricula",   "").strip()
    f_layout      = request.args.get("layout",      "").strip()
    f_dt_cad_de   = request.args.get("dt_cad_de",  "").strip()
    f_dt_cad_ate  = request.args.get("dt_cad_ate", "").strip()
    f_remessa_de  = request.args.get("remessa_de",  "").strip()
    f_remessa_ate = request.args.get("remessa_ate", "").strip()
    f_sit_1       = request.args.get("sit_1", "")
    f_sit_2       = request.args.get("sit_2", "")
    f_sit_3       = request.args.get("sit_3", "")

    _LAYOUTS = {
        "2200": "S-2200 Admissão",   "2205": "S-2205 Alt.Cad.",
        "2206": "S-2206 Alt.Cont.",  "2230": "S-2230 Afastam.",
        "2299": "S-2299 Desligam.",  "1200": "S-1200 Remun.",
        "1210": "S-1210 Pagam.",
    }

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"

    data = []
    try:
        q = supabase.table("tab_esocial").select("*").eq("id_empresa", id_empresa)
        if f_ano_mes:
            try:    q = q.eq("ano_mes", int(f_ano_mes))
            except ValueError: pass
        if f_matricula:
            try:    q = q.eq("matricula", int(f_matricula))
            except ValueError: pass
        if f_layout:
            q = q.eq("layout", f_layout)
        if f_dt_cad_de:
            q = q.gte("data_cad", f_dt_cad_de.replace("-", ""))
        if f_dt_cad_ate:
            q = q.lte("data_cad", f_dt_cad_ate.replace("-", ""))
        if f_remessa_de:
            q = q.gte("data_grava", f_remessa_de.replace("-", ""))
        if f_remessa_ate:
            q = q.lte("data_grava", f_remessa_ate.replace("-", ""))
        raw = q.order("data_cad", desc=True).order("hora_cad", desc=True).execute().data or []
        for r in raw:
            recibo = (r.get("recibo")          or "").strip()
            obs    = (r.get("observacao_erro") or "").strip()
            dgrava = (r.get("data_grava")      or "").strip()
            r["_sit"] = "1" if (not dgrava and not recibo) else ("3" if obs else "2")
        sits = {s for s, f in [("1", f_sit_1), ("2", f_sit_2), ("3", f_sit_3)] if f}
        data = [r for r in raw if not sits or r["_sit"] in sits]
    except Exception:
        pass

    SIT_LABEL = {"1": "Pendente", "2": "Remetido", "3": "Com Erro"}
    rows = []
    for r in data:
        am     = str(r.get("ano_mes")    or "")
        lay    = str(r.get("layout")     or "").strip()
        tp     = str(r.get("folha_tipo") or "").strip()
        mat    = r.get("matricula")
        recibo = (r.get("recibo") or "").strip()
        rows.append([
            _d8(r.get("data_cad")),
            str(mat or "").zfill(6) if mat else "—",
            _LAYOUTS.get(lay, f"S-{lay}" if lay else "—"),
            "13° Sal." if tp == "1" else "Normal",
            SIT_LABEL.get(r["_sit"], r["_sit"]),
            _d8(r.get("data_grava")),
            (recibo[:25] + "…") if len(recibo) > 25 else (recibo or "—"),
        ])

    def _fmt_data(v):
        s = str(v or "").replace("-", "")
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else v

    partes = []
    if f_matricula:
        partes.append(f"Matrícula: {f_matricula.zfill(6)}")
    if len(f_ano_mes) == 6:
        partes.append(f"Folha: {f_ano_mes[4:6]}/{f_ano_mes[:4]}")
    if f_layout:
        partes.append(f"Layout: {_LAYOUTS.get(f_layout, 'S-' + f_layout)}")
    sits_ativas = [n for n, f in [("Pendente", f_sit_1), ("Remetido", f_sit_2), ("Com Erro", f_sit_3)] if f]
    if sits_ativas and len(sits_ativas) < 3:
        partes.append("Situação: " + ", ".join(sits_ativas))
    if f_dt_cad_de or f_dt_cad_ate:
        partes.append(f"Dt. Cadastro: {_fmt_data(f_dt_cad_de) or '—'} a {_fmt_data(f_dt_cad_ate) or '—'}")
    if f_remessa_de or f_remessa_ate:
        partes.append(f"Dt. Remessa: {_fmt_data(f_remessa_de) or '—'} a {_fmt_data(f_remessa_ate) or '—'}")
    notas_filtros = ("Filtros: " + "  |  ".join(partes)) if partes else ""

    return _pdf_tabela("Remessas eSocial",
                       ["Dt. Cad.", "Mat.", "Layout", "Folha", "Situação",
                        "Dt. Remessa", "Recibo"],
                       [2.5, 2.0, 4.5, 2.0, 2.5, 2.5, 9.7], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       landscape=True, filename="RemessaseSocial.pdf",
                       notas=notas_filtros)


@app.route("/rel_sal_aumento_pdf")
def rel_sal_aumento_pdf():
    if not session.get("logado"):
        return redirect("/")

    id_empresa       = _get_id_empresa()
    classificacao    = _def_classificacao()
    apenas_alterados = request.args.get("apenas_alterados", "").upper() == "S"
    motivo_filtro    = request.args.get("motivo", "").strip()
    anomes_rel       = str(session.get("anomes_atual") or "")

    MOTIVO_LABEL = {"1": "Dissídio", "2": "Espontâneo", "3": "Promoção", "4": "Salário Mínimo", "9": "Outros Motivos"}

    def _fsal(c):
        if c is None:
            return "—"
        return "R$ " + f"{c/100:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _fdata(v):
        s = str(v or "")
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"

    eventos = {}
    mats_com_aumento = None
    if apenas_alterados and len(anomes_rel) == 6:
        try:
            ev_q = supabase.table("tab_eventos") \
                .select("matricula, ref1, ref2, campotxt1, campotxt2") \
                .eq("id_empresa", id_empresa).eq("op1", 5).eq("folha", int(anomes_rel))
            if motivo_filtro:
                ev_q = ev_q.eq("campotxt2", motivo_filtro)
            for ev in (ev_q.execute().data or []):
                eventos[ev["matricula"]] = ev
            mats_com_aumento = list(eventos.keys())
        except Exception:
            mats_com_aumento = []

    order_map = {"N": "matricula", "D": "dtadm", "A": "nome", "S": "nome"}
    order_col  = order_map.get(classificacao, "nome")

    registros = []
    try:
        q = supabase.table("tab_cad").select("matricula, nome, dtadm, vrsalfx") \
            .eq("id_empresa", id_empresa).eq("situacao", "A").order(order_col)
        if mats_com_aumento is not None:
            funcs = (q.in_("matricula", mats_com_aumento).execute().data or []) \
                    if mats_com_aumento else []
        else:
            funcs = q.execute().data or []

        for f in funcs:
            mat   = f.get("matricula")
            sal_at = f.get("vrsalfx") or 0
            ev    = eventos.get(mat)
            sal_ant = ev.get("ref1") if ev else None
            sal_nov = ev.get("ref2") if ev else None
            perc_txt = ev.get("campotxt1", "") if ev else ""
            mot_txt  = MOTIVO_LABEL.get(ev.get("campotxt2", ""), "") if ev else ""
            registros.append({
                "mat_fmt":       str(mat).zfill(6),
                "nome":          f.get("nome", ""),
                "dtadm_fmt":     _fdata(f.get("dtadm")),
                "sal_atual_fmt": _fsal(sal_at),
                "sal_ant_fmt":   _fsal(sal_ant) if sal_ant is not None else "—",
                "sal_nov_fmt":   _fsal(sal_nov)  if sal_nov  is not None else "—",
                "diff_fmt":      _fsal(sal_nov - sal_ant)
                                 if (sal_ant is not None and sal_nov is not None) else "—",
                "perc_txt":      perc_txt,
                "motivo":        mot_txt,
            })
    except Exception:
        pass

    rows = [[r["mat_fmt"], r["nome"], r["dtadm_fmt"], r["sal_ant_fmt"],
             r["sal_nov_fmt"], r["diff_fmt"], r["perc_txt"], r["motivo"]]
            for r in registros]

    anomes_fmt   = f"{anomes_rel[4:6]}/{anomes_rel[:4]}" if len(anomes_rel) == 6 else ""
    motivo_label = MOTIVO_LABEL.get(motivo_filtro, "") if motivo_filtro else ""
    sub_parts    = [s for s in [anomes_fmt, motivo_label] if s]
    if apenas_alterados:
        sub_parts.append("Apenas com aumento")

    return _pdf_tabela("Relatório de Salários — Aumentos",
                       ["Mat.", "Funcionário", "Dt. Adm.", "Sal. Anterior",
                        "Sal. Novo", "Diferença", "%", "Motivo"],
                       [2.0, 6.5, 2.5, 3.0, 3.0, 3.0, 2.0, 3.2], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       subtitulo=" · ".join(sub_parts),
                       landscape=True, filename="Salarios_Aumentos.pdf")


@app.route("/rel_aumento_pdf")
def rel_aumento_pdf():
    if not session.get("logado"):
        return redirect("/")

    import calendar as _cal

    id_empresa   = _get_id_empresa()
    vigencia_raw = request.args.get("vigencia", "").strip()
    percentual   = float(request.args.get("percentual", "0") or 0)
    tipo         = int(request.args.get("tipo", "1") or 1)
    motivo_raw   = request.args.get("motivo", "1").strip()
    vr_inf       = int(request.args.get("vr_inferior", "0") or 0)
    vr_sup       = int(request.args.get("vr_superior", "9999999999") or 9999999999)
    mats_raw     = request.args.get("mats", "").strip()
    mats_lista   = [int(m) for m in mats_raw.split(",") if m.strip().isdigit()] if mats_raw else []

    if len(vigencia_raw) != 6 or not vigencia_raw.isdigit():
        vigencia_raw = str(session.get("anomes_atual") or "")
    if len(vigencia_raw) != 6:
        from flask import make_response as _mr
        r = _mr("Vigência inválida."); r.headers["Content-Type"] = "text/plain"
        return r, 400

    vig_year  = int(vigencia_raw[:4])
    vig_month = int(vigencia_raw[4:6])

    MOTIVO_LABEL = {"1": "Dissídio", "2": "Espontâneo", "3": "Promoção", "4": "Salário Mínimo", "9": "Outros Motivos"}

    def _fsal(c):
        if c is None:
            return "—"
        return f"{c/100:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _fdata(v):
        s = str(v or "")
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"

    def _calcular(vrsalfx, dtadm_int):
        if tipo == 1:
            prop  = 1.0
            meses = 12
        else:
            try:
                s         = str(dtadm_int).zfill(8)
                adm_year  = int(s[0:4])
                adm_month = int(s[4:6])
                adm_day   = int(s[6:8])
            except Exception:
                return vrsalfx + round(vrsalfx * percentual / 100), 1.0, 12, percentual
            diff = (vig_year - adm_year) * 12 + (vig_month - adm_month)
            if diff >= 12:
                prop  = 1.0
                meses = 12
            else:
                days_in_adm = _cal.monthrange(adm_year, adm_month)[1]
                days_rem    = days_in_adm - adm_day + 1
                if tipo == 4:
                    count_adm = 0
                elif tipo == 2:
                    count_adm = 1
                else:
                    count_adm = 1 if days_rem > 15 else 0
                meses = max(0, min(12, diff + count_adm))
                prop  = meses / 12
        perc_ap = percentual * prop
        novo    = vrsalfx + round(vrsalfx * perc_ap / 100)
        return novo, prop, meses, perc_ap

    registros = []
    try:
        q = supabase.table("tab_cad").select("matricula, nome, dtadm, vrsalfx") \
            .eq("id_empresa", id_empresa).eq("situacao", "A").order("nome")
        if mats_lista:
            q = q.in_("matricula", mats_lista)
        funcs = [f for f in (q.execute().data or [])
                 if vr_inf <= (f.get("vrsalfx") or 0) <= vr_sup]
    except Exception:
        funcs = []

    for f in funcs:
        mat   = f.get("matricula")
        sal_at = f.get("vrsalfx") or 0
        sal_novo, prop, meses, perc_ap = _calcular(sal_at, f.get("dtadm"))
        registros.append({
            "mat":          mat,
            "nome":         f.get("nome", ""),
            "dtadm_fmt":    _fdata(f.get("dtadm")),
            "meses":        meses,
            "prop_fmt":     f"{prop*100:.0f}",
            "sal_atual_fmt":_fsal(sal_at),
            "perc_ap_fmt":  f"{perc_ap:.2f}".replace(".", ","),
            "sal_novo_fmt": _fsal(sal_novo),
            "diff_fmt":     _fsal(sal_novo - sal_at),
        })

    rows = [[f"{int(r['mat'] or 0):06d}", r["nome"], r["dtadm_fmt"],
             r["meses"], r["prop_fmt"] + "%", r["sal_atual_fmt"],
             r["perc_ap_fmt"] + "%", r["sal_novo_fmt"], r["diff_fmt"]]
            for r in registros]

    vig_fmt = f"{vigencia_raw[4:6]}/{vigencia_raw[:4]}"
    sub     = (f"Vigência: {vig_fmt} · {percentual:.2f}% · "
               f"{MOTIVO_LABEL.get(motivo_raw, motivo_raw)}")
    return _pdf_tabela("Simulação/Alteração de Salário",
                       ["Mat.", "Funcionário", "Dt.Adm.", "Meses", "Prop.",
                        "Sal.Atual", "% Apl.", "Sal.Novo", "Diferença"],
                       [2.0, 5.5, 2.5, 1.5, 1.5, 3.0, 1.7, 3.0, 3.0], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       subtitulo=sub, landscape=True, filename="Aumento_Salario.pdf")


@app.route("/rel_mov_fixo_pdf")
def rel_mov_fixo_pdf():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    try:
        mat_filtro   = int(request.args.get("matricula",  "0") or 0)
        verba_filtro = int(request.args.get("cod_verba",  "0") or 0)
    except (ValueError, TypeError):
        mat_filtro = verba_filtro = 0

    # Nomes de funcionários
    nomes_map = {}
    try:
        r_cad = supabase.table("tab_cad").select("matricula, nome, nomer, codcateg, dtnascto, dtadm, vrsalfx") \
            .eq("id_empresa", id_empresa).eq("id_cliente", id_cliente).execute()
        for f in (r_cad.data or []):
            nomes_map[f["matricula"]] = {
                "nome": (f.get("nomer") or f.get("nome") or "").strip(),
                "raw":  f,
            }
    except Exception:
        pass

    # Nomes de verbas
    verbas_map = {}
    try:
        r_v = supabase.table("tab_rubrica") \
            .select("cod_rubr, dsc_rubr, tp_rubr, unid_verba, id_cliente, is_nao_digitar") \
            .in_("id_cliente", [0, id_cliente]).eq("situacao", "A").execute()
        vm = {}
        for v in (r_v.data or []):
            if v.get("is_nao_digitar"):
                continue
            cod = v.get("cod_rubr")
            if cod not in vm or v.get("id_cliente") != 0:
                vm[cod] = v.get("dsc_rubr") or ""
        verbas_map = vm
    except Exception:
        pass

    regs = []
    try:
        q = supabase.table("tab_mov_fixo").select("*") \
            .eq("id_empresa", id_empresa).eq("id_cliente", id_cliente) \
            .eq("situacao", "A").order("id")
        if verba_filtro:
            q = q.eq("cod_verba", verba_filtro)
        regs = q.execute().data or []

        if mat_filtro:
            func_data = nomes_map.get(mat_filtro, {}).get("raw")
            resultado = []
            for reg in regs:
                if reg.get("matricula") == mat_filtro:
                    resultado.append(reg)
                elif reg.get("matricula") is None:
                    enquadra, incerto = _avaliar_enquadramento(func_data, reg) \
                        if func_data else (False, True)
                    if enquadra or incerto:
                        resultado.append(reg)
            regs = resultado
    except Exception:
        pass

    def _vig(r):
        if r.get("qtd_parcelas"):
            restam = (r.get("qtd_parcelas") or 0) - (r.get("qtd_parcelas_before") or 0)
            return f"{restam}/{r['qtd_parcelas']} parc."
        fi = r.get("folha_inicial") or 0
        ff = r.get("folha_final")   or 0
        def _fmt(v):
            if not v:
                return "?"
            if v == 999912:
                return "Indef."
            return f"{v % 100:02d}/{v // 100}"
        return f"{_fmt(fi)} → {_fmt(ff)}"

    def _fval(c):
        return f"{c / 100:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".") if c else "—"

    rows = []
    for r in regs:
        mat = r.get("matricula")
        if mat:
            alvo = f"{int(mat):06d} {nomes_map.get(mat, {}).get('nome', '')}"
        else:
            partes = []
            if r.get("id_sindicato"): partes.append(f"Sind.{r['id_sindicato']}")
            if r.get("id_funcao"):    partes.append(f"Func.{r['id_funcao']}")
            if r.get("categoria"):    partes.append(f"Cat.{r['categoria']}")
            alvo = "Grupo" + (": " + " · ".join(partes) if partes else "")
        regras = (f"Fér:{r.get('nas_ferias','?')} Afs:{r.get('se_afastado','?')} "
                  f"Adm:{r.get('mes_admissao','?')} Rsc:{r.get('mes_rescisao','?')}")
        rows.append([
            alvo,
            f"{int(r.get('cod_verba') or 0):04d} {verbas_map.get(r.get('cod_verba'), '')}",
            _fval(r.get("valor")),
            _vig(r),
            regras,
        ])

    sub_parts = []
    if mat_filtro:
        sub_parts.append(f"Funcionário: {int(mat_filtro):06d} {nomes_map.get(mat_filtro, {}).get('nome', '')}")
    if verba_filtro:
        sub_parts.append(f"Verba: {int(verba_filtro):04d}")

    return _pdf_tabela("Relatório de Movimentos Fixos",
                       ["Funcionário / Grupo", "Verba", "Valor", "Vigência", "Regras"],
                       [7.0, 7.0, 2.5, 4.5, 4.7], rows,
                       str(session.get("empresa_info") or ""),
                       _fmt_cnpj(session.get("cnpj_empresa", "")),
                       subtitulo=" · ".join(sub_parts),
                       landscape=True, filename="MovimentosFixos.pdf")


@app.route("/rel_ficha_financeira")
def rel_ficha_financeira():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    ano_atual  = datetime.now().year
    MESES      = ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"]

    def ff_fmt(centavos):
        if not centavos:
            return "—"
        v = centavos / 100
        return f"{v:,.2f}".replace(",","X").replace(".",",").replace("X",".")

    mat_raw = request.args.get("mat", "").strip()
    try:
        ano = int(request.args.get("ano", ano_atual))
    except ValueError:
        ano = ano_atual

    anos_disponiveis = list(range(ano_atual, ano_atual - 6, -1))
    func      = None
    verbas    = []
    _z = {"prov_fmt":"—","desc_fmt":"—","liq_fmt":"—",
          "inss_sem_fmt":"—","inss_com_fmt":"—",
          "irrf_total_fmt":"—","irrf_tabela_fmt":"—",
          "fgts_base_fmt":"—","fgts_val_fmt":"—"}
    totais     = [dict(_z) for _ in range(12)]
    tot_anual  = dict(_z)
    tot_adiant = dict(_z)
    tot_decimo = dict(_z)
    erro       = None

    if mat_raw.isdigit():
        mat_int = int(mat_raw)

        try:
            r = supabase.table("tab_cad") \
                .select("matricula, nome, nomer, situacao, dtadm") \
                .eq("id_empresa", id_empresa) \
                .eq("matricula", mat_int) \
                .limit(1).execute()
            if r.data:
                row = r.data[0]
                row["nome_fmt"] = (row.get("nomer") or row.get("nome") or "").strip()
                func = row
            else:
                erro = "Funcionário não encontrado."
        except Exception:
            erro = "Erro ao buscar funcionário."

        if func:
            anomes_ini = int(f"{ano}01")
            anomes_fim = int(f"{ano}12")

            try:
                q = supabase.table("tab_mov") \
                    .select("cod_verba, valor, folha, folha_tipo") \
                    .eq("id_empresa", id_empresa) \
                    .eq("matricula", mat_int) \
                    .eq("situacao", "A") \
                    .gte("folha", anomes_ini) \
                    .lte("folha", anomes_fim)
                if id_cliente:
                    q = q.eq("id_cliente", id_cliente)
                mov_data = q.execute().data or []
            except Exception:
                mov_data = []

            # agregar mov separado por folha_tipo: N=mensal, A=adiantamento, 1=13º
            agg_n = {}  # Normal: por cod_verba → [12 meses]
            agg_a = {}  # Adiantamento 13º: por cod_verba → total
            agg_1 = {}  # 13º Salário: por cod_verba → total
            for m in mov_data:
                cod = int(m.get("cod_verba") or 0)
                if not cod:
                    continue
                ft  = str(m.get("folha_tipo") or "N")
                val = int(m.get("valor") or 0)
                if ft == "A":
                    agg_a[cod] = agg_a.get(cod, 0) + val
                elif ft == "1":
                    agg_1[cod] = agg_1.get(cod, 0) + val
                else:
                    mes = int(m.get("folha") or 0) % 100
                    if 1 <= mes <= 12:
                        if cod not in agg_n:
                            agg_n[cod] = [0] * 12
                        agg_n[cod][mes - 1] += val

            # descrições das verbas (union dos três buckets)
            all_cods = set(agg_n) | set(agg_a) | set(agg_1)
            rubrica_info = {}
            if all_cods:
                try:
                    cli_ids = [0] + ([id_cliente] if id_cliente else [])
                    r_rub = supabase.table("tab_rubrica") \
                        .select("cod_rubr, dsc_rubr, tp_rubr, id_cliente") \
                        .in_("id_cliente", cli_ids) \
                        .in_("cod_rubr", list(all_cods)) \
                        .eq("situacao", "A") \
                        .execute()
                    for row in (r_rub.data or []):
                        cod = int(row.get("cod_rubr") or 0)
                        if cod not in rubrica_info or int(row.get("id_cliente") or 0) != 0:
                            rubrica_info[cod] = {
                                "dsc": row.get("dsc_rubr") or f"Verba {cod}",
                                "tp":  str(row.get("tp_rubr") or "1"),
                            }
                except Exception:
                    pass

            prov, desc = [], []
            for cod in sorted(all_cods):
                info   = rubrica_info.get(cod, {"dsc": f"Verba {cod}", "tp": "1"})
                vals_n = agg_n.get(cod, [0] * 12)
                entry  = {
                    "cod":        cod,
                    "dsc":        info["dsc"],
                    "tp":         info["tp"],
                    "vals_fmt":   [ff_fmt(v) for v in vals_n],
                    "total_fmt":  ff_fmt(sum(vals_n)),
                    "adiant_fmt": ff_fmt(agg_a.get(cod, 0)),
                    "decimo_fmt": ff_fmt(agg_1.get(cod, 0)),
                }
                (prov if info["tp"] == "1" else desc).append(entry)
            verbas = prov + desc

            # totais do tab_total
            try:
                q = supabase.table("tab_total") \
                    .select("folha, folha_tipo,"
                            " valor_total_proventos, valor_total_descontos, valor_liquido,"
                            " valor_base_inss_semlimite, valor_base_inss_comlimite,"
                            " valor_irrf_basetotal, valor_irrf_basetabela,"
                            " valor_base_fgts, valor_fgts") \
                    .eq("id_empresa", id_empresa) \
                    .eq("matricula", mat_int) \
                    .gte("folha", anomes_ini) \
                    .lte("folha", anomes_fim)
                if id_cliente:
                    q = q.eq("id_cliente", id_cliente)
                tot_data = q.execute().data or []
            except Exception:
                tot_data = []

            def _acc(d, t):
                d["prov"]        += int(t.get("valor_total_proventos")     or 0)
                d["desc"]        += int(t.get("valor_total_descontos")     or 0)
                d["liq"]         += int(t.get("valor_liquido")             or 0)
                d["inss_sem"]    += int(t.get("valor_base_inss_semlimite") or 0)
                d["inss_com"]    += int(t.get("valor_base_inss_comlimite") or 0)
                d["irrf_total"]  += int(t.get("valor_irrf_basetotal")      or 0)
                d["irrf_tabela"] += int(t.get("valor_irrf_basetabela")     or 0)
                d["fgts_base"]   += int(t.get("valor_base_fgts")           or 0)
                d["fgts_val"]    += int(t.get("valor_fgts")                or 0)

            def _new_acc():
                return {"prov":0,"desc":0,"liq":0,"inss_sem":0,"inss_com":0,
                        "irrf_total":0,"irrf_tabela":0,"fgts_base":0,"fgts_val":0}

            def _fmt_acc(d):
                return {
                    "prov_fmt":        ff_fmt(d["prov"]),
                    "desc_fmt":        ff_fmt(d["desc"]),
                    "liq_fmt":         ff_fmt(d["liq"]),
                    "inss_sem_fmt":    ff_fmt(d["inss_sem"]),
                    "inss_com_fmt":    ff_fmt(d["inss_com"]),
                    "irrf_total_fmt":  ff_fmt(d["irrf_total"]),
                    "irrf_tabela_fmt": ff_fmt(d["irrf_tabela"]),
                    "fgts_base_fmt":   ff_fmt(d["fgts_base"]),
                    "fgts_val_fmt":    ff_fmt(d["fgts_val"]),
                }

            tot_mes  = {}
            acc_a    = _new_acc()
            acc_1    = _new_acc()
            acc_anual = _new_acc()
            for t in tot_data:
                ft_tipo = str(t.get("folha_tipo") or "N")
                mes     = int(t.get("folha") or 0) % 100
                if ft_tipo == "A":
                    _acc(acc_a, t)
                elif ft_tipo == "1":
                    _acc(acc_1, t)
                elif 1 <= mes <= 12:
                    if mes not in tot_mes:
                        tot_mes[mes] = _new_acc()
                    _acc(tot_mes[mes], t)
                    _acc(acc_anual, t)

            totais     = [_fmt_acc(tot_mes.get(m, _new_acc())) for m in range(1, 13)]
            tot_anual  = _fmt_acc(acc_anual)
            tot_adiant = _fmt_acc(acc_a)
            tot_decimo = _fmt_acc(acc_1)

    # lista de funcionários ativos para o select
    try:
        all_funcs = supabase.table("tab_cad") \
            .select("matricula, nome, nomer") \
            .eq("id_empresa", id_empresa) \
            .eq("situacao", "A") \
            .order("nome") \
            .execute().data or []
    except Exception:
        all_funcs = []
    for f in all_funcs:
        f["nome_fmt"] = (f.get("nomer") or f.get("nome") or "").strip()

    return render_template(
        "F10_Rel_Ficha_Financeira.html",
        **_ctx_relatorio(),
        mat=mat_raw,
        ano=ano,
        anos_disponiveis=anos_disponiveis,
        MESES=MESES,
        func=func,
        all_funcs=all_funcs,
        verbas=verbas,
        totais=totais,
        tot_anual=tot_anual,
        tot_adiant=tot_adiant,
        tot_decimo=tot_decimo,
        erro=erro,
    )


@app.route("/rel_ficha_financeira_pdf")
def rel_ficha_financeira_pdf():
    if not session.get("logado"):
        return redirect("/")

    from io import BytesIO
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    ano_atual  = datetime.now().year
    MESES_ABR  = ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"]

    def ff_fmt(centavos):
        if not centavos:
            return "—"
        v = centavos / 100
        return f"{v:,.2f}".replace(",","X").replace(".",",").replace("X",".")

    mat_raw = request.args.get("mat", "").strip()
    try:
        ano = int(request.args.get("ano", ano_atual))
    except ValueError:
        ano = ano_atual

    if not mat_raw.isdigit():
        return redirect("/rel_ficha_financeira")
    mat_int = int(mat_raw)

    # ── dados funcionário ──
    try:
        r = supabase.table("tab_cad") \
            .select("matricula, nome, nomer") \
            .eq("id_empresa", id_empresa) \
            .eq("matricula", mat_int) \
            .limit(1).execute()
        func = r.data[0] if r.data else None
    except Exception:
        func = None
    if not func:
        return redirect("/rel_ficha_financeira")

    nome_func = (func.get("nomer") or func.get("nome") or "").strip()
    mat_fmt   = f"{mat_int:06d}"

    anomes_ini = int(f"{ano}01")
    anomes_fim = int(f"{ano}12")

    # ── tab_mov: separado por folha_tipo ──
    try:
        q = supabase.table("tab_mov") \
            .select("cod_verba, valor, folha, folha_tipo") \
            .eq("id_empresa", id_empresa) \
            .eq("matricula", mat_int) \
            .eq("situacao", "A") \
            .gte("folha", anomes_ini) \
            .lte("folha", anomes_fim)
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        mov_data = q.execute().data or []
    except Exception:
        mov_data = []

    agg_n, agg_a, agg_1 = {}, {}, {}
    for m in mov_data:
        cod = int(m.get("cod_verba") or 0)
        if not cod:
            continue
        ft  = str(m.get("folha_tipo") or "N")
        val = int(m.get("valor") or 0)
        if ft == "A":
            agg_a[cod] = agg_a.get(cod, 0) + val
        elif ft == "1":
            agg_1[cod] = agg_1.get(cod, 0) + val
        else:
            mes = int(m.get("folha") or 0) % 100
            if 1 <= mes <= 12:
                if cod not in agg_n:
                    agg_n[cod] = [0] * 12
                agg_n[cod][mes - 1] += val

    all_cods = set(agg_n) | set(agg_a) | set(agg_1)
    rubrica_info = {}
    if all_cods:
        try:
            cli_ids = [0] + ([id_cliente] if id_cliente else [])
            r_rub = supabase.table("tab_rubrica") \
                .select("cod_rubr, dsc_rubr, tp_rubr, id_cliente") \
                .in_("id_cliente", cli_ids) \
                .in_("cod_rubr", list(all_cods)) \
                .eq("situacao", "A") \
                .execute()
            for row in (r_rub.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod not in rubrica_info or int(row.get("id_cliente") or 0) != 0:
                    rubrica_info[cod] = {
                        "dsc": row.get("dsc_rubr") or f"Verba {cod}",
                        "tp":  str(row.get("tp_rubr") or "1"),
                    }
        except Exception:
            pass

    prov, desc = [], []
    for cod in sorted(all_cods):
        info   = rubrica_info.get(cod, {"dsc": f"Verba {cod}", "tp": "1"})
        vals_n = agg_n.get(cod, [0] * 12)
        entry  = {
            "dsc":   info["dsc"], "tp": info["tp"],
            "vals":  vals_n, "total": sum(vals_n),
            "adiant": agg_a.get(cod, 0), "decimo": agg_1.get(cod, 0),
        }
        (prov if info["tp"] == "1" else desc).append(entry)

    # ── tab_total: separado por folha_tipo ──
    try:
        q = supabase.table("tab_total") \
            .select("folha, folha_tipo,"
                    " valor_total_proventos, valor_total_descontos, valor_liquido,"
                    " valor_base_inss_semlimite, valor_base_inss_comlimite,"
                    " valor_irrf_basetotal, valor_irrf_basetabela,"
                    " valor_base_fgts, valor_fgts") \
            .eq("id_empresa", id_empresa) \
            .eq("matricula", mat_int) \
            .gte("folha", anomes_ini) \
            .lte("folha", anomes_fim)
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        tot_data = q.execute().data or []
    except Exception:
        tot_data = []

    def _new_a():
        return {"prov":0,"desc":0,"liq":0,"inss_sem":0,"inss_com":0,
                "irrf_tot":0,"irrf_tab":0,"fgts_base":0,"fgts_val":0}

    def _acc_t(d, t):
        d["prov"]     += int(t.get("valor_total_proventos")     or 0)
        d["desc"]     += int(t.get("valor_total_descontos")     or 0)
        d["liq"]      += int(t.get("valor_liquido")             or 0)
        d["inss_sem"] += int(t.get("valor_base_inss_semlimite") or 0)
        d["inss_com"] += int(t.get("valor_base_inss_comlimite") or 0)
        d["irrf_tot"] += int(t.get("valor_irrf_basetotal")      or 0)
        d["irrf_tab"] += int(t.get("valor_irrf_basetabela")     or 0)
        d["fgts_base"]+= int(t.get("valor_base_fgts")           or 0)
        d["fgts_val"] += int(t.get("valor_fgts")                or 0)

    tot_mes, acc_a, acc_1, acc_n = {}, _new_a(), _new_a(), _new_a()
    for t in tot_data:
        ft_tipo = str(t.get("folha_tipo") or "N")
        mes     = int(t.get("folha") or 0) % 100
        if ft_tipo == "A":
            _acc_t(acc_a, t)
        elif ft_tipo == "1":
            _acc_t(acc_1, t)
        elif 1 <= mes <= 12:
            if mes not in tot_mes:
                tot_mes[mes] = _new_a()
            _acc_t(tot_mes[mes], t)
            _acc_t(acc_n, t)

    # ── ReportLab ──
    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))
    titulo     = f"Ficha Financeira — {mat_fmt}  {nome_func}  —  Exercício {ano}"

    buf  = BytesIO()
    page = landscape(A4)
    # 16 colunas: nome + 12 meses + Total + Adiant.13 + 13ºSal.
    # largura útil = 29.7cm - 3cm margens, com 6pt de buffer para evitar overflow
    W       = page[0] - 3 * cm - 6
    col_nm  = 3.8 * cm
    col_ext = 1.65 * cm         # Total Ano, Adiant.13, 13ºSal.
    col_m   = (W - col_nm - 3 * col_ext) / 12
    col_ws  = [col_nm] + [col_m] * 12 + [col_ext, col_ext, col_ext]

    doc = SimpleDocTemplate(buf, pagesize=page,
                            leftMargin=1.5*cm, rightMargin=1.5*cm,
                            topMargin=1.8*cm,  bottomMargin=1.5*cm)

    c_navy   = colors.HexColor("#0b1f3a")
    c_adiant = colors.HexColor("#1a3a2a")
    c_decimo = colors.HexColor("#2a1a3a")
    c_prov   = colors.HexColor("#166534")
    bg_prov  = colors.HexColor("#f0fdf4")
    c_desc   = colors.HexColor("#991b1b")
    bg_desc  = colors.HexColor("#fff7f7")
    c_border = colors.HexColor("#dde3ec")
    c_total  = colors.HexColor("#eaf1fb")
    c_base   = colors.HexColor("#f8fafc")
    c_base_h = colors.HexColor("#f1f5f9")
    cW       = colors.white

    def P(txt, fn="Helvetica", fs=6, col=colors.black, align=0):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, textColor=col,
                            alignment=align, leading=fs + 2)
        return Paragraph(str(txt), st)

    def Ph(txt, fn="Helvetica-Bold", fs=6, align=1):
        """Parágrafo de cabeçalho — sempre branco."""
        return P(txt, fn=fn, fs=fs, col=cW, align=align)

    N_EXTRA = 3   # colunas extras após os 12 meses

    # cabeçalho — texto branco explícito
    c_hdr_bg  = colors.HexColor("#e8edf4")   # fundo claro para cabeçalho de meses
    c_hdr_txt = colors.HexColor("#0b1f3a")   # texto escuro navy

    def Pm(txt):
        """Parágrafo de cabeçalho de mês — navy escuro, centralizado."""
        return P(txt, fn="Helvetica-Bold", fs=6, col=c_hdr_txt, align=1)

    hdr_row = ([P("Verba", fn="Helvetica-Bold", fs=6, col=c_hdr_txt)]
               + [Pm(m) for m in MESES_ABR]
               + [P("Total Ano", fn="Helvetica-Bold", fs=6, col=c_hdr_txt, align=1),
                  P("Adiant.13", fn="Helvetica-Bold", fs=6, col=c_hdr_txt, align=1),
                  P("13º Sal.",  fn="Helvetica-Bold", fs=6, col=c_hdr_txt, align=1)])

    tbl_data   = [hdr_row]
    tbl_styles = [
        ("BACKGROUND", (0, 0),  (-1, 0),  c_hdr_bg),
        ("LINEBELOW",  (0, 0),  (-1, 0),  1.0, c_navy),
        ("FONTSIZE",   (0, 0),  (-1, -1), 6),
        ("TOPPADDING",    (0, 0), (-1, -1), 2),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ("LEFTPADDING",   (0, 0), (-1, -1), 2),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
        ("VALIGN",     (0, 0),  (-1, -1), "MIDDLE"),
    ]

    def _verba_row(v):
        vals_n = v["vals"]
        return ([P(v["dsc"])]
                + [P(ff_fmt(x), align=2) for x in vals_n]
                + [P(ff_fmt(v["total"]),  fn="Helvetica-Bold", align=2),
                   P(ff_fmt(v["adiant"]), fn="Helvetica-Bold", align=2),
                   P(ff_fmt(v["decimo"]), fn="Helvetica-Bold", align=2)])

    def _sec_row(label, col_txt):
        return [P(label, fn="Helvetica-Bold", fs=5, col=col_txt)] + [""] * (12 + N_EXTRA)

    def _tot_row(label, key, bold=True):
        fn = "Helvetica-Bold" if bold else "Helvetica"
        mes_vals = [tot_mes.get(m, _new_a()).get(key, 0) for m in range(1, 13)]
        return ([P(label, fn=fn, fs=6)]
                + [P(ff_fmt(v), fn=fn, align=2) for v in mes_vals]
                + [P(ff_fmt(acc_n.get(key, 0)),  fn=fn, align=2),
                   P(ff_fmt(acc_a.get(key, 0)),  fn=fn, align=2),
                   P(ff_fmt(acc_1.get(key, 0)),  fn=fn, align=2)])

    # PROVENTOS
    if prov:
        ri = len(tbl_data)
        tbl_data.append(_sec_row("PROVENTOS", c_prov))
        tbl_styles += [("SPAN", (0,ri),(-1,ri)),
                       ("BACKGROUND",(0,ri),(-1,ri),bg_prov),
                       ("LINEBELOW",(0,ri),(-1,ri),0.3,c_border)]
        for v in prov:
            ri = len(tbl_data)
            tbl_data.append(_verba_row(v))
            tbl_styles.append(("LINEBELOW",(0,ri),(-1,ri),0.2,colors.HexColor("#e5e7eb")))

    # DESCONTOS
    if desc:
        ri = len(tbl_data)
        tbl_data.append(_sec_row("DESCONTOS", c_desc))
        tbl_styles += [("SPAN",(0,ri),(-1,ri)),
                       ("BACKGROUND",(0,ri),(-1,ri),bg_desc),
                       ("LINEBELOW",(0,ri),(-1,ri),0.3,c_border)]
        for v in desc:
            ri = len(tbl_data)
            tbl_data.append(_verba_row(v))
            tbl_styles.append(("LINEBELOW",(0,ri),(-1,ri),0.2,colors.HexColor("#e5e7eb")))

    # TOTAIS
    for label, key in [("Total Proventos","prov"),
                        ("Total Descontos","desc"),
                        ("Líquido",        "liq")]:
        ri = len(tbl_data)
        tbl_data.append(_tot_row(label, key))
        tbl_styles += [("BACKGROUND",(0,ri),(-1,ri),c_total),
                       ("LINEABOVE",(0,ri),(-1,ri),0.5,c_border)]

    # BASES DE CÁLCULO
    ri = len(tbl_data)
    tbl_data.append([P("BASES DE CÁLCULO", fn="Helvetica-Bold", fs=5,
                        col=colors.HexColor("#475569"))] + [""] * (12 + N_EXTRA))
    tbl_styles += [("SPAN",(0,ri),(-1,ri)),
                   ("BACKGROUND",(0,ri),(-1,ri),c_base_h),
                   ("LINEABOVE",(0,ri),(-1,ri),0.5,c_border),
                   ("LINEBELOW",(0,ri),(-1,ri),0.3,c_border)]

    for label, key in [("Base INSS (sem limite)", "inss_sem"),
                        ("Base INSS (com limite)", "inss_com"),
                        ("Base IRRF (total)",      "irrf_tot"),
                        ("Base IRRF (tabela)",     "irrf_tab"),
                        ("Base FGTS",              "fgts_base"),
                        ("FGTS a depositar",       "fgts_val")]:
        ri = len(tbl_data)
        tbl_data.append(_tot_row(label, key, bold=False))
        tbl_styles += [("BACKGROUND",(0,ri),(-1,ri),c_base),
                       ("LINEBELOW",(0,ri),(-1,ri),0.2,c_border)]

    tbl = Table(tbl_data, colWidths=col_ws, repeatRows=1)
    tbl.setStyle(TableStyle(tbl_styles))

    # cabeçalho landscape: largura proporcional ao A4 deitado (26.7cm útil)
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    W_hdr = page[0] - 3 * cm
    col_hdr = [W_hdr * 0.45, W_hdr * 0.10, W_hdr * 0.45]
    agora_hdr = datetime.now().strftime("%d/%m/%Y %H:%M")
    st_hL = ParagraphStyle("hL", fontName="Helvetica",      fontSize=8, leading=10)
    st_hR = ParagraphStyle("hR", fontName="Helvetica",      fontSize=8, leading=10, alignment=TA_RIGHT)
    st_hT = ParagraphStyle("hT", fontName="Helvetica-Bold", fontSize=9, leading=11, alignment=TA_CENTER)
    hdr_tbl = Table(
        [[Paragraph(f"{cnpj_fmt} — {empresa_nm}", st_hL), "", Paragraph(agora_hdr, st_hR)],
         [Paragraph(titulo, st_hT), "", ""]],
        colWidths=col_hdr)
    hdr_tbl.setStyle(TableStyle([
        ("SPAN",          (0, 1), (-1, 1)),
        ("SPAN",          (0, 0), (1, 0)),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING",    (0, 0), (-1, -1), 2),
        ("BOTTOMPADDING", (0, 0), (-1, 0), 2),
        ("BOTTOMPADDING", (0, 1), (-1, 1), 5),
        ("LEFTPADDING",   (0, 0), (-1, -1), 0),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
        ("LINEBELOW",     (0, 1), (-1, 1), 0.5, colors.HexColor("#374151")),
    ]))
    story = [hdr_tbl, Spacer(1, 6), tbl]
    doc.build(story, onFirstPage=_pdf_num_pagina, onLaterPages=_pdf_num_pagina)
    buf.seek(0)

    from flask import make_response
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="FichaFinanceira_{mat_fmt}_{ano}.pdf"'
    return resp


@app.route("/gerador_relatorio")
def gerador_relatorio():
    if not session.get("logado"):
        return redirect("/")

    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    ano_atual   = datetime.now().year
    _anomes     = str(session.get("anomes_atual") or "")
    _ano_folha  = int(_anomes[:4]) if len(_anomes) >= 4 else ano_atual
    _mes_folha  = int(_anomes[4:6]) if len(_anomes) >= 6 else datetime.now().month

    CAD_CAMPOS = [
        # (key, label, db_col, tipo)  — tipo: txt | data | val
        ("cpf",         "CPF",             "cpf",         "txt"),
        ("dtadm",       "Admissão",        "dtadm",       "data"),
        ("funcao_cbo",  "Função CBO",      "cbofuncao",   "txt"),
        ("funcao_nome", "Função Nome",     "",            "lookup_funcao"),
        ("vrsalfx",     "Salário Fixo",    "vrsalfx",     "val"),
        ("dtnascto",    "Nascimento",      "dtnascto",    "data"),
        ("sexo",        "Sexo",            "sexo",        "txt"),
        ("estadocivil", "Estado Civil",    "estadocivil", "txt"),
        ("email",       "E-mail",          "email",       "txt"),
        ("telefone",    "Telefone",        "telefone",    "txt"),
        ("endereco",    "Endereço",        "endereco",    "txt"),
        ("cidade",      "Cidade",          "cidade",      "txt"),
        ("uf",          "UF",              "uf",          "txt"),
        ("cep",         "CEP",             "cep",         "txt"),
        ("banco",       "Banco",           "banco",       "txt"),
        ("agencia",     "Agência",         "agencia",     "txt"),
        ("conta",       "Conta",           "conta",       "txt"),
    ]
    CAD_CAMPOS_MAP  = {k: (lbl, col, tp) for k, lbl, col, tp in CAD_CAMPOS}
    CAD_DEFAULTS    = []

    mat_raw        = request.args.get("mat",            "").strip()
    sit            = request.args.get("sit",            "A")
    ano            = int(request.args.get("ano",     _ano_folha) or _ano_folha)
    mes_ini        = int(request.args.get("mes_ini", _mes_folha) or _mes_folha)
    mes_fim        = int(request.args.get("mes_fim", _mes_folha) or _mes_folha)
    classificacao  = _def_classificacao()
    titulo_rel     = request.args.get("titulo_rel",    "").strip()

    TOT_BASES = [
        # (key, label, db_col, tp)  tp: val=centavos→R$  int=inteiro puro
        ("prov",         "Total Proventos",   "valor_total_proventos",     "val"),
        ("desc",         "Total Descontos",   "valor_total_descontos",     "val"),
        ("liq",          "Líquido",           "valor_liquido",             "val"),
        ("base_inss_sl", "Base INSS s/teto",  "valor_base_inss_semlimite", "val"),
        ("base_inss_cl", "Base INSS c/teto",  "valor_base_inss_comlimite", "val"),
        ("inss",         "INSS Retido",       "valor_inss_retido",         "val"),
        ("base_fgts",    "Base FGTS",         "valor_base_fgts",           "val"),
        ("fgts",         "FGTS",              "valor_fgts",                "val"),
        ("base_irrf_bt", "Base IRRF bruta",   "valor_irrf_basetotal",      "val"),
        ("base_irrf_bk", "Base IRRF tabela",  "valor_irrf_basetabela",     "val"),
        ("ded_dep_irrf", "Ded. Dep. IRRF",    "valor_irrf_dependentes",    "val"),
        ("qtd_dep_irrf", "Qtd. Dep. IRRF",    "qtd_irrf_dependentes",      "int"),
        ("salario",      "Salário nesta Folha", "valor_salario",           "val"),
    ]
    TOT_BASES_MAP = {k: (lbl, col, tp) for k, lbl, col, tp in TOT_BASES}

    sec_cad     = request.args.get("sec_cad")     == "1"
    sec_totais  = request.args.get("sec_totais")  == "1"
    sec_mov     = request.args.get("sec_mov")     == "1"
    sec_eventos = request.args.get("sec_eventos") == "1"
    sec_dep     = request.args.get("sec_dep")     == "1"
    dep_somente = request.args.get("dep_somente") == "1"
    dep_tipos   = [t for t in request.args.getlist("dep_tipo") if str(t).isdigit() and 0 < int(t) < 200]

    tipos_dep_list = []
    try:
        _tdep = supabase.table("tab_tabela_total").select("codigo,texto") \
            .eq("num_tabela", 7).neq("codigo", "DOC").order("codigo").execute()
        tipos_dep_list = [
            {"cod": int(t["codigo"]), "texto": t["texto"]}
            for t in (_tdep.data or [])
            if str(t.get("codigo", "")).strip().isdigit()
        ]
    except Exception:
        pass
    mov_fields  = [int(x) for x in request.args.getlist("mov_f") if str(x).isdigit()]
    tot_fields  = [k for k in request.args.getlist("tot_f") if k in TOT_BASES_MAP]
    ev_tipos    = [t for t in request.args.getlist("ev_tipo") if t in ("3", "6")]
    ev_periodo  = request.args.get("ev_periodo", "mes")
    gerando     = any([sec_cad, sec_totais, sec_mov, sec_eventos, sec_dep])

    cad_fields    = request.args.getlist("cad_f")
    order_col     = "nome" if classificacao == "A" else "matricula"

    # lista de funcionários para o select
    try:
        all_funcs = supabase.table("tab_cad") \
            .select("matricula, nome, nomer, situacao") \
            .eq("id_empresa", id_empresa).order("nome").execute().data or []
    except Exception:
        all_funcs = []
    for f in all_funcs:
        f["nome_fmt"] = (f.get("nomer") or f.get("nome") or "").strip()

    todas_verbas = request.args.get("todas_verbas") == "1"

    try:
        _cli_rubr = [0] + ([id_cliente] if id_cliente else [])
        all_verbas = (supabase.table("tab_rubrica")
                     .select("cod_rubr, dsc_rubr, tp_rubr")
                     .in_("id_cliente", _cli_rubr)
                     .eq("situacao","A").order("cod_rubr")
                     .execute().data or [])
        for _v in all_verbas:
            _v["cod_rubr"] = int(_v.get("cod_rubr") or 0)
    except Exception:
        all_verbas = []

    # Filtra verbas pelo período selecionado (a menos que todas_verbas=1)
    mov_verbas_filtrado = False
    if not todas_verbas and all_verbas:
        try:
            _anomes_ini_ui = int(f"{ano}{mes_ini:02d}")
            _anomes_fim_ui = int(f"{ano}{mes_fim:02d}")
            _qmov = (supabase.table("tab_mov")
                     .select("cod_verba")
                     .eq("id_empresa", id_empresa)
                     .eq("situacao", "A").eq("folha_tipo", "N")
                     .gte("folha", _anomes_ini_ui).lte("folha", _anomes_fim_ui))
            if id_cliente:
                _qmov = _qmov.eq("id_cliente", id_cliente)
            _cod_usados = {int(r["cod_verba"])
                           for r in (_qmov.execute().data or []) if r.get("cod_verba")}
            if _cod_usados:
                all_verbas = [v for v in all_verbas if v["cod_rubr"] in _cod_usados]
                mov_verbas_filtrado = True
        except Exception:
            pass  # mantém lista completa em caso de erro

    _rub_dsc_map = {v["cod_rubr"]: v.get("dsc_rubr") or f"V.{v['cod_rubr']}" for v in all_verbas}
    mov_col_labels = [{"cod": c, "label": f"{c:04d} — {_rub_dsc_map.get(c, f'Verba {c}')}"}
                      for c in mov_fields] if (sec_mov and mov_fields) else []

    MESES_LABEL = [("1","Janeiro"),("2","Fevereiro"),("3","Março"),("4","Abril"),
                   ("5","Maio"),("6","Junho"),("7","Julho"),("8","Agosto"),
                   ("9","Setembro"),("10","Outubro"),("11","Novembro"),("12","Dezembro")]
    anos_disp   = list(range(ano_atual, ano_atual - 6, -1))

    relatorio, erro = [], None
    ev_total = 0

    if gerando:
        anomes_ini = int(f"{ano}{mes_ini:02d}")
        anomes_fim = int(f"{ano}{mes_fim:02d}")

        def _fval(c):
            if not c:
                return "—"
            return f"R$ {c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")

        def _fnum(c):
            if not c: return "—"
            return f"{c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")

        def _fdata(d):
            s = str(d or "")
            return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else (s or "—")

        def _dias_ev(ref1, d1i, d1f):
            if ref1:
                return str(ref1)
            try:
                s1 = str(d1i or "").replace("-", "")
                s2 = str(d1f or "").replace("-", "")
                if len(s1) == 8 and len(s2) == 8:
                    dt1 = date(int(s1[:4]), int(s1[4:6]), int(s1[6:]))
                    dt2 = date(int(s2[:4]), int(s2[4:6]), int(s2[6:]))
                    return str((dt2 - dt1).days + 1)
            except Exception:
                pass
            return "—"

        # funcionários do filtro
        try:
            _always = ["matricula", "nome", "nomer", "situacao"]
            _extra  = [CAD_CAMPOS_MAP[k][1] for k in cad_fields
                       if k in CAD_CAMPOS_MAP and CAD_CAMPOS_MAP[k][1]]
            if "funcao_nome" in cad_fields and "cbofuncao" not in _extra:
                _extra.append("cbofuncao")
            _sel    = ", ".join(dict.fromkeys(_always + _extra))
            q = supabase.table("tab_cad") \
                .select(_sel) \
                .eq("id_empresa", id_empresa).order(order_col)
            if sit != "T":
                q = q.eq("situacao", sit)
            if mat_raw.isdigit():
                q = q.eq("matricula", int(mat_raw))
            funcs = q.execute().data or []
        except Exception as e:
            funcs = []; erro = f"Erro ao buscar funcionários: {e}"

        if funcs:
            mats = [int(f["matricula"]) for f in funcs]

            mov_por_mat, tot_por_mat, tot_agg_por_mat, ev_por_mat, dep_por_mat = {}, {}, {}, {}, {}
            ev_total = 0

            if sec_mov and mov_fields:
                try:
                    q = supabase.table("tab_mov") \
                        .select("matricula, cod_verba, valor") \
                        .eq("id_empresa", id_empresa).eq("situacao","A") \
                        .eq("folha_tipo","N").in_("matricula", mats) \
                        .in_("cod_verba", mov_fields) \
                        .gte("folha", anomes_ini).lte("folha", anomes_fim)
                    if id_cliente:
                        q = q.eq("id_cliente", id_cliente)
                    for row in (q.execute().data or []):
                        m = int(row.get("matricula") or 0)
                        mov_por_mat.setdefault(m, []).append(row)
                except Exception:
                    pass

            if sec_totais:
                _card_cols  = ["matricula", "folha", "folha_tipo",
                               "valor_total_proventos", "valor_total_descontos",
                               "valor_liquido", "valor_inss_retido",
                               "valor_fgts", "valor_irrf_basetabela"]
                _pivot_cols = [TOT_BASES_MAP[k][1] for k in tot_fields if k in TOT_BASES_MAP]
                _tot_sel    = ", ".join(dict.fromkeys(_card_cols + _pivot_cols))
                try:
                    q = supabase.table("tab_total") \
                        .select(_tot_sel) \
                        .eq("id_empresa", id_empresa).in_("matricula", mats) \
                        .gte("folha", anomes_ini).lte("folha", anomes_fim)
                    if id_cliente:
                        q = q.eq("id_cliente", id_cliente)
                    for row in (q.execute().data or []):
                        m = int(row.get("matricula") or 0)
                        tot_por_mat.setdefault(m, []).append(row)
                        if tot_fields:
                            tot_agg_por_mat.setdefault(m, {})
                            for k in tot_fields:
                                col = TOT_BASES_MAP[k][1]
                                tot_agg_por_mat[m][k] = (
                                    tot_agg_por_mat[m].get(k, 0) + int(row.get(col) or 0)
                                )
                except Exception:
                    pass

            if sec_eventos and ev_tipos:
                try:
                    _ev_op1 = [int(t) for t in ev_tipos]
                    q = supabase.table("tab_eventos") \
                        .select("matricula, op1, data1i, data1f, ref1, campotxt1") \
                        .eq("id_empresa", id_empresa) \
                        .in_("op1", _ev_op1)
                    if ev_periodo == "mes":
                        _d_ini = f"{ano}{mes_ini:02d}01"
                        _d_fim = f"{ano}{mes_fim:02d}31"
                        q = q.gte("data1i", _d_ini).lte("data1i", _d_fim)
                    if id_cliente:
                        q = q.eq("id_cliente", id_cliente)
                    for row in (q.execute().data or []):
                        m = int(row.get("matricula") or 0)
                        if m in mats:
                            ev_por_mat.setdefault(m, []).append(row)
                except Exception as e:
                    erro = f"Erro ao buscar eventos: {e}"

            ev_total = sum(len(v) for v in ev_por_mat.values())

            if sec_dep:
                try:
                    q = supabase.table("tab_dependentes") \
                        .select("matricula, nome, tpdep, dtnascto, depirrf, depsf") \
                        .eq("id_empresa", id_empresa).in_("matricula", mats)
                    if id_cliente:
                        q = q.eq("id_cliente", id_cliente)
                    if dep_tipos:
                        q = q.in_("tpdep", [int(t) for t in dep_tipos])
                    for row in (q.execute().data or []):
                        m = int(row.get("matricula") or 0)
                        dep_por_mat.setdefault(m, []).append(row)
                except Exception:
                    pass

            mapa_funcao = {}
            if "funcao_nome" in cad_fields:
                try:
                    cbos = list({str(f.get("cbofuncao") or "").strip() for f in funcs if f.get("cbofuncao")})
                    if cbos:
                        rc = supabase.table("tab_aux_funcao_total") \
                            .select("cbo_codigo, cbo_nome").in_("cbo_codigo", cbos).execute()
                        mapa_funcao = {str(r.get("cbo_codigo") or ""): str(r.get("cbo_nome") or "—")
                                       for r in (rc.data or [])}
                except Exception:
                    pass

            OP1_LABEL = {3:"Férias", 5:"Aumento Salarial", 6:"Afastamento",
                         9:"Aviso Prévio / Rescisão"}
            TPDEP     = ({t["cod"]: t["texto"] for t in tipos_dep_list}
                         if tipos_dep_list else {1:"Cônjuge", 3:"Filho(a)/Enteado(a)", 9:"Pais"})
            TP_FOLHA  = {"N":"Normal","A":"Adiant. 13º","1":"13º Salário",
                         "F":"Férias","R":"Rescisão"}

            mov_col_sums = {c: 0 for c in mov_fields}
            tot_col_sums = {k: 0 for k in tot_fields}

            for f in funcs:
                mat  = int(f.get("matricula") or 0)
                nome = (f.get("nomer") or f.get("nome") or "").strip()
                bloco = {"mat": f"{mat:06d}", "nome": nome, "sit": f.get("situacao","A")}

                if sec_cad:
                    cad_row = {}
                    for k in cad_fields:
                        if k not in CAD_CAMPOS_MAP:
                            continue
                        lbl, col, tp = CAD_CAMPOS_MAP[k]
                        raw = f.get(col)
                        if tp == "val":
                            disp = _fval(raw)
                        elif tp == "data":
                            disp = _fdata(raw)
                        elif tp == "lookup_funcao":
                            cbo = str(f.get("cbofuncao") or "").strip()
                            disp = mapa_funcao.get(cbo, "—")
                        else:
                            disp = str(raw or "—")
                        cad_row[k] = {"label": lbl, "valor": disp}
                    bloco["cad"] = cad_row

                if sec_totais:
                    rows = sorted(tot_por_mat.get(mat, []),
                                  key=lambda x: (x.get("folha") or 0))
                    bloco["totais"] = [{
                        "folha": (lambda s: f"{s[4:6]}/{s[:4]}" if len(s)==6 else s)(str(r.get("folha") or "")),
                        "tipo":  TP_FOLHA.get(str(r.get("folha_tipo") or "N"), "Normal"),
                        "prov":  _fval(r.get("valor_total_proventos")),
                        "desc":  _fval(r.get("valor_total_descontos")),
                        "liq":   _fval(r.get("valor_liquido")),
                        "inss":  _fval(r.get("valor_inss_retido")),
                        "fgts":  _fval(r.get("valor_fgts")),
                        "irrf":  _fval(r.get("valor_irrf_basetabela")),
                    } for r in rows]

                if sec_mov and mov_fields:
                    _agg = {}
                    for r in mov_por_mat.get(mat, []):
                        cod = int(r.get("cod_verba") or 0)
                        _agg[cod] = _agg.get(cod, 0) + int(r.get("valor") or 0)
                    bloco["mov_pivot"] = {c: _fnum(_agg.get(c)) for c in mov_fields}
                    for c in mov_fields:
                        mov_col_sums[c] += _agg.get(c, 0)

                if sec_totais and tot_fields:
                    _tagg = tot_agg_por_mat.get(mat, {})
                    bloco["tot_pivot"] = {
                        k: (str(_tagg.get(k, 0))
                            if TOT_BASES_MAP[k][2] == "int"
                            else _fnum(_tagg.get(k)))
                        for k in tot_fields if k in TOT_BASES_MAP
                    }
                    for k in tot_fields:
                        tot_col_sums[k] += _tagg.get(k, 0)

                if sec_eventos:
                    bloco["eventos"] = [{
                        "tipo":   OP1_LABEL.get(int(r.get("op1") or 0), f"Evento {r.get('op1')}"),
                        "data1i": _fdata(r.get("data1i")),
                        "data1f": _fdata(r.get("data1f")),
                        "ref1":   _dias_ev(r.get("ref1"), r.get("data1i"), r.get("data1f")),
                        "obs":    r.get("campotxt1") or "—",
                    } for r in sorted(ev_por_mat.get(mat, []),
                                      key=lambda x: (x.get("data1i") or ""))]

                if sec_dep:
                    bloco["deps"] = [{
                        "nome":   r.get("nome") or "—",
                        "tipo":   TPDEP.get(int(r.get("tpdep") or 0), "Outro"),
                        "dtnasc": _fdata(r.get("dtnascto")),
                        "irrf":   "Sim" if r.get("depirrf") else "Não",
                        "sf":     "Sim" if r.get("depsf") else "Não",
                    } for r in dep_por_mat.get(mat, [])]
                    if dep_somente and not bloco["deps"]:
                        continue

                relatorio.append(bloco)
        elif not erro:
            erro = "Nenhum funcionário encontrado com os filtros informados."

    tot_col_labels = [{"key": k, "label": TOT_BASES_MAP[k][0]}
                      for k in tot_fields if k in TOT_BASES_MAP] if (sec_totais and tot_fields) else []

    def _fmt_sum(v, tp="val"):
        return str(v) if tp == "int" else (_fval_outer(v) if v else "—")

    def _fval_outer(c):
        if not c: return "—"
        return f"{c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")

    mov_col_sums_fmt = (
        {c: _fval_outer(v) for c, v in mov_col_sums.items()}
        if gerando and mov_fields else {}
    )
    tot_col_sums_fmt = (
        {k: (str(v) if TOT_BASES_MAP.get(k, ("","","val"))[2] == "int" else _fval_outer(v))
         for k, v in tot_col_sums.items()}
        if gerando and tot_fields else {}
    )

    n_cols_total = (1 + len(cad_fields)
                   + (len(mov_fields) if sec_mov else 0)
                   + (len(tot_fields) if sec_totais else 0))
    COL_LIMIT    = 8

    return render_template(
        "F10_Gerador_Relatorio.html",
        **_ctx_relatorio(),
        all_funcs=all_funcs,
        anos_disp=anos_disp,
        MESES_LABEL=MESES_LABEL,
        mat=mat_raw, sit=sit, ano=ano, mes_ini=mes_ini, mes_fim=mes_fim,
        classificacao=classificacao, titulo_rel=titulo_rel,
        sec_cad=sec_cad, sec_totais=sec_totais, sec_mov=sec_mov,
        sec_eventos=sec_eventos, sec_dep=sec_dep,
        dep_somente=dep_somente, dep_tipos=dep_tipos,
        tipos_dep_list=tipos_dep_list,
        ev_tipos=ev_tipos, ev_periodo=ev_periodo,
        CAD_CAMPOS=CAD_CAMPOS, cad_fields=cad_fields,
        all_verbas=all_verbas, mov_verbas_filtrado=mov_verbas_filtrado,
        mov_fields=mov_fields, mov_col_labels=mov_col_labels,
        TOT_BASES=TOT_BASES, tot_fields=tot_fields, tot_col_labels=tot_col_labels,
        mov_col_sums=mov_col_sums_fmt, tot_col_sums=tot_col_sums_fmt,
        n_cols_total=n_cols_total, COL_LIMIT=COL_LIMIT,
        gerando=gerando, relatorio=relatorio, erro=erro,
        ev_total=ev_total,
    )


@app.route("/gerador_relatorio_pdf")
def gerador_relatorio_pdf():
    if not session.get("logado"):
        return redirect("/")

    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm
    import io

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    CAD_CAMPOS = [
        ("cpf",         "CPF",             "cpf",         "txt"),
        ("dtadm",       "Admissão",        "dtadm",       "data"),
        ("funcao_cbo",  "Função CBO",      "cbofuncao",   "txt"),
        ("funcao_nome", "Função Nome",     "",            "lookup_funcao"),
        ("vrsalfx",     "Salário Fixo",    "vrsalfx",     "val"),
        ("dtnascto",    "Nascimento",      "dtnascto",    "data"),
        ("sexo",        "Sexo",            "sexo",        "txt"),
        ("estadocivil", "Estado Civil",    "estadocivil", "txt"),
        ("email",       "E-mail",          "email",       "txt"),
        ("telefone",    "Telefone",        "telefone",    "txt"),
        ("endereco",    "Endereço",        "endereco",    "txt"),
        ("cidade",      "Cidade",          "cidade",      "txt"),
        ("uf",          "UF",              "uf",          "txt"),
        ("cep",         "CEP",             "cep",         "txt"),
        ("banco",       "Banco",           "banco",       "txt"),
        ("agencia",     "Agência",         "agencia",     "txt"),
        ("conta",       "Conta",           "conta",       "txt"),
    ]
    CAD_CAMPOS_MAP = {k: (lbl, col, tp) for k, lbl, col, tp in CAD_CAMPOS}

    mat_raw       = request.args.get("mat",           "").strip()
    sit           = request.args.get("sit",           "A")
    ano           = int(request.args.get("ano", datetime.now().year) or datetime.now().year)
    mes_ini       = int(request.args.get("mes_ini", 1)  or 1)
    mes_fim       = int(request.args.get("mes_fim", 12) or 12)
    anomes_ini    = int(f"{ano}{mes_ini:02d}")
    anomes_fim    = int(f"{ano}{mes_fim:02d}")
    classificacao = _def_classificacao()
    titulo_rel    = request.args.get("titulo_rel",   "").strip()
    cad_fields    = request.args.getlist("cad_f")
    sec_mov       = request.args.get("sec_mov")    == "1"
    sec_totais    = request.args.get("sec_totais") == "1"
    mov_fields    = [int(x) for x in request.args.getlist("mov_f") if str(x).isdigit()]
    order_col     = "nome" if classificacao == "A" else "matricula"

    TOT_BASES_PDF = [
        ("prov",         "Proventos",         "valor_total_proventos",     "val"),
        ("desc",         "Descontos",         "valor_total_descontos",     "val"),
        ("liq",          "Líquido",           "valor_liquido",             "val"),
        ("base_inss_sl", "B.INSS s/teto",     "valor_base_inss_semlimite", "val"),
        ("base_inss_cl", "B.INSS c/teto",     "valor_base_inss_comlimite", "val"),
        ("inss",         "INSS Ret.",         "valor_inss_retido",         "val"),
        ("base_fgts",    "Base FGTS",         "valor_base_fgts",           "val"),
        ("fgts",         "FGTS",              "valor_fgts",                "val"),
        ("base_irrf_bt", "B.IRRF bruta",      "valor_irrf_basetotal",      "val"),
        ("base_irrf_bk", "B.IRRF tabela",     "valor_irrf_basetabela",     "val"),
        ("ded_dep_irrf", "Ded.Dep.IRRF",      "valor_irrf_dependentes",    "val"),
        ("qtd_dep_irrf", "Qtd.Dep.",          "qtd_irrf_dependentes",      "int"),
        ("salario",      "Sal.nesta Folha",   "valor_salario",             "val"),
    ]
    TOT_BASES_MAP_PDF = {k: (lbl, col, tp) for k, lbl, col, tp in TOT_BASES_PDF}
    tot_fields = [k for k in request.args.getlist("tot_f") if k in TOT_BASES_MAP_PDF]

    def _fval(c):
        if not c: return "—"
        return f"R$ {c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    def _fnum(c):
        if not c: return "—"
        return f"{c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    def _fdata(d):
        s = str(d or "")
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else (s or "—")

    def _dias_ev(ref1, d1i, d1f):
        if ref1:
            return str(ref1)
        try:
            s1 = str(d1i or "").replace("-", "")
            s2 = str(d1f or "").replace("-", "")
            if len(s1) == 8 and len(s2) == 8:
                dt1 = date(int(s1[:4]), int(s1[4:6]), int(s1[6:]))
                dt2 = date(int(s2[:4]), int(s2[4:6]), int(s2[6:]))
                return str((dt2 - dt1).days + 1)
        except Exception:
            pass
        return "—"

    try:
        _always = ["matricula", "nome", "nomer", "situacao"]
        _extra  = [CAD_CAMPOS_MAP[k][1] for k in cad_fields
                   if k in CAD_CAMPOS_MAP and CAD_CAMPOS_MAP[k][1]]
        if "funcao_nome" in cad_fields and "cbofuncao" not in _extra:
            _extra.append("cbofuncao")
        _sel = ", ".join(dict.fromkeys(_always + _extra))
        q = supabase.table("tab_cad").select(_sel).eq("id_empresa", id_empresa).order(order_col)
        if sit != "T":
            q = q.eq("situacao", sit)
        if mat_raw.isdigit():
            q = q.eq("matricula", int(mat_raw))
        funcs = q.execute().data or []
    except Exception:
        funcs = []

    mapa_funcao = {}
    if "funcao_nome" in cad_fields and funcs:
        try:
            cbos = list({str(f.get("cbofuncao") or "").strip() for f in funcs if f.get("cbofuncao")})
            if cbos:
                rc = supabase.table("tab_aux_funcao_total") \
                    .select("cbo_codigo, cbo_nome").in_("cbo_codigo", cbos).execute()
                mapa_funcao = {str(r.get("cbo_codigo") or ""): str(r.get("cbo_nome") or "—")
                               for r in (rc.data or [])}
        except Exception:
            pass

    sec_dep      = request.args.get("sec_dep")      == "1"
    dep_somente  = request.args.get("dep_somente")  == "1"
    dep_tipos    = [t for t in request.args.getlist("dep_tipo") if str(t).isdigit() and 0 < int(t) < 200]
    sec_eventos  = request.args.get("sec_eventos")  == "1"
    ev_tipos     = [t for t in request.args.getlist("ev_tipo") if t in ("3", "6")]
    ev_periodo   = request.args.get("ev_periodo", "todos")

    OP1_LABEL_PDF = {3: "Férias", 6: "Afastamento"}
    ev_por_mat_pdf = {}
    if sec_eventos and ev_tipos and funcs:
        try:
            _mats_ev = [int(f.get("matricula") or 0) for f in funcs]
            _ev_op1  = [int(t) for t in ev_tipos]
            qe = (supabase.table("tab_eventos")
                  .select("matricula, op1, data1i, data1f, ref1, campotxt1")
                  .eq("id_empresa", id_empresa)
                  .in_("op1", _ev_op1))
            if ev_periodo == "mes":
                _d_ini = f"{ano}{mes_ini:02d}01"
                _d_fim = f"{ano}{mes_fim:02d}31"
                qe = qe.gte("data1i", _d_ini).lte("data1i", _d_fim)
            if id_cliente:
                qe = qe.eq("id_cliente", id_cliente)
            for row in (qe.execute().data or []):
                m = int(row.get("matricula") or 0)
                if m in _mats_ev:
                    ev_por_mat_pdf.setdefault(m, []).append(row)
        except Exception:
            pass

    _tdep_pdf = []
    try:
        _r = supabase.table("tab_tabela_total").select("codigo,texto") \
            .eq("num_tabela", 7).neq("codigo", "DOC").order("codigo").execute()
        _tdep_pdf = [{"cod": int(t["codigo"]), "texto": t["texto"]}
                     for t in (_r.data or []) if str(t.get("codigo","")).strip().isdigit()]
    except Exception:
        pass
    TPDEP = ({t["cod"]: t["texto"] for t in _tdep_pdf}
             if _tdep_pdf else {1:"Cônjuge", 3:"Filho(a)/Enteado(a)", 9:"Pais"})
    dep_por_mat = {}
    if sec_dep and funcs:
        try:
            mats_dep = [int(f.get("matricula") or 0) for f in funcs]
            qd = (supabase.table("tab_dependentes")
                  .select("matricula, nome, tpdep, dtnascto, depirrf, depsf")
                  .eq("id_empresa", id_empresa).in_("matricula", mats_dep))
            if id_cliente:
                qd = qd.eq("id_cliente", id_cliente)
            if dep_tipos:
                qd = qd.in_("tpdep", [int(t) for t in dep_tipos])
            for row in (qd.execute().data or []):
                m = int(row.get("matricula") or 0)
                dep_por_mat.setdefault(m, []).append(row)
        except Exception:
            pass

    mov_col_labels_pdf = []
    mov_pivot_por_mat  = {}
    if sec_mov and mov_fields and funcs:
        try:
            _cli_rubr = [0] + ([id_cliente] if id_cliente else [])
            _rub_dsc  = {}
            for _rv in (supabase.table("tab_rubrica")
                        .select("cod_rubr, dsc_rubr")
                        .in_("id_cliente", _cli_rubr).eq("situacao","A")
                        .execute().data or []):
                _rub_dsc[int(_rv.get("cod_rubr") or 0)] = _rv.get("dsc_rubr") or ""
            mov_col_labels_pdf = [f"{c:04d}\n{_rub_dsc.get(c, f'V.{c}')}" for c in mov_fields]
        except Exception:
            mov_col_labels_pdf = [f"V.{c}" for c in mov_fields]
        try:
            _mats_m = [int(f.get("matricula") or 0) for f in funcs]
            _qm = (supabase.table("tab_mov")
                   .select("matricula, cod_verba, valor")
                   .eq("id_empresa", id_empresa).eq("situacao","A")
                   .eq("folha_tipo","N").in_("matricula", _mats_m)
                   .in_("cod_verba", mov_fields)
                   .gte("folha", anomes_ini).lte("folha", anomes_fim))
            if id_cliente:
                _qm = _qm.eq("id_cliente", id_cliente)
            for _mr in (_qm.execute().data or []):
                _m = int(_mr.get("matricula") or 0)
                _c = int(_mr.get("cod_verba") or 0)
                mov_pivot_por_mat.setdefault(_m, {})
                mov_pivot_por_mat[_m][_c] = mov_pivot_por_mat[_m].get(_c, 0) + int(_mr.get("valor") or 0)
        except Exception:
            pass

    tot_col_labels_pdf = []
    tot_pivot_por_mat  = {}
    if sec_totais and tot_fields and funcs:
        tot_col_labels_pdf = [TOT_BASES_MAP_PDF[k][0] for k in tot_fields]
        try:
            _mats_t   = [int(f.get("matricula") or 0) for f in funcs]
            _tot_cols = ", ".join(dict.fromkeys(
                ["matricula"] + [TOT_BASES_MAP_PDF[k][1] for k in tot_fields]
            ))
            _qt = (supabase.table("tab_total")
                   .select(_tot_cols)
                   .eq("id_empresa", id_empresa).in_("matricula", _mats_t)
                   .gte("folha", anomes_ini).lte("folha", anomes_fim))
            if id_cliente:
                _qt = _qt.eq("id_cliente", id_cliente)
            for _tr in (_qt.execute().data or []):
                _m = int(_tr.get("matricula") or 0)
                tot_pivot_por_mat.setdefault(_m, {})
                for k in tot_fields:
                    _col = TOT_BASES_MAP_PDF[k][1]
                    tot_pivot_por_mat[_m][k] = (
                        tot_pivot_por_mat[_m].get(k, 0) + int(_tr.get(_col) or 0)
                    )
        except Exception:
            pass

    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))

    col_labels = (["Matr. / Nome"]
                  + [CAD_CAMPOS_MAP[k][0] for k in cad_fields if k in CAD_CAMPOS_MAP]
                  + mov_col_labels_pdf
                  + tot_col_labels_pdf)

    # ── Larguras inteligentes por conteúdo ──────────────────────────────────
    _W_CAD = {
        "cpf": 2.3, "dtadm": 1.8, "funcao_cbo": 1.8, "funcao_nome": 3.8,
        "vrsalfx": 2.3, "dtnascto": 1.8, "sexo": 0.9, "estadocivil": 2.0,
        "email": 4.0, "telefone": 2.5, "endereco": 5.0, "cidade": 3.0,
        "uf": 0.8, "cep": 1.9, "banco": 1.5, "agencia": 1.5, "conta": 2.0,
    }
    _raw_w = [5.5]                                           # Matr./Nome (cm)
    for k in cad_fields:
        if k in CAD_CAMPOS_MAP:
            _raw_w.append(_W_CAD.get(k, 2.5))
    for _ in mov_fields:
        _raw_w.append(2.3)                                   # verba monetária
    for k in tot_fields:
        _raw_w.append(1.3 if TOT_BASES_MAP_PDF.get(k, ("","","val"))[2] == "int" else 2.3)

    page       = landscape(A4)
    page_w     = page[0] - 3*cm
    _pw_cm     = page_w / cm
    _total_raw = sum(_raw_w)
    if _total_raw > _pw_cm:
        _scale = _pw_cm / _total_raw
        col_widths = [w * _scale * cm for w in _raw_w]
    else:
        col_widths = [w * cm for w in _raw_w]
    n_cols = len(col_labels)

    navy = colors.HexColor("#0b1f3a")
    gray = colors.HexColor("#f8fafc")
    bdr  = colors.HexColor("#dde3ec")
    dep_bg = colors.HexColor("#f1f5f9")

    st_hdr      = ParagraphStyle("hdr", fontName="Helvetica-Bold", fontSize=7, textColor=colors.HexColor("#1e293b"),       leading=9)
    st_cel      = ParagraphStyle("cel", fontName="Helvetica",      fontSize=7, textColor=colors.HexColor("#1e293b"),       leading=9)
    st_tot      = ParagraphStyle("tot", fontName="Helvetica-Bold", fontSize=7, textColor=colors.HexColor("#1e293b"),       leading=9)
    st_dep_hdr  = ParagraphStyle("dh",  fontName="Helvetica-Bold", fontSize=6, textColor=colors.HexColor("#475569"),       leading=8)
    st_dep_cel  = ParagraphStyle("dc",  fontName="Helvetica",      fontSize=6, textColor=colors.HexColor("#374151"),       leading=8)
    st_dep_none = ParagraphStyle("dn",  fontName="Helvetica-Oblique", fontSize=6, textColor=colors.HexColor("#94a3b8"),    leading=8)
    st_ev_hdr   = ParagraphStyle("eh",  fontName="Helvetica-Bold", fontSize=6, textColor=colors.HexColor("#166534"),       leading=8)
    st_ev_cel   = ParagraphStyle("ec",  fontName="Helvetica",      fontSize=6, textColor=colors.HexColor("#374151"),       leading=8)

    tbl_data  = [[Paragraph(h, st_hdr) for h in col_labels]]
    row_types = ["header"]
    emp_alt   = 0

    for f in funcs:
        mat  = int(f.get("matricula") or 0)
        if dep_somente and sec_dep and not dep_por_mat.get(mat):
            continue
        nome = (f.get("nomer") or f.get("nome") or "").strip()
        row  = [f"{mat:06d}  {nome}"]
        for k in cad_fields:
            if k not in CAD_CAMPOS_MAP:
                continue
            lbl, col, tp = CAD_CAMPOS_MAP[k]
            raw = f.get(col)
            if tp == "val":
                disp = _fval(raw)
            elif tp == "data":
                disp = _fdata(raw)
            elif tp == "lookup_funcao":
                cbo  = str(f.get("cbofuncao") or "").strip()
                disp = mapa_funcao.get(cbo, "—")
            else:
                disp = str(raw or "—")
            row.append(disp)
        _pivot = mov_pivot_por_mat.get(mat, {})
        for _mc in mov_fields:
            row.append(_fnum(_pivot.get(_mc)))
        _tpivot = tot_pivot_por_mat.get(mat, {})
        for k in tot_fields:
            _, _, _tp = TOT_BASES_MAP_PDF[k]
            _v = _tpivot.get(k, 0)
            row.append(str(_v) if _tp == "int" else _fnum(_v))
        tbl_data.append([Paragraph(str(v), st_cel) for v in row])
        row_types.append(("emp", emp_alt % 2))
        emp_alt += 1

        if sec_dep:
            deps = dep_por_mat.get(mat, [])
            if deps:
                dep_col_ws = [col_nome * 1.2, 1.8*cm, 1.6*cm, 1.0*cm, 1.0*cm]
                nd = [[Paragraph(h, st_dep_hdr) for h in ["Nome", "Parentesco", "Nasc.", "IRRF", "Saúde"]]]
                for d in deps:
                    nd.append([
                        Paragraph(str(d.get("nome") or "—"), st_dep_cel),
                        Paragraph(TPDEP.get(int(d.get("tpdep") or 0), "Outro"), st_dep_cel),
                        Paragraph(_fdata(d.get("dtnascto")), st_dep_cel),
                        Paragraph("Sim" if d.get("depirrf") else "Não", st_dep_cel),
                        Paragraph("Sim" if d.get("depsf")   else "Não", st_dep_cel),
                    ])
                nested = Table(nd, colWidths=dep_col_ws)
                nested.setStyle(TableStyle([
                    ("LINEBELOW",     (0,0), (-1,0), 0.3, colors.HexColor("#e2e8f0")),
                    ("TOPPADDING",    (0,0), (-1,-1), 2),
                    ("BOTTOMPADDING", (0,0), (-1,-1), 2),
                    ("LEFTPADDING",   (0,0), (-1,-1), 0),
                    ("RIGHTPADDING",  (0,0), (-1,-1), 6),
                ]))
                tbl_data.append([nested] + [""] * (n_cols - 1))
            else:
                tbl_data.append([Paragraph("sem dependentes", st_dep_none)] + [""] * (n_cols - 1))
            row_types.append("dep")

        if sec_eventos and ev_tipos:
            evs = sorted(ev_por_mat_pdf.get(mat, []), key=lambda x: (x.get("data1i") or ""))
            if evs:
                ev_col_ws = [2.0*cm, 2.0*cm, 2.0*cm, 1.2*cm, 4.0*cm]
                nd_ev = [[Paragraph(h, st_ev_hdr) for h in ["Tipo", "Início", "Fim", "Dias", "Obs."]]]
                for ev in evs:
                    nd_ev.append([
                        Paragraph(OP1_LABEL_PDF.get(int(ev.get("op1") or 0), "Evento"), st_ev_cel),
                        Paragraph(_fdata(ev.get("data1i")), st_ev_cel),
                        Paragraph(_fdata(ev.get("data1f")), st_ev_cel),
                        Paragraph(_dias_ev(ev.get("ref1"), ev.get("data1i"), ev.get("data1f")), st_ev_cel),
                        Paragraph(str(ev.get("campotxt1") or "—"), st_ev_cel),
                    ])
                nested_ev = Table(nd_ev, colWidths=ev_col_ws)
                nested_ev.setStyle(TableStyle([
                    ("LINEBELOW",     (0,0), (-1,0), 0.3, colors.HexColor("#bbf7d0")),
                    ("TOPPADDING",    (0,0), (-1,-1), 2),
                    ("BOTTOMPADDING", (0,0), (-1,-1), 2),
                    ("LEFTPADDING",   (0,0), (-1,-1), 0),
                    ("RIGHTPADDING",  (0,0), (-1,-1), 6),
                ]))
                tbl_data.append([nested_ev] + [""] * (n_cols - 1))
                row_types.append("ev")

    total_txt = f"Total: {len(funcs)} funcionário{'s' if len(funcs) != 1 else ''}"
    tbl_data.append([Paragraph(total_txt, st_tot)] + [""] * (n_cols - 1))
    row_types.append("total")
    last = len(tbl_data) - 1

    style_cmds = [
        ("BACKGROUND", (0, 0),    (-1, 0),    colors.HexColor("#eaf1fb")),
        ("LINEBELOW",  (0, 0),    (-1, 0),    0.5, bdr),
        ("SPAN",       (0, last), (-1, last)),
        ("BACKGROUND", (0, last), (-1, last), gray),
        ("LINEABOVE",  (0, last), (-1, last), 1, bdr),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING",    (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
        ("LEFTPADDING",   (0, 0), (-1, -1), 4),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 4),
    ]
    for i, rt in enumerate(row_types):
        if isinstance(rt, tuple) and rt[0] == "emp":
            bg = colors.white if rt[1] == 0 else gray
            style_cmds += [("BACKGROUND", (0,i), (-1,i), bg),
                           ("GRID",       (0,i), (-1,i), 0.4, bdr)]
        elif rt == "dep":
            style_cmds += [("SPAN",          (0,i), (-1,i)),
                           ("LEFTPADDING",   (0,i), (-1,i), 18),
                           ("TOPPADDING",    (0,i), (-1,i), 2),
                           ("BOTTOMPADDING", (0,i), (-1,i), 4)]
        elif rt == "ev":
            style_cmds += [("SPAN",          (0,i), (-1,i)),
                           ("BACKGROUND",    (0,i), (-1,i), colors.HexColor("#f0fdf4")),
                           ("LEFTPADDING",   (0,i), (-1,i), 18),
                           ("TOPPADDING",    (0,i), (-1,i), 2),
                           ("BOTTOMPADDING", (0,i), (-1,i), 4)]

    t = Table(tbl_data, colWidths=col_widths, repeatRows=1)
    t.setStyle(TableStyle(style_cmds))

    # linha de cabeçalho do doc (empresa + título + data)
    titulo_pdf = titulo_rel if titulo_rel else "Gerador de Relatório — Cadastro"
    cabecalho  = _pdf_cabecalho(titulo_pdf, cnpj_fmt, empresa_nm, page_width=page_w)

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=page,
                            leftMargin=1.5*cm, rightMargin=1.5*cm,
                            topMargin=1.2*cm, bottomMargin=1.2*cm)
    doc.build([cabecalho, Spacer(1, 0.4*cm), t])

    from flask import make_response
    buf.seek(0)
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = 'inline; filename="GeradorRelatorio.pdf"'
    return resp


@app.route("/api/gerador_verbas_usadas")
def api_gerador_verbas_usadas():
    if not session.get("logado"):
        return jsonify({"ok": False})
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    ano     = int(request.args.get("ano",     datetime.now().year)  or datetime.now().year)
    mes_ini = int(request.args.get("mes_ini", 1)  or 1)
    mes_fim = int(request.args.get("mes_fim", 12) or 12)
    todas   = request.args.get("todas", "0") == "1"

    _cli_rubr = [0] + ([id_cliente] if id_cliente else [])
    try:
        _q_rubr = (supabase.table("tab_rubrica")
                   .select("cod_rubr, dsc_rubr")
                   .in_("id_cliente", _cli_rubr)
                   .eq("situacao", "A").order("cod_rubr"))

        filtrado = False
        if not todas:
            _anomes_ini = int(f"{ano}{mes_ini:02d}")
            _anomes_fim = int(f"{ano}{mes_fim:02d}")
            _qm = (supabase.table("tab_mov")
                   .select("cod_verba")
                   .eq("id_empresa", id_empresa)
                   .eq("situacao", "A").eq("folha_tipo", "N")
                   .gte("folha", _anomes_ini).lte("folha", _anomes_fim))
            if id_cliente:
                _qm = _qm.eq("id_cliente", id_cliente)
            _cod_usados = {int(r["cod_verba"])
                           for r in (_qm.execute().data or []) if r.get("cod_verba")}
            if _cod_usados:
                _q_rubr = _q_rubr.in_("cod_rubr", list(_cod_usados))
                filtrado = True

        verbas = _q_rubr.execute().data or []
        for v in verbas:
            v["cod_rubr"] = int(v.get("cod_rubr") or 0)
        return jsonify({"ok": True, "verbas": verbas, "filtrado": filtrado})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


