@app.route("/cad_aviso_previo")
def cad_aviso_previo():
    if not session.get("logado"):
        return redirect("/")

    from datetime import date as _date, timedelta as _td

    mat_raw = request.args.get("mats", request.args.get("mat", "")).strip()
    mat_int = int(mat_raw.split(",")[0]) if mat_raw and mat_raw.split(",")[0].isdigit() else None

    funcionario = None
    if mat_int:
        id_empresa = _get_id_empresa()
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula, nome, dtadm, vrsalfx")
                 .eq("id_empresa", id_empresa)
                 .eq("matricula", mat_int)
                 .limit(1)
                 .execute())
            if r.data:
                f = r.data[0]
                sal   = f.get("vrsalfx") or 0
                dtadm = f.get("dtadm")
                s = str(dtadm or "").zfill(8)
                dtadm_fmt = f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"
                sal_fmt = ("R$ " + f"{sal/100:,.2f}"
                           .replace(",","X").replace(".",",").replace("X","."))
                anos = 0
                if len(s) == 8:
                    try:
                        adm_d = _date(int(s[:4]), int(s[4:6]), int(s[6:8]))
                        anos  = (_date.today() - adm_d).days // 365
                    except Exception:
                        pass
                prazo = min(30 + anos * 3, 90)
                funcionario = {
                    "matricula": mat_int,
                    "mat_fmt":   str(mat_int).zfill(6),
                    "nome":      f.get("nome", ""),
                    "dtadm_fmt": dtadm_fmt,
                    "sal_fmt":   sal_fmt,
                    "anos":      anos,
                    "prazo":     prazo,
                }
        except Exception:
            pass

    # Verifica se já existe aviso prévio gravado para este funcionário
    ja_tem_aviso = False
    if funcionario:
        try:
            r_av = (supabase.table("tab_eventos")
                    .select("id")
                    .eq("id_empresa", _get_id_empresa())
                    .eq("matricula", mat_int)
                    .eq("op1", 9)
                    .limit(1)
                    .execute())
            ja_tem_aviso = bool(r_av.data)
        except Exception:
            pass

    hoje        = _date.today().strftime("%Y-%m-%d")
    anomes      = str(session.get("anomes_atual") or "")
    folha_ym    = f"{anomes[:4]}-{anomes[4:6]}" if len(anomes) == 6 else ""
    folha_fmt   = f"{anomes[4:6]}/{anomes[:4]}"  if len(anomes) == 6 else ""
    # Se vier de volta da tela 2, restaura os campos
    p_data_aviso    = request.args.get("data_aviso",    hoje)
    p_tipo_aviso    = request.args.get("tipo_aviso",    "T")
    p_quem_aviso    = request.args.get("quem_aviso",    "E")
    p_cond_especial = request.args.get("cond_especial", "N")

    return render_template(
        "F10_Cad_AvisoPrevio.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        funcionario=funcionario,
        ja_tem_aviso=ja_tem_aviso,
        mat_raw=mat_raw,
        data_hoje=p_data_aviso,
        p_tipo_aviso=p_tipo_aviso,
        p_quem_aviso=p_quem_aviso,
        p_cond_especial=p_cond_especial,
        folha_ym=folha_ym,
        folha_fmt=folha_fmt,
    )


@app.route("/cad_aviso_previo2", methods=["GET", "POST"])
def cad_aviso_previo2():
    if not session.get("logado"):
        return redirect("/")

    from datetime import date as _date, timedelta as _td

    mat_raw       = request.args.get("mat", "").strip()
    data_aviso    = request.args.get("data_aviso", "").strip()     # YYYY-MM-DD
    tipo_aviso    = request.args.get("tipo_aviso", "T").strip()    # T/I
    quem_aviso    = request.args.get("quem_aviso", "E").strip()    # E/F/A
    cond_especial = request.args.get("cond_especial", "N").strip() # N/J/T/F

    mat_int = int(mat_raw) if mat_raw.isdigit() else None

    # ── Buscar funcionário ──
    funcionario  = None
    prazo_normal = 15 if quem_aviso == "A" else 30  # 1º AP: 15 dias se Acordo, 30 nos demais
    prazo_lei    = 0
    if mat_int:
        id_empresa = _get_id_empresa()
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula, nome, dtadm, vrsalfx")
                 .eq("id_empresa", id_empresa)
                 .eq("matricula", mat_int)
                 .limit(1)
                 .execute())
            if r.data:
                f = r.data[0]
                sal   = f.get("vrsalfx") or 0
                dtadm = f.get("dtadm")
                s = str(dtadm or "").zfill(8)
                dtadm_fmt = f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"
                sal_fmt = "R$ " + f"{sal/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")
                anos = 0
                if len(s) == 8:
                    try:
                        adm_d = _date(int(s[:4]), int(s[4:6]), int(s[6:8]))
                        anos  = (_date.today() - adm_d).days // 365
                    except Exception:
                        pass
                prazo_lei = min(anos * 3, 60)  # 2º AP: 3 dias/ano, máx 60, convertido em $
                funcionario = {
                    "matricula": mat_int,
                    "mat_fmt":   str(mat_int).zfill(6),
                    "nome":      f.get("nome", ""),
                    "dtadm_fmt": dtadm_fmt,
                    "sal_fmt":   sal_fmt,
                    "anos":      anos,
                    "dtadm_raw": s,
                }
        except Exception:
            pass

    # ── Processar gravação (POST) ──
    if request.method == "POST":
        tipo_aviso_post = request.form.get("tipo_aviso", tipo_aviso)  # prefere form body
        data_fim        = request.form.get("data_fim", "")

        if not funcionario or not data_aviso:
            return redirect("/menu")

        id_cliente = session.get("id_cliente")
        id_empresa = _get_id_empresa()
        anomes_int = session.get("anomes_atual")

        def _dt_to_int(s_date):
            try:
                return int("".join(s_date.split("-")))
            except Exception:
                return None

        data_aviso_int = _dt_to_int(data_aviso)

        quem_map = {"E": "Empresa", "F": "Funcionário", "A": "Acordo"}
        tipo_map = {"T": "Trabalhado", "I": "Indenizado"}
        cond_map = {"J": "Justa Causa", "T": "Contrato Temporário", "F": "Falecimento"}

        campotxt1 = tipo_map.get(tipo_aviso_post, "Trabalhado")
        campotxt2 = quem_map.get(quem_aviso, "Empresa")
        campotxt3 = cond_map.get(cond_especial) or None  # None se sem condição especial

        data_aviso_br = f"{data_aviso[8:10]}/{data_aviso[5:7]}/{data_aviso[:4]}"
        obs = f"Aviso Prévio {campotxt2}: {campotxt1}, Data: {data_aviso_br}"
        if campotxt3:
            obs += f", {campotxt3}"

        try:
            supabase.table("tab_eventos").insert({
                "id_cliente": id_cliente,
                "id_empresa": id_empresa,
                "matricula":  mat_int,
                "folha":      int(anomes_int),
                "op1":        9,
                "op2":        0,
                "data1i":     data_aviso_int,
                "ref1":       prazo_normal,
                "ref2":       prazo_lei,
                "campotxt1":  campotxt1,
                "campotxt2":  campotxt2,
                "campotxt3":  campotxt3,
            }).execute()
        except Exception as e:
            gravar_log("AVISO-ERRO", str(e)[:200], matricula=mat_int)
            return redirect("/menu")

        gravar_log("AVISO-PREVIO", obs, matricula=mat_int)

        return redirect(f"/cad_aviso_previo2_ok?mat={mat_int}&quem={quem_aviso}"
                        f"&tipo={tipo_aviso_post}&data_aviso={data_aviso}"
                        f"&data_fim={data_fim}&prazo={prazo_normal}")

    # ── Calcular datas usando apenas o 1º AP (prazo_normal) ──
    data_inicio_fmt = ""
    data_fim_fmt    = ""
    data_inicio_val = ""
    data_fim_val    = ""
    try:
        d_av  = _date.fromisoformat(data_aviso)
        d_ini = d_av + _td(days=1)
        d_fim = d_ini + _td(days=prazo_normal - 1)
        data_inicio_fmt = d_ini.strftime("%d/%m/%Y")
        data_fim_fmt    = d_fim.strftime("%d/%m/%Y")
        data_inicio_val = d_ini.isoformat()
        data_fim_val    = d_fim.isoformat()
    except Exception:
        pass

    data_aviso_fmt = ""
    try:
        data_aviso_fmt = _date.fromisoformat(data_aviso).strftime("%d/%m/%Y")
    except Exception:
        pass

    quem_desc = {"E": "Empresa (demissão sem justa causa)",
                 "F": "Funcionário (pedido de demissão)",
                 "A": "Acordo (Lei 13.467/2017)"}

    return render_template(
        "F10_Cad_AvisoPrevio2.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        funcionario=funcionario,
        data_aviso=data_aviso,
        data_aviso_fmt=data_aviso_fmt,
        tipo_aviso=tipo_aviso,
        quem_aviso=quem_aviso,
        cond_especial=cond_especial,
        quem_desc=quem_desc.get(quem_aviso, "—"),
        data_inicio_fmt=data_inicio_fmt,
        data_fim_fmt=data_fim_fmt,
        data_inicio_val=data_inicio_val,
        data_fim_val=data_fim_val,
        prazo_normal=prazo_normal,
        prazo_lei=prazo_lei,
    )


@app.route("/cad_aviso_previo2_ok")
def cad_aviso_previo2_ok():
    if not session.get("logado"):
        return redirect("/")

    mat_raw    = request.args.get("mat", "")
    quem       = request.args.get("quem", "E")
    tipo       = request.args.get("tipo", "T")
    data_aviso = request.args.get("data_aviso", "")
    data_fim   = request.args.get("data_fim", "")
    prazo      = request.args.get("prazo", "30")

    def _fmt(s_iso):
        try:
            from datetime import date as _date
            return _date.fromisoformat(s_iso).strftime("%d/%m/%Y")
        except Exception:
            return s_iso

    quem_desc = {"E": "Empresa", "F": "Funcionário", "A": "Acordo"}
    tipo_desc = {"T": "Trabalhado", "I": "Indenizado"}

    return render_template(
        "F10_Cad_AvisoPrevio2_OK.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        mat=mat_raw,
        mat_fmt=str(mat_raw).zfill(6),
        quem_desc=quem_desc.get(quem, quem),
        tipo_desc=tipo_desc.get(tipo, tipo),
        data_aviso_fmt=_fmt(data_aviso),
        data_fim_fmt=_fmt(data_fim),
        prazo=prazo,
    )


# =========================================================
# CANCELAR AVISO PRÉVIO
# Só é cancelável o aviso registrado no mês da folha ATUAL
# (tab_eventos.folha == anomes_atual). Aviso prévio não tem
# layout no eSocial — nada a desfazer lá.
# =========================================================
@app.route("/api/funcionarios_com_aviso_cancelavel")
def api_funcionarios_com_aviso_cancelavel():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    if not anomes:
        return jsonify({"ok": True, "funcionarios": []})
    try:
        # Matrículas com aviso prévio (op1=9) registrado NESTA folha (mês atual)
        r_ev = (supabase.table("tab_eventos")
                .select("matricula")
                .eq("id_empresa", id_empresa)
                .eq("op1", 9)
                .eq("folha", int(anomes))
                .execute())
        mats = list({int(row["matricula"]) for row in (r_ev.data or [])
                     if row.get("matricula") is not None})
        if not mats:
            return jsonify({"ok": True, "funcionarios": []})
        r = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, dtadm, situacao, codcateg, cbofuncao")
             .eq("id_empresa", id_empresa)
             .in_("matricula", mats)
             .order("matricula")
             .execute())
        funcionarios = []
        for f in (r.data or []):
            nome = (f.get("nomer") or f.get("nome") or "").strip()
            funcionarios.append({
                "matricula": f.get("matricula"),
                "nome":      nome,
                "dtadm":     str(f.get("dtadm") or ""),
                "situacao":  str(f.get("situacao") or ""),
                "codcateg":  str(f.get("codcateg") or ""),
                "cbofuncao": str(f.get("cbofuncao") or ""),
            })
        return jsonify({"ok": True, "funcionarios": funcionarios})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


@app.route("/cancelar_aviso_previo", methods=["GET", "POST"])
def cancelar_aviso_previo():
    if not session.get("logado"):
        return redirect("/")
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    folha_fmt  = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else ""

    mat_raw = (request.args.get("mats") or request.args.get("mat") or "").strip()
    mat_str = mat_raw.split(",")[0].strip()
    if not mat_str.isdigit():
        return redirect("/select_funcionario?contexto=cancelar_aviso_previo")
    mat_int = int(mat_str)

    # ── POST: efetiva o cancelamento (deleta op1=9 do mês atual) ──
    if request.method == "POST":
        if not anomes:
            return redirect("/menu")
        nome_func = ""
        try:
            r_n = (supabase.table("tab_cad").select("nome, nomer")
                   .eq("id_empresa", id_empresa).eq("matricula", mat_int).limit(1).execute())
            if r_n.data:
                nome_func = (r_n.data[0].get("nomer") or r_n.data[0].get("nome") or "").strip()
        except Exception:
            pass
        try:
            (supabase.table("tab_eventos").delete()
             .eq("id_empresa", id_empresa).eq("matricula", mat_int)
             .eq("op1", 9).eq("folha", int(anomes)).execute())
        except Exception as e:
            gravar_log("AVISO-CAN-ER", str(e)[:200], matricula=mat_int)
            return redirect(f"/cancelar_aviso_previo?mats={mat_int}&erro=1")
        gravar_log("AVISO-CANCEL",
                   f"Aviso prévio cancelado (folha {anomes}): {nome_func}", matricula=mat_int)
        return redirect(f"/cancelar_aviso_previo?mats={mat_int}&ok=1")

    # ── GET: funcionário + aviso cancelável (deste mês) ──
    funcionario = None
    try:
        r = (supabase.table("tab_cad").select("matricula, nome, nomer, situacao")
             .eq("id_empresa", id_empresa).eq("matricula", mat_int).limit(1).execute())
        if r.data:
            f = r.data[0]
            funcionario = {
                "matricula": mat_int,
                "mat_fmt":   str(mat_int).zfill(6),
                "nome":      (f.get("nomer") or f.get("nome") or "").strip(),
                "situacao":  str(f.get("situacao") or ""),
            }
    except Exception:
        pass

    aviso = None
    if anomes:
        try:
            r_ev = (supabase.table("tab_eventos")
                    .select("data1i, campotxt1, campotxt2, campotxt3")
                    .eq("id_empresa", id_empresa).eq("matricula", mat_int)
                    .eq("op1", 9).eq("folha", int(anomes))
                    .order("data1i", desc=True).limit(1).execute())
            if r_ev.data:
                ev = r_ev.data[0]
                d = int(ev.get("data1i") or 0)
                data_fmt = ""
                if d > 0:
                    s = f"{d:08d}"
                    data_fmt = f"{s[6:8]}/{s[4:6]}/{s[0:4]}"
                aviso = {
                    "data_fmt": data_fmt,
                    "tipo":     ev.get("campotxt1") or "",
                    "quem":     ev.get("campotxt2") or "",
                    "cond":     ev.get("campotxt3") or "",
                }
        except Exception:
            aviso = None

    return render_template(
        "F10_Cancelar_AvisoPrevio.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        funcionario=funcionario,
        aviso=aviso,
        folha_fmt=folha_fmt,
        ok=request.args.get("ok"),
        erro=request.args.get("erro"),
    )


def _lista_aviso_previo_dados(id_empresa):
    """Funcionários ATIVOS com aviso prévio (op1=9, qualquer mês). Retorna lista
    ordenada por nome, com data/competência/quem/tipo do aviso mais recente."""
    aviso_info = {}
    try:
        r = (supabase.table("tab_eventos")
             .select("matricula, data1i, folha, campotxt1, campotxt2")
             .eq("id_empresa", id_empresa).eq("op1", 9)
             .order("data1i", desc=True).execute())
        for row in (r.data or []):
            m = row.get("matricula")
            if m is None:
                continue
            m = int(m)
            if m in aviso_info:
                continue  # já pegou o mais recente (ordenado desc)
            d = int(row.get("data1i") or 0)
            data_fmt = f"{d:08d}"[6:8] + "/" + f"{d:08d}"[4:6] + "/" + f"{d:08d}"[0:4] if d > 0 else ""
            fol = row.get("folha")
            folha_fmt = ""
            if fol:
                fs = f"{int(fol):06d}"
                if len(fs) == 6:
                    folha_fmt = f"{fs[4:6]}/{fs[0:4]}"
            aviso_info[m] = {
                "data_fmt":  data_fmt,
                "folha_fmt": folha_fmt,
                "quem":      row.get("campotxt2") or "",
                "tipo":      row.get("campotxt1") or "",
            }
    except Exception:
        aviso_info = {}

    funcs = []
    if aviso_info:
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, situacao")
                 .eq("id_empresa", id_empresa).eq("situacao", "A")
                 .in_("matricula", list(aviso_info.keys()))
                 .order("nome").execute())
            for f in (r.data or []):
                m = int(f.get("matricula") or 0)
                info = aviso_info.get(m, {})
                funcs.append({
                    "matricula": m,
                    "mat_fmt":   f"{m:06d}",
                    "nome":      (f.get("nome") or f.get("nomer") or "").strip(),   # nome completo
                    "data_fmt":  info.get("data_fmt", ""),
                    "folha_fmt": info.get("folha_fmt", ""),
                    "quem":      info.get("quem", ""),
                    "tipo":      info.get("tipo", ""),
                })
        except Exception:
            funcs = []
    return funcs


@app.route("/lista_aviso_previo")
def lista_aviso_previo():
    """Listagem de funcionários atualmente em aviso prévio: todos com op1=9
    (qualquer mês) que ainda estão ATIVOS (não desligados)."""
    if not session.get("logado"):
        return redirect("/")
    funcs = _lista_aviso_previo_dados(_get_id_empresa())
    return render_template("F10_Lista_AvisoPrevio.html", **_ctx_relatorio(), funcs=funcs)


@app.route("/lista_aviso_previo_pdf")
def lista_aviso_previo_pdf():
    if not session.get("logado"):
        return redirect("/")

    from io import BytesIO
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle

    id_empresa = _get_id_empresa()
    funcs      = _lista_aviso_previo_dados(id_empresa)
    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))
    titulo     = "Funcionários em Aviso Prévio"

    def P(txt, fn="Helvetica", fs=8, align=0, col=colors.HexColor("#1f2937")):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, alignment=align,
                            textColor=col, leading=fs + 2)
        return Paragraph(str(txt), st)

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=2*cm, rightMargin=2*cm,
                            topMargin=1.5*cm, bottomMargin=1.5*cm)

    cab = ["Matrícula", "Nome", "Data do Aviso", "Competência", "Quem deu", "Tipo"]
    tbl_data = [[P(h, fn="Helvetica-Bold") for h in cab]]
    lt_gray  = colors.HexColor("#f8fafc")
    for f in funcs:
        tbl_data.append([
            P(f["mat_fmt"], fn="Courier"),
            P(f["nome"]),
            P(f.get("data_fmt") or "—", align=1),
            P(f.get("folha_fmt") or "—", align=1),
            P(f.get("quem") or "—", align=1),
            P(f.get("tipo") or "—", align=1),
        ])

    tbl = Table(tbl_data, colWidths=[2.0*cm, 6.8*cm, 2.4*cm, 2.2*cm, 2.0*cm, 1.6*cm], repeatRows=1)
    row_bg = [("BACKGROUND", (0, i), (-1, i), lt_gray if i % 2 == 0 else colors.white)
              for i in range(1, len(tbl_data))]
    tbl.setStyle(TableStyle([
        ("BACKGROUND",    (0, 0), (-1, 0), colors.HexColor("#eaf1fb")),
        ("LINEBELOW",     (0, 0), (-1, 0), 0.5, colors.HexColor("#dbe3ee")),
        ("LINEBELOW",     (0, 1), (-1, -1), 0.3, colors.HexColor("#f1f5f9")),
        ("TOPPADDING",    (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
        ("LEFTPADDING",   (0, 0), (-1, -1), 4),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 4),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
    ] + row_bg))

    total_linha = P(f"Total: {len(funcs)} funcionário(s) em aviso prévio", fn="Helvetica", fs=8,
                    col=colors.HexColor("#64748b"), align=2)
    story = [_pdf_cabecalho(titulo, cnpj_fmt, empresa_nm, data_label="Emitido em"),
             Spacer(1, 8), tbl, Spacer(1, 6), total_linha]
    doc.build(story, onFirstPage=_pdf_num_pagina, onLaterPages=_pdf_num_pagina)
    buf.seek(0)

    from flask import make_response
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = 'inline; filename="FuncionariosAvisoPrevio.pdf"'
    return resp


# =========================================================
# LISTAGEM DOS DEMITIDOS (filtro por data de demissão)
# =========================================================
def _mes_atual_intervalo():
    """(data_ini, data_fim) em YYYY-MM-DD: 1º ao último dia do mês da folha ativa
    (ou do mês corrente se não houver folha)."""
    import calendar
    anomes = str(session.get("anomes_atual") or "")
    if len(anomes) == 6 and anomes.isdigit():
        y, m = int(anomes[:4]), int(anomes[4:6])
    else:
        now = datetime.now()
        y, m = now.year, now.month
    last = calendar.monthrange(y, m)[1]
    return f"{y:04d}-{m:02d}-01", f"{y:04d}-{m:02d}-{last:02d}"


def _lista_demitidos_dados(id_empresa, ini_int, fim_int):
    """Desligados (situacao='D') com datarescisao no intervalo [ini_int, fim_int]
    (YYYYMMDD int). Ordenado por data de demissão."""
    funcs = []
    try:
        q = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, dtadm, datarescisao, motrescisao")
             .eq("id_empresa", id_empresa).eq("situacao", "D"))
        if ini_int:
            q = q.gte("datarescisao", ini_int)
        if fim_int:
            q = q.lte("datarescisao", fim_int)
        rows = q.order("datarescisao").execute().data or []
        for f in rows:
            dr = str(f.get("datarescisao") or "")
            da = str(f.get("dtadm") or "")
            m  = int(f.get("matricula") or 0)
            funcs.append({
                "matricula": m,
                "mat_fmt":   f"{m:06d}",
                "nome":      (f.get("nome") or f.get("nomer") or "").strip(),   # nome completo
                "adm_fmt":   f"{da[6:8]}/{da[4:6]}/{da[0:4]}" if len(da) == 8 and da.isdigit() else "—",
                "dem_fmt":   f"{dr[6:8]}/{dr[4:6]}/{dr[0:4]}" if len(dr) == 8 and dr.isdigit() else "—",
                "adm_raw":   da,
                "dem_raw":   dr,
                "motivo":    str(f.get("motrescisao") or ""),
            })
    except Exception:
        funcs = []
    return funcs


def _demitidos_intervalo_args():
    """Lê data_ini/data_fim da query (default = mês atual) e retorna
    (data_ini, data_fim, ini_int, fim_int)."""
    def_ini, def_fim = _mes_atual_intervalo()
    data_ini = request.args.get("data_ini") or def_ini
    data_fim = request.args.get("data_fim") or def_fim
    def _to_int(d):
        d = (d or "").replace("-", "")
        return int(d) if len(d) == 8 and d.isdigit() else None
    return data_ini, data_fim, _to_int(data_ini), _to_int(data_fim)


@app.route("/lista_demitidos")
def lista_demitidos():
    if not session.get("logado"):
        return redirect("/")
    data_ini, data_fim, ini_int, fim_int = _demitidos_intervalo_args()
    funcs = _lista_demitidos_dados(_get_id_empresa(), ini_int, fim_int)
    return render_template("F10_Lista_Demitidos.html", **_ctx_relatorio(),
                           funcs=funcs, data_ini=data_ini, data_fim=data_fim)


