@app.route("/cad_rescisao_ok")
def cad_rescisao_ok():
    if not session.get("logado"):
        return redirect("/")

    mat_raw        = request.args.get("mat", "").strip()
    data_demissao  = request.args.get("data_demissao", "").strip()

    def _fmt(s_iso):
        try:
            from datetime import date as _date
            return _date.fromisoformat(s_iso).strftime("%d/%m/%Y")
        except Exception:
            return s_iso

    id_empresa = _get_id_empresa()
    nome_func  = ""
    try:
        mat_int = int(mat_raw)
        r = (supabase.table("tab_cad")
             .select("nome, nomer")
             .eq("id_empresa", id_empresa)
             .eq("matricula", mat_int)
             .limit(1)
             .execute())
        if r.data:
            nome_func = (r.data[0].get("nomer") or r.data[0].get("nome") or "").strip()
    except Exception:
        mat_int = 0

    return render_template(
        "F10_Cad_Rescisao_OK.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        mat=mat_raw,
        mat_fmt=str(mat_raw).zfill(6),
        nome_func=nome_func,
        data_demissao_fmt=_fmt(data_demissao),
    )


# =========================================================
# CANCELAR RESCISÃO
# Só permitido se o S-1299 do período NÃO estiver ativo — ou seja, não enviado,
# ou enviado e depois EXCLUÍDO por um S-3000. Cancelar não gera evento eSocial;
# apenas reverte o tab_cad e remove o S-2299 ainda pendente (não enviado).
# =========================================================
def _s1299_ativo(id_empresa, ano_mes, folha_tipo):
    """True se há um S-1299 ATIVO (enviado com recibo e não excluído por S-3000)
    para o período (ano_mes + folha_tipo). Bloqueia o cancelamento da rescisão."""
    if not ano_mes:
        return False
    try:
        rows = (supabase.table("tab_esocial")
                .select("recibo, observacao_erro")
                .eq("id_empresa", id_empresa)
                .eq("layout", "1299")
                .eq("ano_mes", int(ano_mes))
                .eq("folha_tipo", str(folha_tipo or "N"))
                .not_.is_("recibo", "null")
                .neq("recibo", "")
                .execute().data or [])
        for r in rows:
            if (r.get("observacao_erro") or "").strip().upper() != "EXCLUIDO":
                return True   # há um S-1299 vigente para o período
        return False
    except Exception:
        return False


def _gravar_ou_atualizar_s2299(id_empresa, id_cliente, mat_int, anomes_am, folha_tipo_es,
                               codcateg=None):
    """Grava (ou atualiza) o evento de término na tab_esocial no momento do
    CÁLCULO da rescisão. Empregado (S-2200) → layout S-2299; não-empregado /
    TSVE (721/722/723/901, ligado ao S-2300) → layout S-2399. Se já existe um
    registro do funcionário ainda SEM recibo (não enviado) e não EXCLUÍDO,
    apenas atualiza data/hora — não duplica. Só cria um novo quando não há
    nenhum pendente."""
    from datetime import datetime as _dt
    try:
        _categ_n = int(str(codcateg or "0").strip())
    except (ValueError, TypeError):
        _categ_n = 0
    layout = "2399" if _categ_n in (721, 722, 723, 901) else "2299"
    agora_es    = _dt.now()
    ano_mes_int = int(anomes_am) if str(anomes_am).isdigit() else None
    try:
        existentes = (supabase.table("tab_esocial")
                      .select("id_esocial, recibo, observacao_erro")
                      .eq("id_empresa", id_empresa).eq("matricula", mat_int)
                      .eq("layout", layout).execute().data or [])
    except Exception:
        existentes = []
    pendente = None
    for row in existentes:
        rec = (row.get("recibo") or "").strip()
        obs = (row.get("observacao_erro") or "").strip().upper()
        if not rec and obs != "EXCLUIDO":
            pendente = row
            break
    campos = {
        "data_cad":   agora_es.strftime("%Y%m%d"),
        "hora_cad":   agora_es.strftime("%H%M"),
        "id_remessa": agora_es.strftime("%Y%m%d%H%M%S"),
        "ano_mes":    ano_mes_int,
        "folha_tipo": folha_tipo_es,
    }
    try:
        if pendente:
            (supabase.table("tab_esocial").update(campos)
             .eq("id_esocial", pendente["id_esocial"]).execute())
        else:
            supabase.table("tab_esocial").insert({
                "id_cliente": id_cliente, "id_empresa": id_empresa,
                "layout": layout, "matricula": mat_int, "codigo2": 0,
                **campos,
            }).execute()
    except Exception:
        pass  # falha no eSocial não desfaz o cálculo da rescisão


def _periodo_rescisao(id_empresa, mat_int, datarescisao):
    """(ano_mes, folha_tipo) do período da rescisão. Usa o S-2299 mais recente
    do funcionário; se não houver, deriva da data de rescisão (folha_tipo 'N')."""
    try:
        r = (supabase.table("tab_esocial")
             .select("ano_mes, folha_tipo")
             .eq("id_empresa", id_empresa).eq("matricula", mat_int)
             .eq("layout", "2299")
             .order("id_remessa", desc=True).limit(1).execute())
        if r.data and r.data[0].get("ano_mes"):
            return int(r.data[0]["ano_mes"]), str(r.data[0].get("folha_tipo") or "N")
    except Exception:
        pass
    dr = str(datarescisao or "")
    if len(dr) >= 6 and dr[:6].isdigit():
        return int(dr[:6]), "N"
    return None, "N"


@app.route("/api/funcionarios_demitidos")
def api_funcionarios_demitidos():
    """Desligados cuja rescisão é do MÊS DA FOLHA ATUAL (só esses podem ser
    cancelados). Rescisões de meses anteriores não são exibidas."""
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    if len(anomes) != 6:
        return jsonify({"ok": True, "funcionarios": []})
    try:
        r = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, dtadm, situacao, datarescisao")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "D")
             .order("matricula")
             .execute())
        funcionarios = []
        for f in (r.data or []):
            dr = str(f.get("datarescisao") or "")
            if dr[:6] != anomes:          # só rescisões do mês da folha ativa
                continue
            nome = (f.get("nome") or f.get("nomer") or "").strip()   # nome COMPLETO
            resc = f"{dr[6:8]}/{dr[4:6]}/{dr[0:4]}" if len(dr) == 8 and dr.isdigit() else ""
            funcionarios.append({
                "matricula": f.get("matricula"),
                "nome":      nome,
                "dtadm":     str(f.get("dtadm") or ""),
                "situacao":  "D",
                "resc_data": resc,
            })
        return jsonify({"ok": True, "funcionarios": funcionarios})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


@app.route("/cancelar_rescisao", methods=["GET", "POST"])
def cancelar_rescisao():
    if not session.get("logado"):
        return redirect("/")
    id_empresa = _get_id_empresa()
    mat_raw = (request.args.get("mats") or request.args.get("mat") or "").strip()
    mat_str = mat_raw.split(",")[0].strip()
    if not mat_str.isdigit():
        return redirect("/select_funcionario?contexto=cancelar_rescisao")
    mat_int = int(mat_str)

    # Funcionário + dados da rescisão
    funcionario, datarescisao = None, ""
    try:
        r = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, situacao, datarescisao, motrescisao")
             .eq("id_empresa", id_empresa).eq("matricula", mat_int).limit(1).execute())
        if r.data:
            f = r.data[0]
            datarescisao = str(f.get("datarescisao") or "")
            resc = (f"{datarescisao[6:8]}/{datarescisao[4:6]}/{datarescisao[0:4]}"
                    if len(datarescisao) == 8 and datarescisao.isdigit() else "")
            funcionario = {
                "matricula": mat_int,
                "mat_fmt":   str(mat_int).zfill(6),
                "nome":      (f.get("nomer") or f.get("nome") or "").strip(),
                "situacao":  str(f.get("situacao") or ""),
                "resc_data": resc,
                "motivo":    str(f.get("motrescisao") or ""),
            }
    except Exception:
        pass

    # Período da rescisão e status do S-1299
    periodo_am, periodo_tp = _periodo_rescisao(id_empresa, mat_int, datarescisao)
    s1299 = _s1299_ativo(id_empresa, periodo_am, periodo_tp)

    # Folha precisa estar Aberta (não Calculada/Fechada)
    sit_folha    = _refresh_situacao_folha()
    folha_aberta = sit_folha in ("A", "X")
    folha_sit    = {"A": "Aberta", "X": "Aberta", "C": "Calculada",
                    "F": "Fechada", "P": "Processando"}.get(sit_folha, sit_folha)

    # Só cancela rescisão do MÊS ATUAL (a data da rescisão tem que cair na folha
    # ativa). Rescisões de meses anteriores não podem ser canceladas.
    anomes_atual = str(session.get("anomes_atual") or "")
    mes_rescisao = (datarescisao[:6] if len(datarescisao) >= 6 and datarescisao[:6].isdigit()
                    else (str(periodo_am) if periodo_am else ""))
    mes_ok       = bool(anomes_atual) and mes_rescisao == anomes_atual

    def _mmaa(am):
        a = str(am or "")
        return f"{a[4:6]}/{a[0:4]}" if len(a) == 6 else (a or "—")
    folha_fmt    = _mmaa(anomes_atual)
    mes_resc_fmt = _mmaa(mes_rescisao)

    # Bloqueios (ordem de prioridade)
    bloqueio = ""
    if not funcionario:
        bloqueio = "nao_encontrado"
    elif funcionario.get("situacao") != "D":
        bloqueio = "nao_demitido"
    elif not folha_aberta:
        bloqueio = "folha_fechada"
    elif not mes_ok:
        bloqueio = "mes_diferente"
    elif s1299:
        bloqueio = "s1299"

    # ── POST: efetiva o cancelamento ──
    if request.method == "POST":
        if bloqueio:
            return redirect(f"/cancelar_rescisao?mats={mat_int}")
        # Reverte o cadastro para Ativo
        try:
            try:
                (supabase.table("tab_cad")
                 .update({"situacao": "A", "datarescisao": None, "motrescisao": None})
                 .eq("id_empresa", id_empresa).eq("matricula", mat_int).execute())
            except Exception:
                (supabase.table("tab_cad").update({"situacao": "A"})
                 .eq("id_empresa", id_empresa).eq("matricula", mat_int).execute())
        except Exception as e:
            gravar_log("RESC-CAN-ER", str(e)[:200], matricula=mat_int)
            return redirect(f"/cancelar_rescisao?mats={mat_int}&erro=1")
        # Remove o S-2299 ainda PENDENTE (não enviado / não excluído)
        try:
            r2 = (supabase.table("tab_esocial")
                  .select("id_esocial, recibo, observacao_erro")
                  .eq("id_empresa", id_empresa).eq("matricula", mat_int)
                  .eq("layout", "2299").execute().data or [])
            for row in r2:
                rec = (row.get("recibo") or "").strip()
                obs = (row.get("observacao_erro") or "").strip().upper()
                if not rec and obs != "EXCLUIDO":
                    (supabase.table("tab_esocial").delete()
                     .eq("id_esocial", row["id_esocial"]).execute())
        except Exception:
            pass
        # Cancela também o AVISO PRÉVIO que originou a rescisão (op1=9 do mês
        # atual ou do anterior — mesma janela usada na seleção de rescisão).
        try:
            _y, _m = int(anomes_atual[:4]), int(anomes_atual[4:6])
            _prev  = (_y - 1) * 100 + 12 if _m == 1 else _y * 100 + (_m - 1)
            (supabase.table("tab_eventos").delete()
             .eq("id_empresa", id_empresa).eq("matricula", mat_int)
             .eq("op1", 9).in_("folha", [int(anomes_atual), _prev]).execute())
        except Exception:
            pass
        gravar_log("RESC-CANCEL",
                   f"Rescisão + aviso prévio cancelados — {funcionario['nome']} "
                   f"(resc. {funcionario['resc_data']})",
                   matricula=mat_int)
        return redirect(f"/cancelar_rescisao?mats={mat_int}&ok=1")

    return render_template(
        "F10_Cancelar_Rescisao.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        funcionario=funcionario,
        bloqueio=bloqueio,
        folha_sit=folha_sit,
        folha_fmt=folha_fmt,
        mes_resc_fmt=mes_resc_fmt,
        ok=request.args.get("ok"),
        erro=request.args.get("erro"),
    )


# =========================================================
# CÁLCULO DA RESCISÃO  (folha_tipo="R")
# Espelha o cálculo de férias: médias da ficha financeira (inc_rescisao),
# INSS/IRRF/FGTS, grava tab_mov/tab_total/tab_log e memória PDF detalhada.
# Parte da rescisão JÁ REGISTRADA (situacao='D', datarescisao, motrescisao).
# =========================================================
# Códigos de verba (Folha10) usados na rescisão
VR_SALDO       = 10    # SALDO DE SALARIO
VR_13_PROP     = 12    # 13 SALARIO PROPORCIONAL
VR_13_AVISO    = 13    # 13 SALARIO INDENIZADO (projeção do aviso)
VR_FERIAS_PROP = 49    # FERIAS PROPORCIONAIS+1/3
VR_FERIAS_AVISO= 44    # FERIAS RESCISAO AVISO PREVIO (+1/3)
VR_AVISO_IND   = 61    # AVISO PREVIO (indenizado)
VR_INSS        = 101   # INSS (saldo)
VR_INSS_13     = 104   # INSS 13.SAL. RESC.
VR_IRRF        = 120   # IRRF
VR_IRRF_13     = 122   # IRRF 13.SAL

# Verbas de rescisão que NÃO entram na média (são proventos/descontos próprios)
_VERBAS_RESC_PROPRIAS = {10, 11, 12, 13, 14, 17, 18, 41, 42, 43, 44, 45, 46, 47, 48, 49,
                         51, 60, 61, 62, 63, 64, 65, 66, 69, 94, 101, 102, 103, 104, 109,
                         120, 121, 122, 133, 260, 333, 334, 366, 430, 490, 499, 502,
                         551, 552, 560, 561, 562, 611, 612}

# Regras por motivo de desligamento (Tabela 19 eSocial):
#   (tem_13_prop, tem_ferias_prop, multa_fgts_pct)
# Aviso prévio indenizado é definido pelo evento op1=9 (campotxt1='Indenizado'),
# ajustado por motivo (acordo=50%). default = paga 13º/férias, sem multa.
_MOTIVO_RESC = {
    "01": (False, False, 0),   # com justa causa
    "02": (True,  True,  40),  # sem justa causa (empregador)
    "03": (True,  True,  40),  # antecipada contrato a termo — empregador
    "04": (True,  True,  0),   # antecipada contrato a termo — empregado
    "05": (True,  True,  20),  # culpa recíproca
    "06": (True,  True,  0),   # término do contrato a termo
    "07": (True,  True,  0),   # pedido do empregado
    "10": (True,  True,  0),   # falecimento do empregado
    "17": (True,  True,  40),  # rescisão indireta
    "33": (True,  True,  20),  # acordo (484-A)
}


def _conta_avos_resc(dt_ini, dt_fim):
    """Conta avos (meses) de dt_ini a dt_fim; cada mês com >=15 dias trabalhados
    conta 1 avo (regra CLT do 13º e das férias)."""
    if not dt_ini or not dt_fim or dt_fim < dt_ini:
        return 0
    avos, y, m = 0, dt_ini.year, dt_ini.month
    while (y < dt_fim.year) or (y == dt_fim.year and m <= dt_fim.month):
        ult = calendar.monthrange(y, m)[1]
        d_ini = dt_ini.day if (y == dt_ini.year and m == dt_ini.month) else 1
        d_fim = dt_fim.day if (y == dt_fim.year and m == dt_fim.month) else ult
        if (d_fim - d_ini + 1) >= 15:
            avos += 1
        m += 1
        if m > 12:
            m, y = 1, y + 1
    return min(12, avos)


def _inicio_aquisitivo_resc(dt_adm, dt_ref):
    """Início do período aquisitivo de férias em curso na data dt_ref."""
    from datetime import date as _d
    anos = dt_ref.year - dt_adm.year
    def _aniv(n):
        try:
            return dt_adm.replace(year=dt_adm.year + n)
        except ValueError:
            return dt_adm.replace(year=dt_adm.year + n, day=28)
    aniv = _aniv(anos)
    if aniv > dt_ref:
        aniv = _aniv(anos - 1)
    return aniv


def _dparse(s):
    """'YYYYMMDD' (int/str) -> date, ou None."""
    from datetime import date as _d
    s = str(s or "")
    if len(s) == 8 and s.isdigit():
        try:
            return _d(int(s[:4]), int(s[4:6]), int(s[6:8]))
        except Exception:
            return None
    return None


@app.route("/calc_rescisao")
def calc_rescisao():
    """Tela do cálculo da rescisão — lista os desligados do mês da folha ativa."""
    if not session.get("logado"):
        return redirect("/")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    def_ini, def_fim = _mes_atual_intervalo() if len(anomes) != 6 else (None, None)
    # desligados com datarescisao no mês da folha ativa
    funcs = []
    if len(anomes) == 6:
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, situacao, datarescisao, motrescisao")
                 .eq("id_empresa", id_empresa).eq("situacao", "D").order("matricula").execute())
            # matrículas já calculadas (tab_total R) = "Calculada"; senão "Pendente"
            calc_set = _rescisao_calculada_mats(id_empresa, id_cliente, int(anomes))
            for f in (r.data or []):
                dr = str(f.get("datarescisao") or "")
                if dr[:6] != anomes:
                    continue
                m = int(f.get("matricula") or 0)
                funcs.append({
                    "matricula": m, "mat_fmt": f"{m:06d}",
                    "nome": (f.get("nome") or f.get("nomer") or "").strip(),
                    "resc_data": f"{dr[6:8]}/{dr[4:6]}/{dr[0:4]}" if len(dr) == 8 else "—",
                    "motivo": str(f.get("motrescisao") or ""),
                    "calculado": m in calc_set,
                })
        except Exception:
            funcs = []
    folha_situacao = _refresh_situacao_folha() if len(anomes) == 6 else ""
    modo = request.args.get("modo")
    return render_template("F10_Calc_Rescisao.html", **_ctx_relatorio(),
                           anomes_atual=anomes, funcs=funcs,
                           folha_situacao=folha_situacao,
                           modo_trct=(modo == "trct"), modo_memoria=(modo == "memoria"))


@app.route("/api/calc_rescisao_calcular", methods=["POST"])
def api_calc_rescisao_calcular():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    if str(session.get("anomes_situacao") or "") in ("C", "F"):
        return jsonify({"ok": False, "msg": "A folha precisa estar Aberta para calcular."})

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if len(anomes) != 6:
        return jsonify({"ok": False, "msg": "Nenhuma folha ativa."})
    tabela = _get_tabela_legais(anomes)
    if not tabela:
        return jsonify({"ok": False, "msg": "Tabela legal (INSS/IRRF) não encontrada para o período."})

    folha_int  = int(anomes)
    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))
    dep_count    = _get_dep_irrf_count(id_empresa)
    dep_irrf_ded = int(tabela.get("irrf_dep_dedu") or 0)

    body = request.get_json(silent=True) or {}
    filtro_mats = set(int(x) for x in (body.get("matriculas") or []) if str(x).isdigit())

    # ── Desligados do mês da folha ativa ──
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, undsalfixo, vrsalfx, qtdhrsmes, dtadm, datarescisao, motrescisao")
                 .eq("id_empresa", id_empresa).eq("situacao", "D").execute())
        demitidos = [c for c in (r_cad.data or [])
                     if str(c.get("datarescisao") or "")[:6] == anomes
                     and (not filtro_mats or int(c.get("matricula") or 0) in filtro_mats)]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar cadastros: {e}"})
    if not demitidos:
        return jsonify({"ok": False, "msg": "Nenhum desligado no mês para calcular."})

    # ── Verbas variáveis que entram na média (inc_rescisao) ──
    try:
        r_rub = (supabase.table("tab_rubrica")
                 .select("cod_rubr, dsc_rubr, tp_rubr, unid_verba, inc_rescisao, tpr_inc_cp, tpr_inc_irrf, tpr_inc_fgts")
                 .in_("id_cliente", [0, id_cliente]).eq("situacao", "A").order("cod_rubr").execute())
        rubrics = r_rub.data or []
    except Exception:
        rubrics = []
    _INC_VALIDOS = {"MAP", "M12", "MAN", "S"}
    _verbas_media = [int(r["cod_rubr"]) for r in rubrics
                     if str(r.get("inc_rescisao") or "").upper() in _INC_VALIDOS
                     and str(r.get("tp_rubr") or "") == "1"
                     and int(r.get("cod_rubr") or 0) not in _VERBAS_RESC_PROPRIAS]
    _verbas_horas = {int(r["cod_rubr"]) for r in rubrics
                     if int(r.get("cod_rubr") or 0) in set(_verbas_media)
                     and str(r.get("unid_verba") or "").upper() == "H"}
    _rubr_desc = {int(r["cod_rubr"]): (r.get("dsc_rubr") or "").strip() for r in rubrics}
    # Mapa completo p/ classificar as verbas MANUAIS (origem='M') lançadas na
    # rescisão: tipo (1=provento/2=desconto) e incidências de rescisão (tpr_inc_*).
    # Incidência: "11" incide (INSS/IRRF/FGTS); FGTS também aceita "S" (verba 17).
    _rubr_full = {}
    for r in rubrics:
        c = int(r.get("cod_rubr") or 0)
        if c:
            _rubr_full[c] = {
                "tp":   str(r.get("tp_rubr")      or "1"),
                "unid": str(r.get("unid_verba")   or "V").upper()[:1],
                "icp":  str(r.get("tpr_inc_cp")   or ""),
                "iir":  str(r.get("tpr_inc_irrf") or ""),
                "ift":  str(r.get("tpr_inc_fgts") or ""),
            }

    # Verbas manuais (origem='M') da rescisão do mês, por matrícula. Não são
    # apagadas pelo recálculo; aqui entram nas bases (INSS/IRRF/FGTS) e totais.
    manual_mov = {}
    try:
        q_man = (supabase.table("tab_mov")
                 .select("id, matricula, cod_verba, valor, qtd")
                 .eq("id_empresa", id_empresa)
                 .eq("folha",      folha_int)
                 .eq("folha_tipo", "R")
                 .eq("origem",     "M")
                 .eq("situacao",   "A"))
        if id_cliente:
            q_man = q_man.eq("id_cliente", id_cliente)
        for row in (q_man.execute().data or []):
            m = int(row.get("matricula") or 0)
            manual_mov.setdefault(m, []).append(row)
    except Exception:
        pass

    ano_folha = int(anomes[:4]); mes_folha = int(anomes[4:6])

    def _media_variaveis(mat, sal_hora_c):
        """Médias das verbas variáveis da ficha financeira (tab_mov) para a rescisão.

        Regra: a base é a soma dos últimos 11 meses + o mês da rescisão (12 folhas
        terminando NO mês da rescisão, inclusive), dividida por 12 → média p/ FÉRIAS.
        Para o 13º SALÁRIO só entram valores do ANO CORRENTE (folhas de janeiro do
        ano da rescisão até o mês da rescisão), também dividida por 12.
        Retorna (medias_fer, medias_13, info)."""
        if not _verbas_media:
            return {}, {}, {}
        # janela de 12 folhas terminando NO mês da rescisão (inclui o próprio mês)
        t_fim = ano_folha * 12 + mes_folha - 1
        if t_fim < 0: t_fim = 0
        t_ini = t_fim - 11
        fi = (t_ini // 12) * 100 + t_ini % 12 + 1
        ff = (t_fim // 12) * 100 + t_fim % 12 + 1
        fi13 = ano_folha * 100 + 1          # janeiro do ano da rescisão
        por_mes = {}
        tot_val, tot_qtd     = {}, {}       # 12 meses → médias de férias
        tot_val13, tot_qtd13 = {}, {}       # ano corrente → médias do 13º
        try:
            r_med = (supabase.table("tab_mov")
                     .select("cod_verba, valor, qtd, folha")
                     .eq("id_cliente", id_cliente).eq("id_empresa", id_empresa)
                     .eq("matricula", mat).eq("situacao", "A")
                     .in_("cod_verba", _verbas_media)
                     .gte("folha", fi).lte("folha", ff)
                     .eq("folha_tipo", "N").execute())
            for row in (r_med.data or []):
                c   = int(row.get("cod_verba") or 0)
                fol = int(row.get("folha") or 0)
                v   = int(row.get("valor") or 0)
                q   = int(row.get("qtd") or 0)
                por_mes.setdefault(c, {}).setdefault(fol, {"valor": 0, "qtd": 0})
                por_mes[c][fol]["valor"] += v
                por_mes[c][fol]["qtd"]   += q
                if c in _verbas_horas:
                    tot_qtd[c] = tot_qtd.get(c, 0) + q
                    if fol >= fi13:
                        tot_qtd13[c] = tot_qtd13.get(c, 0) + q
                else:
                    tot_val[c] = tot_val.get(c, 0) + v
                    if fol >= fi13:
                        tot_val13[c] = tot_val13.get(c, 0) + v
        except Exception:
            pass
        # "+ o mês da rescisão": verbas variáveis lançadas na PRÓPRIA folha da
        # rescisão (folha_tipo='R', origem='M'). Não existe folha 'N' no mês do
        # desligamento, então sem isto a parte "+ mês da rescisão" da regra ficaria
        # vazia. Entram nas duas médias (rescisão é sempre do ano corrente → 13º).
        for row in manual_mov.get(mat, []):
            c = int(row.get("cod_verba") or 0)
            if c not in _verbas_media:
                continue
            v = int(row.get("valor") or 0)
            q = int(row.get("qtd") or 0)
            por_mes.setdefault(c, {}).setdefault(ff, {"valor": 0, "qtd": 0})
            por_mes[c][ff]["valor"] += v
            por_mes[c][ff]["qtd"]   += q
            if c in _verbas_horas:
                tot_qtd[c]   = tot_qtd.get(c, 0) + q
                tot_qtd13[c] = tot_qtd13.get(c, 0) + q
            else:
                tot_val[c]   = tot_val.get(c, 0) + v
                tot_val13[c] = tot_val13.get(c, 0) + v
        medias_fer, medias_13 = {}, {}
        det = []
        for c in sorted(set(tot_val) | set(tot_qtd)):
            if c in _verbas_horas:
                avg_min   = round(tot_qtd.get(c, 0) / 12)
                val_fer   = round(avg_min * sal_hora_c / 60)
                avg_min13 = round(tot_qtd13.get(c, 0) / 12)
                val_13    = round(avg_min13 * sal_hora_c / 60)
            else:
                avg_min = avg_min13 = 0
                val_fer = round(tot_val.get(c, 0) / 12)
                val_13  = round(tot_val13.get(c, 0) / 12)
            if val_fer:
                medias_fer[c] = val_fer
            if val_13:
                medias_13[c] = val_13
            if val_fer or val_13:
                det.append({"cod": c, "dsc": _rubr_desc.get(c, f"Verba {c:04d}"),
                            "tipo": "H" if c in _verbas_horas else "V",
                            "fi": fi, "ff": ff, "fi13": fi13,
                            "avg_min": avg_min, "avg_min13": avg_min13,
                            "total": tot_val.get(c, 0), "total_min": tot_qtd.get(c, 0),
                            "total13": tot_val13.get(c, 0), "total_min13": tot_qtd13.get(c, 0),
                            "por_mes": sorted(por_mes.get(c, {}).items()),
                            "val": val_fer, "val_fer": val_fer, "val_13": val_13})
        return medias_fer, medias_13, {"fi": fi, "ff": ff, "fi13": fi13, "det": det}

    from datetime import date as _date
    resultados = []
    for cad in demitidos:
        mat = int(cad.get("matricula") or 0)
        nome = (cad.get("nome") or cad.get("nomer") or "").strip()
        vrsalfx = int(cad.get("vrsalfx") or 0)
        qhm = int(cad.get("qtdhrsmes") or 220) or 220
        und = (cad.get("undsalfixo") or "M").upper()[:1]
        sal_mes = vrsalfx * qhm if und == "H" else vrsalfx
        sal_hora_c = vrsalfx if und == "H" else (round(vrsalfx / qhm) if qhm else 0)

        dt_resc = _dparse(cad.get("datarescisao"))
        dt_adm  = _dparse(cad.get("dtadm"))
        if not dt_resc:
            continue
        motivo = str(cad.get("motrescisao") or "").zfill(2)
        tem_13, tem_fer, multa_pct = _MOTIVO_RESC.get(motivo, (True, True, 0))

        # aviso prévio (op1=9)
        aviso_ind, dias_aviso = False, 0
        try:
            r_av = (supabase.table("tab_eventos")
                    .select("campotxt1, campotxt2, ref1, ref2, data1i")
                    .eq("id_empresa", id_empresa).eq("matricula", mat).eq("op1", 9)
                    .order("data1i", desc=True).limit(1).execute())
            if r_av.data:
                ev = r_av.data[0]
                aviso_ind = str(ev.get("campotxt1") or "").strip().lower().startswith("inden")
                dias_aviso = int(ev.get("ref1") or 0) + int(ev.get("ref2") or 0)
        except Exception:
            pass

        # projeção do aviso indenizado (avança a data p/ avos)
        dt_proj = dt_resc
        if aviso_ind and dias_aviso > 0:
            from datetime import timedelta as _td
            dt_proj = dt_resc + _td(days=dias_aviso)

        # ── Proventos ──
        saldo = round(sal_mes * dt_resc.day / 30)
        # aviso prévio indenizado (acordo=50%)
        aviso_val = 0
        if aviso_ind and dias_aviso > 0:
            aviso_val = round(sal_mes * dias_aviso / 30)
            if multa_pct == 20:   # acordo 484-A → aviso 50%
                aviso_val = round(aviso_val / 2)
        # médias variáveis (férias = 12 meses; 13º = só ano corrente)
        medias, medias_13, medias_info = _media_variaveis(mat, sal_hora_c)
        med_total    = sum(medias.values())      # média p/ férias (últimos 11 + mês da rescisão ÷ 12)
        med_total_13 = sum(medias_13.values())   # média p/ 13º (ano corrente ÷ 12)
        base_media_fer = med_total
        base_media_13  = med_total_13
        # 13º proporcional (avos no ano + projeção) sobre salário + médias do ano corrente
        ini_ano = _date(dt_proj.year, 1, 1)
        if dt_adm and dt_adm > ini_ano:
            ini_ano = dt_adm
        avos_13 = _conta_avos_resc(ini_ano, dt_proj) if tem_13 else 0
        d13 = round((sal_mes + base_media_13) * avos_13 / 12) if avos_13 else 0
        # férias proporcionais + 1/3 (avos do período aquisitivo em curso)
        ini_aq = _inicio_aquisitivo_resc(dt_adm, dt_proj) if dt_adm else _date(dt_proj.year, 1, 1)
        avos_fer = _conta_avos_resc(ini_aq, dt_proj) if tem_fer else 0
        fer_base = round((sal_mes + base_media_fer) * avos_fer / 12) if avos_fer else 0
        fer_prop = round(fer_base * 4 / 3)   # inclui 1/3

        # ── Verbas MANUAIS (origem='M') lançadas na rescisão ──
        # Proventos entram nos totais e (conforme incidência) nas bases de
        # INSS/IRRF/FGTS do saldo; descontos abatem o líquido.
        # salário-hora / salário-dia p/ recalcular verbas H/D manuais
        sal_hora_man = float(vrsalfx) if und == "H" else (round(vrsalfx / qhm, 4) if qhm else 0.0)
        _dias_folha_man = _dias_no_mes_total(anomes) or 30
        sal_dia_man = (sal_mes / _dias_folha_man) if _dias_folha_man else 0.0

        man_prov = man_desc = add_inss = add_irrf = add_fgts = 0
        manuais_det = []
        for row in manual_mov.get(mat, []):
            cod_m = int(row.get("cod_verba") or 0)
            qtd_m = int(row.get("qtd") or 0)
            ri_m = _rubr_full.get(cod_m, {"tp": "1", "unid": "V", "icp": "", "iir": "", "ift": ""})
            unid_m = ri_m.get("unid", "V")
            # verba H/D: valor = qtd × salário-hora/dia (ignora valor gravado, que
            # pode estar defasado); demais usam o valor lançado.
            if unid_m == "H" and qtd_m > 0:
                val_m = int(round(qtd_m / 60 * sal_hora_man))
                _hh, _mm = qtd_m // 60, qtd_m % 60
                det_m = (f"{_hh:02d}h{_mm:02d} × {_fmt_brl(int(round(sal_hora_man)))}/h"
                         f"  =  {_fmt_brl(val_m)}")
            elif unid_m == "D" and qtd_m > 0:
                val_m = int(round(qtd_m * sal_dia_man))
                det_m = (f"{qtd_m} {'dia' if qtd_m == 1 else 'dias'} × "
                         f"{_fmt_brl(int(round(sal_dia_man)))}/dia  =  {_fmt_brl(val_m)}")
            else:
                val_m = int(row.get("valor") or 0)
                det_m = f"Valor lançado: {_fmt_brl(val_m)}" if val_m else ""
            if not val_m:
                continue
            # persiste o valor corrigido no tab_mov (p/ TRCT/Visualizar lerem igual)
            if val_m != int(row.get("valor") or 0) and row.get("id"):
                try:
                    supabase.table("tab_mov").update({"valor": val_m}).eq("id", row["id"]).execute()
                except Exception:
                    pass
            eh_prov = str(ri_m["tp"]) == "1"
            incs = []
            if eh_prov:                               # provento
                man_prov += val_m
                if ri_m["icp"] == "11":              add_inss += val_m; incs.append("INSS")
                if ri_m["iir"] == "11":              add_irrf += val_m; incs.append("IRRF")
                if ri_m["ift"] in ("11", "S"):       add_fgts += val_m; incs.append("FGTS")
            else:                                     # desconto
                man_desc += val_m
            manuais_det.append({"cod": cod_m, "dsc": _rubr_desc.get(cod_m, f"Verba {cod_m:04d}"),
                                "tp": "P" if eh_prov else "D", "val": val_m,
                                "unid": unid_m, "qtd": qtd_m, "det": det_m,
                                "inc": "+".join(incs) if incs else "—"})

        # ── Bases e impostos ──
        # As médias são REFLEXO (entram no 13º e nas férias), não são pagas como
        # linha própria. Saldo de salário incide INSS sobre o salário do período.
        # Verbas manuais que incidem somam à base do saldo.
        base_inss_saldo = saldo + add_inss
        inss_saldo, inss_saldo_det, _ = _calc_inss_progressivo(base_inss_saldo, tabela)
        # INSS 13º (base separada)
        inss_13, inss_13_det, _ = (_calc_inss_progressivo(d13, tabela) if d13 else (0, [], 0))
        # IRRF: base saldo (saldo + manuais c/ inc. IRRF) - inss_saldo - dep ; 13º separado
        ndep = dep_count.get(mat, 0); dep_total = ndep * dep_irrf_ded
        base_irrf_saldo = max(0, saldo + add_irrf - inss_saldo - dep_total)
        irrf_saldo, irrf_saldo_info = _calc_irrf(base_irrf_saldo, tabela)
        base_irrf_13 = max(0, d13 - inss_13)
        irrf_13, irrf_13_info = (_calc_irrf(base_irrf_13, tabela) if d13 else (0, None))
        # FGTS 8% sobre saldo + 13º + aviso indenizado + manuais c/ inc. FGTS
        # (férias indenizadas não têm FGTS)
        base_fgts = saldo + d13 + aviso_val + add_fgts
        fgts_val = round(base_fgts * 8 / 100)

        total_prov = saldo + aviso_val + d13 + fer_prop + man_prov
        total_desc = inss_saldo + inss_13 + irrf_saldo + irrf_13 + man_desc
        liquido    = total_prov - total_desc

        # ── Grava ── (apaga 'C' antes; preserva manuais 'M')
        try:
            (supabase.table("tab_mov").delete()
             .eq("id_cliente", id_cliente).eq("id_empresa", id_empresa).eq("matricula", mat)
             .eq("folha", folha_int).eq("folha_tipo", "R").eq("origem", "C").execute())
        except Exception:
            pass
        try:
            (supabase.table("tab_total").delete()
             .eq("id_cliente", id_cliente).eq("id_empresa", id_empresa).eq("matricula", mat)
             .eq("folha", folha_int).eq("folha_tipo", "R").execute())
        except Exception:
            pass
        base_mov = {"id_cliente": id_cliente, "id_empresa": id_empresa, "situacao": "A",
                    "matricula": mat, "folha": folha_int, "folha_tipo": "R",
                    "lote": 0, "origem": "C", "controle": 0, "os": 0}
        recs = []
        if saldo:     recs.append({**base_mov, "cod_verba": VR_SALDO,        "qtd": dt_resc.day, "valor": saldo})
        if aviso_val: recs.append({**base_mov, "cod_verba": VR_AVISO_IND,    "qtd": dias_aviso,  "valor": aviso_val})
        # médias NÃO viram linha própria — já estão embutidas no 13º e nas férias
        if d13:       recs.append({**base_mov, "cod_verba": VR_13_PROP,      "qtd": avos_13,  "valor": d13})
        if fer_prop:  recs.append({**base_mov, "cod_verba": VR_FERIAS_PROP,  "qtd": avos_fer, "valor": fer_prop})
        if inss_saldo:recs.append({**base_mov, "cod_verba": VR_INSS,         "qtd": 0, "valor": inss_saldo})
        if inss_13:   recs.append({**base_mov, "cod_verba": VR_INSS_13,      "qtd": 0, "valor": inss_13})
        if irrf_saldo:recs.append({**base_mov, "cod_verba": VR_IRRF,         "qtd": 0, "valor": irrf_saldo})
        if irrf_13:   recs.append({**base_mov, "cod_verba": VR_IRRF_13,      "qtd": 0, "valor": irrf_13})
        if recs:
            try:
                supabase.table("tab_mov").insert(recs).execute()
            except Exception as e_ins:
                return jsonify({"ok": False, "msg": f"Erro ao gravar movimentos (mat {mat}): {str(e_ins)[:200]}"})
        rec_tot = {
            "id_cliente": id_cliente, "id_empresa": id_empresa, "matricula": mat,
            "folha": folha_int, "folha_tipo": "R",
            "valor_base_inss_semlimite": base_inss_saldo, "valor_base_inss_comlimite": base_inss_saldo,
            "valor_inss_retido": inss_saldo + inss_13,
            "valor_base_fgts": base_fgts, "valor_fgts": fgts_val,
            "valor_irrf_basetotal": base_inss_saldo, "valor_irrf_basetabela": base_irrf_saldo,
            "valor_irrf_dependentes": dep_total, "qtd_irrf_dependentes": ndep,
            "valor_salario": sal_mes, "valor_total_proventos": total_prov,
            "valor_total_descontos": total_desc, "valor_liquido": liquido,
            "os": 0, "controle": 0,
        }
        try:
            supabase.table("tab_total").insert(rec_tot).execute()
        except Exception:
            pass
        gravar_log("CALC_RES",
                   f"Rescisão calc: saldo={_fmt_brl(saldo)} 13={_fmt_brl(d13)} fer={_fmt_brl(fer_prop)} "
                   f"INSS={_fmt_brl(inss_saldo+inss_13)} IRRF={_fmt_brl(irrf_saldo+irrf_13)} Liq={_fmt_brl(liquido)}",
                   matricula=mat)

        # Grava/atualiza o S-2299 (Desligamento) na tab_esocial — só aqui, no cálculo.
        _folha_tipo_es = "1" if str(session.get("anomes_tipo") or "") in ("1", "A") else "N"
        _gravar_ou_atualizar_s2299(id_empresa, id_cliente, mat, anomes, _folha_tipo_es,
                                   codcateg=cad.get("codcateg"))

        multa_fgts = round((int(body.get("saldo_fgts_" + str(mat)) or 0)) * multa_pct / 100)
        resultados.append({
            "matricula": mat, "mat_fmt": f"{mat:06d}", "nome": nome,
            "calc_dhg": datetime.now().strftime("%d/%m/%Y %H:%M"),
            "resc_data_fmt": dt_resc.strftime("%d/%m/%Y"),
            "dt_proj_fmt": dt_proj.strftime("%d/%m/%Y"),
            "motivo": motivo, "aviso_ind": aviso_ind, "dias_aviso": dias_aviso,
            "sal_mes": sal_mes, "saldo": saldo, "dia_resc": dt_resc.day,
            "und_sal": und, "qtd_hrs_mes": qhm, "sal_hora": sal_hora_man,
            "aviso_val": aviso_val, "avos_13": avos_13, "d13": d13,
            "avos_fer": avos_fer, "fer_base": fer_base, "fer_prop": fer_prop,
            "med_total": med_total, "med_total_13": med_total_13, "medias_info": medias_info,
            "base_inss_saldo": base_inss_saldo, "inss_saldo": inss_saldo, "inss_saldo_det": inss_saldo_det,
            "d13_base": d13, "inss_13": inss_13, "inss_13_det": inss_13_det,
            "ndep": ndep, "dep_irrf_ded": dep_irrf_ded, "dep_total": dep_total,
            "base_irrf_saldo": base_irrf_saldo, "irrf_saldo": irrf_saldo, "irrf_saldo_info": irrf_saldo_info,
            "base_irrf_13": base_irrf_13, "irrf_13": irrf_13, "irrf_13_info": irrf_13_info,
            "base_fgts": base_fgts, "fgts_val": fgts_val, "multa_pct": multa_pct, "multa_fgts": multa_fgts,
            "man_prov": man_prov, "man_desc": man_desc, "manuais_det": manuais_det,
            "add_inss": add_inss, "add_irrf": add_irrf, "add_fgts": add_fgts,
            "total_prov": total_prov, "total_desc": total_desc, "liquido": liquido,
            # formatados p/ a tela
            "saldo_fmt": _fmt_brl(saldo), "d13_fmt": _fmt_brl(d13), "fer_fmt": _fmt_brl(fer_prop),
            "aviso_fmt": _fmt_brl(aviso_val) if aviso_val else "—",
            "med_fmt": _fmt_brl(med_total) if med_total else "—",
            "inss_fmt": _fmt_brl(inss_saldo + inss_13), "irrf_fmt": _fmt_brl(irrf_saldo + irrf_13),
            "fgts_fmt": _fmt_brl(fgts_val), "prov_fmt": _fmt_brl(total_prov),
            "desc_fmt": _fmt_brl(total_desc), "liq_fmt": _fmt_brl(liquido),
        })

    try:
        _gerar_memoria_rescisao(empresa_nm, cnpj_fmt, anomes, id_empresa, resultados)
    except Exception as e_mem:
        print(f"[gerar_memoria_rescisao] erro: {e_mem}")

    # remove campos pesados do JSON (só resumo p/ a tela)
    _CAMPOS_PDF = {"medias_info", "inss_saldo_det", "inss_13_det", "irrf_saldo_info", "irrf_13_info",
                   "manuais_det"}
    web = [{k: v for k, v in r.items() if k not in _CAMPOS_PDF} for r in resultados]
    return jsonify({"ok": True, "resultados": web, "total": len(web)})


def _gerar_memoria_rescisao(empresa_nm, cnpj_fmt, anomes, id_empresa, resultados):
    """PDF de memória de cálculo da rescisão por funcionário (detalhada)."""
    if not resultados or len(anomes) != 6:
        return
    dest = _memoria_destino(anomes, id_empresa)
    if not dest.get("base"):
        return
    ts = datetime.now().strftime("%Y%m%d_as_%H%M%S")

    st_etapa   = ParagraphStyle("mr_eta", fontName="Helvetica-Bold", fontSize=8,
                                spaceBefore=10, spaceAfter=3)
    st_det     = ParagraphStyle("mr_det", fontName="Helvetica", fontSize=8,
                                leftIndent=10, textColor=colors.HexColor("#374151"))
    st_tot     = ParagraphStyle("mr_tot", fontName="Helvetica-Bold", fontSize=9,
                                spaceBefore=4)
    _sz = TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0),
                      ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                      ("TOPPADDING", (0, 0), (0, 0), 6),
                      ("BOTTOMPADDING", (0, 0), (-1, -1), 3)])

    _memoria_apagar(anomes, id_empresa,
                    remover_pred=lambda n: "_Rescisao_" in n and n.lower().endswith(".pdf"))

    def _B(c): return _fmt_brl(int(c or 0))
    def _fmt_anomes(v):
        s = str(v or "")
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else "—"

    def _etapa(titulo, linhas):
        rows = [[Paragraph(titulo, st_etapa)]]
        for ln in linhas:
            rows.append([Paragraph(ln, st_det)])
        t = Table(rows, colWidths=[17*cm]); t.setStyle(_sz)
        return t

    for r in resultados:
        mat = int(r["matricula"]); nome = r["nome"]
        nome_f = (f"Folha10_Memoria_Empresa_{int(id_empresa):06d}_Rescisao_{anomes}"
                  f"_Matricula_{mat:06d}_em_{ts}.pdf")
        try:
            buf = io.BytesIO()
            titulo_mem = f"MEMORIA DE CALCULO — {anomes[4:6]}/{anomes[:4]} — RESCISAO — {mat:06d} — {nome}"
            _agora = datetime.now().strftime("%d/%m/%Y %H:%M")
            _emp = f"{cnpj_fmt} — {empresa_nm}"

            def _hdr(canvas, doc, _t=titulo_mem, _a=_agora, _e=_emp):
                _pdf_num_pagina(canvas, doc)
                canvas.saveState()
                xL = doc.leftMargin; xR = xL + 17*cm; y1 = A4[1] - 0.60*cm
                canvas.setFont("Helvetica", 8); canvas.setFillColor(colors.HexColor("#374151"))
                canvas.drawString(xL, y1, _e); canvas.drawRightString(xR, y1, f"Calculado em {_a}")
                y2 = y1 - 0.50*cm
                canvas.setFont("Helvetica-Bold", 8); canvas.drawCentredString(xL + 8.5*cm, y2, _t)
                canvas.setStrokeColor(colors.HexColor("#374151")); canvas.setLineWidth(0.5)
                canvas.line(xL, y2 - 0.28*cm, xR, y2 - 0.28*cm)
                canvas.restoreState()

            doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=2*cm, rightMargin=2*cm,
                                    topMargin=2.8*cm, bottomMargin=1.5*cm)
            e = []
            sal = int(r["sal_mes"])

            # 0001 — Dados
            aviso_txt = (f"Aviso prévio INDENIZADO ({r['dias_aviso']} dias)" if r["aviso_ind"]
                         else "Sem aviso prévio indenizado")
            _und  = str(r.get("und_sal") or "M")
            _qhm  = int(r.get("qtd_hrs_mes") or 220)
            _shora = int(round(r.get("sal_hora") or 0))
            if _und == "H":
                lin_sal   = f"Salário cadastrado: {_B(_shora)}/hora (horista)"
                lin_shora = (f"Salário-hora = {_B(_shora)}/hora  ·  "
                             f"Salário mensal = {_B(_shora)} × {_qhm} h/mês = <b>{_B(sal)}</b>")
            else:
                lin_sal   = f"Salário cadastrado: {_B(sal)}/mês (mensalista)"
                lin_shora = (f"Salário-hora = {_B(sal)} ÷ {_qhm} h/mês = <b>{_B(_shora)}/hora</b>")
            e.append(_etapa("ETAPA 0001 - DADOS DA RESCISAO", [
                f"Data da rescisão: {r['resc_data_fmt']}   Motivo: {r['motivo']}",
                f"{aviso_txt}   Data projetada (avos): {r['dt_proj_fmt']}",
                lin_sal,
                lin_shora,
            ]))
            # 0002 — Saldo de salário
            e.append(_etapa("ETAPA 0002 - SALDO DE SALARIO", [
                f"Salário {_B(sal)} × {r['dia_resc']} dias / 30 = <b>{_B(r['saldo'])}</b>",
            ]))
            # 0003 — Aviso prévio indenizado
            if r["aviso_val"]:
                e.append(_etapa("ETAPA 0003 - AVISO PREVIO INDENIZADO", [
                    f"Salário {_B(sal)} × {r['dias_aviso']} dias / 30 = <b>{_B(r['aviso_val'])}</b>"
                    + ("  (acordo 484-A: 50%)" if r["multa_pct"] == 20 else ""),
                ]))
            # 0004 — Médias (férias = 11 meses + mês da rescisão ÷ 12; 13º = ano corrente ÷ 12)
            det = (r.get("medias_info") or {}).get("det") or []
            mi = r.get("medias_info") or {}
            lin_med = []
            if det:
                per   = f"{_fmt_anomes(mi.get('fi'))} a {_fmt_anomes(mi.get('ff'))}"
                per13 = f"{_fmt_anomes(mi.get('fi13'))} a {_fmt_anomes(mi.get('ff'))}"
                lin_med.append(f"<b>Férias — base: últimos 11 meses + mês da rescisão ({per}) ÷ 12</b>")
                for d in det:
                    if not d.get("val_fer"):
                        continue
                    if d["tipo"] == "H":
                        lin_med.append(f"{d['cod']:04d} {d['dsc']} — {d['avg_min']} min/mês → {_B(d['val_fer'])}")
                    else:
                        lin_med.append(f"{d['cod']:04d} {d['dsc']} — total {_B(d['total'])} /12 = {_B(d['val_fer'])}")
                lin_med.append(f"<b>Total das médias (férias): {_B(r['med_total'])}</b>")
                lin_med.append("")
                lin_med.append(f"<b>13º salário — base: valores do ano corrente ({per13}) ÷ 12</b>")
                _tem13 = False
                for d in det:
                    if not d.get("val_13"):
                        continue
                    _tem13 = True
                    if d["tipo"] == "H":
                        lin_med.append(f"{d['cod']:04d} {d['dsc']} — {d['avg_min13']} min/mês → {_B(d['val_13'])}")
                    else:
                        lin_med.append(f"{d['cod']:04d} {d['dsc']} — total {_B(d['total13'])} /12 = {_B(d['val_13'])}")
                if not _tem13:
                    lin_med.append("Sem valores de verbas variáveis no ano corrente.")
                lin_med.append(f"<b>Total das médias (13º): {_B(r.get('med_total_13', 0))}</b>")
            else:
                lin_med.append("Sem verbas variáveis com incidência de rescisão no período.")
            e.append(_etapa("ETAPA 0004 - MEDIAS DAS VERBAS VARIAVEIS", lin_med))
            # 0005 — 13º proporcional (médias do ano corrente)
            e.append(_etapa("ETAPA 0005 - 13o SALARIO PROPORCIONAL", [
                f"(Salário {_B(sal)} + Médias {_B(r.get('med_total_13', 0))}) × {r['avos_13']}/12 = <b>{_B(r['d13'])}</b>"
                if r["d13"] else "Sem 13º proporcional para este motivo.",
            ]))
            # 0006 — Férias proporcionais + 1/3 (médias de 12 meses)
            e.append(_etapa("ETAPA 0006 - FERIAS PROPORCIONAIS + 1/3", [
                f"(Salário {_B(sal)} + Médias {_B(r['med_total'])}) × {r['avos_fer']}/12 = {_B(r['fer_base'])}   "
                f"+ 1/3 = <b>{_B(r['fer_prop'])}</b>"
                if r["fer_prop"] else "Sem férias proporcionais para este motivo.",
            ]))
            # 0006B — Verbas manuais lançadas
            det_man = r.get("manuais_det") or []
            if det_man:
                lin_man = []
                for d in det_man:
                    sinal = "+" if d["tp"] == "P" else "−"
                    tp_lbl = "Provento" if d["tp"] == "P" else "Desconto"
                    lin_man.append(f"{d['cod']:04d} {d['dsc']} — {tp_lbl} {sinal}<b>{_B(d['val'])}</b>"
                                   + (f"  (incide {d['inc']})" if d['tp'] == 'P' else ""))
                    if d.get("det"):
                        lin_man.append(f"      {d['det']}")
                if r.get("man_prov"):
                    lin_man.append(f"<b>Total proventos manuais: {_B(r['man_prov'])}</b>")
                if r.get("man_desc"):
                    lin_man.append(f"<b>Total descontos manuais: {_B(r['man_desc'])}</b>")
                e.append(_etapa("ETAPA 0006B - VERBAS MANUAIS LANCADAS", lin_man))
            # 0007 — INSS
            _base_lbl = "saldo" + (" + manuais c/ inc. INSS" if r.get("add_inss") else "")
            lin_inss = [f"Base saldo ({_base_lbl}): {_B(r['base_inss_saldo'])}"]
            for fx in (r.get("inss_saldo_det") or []):
                lim, pct, bf, vf = fx
                lin_inss.append(f"  faixa até {_B(lim)} × {pct/100:.2f}% sobre {_B(bf)} = {_B(vf)}")
            lin_inss.append(f"INSS saldo = <b>{_B(r['inss_saldo'])}</b>")
            if r["inss_13"]:
                lin_inss.append(f"INSS 13º (base {_B(r['d13_base'])}) = <b>{_B(r['inss_13'])}</b>")
            e.append(_etapa("ETAPA 0007 - INSS", lin_inss))
            # 0008 — IRRF
            _irrf_base_lbl = "saldo" + (" + manuais c/ inc. IRRF" if r.get("add_irrf") else "")
            lin_irrf = [
                f"Base ({_irrf_base_lbl}) − INSS − dependentes ({r['ndep']}×{_B(r['dep_irrf_ded'])}) = {_B(r['base_irrf_saldo'])}",
                f"IRRF saldo = <b>{_B(r['irrf_saldo'])}</b>",
            ]
            if r["irrf_13"]:
                lin_irrf.append(f"IRRF 13º (base {_B(r['base_irrf_13'])}) = <b>{_B(r['irrf_13'])}</b>")
            e.append(_etapa("ETAPA 0008 - IRRF", lin_irrf))
            # 0009 — FGTS + multa
            _fgts_lbl = "saldo+13º+aviso" + ("+manuais c/ inc. FGTS" if r.get("add_fgts") else "")
            lin_fgts = [f"Base FGTS ({_fgts_lbl}) {_B(r['base_fgts'])} × 8% = <b>{_B(r['fgts_val'])}</b>"]
            if r["multa_pct"]:
                lin_fgts.append(f"Multa FGTS: {r['multa_pct']}% sobre o saldo de FGTS"
                                + (f" = {_B(r['multa_fgts'])}" if r["multa_fgts"] else " (informe o saldo)"))
            e.append(_etapa("ETAPA 0009 - FGTS", lin_fgts))
            # Totais
            e.append(Spacer(1, 4))
            e.append(Paragraph(f"TOTAL PROVENTOS: {_B(r['total_prov'])}", st_tot))
            e.append(Paragraph(f"<font color='#b91c1c'>TOTAL DESCONTOS: {_B(r['total_desc'])}</font>", st_tot))
            e.append(Paragraph(f"LIQUIDO A RECEBER: {_B(r['liquido'])}", st_tot))

            doc.build(e, onFirstPage=_hdr, onLaterPages=_hdr)
            _salvar_memoria_pdf(dest, nome_f, buf.getvalue())
        except Exception as e_r:
            print(f"[memoria_rescisao] mat={mat} erro: {e_r}")


