# =========================================================
def _validar_per_adianta13(dados):
    """Normaliza dados['perAdianta13'] para inteiro 10..90 (default 50).
    Retorna uma msg de erro (str) se inválido, ou None se OK (e ajusta dados)."""
    v = dados.get("perAdianta13")
    if v is None or v == "":
        dados["perAdianta13"] = 50
        return None
    try:
        p = int(v)
    except (TypeError, ValueError):
        return "O % de adiantamento do 13º deve ser um número inteiro entre 10 e 90."
    if p < 10 or p > 90:
        return "O % de adiantamento do 13º deve estar entre 10 e 90."
    dados["perAdianta13"] = p
    return None


@app.route("/alterar_empresa")
def alterar_empresa():
    if not session.get("logado"):
        return redirect("/")
    id_empresa = _get_id_empresa()
    if not id_empresa:
        return redirect("/f10_cad_empresa")
    try:
        r = (supabase.table("tab_empresa")
             .select("*")
             .eq("id_empresa", id_empresa)
             .limit(1)
             .execute())
        emp = r.data[0] if r.data else {}
    except Exception:
        emp = {}
    # formata CNPJ para exibição
    cnpj_raw = str(emp.get("cnpj") or "")
    if len(cnpj_raw) == 14:
        emp["cnpj_fmt"] = f"{cnpj_raw[:2]}.{cnpj_raw[2:5]}.{cnpj_raw[5:8]}/{cnpj_raw[8:12]}-{cnpj_raw[12:]}"
    else:
        emp["cnpj_fmt"] = cnpj_raw
    return render_template(
        "F10_Cad_Empresa.html",
        titulo_sistema="Folha10-Simples",
        titulo_tela="Alterar Empresa",
        cliente_info=session.get("cliente_info", ""),
        empresa_info=session.get("empresa_info", ""),
        versao=ler_versao(),
        modo="alterar",
        empresa_dados=emp,
    )


@app.route("/api/alterar_empresa", methods=["POST"])
def api_alterar_empresa():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})
    id_empresa = _get_id_empresa()
    if not id_empresa:
        return jsonify({"ok": False, "msg": "Empresa não encontrada na sessão"})
    try:
        dados = request.get_json()
        if not dados:
            return jsonify({"ok": False, "msg": "Dados não recebidos"})
        # Simples Nacional e obrigatorio (defesa em profundidade)
        _is = str(dados.get("ind_simples") or "").strip().upper()
        if _is not in ("S", "N"):
            return jsonify({"ok": False,
                "msg": "Informe se a empresa e optante pelo Simples Nacional (Sim ou Nao)."})
        dados["ind_simples"] = _is
        # % adiantamento do 13º: inteiro entre 10 e 90 (default 50)
        _erro_p13 = _validar_per_adianta13(dados)
        if _erro_p13:
            return jsonify({"ok": False, "msg": _erro_p13})
        dados.pop("cnpj",       None)
        dados.pop("id_cliente", None)
        dados.pop("id_empresa", None)
        dados.pop("tp_insc",    None)
        resposta = (supabase.table("tab_empresa")
                    .update(dados)
                    .eq("id_empresa", id_empresa)
                    .execute())
        if not resposta.data:
            return jsonify({"ok": False, "msg": "Sem retorno do banco"})
        return jsonify({"ok": True})
    except Exception as e:
        print("Erro /api/alterar_empresa:", str(e))
        return jsonify({"ok": False, "msg": str(e)})


@app.route("/api/gravar_empresa", methods=["POST"])
def api_gravar_empresa():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})

    try:
        dados = request.get_json()
        if not dados:
            return jsonify({"ok": False, "msg": "Dados não recebidos"})

        # Simples Nacional e obrigatorio
        _is = str(dados.get("ind_simples") or "").strip().upper()
        if _is not in ("S", "N"):
            return jsonify({"ok": False,
                "msg": "Informe se a empresa e optante pelo Simples Nacional (Sim ou Nao)."})
        dados["ind_simples"] = _is
        # % adiantamento do 13º: inteiro entre 10 e 90 (default 50)
        _erro_p13 = _validar_per_adianta13(dados)
        if _erro_p13:
            return jsonify({"ok": False, "msg": _erro_p13})

        id_cliente_sess = session.get("id_cliente", 1)
        dados["id_cliente"] = id_cliente_sess
        dados["tp_insc"] = "1"

        # Este endpoint grava SEMPRE uma empresa NOVA (o front usa
        # /api/alterar_empresa quando esta em modo de edicao). Se o CNPJ ja
        # existir PARA ESTE CLIENTE, e cadastro duplicado -> orienta a alterar.
        cnpj_norm = so_numeros(str(dados.get("cnpj") or ""))
        if cnpj_norm:
            _ja_existe = (supabase.table("tab_empresa")
                          .select("id_empresa")
                          .eq("id_cliente", id_cliente_sess)
                          .eq("cnpj", cnpj_norm)
                          .limit(1).execute().data or [])
            if _ja_existe:
                return jsonify({"ok": False,
                    "msg": ("Esta empresa (CNPJ) ja esta cadastrada para este "
                            "cliente. Use 'Alterar Esta Empresa' para edita-la.")})

            _lic = _estado_licenca(id_cliente_sess)
            if _lic["sem_licenca"]:
                return jsonify({"ok": False,
                    "msg": ("Sua licenca esta zerada — nenhuma empresa pode "
                            "ser cadastrada. Renove em Comprar Licenca.")})
            if _lic["qtd_empresas"] > 0 and (_lic["atual_empresas"] + 1) > _lic["qtd_empresas"]:
                return jsonify({"ok": False,
                    "msg": (f"Limite de empresas da licenca atingido: voce ja cadastrou "
                            f"{_lic['atual_empresas']} empresa(s) e sua licenca permite no "
                            f"maximo {_lic['qtd_empresas']}. Amplie a licenca antes de "
                            "cadastrar mais.")})

        resposta = (
            supabase
            .table("tab_empresa")
            .insert(dados)
            .execute()
        )

        if not resposta.data:
            return jsonify({"ok": False, "msg": "Sem retorno do banco"})

        id_empresa = resposta.data[0].get("id_empresa")
        print(f"=== Empresa gravada id={id_empresa} cnpj={dados.get('cnpj')} ===")
        return jsonify({"ok": True, "id_empresa": id_empresa})

    except Exception as e:
        print("Erro /api/gravar_empresa:", str(e))
        return jsonify({"ok": False, "msg": str(e)})

# =========================================================
# FERIADOS — CONSTANTES
# =========================================================
FERIADOS_NACIONAIS_FIXOS = [
    ("99990101", "Confraternização Universal"),
    ("99990421", "Tiradentes"),
    ("99990501", "Dia do Trabalho"),
    ("99990907", "Independência do Brasil"),
    ("99991012", "Nossa Senhora Aparecida"),
    ("99991115", "Proclamação da República"),
    ("99991120", "Dia da Consciência Negra"),
    ("99991225", "Natal"),
]

def _fmt_dat_feriado(dat):
    """'99990101' → '01/01'  |  '20260421' → '21/04/2026'"""
    if not dat or len(dat) != 8:
        return dat
    yyyy, mm, dd = dat[:4], dat[4:6], dat[6:8]
    if yyyy == "9999":
        return f"{dd}/{mm}"
    return f"{dd}/{mm}/{yyyy}"

# =========================================================
# TELA FERIADOS
# =========================================================
@app.route("/cad_feriado")
def cad_feriado():
    if not session.get("logado"):
        return redirect("/")

    id_cliente = session.get("id_cliente")
    r = (
        supabase
        .table("tab_aux_feriados")
        .select("*")
        .or_(f"id_cliente.eq.{id_cliente},id_cliente.is.null")
        .order("dat_feriado")
        .execute()
    )
    hoje_str = datetime.now().strftime("%Y%m%d")
    feriados = []
    for row in (r.data or []):
        dat = row.get("dat_feriado", "")
        row["dat_fmt"] = _fmt_dat_feriado(dat)
        row["vencido"] = dat[:4] != "9999" and dat < hoje_str
        feriados.append(row)

    # Fixos (9999) primeiro, depois variáveis por data
    feriados.sort(key=lambda x: (0 if x["dat_feriado"].startswith("9999") else 1, x["dat_feriado"]))

    return render_template(
        "F10_Cad_Feriado.html",
        versao=ler_versao(),
        nome_cliente=session.get("nome", ""),
        empresa_info=session.get("empresa_info", ""),
        feriados=feriados
    )

