@app.route("/cad_verba")
def cad_verba():
    if not session.get("logado"):
        return redirect("/")

    id_cliente = session.get("id_cliente")

    # Carrega verbas do sistema (id_cliente=0) + verbas do cliente
    r = (
        supabase
        .table("tab_rubrica")
        .select("*")
        .in_("id_cliente", [0, id_cliente])
        .eq("situacao", "A")
        .order("cod_rubr")
        .execute()
    )

    import json
    verbas_json = json.dumps(r.data or [])

    # Carrega Natureza da Rubrica (eSocial Tabela 03)
    nat = (
        supabase
        .table("tab_tabela_total")
        .select("codigo,texto")
        .eq("num_tabela", 3)
        .order("codigo")
        .execute()
    )

    # Carrega codIncCP (101), codIncFGTS (102), codIncIRRF (103)
    inc_cp = (
        supabase
        .table("tab_tabela_total")
        .select("codigo,texto")
        .eq("num_tabela", 101)
        .neq("codigo", "DOC")
        .order("codigo")
        .execute()
    )

    inc_fgts = (
        supabase
        .table("tab_tabela_total")
        .select("codigo,texto")
        .eq("num_tabela", 102)
        .neq("codigo", "DOC")
        .order("codigo")
        .execute()
    )

    inc_irrf = (
        supabase
        .table("tab_tabela_total")
        .select("codigo,texto")
        .eq("num_tabela", 103)
        .neq("codigo", "DOC")
        .order("codigo")
        .execute()
    )

    inc_pis = (
        supabase
        .table("tab_tabela_total")
        .select("codigo,texto")
        .eq("num_tabela", 104)
        .neq("codigo", "DOC")
        .order("codigo")
        .execute()
    )

    # Verbas com cod_rubr < 1000 sao "do sistema" (id_cliente=0) e so podem
    # ser alteradas pelo administrador F10 (CPF 15313921487).
    is_admin_verbas = (str(session.get("cpf") or "") == CPF_ADMIN_F10)

    return render_template(
        "F10_Cad_Verba.html",
        versao=ler_versao(),
        nome_cliente=session.get("nome", ""),
        empresa_info=session.get("empresa_info", ""),
        verbas=r.data or [],
        verbas_json=verbas_json,
        nat_rubricas=nat.data or [],
        inc_cp=inc_cp.data or [],
        inc_fgts=inc_fgts.data or [],
        inc_irrf=inc_irrf.data or [],
        inc_pis=inc_pis.data or [],
        is_admin_verbas=is_admin_verbas,
    )


