# =========================================================
# ANO/MÊS — HELPER
# =========================================================
def _get_id_empresa():
    """Retorna id_empresa: usa sessão (gravada no login) e só consulta o banco como fallback."""
    id_sess = session.get("id_empresa")
    if id_sess:
        return int(id_sess)
    # fallback: consulta banco pelo CNPJ
    cnpj = session.get("cnpj_empresa", "")
    if not cnpj:
        return 0
    try:
        r = supabase.table("tab_empresa").select("id_empresa").eq("cnpj", cnpj).execute()
        if r.data:
            val = r.data[0].get("id_empresa", 0) or 0
            session["id_empresa"] = val  # guarda para chamadas futuras
            return int(val)
    except Exception:
        pass
    return 0


def _refresh_situacao_folha():
    """Busca situação atual da folha no banco e atualiza a sessão. Retorna a situação."""
    try:
        id_empresa  = _get_id_empresa()
        id_cliente  = session.get("id_cliente")
        anomes      = str(session.get("anomes_atual") or "")
        anomes_tipo = str(session.get("anomes_tipo") or "N")
        if not anomes or not id_empresa:
            return str(session.get("anomes_situacao") or "A")
        r = (supabase.table("tab_anomes")
             .select("situacao")
             .eq("id_cliente", id_cliente)
             .eq("id_empresa", id_empresa)
             .eq("ano_mes", int(anomes))
             .eq("tipo", anomes_tipo)
             .limit(1)
             .execute())
        if r.data:
            sit = str(r.data[0].get("situacao") or "A")
            session["anomes_situacao"] = sit
            return sit
    except Exception:
        pass
    return str(session.get("anomes_situacao") or "A")


# Mapa de rótulos de situação da folha (usado nas mensagens de validação)
_SIT_FOLHA_LABEL = {
    "A": "Aberta",
    "X": "Aberta",
    "C": "Calculada",
    "F": "Fechada",
    "P": "Processada",
}


def _folha_aberta_no_esocial(id_empresa=None, ano_mes=None):
    """True se a folha do período está Aberta no eSocial.

    Regra: olha o ÚLTIMO evento entre S-1299 (fechamento) e S-1298 (reabertura)
    com recibo no período. Se o último for S-1298 a folha está reaberta;
    se for S-1299 está fechada; se não houver nenhum dos dois, está aberta."""
    try:
        ie = id_empresa or _get_id_empresa()
        am = str(ano_mes or session.get("anomes_atual") or "").strip()
        if not am or len(am) != 6:
            return True
        r = (supabase.table("tab_esocial")
             .select("layout, data_grava, hora_grava")
             .eq("id_empresa", ie)
             .in_("layout", ["1298", "1299"])
             .eq("ano_mes", int(am))
             .not_.is_("recibo", "null")
             .neq("recibo", "")
             .order("data_grava", desc=True)
             .order("hora_grava", desc=True)
             .limit(1)
             .execute())
        if not r.data:
            return True
        # Aberta se o último evento foi S-1298 (reabertura); fechada se S-1299.
        return str(r.data[0].get("layout") or "") == "1298"
    except Exception:
        return True


def _validar_folha_para_envio_esocial(layout, ano_mes=None, folha_tipo="N"):
    """
    Valida se o status da folha permite o envio do evento eSocial.

    Regra:
    - Eventos periódicos (S-1200, S-1210, S-1298, S-1299): folha DO PERÍODO
      do evento deve estar FECHADA (situacao = 'F').
    - Eventos não periódicos (tabelas S-1000..S-1099 e eventos S-2xxx): folha
      ATUAL (da sessão) deve estar ABERTA (situacao = 'A' ou 'X').

    Retorna (ok: bool, msg: str). Em caso de OK, msg é "".
    """
    lay = str(layout or "").strip()
    is_periodico = lay.startswith("12")  # S-1200, S-1210, S-1298, S-1299

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    if is_periodico:
        if not ano_mes:
            return (False, "Período do evento não informado — não é possível validar status da folha.")
        try:
            r = (supabase.table("tab_anomes")
                 .select("situacao")
                 .eq("id_cliente", id_cliente)
                 .eq("id_empresa", id_empresa)
                 .eq("ano_mes", int(ano_mes))
                 .eq("tipo", str(folha_tipo or "N"))
                 .limit(1)
                 .execute())
            if not r.data:
                am = str(ano_mes)
                fmt = f"{am[4:6]}/{am[0:4]}" if len(am) == 6 else am
                return (False, f"Folha {fmt} não encontrada — não é possível enviar evento periódico.")
            sit = str(r.data[0].get("situacao") or "")
            if sit != "F":
                am = str(ano_mes)
                fmt = f"{am[4:6]}/{am[0:4]}" if len(am) == 6 else am
                lbl = _SIT_FOLHA_LABEL.get(sit, sit or "indefinida")
                return (False, f"Eventos periódicos só podem ser enviados com folha FECHADA. Folha {fmt} está {lbl}.")
        except Exception as e:
            return (False, f"Erro ao validar status da folha: {e}")
    else:
        sit = _refresh_situacao_folha()
        if sit not in ("A", "X"):
            am = str(session.get("anomes_atual") or "")
            fmt = f"{am[4:6]}/{am[0:4]}" if len(am) == 6 else am
            lbl = _SIT_FOLHA_LABEL.get(sit, sit or "indefinida")
            return (False, f"Eventos não periódicos só podem ser enviados com folha ABERTA. Folha atual {fmt} está {lbl}.")

    return (True, "")


# =========================================================
# ANO/MÊS — TELA
# =========================================================
@app.route("/cad_anomes")
def cad_anomes():
    if not session.get("logado"):
        return redirect("/")

    id_cliente = session.get("id_cliente")
    id_empresa = _get_id_empresa()

    try:
        r = (
            supabase.table("tab_anomes")
            .select("*")
            .eq("id_cliente", id_cliente)
            .eq("id_empresa", id_empresa)
            .order("ano_mes", desc=True)
            .order("tipo")
            .execute()
        )
        rows = r.data or []
        # Formata datas yyyymmdd → dd/mm/yyyy para exibição
        for row in rows:
            for campo in ("data_falta1", "data_falta2"):
                v = row.get(campo) or ""
                if len(v) == 8:
                    row[campo + "_fmt"] = f"{v[6:8]}/{v[4:6]}/{v[0:4]}"
                else:
                    row[campo + "_fmt"] = ""
        anomes_list = rows
    except Exception:
        anomes_list = []

    # Calcula próximo ano/mês sugerido
    from datetime import date as _date
    hoje = _date.today()
    if anomes_list:
        ultimo = anomes_list[0]["ano_mes"]  # mais recente (ordem desc)
        _ano = int(ultimo[:4])
        _mes = int(ultimo[4:6])
        _mes += 1
        if _mes > 12:
            _mes = 1
            _ano += 1
        proximo_anomes = f"{_ano:04d}{_mes:02d}"
    else:
        proximo_anomes = f"{hoje.year:04d}{hoje.month:02d}"

    # Busca data_limite do cliente (formato "YYYY-MM" → "YYYYMM")
    limite_anomes = ""
    try:
        rl = (
            supabase.table("tab_cliente")
            .select("data_limite")
            .eq("id_cliente", id_cliente)
            .limit(1)
            .execute()
        )
        dl = (rl.data or [{}])[0].get("data_limite") or ""
        if dl and len(dl) == 7:          # "YYYY-MM"
            limite_anomes = dl[:4] + dl[5:7]
    except Exception:
        pass

    modo = request.args.get("modo", "")

    return render_template(
        "F10_Cad_AnoMes.html",
        versao=ler_versao(),
        nome_cliente=session.get("nome", ""),
        empresa_info=session.get("empresa_info", ""),
        anomes_list=anomes_list,
        proximo_anomes=proximo_anomes,
        limite_anomes=limite_anomes,
        modo=modo,
    )


