# FUNCIONÁRIOS — API ALTERAR
# =========================================================
@app.route("/api/funcionario/alterar", methods=["POST"])
def api_funcionario_alterar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})

    sit = str(session.get("anomes_situacao") or "")
    if sit in ("C", "F"):
        sit_label = "Calculada" if sit == "C" else "Fechada"
        return jsonify({"ok": False, "msg": f"Folha está {sit_label} — alteração de funcionário não permitida."})

    d          = request.get_json() or {}
    func_id    = d.get("id")
    id_empresa = _get_id_empresa()

    if not func_id:
        return jsonify({"ok": False, "msg": "ID do funcionário não informado"})

    nome = (d.get("nome") or "").strip()
    cpf  = (d.get("cpf")  or "").strip()
    if not nome:
        return jsonify({"ok": False, "msg": "Nome obrigatório"})
    for campo, label in [
        ("codCateg",   "Categoria eSocial"),
        ("sexo",       "Sexo"),
        ("racaCor",    "Raça / Cor"),
        ("dtNascto",   "Data de Nascimento"),
        ("dtAdm",      "Data de Admissão"),
        ("tpAdmissao", "Tipo de Admissão"),
        ("tpContr",    "Tipo de Contrato"),
        ("tpRegJor",   "Regime de Jornada"),
        ("CBOFuncao",  "CBO da Função"),
    ]:
        if not (d.get(campo) or "").strip():
            return jsonify({"ok": False, "msg": f"{label} obrigatório"})

    def sv(f):
        v = (d.get(f) or "").strip()
        return v if v else None

    campos = {
        "cpf":          cpf,
        "nome":         nome,
        "codcateg":     sv("codCateg"),
        "sexo":         sv("sexo"),
        "racacor":      sv("racaCor"),
        "dtnascto":     sv("dtNascto"),
        "dtadm":        sv("dtAdm"),
        "tpadmissao":   sv("tpAdmissao"),
        "tpcontr":      sv("tpContr"),
        "tpregjor":     sv("tpRegJor"),
        "cbofuncao":    sv("CBOFuncao"),
        "natatividade": "1",
    }
    opcionais_alt = {
        "nomeR":             "nomer",
        "nomeMae":           "nomemae",
        "UndSalFixo":        "undsalfixo",
        "dtTerm":            "datarescisao",
        "ClauAssec":         "clausassec",
        "objDet":            "objdet",
        "natEstagio":        "est_natestagio",
        "nivEstagio":        "est_nivestagio",
        "dtPrevTerm":        "est_dtprevterm",
        "est_instNome":      "est_inst_nome",
        "est_instLograd":    "est_inst_lograd",
        "est_instNr":        "est_inst_nr",
        "est_instCep":       "est_inst_cep",
        "est_instMunic":     "est_inst_munic",
        "est_instUf":        "est_inst_uf",
        "lt_tpInsc":         "lt_tpinsc",
        "lt_nrInsc":         "lt_nrinsc",
        "qtdHrsSem":         "qtdhrssem",
        "qtdHrsMes":         "qtdhrsmes",
        "tpJornada":         "tpjornada",
        "tmpParc":           "tmpparc",
        "horNoturno":        "hornoturno",
        "id_tab_Horario":    "id_tab_horario",
        "estCiv":            "estciv",
        "grauInstr":         "grauinstr",
        "paisNascto":        "paisnascto",
        "paisNac":           "paisnac",
        "indAdmissao":       "indadmissao",
        "dtTransf":          "dttransf",
        "cnpjTransf":        "cnpjtransf",
        "matriculaTransf":   "matriculatransf",
        "nrProcTrab":        "nrproctrab",
        "cnpjSindCategProf": "cnpjsindcategprof",
        "tomador_tpInsc":    "tomador_tpinsc",
        "tomador_nrInsc":    "tomador_nrinsc",
        "banco_Numero":      "banco_numero",
        "banco_Agencia":     "banco_agencia",
        "banco_AgenciaDV":   "banco_agenciadv",
        "banco_Conta":       "banco_conta",
        "banco_ContaDV":     "banco_contadv",
        "ender_dscLograd":   "ender_dsclograd",
        "ender_nrLograd":    "ender_nrlograd",
        "ender_complemento": "ender_complemento",
        "ender_bairro":      "ender_bairro",
        "ender_cep":         "ender_cep",
        "ender_codMunic":    "ender_codmunic",
        "ender_uf":          "ender_uf",
        "ind_Imigrante":     "ind_imigrante",
        "imigrante_tmpResid":"imigrante_tmpresid",
        "condIng":           "conding",
        "defFisica":         "deffisica",
        "defVisual":         "defvisual",
        "defAuditiva":       "defauditiva",
        "defMental":         "defmental",
        "defIntelectual":    "defintelectual",
        "infoCota":          "infocota",
        "indAprend":         "indaprend",
        "cnpjEntQual":       "cnpjentqual",
        "Aprend_tpInsc":     "aprend_tpinsc",
        "Aprend_cnpjPrat":   "aprend_cnpjprat",
    }
    for payload_key, db_col in opcionais_alt.items():
        v = sv(payload_key)
        if v is not None:
            campos[db_col] = v

    # Bloqueio: a categoria eSocial (codCateg) só pode mudar se o S-2200 ainda
    # NÃO foi enviado, ou se foi enviado e anulado por S-3000. Com S-2200 ativo
    # a categoria fica travada — o eSocial não aceita troca de categoria com a
    # admissão vigente. Defesa no backend (a tela também desabilita o campo).
    novo_categ = (campos.get("codcateg") or "").strip()
    try:
        _cur = (supabase.table("tab_cad")
                .select("codcateg, matricula")
                .eq("id", func_id).eq("id_empresa", id_empresa)
                .limit(1).execute().data or [])
    except Exception:
        _cur = []
    if _cur:
        _cat_atual = str(_cur[0].get("codcateg") or "").strip()
        if novo_categ != _cat_atual and _s2200_ativo(id_empresa, _cur[0].get("matricula")):
            return jsonify({"ok": False, "msg":
                "Categoria eSocial não pode ser alterada: o S-2200 deste "
                "funcionário já foi enviado. Para trocar a categoria, anule "
                "antes o S-2200 (envio do S-3000)."})

    # Monta observação com campos alterados
    _labels = {
        "cpf":"CPF","nome":"Nome","nomer":"NomeR","nomemae":"NomeMãe",
        "codcateg":"Categ","sexo":"Sexo","racacor":"Raça","estciv":"EstCiv",
        "grauinstr":"Instr","dtnascto":"DtNasc","paisnascto":"PaisNasc",
        "paisnac":"PaisNac","dtadm":"DtAdm","tpadmissao":"TpAdm",
        "indadmissao":"IndAdm","tpcontr":"TpContr","datarescisao":"DtRescisao",
        "clausassec":"ClauAssec","objdet":"ObjDet","tpregjor":"RegJor",
        "est_natestagio":"NatEstag","est_nivestagio":"NivEstag","est_dtprevterm":"DtPrevTerm",
        "est_inst_nome":"InstNome","est_inst_lograd":"InstLogr","est_inst_nr":"InstNr",
        "est_inst_cep":"InstCEP","est_inst_munic":"InstMunic","est_inst_uf":"InstUF",
        "cbofuncao":"CBO","cnpjsindcategprof":"Sind","undsalfixo":"UndSal",
        "lt_tpinsc":"LtTp","lt_nrinsc":"LtNr","qtdhrssem":"HrSem",
        "qtdhrsmes":"HrMes","tpjornada":"TpJorn","tmpparc":"TmpParc",
        "hornoturno":"HorNot","id_tab_horario":"Horario",
        "ender_cep":"CEP","ender_dsclograd":"Logr","ender_nrlograd":"NrLogr",
        "ender_complemento":"Compl","ender_bairro":"Bairro",
        "ender_codmunic":"CodMun","ender_uf":"UF",
        "banco_numero":"Banco","banco_agencia":"Agencia",
        "banco_agenciadv":"AgDV","banco_conta":"Conta","banco_contadv":"ContaDV",
        "ind_imigrante":"Imig","imigrante_tmpresid":"TmpRes","conding":"CondIng",
        "deffisica":"DefFis","defvisual":"DefVis","defauditiva":"DefAud",
        "defmental":"DefMen","defintelectual":"DefInt",
        "infocota":"InfoCota","indaprend":"Aprend",
        "tomador_tpinsc":"TomTp","tomador_nrinsc":"TomNr",
    }
    # Campos que disparam S-2205 (dados pessoais)
    _S2205 = {
        "nome", "nomer", "sexo", "racacor", "estciv", "grauinstr",
        "dtnascto", "paisnascto", "paisnac", "nomemae",
        "ender_dsclograd", "ender_nrlograd", "ender_complemento",
        "ender_bairro", "ender_cep", "ender_codmunic", "ender_uf",
        "fone_princ", "email_princ",
        "deffisica", "defvisual", "defauditiva", "defmental", "defintelectual", "infocota",
    }
    # Campos que disparam S-2206 (dados contratuais)
    _S2206 = {
        "codcateg", "cbofuncao", "nmcargo", "vrsalfx", "undsalfixo",
        "tpregjor", "natatividade", "qtdhrssem", "tpjornada",
        "tmpparc", "hornoturno", "tpcontr", "datarescisao",
        "lt_tpinsc", "lt_nrinsc",
    }

    obs = f"ALT funcionario: {cpf}"
    precisa_2205 = False
    precisa_2206 = False
    try:
        atual = supabase.table("tab_cad").select("*").eq("id", func_id).execute()
        if atual.data:
            reg = atual.data[0]
            partes = []
            for col, label in _labels.items():
                novo = campos.get(col)
                if novo is None:
                    continue
                velho = str(reg.get(col) or "").strip()
                novo_s = str(novo).strip()
                if novo_s != velho:
                    partes.append(f"{label}: '{velho}'→'{novo_s}'")
                    if col in _S2205:
                        precisa_2205 = True
                    if col in _S2206:
                        precisa_2206 = True
            if partes:
                obs += " | " + " | ".join(partes)
    except Exception:
        pass

    try:
        supabase.table("tab_cad").update(campos).eq("id", func_id).eq("id_empresa", id_empresa).execute()
        mat_raw = d.get("matricula")
        mat = int(mat_raw) if mat_raw else None
        gravar_log("FUNCIONARIO", obs, matricula=mat)

        # Gera pendências eSocial se houve alteração relevante.
        # TSVE / não-empregado (721/722/723/901) NÃO usa S-2205/S-2206 (são
        # eventos de empregado). A alteração deles seria via S-2306, ainda não
        # implementado — por ora não gera evento (melhor nada que evento errado).
        try:
            _categ_alt = int((campos.get("codcateg") or "0"))
        except (ValueError, TypeError):
            _categ_alt = 0
        _eh_tsve = _categ_alt in (721, 722, 723, 901)
        if mat and not _eh_tsve and (precisa_2205 or precisa_2206):
            _agora   = datetime.now()
            _anomes  = str(session.get("anomes_atual") or "")
            _id_cli  = session.get("id_cliente")
            _ts      = _agora.strftime("%Y%m%d%H%M%S")
            for _lay in (["2205"] if precisa_2205 else []) + (["2206"] if precisa_2206 else []):
                try:
                    supabase.table("tab_esocial").insert({
                        "id_cliente": _id_cli,
                        "id_empresa": id_empresa,
                        "data_cad":   _agora.strftime("%Y%m%d"),
                        "hora_cad":   _agora.strftime("%H%M"),
                        "id_remessa": f"{_ts}{_lay}",
                        "ano_mes":    int(_anomes) if len(_anomes) == 6 else None,
                        "folha_tipo": "N",
                        "layout":     _lay,
                        "matricula":  mat,
                        "codigo2":    0,
                    }).execute()
                except Exception:
                    pass

        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


