@app.route("/api/funcionario/check_cpf")
def api_funcionario_check_cpf():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})
    cpf = request.args.get("cpf", "").strip()
    if not cpf:
        return jsonify({"ok": True})
    id_empresa = _get_id_empresa()
    try:
        r = (
            supabase.table("tab_cad")
            .select("id, situacao, matricula")
            .eq("id_empresa", id_empresa)
            .eq("cpf", cpf)
            .execute()
        )
        for row in (r.data or []):
            if row.get("situacao") == "A":
                mat = row.get("matricula", "")
                return jsonify({"ok": False, "msg": f"CPF já possui vínculo ativo — matrícula {mat}"})
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


# =========================================================
# FUNCIONÁRIOS — API INCLUIR
# =========================================================
@app.route("/api/funcionario/incluir", methods=["POST"])
def api_funcionario_incluir():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})

    sit = str(session.get("anomes_situacao") or "")
    if sit in ("C", "F"):
        sit_label = "Calculada" if sit == "C" else "Fechada"
        return jsonify({"ok": False, "msg": f"Folha está {sit_label} — inclusão de funcionário não permitida."})

    d          = request.get_json() or {}
    id_cliente = session.get("id_cliente")
    id_empresa = _get_id_empresa()

    # Bloqueia se a licenca esta zerada ou se o novo funcionario excederia o
    # limite contratado.
    _lic = _estado_licenca(id_cliente)
    if _lic["sem_licenca"]:
        return jsonify({"ok": False,
            "msg": ("Sua licenca esta zerada — nenhum funcionario pode ser "
                    "cadastrado. Renove na tela de Comprar Licenca.")})
    if _lic["qtd_funcionarios"] > 0 and (_lic["atual_funcionarios"] + 1) > _lic["qtd_funcionarios"]:
        return jsonify({"ok": False,
            "msg": (f"Limite de funcionarios da licenca atingido "
                    f"({_lic['atual_funcionarios']}/{_lic['qtd_funcionarios']}). "
                    "Amplie a licenca antes de cadastrar mais.")})

    cpf  = (d.get("cpf")  or "").strip()
    nome = (d.get("nome") or "").strip()

    if not cpf:
        return jsonify({"ok": False, "msg": "CPF obrigatório"})
    if not nome:
        return jsonify({"ok": False, "msg": "Nome obrigatório"})
    for campo, label in [
        ("codCateg",   "Categoria eSocial"),
        ("sexo",       "Sexo"),
        ("racaCor",    "Raça / Cor"),
        ("dtNascto",   "Data de Nascimento"),
        ("dtAdm",      "Data de Admissão"),
        ("tpAdmissao", "Tipo de Admissão"),
        ("tpContr",    "Tipo de Contrato"),
        ("tpRegJor",   "Regime de Jornada"),
        ("CBOFuncao",  "CBO da Função"),
    ]:
        if not (d.get(campo) or "").strip():
            return jsonify({"ok": False, "msg": f"{label} obrigatório"})

    # Duplicidade: CPF ativo na mesma empresa
    try:
        dup_cpf = (
            supabase.table("tab_cad")
            .select("id, situacao")
            .eq("id_empresa", id_empresa)
            .eq("cpf", cpf)
            .execute()
        )
        for row in (dup_cpf.data or []):
            if row.get("situacao") == "A":
                return jsonify({"ok": False, "msg": f"CPF {cpf} já possui vínculo ativo nesta empresa"})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao verificar CPF: {e}"})

    # Duplicidade: matrícula na mesma empresa
    matricula_raw = (d.get("matricula") or "").strip()
    if matricula_raw:
        try:
            dup_mat = (
                supabase.table("tab_cad")
                .select("id")
                .eq("id_empresa", id_empresa)
                .eq("matricula", int(matricula_raw))
                .execute()
            )
            if dup_mat.data:
                return jsonify({"ok": False, "msg": f"Matrícula {matricula_raw} já existe nesta empresa"})
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Erro ao verificar matrícula: {e}"})

    def sv(f):
        v = (d.get(f) or "").strip()
        return v if v else None

    campos = {
        "id_cliente":    id_cliente,
        "id_empresa":    id_empresa,
        "situacao":      "A",
        "cpf":           cpf,
        "nome":          nome,
        "codcateg":      sv("codCateg"),
        "sexo":          sv("sexo"),
        "racacor":       sv("racaCor"),
        "dtnascto":      sv("dtNascto"),
        "dtadm":         sv("dtAdm"),
        "tpadmissao":    sv("tpAdmissao"),
        "tpcontr":       sv("tpContr"),
        "tpregjor":      sv("tpRegJor"),
        "cbofuncao":     sv("CBOFuncao"),
        "natatividade":  "1",
        "centrocusto":   sv("centrocusto") or None,
    }
    # mapeamento campo_payload → coluna_db
    opcionais = {
        "matricula":         "matricula",
        "matricula_eS":      "matricula_es",
        "filial":            "filial",
        "nomeR":             "nomer",
        "nomeMae":           "nomemae",
        "UndSalFixo":        "undsalfixo",
        "dtTerm":            "datarescisao",
        "ClauAssec":         "clausassec",
        "objDet":            "objdet",
        "natEstagio":        "est_natestagio",
        "nivEstagio":        "est_nivestagio",
        "dtPrevTerm":        "est_dtprevterm",
        "est_instNome":      "est_inst_nome",
        "est_instLograd":    "est_inst_lograd",
        "est_instNr":        "est_inst_nr",
        "est_instCep":       "est_inst_cep",
        "est_instMunic":     "est_inst_munic",
        "est_instUf":        "est_inst_uf",
        "lt_tpInsc":         "lt_tpinsc",
        "lt_nrInsc":         "lt_nrinsc",
        "qtdHrsSem":         "qtdhrssem",
        "qtdHrsMes":         "qtdhrsmes",
        "tpJornada":         "tpjornada",
        "tmpParc":           "tmpparc",
        "horNoturno":        "hornoturno",
        "id_tab_Horario":    "id_tab_horario",
        "estCiv":            "estciv",
        "grauInstr":         "grauinstr",
        "paisNascto":        "paisnascto",
        "paisNac":           "paisnac",
        "indAdmissao":       "indadmissao",
        "dtTransf":          "dttransf",
        "cnpjTransf":        "cnpjtransf",
        "matriculaTransf":   "matriculatransf",
        "nrProcTrab":        "nrproctrab",
        "cnpjSindCategProf": "cnpjsindcategprof",
        "tomador_tpInsc":    "tomador_tpinsc",
        "tomador_nrInsc":    "tomador_nrinsc",
        "banco_Numero":      "banco_numero",
        "banco_Agencia":     "banco_agencia",
        "banco_AgenciaDV":   "banco_agenciadv",
        "banco_Conta":       "banco_conta",
        "banco_ContaDV":     "banco_contadv",
        "ender_dscLograd":   "ender_dsclograd",
        "ender_nrLograd":    "ender_nrlograd",
        "ender_complemento": "ender_complemento",
        "ender_bairro":      "ender_bairro",
        "ender_cep":         "ender_cep",
        "ender_codMunic":    "ender_codmunic",
        "ender_uf":          "ender_uf",
        "ind_Imigrante":     "ind_imigrante",
        "imigrante_tmpResid":"imigrante_tmpresid",
        "condIng":           "conding",
        "defFisica":         "deffisica",
        "defVisual":         "defvisual",
        "defAuditiva":       "defauditiva",
        "defMental":         "defmental",
        "defIntelectual":    "defintelectual",
        # "reabReadap":      "reabredap",  # verificar nome real no banco
        "infoCota":          "infocota",
        "indAprend":         "indaprend",
        "cnpjEntQual":       "cnpjentqual",
        "Aprend_tpInsc":     "aprend_tpinsc",
        "Aprend_cnpjPrat":   "aprend_cnpjprat",
    }
    for payload_key, db_col in opcionais.items():
        v = sv(payload_key)
        if v is not None:
            campos[db_col] = v

    # vrSalFx: inteiro com centavos embutidos
    vr = d.get("vrSalFx")
    if vr is not None:
        try:
            campos["vrsalfx"] = int(vr)
        except (ValueError, TypeError):
            pass

    try:
        supabase.table("tab_cad").insert(campos).execute()
        mat = int(matricula_raw) if matricula_raw else None
        gravar_log("FUNCIONARIO", f"INC funcionario: {cpf} = {nome[:30]}", matricula=mat)
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    # Registra remessa eSocial: empregado → S-2200; não-empregado
    # (TSVE 721/722/723/901) → S-2300 (evtTSVInicio).
    try:
        agora       = datetime.now()
        anomes_tp   = str(session.get("anomes_tipo")   or "")
        anomes_am   = str(session.get("anomes_atual")  or "")
        folha_tipo_es = "1" if anomes_tp in ("1", "A") else "N"
        try:
            _categ_es = int((d.get("codCateg") or "0").strip())
        except (ValueError, TypeError):
            _categ_es = 0
        layout_es = "2300" if _categ_es in (721, 722, 723, 901) else "2200"
        supabase.table("tab_esocial").insert({
            "id_cliente": id_cliente,
            "id_empresa": id_empresa,
            "data_cad":   agora.strftime("%Y%m%d"),
            "hora_cad":   agora.strftime("%H%M"),
            "id_remessa": agora.strftime("%Y%m%d%H%M%S"),
            "ano_mes":    int(anomes_am) if anomes_am else None,
            "folha_tipo": folha_tipo_es,
            "layout":     layout_es,
            "matricula":  mat,
            "codigo2":    0,
        }).execute()
    except Exception:
        pass  # falha no eSocial não desfaz a inclusão do funcionário

    # Insalubridade (op1=31) e Periculosidade (op1=41)
    anomes_ev  = str(session.get("anomes_atual") or "")
    dtadm_cad  = str(d.get("dtAdm") or "").strip()
    adm_ok_ev  = len(dtadm_cad) != 8 or dtadm_cad[:6] <= anomes_ev
    if mat and len(anomes_ev) == 6 and adm_ok_ev:
        data1i_ev = anomes_ev + "01"
        folha_ev  = int(anomes_ev)
        for flag_key, per_key, op1_val in [
            ("hasInsalubridade",  "perInsalubridade",  31),
            ("hasPericulosidade", "perPericulosidade", 41),
        ]:
            if d.get(flag_key):
                per_raw = d.get(per_key)
                try:
                    ref1_val = int(round(float(per_raw) * 100)) if per_raw is not None else None
                except (TypeError, ValueError):
                    ref1_val = None
                try:
                    supabase.table("tab_eventos").insert({
                        "id_cliente": id_cliente,
                        "id_empresa": id_empresa,
                        "matricula":  mat,
                        "folha":      folha_ev,
                        "op1":        op1_val,
                        "data1i":     data1i_ev,
                        "ref1":       ref1_val,
                    }).execute()
                except Exception:
                    pass

    return jsonify({"ok": True})


# =========================================================
# LIMPEZA DE FUNCIONARIO — apaga matricula em todas as tabelas
# =========================================================
# Tabelas que tem o campo `matricula` e devem ser limpas. tab_log NAO entra
# (e o registro de auditoria e deve ser preservado).
_LIMPEZA_TABELAS = (
    "tab_mov", "tab_total", "tab_eventos", "tab_esocial",
    "tab_dependentes", "tab_acidente", "tab_mov_fixo", "tab_pensao",
)

# O proprio S-3000 grava uma linha com matricula e recibo (ver envio do S-3000).
# Se ele entrasse na regra de "layout com recibo ativo", excluir o S-2200
# passaria a bloquear a limpeza para sempre — o inverso da regra.
_LIMPEZA_LAYOUTS_IGNORAR = ("3000",)


def _limpeza_regras(id_cliente, id_empresa, matricula):
    """Regras de bloqueio da limpeza. Fonte unica para validar e executar.
       Devolve (pode_limpar, msg, detalhes)."""
    detalhes = {"eventos_ativos": [], "dtadm": None, "folha_ativa": None}

    # --- Regra 1: admissao tem que ser no mes da folha ativa ---
    folha = str(session.get("anomes_atual") or "").strip()
    detalhes["folha_ativa"] = folha
    if not folha or len(folha) != 6:
        return False, "Folha ativa nao definida. Abra uma folha antes de limpar.", detalhes
    try:
        r = (supabase.table("tab_cad")
             .select("dtadm")
             .eq("id_cliente", id_cliente)
             .eq("id_empresa", id_empresa)
             .eq("matricula", matricula)
             .limit(1).execute())
        if not r.data:
            return False, "Funcionario nao encontrado.", detalhes
        dtadm = int(r.data[0].get("dtadm") or 0)
    except Exception as e:
        return False, f"Erro ao ler admissao: {e}", detalhes

    detalhes["dtadm"] = dtadm
    if not dtadm:
        return False, "Funcionario sem data de admissao. Limpeza bloqueada.", detalhes
    if (dtadm // 100) != int(folha):
        d = str(dtadm).zfill(8)
        return False, (
            f"Bloqueado: a limpeza so vale para admitidos no mes da folha ativa "
            f"({folha[4:6]}/{folha[0:4]}). Este funcionario foi admitido em "
            f"{d[6:8]}/{d[4:6]}/{d[0:4]}."), detalhes

    # --- Regra 2: nenhum evento eSocial com recibo ativo ---
    # "Ativo" = tem recibo e nao foi anulado por S-3000 (observacao_erro=EXCLUIDO).
    try:
        evs = (supabase.table("tab_esocial")
               .select("id_esocial, layout, recibo, observacao_erro, data_grava, hora_grava")
               .eq("id_cliente", id_cliente)
               .eq("id_empresa", id_empresa)
               .eq("matricula", matricula)
               .not_.is_("recibo", "null").neq("recibo", "")
               .execute().data or [])
    except Exception as e:
        return False, f"Erro ao validar eSocial: {e}", detalhes

    ativos = []
    for s in evs:
        if str(s.get("layout") or "") in _LIMPEZA_LAYOUTS_IGNORAR:
            continue
        if (s.get("observacao_erro") or "").strip().upper() == "EXCLUIDO":
            continue  # anulado por S-3000 — nao bloqueia
        ativos.append({
            "id_esocial": s["id_esocial"],
            "layout":     s.get("layout"),
            "recibo":     s.get("recibo"),
            "data_grava": s.get("data_grava"),
            "hora_grava": s.get("hora_grava"),
        })
    detalhes["eventos_ativos"] = ativos

    if ativos:
        lst = ", ".join(f"S-{a['layout']}" for a in ativos)
        tem_2200 = any(a["layout"] == "2200" for a in ativos)
        msg = (f"Bloqueado: existem {len(ativos)} evento(s) eSocial enviado(s) e "
               f"ainda nao excluido(s) via S-3000 ({lst}). "
               f"Envie o S-3000 de cada um antes de limpar.")
        if tem_2200:
            msg += " O S-2200 (admissao) esta ativo — comece por ele."
        return False, msg, detalhes

    return True, "", detalhes


