@app.route("/cad_funcionario")
def cad_funcionario():
    if not session.get("logado"):
        return redirect("/")

    cpf_cliente = so_numeros(session.get("cpf", ""))
    id_cliente  = session.get("id_cliente")

    # Local de Trabalho: empresa própria = tipo 1 CNPJ
    cnpj      = so_numeros(session.get("cnpj_empresa", ""))
    lt_tpInsc = "1" if cnpj else ""
    lt_nrInsc = cnpj
    filial    = cnpj[-6:] if len(cnpj) >= 6 else cnpj

    # Funções do cliente
    funcoes = []
    try:
        r = (
            supabase
            .table("tab_funcao_cli")
            .select("id_funcao_total, nome_resumido")
            .eq("id_cliente", id_cliente)
            .eq("situacao", "A")
            .order("nome_resumido")
            .execute()
        )
        cli_rows = r.data or []
        if not cli_rows:
            return redirect("/cad_funcao?aviso=sem_funcao")
        ids = [row["id_funcao_total"] for row in cli_rows if row.get("id_funcao_total")]
        mapa_cbo = {}
        if ids:
            rt = supabase.table("tab_aux_funcao_total").select("id, cbo_codigo").in_("id", ids).execute()
            mapa_cbo = {row["id"]: row.get("cbo_codigo", "") for row in (rt.data or [])}
        for row in cli_rows:
            cbo = str(mapa_cbo.get(row.get("id_funcao_total"), "") or "").strip()
            funcoes.append({"cbo": cbo, "nome": row.get("nome_resumido", "")})
    except Exception:
        pass

    # Sindicatos do cliente
    sindicatos = []
    try:
        r = (
            supabase
            .table("tab_aux_sindicatos")
            .select("cnpj, nome_sindicato")
            .eq("id_cliente", id_cliente)
            .eq("situacao", "A")
            .order("nome_sindicato")
            .execute()
        )
        sindicatos = [
            {"cnpj": row.get("cnpj", ""), "nome": row.get("nome_sindicato", "")}
            for row in (r.data or [])
        ]
    except Exception:
        pass

    id_empresa = session.get("id_empresa")

    # Centros de Custo da empresa
    centros_custo = []
    try:
        r = (
            supabase
            .table("tab_cc")
            .select("codigo_cc, nomecc")
            .eq("id_cliente", id_cliente)
            .eq("id_empresa", id_empresa)
            .eq("situacao", "A")
            .order("codigo_cc")
            .execute()
        )
        centros_custo = r.data or []
    except Exception:
        pass

    # Filiais da empresa
    filiais_func = []
    try:
        r = (
            supabase
            .table("tab_filial")
            .select("cnpj, filial_nome")
            .eq("id_cliente", id_cliente)
            .eq("id_empresa", id_empresa)
            .eq("situacao", "A")
            .order("filial_nome")
            .execute()
        )
        filiais_func = [
            {"valor": row["cnpj"][-6:], "nome": row["filial_nome"], "cnpj": row["cnpj"]}
            for row in (r.data or [])
        ]
    except Exception:
        pass

    # Horários do cliente (+ horários de sistema id_cliente=0)
    horarios = []
    horarios_resumo = {}
    try:
        r = (
            supabase
            .table("tab_aux_horarios")
            .select("id_horario, nome_horario, horas_2a, horas_3a, horas_4a, "
                    "horas_5a, horas_6a, horas_sab, horas_dom")
            .in_("id_cliente", [id_cliente, 0])
            .eq("situacao", "A")
            .order("nome_horario")
            .execute()
        )
        for row in (r.data or []):
            hid = row.get("id_horario", "")
            horarios.append({
                "id":     hid,
                "id_fmt": str(hid or "").zfill(6),
                "nome":   row.get("nome_horario", ""),
            })
            horarios_resumo[str(hid)] = _resumo_horario(row)
    except Exception:
        pass
    horarios_resumo_json = json.dumps(horarios_resumo, ensure_ascii=False)

    # Categorias eSocial (Tabela 01)
    categorias = []
    try:
        r = (
            supabase
            .table("tab_tabela_total")
            .select("codigo, texto")
            .eq("num_tabela", 1)
            .neq("codigo", "DOC")
            .order("codigo")
            .execute()
        )
        categorias = r.data or []
    except Exception:
        pass

    modo  = request.args.get("modo",  "inclusao")
    aviso = request.args.get("aviso", "")

    return render_template(
        "F10_Cad_Funcionario.html",
        versao=ler_versao(),
        empresa_nome=session.get("empresa_info", ""),
        cliente_nome=session.get("nome", ""),
        empresa_lt_tpInsc=lt_tpInsc,
        empresa_lt_nrInsc=lt_nrInsc,
        filial=filial,
        funcoes=funcoes,
        sindicatos=sindicatos,
        horarios=horarios,
        horarios_resumo_json=horarios_resumo_json,
        categorias=categorias,
        centros_custo=centros_custo,
        filiais_func=filiais_func,
        modo=modo,
        aviso=aviso,
        folha_situacao=str(session.get("anomes_situacao") or ""),
        anomes_atual=str(session.get("anomes_atual") or ""),
    )


