# MOVIMENTO — API: lookup de verba/rubrica
# =========================================================
@app.route("/api/rubrica_lookup")
def api_rubrica_lookup():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    cod_str    = request.args.get("cod", "").strip()
    id_cliente = session.get("id_cliente")
    if not cod_str or not cod_str.isdigit():
        return jsonify({"ok": False, "msg": "Código inválido."})
    cod_int = int(cod_str)
    try:
        r = (supabase.table("tab_rubrica")
             .select("cod_rubr, dsc_rubr, tp_rubr, unid_verba, is_nao_digitar, id_cliente")
             .in_("id_cliente", [0, id_cliente])
             .eq("cod_rubr", cod_int)
             .eq("situacao", "A")
             .execute())
        if not r.data:
            return jsonify({"ok": False, "msg": "Verba não encontrada."})
        verbas = sorted(r.data, key=lambda v: 0 if v.get("id_cliente") != 0 else 1)
        v = verbas[0]
        if v.get("is_nao_digitar"):
            return jsonify({"ok": False, "msg": "Esta verba não pode ser digitada manualmente."})
        return jsonify({
            "ok":         True,
            "cod_rubr":   v.get("cod_rubr"),
            "dsc_rubr":   v.get("dsc_rubr") or "",
            "tp_rubr":    v.get("tp_rubr") or "",
            "unid_verba": v.get("unid_verba") or "V",
        })
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


# =========================================================
# MOVIMENTO — API: listar registros da folha ativa
# =========================================================
@app.route("/api/tab_mov_listar")
def api_tab_mov_listar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if not anomes:
        return jsonify({"ok": True, "registros": []})
    folha_int  = int(anomes)
    filtro_tipo = request.args.get("folha_tipo", "").strip().upper()[:1]
    try:
        q = (supabase.table("tab_mov")
             .select("id, matricula, cod_verba, qtd, valor, folha_tipo, origem")
             .eq("id_empresa", id_empresa)
             .eq("id_cliente", id_cliente)
             .eq("folha",      folha_int)
             .eq("situacao",   "A")
             .eq("origem",     "M"))
        if filtro_tipo in ("N", "F", "R"):
            q = q.eq("folha_tipo", filtro_tipo)
        r = q.order("id", desc=True).execute()
        registros_raw = r.data or []
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})

    if not registros_raw:
        return jsonify({"ok": True, "registros": []})

    mats = list({reg["matricula"] for reg in registros_raw if reg.get("matricula")})
    nomes_map = {}
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer")
                 .eq("id_empresa", id_empresa)
                 .in_("matricula", mats)
                 .execute())
        for f in (r_cad.data or []):
            nomes_map[f["matricula"]] = (f.get("nomer") or f.get("nome") or "").strip()
    except Exception:
        pass

    cod_verbas = list({reg["cod_verba"] for reg in registros_raw if reg.get("cod_verba") is not None})
    verbas_map = {}
    try:
        r_v = (supabase.table("tab_rubrica")
               .select("cod_rubr, dsc_rubr, unid_verba, tp_rubr, id_cliente")
               .in_("id_cliente", [0, id_cliente])
               .in_("cod_rubr",   cod_verbas)
               .eq("situacao", "A")
               .execute())
        for v in (r_v.data or []):
            cod = v.get("cod_rubr")
            if cod not in verbas_map or v.get("id_cliente") != 0:
                verbas_map[cod] = {
                    "dsc_rubr":   v.get("dsc_rubr") or "",
                    "unid_verba": v.get("unid_verba") or "V",
                    "tp_rubr":    v.get("tp_rubr") or "",
                }
    except Exception:
        pass

    registros = []
    for reg in registros_raw:
        mat       = reg.get("matricula")
        cod       = reg.get("cod_verba")
        vi        = verbas_map.get(cod, {"dsc_rubr": "", "unid_verba": "V", "tp_rubr": ""})
        unid      = vi["unid_verba"]
        qtd_raw   = reg.get("qtd")   or 0
        valor_raw = reg.get("valor") or 0

        if unid == "H":
            h, m = qtd_raw // 60, qtd_raw % 60
            entrada_fmt = f"{h:02d}:{m:02d}"
        elif unid == "D":
            entrada_fmt = f"{qtd_raw} dia(s)"
        else:
            reais = valor_raw / 100
            entrada_fmt = (f"R$ {reais:,.2f}"
                           .replace(",", "X").replace(".", ",").replace("X", "."))

        registros.append({
            "id":          reg["id"],
            "matricula":   mat,
            "nome":        nomes_map.get(mat, "—"),
            "cod_verba":   cod,
            "dsc_rubr":    vi["dsc_rubr"],
            "unid_verba":  unid,
            "tp_rubr":     vi["tp_rubr"],
            "qtd_raw":     qtd_raw,
            "valor_raw":   valor_raw,
            "entrada_fmt": entrada_fmt,
            "folha_tipo":  reg.get("folha_tipo", "N"),
        })
    return jsonify({"ok": True, "registros": registros})


def _invalidar_rescisao_calculada(id_empresa, id_cliente, folha_int, mats):
    """Ao lançar/alterar/excluir verba manual numa rescisão já CALCULADA, o
    cálculo fica desatualizado. Apaga as verbas calculadas (origem='C') e o
    tab_total (folha_tipo='R') das matrículas que tinham cálculo, deixando a
    rescisão 'pendente' (precisa recalcular para poder imprimir).
    Retorna a lista de matrículas que estavam calculadas e foram invalidadas."""
    try:
        mats = [int(m) for m in mats if str(m).strip()]
    except Exception:
        mats = []
    if not mats or not folha_int:
        return []
    calculadas = []
    try:
        q = (supabase.table("tab_total")
             .select("matricula")
             .eq("id_empresa", id_empresa)
             .eq("folha", folha_int)
             .eq("folha_tipo", "R")
             .in_("matricula", mats))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        calculadas = list({int(r["matricula"]) for r in (q.execute().data or [])})
    except Exception:
        return []
    if not calculadas:
        return []
    try:
        dt = (supabase.table("tab_total").delete()
              .eq("id_empresa", id_empresa).eq("folha", folha_int)
              .eq("folha_tipo", "R").in_("matricula", calculadas))
        if id_cliente:
            dt = dt.eq("id_cliente", id_cliente)
        dt.execute()
    except Exception:
        pass
    try:
        dm = (supabase.table("tab_mov").delete()
              .eq("id_empresa", id_empresa).eq("folha", folha_int)
              .eq("folha_tipo", "R").eq("origem", "C").in_("matricula", calculadas))
        if id_cliente:
            dm = dm.eq("id_cliente", id_cliente)
        dm.execute()
    except Exception:
        pass
    for m in calculadas:
        gravar_log("RESC-INVALID",
                   "Rescisão marcada como pendente após lançamento manual (precisa recalcular)",
                   matricula=m)
    return calculadas


def _rescisao_calculada_mats(id_empresa, id_cliente, folha_int, mats=None):
    """Conjunto de matrículas que têm rescisão CALCULADA (tab_total folha_tipo='R')
    na folha. Se mats for informado, restringe a elas."""
    if not folha_int:
        return set()
    try:
        q = (supabase.table("tab_total")
             .select("matricula")
             .eq("id_empresa", id_empresa)
             .eq("folha", folha_int)
             .eq("folha_tipo", "R"))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        if mats:
            q = q.in_("matricula", [int(m) for m in mats])
        return {int(r["matricula"]) for r in (q.execute().data or [])}
    except Exception:
        return set()


# =========================================================
# MOVIMENTO — API: gravar
# =========================================================
@app.route("/api/tab_mov_gravar", methods=["POST"])
def api_tab_mov_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    data       = request.get_json(silent=True) or {}
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if not anomes:
        return jsonify({"ok": False, "msg": "Sem folha ativa."})
    folha_int  = int(anomes)

    matriculas = data.get("matriculas", [])
    cod_verba  = data.get("cod_verba")
    qtd        = int(data.get("qtd")   or 0)
    valor      = int(data.get("valor") or 0)
    folha_tipo = str(data.get("folha_tipo") or "N").upper()[:1]
    if folha_tipo not in ("N", "F", "R"):
        folha_tipo = "N"

    if not matriculas:
        return jsonify({"ok": False, "msg": "Nenhum funcionário selecionado."})
    if not cod_verba:
        return jsonify({"ok": False, "msg": "Verba não informada."})
    if qtd == 0 and valor == 0:
        return jsonify({"ok": False, "msg": "Informe quantidade ou valor."})

    mats_int = [int(m) for m in matriculas]

    # Verifica se a verba é do tipo Hora (H) para calcular valor monetário
    verba_unid = "V"
    try:
        r_rub = (supabase.table("tab_rubrica")
                 .select("unid_verba, id_cliente")
                 .eq("cod_rubr", int(cod_verba))
                 .in_("id_cliente", [0, id_cliente])
                 .execute())
        for rv in sorted(r_rub.data or [], key=lambda x: x.get("id_cliente") or 0):
            if rv.get("unid_verba"):
                verba_unid = str(rv["unid_verba"])
    except Exception:
        pass

    # Para verba H ou D: busca salário de cada funcionário
    sal_hora_map = {}
    sal_dia_map  = {}
    if verba_unid in ("H", "D") and qtd > 0:
        try:
            r_cad = (supabase.table("tab_cad")
                     .select("matricula, vrsalfx, undsalfixo, qtdhrsmes")
                     .eq("id_empresa", id_empresa)
                     .in_("matricula", mats_int)
                     .execute())
            dias_mes_api = _dias_no_mes_total(anomes)
            for emp in (r_cad.data or []):
                mat_e      = int(emp.get("matricula") or 0)
                vrsalfx    = int(emp.get("vrsalfx")   or 0)
                undsalfix  = (emp.get("undsalfixo") or "M").upper()
                # fallback 220h/mês quando o cadastro está zerado (igual ao cálculo)
                qtdhrsmes  = int(emp.get("qtdhrsmes") or 0) or 220
                if undsalfix == "H":
                    sal_hora_map[mat_e] = vrsalfx
                    sal_mes_e = vrsalfx * qtdhrsmes
                else:
                    sal_hora_map[mat_e] = round(vrsalfx / qtdhrsmes, 4) if qtdhrsmes else 0.0
                    sal_mes_e = vrsalfx
                sal_dia_map[mat_e] = (sal_mes_e / dias_mes_api) if dias_mes_api else 0.0
        except Exception:
            pass

    # Busca data de admissão de todas as matrículas de uma vez
    try:
        r_adm = (supabase.table("tab_cad")
                 .select("matricula, dtadm")
                 .eq("id_empresa", id_empresa)
                 .in_("matricula", mats_int)
                 .execute())
        adm_map = {int(r["matricula"]): _norm_data8(str(r.get("dtadm") or ""))
                   for r in (r_adm.data or [])}
    except Exception:
        adm_map = {}

    inseridos = 0
    for mat in matriculas:
        try:
            mat_int   = int(mat)
            dtadm_mov = adm_map.get(mat_int, "")
            if dtadm_mov and len(dtadm_mov) >= 6 and anomes < dtadm_mov[:6]:
                adm_fmt = f"{dtadm_mov[4:6]}/{dtadm_mov[:4]}"
                return jsonify({"ok": False,
                                "msg": f"Mat {mat_int}: mês {anomes[4:]}/{anomes[:4]} é anterior "
                                       f"à admissão ({adm_fmt}). Nenhum registro gravado."})
            # Para verba H, calcula valor = horas × sal_hora
            # Para verba D, calcula valor = dias × sal_dia
            if verba_unid == "H" and qtd > 0:
                sh = sal_hora_map.get(mat_int, 0)
                valor_gravar = int(round(qtd / 60 * sh))
            elif verba_unid == "D" and qtd > 0:
                sd = sal_dia_map.get(mat_int, 0)
                valor_gravar = int(round(qtd * sd))
            else:
                valor_gravar = valor
            supabase.table("tab_mov").insert({
                "id_cliente":  id_cliente,
                "id_empresa":  id_empresa,
                "situacao":    "A",
                "matricula":   int(mat),
                "folha":       folha_int,
                "folha_tipo":  folha_tipo,
                "cod_verba":   int(cod_verba),
                "qtd":         qtd,
                "valor":       valor_gravar,
                "lote":        0,
                "origem":      "M",
                "controle":    0,
                "os":          0,
            }).execute()
            inseridos += 1
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Erro mat {mat}: {str(e)[:120]}"})

    gravar_log("MOV-INC",
               f"verba={int(cod_verba):04d} mats={len(matriculas)} folha={folha_int}")
    resp = {"ok": True, "msg": f"{inseridos} registro(s) gravado(s).", "inseridos": inseridos}
    if folha_tipo == "R":
        invalid = _invalidar_rescisao_calculada(id_empresa, id_cliente, folha_int, mats_int)
        if invalid:
            resp["recalcular"] = True
            resp["msg"] += (" Atenção: a rescisão já estava calculada e foi marcada como "
                            "PENDENTE — recalcule antes de imprimir.")
    return jsonify(resp)


