# =========================================================
@app.route("/api/tab_mov_alterar", methods=["POST"])
def api_tab_mov_alterar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    data       = request.get_json(silent=True) or {}
    id_ev      = data.get("id")
    qtd        = int(data.get("qtd")   or 0)
    valor      = int(data.get("valor") or 0)
    folha_tipo = str(data.get("folha_tipo") or "N").upper()[:1]
    if folha_tipo not in ("N", "F", "R"):
        folha_tipo = "N"
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    if not id_ev:
        return jsonify({"ok": False, "msg": "ID não informado."})
    if qtd == 0 and valor == 0:
        return jsonify({"ok": False, "msg": "Informe quantidade ou valor."})
    try:
        r = (supabase.table("tab_mov")
             .select("id, cod_verba, matricula, folha")
             .eq("id",         id_ev)
             .eq("id_empresa", id_empresa)
             .eq("id_cliente", id_cliente)
             .execute())
        if not r.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})

        rec       = r.data[0]
        cod_verba = rec.get("cod_verba")
        matricula = rec.get("matricula")
        folha_rec = int(rec.get("folha") or 0)

        # Para verba H: recalcula valor = horas × sal_hora
        valor_gravar = valor
        if cod_verba and qtd > 0:
            try:
                r_rub = (supabase.table("tab_rubrica")
                         .select("unid_verba")
                         .eq("cod_rubr", int(cod_verba))
                         .in_("id_cliente", [0, id_cliente])
                         .execute())
                verba_unid = "V"
                for rv in sorted(r_rub.data or [], key=lambda x: x.get("id_cliente") or 0):
                    if rv.get("unid_verba"):
                        verba_unid = str(rv["unid_verba"])
                if verba_unid == "H" and matricula:
                    r_cad = (supabase.table("tab_cad")
                             .select("vrsalfx, undsalfixo, qtdhrsmes")
                             .eq("id_empresa", id_empresa)
                             .eq("matricula",  int(matricula))
                             .execute())
                    if r_cad.data:
                        emp       = r_cad.data[0]
                        vrsalfx   = int(emp.get("vrsalfx")   or 0)
                        undsalfix = (emp.get("undsalfixo") or "M").upper()
                        qtdhrsmes = int(emp.get("qtdhrsmes") or 0) or 220
                        if undsalfix == "H":
                            sh = vrsalfx
                        else:
                            sh = round(vrsalfx / qtdhrsmes, 4) if qtdhrsmes else 0.0
                        valor_gravar = int(round(qtd / 60 * sh))
            except Exception:
                pass

        supabase.table("tab_mov").update({
            "qtd":        qtd,
            "valor":      valor_gravar,
            "folha_tipo": folha_tipo,
        }).eq("id", id_ev).execute()
        gravar_log("MOV-ALT", f"id={id_ev} qtd={qtd} valor={valor_gravar}")
        resp = {"ok": True, "msg": "Registro alterado com sucesso."}
        if folha_tipo == "R" and matricula:
            if _invalidar_rescisao_calculada(id_empresa, id_cliente, folha_rec, [matricula]):
                resp["recalcular"] = True
                resp["msg"] += (" Atenção: a rescisão já estava calculada e foi marcada como "
                                "PENDENTE — recalcule antes de imprimir.")
        return jsonify(resp)
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


# =========================================================
# MOVIMENTO — API: excluir (soft delete)
# =========================================================
@app.route("/api/tab_mov_excluir", methods=["POST"])
def api_tab_mov_excluir():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    data       = request.get_json(silent=True) or {}
    id_ev      = data.get("id")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    if not id_ev:
        return jsonify({"ok": False, "msg": "ID não informado."})
    try:
        r = (supabase.table("tab_mov")
             .select("id, matricula, folha, folha_tipo")
             .eq("id",         id_ev)
             .eq("id_empresa", id_empresa)
             .eq("id_cliente", id_cliente)
             .execute())
        if not r.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        rec       = r.data[0]
        matricula = rec.get("matricula")
        folha_rec = int(rec.get("folha") or 0)
        ftipo_rec = str(rec.get("folha_tipo") or "N").upper()[:1]
        supabase.table("tab_mov").update({"situacao": "D"}).eq("id", id_ev).execute()
        gravar_log("MOV-EXCL", f"id={id_ev}")
        resp = {"ok": True, "msg": "Registro excluído."}
        if ftipo_rec == "R" and matricula:
            if _invalidar_rescisao_calculada(id_empresa, id_cliente, folha_rec, [matricula]):
                resp["recalcular"] = True
                resp["msg"] += (" Atenção: a rescisão já estava calculada e foi marcada como "
                                "PENDENTE — recalcule antes de imprimir.")
        return jsonify(resp)
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


