# AUMENTO DE SALÁRIO — Formulário
# =========================================================
@app.route("/cad_aumento")
def cad_aumento():
    if not session.get("logado"):
        return redirect("/")

    mats_raw  = request.args.get("mats", "").strip()
    mats_lista = [int(m) for m in mats_raw.split(",") if m.strip().isdigit()] if mats_raw else []

    # Parâmetros restaurados ao voltar da tela de resultado
    p_vigencia    = request.args.get("vigencia",    "").strip()       # YYYYMM
    p_percentual  = request.args.get("percentual",  "").strip()
    p_tipo        = request.args.get("tipo",        "1").strip()
    p_motivo      = request.args.get("motivo",      "1").strip()
    p_gravar      = request.args.get("gravar",      "N").upper().strip()
    p_vr_inferior = request.args.get("vr_inferior", "").strip()       # centavos
    p_vr_superior = request.args.get("vr_superior", "").strip()       # centavos
    p_nao_ficha   = request.args.get("nao_ficha",   "N").upper().strip()

    funcionarios = []
    if mats_lista:
        id_empresa = _get_id_empresa()
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula, nome, dtadm, vrsalfx")
                 .eq("id_empresa", id_empresa)
                 .in_("matricula", mats_lista)
                 .order("nome")
                 .execute())
            for f in (r.data or []):
                sal   = f.get("vrsalfx") or 0
                dtadm = f.get("dtadm")
                s     = str(dtadm or "")
                dtadm_fmt = f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"
                sal_fmt   = ("R$ " + f"{sal/100:,.2f}"
                             .replace(",", "X").replace(".", ",").replace("X", "."))
                funcionarios.append({
                    "matricula": f.get("matricula"),
                    "mat_fmt":   str(f.get("matricula", "")).zfill(6),
                    "nome":      f.get("nome", ""),
                    "dtadm_fmt": dtadm_fmt,
                    "sal_fmt":   sal_fmt,
                    "sal_cents": int(sal),
                })
            # Última vigência de salário por funcionário
            for f in funcionarios:
                f["ultima_vigencia"]     = None
                f["ultima_vigencia_fmt"] = ""
            if funcionarios:
                try:
                    rv = (supabase.table("tab_eventos")
                          .select("matricula, folha")
                          .eq("id_empresa", id_empresa)
                          .in_("matricula", mats_lista)
                          .eq("op1", 5)
                          .order("folha", desc=True)
                          .execute())
                    _ult = {}
                    for ev in (rv.data or []):
                        mat_ev = ev.get("matricula")
                        fol    = ev.get("folha")
                        if mat_ev not in _ult and fol:
                            _ult[mat_ev] = int(fol)
                    for f in funcionarios:
                        uv = _ult.get(f["matricula"])
                        f["ultima_vigencia"] = uv  # int YYYYMM ou None
                        uv_s = str(uv) if uv else ""
                        f["ultima_vigencia_fmt"] = f"{uv_s[4:6]}/{uv_s[0:4]}" if len(uv_s) == 6 else ""
                except Exception:
                    pass
        except Exception:
            pass

    # Vigência: prefere o valor restaurado, senão usa folha ativa
    if p_vigencia and len(p_vigencia) == 6 and p_vigencia.isdigit():
        vigencia_default = f"{p_vigencia[:4]}-{p_vigencia[4:6]}-01"
    else:
        anomes = str(session.get("anomes_atual") or "")
        if len(anomes) == 6:
            vigencia_default = f"{anomes[:4]}-{anomes[4:6]}-01"
        else:
            from datetime import date as _date
            vigencia_default = _date.today().strftime("%Y-%m-01")

    # Faixa salarial: converte centavos → string BR para preencher o input
    def _cents_to_str(s, default):
        try:
            return (f"{int(s)/100:,.2f}"
                    .replace(",", "X").replace(".", ",").replace("X", "."))
        except Exception:
            return default

    vr_inferior_str = _cents_to_str(p_vr_inferior, "0,00")
    vr_superior_str = _cents_to_str(p_vr_superior, "99.999.999,99")

    return render_template(
        "F10_Cad_Aumento.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        vigencia_default=vigencia_default,
        funcionarios=funcionarios,
        mats_raw=mats_raw,
        p_percentual=p_percentual,
        p_tipo=p_tipo,
        p_motivo=p_motivo,
        p_gravar=p_gravar,
        p_vr_inferior=vr_inferior_str,
        p_vr_superior=vr_superior_str,
        p_nao_ficha=p_nao_ficha,
    )


# =========================================================
# AUMENTO DE SALÁRIO — Resultado / Processamento
# =========================================================
@app.route("/rel_aumento")
def rel_aumento():
    if not session.get("logado"):
        return redirect("/")

    import calendar as _cal

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente", 0)

    # --- parâmetros da URL ---
    vigencia_raw = request.args.get("vigencia", "").strip()  # YYYYMM
    percentual   = float(request.args.get("percentual", "0") or 0)
    tipo         = int(request.args.get("tipo", "1") or 1)
    motivo_raw   = request.args.get("motivo", "1").strip()
    gravar_flag  = request.args.get("gravar", "N").upper().strip() == "S"
    vr_inf       = int(request.args.get("vr_inferior", "0") or 0)
    vr_sup       = int(request.args.get("vr_superior", "9999999999") or 9999999999)
    # mats: seleção manual (lista de matrículas separadas por vírgula)
    mats_raw     = request.args.get("mats", "").strip()
    mats_lista   = [int(m) for m in mats_raw.split(",") if m.strip().isdigit()] if mats_raw else []
    nao_ficha    = request.args.get("nao_ficha", "N").upper().strip() == "S"

    # Validação mínima
    if len(vigencia_raw) != 6 or not vigencia_raw.isdigit():
        vigencia_raw = str(session.get("anomes_atual") or "")
    vig_year  = int(vigencia_raw[:4])
    vig_month = int(vigencia_raw[4:6])

    # Rótulos para exibição
    TIPO_LABEL   = {
        1: "1 — Integral",
        2: "2 — Proporcional · Arredondando qualquer fração",
        3: "3 — Proporcional · Arredondando fração > 15 dias",
        4: "4 — Proporcional · Sem contar mês de admissão",
    }
    MOTIVO_LABEL = {"1": "Dissídio", "2": "Espontâneo", "3": "Promoção", "4": "Salário Mínimo", "9": "Outros Motivos"}

    vigencia_fmt   = f"{vigencia_raw[4:6]}/{vigencia_raw[:4]}"
    percentual_fmt = f"{percentual:.2f}".replace(".", ",")
    vr_inf_fmt = "R$ " + f"{vr_inf/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    vr_sup_fmt = "R$ " + f"{vr_sup/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    faixa_str  = f"{vr_inf_fmt} — {vr_sup_fmt}"
    if mats_lista:
        faixa_label = f"{len(mats_lista)} funcionário(s) selecionado(s) · faixa {faixa_str}"
    else:
        faixa_label = faixa_str

    def _fsal(c):
        if c is None:
            return "—"
        return "R$ " + f"{c/100:,.2f}".replace(",","X").replace(".",",").replace("X",".")

    def _fdata(v):
        s = str(v or "")
        if len(s) == 8:
            return f"{s[6:8]}/{s[4:6]}/{s[0:4]}"
        return "—"

    def _calcular(vrsalfx, dtadm_int):
        """Retorna (novo_vrsalfx, proporcao_pct, meses_int, perc_aplicado)."""
        if tipo == 1:
            prop = 1.0
            meses = 12
        else:
            try:
                s = str(dtadm_int).zfill(8)
                adm_year  = int(s[0:4])
                adm_month = int(s[4:6])
                adm_day   = int(s[6:8])
            except Exception:
                prop  = 1.0
                meses = 12
            else:
                diff = (vig_year - adm_year) * 12 + (vig_month - adm_month)
                if diff >= 12:
                    prop  = 1.0
                    meses = 12
                else:
                    days_in_adm = _cal.monthrange(adm_year, adm_month)[1]
                    days_rem    = days_in_adm - adm_day + 1
                    if tipo == 4:
                        count_adm = 0
                    elif tipo == 2:
                        count_adm = 1
                    else:  # tipo == 3
                        count_adm = 1 if days_rem > 15 else 0
                    meses = max(0, min(12, diff + count_adm))
                    prop  = meses / 12

        perc_aplicado = percentual * prop
        aumento       = round(vrsalfx * (perc_aplicado / 100))
        novo          = vrsalfx + aumento
        return novo, prop, meses, perc_aplicado

    # --- buscar funcionários ---
    registros = []
    try:
        q = (supabase.table("tab_cad")
             .select("matricula, nome, dtadm, vrsalfx")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .order("nome"))
        if mats_lista:
            q = q.in_("matricula", mats_lista)
        resp = q.execute()
        # Filtro de faixa aplicado em Python: evita exclusão por NULL no banco
        funcs = [f for f in (resp.data or [])
                 if vr_inf <= (f.get("vrsalfx") or 0) <= vr_sup]
    except Exception as e:
        funcs = []

    erros_gravacao = []
    for f in funcs:
        mat      = f.get("matricula")
        nome_f   = f.get("nome", "")
        dtadm    = f.get("dtadm")
        sal_at   = f.get("vrsalfx") or 0

        sal_novo, prop, meses, perc_ap = _calcular(sal_at, dtadm)
        diff     = sal_novo - sal_at

        if gravar_flag:
            try:
                supabase.table("tab_cad").update(
                    {"vrsalfx": sal_novo}
                ).eq("id_empresa", id_empresa).eq("matricula", mat).execute()

                if not nao_ficha:
                    data1i_int = int(vigencia_raw + "01")
                    supabase.table("tab_eventos").insert({
                        "id_cliente": id_cliente,
                        "id_empresa": id_empresa,
                        "matricula":  mat,
                        "folha":      int(vigencia_raw),
                        "op1":        5,
                        "op2":        1,
                        "data1i":     data1i_int,
                        "ref1":       sal_at,
                        "ref2":       sal_novo,
                        "campotxt1":  f"{perc_ap:.4f}".replace(".", ",") + "%",
                        "campotxt2":  str(motivo_raw),
                    }).execute()

                def _brl(c):
                    return (f"{c/100:,.2f}"
                            .replace(",", "X").replace(".", ",").replace("X", "."))
                gravar_log(
                    "SAL-AUMENTO",
                    f"Salario: de {_brl(sal_at)} para {_brl(sal_novo)}",
                    matricula=mat,
                )

                # Gera pendência S-2206 (alteração salarial)
                try:
                    _agora_es = datetime.now()
                    _anomes   = str(session.get("anomes_atual") or "")
                    _ts_es    = _agora_es.strftime("%Y%m%d%H%M%S")
                    supabase.table("tab_esocial").insert({
                        "id_cliente": id_cliente,
                        "id_empresa": id_empresa,
                        "data_cad":   _agora_es.strftime("%Y%m%d"),
                        "hora_cad":   _agora_es.strftime("%H%M"),
                        "id_remessa": f"{_ts_es}2206{mat}",
                        "ano_mes":    int(_anomes) if len(_anomes) == 6 else None,
                        "folha_tipo": "N",
                        "layout":     "2206",
                        "matricula":  mat,
                        "codigo2":    0,
                    }).execute()
                except Exception:
                    pass

            except Exception as e_grav:
                erros_gravacao.append(str(mat))
                continue

        registros.append({
            "matricula":       mat,
            "nome":            nome_f,
            "dtadm_fmt":       _fdata(dtadm),
            "meses":           meses,
            "prop_fmt":        f"{prop*100:.1f}".replace(".", ","),
            "sal_atual_fmt":   _fsal(sal_at),
            "perc_aplicado_fmt": f"{perc_ap:.2f}".replace(".", ","),
            "sal_novo_fmt":    _fsal(sal_novo),
            "diff_fmt":        _fsal(diff),
            "_sal_at":         sal_at,
            "_sal_novo":       sal_novo,
            "_diff":           diff,
        })

    total_atual = sum(r["_sal_at"]  for r in registros)
    total_novo  = sum(r["_sal_novo"] for r in registros)
    total_diff  = total_novo - total_atual

    # URL para gravar (usado no botão de simulação → gravar)
    args_gravar = request.query_string.decode()
    args_gravar = args_gravar.replace("gravar=N", "gravar=S").replace("gravar=n", "gravar=S")

    # URL de volta ao formulário com TODOS os parâmetros restaurados
    from urllib.parse import urlencode as _urlencode
    _voltar_qs = _urlencode({
        "mats":        mats_raw,
        "vigencia":    vigencia_raw,
        "percentual":  f"{percentual:.2f}",
        "tipo":        tipo,
        "motivo":      motivo_raw,
        "gravar":      "S" if gravar_flag else "N",
        "vr_inferior": vr_inf,
        "vr_superior": vr_sup,
        "nao_ficha":   "S" if nao_ficha else "N",
    })
    url_voltar = f"/cad_aumento?{_voltar_qs}"

    return render_template(
        "F10_Rel_Aumento.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        gravado=gravar_flag,
        registros=registros,
        vigencia_fmt=vigencia_fmt,
        percentual_fmt=percentual_fmt,
        tipo_label=TIPO_LABEL.get(tipo, str(tipo)),
        motivo_label=MOTIVO_LABEL.get(motivo_raw, motivo_raw),
        faixa_label=faixa_label,
        total_atual_fmt=_fsal(total_atual),
        total_novo_fmt=_fsal(total_novo),
        total_diff_fmt=_fsal(total_diff),
        url_gravar=f"/rel_aumento?{args_gravar}",
        url_voltar=url_voltar,
        erros_gravacao=erros_gravacao,
    )


# =========================================================
# CANCELAR ALTERAÇÃO DE SALÁRIO — TELA
# =========================================================
@app.route("/cad_cancelar_aumento")
def cad_cancelar_aumento():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    sit_folha  = _refresh_situacao_folha()
    folha_aberta = sit_folha in ("A", "X")
    anomes_fmt = f"{anomes[4:6]}/{anomes[0:4]}" if len(anomes) == 6 else anomes

    ok_msg   = request.args.get("ok", "")
    erro_msg = request.args.get("erro", "")

    _MOTIVO_AUM = {"1":"Dissídio","2":"Espontâneo","3":"Promoção","4":"Salário Mínimo","9":"Outros Motivos"}
    linhas = []
    erro   = None

    if anomes and len(anomes) == 6:
        try:
            # 1. Todos os aumentos do período
            r_ev = (supabase.table("tab_eventos")
                    .select("id, matricula, folha, ref1, ref2, campotxt1, campotxt2")
                    .eq("id_empresa", id_empresa)
                    .eq("op1", 5)
                    .eq("folha", int(anomes))
                    .order("matricula")
                    .execute())
            eventos = r_ev.data or []

            if eventos:
                mats_ev = list({ev.get("matricula") for ev in eventos})

                # 2. Nomes dos funcionários
                r_cad = (supabase.table("tab_cad")
                         .select("matricula, nome")
                         .eq("id_empresa", id_empresa)
                         .in_("matricula", mats_ev)
                         .execute())
                nomes = {f.get("matricula"): f.get("nome", "") for f in (r_cad.data or [])}

                # 3. S-2206 do período (todos de uma vez)
                r_es = (supabase.table("tab_esocial")
                        .select("id_esocial, matricula, recibo, observacao_erro")
                        .eq("id_empresa", id_empresa)
                        .eq("layout", "2206")
                        .eq("ano_mes", int(anomes))
                        .in_("matricula", mats_ev)
                        .execute())
                # pega o maior id_esocial por matrícula
                es_map = {}
                for es in sorted(r_es.data or [], key=lambda x: x.get("id_esocial") or 0):
                    es_map[es.get("matricula")] = es

                # 4. Aumentos posteriores ao período (para bloquear)
                r_post = (supabase.table("tab_eventos")
                          .select("matricula, folha")
                          .eq("id_empresa", id_empresa)
                          .eq("op1", 5)
                          .in_("matricula", mats_ev)
                          .gt("folha", int(anomes))
                          .execute())
                post_map = {}
                for p in (r_post.data or []):
                    m = p.get("matricula")
                    f = str(p.get("folha") or "")
                    if m not in post_map:
                        post_map[m] = f"{f[4:6]}/{f[0:4]}" if len(f) == 6 else f

                def _brl(c):
                    return ("R$ " + f"{(c or 0)/100:,.2f}"
                            .replace(",", "X").replace(".", ",").replace("X", "."))

                for ev in eventos:
                    mat      = ev.get("matricula")
                    sal_ant  = int(ev.get("ref1") or 0)
                    sal_nov  = int(ev.get("ref2") or 0)
                    perc     = ev.get("campotxt1") or "—"
                    motivo   = _MOTIVO_AUM.get(str(ev.get("campotxt2") or ""), "—")
                    es       = es_map.get(mat)
                    recibo   = (es.get("recibo") or "").strip() if es else ""
                    id_es    = es.get("id_esocial") if es else None

                    cancelavel  = True
                    motivo_bloq = ""
                    s2206_label = "Sem remessa"

                    if recibo:
                        s2206_label = f"Recibo: {recibo[:20]}"
                        cancelavel  = False
                        motivo_bloq = "S-2206 já enviado com recibo — não pode ser cancelado."
                    elif es:
                        s2206_label = "Pendente (sem recibo)"

                    if cancelavel and mat in post_map:
                        cancelavel  = False
                        motivo_bloq = f"Existe alteração posterior em {post_map[mat]} — cancele-a primeiro."

                    if not folha_aberta:
                        cancelavel  = False
                        motivo_bloq = "Folha fechada ou calculada."

                    linhas.append({
                        "id":          ev.get("id"),
                        "id_esocial":  id_es,
                        "mat":         mat,
                        "mat_fmt":     str(mat).zfill(6),
                        "nome":        nomes.get(mat, ""),
                        "sal_ant_fmt": _brl(sal_ant),
                        "sal_nov_fmt": _brl(sal_nov),
                        "perc":        perc,
                        "motivo":      motivo,
                        "s2206_label": s2206_label,
                        "tem_recibo":  bool(recibo),
                        "cancelavel":  cancelavel,
                        "motivo_bloq": motivo_bloq,
                    })
        except Exception as e:
            erro = f"Erro ao buscar dados: {e}"

    return render_template(
        "F10_CancelAumento.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        linhas=linhas,
        anomes_fmt=anomes_fmt,
        folha_aberta=folha_aberta,
        sit_folha=sit_folha,
        erro=erro,
        ok_msg=ok_msg,
        erro_msg=erro_msg,
    )


@app.route("/exec_cancelar_aumento")
def exec_cancelar_aumento():
    if not session.get("logado"):
        return redirect("/")

    id_ev   = request.args.get("id_ev", "").strip()
    mat_raw = request.args.get("mat", "").strip()
    if not id_ev or not mat_raw:
        return redirect("/cad_cancelar_aumento")

    id_empresa   = _get_id_empresa()
    anomes       = str(session.get("anomes_atual") or "")
    mat          = int(mat_raw)
    msg_erro     = None
    sal_anterior = 0
    sal_novo_ev  = 0

    try:
        # 1. Folha aberta
        if _refresh_situacao_folha() not in ("A", "X"):
            raise Exception("Folha do período está fechada — cancelamento não permitido.")

        # 2. Busca o evento
        r_ev = (supabase.table("tab_eventos")
                .select("id, folha, ref1, ref2")
                .eq("id", int(id_ev))
                .eq("id_empresa", id_empresa)
                .eq("matricula", mat)
                .eq("op1", 5)
                .limit(1).execute())
        if not r_ev.data:
            raise Exception("Evento não encontrado.")
        ev = r_ev.data[0]
        if str(ev.get("folha") or "") != anomes:
            raise Exception("O evento não pertence ao período ativo.")

        sal_anterior = int(ev.get("ref1") or 0)
        sal_novo_ev  = int(ev.get("ref2") or 0)

        # 3. Verifica S-2206 — bloqueia se qualquer uma tiver recibo
        r_es = (supabase.table("tab_esocial")
                .select("id_esocial, recibo")
                .eq("id_empresa", id_empresa)
                .eq("matricula", mat)
                .eq("layout", "2206")
                .eq("ano_mes", int(anomes))
                .execute())
        tem_s2206 = bool(r_es.data)
        for es in (r_es.data or []):
            if (es.get("recibo") or "").strip():
                raise Exception("S-2206 já enviado com recibo — não pode ser cancelado.")

        # 4. Verifica aumento posterior
        r_post = (supabase.table("tab_eventos")
                  .select("folha")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", mat)
                  .eq("op1", 5)
                  .gt("folha", int(anomes))
                  .limit(1).execute())
        if r_post.data:
            f = str(r_post.data[0].get("folha") or "")
            raise Exception(f"Existe alteração posterior em "
                            f"{f[4:6]}/{f[0:4] if len(f)==6 else f} — cancele-a primeiro.")

        # 5. Restaura salário
        supabase.table("tab_cad").update({"vrsalfx": sal_anterior}) \
            .eq("id_empresa", id_empresa).eq("matricula", mat).execute()

        # 6. Exclui o evento de aumento
        supabase.table("tab_eventos").delete() \
            .eq("id", int(id_ev)).eq("id_empresa", id_empresa).execute()

        # 7. Apaga todas as remessas S-2206 do período (sem recibo, validado acima)
        if tem_s2206:
            supabase.table("tab_esocial").delete() \
                .eq("id_empresa", id_empresa) \
                .eq("matricula", mat) \
                .eq("layout", "2206") \
                .eq("ano_mes", int(anomes)).execute()

    except Exception as e:
        if not msg_erro:
            msg_erro = str(e)[:300]

    # 8. Log — fora do try para garantir gravação mesmo se etapa anterior lançar exceção
    if not msg_erro:
        def _brl(c):
            return "R$ " + f"{c/100:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        gravar_log("SAL-CANCEL",
                   f"Cancelado: de {_brl(sal_novo_ev)} voltou para {_brl(sal_anterior)}",
                   matricula=mat)

    if msg_erro:
        from urllib.parse import quote as _quote
        return redirect(f"/cad_cancelar_aumento?erro={_quote(msg_erro)}")
    return redirect("/cad_cancelar_aumento?ok=1")


