@app.route("/cad_cancelar_ferias")
def cad_cancelar_ferias():
    if not session.get("logado"):
        return redirect("/")

    id_cliente   = session.get("id_cliente")
    id_empresa   = _get_id_empresa()
    anomes       = str(session.get("anomes_atual") or "")
    sit_folha    = _refresh_situacao_folha()
    folha_aberta = sit_folha in ("A", "X")
    anomes_fmt   = f"{anomes[4:6]}/{anomes[0:4]}" if len(anomes) == 6 else anomes

    ok_msg   = request.args.get("ok",   "")
    erro_msg = request.args.get("erro", "")

    linhas = []
    erro   = None

    if anomes and len(anomes) == 6:
        try:
            # 1. Férias do período ativo (op1=3, data1i no mês)
            r_ev = (supabase.table("tab_eventos")
                    .select("id, matricula, data1i, data1f, ref1, ref2")
                    .eq("id_cliente", id_cliente)
                    .eq("id_empresa", id_empresa)
                    .eq("op1", 3)
                    .gte("data1i", anomes + "01")
                    .lte("data1i", anomes + "31")
                    .order("matricula")
                    .execute())
            eventos = r_ev.data or []

            if eventos:
                mats_ev = list({ev.get("matricula") for ev in eventos})
                ids_ev  = [ev["id"] for ev in eventos if ev.get("id")]

                # 2. Nomes dos funcionários
                r_cad = (supabase.table("tab_cad")
                         .select("matricula, nome")
                         .eq("id_empresa", id_empresa)
                         .in_("matricula", mats_ev)
                         .execute())
                nomes = {f.get("matricula"): f.get("nome", "")
                         for f in (r_cad.data or [])}

                # 3. S-2230 vinculados aos eventos (codigo2 = id do tab_eventos)
                r_es = (supabase.table("tab_esocial")
                        .select("id_esocial, codigo2, recibo")
                        .eq("id_empresa", id_empresa)
                        .eq("layout", "2230")
                        .in_("codigo2", ids_ev)
                        .execute())
                es_map = {es.get("codigo2"): es for es in (r_es.data or [])}

                for ev in eventos:
                    id_ev  = ev.get("id")
                    mat    = ev.get("matricula")
                    di     = str(ev.get("data1i") or "")
                    df     = str(ev.get("data1f") or "")
                    dias   = int(ev.get("ref1") or 0)
                    abono  = int(ev.get("ref2") or 0)

                    es      = es_map.get(id_ev)
                    recibo  = (es.get("recibo") or "").strip() if es else ""

                    cancelavel  = True
                    motivo_bloq = ""
                    if recibo:
                        s2230_label = f"Recibo: {recibo[:18]}"
                        cancelavel  = False
                        motivo_bloq = "S-2230 já enviado com recibo — não pode ser cancelado."
                    elif es:
                        s2230_label = "Pendente"
                    else:
                        s2230_label = "Sem remessa"

                    if not folha_aberta:
                        cancelavel  = False
                        motivo_bloq = "Folha fechada ou calculada."

                    linhas.append({
                        "id":          id_ev,
                        "mat":         mat,
                        "mat_fmt":     str(mat).zfill(6),
                        "nome":        nomes.get(mat, ""),
                        "di_fmt":      _fmt_dt(di),
                        "df_fmt":      _fmt_dt(df),
                        "dias":        dias,
                        "abono":       abono,
                        "tem_recibo":  bool(recibo),
                        "s2230_label": s2230_label,
                        "cancelavel":  cancelavel,
                        "motivo_bloq": motivo_bloq,
                    })
        except Exception as e:
            erro = f"Erro ao buscar dados: {e}"

    return render_template(
        "F10_CancelarFerias.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        linhas=linhas,
        anomes_fmt=anomes_fmt,
        folha_aberta=folha_aberta,
        sit_folha=sit_folha,
        erro=erro,
        ok_msg=ok_msg,
        erro_msg=erro_msg,
    )


@app.route("/exec_cancelar_ferias")
def exec_cancelar_ferias():
    if not session.get("logado"):
        return redirect("/")

    id_ev   = request.args.get("id_ev", "").strip()
    mat_raw = request.args.get("mat",   "").strip()
    if not id_ev or not mat_raw:
        return redirect("/cad_cancelar_ferias")

    id_cliente = session.get("id_cliente")
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    mat        = int(mat_raw)
    msg_erro   = None
    di_log     = ""
    df_log     = ""

    try:
        # 1. Folha aberta
        if _refresh_situacao_folha() not in ("A", "X"):
            raise Exception("Folha do período está fechada — cancelamento não permitido.")

        # 2. Busca e valida o evento
        r_ev = (supabase.table("tab_eventos")
                .select("id, data1i, data1f")
                .eq("id", int(id_ev))
                .eq("id_empresa", id_empresa)
                .eq("id_cliente", id_cliente)
                .eq("matricula", mat)
                .eq("op1", 3)
                .limit(1).execute())
        if not r_ev.data:
            raise Exception("Evento de férias não encontrado.")
        ev     = r_ev.data[0]
        di_log = str(ev.get("data1i") or "")
        df_log = str(ev.get("data1f") or "")

        # 3. Bloqueia se S-2230 já tem recibo
        r_es = (supabase.table("tab_esocial")
                .select("recibo")
                .eq("id_empresa", id_empresa)
                .eq("layout", "2230")
                .eq("codigo2", int(id_ev))
                .execute())
        for es in (r_es.data or []):
            if (es.get("recibo") or "").strip():
                raise Exception("S-2230 já enviado com recibo — não pode ser cancelado.")

        folha_int = int(anomes) if anomes else None

        # 4. Cancela tab_mov (apenas folha_tipo F)
        (supabase.table("tab_mov")
         .delete()
         .eq("id_cliente", id_cliente)
         .eq("id_empresa", id_empresa)
         .eq("matricula",  mat)
         .eq("folha",      folha_int)
         .eq("folha_tipo", "F")
         .execute())

        # 5. Cancela tab_total (apenas folha_tipo F)
        (supabase.table("tab_total")
         .delete()
         .eq("id_cliente", id_cliente)
         .eq("id_empresa", id_empresa)
         .eq("matricula",  mat)
         .eq("folha",      folha_int)
         .eq("folha_tipo", "F")
         .execute())

        # 6. Cancela S-2230 vinculado ao evento
        (supabase.table("tab_esocial")
         .delete()
         .eq("id_empresa", id_empresa)
         .eq("layout",     "2230")
         .eq("codigo2",    int(id_ev))
         .execute())

        # 7. Cancela o evento (tab_reg)
        (supabase.table("tab_eventos")
         .delete()
         .eq("id",         int(id_ev))
         .eq("id_empresa", id_empresa)
         .execute())

    except Exception as e:
        if not msg_erro:
            msg_erro = str(e)[:300]

    if not msg_erro:
        gravar_log("FERIAS",
                   f"CANCEL id:{id_ev} ini:{_fmt_dt(di_log)} fim:{_fmt_dt(df_log)}",
                   matricula=mat)

    if msg_erro:
        from urllib.parse import quote as _quote
        return redirect(f"/cad_cancelar_ferias?erro={_quote(msg_erro)}")
    return redirect("/cad_cancelar_ferias?ok=1")


# =========================================================
# INSALUBRIDADE / PERICULOSIDADE — TELA
# =========================================================
@app.route("/cad_insalub_pericu")
def cad_insalub_pericu():
    if not session.get("logado"):
        return redirect("/")

    mats_raw = request.args.get("mats", "").strip()
    mats = [int(m) for m in mats_raw.split(",") if m.strip().isdigit()]
    if len(mats) != 1:
        return redirect("/select_funcionario?contexto=insalub_pericu")

    matricula  = mats[0]
    id_empresa = _get_id_empresa()

    func = {}
    try:
        r = (supabase.table("tab_cad")
             .select("matricula, nome, situacao")
             .eq("id_empresa", id_empresa)
             .eq("matricula", matricula)
             .single()
             .execute())
        func = r.data or {}
    except Exception:
        pass

    if not func:
        return redirect("/select_funcionario?contexto=insalub_pericu")

    def _buscar_ativo(op1):
        try:
            r = (supabase.table("tab_eventos")
                 .select("id, data1i, ref1")
                 .eq("id_empresa", id_empresa)
                 .eq("matricula", matricula)
                 .eq("op1", op1)
                 .is_("data1f", "null")
                 .order("data1i", desc=True)
                 .limit(1)
                 .execute())
            return (r.data or [None])[0]
        except Exception:
            return None

    def _fmt_ev(ev):
        if not ev:
            return None
        d = str(ev.get("data1i") or "")
        data_fmt = f"{d[6:8]}/{d[4:6]}/{d[0:4]}" if len(d) == 8 else "—"
        ref1 = ev.get("ref1")
        try:
            per_fmt = f"{float(ref1) / 100:g}%"
        except Exception:
            per_fmt = "—"
        return {"id": ev.get("id"), "data1i": d, "data_fmt": data_fmt, "per_fmt": per_fmt}

    insalub_ativo = _fmt_ev(_buscar_ativo(31))
    pericu_ativo  = _fmt_ev(_buscar_ativo(41))

    anomes = str(session.get("anomes_atual") or "")
    data_default = f"01/{anomes[4:6]}/{anomes[0:4]}" if len(anomes) == 6 else ""

    return render_template(
        "F10_Cad_InsalubPericu.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        nome=session.get("nome", ""),
        mats_raw=mats_raw,
        matricula=matricula,
        mat_fmt=str(matricula).zfill(6),
        func_nome=func.get("nome", ""),
        insalub_ativo=insalub_ativo,
        pericu_ativo=pericu_ativo,
        data_default=data_default,
    )


# =========================================================
# INSALUBRIDADE / PERICULOSIDADE — API GRAVAR
# =========================================================
@app.route("/api/insalub_pericu/gravar", methods=["POST"])
def api_insalub_pericu_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão inválida"})

    d          = request.get_json() or {}
    id_cliente = session.get("id_cliente")
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")

    mat_raw = str(d.get("matricula") or "").strip()
    if not mat_raw.isdigit():
        return jsonify({"ok": False, "msg": "Matrícula inválida"})
    mat_int = int(mat_raw)

    # Busca dtadm para validação de admissão × folha ativa
    dtadm_func = ""
    try:
        r_adm = (supabase.table("tab_cad")
                 .select("dtadm")
                 .eq("id_empresa", id_empresa)
                 .eq("matricula", mat_int)
                 .limit(1)
                 .execute())
        if r_adm.data:
            dtadm_func = str(r_adm.data[0].get("dtadm") or "")
    except Exception:
        pass

    def _dmy_to_ymd(s):
        try:
            p = (s or "").strip().split("/")
            return p[2] + p[1] + p[0] if len(p) == 3 and all(x.isdigit() for x in p) else ""
        except Exception:
            return ""

    msgs, erros = [], []

    for tipo, op1_val, label in [("insalub", 31, "Insalubridade"), ("pericu", 41, "Periculosidade")]:
        acao = (d.get(f"acao_{tipo}") or "").strip().lower()

        if acao == "incluir":
            data_ymd = _dmy_to_ymd(d.get(f"data_{tipo}") or "")
            per_raw  = d.get(f"per_{tipo}")
            if not data_ymd or len(data_ymd) != 8:
                erros.append(f"Data inválida para {label}"); continue
            if len(dtadm_func) == 8 and dtadm_func[:6] > anomes:
                erros.append(f"{label}: admissão ({_fmt_dt(dtadm_func)}) posterior à folha ativa — inclusão não permitida"); continue
            try:
                ref1_val = int(round(float(per_raw) * 100))
            except (TypeError, ValueError):
                erros.append(f"Percentual inválido para {label}"); continue
            if ref1_val <= 0:
                erros.append(f"Percentual deve ser maior que zero ({label})"); continue
            try:
                supabase.table("tab_eventos").insert({
                    "id_cliente": id_cliente,
                    "id_empresa": id_empresa,
                    "matricula":  mat_int,
                    "folha":      int(anomes) if anomes else None,
                    "op1":        op1_val,
                    "data1i":     data_ymd,
                    "ref1":       ref1_val,
                }).execute()
                gravar_log(f"{label[:7].upper()}-INC",
                           f"mat:{mat_int} perc:{ref1_val/100:.2f}% dt:{data_ymd}",
                           matricula=mat_int)
                msgs.append(f"{label} incluída — {ref1_val/100:g}% a partir de {_fmt_dt(data_ymd)}")
            except Exception as e:
                erros.append(f"Erro ao gravar {label}: {str(e)[:80]}")

        elif acao == "cancelar":
            id_ev    = str(d.get(f"id_evento_{tipo}") or "").strip()
            data_ymd = _dmy_to_ymd(d.get(f"data_{tipo}") or "")
            if not id_ev:
                erros.append(f"ID do evento não informado ({label})"); continue
            if not data_ymd or len(data_ymd) != 8:
                erros.append(f"Data de encerramento inválida ({label})"); continue
            try:
                supabase.table("tab_eventos").update({"data1f": data_ymd}) \
                    .eq("id", id_ev).eq("id_empresa", id_empresa).execute()
                gravar_log(f"{label[:7].upper()}-CANC",
                           f"mat:{mat_int} id:{id_ev} dt:{data_ymd}",
                           matricula=mat_int)
                msgs.append(f"{label} encerrada em {_fmt_dt(data_ymd)}")
            except Exception as e:
                erros.append(f"Erro ao cancelar {label}: {str(e)[:80]}")

    if not msgs and not erros:
        return jsonify({"ok": False, "msg": "Nenhuma operação selecionada."})
    if erros and not msgs:
        return jsonify({"ok": False, "msg": " | ".join(erros)})

    msg_final = " | ".join(msgs)
    if erros:
        msg_final += "  (erros: " + " | ".join(erros) + ")"
    return jsonify({"ok": True, "msg": msg_final})


