def _parse_ide_response(xml_resp):
    """Extrai lista de IDs da resposta de ConsultarIdentificadoresEventos.
    Retorna {'ok': bool, 'status': {cdResp, descResp}, 'ids': [{id, tpEvt}], 'erro': str}."""
    from lxml import etree
    out = {"ok": False, "status": {}, "ids": [], "erro": ""}
    if not xml_resp or not xml_resp.strip():
        out["erro"] = "Resposta vazia."
        return out
    try:
        root = etree.fromstring(xml_resp.encode("utf-8", errors="replace"))
    except Exception as e:
        out["erro"] = f"XML inválido: {e}"
        return out
    # SOAP Fault
    for el in root.iter():
        if isinstance(el.tag, str) and el.tag.split("}")[-1] == "Fault":
            for c in el.iter():
                if isinstance(c.tag, str) and c.tag.split("}")[-1] == "faultstring":
                    out["erro"] = f"SOAP Fault: {(c.text or '').strip()}"
                    return out
    # Status + IDs (tags sem namespace pra ficar resiliente entre versões do schema)
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        tag = el.tag.split("}")[-1]
        txt = (el.text or "").strip()
        if tag == "cdResposta":
            out["status"]["cdResp"] = txt
        elif tag == "descResposta":
            out["status"]["descResp"] = txt
    # Coleta cada <ideEvento> contendo <id> e <tpEvt>
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        if el.tag.split("}")[-1] != "ideEvento":
            continue
        item = {"id": "", "tpEvt": "", "nrRecEvt": "", "perApur": ""}
        for c in el:
            if not isinstance(c.tag, str):
                continue
            t = c.tag.split("}")[-1]
            txt = (c.text or "").strip()
            if t == "id":          item["id"]       = txt
            elif t == "tpEvt":     item["tpEvt"]    = txt
            elif t == "nrRecEvt":  item["nrRecEvt"] = txt
            elif t == "perApur":   item["perApur"]  = txt
        if item["id"]:
            out["ids"].append(item)
    cd = out["status"].get("cdResp", "")
    # 200/201/202 = sucesso na consulta (mesmo sem eventos)
    out["ok"] = cd.startswith("2") if cd else bool(out["ids"])
    return out


def _parse_dwn_response(xml_resp):
    """Extrai eventos individuais da resposta de SolicitarDownloadEventosPorId.
    Retorna {'ok': bool, 'status': {...}, 'eventos': [{id, xml_str}], 'erro': str}."""
    from lxml import etree
    out = {"ok": False, "status": {}, "eventos": [], "erro": ""}
    if not xml_resp or not xml_resp.strip():
        out["erro"] = "Resposta vazia."
        return out
    try:
        root = etree.fromstring(xml_resp.encode("utf-8", errors="replace"))
    except Exception as e:
        out["erro"] = f"XML inválido: {e}"
        return out
    for el in root.iter():
        if isinstance(el.tag, str) and el.tag.split("}")[-1] == "Fault":
            for c in el.iter():
                if isinstance(c.tag, str) and c.tag.split("}")[-1] == "faultstring":
                    out["erro"] = f"SOAP Fault: {(c.text or '').strip()}"
                    return out
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        tag = el.tag.split("}")[-1]
        txt = (el.text or "").strip()
        if tag == "cdResposta":
            out["status"]["cdResp"] = txt
        elif tag == "descResposta":
            out["status"]["descResp"] = txt
    # Cada <evento Id="..."> com o XML do evento dentro (ou um child <eSocial>)
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        if el.tag.split("}")[-1] != "evento":
            continue
        evt_id = el.get("Id") or el.get("id") or ""
        # O conteúdo é tipicamente o XML completo do evento eSocial — pega o primeiro filho elemento
        xml_inner = ""
        for c in el:
            if isinstance(c.tag, str):
                xml_inner = etree.tostring(c, encoding="unicode")
                break
        if not xml_inner:
            xml_inner = (el.text or "").strip()
        if xml_inner:
            out["eventos"].append({"id": evt_id, "xml": xml_inner})
    cd = out["status"].get("cdResp", "")
    out["ok"] = cd.startswith("2") if cd else bool(out["eventos"])
    return out


def _tipo_evt_do_xml(xml_str):
    """Detecta o tpEvt (S-5001, S-5002, etc.) inspecionando o XML do evento."""
    import re as _re
    m = _re.search(r'<(evt[A-Za-z0-9]+)\b', xml_str)
    if not m:
        return ""
    tag = m.group(1)
    mapa = {
        "evtBasesTrab":    "S-5001",
        "evtIrrfBenef":    "S-5002",
        "evtBasesFGTS":    "S-5003",
        "evtCS":           "S-5011",
        "evtIrrf":         "S-5012",
        "evtFGTS":         "S-5013",
    }
    return mapa.get(tag, "")


def _http_post_cert(url, soap_body, pfx_bytes, senha_str, soap_action=""):
    """POST HTTPS com mTLS (certificado A1) e sem verificação de CA."""
    import tempfile, os as _os
    from cryptography.hazmat.primitives.serialization import (
        pkcs12, Encoding, PrivateFormat, NoEncryption
    )
    senha = senha_str.encode() if isinstance(senha_str, str) else senha_str
    pk, cert, _ = pkcs12.load_key_and_certificates(pfx_bytes, senha)
    key_pem  = pk.private_bytes(Encoding.PEM, PrivateFormat.TraditionalOpenSSL, NoEncryption())
    cert_pem = cert.public_bytes(Encoding.PEM)

    kf = tempfile.NamedTemporaryFile(delete=False, suffix=".key.pem")
    cf = tempfile.NamedTemporaryFile(delete=False, suffix=".cert.pem")
    try:
        kf.write(key_pem);  kf.close()
        cf.write(cert_pem); cf.close()
        resp = requests.post(
            url,
            data=soap_body.encode("utf-8"),
            headers={"Content-Type": "text/xml;charset=UTF-8",
                     "SOAPAction": f'"{soap_action}"'},
            cert=(cf.name, kf.name),
            verify=False,
            timeout=60,
        )
        body = resp.text or ""
        if resp.status_code != 200 or not body.strip():
            raise Exception(
                f"HTTP {resp.status_code} | URL: {url} | "
                f"Content-Type: {resp.headers.get('Content-Type','')} | "
                f"Body: {body[:500] or '(vazio)'}"
            )
        return body
    finally:
        _os.unlink(kf.name)
        _os.unlink(cf.name)


def _analisar_resposta_envio(xml_resp):
    """
    Analisa a resposta SOAP do eSocial (envio de lote).
    Retorna dict: nr_rec, cd_resp, desc, erro.
    """
    from lxml import etree

    vazio = {"nr_rec": "", "cd_resp": "", "desc": "", "erro": ""}

    if not xml_resp or not xml_resp.strip():
        return {**vazio, "erro": "Resposta vazia do servidor eSocial."}

    try:
        root = etree.fromstring(xml_resp.encode("utf-8", errors="replace"))
    except Exception:
        trecho = xml_resp[:300]
        return {**vazio, "erro": f"Resposta não é XML válido: {trecho}"}

    result = dict(vazio)

    # 1. SOAP Fault (erro de protocolo ou autenticação)
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        if el.tag.split("}")[-1] == "Fault":
            for c in el:
                if not isinstance(c.tag, str):
                    continue
                if c.tag.split("}")[-1] == "faultstring":
                    result["erro"] = f"SOAP Fault: {(c.text or '').strip()}"
            if not result["erro"]:
                result["erro"] = "SOAP Fault sem descrição."
            return result

    # 2. Campos do retorno eSocial
    for el in root.iter():
        if not isinstance(el.tag, str):
            continue
        tag = el.tag.split("}")[-1]
        txt = (el.text or "").strip()
        if tag in ("protocoloEnvio", "nrProtEnvio") and not result["nr_rec"]:  result["nr_rec"]  = txt
        if tag == "cdResposta"     and not result["cd_resp"]: result["cd_resp"] = txt
        if tag == "descResposta"   and not result["desc"]:    result["desc"]    = txt

    # 3. Avalia resultado
    if result["nr_rec"]:
        return result   # sucesso

    # Sem nrRec → erro
    if result["cd_resp"] or result["desc"]:
        result["erro"] = f"[{result['cd_resp']}] {result['desc']}"
    else:
        result["erro"] = f"nrRec não encontrado na resposta: {xml_resp[:400]}"

    return result


def _extrair_resultado_consulta(xml_resp):
    """Retorna dict com cdResposta, descResposta, dhProcessamento e recibo por evento."""
    from lxml import etree
    result = {"cdResposta": "", "descResposta": "", "dhProcessamento": "", "eventos": []}
    try:
        root = etree.fromstring(xml_resp.encode())
        for el in root.iter():
            tag = el.tag.split("}")[-1]
            if tag == "cdResposta"      and not result["cdResposta"]:
                result["cdResposta"] = (el.text or "").strip()
            if tag == "descResposta"    and not result["descResposta"]:
                result["descResposta"] = (el.text or "").strip()
            if tag == "dhProcessamento" and not result["dhProcessamento"]:
                result["dhProcessamento"] = (el.text or "").strip()
        # recibos e ocorrências por evento
        for ev in root.iter():
            if ev.tag.split("}")[-1] == "evento":
                nrRec   = ""
                cdEvt   = ""
                dscEvt  = ""
                dhEvt   = ""
                ocorrs  = []
                for c in ev.iter():
                    t = c.tag.split("}")[-1]
                    if t in ("nrRec", "nrRecibo"): nrRec  = (c.text or "").strip()
                    if t == "cdResposta":           cdEvt  = (c.text or "").strip()
                    if t == "descResposta":         dscEvt = (c.text or "").strip()
                    if t == "dhProcessamento":      dhEvt  = (c.text or "").strip()
                for oc in ev.iter():
                    if oc.tag.split("}")[-1] == "ocorrencia":
                        cod  = ""
                        desc = ""
                        for ch in oc:
                            ct = ch.tag.split("}")[-1]
                            if ct == "codigo":    cod  = (ch.text or "").strip()
                            if ct == "descricao": desc = (ch.text or "").strip()
                        if desc:
                            ocorrs.append(f"[{cod}] {desc}" if cod else desc)
                result["eventos"].append({
                    "nrRec":   nrRec,
                    "cdResp":  cdEvt,
                    "dscResp": dscEvt,
                    "dh":      dhEvt,
                    "ocorrs":  ocorrs,
                })
                # dhProcessamento do evento tem precedência sobre o do lote
                if dhEvt and not result["dhProcessamento"]:
                    result["dhProcessamento"] = dhEvt
    except Exception:
        pass
    return result


# =========================================================
# eSocial S-2200 — GERADOR DE XML
# =========================================================
def _gerar_xml_s2200(func, empresa, tpAmb="1"):
    """Gera string XML do S-2200 (Admissão/Ingresso de Trabalhador)."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def fmt_d8(v):
        s = str(int(v)).zfill(8) if isinstance(v, int) else str(v or '').strip()
        return f"{s[:4]}-{s[4:6]}-{s[6:]}" if len(s) == 8 and s.isdigit() else ''

    def fmt_sal(centavos):
        try:
            return f"{int(centavos) / 100:.2f}"
        except Exception:
            return "0.00"

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    # ID{tpInsc=1}{cnpj_raiz padded to 14}{AAAAMMDDHHMMSS}{nrSeqEvento5}
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf       = dg(func.get('cpf', ''))
    nome      = func.get('nome', '')
    nomemae   = func.get('nomemae', '') or ''
    sexo      = func.get('sexo', 'M') or 'M'
    racacor   = str(func.get('racacor') or '6')
    estciv    = str(func.get('estciv') or '9')
    grauinstr = str(func.get('grauinstr') or '07').zfill(2)
    dtnascto  = fmt_d8(func.get('dtnascto'))

    cep       = dg(func.get('ender_cep', ''))
    dsclograd = func.get('ender_dsclograd', '') or ''
    nrlograd  = func.get('ender_nrlograd', '') or 'S/N'
    compl     = func.get('ender_complemento', '') or ''
    bairro    = func.get('ender_bairro', '') or ''
    codmunic  = str(func.get('ender_codmunic') or '')
    uf        = func.get('ender_uf', '') or ''

    dtadm       = fmt_d8(func.get('dtadm'))
    mat_es      = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)
    codcateg    = str(func.get('codcateg') or '101')
    cbo         = str(func.get('cbofuncao') or '')
    # Busca nome do cargo na tabela de funções pelo CBO
    nmcargo = str(func.get('nmcargo') or '').strip()
    if not nmcargo and cbo:
        try:
            _rc = supabase.table("tab_aux_funcao_total").select("cbo_nome")\
                          .eq("cbo_codigo", cbo).limit(1).execute()
            if _rc.data:
                nmcargo = str(_rc.data[0].get('cbo_nome') or '').strip()
        except Exception:
            pass
    if not nmcargo:
        nmcargo = f"CBO {cbo}" if cbo else "Empregado"

    vrsalfx     = fmt_sal(func.get('vrsalfx') or 0)
    _und_map    = {'H':'1','D':'2','S':'3','Q':'4','M':'5','T':'6','N':'7'}
    _und_raw    = str(func.get('undsalfixo', '5') or '5')
    undsalfixo  = _und_map.get(_und_raw.upper(), _und_raw)
    tpadmissao  = str(func.get('tpadmissao') or '1')
    indadmissao = str(func.get('indadmissao') or '1')
    tpregjor    = str(func.get('tpregjor') or '2')
    natatividade= str(func.get('natatividade') or '1')
    tmpparc     = str(func.get('tmpparc') or '0')
    tpjornada   = str(func.get('tpjornada') or '2')
    hornoturno  = func.get('hornoturno', 'N') or 'N'
    try:
        qtdhrssem = str(int(float(func.get('qtdhrssem') or 44)))
    except Exception:
        qtdhrssem = "44"
    lt_tpinsc  = str(func.get('lt_tpinsc') or '1')
    lt_nrinsc  = dg(func.get('lt_nrinsc') or '') or cnpj_emp
    cnpjsind   = dg(func.get('cnpjsindcategprof') or '')

    # Duração do contrato
    tpcontr    = str(func.get('tpcontr') or '1')
    _dtterm_raw = str(func.get('datarescisao') or '').strip()
    _dtterm_fmt = fmt_d8(_dtterm_raw) if _dtterm_raw else ''
    if tpcontr == '2' and _dtterm_fmt:
        _clauassec   = x(func.get('clausassec', 'N') or 'N')
        _objdet      = str(func.get('objdet') or '').strip()
        _objdet_xml  = f"\n          <objDet>{x(_objdet)}</objDet>" if _objdet else ''
        duracao_xml  = (f"\n        <duracao>"
                        f"\n          <tpContr>2</tpContr>"
                        f"\n          <dtTerm>{_dtterm_fmt}</dtTerm>"
                        f"\n          <clauAssec>{_clauassec}</clauAssec>{_objdet_xml}"
                        f"\n        </duracao>")
    else:
        duracao_xml  = "\n        <duracao>\n          <tpContr>1</tpContr>\n        </duracao>"

    # Blocos opcionais
    nomemae_xml = f"\n        <nomeMae>{x(nomemae)}</nomeMae>" if nomemae else ''
    compl_xml   = f"\n          <complemento>{x(compl)}</complemento>" if compl else ''
    bairro_xml  = f"\n          <bairro>{x(bairro)}</bairro>" if bairro else ''
    sind_xml    = f"\n          <cnpjSindCategProf>{x(cnpjsind)}</cnpjSindCategProf>" if cnpjsind else ''

    tem_def = any(func.get(c) == 'S' for c in
                  ['deffisica', 'defvisual', 'defauditiva', 'defmental', 'defintelectual'])
    bloco_def = ''
    if tem_def:
        bloco_def = f"""
      <infoDeficiencia>
        <defFisica>{x(func.get('deffisica','N'))}</defFisica>
        <defVisual>{x(func.get('defvisual','N'))}</defVisual>
        <defAuditiva>{x(func.get('defauditiva','N'))}</defAuditiva>
        <defMental>{x(func.get('defmental','N'))}</defMental>
        <defIntelectual>{x(func.get('defintelectual','N'))}</defIntelectual>
        <reabReadap>N</reabReadap>
        <infoCota>{x(func.get('infocota','N'))}</infoCota>
      </infoDeficiencia>"""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtAdmissao/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtAdmissao/v_S_01_03_00 evtAdmissao_v_S_01_03_00.xsd">
  <evtAdmissao Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <trabalhador>
      <cpfTrab>{x(cpf)}</cpfTrab>
      <nmTrab>{x(nome)}</nmTrab>
      <sexo>{x(sexo)}</sexo>
      <racaCor>{x(racacor)}</racaCor>
      <estCiv>{x(estciv)}</estCiv>
      <grauInstr>{x(grauinstr)}</grauInstr>
      <nascimento>
        <dtNascto>{x(dtnascto)}</dtNascto>
        <paisNascto>105</paisNascto>
        <paisNac>105</paisNac>
      </nascimento>
      <endereco>
        <brasil>
          <tpLograd>R</tpLograd>
          <dscLograd>{x(dsclograd)}</dscLograd>
          <nrLograd>{x(nrlograd)}</nrLograd>{compl_xml}{bairro_xml}
          <cep>{x(cep)}</cep>
          <codMunic>{x(codmunic)}</codMunic>
          <uf>{x(uf)}</uf>
        </brasil>
      </endereco>{bloco_def}
    </trabalhador>
    <vinculo>
      <matricula>{x(mat_es)}</matricula>
      <tpRegTrab>1</tpRegTrab>
      <tpRegPrev>1</tpRegPrev>
      <cadIni>N</cadIni>
      <infoRegimeTrab>
        <infoCeletista>
          <dtAdm>{x(dtadm)}</dtAdm>
          <tpAdmissao>{x(tpadmissao)}</tpAdmissao>
          <indAdmissao>{x(indadmissao)}</indAdmissao>
          <tpRegJor>{x(tpregjor)}</tpRegJor>
          <natAtividade>{x(natatividade)}</natAtividade>{sind_xml}
        </infoCeletista>
      </infoRegimeTrab>
      <infoContrato>
        <nmCargo>{x(nmcargo)}</nmCargo>
        <CBOCargo>{x(cbo)}</CBOCargo>
        <codCateg>{x(codcateg)}</codCateg>
        <remuneracao>
          <vrSalFx>{x(vrsalfx)}</vrSalFx>
          <undSalFixo>{x(undsalfixo)}</undSalFixo>
        </remuneracao>{duracao_xml}
        <localTrabalho>
          <localTrabGeral>
            <tpInsc>{x(lt_tpinsc)}</tpInsc>
            <nrInsc>{x(lt_nrinsc)}</nrInsc>
          </localTrabGeral>
        </localTrabalho>
        <horContratual>
          <qtdHrsSem>{qtdhrssem}</qtdHrsSem>
          <tpJornada>{x(tpjornada)}</tpJornada>
          <tmpParc>{x(tmpparc)}</tmpParc>
          <horNoturno>{x(hornoturno)}</horNoturno>
          <dscJorn>Jornada de trabalho conforme contrato</dscJorn>
        </horContratual>
      </infoContrato>
    </vinculo>
  </evtAdmissao>
</eSocial>"""


def _gerar_xml_s2300(func, empresa, tpAmb="1"):
    """Gera string XML do S-2300 (evtTSVInicio — Início de TSVE / não-empregado).

    Categorias tratadas: 721/722/723 (contribuinte individual / diretor) e
    901 (estagiário). O bloco <infoEstagiario> só é emitido para 901.
    Estrutura baseada no schema evtTSVInicio v_S_01_03_00. Os campos de
    estágio vêm das colunas est_* / nat/niv/dtprevterm de tab_cad."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def fmt_d8(v):
        s = str(int(v)).zfill(8) if isinstance(v, int) else str(v or '').strip()
        return f"{s[:4]}-{s[4:6]}-{s[6:]}" if len(s) == 8 and s.isdigit() else ''

    def fmt_sal(centavos):
        try:
            return f"{int(centavos) / 100:.2f}"
        except Exception:
            return "0.00"

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf       = dg(func.get('cpf', ''))
    nome      = func.get('nome', '')
    sexo      = func.get('sexo', 'M') or 'M'
    racacor   = str(func.get('racacor') or '6')
    estciv    = str(func.get('estciv') or '9')
    grauinstr = str(func.get('grauinstr') or '07').zfill(2)
    dtnascto  = fmt_d8(func.get('dtnascto'))

    cep       = dg(func.get('ender_cep', ''))
    dsclograd = func.get('ender_dsclograd', '') or ''
    nrlograd  = func.get('ender_nrlograd', '') or 'S/N'
    compl     = func.get('ender_complemento', '') or ''
    bairro    = func.get('ender_bairro', '') or ''
    codmunic  = str(func.get('ender_codmunic') or '')
    uf        = func.get('ender_uf', '') or ''

    dtinicio  = fmt_d8(func.get('dtadm'))
    mat_es    = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)
    codcateg  = str(func.get('codcateg') or '901')
    cbo       = str(func.get('cbofuncao') or '')

    # Nome do cargo pelo CBO (mesmo lookup do S-2200)
    nmcargo = str(func.get('nmcargo') or '').strip()
    if not nmcargo and cbo:
        try:
            _rc = supabase.table("tab_aux_funcao_total").select("cbo_nome")\
                          .eq("cbo_codigo", cbo).limit(1).execute()
            if _rc.data:
                nmcargo = str(_rc.data[0].get('cbo_nome') or '').strip()
        except Exception:
            pass
    if not nmcargo:
        nmcargo = f"CBO {cbo}" if cbo else "Estagiário"

    vrsalfx     = fmt_sal(func.get('vrsalfx') or 0)
    _und_map    = {'H':'1','D':'2','S':'3','Q':'4','M':'5','T':'6','N':'7'}
    _und_raw    = str(func.get('undsalfixo', '5') or '5')
    undsalfixo  = _und_map.get(_und_raw.upper(), _und_raw)

    is_estagiario = codcateg == '901'

    # Blocos opcionais do trabalhador (iguais ao S-2200)
    compl_xml   = f"\n          <complemento>{x(compl)}</complemento>" if compl else ''
    bairro_xml  = f"\n          <bairro>{x(bairro)}</bairro>" if bairro else ''

    tem_def = any(func.get(c) == 'S' for c in
                  ['deffisica', 'defvisual', 'defauditiva', 'defmental', 'defintelectual'])
    bloco_def = ''
    if tem_def:
        bloco_def = f"""
      <infoDeficiencia>
        <defFisica>{x(func.get('deffisica','N'))}</defFisica>
        <defVisual>{x(func.get('defvisual','N'))}</defVisual>
        <defAuditiva>{x(func.get('defauditiva','N'))}</defAuditiva>
        <defMental>{x(func.get('defmental','N'))}</defMental>
        <defIntelectual>{x(func.get('defintelectual','N'))}</defIntelectual>
        <reabReadap>N</reabReadap>
        <infoCota>{x(func.get('infocota','N'))}</infoCota>
      </infoDeficiencia>"""

    # ── infoComplementares ──────────────────────────────────
    # cargoFuncao é comum. Para 901 sai <infoEstagiario>; para
    # 721/722/723 sai <remuneracao> (bolsa do estagiário vai no
    # S-1200/S-1210 mensal, não aqui).
    cargo_xml = (f"\n        <cargoFuncao>"
                 f"\n          <nmCargo>{x(nmcargo)}</nmCargo>"
                 f"\n          <CBOCargo>{x(cbo)}</CBOCargo>"
                 f"\n        </cargoFuncao>")

    if is_estagiario:
        natestagio = str(func.get('est_natestagio') or 'N')
        nivestagio = str(func.get('est_nivestagio') or '')
        dtprevterm = fmt_d8(func.get('est_dtprevterm'))
        inst_nome  = func.get('est_inst_nome', '') or ''
        inst_logr  = func.get('est_inst_lograd', '') or ''
        inst_nr    = func.get('est_inst_nr', '') or ''
        inst_cep   = dg(func.get('est_inst_cep', ''))
        inst_munic = str(func.get('est_inst_munic') or '')
        inst_uf    = func.get('est_inst_uf', '') or ''

        inst_nr_xml  = f"\n            <nrLograd>{x(inst_nr)}</nrLograd>" if inst_nr else ''
        inst_cep_xml = f"\n            <cep>{x(inst_cep)}</cep>" if inst_cep else ''

        complementares_xml = (
            f"{cargo_xml}"
            f"\n        <infoEstagiario>"
            f"\n          <natEstagio>{x(natestagio)}</natEstagio>"
            f"\n          <nivEstagio>{x(nivestagio)}</nivEstagio>"
            f"\n          <dtPrevTerm>{x(dtprevterm)}</dtPrevTerm>"
            f"\n          <instEnsino>"
            f"\n            <nmRazao>{x(inst_nome)}</nmRazao>"
            f"\n            <dscLograd>{x(inst_logr)}</dscLograd>{inst_nr_xml}{inst_cep_xml}"
            f"\n            <codMunic>{x(inst_munic)}</codMunic>"
            f"\n            <uf>{x(inst_uf)}</uf>"
            f"\n          </instEnsino>"
            f"\n        </infoEstagiario>")
    else:
        complementares_xml = (
            f"{cargo_xml}"
            f"\n        <remuneracao>"
            f"\n          <vrSalFx>{x(vrsalfx)}</vrSalFx>"
            f"\n          <undSalFixo>{x(undsalfixo)}</undSalFixo>"
            f"\n        </remuneracao>")

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtTSVInicio/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtTSVInicio/v_S_01_03_00 evtTSVInicio_v_S_01_03_00.xsd">
  <evtTSVInicio Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <trabalhador>
      <cpfTrab>{x(cpf)}</cpfTrab>
      <nmTrab>{x(nome)}</nmTrab>
      <sexo>{x(sexo)}</sexo>
      <racaCor>{x(racacor)}</racaCor>
      <estCiv>{x(estciv)}</estCiv>
      <grauInstr>{x(grauinstr)}</grauInstr>
      <nascimento>
        <dtNascto>{x(dtnascto)}</dtNascto>
        <paisNascto>105</paisNascto>
        <paisNac>105</paisNac>
      </nascimento>
      <endereco>
        <brasil>
          <tpLograd>R</tpLograd>
          <dscLograd>{x(dsclograd)}</dscLograd>
          <nrLograd>{x(nrlograd)}</nrLograd>{compl_xml}{bairro_xml}
          <cep>{x(cep)}</cep>
          <codMunic>{x(codmunic)}</codMunic>
          <uf>{x(uf)}</uf>
        </brasil>
      </endereco>{bloco_def}
    </trabalhador>
    <infoTSVInicio>
      <cadIni>N</cadIni>
      <natAtividade>1</natAtividade>
      <dtInicio>{x(dtinicio)}</dtInicio>
      <codCateg>{x(codcateg)}</codCateg>
      <infoComplementares>{complementares_xml}
      </infoComplementares>
    </infoTSVInicio>
  </evtTSVInicio>
</eSocial>"""


# =========================================================
# eSocial S-1200 — GERADOR DE XML
# =========================================================
def _gerar_xml_s1200(func, mov_items, empresa, ano_mes, folha_tipo, tpAmb="1",
                     rubr_map=None):
    """Gera string XML do S-1200 (Remuneração do Trabalhador - RGPS).

    rubr_map: mantido por compatibilidade, não usado. Gov exige <indApurIR>
    em TODAS as rubricas (tentamos omitir nas retentoras/deduções e o gov
    rejeitou com erro 'Campo de preenchimento obrigatório')."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    def fmt_brl(centavos):
        try:
            return f"{int(centavos) / 100:.2f}"
        except Exception:
            return "0.00"

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf      = dg(func.get('cpf', '')).zfill(11)
    mat_es   = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)
    codcateg = str(func.get('codcateg') or '').strip()
    if not codcateg:
        raise ValueError(
            f"Funcionário {func.get('matricula')} sem 'codcateg' no cadastro — "
            "preencha o campo Categoria eSocial em tab_cad antes de enviar o S-1200."
        )

    # infoAgNocivo só vale para empregados (categorias 1xx — CLT, rurais, aprendizes etc.).
    # Para outras categorias (avulsos, dirigentes, contribuintes individuais, etc.)
    # o eSocial não aceita esse grupo.
    _eh_empregado = codcateg.startswith("1")
    info_ag_nocivo_xml = ("""
            <infoAgNocivo>
              <grauExp>1</grauExp>
            </infoAgNocivo>""" if _eh_empregado else "")

    # codLotacao = centrocusto do funcionário em tab_cad
    cod_lotacao = str(func.get('centrocusto') or '').strip()
    if not cod_lotacao:
        raise ValueError(
            f"Funcionário {func.get('matricula')} sem 'centrocusto' no cadastro — "
            "preencha o campo Centro de Custo em tab_cad antes de enviar o S-1200."
        )

    _am     = str(int(ano_mes)).zfill(6)
    per_apur = f"{_am[:4]}-{_am[4:6]}"
    # ATENCAO: <indApuracao> (no ideEvento) e <indApurIR> (em itensRemun)
    # sao campos DIFERENTES e tem enumeracoes diferentes no schema v_S_01_03_00.
    #
    # <indApuracao> (ideEvento): TS_indApuracao = {1, 2}
    #   1 = Mensal (folha normal)
    #   2 = Anual (13º salario)
    #
    # <indApurIR> (itensRemun): TS_indApurIR = {0, 1}
    #   0 = Apuracao Mensal (segue indApuracao=1)
    #   1 = Apuracao Anual (RRA — Rendimentos Recebidos Acumuladamente)
    #
    # Mandar indApurIR=1 em folha mensal faz o gov tratar tudo como RRA, e o
    # S-5012 (IRRF) retorna com indExistInfo=2 (zerado) por conflito com o
    # tpCR=056107 do S-1210.
    ind_apuracao = "2" if folha_tipo in ('1', 'A') else "1"
    ind_apur_ir  = "0"

    # codRubr / ideTabRubr: convenção COMPROVADA como aceita pelo gov (XMLs do
    # S-1010 com recibo) — codRubr = código CRU (como em tab_rubrica.cod_rubr,
    # sem zero-padding e sem sufixo) e ideTabRubr = raiz do CNPJ (8 dígitos).
    # ANTES gerava "0015-FOL"/"0015-FOL" (não casava com o S-1010) → 0 recibos.
    # O sufixo -FOL/-FER é do DESKTOP, que reusa o mesmo código em contextos
    # diferentes; o web usa códigos distintos, então não precisa de sufixo.
    #
    # <indApurIR> é OBRIGATÓRIO em todo <itensRemun> (gov rejeitou tentativa
    # de omitir em rubricas com tpn_inc_irrf=9/N/31/41). Valor fixo "0" para
    # apuracao mensal (igual ao sistema legado em prod) — usar "1" tornaria
    # tudo RRA e zeraria o S-5012.
    itens_xml = ""
    for item in mov_items:
        cod = str(item.get('cod_verba') or item.get('cod_rubr') or '').strip()
        val = int(item.get('valor') or 0)
        if cod and val != 0:
            itens_xml += f"""
            <itensRemun>
              <codRubr>{x(cod)}</codRubr>
              <ideTabRubr>{x(cnpj_raiz)}</ideTabRubr>
              <vrRubr>{fmt_brl(val)}</vrRubr>
              <indApurIR>{ind_apur_ir}</indApurIR>
            </itensRemun>"""

    if not itens_xml.strip():
        itens_xml = f"""
            <itensRemun>
              <codRubr>1</codRubr>
              <ideTabRubr>{x(cnpj_raiz)}</ideTabRubr>
              <vrRubr>0.00</vrRubr>
              <indApurIR>{ind_apur_ir}</indApurIR>
            </itensRemun>"""

    nis_trab = dg(func.get('nis') or func.get('pis') or '')
    nis_xml  = f"\n      <nisTrab>{x(nis_trab)}</nisTrab>" if nis_trab else ""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtRemun/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtRemun/v_S_01_03_00 evtRemun_v_S_01_03_00.xsd">
  <evtRemun Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <indApuracao>{ind_apuracao}</indApuracao>
      <perApur>{per_apur}</perApur>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideTrabalhador>
      <cpfTrab>{x(cpf)}</cpfTrab>{nis_xml}
    </ideTrabalhador>
    <dmDev>
      <ideDmDev>{mat_es}00</ideDmDev>
      <codCateg>{x(codcateg)}</codCateg>
      <infoPerApur>
        <ideEstabLot>
          <tpInsc>1</tpInsc>
          <nrInsc>{x(cnpj_emp)}</nrInsc>
          <codLotacao>{x(cod_lotacao)}</codLotacao>
          <remunPerApur>
            <matricula>{x(mat_es)}</matricula>{itens_xml}{info_ag_nocivo_xml}
          </remunPerApur>
        </ideEstabLot>
      </infoPerApur>
    </dmDev>
  </evtRemun>
</eSocial>"""


# =========================================================
# eSocial S-1210 — GERADOR DE XML
# =========================================================
def _gerar_xml_s1210(func, empresa, ano_mes, folha_tipo, tpAmb, dtPgto,
                     recibo_s1200, totais, mov_items=None, rubr_map=None,
                     deps_irrf=None, vlr_ded_dep_cent=0):
    """Gera string XML do S-1210 (Pagamentos de Rendimentos do Trabalho).

    Dentro de <infoPgto> o schema v_S_01_03_00 é minimalista (so dtPgto,
    tpPgto, perRef, ideDmDev, vrLiq + paisResidExt/infoPgtoExt opcionais —
    NAO existe <detPgtoFl>). Mas <infoIRComplem> EXISTE como irmao de
    <infoPgto> dentro de <ideBenef> e e usado para informar dependentes
    de IRRF + codigo de receita 056107 + deducao de dependente — sem
    esse bloco o gov nao retorna IR retido no S-5002.

    deps_irrf: lista de dependentes IRRF do funcionario (dicts com
        'cpfdep' e 'tpdep'). Vazio = sem dependentes.
    vlr_ded_dep_cent: deducao por dependente em centavos (vem da tabela
        legal IRRF vigente)."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    def fmt_brl(centavos):
        try:
            return f"{int(centavos) / 100:.2f}"
        except Exception:
            return "0.00"

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf      = dg(func.get('cpf', '')).zfill(11)
    mat_es   = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)

    _am      = str(int(ano_mes)).zfill(6)
    per_apur = f"{_am[:4]}-{_am[4:6]}"
    # ideDmDev: identificador unico do demonstrativo do trabalhador (S-1200)
    # que o S-1210 referencia. Tem que ser DIFERENTE por trabalhador (usar
    # so o per_apur deixa todos com mesmo ID, e o gov nao casa o pagamento
    # com a remuneracao certa — zera o S-5012). Padrao do legado: matricula
    # 6 digitos + "00" (ex.: matricula 1 -> "00000100").
    ide_dm_dev = f"{mat_es}00"

    _TP_PGTO = {'N': '1', '1': '2', 'A': '2', 'F': '4', 'R': '3'}
    tp_pgto  = _TP_PGTO.get(str(folha_tipo), '1')

    vr_total = fmt_brl(totais.get('valor_liquido', 0))

    # ── infoIRComplem ───────────────────────────────────────────────────
    # Bloco usado pelo gov para conciliar a retencao de IRRF no S-5002.
    # Gera quando ha dependente IRRF cadastrado (depirrf='S').
    deps_irrf = deps_irrf or []
    info_ir_xml = ""
    if deps_irrf:
        info_dep_xml = ""
        ded_depen_xml = ""
        for _d in deps_irrf:
            _cpfd = dg(_d.get("cpfdep") or "").zfill(11)
            _tpd  = str(_d.get("tpdep") or "").strip().zfill(2)
            if not _cpfd or not _tpd:
                continue
            info_dep_xml += f"""
        <infoDep>
          <cpfDep>{x(_cpfd)}</cpfDep>
          <depIRRF>S</depIRRF>
          <tpDep>{x(_tpd)}</tpDep>
        </infoDep>"""
            ded_depen_xml += f"""
          <dedDepen>
            <tpRend>11</tpRend>
            <cpfDep>{x(_cpfd)}</cpfDep>
            <vlrDedDep>{fmt_brl(vlr_ded_dep_cent)}</vlrDedDep>
          </dedDepen>"""
        if info_dep_xml or ded_depen_xml:
            info_ir_xml = f"""
      <infoIRComplem>{info_dep_xml}
        <infoIRCR>
          <tpCR>056107</tpCR>{ded_depen_xml}
        </infoIRCR>
      </infoIRComplem>"""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtPgtos/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtPgtos/v_S_01_03_00 evtPgtos_v_S_01_03_00.xsd">
  <evtPgtos Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <perApur>{per_apur}</perApur>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideBenef>
      <cpfBenef>{x(cpf)}</cpfBenef>
      <infoPgto>
        <dtPgto>{x(dtPgto)}</dtPgto>
        <tpPgto>{x(tp_pgto)}</tpPgto>
        <perRef>{per_apur}</perRef>
        <ideDmDev>{ide_dm_dev}</ideDmDev>
        <vrLiq>{vr_total}</vrLiq>
      </infoPgto>{info_ir_xml}
    </ideBenef>
  </evtPgtos>
</eSocial>"""


# =========================================================
# eSocial S-3000 — GERADOR DE XML
# =========================================================
def _gerar_xml_s3000(recibo_excluir, tp_evento, cpf_trab, empresa, tpAmb="1",
                     ano_mes=None, folha_tipo=None):
    """Gera string XML do S-3000 (Exclusão de Eventos).
    cpf_trab vazio = evento de empregador (S-1000, S-1005, etc.) — sem ideTrabalhador.
    ano_mes + folha_tipo: obrigatórios ao excluir periódico (S-1200/1210/1295/1298/1299/1280/1270)
        — o gov exige <ideFolhaPagto> dentro de <infoExclusao>."""
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt
    import re

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    # Para periódicos (S-1200/1210/1299...) o gov exige nesta ORDEM dentro de
    # <infoExclusao>:  tpEvento → nrRecEvt → ideTrabalhador → ideFolhaPagto.
    # Para S-2xxx (não-periódicos com trabalhador): só <ideTrabalhador>.
    # Para S-1xxx empregador (S-1000/1005/1010/1020): nada extra.
    PERIODICOS = {"1200", "1210", "1270", "1280", "1295", "1298", "1299"}
    tp_evt_num = str(tp_evento).strip()

    ide_trab_xml = ""
    if cpf_trab:
        ide_trab_xml = (
            f"\n      <ideTrabalhador>"
            f"\n        <cpfTrab>{x(cpf_trab)}</cpfTrab>"
            f"\n      </ideTrabalhador>"
        )

    ide_folha_xml = ""
    if tp_evt_num in PERIODICOS:
        if not ano_mes:
            raise ValueError(
                f"S-3000 para S-{tp_evt_num} exige ano_mes (periódico) — "
                "passe ano_mes do registro original.")
        _am = str(int(ano_mes)).zfill(6)
        # 13º (folha_tipo 1/A) → perApur=YYYY; demais → YYYY-MM
        eh_anual = str(folha_tipo or "").upper() in ("1", "A")
        per_apur = _am[:4] if eh_anual else f"{_am[:4]}-{_am[4:6]}"
        # S-1210 (Pagamentos) é o único periódico sem indApuracao no XSD do
        # gov; os outros (S-1200/1270/1280/1295/1298/1299) exigem.
        if tp_evt_num == "1210":
            ide_folha_xml = (
                f"\n      <ideFolhaPagto>"
                f"\n        <perApur>{per_apur}</perApur>"
                f"\n      </ideFolhaPagto>"
            )
        else:
            ind_apur = "2" if eh_anual else "1"
            ide_folha_xml = (
                f"\n      <ideFolhaPagto>"
                f"\n        <indApuracao>{ind_apur}</indApuracao>"
                f"\n        <perApur>{per_apur}</perApur>"
                f"\n      </ideFolhaPagto>"
            )

    return f"""<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtExclusao/v_S_01_03_00">
  <evtExclusao Id="{evt_id}">
    <ideEvento>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <infoExclusao>
      <tpEvento>S-{x(tp_evt_num)}</tpEvento>
      <nrRecEvt>{x(recibo_excluir)}</nrRecEvt>{ide_trab_xml}{ide_folha_xml}
    </infoExclusao>
  </evtExclusao>
</eSocial>"""


# =========================================================
# eSocial — helpers de contexto (S-1005 / S-1010 / S-1020)
# =========================================================
def _ctx_esocial():
    cnpj_raw = so_numeros(session.get("cnpj_empresa", ""))
    cnpj_fmt = _fmt_cnpj(cnpj_raw) if len(cnpj_raw) == 14 else cnpj_raw
    return dict(
        versao=ler_versao(),
        empresa_info=session.get("empresa_info", ""),
        cnpj_fmt=cnpj_fmt,
    )


# =========================================================
# eSocial S-1000 — GERADOR DE XML
# =========================================================
def _gerar_xml_s1000(empresa, tpAmb, tp_op, ini_valid, fim_valid, contato_nome, contato_cpf):
    """Gera string XML do S-1000 (Informações do Empregador/Contribuinte).
    tp_op: 'inclusao' ou 'alteracao'
    ini_valid / fim_valid: 'YYYY-MM'
    """
    import re as _re2
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return _re2.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    nm_razao   = x(empresa.get('razaosocial', ''))
    class_trib = str(empresa.get('class_trib') or '01').zfill(2)
    nat_jurid  = str(empresa.get('nat_juridica') or '').strip()
    ind_coop   = str(empresa.get('ind_coop') or '0')
    ind_constr = str(empresa.get('ind_constr') or '0')
    ind_des    = str(empresa.get('ind_des_folha') or '0')
    ind_porte  = str(empresa.get('ind_porte') or '').strip()

    fim_valid_xml = f"\n          <fimValid>{x(fim_valid)}</fimValid>" if fim_valid else ''
    nat_jurid_xml = f"\n          <natJurid>{x(nat_jurid)}</natJurid>" if nat_jurid else ''
    ind_porte_xml = f"\n          <indPorte>{x(ind_porte)}</indPorte>" if ind_porte else ''

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtInfoEmpregador/v02_05_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtInfoEmpregador/v02_05_00 evtInfoEmpregador_v02_05_00.xsd">
  <evtInfoEmpregador Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <infoEmpregador>
      <{tp_op}>
        <idePeriodo>
          <iniValid>{x(ini_valid)}</iniValid>{fim_valid_xml}
        </idePeriodo>
        <infoCadastro>
          <nmRazao>{nm_razao}</nmRazao>
          <classTrib>{x(class_trib)}</classTrib>{nat_jurid_xml}
          <indCoop>{x(ind_coop)}</indCoop>
          <indConstr>{x(ind_constr)}</indConstr>
          <indDesFolha>{x(ind_des)}</indDesFolha>
          <indOptRegEletron>0</indOptRegEletron>{ind_porte_xml}
          <contato>
            <nmCtt>{x(contato_nome)}</nmCtt>
            <cpfCtt>{dg(contato_cpf)}</cpfCtt>
          </contato>
        </infoCadastro>
      </{tp_op}>
    </infoEmpregador>
  </evtInfoEmpregador>
</eSocial>"""


# =========================================================
# eSocial S-1000 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s1000")
def esocial_s1000():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    anomes_folha = str(session.get("anomes_atual") or "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1000"))
        if anomes_folha.isdigit() and len(anomes_folha) == 6:
            q = q.gte("data_cad", anomes_folha + "01").lte("data_cad", anomes_folha + "31")
        rows = (q.order("data_cad", desc=True)
                 .order("hora_cad", desc=True)
                 .execute().data or [])
    except Exception:
        rows = []

    empresa = {}
    try:
        r = supabase.table("tab_empresa").select("*")\
            .eq("cnpj", cnpj_emp).limit(1).execute()
        empresa = r.data[0] if r.data else {}
    except Exception:
        pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    import json as _json
    for r in rows:
        r["_datacad_fmt"]   = _d8(r.get("data_cad"))
        r["_datagrava_fmt"] = _d8(r.get("data_grava"))
        r["_tp_op_label"]   = "Inclusão" if str(r.get("codigo2") or "1") == "1" else "Alteração"

        # Parse stored PARAMS from observacao_erro
        obs = (r.get("observacao_erro") or "").strip()
        r["_ini_valid"] = ""
        r["_fim_valid"] = ""
        r["_ctt_nome"]  = ""
        if obs.startswith("PARAMS:"):
            try:
                p = _json.loads(obs[7:])
                r["_ini_valid"] = p.get("ini", "")
                r["_fim_valid"] = p.get("fim", "")
                r["_ctt_nome"]  = p.get("ctt_nome", "")
            except Exception:
                pass
        # Fallback: derive period from ano_mes
        if not r["_ini_valid"]:
            am = str(r.get("ano_mes") or "")
            if len(am) == 6:
                r["_ini_valid"] = f"{am[:4]}-{am[4:6]}"

        recibo = (r.get("recibo") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs and not obs.startswith("PARAMS:"):
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    _CLASS_TRIB = {
        '01': '01 — CNPJ com FGTS', '02': '02 — CNPJ sem FGTS',
        '03': '03 — Simples Nacional', '04': '04 — Simples c/ FGTS',
        '06': '06 — MEI', '07': '07 — Prod. Rural PF',
        '08': '08 — Órgão Público', '09': '09 — RPPS',
        '21': '21 — Emp. Doméstico', '22': '22 — Emp. Dom. MEI',
    }
    ct = str(empresa.get('class_trib') or '').zfill(2)
    empresa['_class_trib_label'] = _CLASS_TRIB.get(ct, ct or '—')

    cnpj_fmt = _fmt_cnpj(cnpj_emp) if len(cnpj_emp) == 14 else cnpj_emp

    return render_template(
        "F10_eSocial_S1000.html",
        versao=ler_versao(),
        empresa_info=session.get("empresa_info", ""),
        cnpj_fmt=cnpj_fmt,
        rows=rows,
        total=len(rows),
        empresa=empresa,
    )


# =========================================================
# eSocial S-1000 — API: gravar (cria registro pendente)
# =========================================================
@app.route("/api/esocial_s1000_gravar", methods=["POST"])
def api_esocial_s1000_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import json as _json
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    data       = request.get_json(force=True) or {}

    tp_op     = data.get("tp_op", "inclusao")
    ini_valid = data.get("ini_valid", "").strip()
    fim_valid = data.get("fim_valid", "").strip()
    ctt_nome  = data.get("contato_nome", "").strip()
    ctt_cpf   = data.get("contato_cpf", "").strip()
    tpAmb     = str(data.get("tpAmb", "1"))

    if not ini_valid or len(ini_valid) != 7 or ini_valid[4] != '-':
        return jsonify({"ok": False, "msg": "Período de início inválido (use AAAA-MM)."})
    if not ctt_nome:
        return jsonify({"ok": False, "msg": "Nome do contato obrigatório."})
    if len(so_numeros(ctt_cpf)) != 11:
        return jsonify({"ok": False, "msg": "CPF do contato inválido (deve ter 11 dígitos)."})

    codigo2 = 1 if tp_op == "inclusao" else 2
    ano_mes = ini_valid.replace("-", "")

    params_json = _json.dumps({
        "ini": ini_valid, "fim": fim_valid,
        "ctt_nome": ctt_nome, "ctt_cpf": so_numeros(ctt_cpf),
        "tpAmb": tpAmb,
    }, ensure_ascii=False)

    agora = datetime.now()
    try:
        r = supabase.table("tab_esocial").insert({
            "id_cliente":      id_cliente,
            "id_empresa":      id_empresa,
            "data_cad":        agora.strftime("%Y%m%d"),
            "hora_cad":        agora.strftime("%H%M"),
            "layout":          "1000",
            "ano_mes":         int(ano_mes),
            "folha_tipo":      "I",
            "codigo2":         codigo2,
            "operacao":        "I" if tp_op == "inclusao" else "A",
            "observacao_erro": f"PARAMS:{params_json}",
        }).execute()
        id_esocial = r.data[0]["id_esocial"] if r.data else None
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gravar: {e}"})

    if not id_esocial:
        return jsonify({"ok": False, "msg": "Falha ao obter ID do registro."})

    return jsonify({"ok": True, "id_esocial": id_esocial})


# =========================================================
# eSocial S-1000 — API: baixar XML
# =========================================================
@app.route("/api/esocial_s1000_xml")
def api_esocial_s1000_xml():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response
    import json as _json

    id_empresa = _get_id_empresa()
    id_reg     = request.args.get("id", "").strip()
    tpAmb      = request.args.get("tpAmb", "").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain")

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1000")
                .limit(1).execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    # Parse stored params
    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    if obs.startswith("PARAMS:"):
        try:
            params = _json.loads(obs[7:])
        except Exception:
            pass

    ini_valid  = tpAmb and params.get("ini", "") or params.get("ini", "")
    fim_valid  = params.get("fim", "")
    ctt_nome   = params.get("ctt_nome", "")
    ctt_cpf    = params.get("ctt_cpf", "")
    if not tpAmb:
        tpAmb  = params.get("tpAmb", "1")
    tp_op      = "inclusao" if str(es.get("codigo2") or "1") == "1" else "alteracao"

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    xml_str = _gerar_xml_s1000(empresa, tpAmb, tp_op, ini_valid, fim_valid, ctt_nome, ctt_cpf)

    try:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
    except Exception:
        pass

    fname = f"S1000_{ini_valid.replace('-','')}_{tp_op[:3].upper()}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xml"
    return Response(
        xml_str,
        mimetype="application/xml; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# =========================================================
# eSocial S-1000 — API: assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1000_enviar", methods=["POST"])
def api_esocial_s1000_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time, json as _json

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("1000")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # ── 1. Registro na tab_esocial ────────────────────────
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1000")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-1000 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    # Parse stored params
    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    if obs.startswith("PARAMS:"):
        try:
            params = _json.loads(obs[7:])
        except Exception:
            pass

    ini_valid = params.get("ini", "")
    fim_valid = params.get("fim", "")
    ctt_nome  = params.get("ctt_nome", "")
    ctt_cpf   = params.get("ctt_cpf", "")
    if not tpAmb or tpAmb == "1":
        tpAmb = params.get("tpAmb", tpAmb)
    tp_op = "inclusao" if str(es.get("codigo2") or "1") == "1" else "alteracao"

    if not ini_valid:
        return jsonify({"ok": False, "msg": "Parâmetros de envio não encontrados. Recrie o registro."})

    # ── 2. Empresa (cert validado depois do save do XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 3. Gerar XML cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S1000_{ini_valid.replace('-','')}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s1000(empresa, tpAmb, tp_op, ini_valid, fim_valid, ctt_nome, ctt_cpf)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 4. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado. Acesse eSocial → Certificado Digital."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    # ── 6. Montar lote (S-1000 = Grupo 1 — Tabelas) ───────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"), grupo="1")
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 7. Enviar ─────────────────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        supabase.table("tab_esocial").update({
            "observacao_erro": f"Erro no envio: {detalhe[:200]}",
            "data_grava": datetime.now().strftime("%Y%m%d"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, f"Erro no envio: {detalhe}")
        return jsonify({"ok": False, "msg": f"Erro no envio: {detalhe}"})

    _xml_save(f"{_pref}_4_resposta.xml", resp_envio)

    # ── 8. Analisar resposta do envio ─────────────────────
    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    agora = datetime.now()
    if not protocolo_envio:
        supabase.table("tab_esocial").update({
            "observacao_erro": analise["erro"][:295],
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, "eSocial recusou o envio.")
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # ── 9. Consultar resultado (até 3 tentativas) ─────────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta ao eSocial: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta da consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    if recibo_final and not obs_erro and not aguardando:
        return jsonify({"ok": True, "recibo": recibo_final,
                        "msg": f"S-1000 enviado com sucesso. Recibo: {recibo_final}"})
    if aguardando:
        return jsonify({"ok": True, "msg": f"Aguardando processamento. Protocolo: {protocolo_envio}",
                        "protocolo": protocolo_envio})
    _xml_erro_save(_pref, 5, obs_erro)
    return jsonify({"ok": False, "msg": obs_erro or "Erro desconhecido na consulta."})


# =========================================================
# eSocial S-1000 — API: apagar registro local (sem recibo)
# =========================================================
@app.route("/api/esocial_s1000_deletar", methods=["POST"])
def api_esocial_s1000_deletar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa = _get_id_empresa()
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial").select("recibo")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1000")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        if (r_es.data[0].get("recibo") or "").strip():
            return jsonify({"ok": False,
                            "msg": "Registro já foi enviado ao eSocial. Use 'Excluir via S-3000'."})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao verificar registro: {e}"})

    try:
        supabase.table("tab_esocial")\
            .delete()\
            .eq("id_esocial", int(id_reg))\
            .eq("id_empresa", id_empresa)\
            .eq("layout", "1000")\
            .execute()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao apagar: {e}"})

    return jsonify({"ok": True, "msg": "Registro apagado."})


# =========================================================
# eSocial S-1000 — API: excluir via S-3000 (com recibo)
# =========================================================
@app.route("/api/esocial_s1000_excluir", methods=["POST"])
def api_esocial_s1000_excluir():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # ── 1. Buscar registro ────────────────────────────────
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1000")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    recibo_excluir = (es.get("recibo") or "").strip()
    if not recibo_excluir:
        return jsonify({"ok": False,
                        "msg": "Registro sem recibo — use 'Apagar' para remover localmente."})

    # ── 2. Empresa (cert validado depois do save do XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 3. Gerar XML S-3000 cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S3000_S1000_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s3000(recibo_excluir, "1000", "", empresa, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML S-3000: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 4. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    # ── 6. Montar lote (grupo 1 — tabelas) ────────────────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"), grupo="1")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    # ── 7. Enviar ─────────────────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    try:
        resp_envio = _http_post_cert(url_envio, _soap_enviar(lote_xml),
                                     pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro no envio: {e}"})

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    if not protocolo_envio:
        return jsonify({"ok": False, "msg": "eSocial recusou a exclusão.", "detalhe": analise["erro"]})

    # ── 8. Consultar resultado ────────────────────────────
    recibo_excl = ""
    obs_err     = ""
    for _ in range(3):
        time.sleep(10)
        try:
            resp_cons = _http_post_cert(url_consulta, _soap_consultar(protocolo_envio),
                                        pfx_bytes, senha_str, _SA_CONSULTAR)
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_err = f"Erro na consulta: {e}"
            break
        cd = resultado.get("cdResposta", "")
        if cd in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_excl = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                obs_err = " · ".join(ev0.get("ocorrs", [])) or resultado.get("descResposta", "")
        break

    if recibo_excl and not obs_err:
        supabase.table("tab_esocial").update({
            "observacao_erro": "EXCLUIDO",
            "data_grava":      datetime.now().strftime("%Y%m%d"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": True, "msg": f"S-1000 excluído com sucesso. Recibo S-3000: {recibo_excl}"})

    if obs_err:
        return jsonify({"ok": False, "msg": f"Erro na exclusão: {obs_err}"})

    return jsonify({"ok": True, "msg": f"Exclusão enviada. Aguardando confirmação. Protocolo: {protocolo_envio}",
                    "protocolo": protocolo_envio})


