# =========================================================
# eSocial S-1010 — GERADOR DE XML (um evento por rubrica)
# =========================================================
def _gerar_xml_s1010_evento(rubrica, empresa, tpAmb, tp_op, ini_valid, fim_valid, nr_seq=1):
    """Gera o XML de um evtTabRubrica para uma única rubrica.
    tp_op: 'inclusao' ou 'alteracao'
    nr_seq: sequência do evento no lote (inteiro)
    """
    import re as _re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return _re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    seq_str   = str(nr_seq).zfill(5)
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}{seq_str}"

    cod_rubr  = str(rubrica.get('cod_rubr') or '').strip()
    dsc_rubr  = x((rubrica.get('dsc_rubr') or '')[:100])
    nat_rubr  = str(rubrica.get('es03_nat_rubr') or '').strip()
    tp_rubr   = str(rubrica.get('tp_rubr') or '1').strip()
    def _inc(v): s = str(v or '').strip(); return s.zfill(2) if s.isdigit() else '00'
    inc_cp    = _inc(rubrica.get('tpn_inc_cp'))
    inc_irrf  = _inc(rubrica.get('tpn_inc_irrf'))
    inc_fgts  = _inc(rubrica.get('tpn_inc_fgts'))
    inc_sind  = _inc(rubrica.get('tpn_inc_pis'))

    fim_valid_xml = f"\n          <fimValid>{x(fim_valid)}</fimValid>" if fim_valid else ''

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtTabRubrica/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtTabRubrica/v_S_01_03_00 evtTabRubrica_v_S_01_03_00.xsd">
  <evtTabRubrica Id="{evt_id}">
    <ideEvento>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <infoRubrica>
      <{tp_op}>
        <ideRubrica>
          <codRubr>{x(cod_rubr)}</codRubr>
          <ideTabRubr>{x(cnpj_raiz)}</ideTabRubr>
          <iniValid>{x(ini_valid)}</iniValid>{fim_valid_xml}
        </ideRubrica>
        <dadosRubrica>
          <dscRubr>{dsc_rubr}</dscRubr>
          <natRubr>{x(nat_rubr)}</natRubr>
          <tpRubr>{x(tp_rubr)}</tpRubr>
          <codIncCP>{inc_cp}</codIncCP>
          <codIncIRRF>{inc_irrf}</codIncIRRF>
          <codIncFGTS>{inc_fgts}</codIncFGTS>
        </dadosRubrica>
      </{tp_op}>
    </infoRubrica>
  </evtTabRubrica>
</eSocial>"""


def _gerar_xml_s1020_evento(lotacao, empresa, tpAmb, tp_op, ini_valid, fim_valid, nr_seq=1):
    """Gera o XML de um evtTabLotacao (S-1020) para uma lotação tributária.
    tp_op: 'inclusao' ou 'alteracao'
    """
    import re as _re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return _re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    seq_str   = str(nr_seq).zfill(5)
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}{seq_str}"

    cod_lot   = str(lotacao.get('codLotacao') or '01').strip()
    tp_lot    = str(lotacao.get('tpLotacao')  or '01').strip()
    fpas      = str(lotacao.get('fpas')       or '').strip()
    cod_tercs = str(lotacao.get('codTercs')   or '0000').strip()

    fim_valid_xml = f"\n          <fimValid>{x(fim_valid)}</fimValid>" if fim_valid else ''

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtTabLotacao/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtTabLotacao/v_S_01_03_00 evtTabLotacao_v_S_01_03_00.xsd">
  <evtTabLotacao Id="{evt_id}">
    <ideEvento>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <infoLotacao>
      <{tp_op}>
        <ideLotacao>
          <codLotacao>{x(cod_lot)}</codLotacao>
          <iniValid>{x(ini_valid)}</iniValid>{fim_valid_xml}
        </ideLotacao>
        <dadosLotacao>
          <tpLotacao>{x(tp_lot)}</tpLotacao>
          <tpInsc>1</tpInsc>
          <nrInsc>{x(cnpj_emp)}</nrInsc>
        </dadosLotacao>
        <fpas>
          <fpas>{x(fpas)}</fpas>
          <codTercs>{x(cod_tercs)}</codTercs>
        </fpas>
      </{tp_op}>
    </infoLotacao>
  </evtTabLotacao>
</eSocial>"""


def _montar_lote_multi(xmls_assinados, cnpj_emp, tpAmb, grupo="1",
                       tra_tpinsc=None, tra_nrinsc=None):
    """Monta lote eSocial com múltiplos eventos assinados.
    tra_tpinsc/tra_nrinsc: inscrição do TRANSMISSOR; None = próprio empregador (atual)."""
    from lxml import etree as _et

    cnpj_raiz = re.sub(r"\D", "", cnpj_emp)[:8]
    NS_LOTE = "http://www.esocial.gov.br/schema/lote/eventos/envio/v1_1_1"
    lote = _et.Element(f"{{{NS_LOTE}}}eSocial", nsmap={None: NS_LOTE})
    env  = _et.SubElement(lote, f"{{{NS_LOTE}}}envioLoteEventos", grupo=grupo)

    ide_emp = _et.SubElement(env, f"{{{NS_LOTE}}}ideEmpregador")
    _et.SubElement(ide_emp, f"{{{NS_LOTE}}}tpInsc").text = "1"
    _et.SubElement(ide_emp, f"{{{NS_LOTE}}}nrInsc").text = cnpj_raiz

    ide_tra = _et.SubElement(env, f"{{{NS_LOTE}}}ideTransmissor")
    _et.SubElement(ide_tra, f"{{{NS_LOTE}}}tpInsc").text = str(tra_tpinsc or "1")
    _et.SubElement(ide_tra, f"{{{NS_LOTE}}}nrInsc").text = (
        re.sub(r"\D", "", tra_nrinsc) if tra_nrinsc else re.sub(r"\D", "", cnpj_emp))

    eventos_el = _et.SubElement(env, f"{{{NS_LOTE}}}eventos")
    for xml_assinado in xmls_assinados:
        es = _et.fromstring(xml_assinado.encode("utf-8"))
        evt_id = ""
        for child in es:
            local = _et.QName(child.tag).localname
            if local.startswith("evt") and child.get("Id"):
                evt_id = child.get("Id", "")
                break
        ev_wrap = _et.SubElement(eventos_el, f"{{{NS_LOTE}}}evento")
        ev_wrap.set("Id", evt_id)
        ev_wrap.append(es)

    return _et.tostring(lote, encoding="unicode")


# =========================================================
# eSocial S-1010 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s1010")
def esocial_s1010():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    anomes_folha = str(session.get("anomes_atual") or "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1010"))
        if anomes_folha.isdigit() and len(anomes_folha) == 6:
            q = q.gte("data_cad", anomes_folha + "01").lte("data_cad", anomes_folha + "31")
        rows = (q.order("data_cad", desc=True)
                 .order("hora_cad", desc=True)
                 .execute().data or [])
    except Exception:
        rows = []

    # Lista completa de rubricas para o modal de seleção
    rubricas_lista = []
    try:
        rubricas_lista = (supabase.table("tab_rubrica")
                          .select("cod_rubr,dsc_rubr,tp_rubr")
                          .in_("id_cliente", [0, id_cliente])
                          .eq("situacao", "A")
                          .order("cod_rubr")
                          .execute().data or [])
    except Exception:
        pass

    import json as _json

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    for r in rows:
        r["_datacad_fmt"] = _d8(r.get("data_cad"))
        obs = (r.get("observacao_erro") or "").strip()
        r["_ini_valid"] = ""
        r["_fim_valid"] = ""
        r["_cod_rubr"]  = "—"
        r["_dsc_rubr"]  = ""
        _params_part = ""
        _status_part = ""
        if "|" in obs:
            parts = obs.split("|", 1)
            _params_part = parts[0] if parts[0].startswith("PARAMS:") else ""
            _status_part = parts[1] if len(parts) > 1 else ""
        elif obs.startswith("PARAMS:"):
            _params_part = obs
        else:
            _status_part = obs
        if _params_part:
            try:
                p = _json.loads(_params_part[7:])
                r["_ini_valid"] = p.get("ini", "")
                r["_fim_valid"] = p.get("fim", "")
                cod_rubr_p = p.get("cod_rubr")
                if cod_rubr_p is not None:
                    r["_cod_rubr"] = str(int(cod_rubr_p)).zfill(4)
                    r["_dsc_rubr"] = p.get("dsc_rubr", "")
            except Exception:
                pass
        if not r["_ini_valid"]:
            am = str(r.get("ano_mes") or "")
            if len(am) == 6:
                r["_ini_valid"] = f"{am[:4]}-{am[4:6]}"

        r["_tp_op_label"] = "Inclusão" if str(r.get("operacao") or "I") == "I" else "Alteração"
        recibo = (r.get("recibo") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and _status_part == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif _status_part.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = _status_part[len("AGUARDANDO:"):]
        elif _status_part:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    cnpj_fmt = _fmt_cnpj(cnpj_emp) if len(cnpj_emp) == 14 else cnpj_emp

    return render_template(
        "F10_eSocial_S1010.html",
        versao=ler_versao(),
        empresa_info=session.get("empresa_info", ""),
        cnpj_fmt=cnpj_fmt,
        rows=rows,
        total=len(rows),
        rubricas_lista=rubricas_lista,
    )


# =========================================================
# eSocial S-1010 — API: gravar registro pendente
# =========================================================
@app.route("/api/esocial_s1010_gravar", methods=["POST"])
def api_esocial_s1010_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import json as _json
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    data       = request.get_json(force=True) or {}

    tp_op     = data.get("tp_op", "inclusao")
    ini_valid = data.get("ini_valid", "").strip()
    fim_valid = data.get("fim_valid", "").strip()
    tpAmb     = str(data.get("tpAmb", "1"))
    verbas    = data.get("verbas", [])   # lista de {cod_rubr, dsc_rubr}

    if not ini_valid or len(ini_valid) != 7 or ini_valid[4] != '-':
        return jsonify({"ok": False, "msg": "Período de início inválido (use AAAA-MM)."})

    if not verbas:
        return jsonify({"ok": False, "msg": "Selecione ao menos uma rubrica."})

    ano_mes = ini_valid.replace("-", "")

    agora = datetime.now()
    ids_criados = []
    for v in verbas:
        try:
            cod_rubr = int(v.get("cod_rubr", 0))
            dsc_rubr = str(v.get("dsc_rubr", "")).strip()
        except Exception:
            return jsonify({"ok": False, "msg": "Dados de rubrica inválidos."})
        p_json = _json.dumps({
            "ini": ini_valid, "fim": fim_valid,
            "tpAmb": tpAmb,
            "cod_rubr": cod_rubr,
            "dsc_rubr": dsc_rubr,
        }, ensure_ascii=False)
        try:
            r = supabase.table("tab_esocial").insert({
                "id_cliente":      id_cliente,
                "id_empresa":      id_empresa,
                "data_cad":        agora.strftime("%Y%m%d"),
                "hora_cad":        agora.strftime("%H%M"),
                "layout":          "1010",
                "ano_mes":         int(ano_mes),
                "folha_tipo":      "I",
                "operacao":        "I" if tp_op == "inclusao" else "A",
                "observacao_erro": f"PARAMS:{p_json}",
            }).execute()
            if r.data:
                ids_criados.append(r.data[0].get("id_esocial"))
        except Exception as e:
            return jsonify({"ok": False, "msg": f"Erro ao gravar rubrica {cod_rubr}: {e}"})

    return jsonify({"ok": True, "qtd_rubricas": len(ids_criados)})


# =========================================================
# eSocial S-1010 — API: baixar XML (preview)
# =========================================================
@app.route("/api/esocial_s1010_xml")
def api_esocial_s1010_xml():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response
    import json as _json

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    id_reg     = request.args.get("id", "").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain")

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1010")
                .limit(1).execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    _params_raw = obs.split("|")[0] if "|" in obs else obs
    if _params_raw.startswith("PARAMS:"):
        try:
            params = _json.loads(_params_raw[7:])
        except Exception:
            pass

    ini_valid    = params.get("ini", "")
    fim_valid    = params.get("fim", "")
    tpAmb        = params.get("tpAmb", "1")
    cod_rubr_reg = params.get("cod_rubr")
    tp_op        = "inclusao" if str(es.get("operacao") or "I") == "I" else "alteracao"

    if not ini_valid:
        am = str(es.get("ano_mes") or "")
        if len(am) == 6:
            ini_valid = f"{am[:4]}-{am[4:6]}"

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    try:
        q = (supabase.table("tab_rubrica")
             .select("cod_rubr,dsc_rubr,tp_rubr,es03_nat_rubr,"
                     "tpn_inc_cp,tpn_inc_fgts,tpn_inc_irrf,tpn_inc_pis")
             .in_("id_cliente", [0, id_cliente])
             .eq("situacao", "A")
             .order("cod_rubr"))
        if cod_rubr_reg is not None:
            q = q.eq("cod_rubr", int(cod_rubr_reg))
        rubricas = q.execute().data or []
    except Exception:
        rubricas = []

    xmls = []
    for idx, rub in enumerate(rubricas, start=1):
        xmls.append(_gerar_xml_s1010_evento(rub, empresa, tpAmb, tp_op, ini_valid, fim_valid, idx))

    combined = "\n<!-- ======== PRÓXIMO EVENTO ======== -->\n".join(xmls)

    try:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
    except Exception:
        pass

    fname = f"S1010_{ini_valid.replace('-','')}_{tp_op[:3].upper()}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xml"
    return Response(
        combined,
        mimetype="application/xml; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# =========================================================
# eSocial S-1010 — API: assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1010_enviar", methods=["POST"])
def api_esocial_s1010_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time, json as _json

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("1010")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # ── 1. Registro na tab_esocial ────────────────────────
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1010")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-1010 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    _params_raw = ""  # parte PARAMS: preservada em todos os updates
    if obs.startswith("PARAMS:"):
        # pode ter "|STATUS:..." após os PARAMS — pega só o bloco PARAMS
        _params_raw = obs.split("|")[0]
        try:
            params = _json.loads(_params_raw[7:])
        except Exception:
            pass
    elif "|" in obs:
        # já foi enviado antes: PARAMS:{...}|STATUS:...
        for part in obs.split("|"):
            if part.startswith("PARAMS:"):
                _params_raw = part
                try:
                    params = _json.loads(_params_raw[7:])
                except Exception:
                    pass
                break

    def _obs_upd(msg):
        """Grava erro/status preservando o bloco PARAMS."""
        if _params_raw:
            return f"{_params_raw}|{msg[:200]}"
        return msg[:295]

    ini_valid    = params.get("ini", "")
    fim_valid    = params.get("fim", "")
    cod_rubr_reg = params.get("cod_rubr")
    if not tpAmb or tpAmb == "1":
        tpAmb = params.get("tpAmb", tpAmb)
    tp_op = "inclusao" if str(es.get("operacao") or "I") == "I" else "alteracao"

    # Reconstrói ini_valid a partir de ano_mes quando PARAMS foi perdido
    if not ini_valid:
        am = str(es.get("ano_mes") or "")
        if len(am) == 6:
            ini_valid = f"{am[:4]}-{am[4:6]}"
    if not ini_valid or cod_rubr_reg is None:
        return jsonify({"ok": False, "msg": "Parâmetros não encontrados. Recrie o registro."})

    # ── 2. Empresa (cert validado mais à frente, após gerar XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 3. Buscar rubrica do registro ─────────────────────
    try:
        rubricas = (supabase.table("tab_rubrica")
                    .select("cod_rubr,dsc_rubr,tp_rubr,es03_nat_rubr,"
                            "tpn_inc_cp,tpn_inc_fgts,tpn_inc_irrf,tpn_inc_pis")
                    .in_("id_cliente", [0, id_cliente])
                    .eq("situacao", "A")
                    .eq("cod_rubr", int(cod_rubr_reg))
                    .limit(1).execute().data or [])
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar rubrica: {e}"})

    if not rubricas:
        return jsonify({"ok": False, "msg": f"Rubrica {cod_rubr_reg} não encontrada ou inativa."})

    # ── 4. Gerar XML cru de cada rubrica e salvar ASAP ───
    # (salvar antes do cert/assinatura/envio garante cópia pra debug
    #  mesmo se algo falhar nas etapas seguintes)
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S1010_{ini_valid.replace('-','')}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    xmls_crus = []
    for idx, rub in enumerate(rubricas, start=1):
        try:
            xml_str = _gerar_xml_s1010_evento(rub, empresa, tpAmb, tp_op, ini_valid, fim_valid, idx)
        except Exception as e:
            msg = f"Erro ao gerar XML rubrica {rub.get('cod_rubr')}: {e}"
            _xml_erro_save(_pref, 1, msg, e)
            return jsonify({"ok": False, "msg": msg})
        xmls_crus.append(xml_str)

    # Wrappa todos os eventos num único XML válido (sem múltiplas
    # declarações <?xml?>) pra ficar legível no viewer.
    import re as _re_s1010
    _decl_re = _re_s1010.compile(r'^\s*<\?xml[^>]*\?>\s*')
    _xml_save(
        f"{_pref}_1_eventos_cru.xml",
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<remessa>\n'
        + '\n'.join(_decl_re.sub('', x).rstrip() for x in xmls_crus)
        + '\n</remessa>\n'
    )

    # ── 5. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        msg = "Certificado digital não configurado."
        _xml_erro_save(_pref, 2, msg)
        return jsonify({"ok": False, "msg": msg})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    xmls_assinados = []
    for idx, xml_str in enumerate(xmls_crus, start=1):
        try:
            xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
        except Exception as e:
            msg = f"Erro na assinatura rubrica {rubricas[idx-1].get('cod_rubr')}: {e}"
            _xml_erro_save(_pref, 2, msg, e)
            return jsonify({"ok": False, "msg": msg})
        xmls_assinados.append(xml_assinado)

    _xml_save(
        f"{_pref}_2_eventos_assinados.xml",
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<remessa>\n'
        + '\n'.join(_decl_re.sub('', x).rstrip() for x in xmls_assinados)
        + '\n</remessa>\n'
    )

    # ── 6. Montar lote com todos os eventos ──────────────
    try:
        lote_xml = _montar_lote_multi(xmls_assinados, cnpj_emp, tpAmb, grupo="1",
                                      tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"))
    except Exception as e:
        msg = f"Erro ao montar lote: {e}"
        _xml_erro_save(_pref, 3, msg, e)
        return jsonify({"ok": False, "msg": msg})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 7. Enviar ─────────────────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        _xml_erro_save(_pref, 4, f"Erro no envio: {detalhe}", e)
        supabase.table("tab_esocial").update({
            "observacao_erro": _obs_upd(f"Erro no envio: {detalhe[:200]}"),
            "data_grava": datetime.now().strftime("%Y%m%d"),
        }).eq("id_esocial", int(id_reg)).execute()
        return jsonify({"ok": False, "msg": f"Erro no envio: {detalhe}"})

    _xml_save(f"{_pref}_4_resposta.xml", resp_envio)

    # ── 8. Analisar resposta ──────────────────────────────
    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    agora = datetime.now()
    if not protocolo_envio:
        supabase.table("tab_esocial").update({
            "observacao_erro": _obs_upd(analise["erro"]),
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).execute()

    # ── 9. Consultar resultado (até 3 tentativas) ─────────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_5_consulta_{tentativa+1}.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        # cd_resp 201 sem nrRec individual → protocolo é o recibo
        if cd_resp == "201" and not recibo_final and not obs_erro:
            recibo_final = protocolo_envio
        elif not recibo_final and not obs_erro:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = _obs_upd(f"AGUARDANDO:{protocolo_envio}")
    elif obs_erro:
        upd["observacao_erro"] = _obs_upd(obs_erro)
    else:
        upd["observacao_erro"] = _params_raw  # sucesso: só preserva PARAMS
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).execute()

    rub_dsc = rubricas[0].get("dsc_rubr", "") if rubricas else ""
    if recibo_final and not obs_erro and not aguardando:
        return jsonify({"ok": True, "recibo": recibo_final,
                        "msg": f"S-1010 enviado — Verba {cod_rubr_reg} {rub_dsc}. Recibo: {recibo_final}"})
    if aguardando:
        return jsonify({"ok": True, "aguardando": True,
                        "msg": f"Aguardando processamento. Protocolo: {protocolo_envio}",
                        "protocolo": protocolo_envio})
    return jsonify({"ok": False, "msg": obs_erro or "Erro desconhecido na consulta."})


# =========================================================
# eSocial S-1010 — API: dados para o relatório de remessas
# =========================================================
@app.route("/api/esocial_s1010_relatorio")
def api_esocial_s1010_relatorio():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import json as _json
    id_empresa = _get_id_empresa()

    try:
        rows = (supabase.table("tab_esocial")
                .select("id_esocial, ano_mes, observacao_erro, recibo, data_grava, hora_grava, operacao, codigo2")
                .eq("id_empresa", id_empresa)
                .eq("layout", "1010")
                .order("data_grava", desc=True)
                .order("hora_grava", desc=True)
                .limit(200)
                .execute().data or [])
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    resultado = []
    for r in rows:
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()
        hgrava = (r.get("hora_grava") or "").strip()

        _params_part = ""
        _status_part = ""
        if "|" in obs:
            parts = obs.split("|", 1)
            _params_part = parts[0] if parts[0].startswith("PARAMS:") else ""
            _status_part = parts[1] if len(parts) > 1 else ""
        elif obs.startswith("PARAMS:"):
            _params_part = obs
        else:
            _status_part = obs

        ini_valid    = ""
        fim_valid    = ""
        cod_rubr_fmt = ""
        dsc_rubr_fmt = ""
        if _params_part:
            try:
                p = _json.loads(_params_part[7:])
                ini_valid    = p.get("ini", "")
                fim_valid    = p.get("fim", "")
                cod_rubr_p   = p.get("cod_rubr")
                if cod_rubr_p is not None:
                    cod_rubr_fmt = str(int(cod_rubr_p)).zfill(4)
                    dsc_rubr_fmt = p.get("dsc_rubr", "")
            except Exception:
                pass
        if not ini_valid:
            am = str(r.get("ano_mes") or "")
            if len(am) == 6:
                ini_valid = f"{am[:4]}-{am[4:6]}"

        if recibo and _status_part == "EXCLUIDO":
            sit, sit_label = "D", "Excluído"
        elif recibo:
            sit, sit_label = "E", "Enviado"
        elif _status_part.startswith("AGUARDANDO:"):
            sit, sit_label = "W", "Aguardando"
        elif _status_part:
            sit, sit_label = "X", "Com Erro"
        elif dgrava:
            sit, sit_label = "G", "Gerado"
        else:
            sit, sit_label = "P", "Pendente"

        erro_exib = _status_part if sit == "X" else ""

        dh = ""
        if dgrava and len(dgrava) == 8 and dgrava.isdigit():
            dh = f"{dgrava[6:]}/{dgrava[4:6]}/{dgrava[:4]}"
            if hgrava and len(hgrava) >= 4:
                dh += f" {hgrava[:2]}:{hgrava[2:4]}"

        tp_op = "Inclusão" if str(r.get("operacao") or "I") == "I" else "Alteração"

        resultado.append({
            "id_esocial":  r["id_esocial"],
            "per_ini":     ini_valid,
            "per_fim":     fim_valid,
            "cod_rubr":    cod_rubr_fmt,
            "dsc_rubr":    dsc_rubr_fmt,
            "tp_op":       tp_op,
            "sit":         sit,
            "sit_label":   sit_label,
            "recibo":      recibo,
            "erro":        erro_exib,
            "dh_grava":    dh,
        })

    return jsonify({"ok": True, "rows": resultado})


# =========================================================
# eSocial S-1010 — API: apagar registro local
# =========================================================
@app.route("/api/esocial_s1010_deletar", methods=["POST"])
def api_esocial_s1010_deletar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa = _get_id_empresa()
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial").select("recibo")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1010")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        if (r_es.data[0].get("recibo") or "").strip():
            return jsonify({"ok": False,
                            "msg": "Registro já enviado ao eSocial. Não é possível apagar localmente."})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao verificar: {e}"})

    try:
        supabase.table("tab_esocial")\
            .delete()\
            .eq("id_esocial", int(id_reg))\
            .eq("id_empresa", id_empresa)\
            .eq("layout", "1010")\
            .execute()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao apagar: {e}"})

    return jsonify({"ok": True, "msg": "Registro apagado."})

# =========================================================
# eSocial S-1020 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s1020")
def esocial_s1020():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    anomes_folha = str(session.get("anomes_atual") or "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1020"))
        if anomes_folha.isdigit() and len(anomes_folha) == 6:
            q = q.gte("data_cad", anomes_folha + "01").lte("data_cad", anomes_folha + "31")
        rows = (q.order("data_cad", desc=True)
                 .order("hora_cad", desc=True)
                 .execute().data or [])
    except Exception:
        rows = []

    # FPAS da empresa para pré-preencher o modal
    fpas_empresa = ""
    try:
        r_emp = (supabase.table("tab_empresa").select("gps_fpas")
                 .eq("id_empresa", id_empresa).limit(1).execute())
        if r_emp.data:
            fpas_empresa = str(r_emp.data[0].get("gps_fpas") or "")
    except Exception:
        pass

    import json as _json

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    for r in rows:
        r["_datacad_fmt"] = _d8(r.get("data_cad"))
        obs = (r.get("observacao_erro") or "").strip()
        r["_ini_valid"]    = ""
        r["_fim_valid"]    = ""
        r["_cod_lotacao"]  = ""
        r["_fpas"]         = ""
        _params_part = ""
        _status_part = ""
        if "|" in obs:
            parts = obs.split("|", 1)
            _params_part = parts[0] if parts[0].startswith("PARAMS:") else ""
            _status_part = parts[1] if len(parts) > 1 else ""
        elif obs.startswith("PARAMS:"):
            _params_part = obs
        else:
            _status_part = obs
        if _params_part:
            try:
                p = _json.loads(_params_part[7:])
                r["_ini_valid"]   = p.get("ini", "")
                r["_fim_valid"]   = p.get("fim", "")
                r["_cod_lotacao"] = p.get("codLotacao", "")
                r["_fpas"]        = p.get("fpas", "")
            except Exception:
                pass
        if not r["_ini_valid"]:
            am = str(r.get("ano_mes") or "")
            if len(am) == 6:
                r["_ini_valid"] = f"{am[:4]}-{am[4:6]}"

        r["_tp_op_label"] = "Inclusão" if str(r.get("operacao") or "I") == "I" else "Alteração"
        recibo = (r.get("recibo") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and _status_part == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif _status_part.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = _status_part[len("AGUARDANDO:"):]
        elif _status_part:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    cnpj_fmt = _fmt_cnpj(cnpj_emp) if len(cnpj_emp) == 14 else cnpj_emp

    return render_template(
        "F10_eSocial_S1020.html",
        versao=ler_versao(),
        empresa_info=session.get("empresa_info", ""),
        cnpj_fmt=cnpj_fmt,
        rows=rows,
        total=len(rows),
        fpas_empresa=fpas_empresa,
    )


# =========================================================
# eSocial S-1020 — API: gravar registro pendente
# =========================================================
@app.route("/api/esocial_s1020_gravar", methods=["POST"])
def api_esocial_s1020_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import json as _json
    id_empresa = _get_id_empresa()
    data       = request.get_json(force=True) or {}

    tp_op      = data.get("tp_op", "inclusao")
    ini_valid  = data.get("ini_valid", "").strip()
    fim_valid  = data.get("fim_valid", "").strip()
    tpAmb      = str(data.get("tpAmb", "1"))
    cod_lotacao = data.get("codLotacao", "01").strip()
    tp_lotacao  = data.get("tpLotacao", "01").strip()
    fpas        = data.get("fpas", "").strip()
    cod_tercs   = data.get("codTercs", "").strip()

    if not ini_valid or len(ini_valid) != 7 or ini_valid[4] != '-':
        return jsonify({"ok": False, "msg": "Período de início inválido (use AAAA-MM)."})
    if not cod_lotacao:
        return jsonify({"ok": False, "msg": "Código da lotação é obrigatório."})
    if not fpas:
        return jsonify({"ok": False, "msg": "Código FPAS é obrigatório."})
    if not cod_tercs:
        return jsonify({"ok": False, "msg": "Código de Terceiros é obrigatório."})

    ano_mes = ini_valid.replace("-", "")
    params_json = _json.dumps({
        "ini": ini_valid, "fim": fim_valid,
        "tpAmb": tpAmb,
        "codLotacao": cod_lotacao,
        "tpLotacao":  tp_lotacao,
        "fpas":       fpas,
        "codTercs":   cod_tercs,
    }, ensure_ascii=False)

    agora = datetime.now()
    try:
        r = supabase.table("tab_esocial").insert({
            "id_empresa":      id_empresa,
            "data_cad":        agora.strftime("%Y%m%d"),
            "hora_cad":        agora.strftime("%H%M"),
            "layout":          "1020",
            "ano_mes":         int(ano_mes),
            "folha_tipo":      "I",
            "operacao":        "I" if tp_op == "inclusao" else "A",
            "observacao_erro": f"PARAMS:{params_json}",
        }).execute()
        id_esocial = r.data[0]["id_esocial"] if r.data else None
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gravar: {e}"})

    if not id_esocial:
        return jsonify({"ok": False, "msg": "Falha ao obter ID do registro."})

    return jsonify({"ok": True, "id_esocial": id_esocial})


# =========================================================
# eSocial S-1020 — API: baixar XML (preview)
# =========================================================
@app.route("/api/esocial_s1020_xml")
def api_esocial_s1020_xml():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response
    import json as _json

    id_empresa = _get_id_empresa()
    id_reg     = request.args.get("id", "").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain")

    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1020")
                .limit(1).execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    if obs.startswith("PARAMS:"):
        try:
            params = _json.loads(obs[7:])
        except Exception:
            pass

    ini_valid  = params.get("ini", "")
    fim_valid  = params.get("fim", "")
    tpAmb      = params.get("tpAmb", "1")
    tp_op      = "inclusao" if str(es.get("operacao") or "I") == "I" else "alteracao"

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    xml_str = _gerar_xml_s1020_evento(params, empresa, tpAmb, tp_op, ini_valid, fim_valid, nr_seq=1)

    try:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
    except Exception:
        pass

    fname = f"S1020_{ini_valid.replace('-','')}_{tp_op[:3].upper()}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xml"
    return Response(
        xml_str,
        mimetype="application/xml; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# =========================================================
# eSocial S-1020 — API: assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1020_enviar", methods=["POST"])
def api_esocial_s1020_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time, json as _json

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("1020")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # ── 1. Registro ──────────────────────────────────────
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1020")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-1020 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    obs = (es.get("observacao_erro") or "").strip()
    params = {}
    _params_raw = ""
    if obs.startswith("PARAMS:"):
        _params_raw = obs.split("|")[0]
        try:
            params = _json.loads(_params_raw[7:])
        except Exception:
            pass
    elif "|" in obs:
        for part in obs.split("|"):
            if part.startswith("PARAMS:"):
                _params_raw = part
                try:
                    params = _json.loads(_params_raw[7:])
                except Exception:
                    pass
                break

    def _obs_upd(msg):
        if _params_raw:
            return f"{_params_raw}|{msg[:200]}"
        return msg[:295]

    ini_valid = params.get("ini", "")
    fim_valid = params.get("fim", "")
    if not tpAmb or tpAmb == "1":
        tpAmb = params.get("tpAmb", tpAmb)
    tp_op = "inclusao" if str(es.get("operacao") or "I") == "I" else "alteracao"

    if not ini_valid:
        am = str(es.get("ano_mes") or "")
        if len(am) == 6:
            ini_valid = f"{am[:4]}-{am[4:6]}"
    if not ini_valid:
        return jsonify({"ok": False, "msg": "Parâmetros não encontrados. Recrie o registro."})

    # ── 2. Empresa (cert validado depois do save do XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 3. Gerar XML cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S1020_{ini_valid.replace('-','')}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s1020_evento(params, empresa, tpAmb, tp_op, ini_valid, fim_valid, nr_seq=1)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 4. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        _xml_erro_save(_pref, 2, "Certificado digital não configurado.")
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    # ── 5. Montar lote ────────────────────────────────────
    try:
        lote_xml = _montar_lote_multi([xml_assinado], cnpj_emp, tpAmb, grupo="1",
                                      tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"))
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 6. Enviar ─────────────────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        supabase.table("tab_esocial").update({
            "observacao_erro": _obs_upd(f"Erro no envio: {detalhe[:200]}"),
            "data_grava": datetime.now().strftime("%Y%m%d"),
        }).eq("id_esocial", int(id_reg)).execute()
        _xml_erro_save(_pref, 4, f"Erro no envio: {detalhe}")
        return jsonify({"ok": False, "msg": f"Erro no envio: {detalhe}"})

    _xml_save(f"{_pref}_4_resposta.xml", resp_envio)

    # ── 7. Analisar resposta ──────────────────────────────
    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    agora = datetime.now()
    if not protocolo_envio:
        supabase.table("tab_esocial").update({
            "observacao_erro": _obs_upd(analise["erro"]),
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).execute()
        _xml_erro_save(_pref, 4, "eSocial recusou o envio.")
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).execute()

    # ── 8. Consultar resultado (até 3 tentativas) ─────────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_5_consulta_{tentativa+1}.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        # cd_resp 201 sem nrRec individual → protocolo é o recibo
        if cd_resp == "201" and not recibo_final and not obs_erro:
            recibo_final = protocolo_envio
        elif not recibo_final and not obs_erro:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = _obs_upd(f"AGUARDANDO:{protocolo_envio}")
    elif obs_erro:
        upd["observacao_erro"] = _obs_upd(obs_erro)
    else:
        upd["observacao_erro"] = _params_raw
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).execute()

    if recibo_final and not obs_erro and not aguardando:
        return jsonify({"ok": True, "recibo": recibo_final,
                        "msg": f"S-1020 enviado com sucesso. Recibo: {recibo_final}"})
    if aguardando:
        return jsonify({"ok": True, "msg": f"Aguardando processamento. Protocolo: {protocolo_envio}",
                        "protocolo": protocolo_envio})
    _xml_erro_save(_pref, 6, obs_erro)
    return jsonify({"ok": False, "msg": obs_erro or "Erro desconhecido na consulta."})


# =========================================================
# eSocial S-1020 — API: apagar registro local
# =========================================================
@app.route("/api/esocial_s1020_deletar", methods=["POST"])
def api_esocial_s1020_deletar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa = _get_id_empresa()
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial").select("recibo")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1020")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        if (r_es.data[0].get("recibo") or "").strip():
            return jsonify({"ok": False,
                            "msg": "Registro já enviado ao eSocial. Não é possível apagar localmente."})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao verificar: {e}"})

    try:
        supabase.table("tab_esocial")\
            .delete()\
            .eq("id_esocial", int(id_reg))\
            .eq("id_empresa", id_empresa)\
            .eq("layout", "1020")\
            .execute()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao apagar: {e}"})

    return jsonify({"ok": True, "msg": "Registro apagado."})

# =========================================================
# eSocial S-2200 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s2200")
def esocial_s2200():
    if not session.get("logado"):
        return redirect("/")

    id_empresa = _get_id_empresa()
    f_sit = request.args.get("sit", "")   # '' | 'P' | 'G' | 'E' | 'X'

    rows = []
    try:
        rows = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_empresa", id_empresa)
                .eq("layout", "2200")
                .order("data_cad", desc=True)
                .order("hora_cad", desc=True)
                .execute().data or [])
    except Exception:
        rows = []

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome, dtadm")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = {"nome": f.get("nome", ""),
                                         "dtadm": f.get("dtadm", "")}
        except Exception:
            pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    for r in rows:
        f = nomes.get(r.get("matricula"), {})
        r["_nome"]          = f.get("nome", "—")
        r["_dtadm"]         = _d8(f.get("dtadm"))
        r["_datacad_fmt"]   = _d8(r.get("data_cad"))
        r["_datagrava_fmt"] = _d8(r.get("data_grava"))

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    if f_sit:
        rows = [r for r in rows if r.get("_sit") == f_sit]

    contagens = {"P": 0, "G": 0, "E": 0, "W": 0, "X": 0, "D": 0}
    for r in rows:
        contagens[r["_sit"]] = contagens.get(r["_sit"], 0) + 1

    anomes_atual = str(session.get("anomes_atual") or "")

    return render_template(
        "F10_eSocial_S2200.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        f_sit=f_sit,
        contagens=contagens,
        total=len(rows),
        anomes_atual=anomes_atual,
        folha_aberta_esocial=_folha_aberta_no_esocial(),
    )


# =========================================================
# eSocial S-2200 — API: baixar XML
# =========================================================
@app.route("/api/esocial_s2200_xml")
def api_esocial_s2200_xml():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response

    id_empresa = _get_id_empresa()
    id_reg = request.args.get("id", "").strip()
    tpAmb  = request.args.get("tpAmb", "1").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain")

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "2200")
                .limit(1)
                .execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    matricula = es.get("matricula")
    if not matricula:
        return Response("Matrícula não associada ao registro.", status=400, mimetype="text/plain")

    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1)
                  .execute())
        if not r_func.data:
            return Response("Funcionário não encontrado.", status=404, mimetype="text/plain")
        func = r_func.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1)
                 .execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    xml_str = _gerar_xml_s2200(func, empresa, tpAmb)

    try:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
    except Exception:
        pass

    mat_fmt = str(matricula).zfill(6)
    fname = f"S2200_{mat_fmt}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xml"

    return Response(
        xml_str,
        mimetype="application/xml; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# =========================================================
# eSocial S-2200 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s2200_enviar", methods=["POST"])
def api_esocial_s2200_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("2200")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # ── 1. Registro na tab_esocial ────────────────────────
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "2200")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-2200 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    matricula = es.get("matricula")

    # ── 2. Dados do funcionário ───────────────────────────
    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    # ── 3. Dados da empresa (cert validado depois do save do XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 4. Gerar XML cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S2200_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s2200(func, empresa, tpAmb)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    # Salva XML gerado antes de qualquer processamento
    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 5. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado. Acesse eSocial → Certificado Digital."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura do evento: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura do evento: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    # ── 6. Montar lote ────────────────────────────────────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"))
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 7. Enviar ao eSocial ──────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    # Salva SOAP de envio (transmissão real) antes de enviar
    _xml_save(f"{_pref}_4_soap_envio.xml", soap_env)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        _xml_save(f"{_pref}_5_resposta.xml", detalhe)
        _xml_erro_save(_pref, 4, "Erro ao transmitir ao eSocial.")
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    # Salva resposta bruta para diagnóstico
    _xml_save(f"{_pref}_5_resposta.xml", resp_envio)

    analise        = _analisar_resposta_envio(resp_envio)
    nr_rec         = analise["nr_rec"]
    protocolo_envio = nr_rec   # protocoloEnvio (≠ nrRecibo)
    if not nr_rec:
        # Salva o erro no banco para referência futura
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False,
                        "msg": "eSocial recusou o envio.",
                        "detalhe": analise["erro"]})

    # Grava data_grava (recibo só após consulta — protocoloEnvio não é recibo)
    agora = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # ── 8. Aguardar e consultar resultado (até 3×) ───────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(nr_rec)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta ao eSocial: {e}"
            break

        _xml_save(f"{_pref}_6_resultado_consulta.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta da consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue                        # lote ainda em processamento

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    # Detecta estado "ainda processando" após esgotar tentativas
    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    # ── 9. Atualiza tab_esocial com resultado final ───────
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-2200 enviado: mat={matricula} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando

    # Formata CPF para exibição no relatório
    _cpf_raw = so_numeros(str(func.get("cpf") or ""))
    _cpf_fmt = (f"{_cpf_raw[:3]}.{_cpf_raw[3:6]}.{_cpf_raw[6:9]}-{_cpf_raw[9:]}"
                if len(_cpf_raw) == 11 else _cpf_raw)
    _dtadm_raw = str(func.get("dtadm") or "")
    _dtadm_fmt = (f"{_dtadm_raw[6:]}/{_dtadm_raw[4:6]}/{_dtadm_raw[:4]}"
                  if len(_dtadm_raw) == 8 and _dtadm_raw.isdigit() else _dtadm_raw)

    _msg_ok = f"Enviado com sucesso. Recibo: {recibo_final}"
    _msg_ag = "eSocial ainda está processando. Use 'Re-consultar' em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg":        (_msg_ag if aguardando else obs_erro or _msg_ok),
        # dados para o relatório
        "protocolo": protocolo_envio,
        "dh_proc":   dh_proc,
        "func_nome": func.get("nome", ""),
        "func_cpf":  _cpf_fmt,
        "func_mat":  str(matricula).zfill(6),
        "func_dtadm": _dtadm_fmt,
        "emp_nome":  empresa.get("razaosocial") or empresa.get("nome_fantasia", ""),
        "emp_cnpj":  _fmt_cnpj(so_numeros(empresa.get("cnpj", ""))),
    })


# =========================================================
# eSocial S-2200 — API: dados para o relatório de remessas
# =========================================================
@app.route("/api/esocial_s2200_relatorio")
def api_esocial_s2200_relatorio():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa = _get_id_empresa()

    try:
        rows = (supabase.table("tab_esocial")
                .select("id_esocial, matricula, recibo, observacao_erro, data_grava, hora_grava")
                .eq("id_empresa", id_empresa)
                .eq("layout", "2200")
                .order("data_grava", desc=True)
                .order("hora_grava", desc=True)
                .limit(200)
                .execute().data or [])
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    # Busca nomes dos funcionários
    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    resultado = []
    for r in rows:
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()
        hgrava = (r.get("hora_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            sit, sit_label = "D", "Excluído"
        elif recibo:
            sit, sit_label = "E", "Enviado"
        elif obs.startswith("AGUARDANDO:"):
            sit, sit_label = "W", "Aguardando"
        elif obs:
            sit, sit_label = "X", "Com Erro"
        elif dgrava:
            sit, sit_label = "G", "Gerado"
        else:
            sit, sit_label = "P", "Pendente"

        # Formata data/hora de gravação
        dh = ""
        if dgrava and len(dgrava) == 8 and dgrava.isdigit():
            dh = f"{dgrava[6:]}/{dgrava[4:6]}/{dgrava[:4]}"
            if hgrava and len(hgrava) >= 4:
                dh += f" {hgrava[:2]}:{hgrava[2:4]}"

        resultado.append({
            "id_esocial": r["id_esocial"],
            "matricula":  str(r.get("matricula") or "").zfill(6),
            "nome":       nomes.get(r.get("matricula"), "—"),
            "sit":        sit,
            "sit_label":  sit_label,
            "recibo":     recibo,
            "erro":       obs if sit == "X" else "",
            "dh_grava":   dh,
        })

    return jsonify({"ok": True, "rows": resultado})


# =========================================================
# eSocial S-2200 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s2200_reconsutar", methods=["POST"])
def api_esocial_s2200_reconsutar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # Lê o protocolo salvo em observacao_erro
    try:
        r_es = (supabase.table("tab_esocial")
                .select("matricula, observacao_erro")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está no estado Aguardando."})

    protocolo_envio = obs[len("AGUARDANDO:"):]
    matricula       = es.get("matricula")

    # Carrega empresa + certificado
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    tpAmb = str(data.get("tpAmb", "1"))
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    # Prefixo para salvar XML de re-consulta
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S2200_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    # Loop de consulta (até 3×)
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""
    aguardando   = False

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_reconsulta_{tentativa+1}.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"[{cd_resp}] {resultado.get('descResposta','')}"
        break

    aguardando = not recibo_final and not obs_erro and cd_resp in ("101", "202")

    # Atualiza tab_esocial
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = None   # limpa o AGUARDANDO ao receber recibo
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # Dados do funcionário para o relatório
    func = {}
    try:
        r_func = (supabase.table("tab_cad").select("nome, cpf, matricula, dtadm")
                  .eq("id_empresa", id_empresa).eq("matricula", matricula)
                  .limit(1).execute())
        if r_func.data:
            func = r_func.data[0]
    except Exception:
        pass

    ok = bool(recibo_final) and not obs_erro and not aguardando
    _msg_ag = "eSocial ainda está processando. Tente novamente em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg":        (_msg_ag if aguardando else obs_erro or f"Recibo: {recibo_final}"),
        "protocolo":  protocolo_envio,
        "dh_proc":    dh_proc,
        "func_nome":  func.get("nome", ""),
        "func_mat":   str(matricula).zfill(6),
        "emp_nome":   empresa.get("razaosocial") or empresa.get("nome_fantasia", ""),
        "emp_cnpj":   _fmt_cnpj(so_numeros(empresa.get("cnpj", ""))),
    })


# =========================================================
# eSocial S-2300 (evtTSVInicio) — API: baixar XML
# =========================================================
@app.route("/api/esocial_s2300_xml")
def api_esocial_s2300_xml():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response

    id_empresa = _get_id_empresa()
    id_reg = request.args.get("id", "").strip()
    tpAmb  = request.args.get("tpAmb", "1").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain")

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "2300")
                .limit(1)
                .execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    matricula = es.get("matricula")
    if not matricula:
        return Response("Matrícula não associada ao registro.", status=400, mimetype="text/plain")

    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1)
                  .execute())
        if not r_func.data:
            return Response("Funcionário não encontrado.", status=404, mimetype="text/plain")
        func = r_func.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain")

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1)
                 .execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    xml_str = _gerar_xml_s2300(func, empresa, tpAmb)

    try:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
    except Exception:
        pass

    mat_fmt = str(matricula).zfill(6)
    fname = f"S2300_{mat_fmt}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xml"

    return Response(
        xml_str,
        mimetype="application/xml; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# =========================================================
# eSocial S-2300 (evtTSVInicio) — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s2300_enviar", methods=["POST"])
def api_esocial_s2300_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("2300")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # ── 1. Registro na tab_esocial ────────────────────────
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "2300")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-2300 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    matricula = es.get("matricula")

    # ── 2. Dados do funcionário ───────────────────────────
    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    # ── 3. Dados da empresa ───────────────────────────────
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 4. Gerar XML cru e salvar ASAP ────────────────────
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S2300_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s2300(func, empresa, tpAmb)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 5. Validar certificado e assinar ──────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado. Acesse eSocial → Certificado Digital."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura do evento: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura do evento: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    # ── 6. Montar lote ────────────────────────────────────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"))
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 7. Enviar ao eSocial ──────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)
    _xml_save(f"{_pref}_4_soap_envio.xml", soap_env)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        _xml_save(f"{_pref}_5_resposta.xml", detalhe)
        _xml_erro_save(_pref, 4, "Erro ao transmitir ao eSocial.")
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    _xml_save(f"{_pref}_5_resposta.xml", resp_envio)

    analise         = _analisar_resposta_envio(resp_envio)
    nr_rec          = analise["nr_rec"]
    protocolo_envio = nr_rec
    if not nr_rec:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False,
                        "msg": "eSocial recusou o envio.",
                        "detalhe": analise["erro"]})

    agora = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # ── 8. Aguardar e consultar resultado (até 3×) ───────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(nr_rec)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta ao eSocial: {e}"
            break

        _xml_save(f"{_pref}_6_resultado_consulta.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta da consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    # ── 9. Atualiza tab_esocial com resultado final ───────
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-2300 enviado: mat={matricula} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando

    _cpf_raw = so_numeros(str(func.get("cpf") or ""))
    _cpf_fmt = (f"{_cpf_raw[:3]}.{_cpf_raw[3:6]}.{_cpf_raw[6:9]}-{_cpf_raw[9:]}"
                if len(_cpf_raw) == 11 else _cpf_raw)
    _dtadm_raw = str(func.get("dtadm") or "")
    _dtadm_fmt = (f"{_dtadm_raw[6:]}/{_dtadm_raw[4:6]}/{_dtadm_raw[:4]}"
                  if len(_dtadm_raw) == 8 and _dtadm_raw.isdigit() else _dtadm_raw)

    _msg_ok = f"Enviado com sucesso. Recibo: {recibo_final}"
    _msg_ag = "eSocial ainda está processando. Use 'Re-consultar' em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg":        (_msg_ag if aguardando else obs_erro or _msg_ok),
        "protocolo": protocolo_envio,
        "dh_proc":   dh_proc,
        "func_nome": func.get("nome", ""),
        "func_cpf":  _cpf_fmt,
        "func_mat":  str(matricula).zfill(6),
        "func_dtadm": _dtadm_fmt,
        "emp_nome":  empresa.get("razaosocial") or empresa.get("nome_fantasia", ""),
        "emp_cnpj":  _fmt_cnpj(so_numeros(empresa.get("cnpj", ""))),
    })


