# eSocial S-2300 (evtTSVInicio) — API: re-consultar protocolo pendente
# =========================================================
@app.route("/api/esocial_s2300_reconsultar", methods=["POST"])
def api_esocial_s2300_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("matricula, observacao_erro")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está no estado Aguardando."})

    protocolo_envio = obs[len("AGUARDANDO:"):]
    matricula       = es.get("matricula")

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    tpAmb = str(data.get("tpAmb", "1"))
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S2300_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_reconsulta_{tentativa+1}.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"[{cd_resp}] {resultado.get('descResposta','')}"
        break

    aguardando = not recibo_final and not obs_erro and cd_resp in ("101", "202")

    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = None
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    ok = bool(recibo_final) and not obs_erro and not aguardando
    _msg_ag = "eSocial ainda está processando. Tente novamente em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg":        (_msg_ag if aguardando else obs_erro or f"Recibo: {recibo_final}"),
        "protocolo":  protocolo_envio,
        "dh_proc":    dh_proc,
    })


# =========================================================
# eSocial — API: VER o XML do evento (1_evento) inline no navegador
# Regenera o XML na hora a partir do cadastro (funciona antes de enviar).
# Suporta eventos por trabalhador: S-2200 (admissão) e S-2300 (TSVE).
# =========================================================
@app.route("/api/esocial_xml_ver")
def api_esocial_xml_ver():
    if not session.get("logado"):
        return redirect("/")

    from flask import Response

    id_empresa = _get_id_empresa()
    id_reg = request.args.get("id", "").strip()
    tpAmb  = request.args.get("tpAmb", "1").strip()

    if not id_reg or not id_reg.isdigit():
        return Response("ID inválido.", status=400, mimetype="text/plain; charset=utf-8")

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return Response("Registro não encontrado.", status=404, mimetype="text/plain; charset=utf-8")
        es = r_es.data[0]
    except Exception as e:
        return Response(str(e), status=500, mimetype="text/plain; charset=utf-8")

    layout    = str(es.get("layout") or "")
    matricula = es.get("matricula")

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {"cnpj": cnpj_emp}
    except Exception:
        empresa = {"cnpj": cnpj_emp}

    func = {}
    if matricula:
        try:
            r_func = (supabase.table("tab_cad").select("*")
                      .eq("id_empresa", id_empresa).eq("matricula", matricula)
                      .limit(1).execute())
            func = r_func.data[0] if r_func.data else {}
        except Exception:
            func = {}

    try:
        if layout == "2300":
            xml_str = _gerar_xml_s2300(func, empresa, tpAmb)
        elif layout == "2200":
            xml_str = _gerar_xml_s2200(func, empresa, tpAmb)
        elif layout == "2399":
            # verbas rescisórias (opcionais) para o detVerbas
            mov_items = []
            try:
                q_mov = (supabase.table("tab_mov").select("cod_verba, valor")
                         .eq("id_empresa", id_empresa).eq("matricula", int(matricula))
                         .eq("folha_tipo", "R").eq("situacao", "A"))
                if es.get("ano_mes"):
                    q_mov = q_mov.eq("folha", int(es.get("ano_mes")))
                mov_items = q_mov.execute().data or []
            except Exception:
                mov_items = []
            xml_str = _gerar_xml_s2399(func, mov_items, empresa, tpAmb)
        else:
            return Response(
                f"Visualização de XML ainda não disponível para o layout S-{layout}.",
                status=400, mimetype="text/plain; charset=utf-8")
    except Exception as e:
        return Response(f"Erro ao gerar XML: {e}", status=500, mimetype="text/plain; charset=utf-8")

    # inline (sem Content-Disposition) — o navegador renderiza a árvore XML
    return Response(xml_str, mimetype="application/xml; charset=utf-8")


# =========================================================
# eSocial S-2205 — GERADOR DE XML
# =========================================================
def _gerar_xml_s2205(func, empresa, dt_alteracao, tpAmb="1"):
    """Gera string XML do S-2205 (Alteração de Dados Cadastrais) - schema evtAltCadastral/v_S_01_03_00."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    def fmt_d8(v):
        s = dg(str(v or ''))
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}" if len(s) >= 8 else ""

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    mat_es    = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf        = dg(str(func.get('cpf', '')))
    nm_trab    = x(func.get('nome', ''))
    sexo       = x(func.get('sexo', 'M'))
    raca_cor   = x(func.get('racacor', '6'))
    est_civ    = str(func.get('estciv') or '').strip()
    grau_instr = str(func.get('grauinstr') or '01').strip().zfill(2)
    nm_soc     = str(func.get('nmsoc') or '').strip()

    dt_nascto   = fmt_d8(func.get('dtnascto', ''))
    pais_nascto = str(func.get('paisnascto') or '105').strip()
    pais_nac    = str(func.get('paisnacionalidade') or func.get('paisnac') or '105').strip()

    dsc_lograd  = str(func.get('ender_dsclograd') or '').strip()
    nr_lograd   = str(func.get('ender_nrlograd') or 'S/N').strip()
    complemento = str(func.get('ender_complemento') or '').strip()
    bairro      = str(func.get('ender_bairro') or '').strip()
    cep         = dg(str(func.get('ender_cep') or ''))
    cod_munic   = dg(str(func.get('ender_codmunic') or ''))
    uf          = str(func.get('ender_uf') or '').strip().upper()
    tp_lograd   = str(func.get('ender_tplograd') or 'R').strip()

    fone_princ  = dg(str(func.get('fone_princ') or ''))
    email_princ = str(func.get('email_princ') or '').strip()

    est_civ_xml = f"<estCiv>{x(est_civ)}</estCiv>" if est_civ else ""
    nm_soc_xml  = f"<nmSoc>{x(nm_soc)}</nmSoc>" if nm_soc else ""
    compl_xml   = f"<complemento>{x(complemento)}</complemento>" if complemento else ""
    bairro_xml  = f"<bairro>{x(bairro)}</bairro>" if bairro else ""

    if dsc_lograd and cep and cod_munic and uf:
        ender_xml = (
            f"      <endereco>\n"
            f"        <brasil>\n"
            f"          <tpLograd>{x(tp_lograd)}</tpLograd>\n"
            f"          <dsLograd>{x(dsc_lograd)}</dsLograd>\n"
            f"          <nrLograd>{x(nr_lograd)}</nrLograd>\n"
            f"          {compl_xml}\n" if complemento else ""
            f"          {bairro_xml}\n" if bairro else ""
            f"          <cep>{cep[:8]}</cep>\n"
            f"          <codMunic>{cod_munic}</codMunic>\n"
            f"          <uf>{x(uf)}</uf>\n"
            f"        </brasil>\n"
            f"      </endereco>"
        )
        # rebuild cleanly
        _parts = [
            "      <endereco>",
            "        <brasil>",
            f"          <tpLograd>{x(tp_lograd)}</tpLograd>",
            f"          <dsLograd>{x(dsc_lograd)}</dsLograd>",
            f"          <nrLograd>{x(nr_lograd)}</nrLograd>",
        ]
        if complemento:
            _parts.append(f"          <complemento>{x(complemento)}</complemento>")
        if bairro:
            _parts.append(f"          <bairro>{x(bairro)}</bairro>")
        _parts += [
            f"          <cep>{cep[:8]}</cep>",
            f"          <codMunic>{cod_munic}</codMunic>",
            f"          <uf>{x(uf)}</uf>",
            "        </brasil>",
            "      </endereco>",
        ]
        ender_xml = "\n".join(_parts)
    else:
        ender_xml = ""

    fone_xml  = f"<fonePrinc>{fone_princ}</fonePrinc>" if fone_princ else ""
    email_xml = f"<emailPrinc>{x(email_princ)}</emailPrinc>" if email_princ else ""
    contato_xml = f"      <contato>{fone_xml}{email_xml}</contato>" if (fone_xml or email_xml) else ""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtAltCadastral/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtAltCadastral/v_S_01_03_00 evtAltCadastral_v_S_01_03_00.xsd">
  <evtAltCadastral Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideVinculo>
      <cpfTrab>{cpf}</cpfTrab>
      <matricula>{mat_es}</matricula>
    </ideVinculo>
    <altCadastral>
      <dtAlteracao>{x(dt_alteracao)}</dtAlteracao>
      <dadosTrabalhador>
        <nmTrab>{nm_trab}</nmTrab>
        <sexo>{sexo}</sexo>
        <racaCor>{raca_cor}</racaCor>
        {est_civ_xml}
        <grauInstr>{grau_instr}</grauInstr>
        {nm_soc_xml}
        <dadosNascimento>
          <dtNascto>{dt_nascto}</dtNascto>
          <paisNascto>{pais_nascto}</paisNascto>
          <paisNacionalidade>{pais_nac}</paisNacionalidade>
        </dadosNascimento>
{ender_xml}
{contato_xml}
      </dadosTrabalhador>
    </altCadastral>
  </evtAltCadastral>
</eSocial>"""


# =========================================================
# eSocial S-2205 — TELA
# =========================================================
@app.route("/esocial_s2205")
def esocial_s2205():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    f_sit        = request.args.get("sit", "").strip().upper()

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "2205")
             .eq("ano_mes", int(anomes_atual))
             .order("data_cad", desc=True)
             .order("hora_cad", desc=True))
        rows = q.execute().data or []
    except Exception:
        pass

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    _SIT_MAP = {
        "E": ("Enviado",    "sit-enviado"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }
    contagens = {k: 0 for k in _SIT_MAP}
    for r in rows:
        r["_nome"]        = nomes.get(r.get("matricula"), "—")
        r["_datacad_fmt"] = _d8(r.get("data_cad"))
        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio_fmt"] = ""

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo:                          s = "E"
        elif obs.startswith("AGUARDANDO:"): s = "W"
        elif obs:                           s = "X"
        elif dgrava:                        s = "G"
        else:                               s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT_MAP[s][0]
        r["_sit_class"] = _SIT_MAP[s][1]
        contagens[s] = contagens.get(s, 0) + 1

    if f_sit:
        rows = [r for r in rows if r["_sit"] == f_sit]

    return render_template(
        "F10_eSocial_S2205.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows, total=len(rows),
        anomes_atual=anomes_atual,
        f_sit=f_sit, contagens=contagens,
        folha_aberta_esocial=_folha_aberta_no_esocial(),
    )


# =========================================================
# eSocial S-2205 — API: buscar dados do funcionário
# =========================================================
@app.route("/api/esocial_s2205_buscar_func")
def api_esocial_s2205_buscar_func():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    matricula  = request.args.get("matricula", "").strip()
    if not matricula:
        return jsonify({"ok": False, "msg": "Matrícula não informada."})
    try:
        r = (supabase.table("tab_cad")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("matricula", int(matricula))
             .limit(1).execute())
        if not r.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        return jsonify({"ok": True, "func": r.data[0]})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


# =========================================================
# eSocial S-2205 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s2205_enviar", methods=["POST"])
def api_esocial_s2205_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}

    id_reg = data.get("id_esocial")
    tpAmb  = str(data.get("tpAmb", "1")).strip()

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    ok_val, msg_val = _validar_folha_para_envio_esocial("2205")
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    # Lê o registro existente em tab_esocial
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", id_reg).eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        reg_es   = r_es.data[0]
        matricula = reg_es.get("matricula")
        dc = str(reg_es.get("data_cad") or "")
        dt_alteracao = f"{dc[:4]}-{dc[4:6]}-{dc[6:8]}" if len(dc) == 8 else datetime.now().strftime("%Y-%m-%d")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    # Lê dados atuais do funcionário
    try:
        r_func = (supabase.table("tab_cad").select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", int(matricula)).limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    agora = datetime.now()

    # ── Gerar XML cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S2205_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s2205(func, empresa, dt_alteracao, tpAmb)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── Validar certificado e assinar ──────────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        _xml_erro_save(_pref, 2, "Certificado digital não configurado.")
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"), grupo="2")
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    _xml_save(f"{_pref}_4_soap_envio.xml", soap_env)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        _xml_save(f"{_pref}_5_resposta.xml", detalhe)
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": detalhe[:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, "Erro ao transmitir ao eSocial.")
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    _xml_save(f"{_pref}_5_resposta.xml", resp_envio)

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    agora = datetime.now()
    if not protocolo_envio:
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, "eSocial recusou o envio.")
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break
        _xml_save(f"{_pref}_6_resultado_consulta.xml", resp_cons)
        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break
        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-2205 enviado: mat={matricula} nrRec={recibo_final} cd={cd_resp}",
               matricula=int(matricula))

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "id_esocial": id_reg,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-2205 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s2205_reconsultar", methods=["POST"])
def api_esocial_s2205_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("observacao_erro, matricula")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        obs = (r_es.data[0].get("observacao_erro") or "")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está aguardando."})

    protocolo_envio = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break
        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break
        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"[{cd_resp}] {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    ok = bool(recibo_final) and not obs_erro
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-2206 — GERADOR DE XML
# =========================================================
def _gerar_xml_s2206(func, empresa, dt_alteracao, tpAmb="1"):
    """Gera string XML do S-2206 (Alteração de Dados Contratuais)."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def fmt_d8(v):
        s = dg(str(v or ''))
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}" if len(s) >= 8 else ""

    def fmt_sal(centavos):
        try:    return f"{int(centavos) / 100:.2f}"
        except: return "0.00"

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf    = dg(func.get('cpf', ''))
    mat_es = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)

    cbo     = str(func.get('cbofuncao') or '')
    nmcargo = str(func.get('nmcargo') or '').strip()
    if not nmcargo and cbo:
        try:
            _rc = supabase.table("tab_aux_funcao_total").select("cbo_nome")\
                          .eq("cbo_codigo", cbo).limit(1).execute()
            if _rc.data:
                nmcargo = str(_rc.data[0].get('cbo_nome') or '').strip()
        except Exception:
            pass
    if not nmcargo:
        nmcargo = f"CBO {cbo}" if cbo else "Empregado"

    vrsalfx    = fmt_sal(func.get('vrsalfx') or 0)
    _und_map   = {'H':'1','D':'2','S':'3','Q':'4','M':'5','T':'6','N':'7'}
    _und_raw   = str(func.get('undsalfixo', '5') or '5')
    undsalfixo = _und_map.get(_und_raw.upper(), _und_raw)
    codcateg   = str(func.get('codcateg') or '101')
    tpregjor   = str(func.get('tpregjor') or '2')
    natativ    = str(func.get('natatividade') or '1')
    tpjornada  = str(func.get('tpjornada') or '2')
    tmpparc    = str(func.get('tmpparc') or '0')
    hornoturno = func.get('hornoturno', 'N') or 'N'
    try:
        qtdhrssem = str(int(float(func.get('qtdhrssem') or 44)))
    except Exception:
        qtdhrssem = "44"
    lt_tpinsc = str(func.get('lt_tpinsc') or '1')
    lt_nrinsc = dg(func.get('lt_nrinsc') or '') or cnpj_emp

    tpcontr     = str(func.get('tpcontr') or '1')
    _dtterm_raw = str(func.get('datarescisao') or '').strip()
    _dtterm_fmt = fmt_d8(_dtterm_raw) if _dtterm_raw else ''
    if tpcontr == '2' and _dtterm_fmt:
        _clauassec  = x(func.get('clausassec', 'N') or 'N')
        _objdet     = str(func.get('objdet') or '').strip()
        _objdet_xml = f"\n          <objDet>{x(_objdet)}</objDet>" if _objdet else ''
        duracao_xml = (f"\n        <duracao>"
                       f"\n          <tpContr>2</tpContr>"
                       f"\n          <dtTerm>{_dtterm_fmt}</dtTerm>"
                       f"\n          <clauAssec>{_clauassec}</clauAssec>{_objdet_xml}"
                       f"\n        </duracao>")
    else:
        duracao_xml = "\n        <duracao>\n          <tpContr>1</tpContr>\n        </duracao>"

    # dt_alteracao aceita yyyy-mm-dd ou yyyymmdd
    if len(dt_alteracao.replace('-','')) == 8:
        s = dt_alteracao.replace('-','')
        dt_alt_fmt = f"{s[:4]}-{s[4:6]}-{s[6:]}"
    else:
        dt_alt_fmt = dt_alteracao

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtAltContratual/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtAltContratual/v_S_01_03_00 evtAltContratual_v_S_01_03_00.xsd">
  <evtAltContratual Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideVinculo>
      <cpfTrab>{x(cpf)}</cpfTrab>
      <matricula>{x(mat_es)}</matricula>
    </ideVinculo>
    <altContratual>
      <dtAlteracao>{x(dt_alt_fmt)}</dtAlteracao>
      <vinculo>
        <tpRegPrev>1</tpRegPrev>
        <infoContrato>
          <nmCargo>{x(nmcargo)}</nmCargo>
          <CBOCargo>{x(cbo)}</CBOCargo>
          <codCateg>{x(codcateg)}</codCateg>
          <remuneracao>
            <vrSalFx>{x(vrsalfx)}</vrSalFx>
            <undSalFixo>{x(undsalfixo)}</undSalFixo>
          </remuneracao>{duracao_xml}
          <localTrabalho>
            <localTrabGeral>
              <tpInsc>{x(lt_tpinsc)}</tpInsc>
              <nrInsc>{x(lt_nrinsc)}</nrInsc>
            </localTrabGeral>
          </localTrabalho>
          <horContratual>
            <qtdHrsSem>{qtdhrssem}</qtdHrsSem>
            <tpJornada>{x(tpjornada)}</tpJornada>
            <tmpParc>{x(tmpparc)}</tmpParc>
            <horNoturno>{x(hornoturno)}</horNoturno>
            <dscJorn>Jornada de trabalho conforme contrato</dscJorn>
          </horContratual>
        </infoContrato>
      </vinculo>
    </altContratual>
  </evtAltContratual>
</eSocial>"""


# =========================================================
# eSocial S-2299 — GERADOR DE XML (Desligamento)
# =========================================================
def _gerar_xml_s2299(func, mov_items, empresa, tpAmb="1",
                     mtv_deslig=None, dt_deslig=None,
                     ind_pagto_api="N", dt_proj_fim_api=None,
                     pens_alim="0", perc_aliment=None, vr_alim=None):
    """Gera string XML do S-2299 (Desligamento).

    Baseado em S-2299 REAL de produção (Folha10 Desktop): verbasResc usa
    <detVerbas> (não <itensRemun>), direto sob <ideEstabLot>; ordem do
    infoDeslig = mtvDeslig, dtDeslig, indPagtoAPI, [dtProjFimAPI], pensAlim,
    [percAliment/vrAlim], verbasResc. Namespace v_S_01_03_00 (padrão do web).

    Parâmetros:
      func       linha de tab_cad: cpf, matricula, codcateg, centrocusto,
                 datarescisao, motrescisao, nis/pis.
      mov_items  verbas da rescisão (tab_mov folha_tipo='R'): cod_verba, valor.
      mtv_deslig motivo (Tabela 19); default = func['motrescisao'].
      dt_deslig  data do desligamento; default = func['datarescisao'].
      ind_pagto_api  'S'/'N' — aviso prévio indenizado pago nesta rescisão.
      dt_proj_fim_api  data projetada do fim do contrato (só se API='S').
      pens_alim  '0' não há | '1' % | '2' valor | '3' ambos.

    codRubr/ideTabRubr: convenção comprovada como ACEITA no web (XMLs do S-1010
    com recibo) = codRubr CRU + ideTabRubr = raiz do CNPJ (ver bloco detVerbas).
    Mesma convenção já aplicada no S-1200 (_gerar_xml_s1200).
    """
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):  return re.sub(r'\D', '', str(v or ''))
    def x(v):   return _esc(str(v or ''))
    def fmt_brl(c):
        try:    return f"{int(c) / 100:.2f}"
        except Exception: return "0.00"
    def fmt_d8(v):
        s = dg(v)
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}" if len(s) >= 8 else ""

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf    = dg(func.get('cpf', '')).zfill(11)
    mat_es = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)

    # motivo (Tabela 19) e data do desligamento (obrigatórios)
    mtv = str(mtv_deslig if mtv_deslig is not None
              else (func.get('motrescisao') or '')).strip().zfill(2)
    if mtv in ('', '00'):
        raise ValueError(
            f"Funcionário {func.get('matricula')} sem motivo de desligamento "
            "(motrescisao) — obrigatório no S-2299.")
    dt_des = fmt_d8(dt_deslig) if dt_deslig else fmt_d8(func.get('datarescisao'))
    if not dt_des:
        raise ValueError(
            f"Funcionário {func.get('matricula')} sem data de desligamento "
            "(datarescisao) — obrigatória no S-2299.")

    # aviso prévio indenizado
    ind_api = str(ind_pagto_api or 'N').strip().upper()
    if ind_api not in ('S', 'N'):
        ind_api = 'N'
    api_xml = ""
    if ind_api == 'S' and dt_proj_fim_api:
        api_xml = f"\n      <dtProjFimAPI>{fmt_d8(dt_proj_fim_api)}</dtProjFimAPI>"

    # pensão alimentícia (0=não há, 1=%, 2=valor, 3=ambos)
    pens = str(pens_alim or '0').strip()
    pens_extra = ""
    if pens in ('1', '3') and perc_aliment is not None:
        pens_extra += f"\n      <percAliment>{x(perc_aliment)}</percAliment>"
    if pens in ('2', '3') and vr_alim is not None:
        pens_extra += f"\n      <vrAlim>{fmt_brl(vr_alim)}</vrAlim>"

    # codLotacao = centrocusto do funcionário
    cod_lotacao = str(func.get('centrocusto') or '').strip()
    if not cod_lotacao:
        raise ValueError(
            f"Funcionário {func.get('matricula')} sem 'centrocusto' — "
            "necessário para o codLotacao do S-2299.")

    # infoAgNocivo só para empregados (categorias 1xx), igual ao S-1200
    codcateg = str(func.get('codcateg') or '').strip()
    info_ag_nocivo_xml = ("""
              <infoAgNocivo>
                <grauExp>1</grauExp>
              </infoAgNocivo>""" if codcateg.startswith("1") else "")

    # codRubr / ideTabRubr: convenção COMPROVADA como aceita no web (XMLs do
    # S-1010 com recibo): codRubr = código CRU (como em tab_rubrica.cod_rubr,
    # sem zero-padding e sem sufixo) e ideTabRubr = raiz do CNPJ (8 dígitos).
    # (O desktop usa sufixo -FOL/-RES porque reusa o mesmo código em contextos
    #  diferentes; o web usa códigos distintos por contexto, então não precisa.)
    det_xml = ""
    for item in mov_items:
        cod = str(item.get('cod_verba') or item.get('cod_rubr') or '').strip()
        val = int(item.get('valor') or 0)
        if cod and val != 0:
            det_xml += f"""
              <detVerbas>
                <codRubr>{x(cod)}</codRubr>
                <ideTabRubr>{x(cnpj_raiz)}</ideTabRubr>
                <vrRubr>{fmt_brl(val)}</vrRubr>
                <indApurIR>0</indApurIR>
              </detVerbas>"""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtDeslig/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtDeslig/v_S_01_03_00 evtDeslig_v_S_01_03_00.xsd">
  <evtDeslig Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideVinculo>
      <cpfTrab>{x(cpf)}</cpfTrab>
      <matricula>{x(mat_es)}</matricula>
    </ideVinculo>
    <infoDeslig>
      <mtvDeslig>{x(mtv)}</mtvDeslig>
      <dtDeslig>{x(dt_des)}</dtDeslig>
      <indPagtoAPI>{ind_api}</indPagtoAPI>{api_xml}
      <pensAlim>{x(pens)}</pensAlim>{pens_extra}
      <verbasResc>
        <dmDev>
          <ideDmDev>{mat_es}00</ideDmDev>
          <infoPerApur>
            <ideEstabLot>
              <tpInsc>1</tpInsc>
              <nrInsc>{x(cnpj_emp)}</nrInsc>
              <codLotacao>{x(cod_lotacao)}</codLotacao>{det_xml}{info_ag_nocivo_xml}
            </ideEstabLot>
          </infoPerApur>
        </dmDev>
      </verbasResc>
    </infoDeslig>
  </evtDeslig>
</eSocial>"""


def _gerar_xml_s2399(func, mov_items, empresa, tpAmb="1",
                     mtv_deslig=None, dt_term=None,
                     pens_alim="0", perc_aliment=None, vr_alim=None):
    """Gera string XML do S-2399 (evtTSVTermino — Término de TSVE / não-empregado).

    É o PAR do S-2299 (que é para empregado, ligado ao S-2200). Aqui o vínculo
    é sem emprego, ligado ao S-2300: categorias 721/722/723 (diretor / CI) e
    901 (estagiário). Estrutura: ideTrabSemVinculo + infoTSVTermino.

    Parâmetros (espelham o S-2299):
      func       linha de tab_cad (cpf, matricula, codcateg, datarescisao,
                 motrescisao, centrocusto).
      mov_items  verbas rescisórias (tab_mov folha_tipo='R'); se vazio, o grupo
                 verbasResc é OMITIDO (caso comum do estagiário).
      mtv_deslig motivo do término; default = func['motrescisao']. Só é emitido
                 se houver valor — obrigatório p/ diretor/dirigente; para
                 estagiário normalmente não se aplica.
      pens_alim  '0' não há | '1' % | '2' valor | '3' ambos.

    A VALIDAR contra o XSD (o retorno do gov aponta o erro exato):
      (a) nome/uso de <mtvDesligTSV> e <pensaoAlim>;
      (b) se <verbasResc>/<dmDev> exige <codCateg>;
      (c) ordem dentro de <infoTSVTermino>.
    """
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):  return re.sub(r'\D', '', str(v or ''))
    def x(v):   return _esc(str(v or ''))
    def fmt_brl(c):
        try:    return f"{int(c) / 100:.2f}"
        except Exception: return "0.00"
    def fmt_d8(v):
        s = dg(v)
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}" if len(s) >= 8 else ""

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    cpf      = dg(func.get('cpf', '')).zfill(11)
    mat_es   = str(func.get('matricula_es') or func.get('matricula') or '').zfill(6)
    codcateg = str(func.get('codcateg') or '901').strip()

    # data de término (obrigatória)
    dt_ter = fmt_d8(dt_term) if dt_term else fmt_d8(func.get('datarescisao'))
    if not dt_ter:
        raise ValueError(
            f"Trabalhador {func.get('matricula')} sem data de término "
            "(datarescisao) — obrigatória no S-2399.")

    # motivo do término (Tabela 20) — condicional; só emite se houver
    mtv = str(mtv_deslig if mtv_deslig is not None
              else (func.get('motrescisao') or '')).strip()
    mtv_xml = (f"\n      <mtvDesligTSV>{x(mtv.zfill(2))}</mtvDesligTSV>"
               if mtv and mtv not in ('0', '00') else "")

    # pensão alimentícia — só emite se houver (0 = não há)
    pens = str(pens_alim or '0').strip()
    pens_xml = ""
    if pens and pens != '0':
        pens_extra = ""
        if pens in ('1', '3') and perc_aliment is not None:
            pens_extra += f"\n        <percAliment>{x(perc_aliment)}</percAliment>"
        if pens in ('2', '3') and vr_alim is not None:
            pens_extra += f"\n        <vrAlim>{fmt_brl(vr_alim)}</vrAlim>"
        pens_xml = f"\n      <pensaoAlim>{x(pens)}</pensaoAlim>{pens_extra}"

    # verbas rescisórias — detVerbas sob ideEstabLot (como no S-2299); opcional
    det_xml = ""
    for item in (mov_items or []):
        cod = str(item.get('cod_verba') or item.get('cod_rubr') or '').strip()
        val = int(item.get('valor') or 0)
        if cod and val != 0:
            det_xml += f"""
                <detVerbas>
                  <codRubr>{x(cod)}</codRubr>
                  <ideTabRubr>{x(cnpj_raiz)}</ideTabRubr>
                  <vrRubr>{fmt_brl(val)}</vrRubr>
                  <indApurIR>0</indApurIR>
                </detVerbas>"""

    verbas_xml = ""
    if det_xml.strip():
        cod_lotacao = str(func.get('centrocusto') or '').strip()
        verbas_xml = f"""
      <verbasResc>
        <dmDev>
          <ideDmDev>{mat_es}00</ideDmDev>
          <codCateg>{x(codcateg)}</codCateg>
          <infoPerApur>
            <ideEstabLot>
              <tpInsc>1</tpInsc>
              <nrInsc>{x(cnpj_emp)}</nrInsc>
              <codLotacao>{x(cod_lotacao)}</codLotacao>{det_xml}
            </ideEstabLot>
          </infoPerApur>
        </dmDev>
      </verbasResc>"""

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtTSVTermino/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtTSVTermino/v_S_01_03_00 evtTSVTermino_v_S_01_03_00.xsd">
  <evtTSVTermino Id="{evt_id}">
    <ideEvento>
      <indRetif>1</indRetif>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>{_verproc_str()}</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <ideTrabSemVinculo>
      <cpfTrab>{x(cpf)}</cpfTrab>
      <matricula>{x(mat_es)}</matricula>
      <codCateg>{x(codcateg)}</codCateg>
    </ideTrabSemVinculo>
    <infoTSVTermino>
      <dtTerm>{x(dt_ter)}</dtTerm>{mtv_xml}{pens_xml}{verbas_xml}
    </infoTSVTermino>
  </evtTSVTermino>
</eSocial>"""


# =========================================================
# eSocial S-2206 — Tela
# =========================================================
@app.route("/esocial_s2206")
def esocial_s2206():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    f_sit        = request.args.get("sit", "").strip().upper()

    rows = []
    try:
        rows = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_empresa", id_empresa)
                .eq("layout", "2206")
                .eq("ano_mes", int(anomes_atual))
                .order("data_cad", desc=True)
                .order("hora_cad", desc=True)
                .execute().data or [])
    except Exception:
        pass

    mats  = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad").select("matricula, nome")
                      .eq("id_empresa", id_empresa).in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    _SIT_MAP = {
        "E": ("Enviado",    "sit-enviado"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }
    contagens = {k: 0 for k in _SIT_MAP}
    for r in rows:
        r["_nome"]        = nomes.get(r.get("matricula"), "—")
        r["_datacad_fmt"] = _d8(r.get("data_cad"))
        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio_fmt"] = ""
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()
        if recibo:                          s = "E"
        elif obs.startswith("AGUARDANDO:"): s = "W"
        elif obs:                           s = "X"
        elif dgrava:                        s = "G"
        else:                               s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT_MAP[s][0]
        r["_sit_class"] = _SIT_MAP[s][1]
        contagens[s] = contagens.get(s, 0) + 1

    if f_sit:
        rows = [r for r in rows if r["_sit"] == f_sit]

    return render_template(
        "F10_eSocial_S2206.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows, total=len(rows),
        anomes_atual=anomes_atual,
        f_sit=f_sit, contagens=contagens,
        folha_aberta_esocial=_folha_aberta_no_esocial(),
    )


