@app.route("/api/esocial_verificacao/pdf")
def api_esocial_verificacao_pdf():
    if not session.get("logado"):
        return Response("Sessão expirada.", status=401, mimetype="text/plain")
    id_empresa   = _get_id_empresa()
    id_cliente   = session.get("id_cliente")
    anomes_atual = str(session.get("anomes_atual") or "")
    folha_tipo   = str(session.get("anomes_tipo") or "N")
    if not anomes_atual or len(anomes_atual) != 6:
        return Response("Folha ativa inválida.", status=400, mimetype="text/plain")

    # Auto-refresh desabilitado (ver comentario na rota /comparar acima).
    # try:
    #     _atualizar_pasta_verificacao(id_empresa, id_cliente, anomes_atual)
    # except Exception as _e:
    #     print(f"[VERIF PDF] auto-refresh falhou: {_e}")

    ok, payload = _montar_comparativo_verif(id_empresa, id_cliente, anomes_atual, folha_tipo)
    if not ok:
        return Response(payload.get("msg", "Erro."), status=500, mimetype="text/plain")

    linhas    = payload.get("linhas") or []
    diffs     = payload.get("diffs") or {"inss": 0, "fgts": 0, "birrf": 0}

    empresa_nm = session.get("empresa_info", "") or ""
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", "") or "")
    periodo_fmt = f"{anomes_atual[4:6]}/{anomes_atual[:4]}"

    from reportlab.lib.pagesizes import A4, landscape
    from io import BytesIO
    buf = BytesIO()
    page = landscape(A4)
    doc = SimpleDocTemplate(
        buf, pagesize=page,
        leftMargin=1.2*cm, rightMargin=1.2*cm,
        topMargin=2.0*cm,  bottomMargin=1.2*cm,
    )

    _FS  = 7
    _FSH = 7

    def P(txt, fn="Helvetica", fs=_FS, align=0, col=colors.HexColor("#1f2937")):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, alignment=align,
                            textColor=col, leading=fs + 1)
        return Paragraph(str(txt or ""), st)

    def br(centavos):
        try:
            v = int(centavos or 0) / 100.0
        except Exception:
            v = 0.0
        s = f"{v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        return s

    def fmt_diff(d):
        d = int(d or 0)
        if d == 0:
            return P("OK", fn="Helvetica-Bold", align=2, col=colors.HexColor("#15803d"))
        sinal = "+" if d > 0 else ""
        col = colors.HexColor("#15803d") if d > 0 else colors.HexColor("#b91c1c")
        return P(f"{sinal}{br(d)}", fn="Helvetica-Bold", align=2, col=col)

    # Cabeçalhos: 2 linhas
    grupo_inss = colors.HexColor("#dbeafe")
    grupo_fgts = colors.HexColor("#fed7aa")
    grupo_irrf = colors.HexColor("#bbf7d0")
    sub_inss   = colors.HexColor("#eff6ff")
    sub_fgts   = colors.HexColor("#fff7ed")
    sub_irrf   = colors.HexColor("#f0fdf4")

    hdr1 = [
        P("Matr.",      fn="Helvetica-Bold", fs=_FSH, align=0),
        P("Funcionário", fn="Helvetica-Bold", fs=_FSH, align=0),
        P("INSS Retido", fn="Helvetica-Bold", fs=_FSH, align=1, col=colors.HexColor("#1d4ed8")),
        "", "",
        P("FGTS",        fn="Helvetica-Bold", fs=_FSH, align=1, col=colors.HexColor("#9a3412")),
        "", "",
        P("IRRF Retido", fn="Helvetica-Bold", fs=_FSH, align=1, col=colors.HexColor("#15803d")),
        "", "",
    ]
    hdr2 = [
        "", "",
        P("Folha10",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("eSocial",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("Δ",        fn="Helvetica-Bold", fs=_FSH, align=2),
        P("Folha10",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("eSocial",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("Δ",        fn="Helvetica-Bold", fs=_FSH, align=2),
        P("Folha10",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("eSocial",  fn="Helvetica-Bold", fs=_FSH, align=2),
        P("Δ",        fn="Helvetica-Bold", fs=_FSH, align=2),
    ]
    tbl_data = [hdr1, hdr2]

    # totais por bloco
    t_f10_i = t_g_i = t_f10_f = t_g_f = t_f10_b = t_g_b = 0
    for l in linhas:
        mat = f"{int(l['matricula'] or 0):06d}" if l.get("matricula") else "—"
        nome = l.get("nome", "—")
        if l.get("no_cadastro"):
            nome = f"{nome} (CPF {l.get('cpf','')} fora do cadastro)"
        tbl_data.append([
            P(mat, fn="Helvetica"),
            P(nome, fn="Helvetica-Bold"),
            P(br(l["f10_inss"]),  align=2),
            P(br(l["gov_inss"]),  align=2),
            fmt_diff(l["diff_inss"]),
            P(br(l["f10_fgts"]),  align=2),
            P(br(l["gov_fgts"]),  align=2),
            fmt_diff(l["diff_fgts"]),
            P(br(l["f10_birrf"]), align=2),
            P(br(l["gov_birrf"]), align=2),
            fmt_diff(l["diff_birrf"]),
        ])
        t_f10_i += l["f10_inss"];  t_g_i += l["gov_inss"]
        t_f10_f += l["f10_fgts"];  t_g_f += l["gov_fgts"]
        t_f10_b += l["f10_birrf"]; t_g_b += l["gov_birrf"]

    # linha de totais
    tbl_data.append([
        "", P(f"TOTAIS ({len(linhas)} trabalhador{'es' if len(linhas)!=1 else ''})", fn="Helvetica-Bold"),
        P(br(t_f10_i), fn="Helvetica-Bold", align=2),
        P(br(t_g_i),   fn="Helvetica-Bold", align=2),
        fmt_diff(diffs.get("inss", 0)),
        P(br(t_f10_f), fn="Helvetica-Bold", align=2),
        P(br(t_g_f),   fn="Helvetica-Bold", align=2),
        fmt_diff(diffs.get("fgts", 0)),
        P(br(t_f10_b), fn="Helvetica-Bold", align=2),
        P(br(t_g_b),   fn="Helvetica-Bold", align=2),
        fmt_diff(diffs.get("birrf", 0)),
    ])

    # Larguras (somam ~27.3 cm — landscape A4 menos 2.4cm de margens)
    col_w = [1.4*cm, 6.0*cm,
             2.2*cm, 2.2*cm, 2.2*cm,
             2.2*cm, 2.2*cm, 2.2*cm,
             2.2*cm, 2.2*cm, 2.2*cm]
    tbl = Table(tbl_data, colWidths=col_w, repeatRows=2)
    estilo = [
        # Cabeçalho linha 1 — merge dos grupos
        ("SPAN",          (2, 0), (4, 0)),    # INSS
        ("SPAN",          (5, 0), (7, 0)),    # FGTS
        ("SPAN",          (8, 0), (10, 0)),   # IRRF
        ("SPAN",          (0, 0), (0, 1)),    # Matr.
        ("SPAN",          (1, 0), (1, 1)),    # Funcionário
        ("BACKGROUND",    (2, 0), (4, 1), grupo_inss),
        ("BACKGROUND",    (5, 0), (7, 1), grupo_fgts),
        ("BACKGROUND",    (8, 0), (10, 1), grupo_irrf),
        ("BACKGROUND",    (0, 0), (1, 1), colors.HexColor("#f1f5f9")),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
        ("ALIGN",         (2, 0), (-1, -1), "RIGHT"),
        ("ALIGN",         (0, 0), (1, -1), "LEFT"),
        ("TOPPADDING",    (0, 0), (-1, -1), 2),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ("LEFTPADDING",   (0, 0), (-1, -1), 3),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 3),
        ("LINEBELOW",     (0, 1), (-1, 1), 0.6, colors.HexColor("#94a3b8")),
        ("LINEBELOW",     (0, 2), (-1, -2), 0.2, colors.HexColor("#e2e8f0")),
        # Divisores entre blocos
        ("LINEBEFORE",    (2, 0), (2, -1), 1.2, colors.HexColor("#64748b")),
        ("LINEBEFORE",    (5, 0), (5, -1), 1.2, colors.HexColor("#64748b")),
        ("LINEBEFORE",    (8, 0), (8, -1), 1.2, colors.HexColor("#64748b")),
        ("BOX",           (0, 0), (-1, -1), 0.6, colors.HexColor("#94a3b8")),
        # Totais — fundo + linha grossa em cima
        ("BACKGROUND",    (0, -1), (-1, -1), colors.HexColor("#f1f5f9")),
        ("LINEABOVE",     (0, -1), (-1, -1), 0.8, colors.HexColor("#64748b")),
    ]
    # Listras alternadas nas linhas de dados (2 até -2)
    for i in range(2, len(tbl_data) - 1):
        if i % 2 == 0:
            estilo.append(("BACKGROUND", (2, i), (4, i), sub_inss))
            estilo.append(("BACKGROUND", (5, i), (7, i), sub_fgts))
            estilo.append(("BACKGROUND", (8, i), (10, i), sub_irrf))
    tbl.setStyle(TableStyle(estilo))

    story = [tbl]

    titulo_h = f"Verificação Folha10 × eSocial — {periodo_fmt}"
    emp_h    = f"{cnpj_fmt} — {empresa_nm}"
    agora    = datetime.now().strftime("%d/%m/%Y %H:%M")
    _pw, _ph = page

    def _header(canvas, doc):
        _pdf_num_pagina(canvas, doc)
        canvas.saveState()
        canvas.setFont("Helvetica", 8); canvas.setFillColor(colors.HexColor("#374151"))
        y1 = _ph - 1.0*cm
        canvas.drawString(1.2*cm, y1, emp_h)
        canvas.drawRightString(_pw - 1.2*cm, y1, agora)
        canvas.setFont("Helvetica-Bold", 9)
        canvas.drawCentredString(_pw / 2, y1 - 12, titulo_h)
        canvas.setStrokeColor(colors.HexColor("#94a3b8")); canvas.setLineWidth(0.4)
        canvas.line(1.2*cm, y1 - 16, _pw - 1.2*cm, y1 - 16)
        canvas.restoreState()

    doc.build(story, onFirstPage=_header, onLaterPages=_header)
    pdf_bytes = buf.getvalue(); buf.close()

    fname = f"verificacao_esocial_{anomes_atual}.pdf"
    return Response(pdf_bytes, mimetype="application/pdf",
                    headers={"Content-Disposition": f'inline; filename="{fname}"'})


# =========================================================
# eSocial S-1298 — TELA
# =========================================================
@app.route("/esocial_s1298")
def esocial_s1298():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    rows = []
    try:
        rows = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_empresa", id_empresa)
                .eq("layout", "1298")
                .order("ano_mes", desc=True)
                .order("data_cad", desc=True)
                .order("hora_cad", desc=True)
                .execute().data or [])
    except Exception:
        rows = []

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    def _fmt_anomes(v):
        s = str(int(v)).zfill(6) if v else ""
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else str(v or "")

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }
    _TIPO_LABEL = {"N": "Mensal", "1": "Anual / 13º"}

    for r in rows:
        r["_periodo"]      = _fmt_anomes(r.get("ano_mes"))
        r["_datacad_fmt"]  = _d8(r.get("data_cad"))
        r["_datagrava_fmt"]= _d8(r.get("data_grava"))
        r["_tipo_label"]   = _TIPO_LABEL.get(str(r.get("folha_tipo") or "N"), "Mensal")

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    return render_template(
        "F10_eSocial_S1298.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        total=len(rows),
        anomes_atual=anomes_atual,
        folha_aberta_esocial=_folha_aberta_no_esocial(),
    )


# =========================================================
# eSocial S-1298 — API: gerar + assinar + enviar
# =========================================================
@app.route("/api/esocial_s1298_enviar", methods=["POST"])
def api_esocial_s1298_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}

    ano_mes      = str(data.get("ano_mes", "")).strip()
    ind_apuracao = str(data.get("ind_apuracao", "1")).strip()
    tpAmb        = str(data.get("tpAmb", "1")).strip()

    if not ano_mes:
        return jsonify({"ok": False, "msg": "Período não informado."})

    _folha_tp_val = "1" if ind_apuracao == "2" else "N"
    ok_val, msg_val = _validar_folha_para_envio_esocial("1298", ano_mes, _folha_tp_val)
    if not ok_val:
        return jsonify({"ok": False, "msg": msg_val})

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*").eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # (cert validado depois do save do XML cru)
    agora      = datetime.now()
    folha_tp   = "1" if ind_apuracao == "2" else "N"
    id_cliente = session.get("id_cliente")
    try:
        _exist = (supabase.table("tab_esocial")
                  .select("id_esocial")
                  .eq("id_empresa", id_empresa)
                  .eq("layout", "1298")
                  .eq("ano_mes", int(ano_mes))
                  .eq("folha_tipo", folha_tp)
                  .order("data_cad", desc=True)
                  .limit(1).execute())
        if _exist.data:
            id_reg = _exist.data[0]["id_esocial"]
            supabase.table("tab_esocial").update({
                "recibo":          "",
                "observacao_erro": "",
                "data_grava":      "",
                "hora_grava":      "",
                "id_remessa":      agora.strftime("%Y%m%d%H%M%S"),
            }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        else:
            ins = {
                "id_cliente": id_cliente,
                "id_empresa": id_empresa,
                "data_cad":   agora.strftime("%Y%m%d"),
                "hora_cad":   agora.strftime("%H%M"),
                "id_remessa": agora.strftime("%Y%m%d%H%M%S"),
                "ano_mes":    int(ano_mes),
                "folha_tipo": folha_tp,
                "layout":     "1298",
                "matricula":  0,
                "codigo2":    0,
            }
            res_ins = supabase.table("tab_esocial").insert(ins).execute()
            id_reg  = res_ins.data[0]["id_esocial"]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao criar/atualizar registro: {e}"})

    # Gerar XML cru e salvar ASAP (antes de cert/assinatura)
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S1298_{ano_mes}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s1298(empresa, ano_mes, ind_apuracao, tpAmb)
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # Validar certificado e assinar
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        _xml_erro_save(_pref, 2, "Certificado digital não configurado.")
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"), grupo="3")
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    _xml_save(f"{_pref}_4_soap_envio.xml", soap_env)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        _xml_save(f"{_pref}_5_resposta.xml", detalhe)
        supabase.table("tab_esocial").update({"observacao_erro": detalhe[:295]})\
            .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, "Erro ao transmitir ao eSocial.")
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    _xml_save(f"{_pref}_5_resposta.xml", resp_envio)

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    if not protocolo_envio:
        agora2 = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora2.strftime("%Y%m%d"),
            "hora_grava":      agora2.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        _xml_erro_save(_pref, 4, "eSocial recusou o envio.")
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.",
                        "detalhe": analise["erro"], "id_esocial": id_reg})

    agora2 = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora2.strftime("%Y%m%d"),
        "hora_grava": agora2.strftime("%H%M"),
    }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_6_resultado_consulta.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1298 enviado: anomes={ano_mes} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "id_esocial": id_reg,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1298 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s1298_reconsultar", methods=["POST"])
def api_esocial_s1298_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1298")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está em estado Aguardando."})
    protocolo = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        emp = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    _aplicar_cert_esocial(emp)
    pfx_bytes = base64.b64decode(emp.get("cert_pfx_b64") or "")
    senha_str = _cert_decrypt(emp.get("cert_senha_enc") or "")
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        if tentativa:
            time.sleep(10)
        soap_cons = _soap_consultar(protocolo)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1298 reconsulta: id={id_reg} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-3000 — TELA
# =========================================================
@app.route("/esocial_s3000")
def esocial_s3000():
    if not session.get("logado"):
        return redirect("/")

    from collections import defaultdict

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    _LAYOUTS = {
        "2200": "S-2200 — Admissão",
        "2205": "S-2205 — Alt. Dados Cadastrais",
        "2206": "S-2206 — Alt. Contrato",
        "2210": "S-2210 — CAT",
        "2220": "S-2220 — Monit. Saúde",
        "2230": "S-2230 — Afastamento",
        "2299": "S-2299 — Desligamento",
    }

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    # Registros com recibo da folha ativa (exceto layout 3000).
    # S-1298 (Reabertura) e S-1299 (Fechamento) NAO podem ser excluidos via
    # tela: o S-1298 mantem a folha aberta no gov e o S-1299 fecha o
    # periodico; exclui-los rompe a sequencia logica do eSocial. A retificacao
    # desses eventos e feita reenviando outro do mesmo tipo.
    _LAYOUTS_NAO_EXCLUIVEIS = ("3000", "1298", "1299")
    elegiveis_raw = []
    if anomes_atual:
        try:
            rows = (supabase.table("tab_esocial")
                    .select("*")
                    .eq("id_empresa", id_empresa)
                    .not_.in_("layout", list(_LAYOUTS_NAO_EXCLUIVEIS))
                    .eq("ano_mes", int(anomes_atual))
                    .not_.is_("recibo", "null")
                    .neq("recibo", "")
                    .execute().data or [])
            elegiveis_raw = [r for r in rows
                             if (r.get("observacao_erro") or "") != "EXCLUIDO"]
        except Exception:
            elegiveis_raw = []

    # S-3000 já enviados
    s3000_rows = []
    try:
        s3000_rows = (supabase.table("tab_esocial")
                      .select("*")
                      .eq("id_empresa", id_empresa)
                      .eq("layout", "3000")
                      .order("data_cad", desc=True)
                      .order("hora_cad", desc=True)
                      .execute().data or [])
    except Exception:
        s3000_rows = []

    mats = list({r["matricula"] for r in elegiveis_raw + s3000_rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    # Agrupa elegíveis por layout
    por_layout = defaultdict(list)
    for r in elegiveis_raw:
        r["_nome"]      = nomes.get(r.get("matricula"), "—")
        r["_datagrava"] = _d8(r.get("data_grava"))
        por_layout[r["layout"]].append(r)

    layouts_disponiveis = sorted([
        {"codigo": lyt,
         "nome":   _LAYOUTS.get(lyt, f"S-{lyt}"),
         "count":  len(itens)}
        for lyt, itens in por_layout.items()
    ], key=lambda x: x["codigo"])

    for r in s3000_rows:
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        r["_nome"]      = nomes.get(r.get("matricula"), "—")
        r["_datagrava"] = _d8(r.get("data_grava"))
        if recibo:
            r["_sit"], r["_sit_label"], r["_sit_class"] = "E", "Enviado",   "sit-enviado"
        elif obs.startswith("AGUARDANDO:"):
            r["_sit"], r["_sit_label"], r["_sit_class"] = "W", "Aguardando","sit-aguardando"
        else:
            r["_sit"], r["_sit_label"], r["_sit_class"] = "X", "Com Erro",  "sit-erro"

    folha_aberta_esocial = _folha_aberta_no_esocial(id_empresa, anomes_atual)

    return render_template(
        "F10_eSocial_S3000.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        layouts_disponiveis=layouts_disponiveis,
        por_layout=dict(por_layout),
        s3000_rows=s3000_rows,
        anomes_atual=anomes_atual,
        folha_aberta_esocial=folha_aberta_esocial,
    )


# =========================================================
# eSocial S-3000 — API: excluir evento já enviado
# =========================================================
@app.route("/api/esocial_s3000_enviar", methods=["POST"])
def api_esocial_s3000_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa   = _get_id_empresa()
    cnpj_emp     = so_numeros(session.get("cnpj_empresa", ""))
    anomes_atual = str(session.get("anomes_atual") or "")
    data         = request.get_json(force=True) or {}
    id_reg       = data.get("id_esocial")
    tpAmb        = str(data.get("tpAmb", "1"))
    layout       = str(data.get("layout", "2200"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # S-1298 (Reabertura) e S-1299 (Fechamento) nao podem ser excluidos via
    # S-3000 — romperia a sequencia logica do periodico.
    if layout in ("1298", "1299"):
        nome = "S-1298 (Reabertura)" if layout == "1298" else "S-1299 (Fechamento)"
        return jsonify({"ok": False,
            "msg": (f"{nome} nao pode ser excluido via S-3000. "
                    "Reabertura/fechamento sao retificados reenviando outro "
                    "evento do mesmo tipo.")})

    # ── 1. Registro na tab_esocial ─────────────────────────
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", layout)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": f"Registro S-{layout} não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    recibo_excluir = (es.get("recibo") or "").strip()
    if not recibo_excluir:
        return jsonify({"ok": False, "msg": "Este registro não possui recibo — não é possível excluir."})

    ano_mes_reg = str(es.get("ano_mes") or "")
    if anomes_atual and ano_mes_reg != anomes_atual:
        return jsonify({"ok": False,
                        "msg": f"Registro pertence ao período {ano_mes_reg}, diferente da folha ativa ({anomes_atual})."})

    matricula = es.get("matricula")

    # ── 2. CPF do funcionário ──────────────────────────────
    try:
        r_func = (supabase.table("tab_cad")
                  .select("cpf, nome")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    cpf_trab = so_numeros(str(func.get("cpf") or ""))
    if len(cpf_trab) != 11:
        return jsonify({"ok": False, "msg": "CPF do funcionário inválido."})

    # ── 3. Empresa (cert validado depois do save do XML cru) ──
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    # ── 4. Gerar XML S-3000 cru e salvar ASAP (antes de cert/assinatura) ──
    _now2 = datetime.now()
    _pref = (f"{_xml_dir_rel(id_empresa, _now2)}/"
             f"S3000_{matricula}_{_now2.strftime('%Y%m%d_%H%M%S')}")

    try:
        xml_str = _gerar_xml_s3000(
            recibo_excluir, layout, cpf_trab, empresa, tpAmb,
            ano_mes=es.get("ano_mes"),
            folha_tipo=es.get("folha_tipo"),
        )
    except Exception as e:
        _xml_erro_save(_pref, 1, f"Erro ao gerar XML: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    _xml_save(f"{_pref}_1_evento.xml", xml_str)

    # ── 5. Validar certificado e assinar ───────────────────
    _aplicar_cert_esocial(empresa)
    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado. Acesse eSocial → Certificado Digital."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        _xml_erro_save(_pref, 2, f"Erro na assinatura: {e}")
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    _xml_save(f"{_pref}_2_assinado.xml", xml_assinado)

    # ── 7. Montar lote ─────────────────────────────────────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str,
                                tra_tpinsc=empresa.get("_tra_tpinsc"), tra_nrinsc=empresa.get("_tra_nrinsc"))
    except Exception as e:
        _xml_erro_save(_pref, 3, f"Erro ao montar lote: {e}")
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    _xml_save(f"{_pref}_3_lote.xml", lote_xml)

    # ── 8. Enviar ao eSocial ───────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    _xml_save(f"{_pref}_4_soap_envio.xml", soap_env)

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        _xml_erro_save(_pref, 4, "Erro ao transmitir ao eSocial.")
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": str(e)})

    _xml_save(f"{_pref}_5_resposta.xml", resp_envio)

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    if not protocolo_envio:
        _xml_erro_save(_pref, 4, "eSocial recusou o envio do S-3000.")
        return jsonify({"ok": False, "msg": "eSocial recusou o envio do S-3000.", "detalhe": analise["erro"]})

    # ── 9. Consultar resultado ─────────────────────────────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        _xml_save(f"{_pref}_6_resultado_consulta.xml", resp_cons)

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = not recibo_final and not obs_erro and cd_resp in ("101", "202")

    # ── 10. Atualizar banco ────────────────────────────────
    agora         = datetime.now()
    anomes_tp     = str(session.get("anomes_tipo") or "")
    folha_tipo_es = "1" if anomes_tp in ("1", "A") else "N"

    if recibo_final and not obs_erro and not aguardando:
        # Marca S-2200 como excluído (mantém o recibo original)
        supabase.table("tab_esocial").update({
            "observacao_erro": "EXCLUIDO",
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # Grava registro S-3000
    novo_es = {
        "id_cliente":  es.get("id_cliente"),
        "id_empresa":  id_empresa,
        "data_cad":    agora.strftime("%Y%m%d"),
        "hora_cad":    agora.strftime("%H%M"),
        "id_remessa":  agora.strftime("%Y%m%d%H%M%S"),
        "ano_mes":     es.get("ano_mes"),
        "folha_tipo":  folha_tipo_es,
        "layout":      "3000",
        "matricula":   matricula,
        "data_grava":  agora.strftime("%Y%m%d"),
        "hora_grava":  agora.strftime("%H%M"),
        "codigo2":     0,
    }
    if recibo_final and not obs_erro and not aguardando:
        novo_es["recibo"] = recibo_final
    elif aguardando:
        novo_es["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        novo_es["observacao_erro"] = obs_erro[:295]
    try:
        supabase.table("tab_esocial").insert(novo_es).execute()
    except Exception:
        pass

    gravar_log("ESOCIAL",
               f"S-3000 enviado: mat={matricula} rec_excluir={recibo_excluir[:20]} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando
    _msg_ok = f"Exclusão concluída. Recibo S-3000: {recibo_final}"
    _msg_ag = "eSocial ainda está processando o S-3000. Verifique a lista em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "msg":        _msg_ag if aguardando else (obs_erro or _msg_ok),
    })


# =========================================================
# CERTIFICADO DIGITAL — TELA DE CONFIGURAÇÃO
# =========================================================
@app.route("/config_certificado")
def config_certificado():
    if not session.get("logado"):
        return redirect("/")

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    cert_atual = {}
    try:
        r = (supabase.table("tab_empresa")
             .select("cert_titular, cert_cnpj, cert_validade")
             .eq("cnpj", cnpj_emp)
             .limit(1)
             .execute())
        if r.data:
            d = r.data[0]
            v = d.get("cert_validade") or ""
            if v:
                from datetime import date as _date
                hoje = _date.today()
                val_date = _date(int(v[:4]), int(v[4:6]), int(v[6:8]))
                dias_restantes = (val_date - hoje).days
                cert_atual = {
                    "titular":        d.get("cert_titular", ""),
                    "cnpj_fmt":       _fmt_cnpj(d.get("cert_cnpj", "") or ""),
                    "validade_fmt":   f"{v[6:8]}/{v[4:6]}/{v[:4]}",
                    "dias_restantes": dias_restantes,
                    "vencido":        dias_restantes < 0,
                    "alerta":         0 <= dias_restantes <= 30,
                }
    except Exception:
        pass

    return render_template(
        "F10_Config_Certificado.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(cnpj_emp),
        cert_atual=cert_atual,
    )


# =========================================================
# CERTIFICADO DIGITAL — API: salvar
# =========================================================
@app.route("/api/certificado_salvar", methods=["POST"])
def api_certificado_salvar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    cnpj_emp  = so_numeros(session.get("cnpj_empresa", ""))
    pfx_file  = request.files.get("pfx_file")
    senha     = request.form.get("pfx_senha", "").strip()

    if not pfx_file or pfx_file.filename == "":
        return jsonify({"ok": False, "msg": "Nenhum arquivo .pfx selecionado."})
    if not senha:
        return jsonify({"ok": False, "msg": "Senha do certificado não informada."})

    pfx_bytes = pfx_file.read()
    if len(pfx_bytes) < 20:
        return jsonify({"ok": False, "msg": "Arquivo inválido ou vazio."})

    try:
        info = _cert_info(pfx_bytes, senha)
    except ValueError as e:
        return jsonify({"ok": False, "msg": str(e)})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao processar certificado: {e}"})

    # Valida CNPJ do certificado (se extraído com sucesso)
    cnpj_cert = info["cnpj"]
    if len(cnpj_cert) == 14 and cnpj_cert != cnpj_emp:
        return jsonify({
            "ok": False,
            "msg": (f"CNPJ do certificado ({_fmt_cnpj(cnpj_cert)}) "
                    f"não corresponde à empresa ({_fmt_cnpj(cnpj_emp)}).")
        })

    pfx_b64   = base64.b64encode(pfx_bytes).decode()
    senha_enc = _cert_encrypt(senha)

    try:
        supabase.table("tab_empresa").update({
            "cert_pfx_b64":   pfx_b64,
            "cert_senha_enc": senha_enc,
            "cert_validade":  info["validade"],
            "cert_titular":   info["titular"],
            "cert_cnpj":      info["cnpj"],
        }).eq("cnpj", cnpj_emp).execute()
        gravar_log("CERT", f"Certificado digital salvo: {info['titular']} val:{info['validade_fmt']}")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    return jsonify({
        "ok":        True,
        "titular":   info["titular"],
        "cnpj_fmt":  _fmt_cnpj(cnpj_cert) if len(cnpj_cert) == 14 else cnpj_cert,
        "validade":  info["validade_fmt"],
    })


# =========================================================
# CERTIFICADO DIGITAL — API: remover
# =========================================================
@app.route("/api/certificado_remover", methods=["POST"])
def api_certificado_remover():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    cnpj_emp = so_numeros(session.get("cnpj_empresa", ""))
    try:
        supabase.table("tab_empresa").update({
            "cert_pfx_b64":   None,
            "cert_senha_enc": None,
            "cert_validade":  None,
            "cert_titular":   None,
            "cert_cnpj":      None,
        }).eq("cnpj", cnpj_emp).execute()
        gravar_log("CERT", "Certificado digital removido.")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    return jsonify({"ok": True})


# =========================================================
# PROCURADOR — certificado de TERCEIROS (procuração eletrônica)
# Tela de importação + APIs. O cert do procurador (escritório/contador)
# pode ser reutilizado por várias empresas do mesmo cliente.
# =========================================================
def _proc_fmt_insc(nr, tp):
    """Formata a inscrição do procurador (CNPJ=1 / CPF=2)."""
    nr = re.sub(r"\D", "", nr or "")
    if str(tp) == "1" and len(nr) == 14:
        return _fmt_cnpj(nr)
    if len(nr) == 11:
        return f"{nr[:3]}.{nr[3:6]}.{nr[6:9]}-{nr[9:]}"
    return nr or "—"


@app.route("/config_procurador")
def config_procurador():
    if not session.get("logado"):
        return redirect("/")

    id_cliente = session.get("id_cliente")
    procuradores = []
    try:
        r = (supabase.table("tab_procurador").select("*")
             .eq("id_cliente", id_cliente).order("nome").execute())
        from datetime import date as _date
        hoje = _date.today()
        for d in (r.data or []):
            v = d.get("cert_validade") or ""
            dias = None; venc = False; alerta = False; val_fmt = ""
            if len(v) == 8:
                try:
                    vd = _date(int(v[:4]), int(v[4:6]), int(v[6:8]))
                    dias = (vd - hoje).days
                    venc = dias < 0
                    alerta = 0 <= dias <= 30
                    val_fmt = f"{v[6:8]}/{v[4:6]}/{v[:4]}"
                except Exception:
                    pass
            tp = str(d.get("tpinsc") or "1")
            procuradores.append({
                "id":           d.get("id_procurador"),
                "nome":         d.get("nome") or d.get("cert_titular") or "",
                "titular":      d.get("cert_titular") or "",
                "tipo":         "CNPJ" if tp == "1" else "CPF",
                "insc_fmt":     _proc_fmt_insc(d.get("nrinsc"), tp),
                "validade_fmt": val_fmt,
                "dias":         dias,
                "vencido":      venc,
                "alerta":       alerta,
            })
    except Exception:
        pass

    return render_template(
        "F10_Config_Procurador.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        procuradores=procuradores,
    )


