@app.route("/api/procurador_salvar", methods=["POST"])
def api_procurador_salvar():
    """Importa o .pfx de um procurador (terceiro). tpInsc/nrInsc derivados do próprio cert."""
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_cliente = session.get("id_cliente")
    pfx_file   = request.files.get("pfx_file")
    senha      = request.form.get("pfx_senha", "").strip()
    nome       = (request.form.get("nome") or "").strip()

    if not pfx_file or pfx_file.filename == "":
        return jsonify({"ok": False, "msg": "Nenhum arquivo .pfx selecionado."})
    if not senha:
        return jsonify({"ok": False, "msg": "Senha do certificado não informada."})

    pfx_bytes = pfx_file.read()
    if len(pfx_bytes) < 20:
        return jsonify({"ok": False, "msg": "Arquivo inválido ou vazio."})

    try:
        info = _cert_info(pfx_bytes, senha)
    except ValueError as e:
        return jsonify({"ok": False, "msg": str(e)})
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao processar certificado: {e}"})

    # A inscrição do transmissor é a do TITULAR do certificado do procurador
    nr = re.sub(r"\D", "", info.get("cnpj") or "")
    if len(nr) not in (11, 14):
        return jsonify({"ok": False, "msg": ("Não foi possível extrair CNPJ/CPF do "
                        "certificado do procurador. Verifique o arquivo.")})
    tp = "2" if len(nr) == 11 else "1"

    reg = {
        "id_cliente":     id_cliente,
        "nome":           nome or info.get("titular") or "",
        "tpinsc":         tp,
        "nrinsc":         nr,
        "cert_pfx_b64":   base64.b64encode(pfx_bytes).decode(),
        "cert_senha_enc": _cert_encrypt(senha),
        "cert_titular":   info.get("titular") or "",
        "cert_validade":  info.get("validade") or "",
        "ativo":          True,
    }
    agora = datetime.now()
    reg["data_grava"] = agora.strftime("%Y%m%d")
    reg["hora_grava"] = agora.strftime("%H%M")

    try:
        resp = supabase.table("tab_procurador").insert(reg).execute()
        novo_id = (resp.data or [{}])[0].get("id_procurador")
        gravar_log("CERT", f"Procurador cadastrado: {reg['nome']} ({nr}) "
                           f"val:{info.get('validade_fmt')}")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    return jsonify({
        "ok":       True,
        "id":       novo_id,
        "titular":  info.get("titular"),
        "tipo":     "CNPJ" if tp == "1" else "CPF",
        "insc_fmt": _proc_fmt_insc(nr, tp),
        "validade": info.get("validade_fmt"),
    })


@app.route("/api/procurador_remover", methods=["POST"])
def api_procurador_remover():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_cliente = session.get("id_cliente")
    data = request.get_json(force=True) or {}
    pid  = data.get("id")
    if not pid:
        return jsonify({"ok": False, "msg": "Procurador não informado."})
    try:
        # Não deixa remover se alguma empresa ainda transmite por este procurador
        em_uso = (supabase.table("tab_empresa")
                  .select("razaosocial")
                  .eq("id_cliente", id_cliente)
                  .eq("id_procurador", int(pid))
                  .eq("cert_modo", "procuracao")
                  .limit(1).execute().data or [])
        if em_uso:
            nm = em_uso[0].get("razaosocial") or "uma empresa"
            return jsonify({"ok": False,
                "msg": (f"Este procurador está em uso por {nm}. Altere o modo de "
                        "transmissão dessa empresa antes de remover.")})
        supabase.table("tab_procurador").delete() \
            .eq("id_procurador", int(pid)).eq("id_cliente", id_cliente).execute()
        gravar_log("CERT", f"Procurador removido id={pid}")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})
    return jsonify({"ok": True})


# =========================================================
# CÁLCULO DA FOLHA
# =========================================================
_FERIADOS_FIXOS = [
    (1,  1),   # Confraternização Universal
    (4,  21),  # Tiradentes
    (5,  1),   # Dia do Trabalho
    (9,  7),   # Independência do Brasil
    (10, 12),  # Nossa Senhora Aparecida
    (11, 2),   # Finados
    (11, 15),  # Proclamação da República
    (12, 25),  # Natal
]

def _calc_dsr_mes(anomes):
    """Retorna (dias_uteis, dias_dsr) para o mês da folha.
    dias_uteis = seg-sáb excluindo feriados nacionais fixos que caem em dia útil
    dias_dsr   = domingos + feriados nacionais fixos que caem em seg-sáb
    """
    try:
        ano = int(str(anomes)[:4])
        mes = int(str(anomes)[4:6])
        _, total_dias = calendar.monthrange(ano, mes)
        feriados_mes = {fd for (fm, fd) in _FERIADOS_FIXOS if fm == mes}
        domingos = 0
        feriados_dia_util = 0
        for dia in range(1, total_dias + 1):
            wd = date(ano, mes, dia).weekday()  # 0=seg … 6=dom
            if wd == 6:
                domingos += 1
            elif dia in feriados_mes:
                feriados_dia_util += 1
        dias_dsr   = domingos + feriados_dia_util
        dias_uteis = total_dias - domingos - feriados_dia_util
        return dias_uteis, dias_dsr
    except Exception:
        return 22, 4   # fallback conservador


# Dias de trabalho considerados na escala 12x36 para o DSR: 15 nos meses
# normais e 14 em fevereiro (nao varia entre mes de 30 e 31 dias).
def _dsr_dias_escala(anomes):
    try:
        return 14 if int(str(anomes)[4:6]) == 2 else 15
    except Exception:
        return 15


def _ids_horario_escala(id_cliente):
    """id_horario dos horarios de escala 12x36 (do sistema e do cliente)."""
    ids = set()
    try:
        r = (supabase.table("tab_aux_horarios")
             .select("id_horario, nome_horario")
             .in_("id_cliente", [0] + ([id_cliente] if id_cliente else []))
             .ilike("nome_horario", "%12x36%")
             .execute())
        for row in (r.data or []):
            if row.get("id_horario"):
                ids.add(int(row["id_horario"]))
    except Exception:
        pass
    return ids


def _calc_etapa1_dados(id_empresa):
    """Busca funcionários e calcula salário hora (Etapa 1)."""
    linhas = []
    try:
        r = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, undsalfixo, vrsalfx, qtdhrsmes, dtadm, codcateg, dtnascto, id_tab_horario")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .order("matricula")
             .execute())
        for f in (r.data or []):
            vrsalfx   = int(f.get("vrsalfx")   or 0)
            qtdhrsmes = int(f.get("qtdhrsmes")  or 0)
            und       = (f.get("undsalfixo") or "M").upper()
            nome      = (f.get("nomer") or f.get("nome") or "").strip()

            if und == "H":
                sal_hora = float(vrsalfx)
                sal_mes  = float(vrsalfx * qtdhrsmes)
                tipo     = "Horista"
            else:
                sal_hora = round(vrsalfx / qtdhrsmes, 4) if qtdhrsmes else 0.0
                sal_mes  = float(vrsalfx)
                tipo     = "Mensalista"

            linhas.append({
                "matricula":    f.get("matricula"),
                "nome":         nome,
                "tipo":         tipo,
                "sal_base":     vrsalfx,
                "qtdhrsmes":    qtdhrsmes,
                "sal_hora":     sal_hora,
                "sal_mes":      sal_mes,
                "sal_base_fmt": _fmt_brl(vrsalfx),
                "sal_hora_fmt": _fmt_brl(sal_hora, 4),
                "sal_mes_fmt":  _fmt_brl(sal_mes),
                "dtadm":        str(f.get("dtadm")    or ""),
                "codcateg":     str(f.get("codcateg") or ""),
                "dtnascto":     str(f.get("dtnascto") or ""),
                "id_horario":   int(f.get("id_tab_horario") or 0),
            })
    except Exception:
        pass
    return linhas


def _d_br(s):
    """YYYY-MM-DD ou YYYYMMDD → DD/MM/YYYY. Retorna vazio se inválido."""
    try:
        if not s:
            return ""
        s = str(s)
        if len(s) >= 10 and s[4] == "-":   # YYYY-MM-DD
            return f"{s[8:10]}/{s[5:7]}/{s[:4]}"
        if len(s) == 8:                     # YYYYMMDD
            return f"{s[6:8]}/{s[4:6]}/{s[:4]}"
        return ""
    except Exception:
        return ""


def _dias_afast(di_raw, df_raw):
    """Dias inclusive entre duas datas YYYYMMDD. None se inválido ou sem data fim."""
    try:
        if not di_raw or not df_raw or len(di_raw) < 8 or len(df_raw) < 8:
            return None
        d1 = date(int(di_raw[:4]), int(di_raw[4:6]), int(di_raw[6:8]))
        d2 = date(int(df_raw[:4]), int(df_raw[4:6]), int(df_raw[6:8]))
        return (d2 - d1).days + 1
    except Exception:
        return None


def _split_afast_mes(di_raw_orig, df_raw, dt_ini_c, dt_fim_c, atestado_acum=0):
    """Dias de afastamento do mês divididos em atestado (empresa) e INSS.
    A cota de atestado é 15 dias acumulados no mês — atestado_acum repassa
    quantos dias já foram consumidos em afastamentos anteriores do mesmo mês.
    Retorna (dias_atestado, dias_inss, dias_no_mes). None nos três se inválido.
    """
    try:
        def _p(s):
            return date(int(s[:4]), int(s[4:6]), int(s[6:8]))

        if not di_raw_orig or len(di_raw_orig) < 8:
            return None, None, None

        d_ini_orig = _p(di_raw_orig)
        d_ini_mes  = _p(dt_ini_c)
        d_fim_mes  = _p(dt_fim_c)
        d_fim      = _p(df_raw) if df_raw and len(df_raw) >= 8 else d_fim_mes

        d_ef_ini = max(d_ini_orig, d_ini_mes)
        d_ef_fim = min(d_fim, d_fim_mes)
        if d_ef_ini > d_ef_fim:
            return 0, 0, 0

        dias_no_mes   = (d_ef_fim - d_ef_ini).days + 1
        restante      = max(0, 15 - atestado_acum)
        dias_atestado = min(dias_no_mes, restante)
        dias_inss     = dias_no_mes - dias_atestado

        return dias_atestado, dias_inss, dias_no_mes
    except Exception:
        return None, None, None


def _calc_etapa2_afastamentos(id_empresa, anomes, id_cliente=None):
    """Dict {matricula: [lista de afastamentos]} com op1=6 sobrepostos ao mês anomes."""
    if not anomes or len(anomes) != 6:
        return {}
    ano  = int(anomes[:4])
    mes  = int(anomes[4:6])
    ultimo = ((date(ano + 1, 1, 1) if mes == 12 else date(ano, mes + 1, 1)) - timedelta(days=1)).day
    d_ini_c = date(ano, mes, 1)
    d_fim_c = date(ano, mes, ultimo)

    def _parse_dt(v):
        """YYYYMMDD, YYYY-MM-DD ou DDMMYYYY → date. None se inválido ou vazio."""
        s = str(v or "").strip()
        d = ''.join(c for c in s if c.isdigit())
        if len(d) < 8:
            return None
        d = d[:8]
        try:                          # YYYYMMDD (formato padrão)
            return date(int(d[:4]), int(d[4:6]), int(d[6:8]))
        except ValueError:
            pass
        try:                          # DDMMYYYY (legado Access)
            return date(int(d[4:8]), int(d[2:4]), int(d[:2]))
        except ValueError:
            return None

    result = {}
    try:
        q = (supabase.table("tab_eventos")
             .select("matricula, op2, data1i, data1f, campotxt4")
             .eq("id_empresa", id_empresa)
             .eq("op1", 6))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        r = q.execute()
        for ev in (r.data or []):
            mat = int(ev.get("matricula") or 0)
            if mat == 0:
                continue
            # op2 >= 10 indica registro auxiliar (CAT, retorno, etc.), não afastamento real
            if int(ev.get("op2") or 0) >= 10:
                continue
            d_ini = _parse_dt(ev.get("data1i"))
            d_fim = _parse_dt(ev.get("data1f"))
            if d_ini and d_ini <= d_fim_c and (d_fim is None or d_fim >= d_ini_c):
                result.setdefault(mat, []).append(ev)
    except Exception as e:
        print(f"[afast] ERRO: {e}")
    return result


def _norm_data8(s):
    """Normaliza data para YYYYMMDD, aceitando YYYY-MM-DD ou YYYYMMDD."""
    s = str(s or "").strip()
    if len(s) == 10 and s[4] == "-":   # YYYY-MM-DD → YYYYMMDD
        return s[:4] + s[5:7] + s[8:10]
    return s


def _dias_no_mes(di_raw, df_raw, dt_ini_c, dt_fim_c):
    """Dias de sobreposição de [di_raw, df_raw] com o mês [dt_ini_c, dt_fim_c]. YYYYMMDD."""
    try:
        def _p(s):
            s = _norm_data8(s)
            return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        di_raw = _norm_data8(di_raw)
        df_raw = _norm_data8(df_raw)
        if not di_raw or len(di_raw) < 8:
            return None
        d_ini_orig = _p(di_raw)
        d_ini_mes  = _p(dt_ini_c)
        d_fim_mes  = _p(dt_fim_c)
        d_fim      = _p(df_raw) if df_raw and len(df_raw) >= 8 else d_fim_mes
        d_ef_ini   = max(d_ini_orig, d_ini_mes)
        d_ef_fim   = min(d_fim, d_fim_mes)
        return max(0, (d_ef_fim - d_ef_ini).days + 1)
    except Exception:
        return None


def _calc_etapa2_ferias(id_empresa, anomes):
    """Dict {matricula: [lista de férias]} com op1=3 sobrepostos ao mês anomes."""
    if not anomes or len(anomes) != 6:
        return {}
    ano  = int(anomes[:4])
    mes  = int(anomes[4:6])
    ultimo   = ((date(ano + 1, 1, 1) if mes == 12 else date(ano, mes + 1, 1)) - timedelta(days=1)).day
    dt_ini_c = f"{ano:04d}{mes:02d}01"
    dt_fim_c = f"{ano:04d}{mes:02d}{ultimo:02d}"
    result   = {}
    try:
        r = (supabase.table("tab_eventos")
             .select("matricula, data1i, data1f, data2i, data2f, ref1")
             .eq("id_empresa", id_empresa)
             .eq("op1", 3)
             .execute())
        for ev in (r.data or []):
            mat = int(ev.get("matricula") or 0)
            di1 = _norm_data8(ev.get("data1i") or "")
            df1 = _norm_data8(ev.get("data1f") or "")
            # data2i/data2f é o período aquisitivo, não conta como dias de gozo
            p1_ok = di1 and di1 <= dt_fim_c and (not df1 or df1 >= dt_ini_c)
            if p1_ok:
                result.setdefault(mat, []).append(ev)
    except Exception as e:
        print(f"[ferias] ERRO: {e}")
    return result


def _calc_etapa5_faltas(id_empresa, anomes, id_cliente=None):
    """Dict {matricula: [lista de faltas]} com op1=21 no mês anomes."""
    result = {}
    try:
        q = (supabase.table("tab_eventos")
             .select("matricula, op2, data1i, campotxt4")
             .eq("id_empresa", id_empresa)
             .eq("op1", 21)
             .eq("folha", int(anomes)))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        r = q.execute()
        for ev in (r.data or []):
            mat = int(ev.get("matricula") or 0)
            if mat == 0:
                continue
            result.setdefault(mat, []).append(ev)
        for mat in result:
            result[mat].sort(key=lambda e: e.get("data1i") or "")
    except Exception:
        pass
    return result


