def _nverbas_build(v_codes, id_empresa, anomes, anomes_tipo, ordem="mat"):
    """Monta verbas_sel, rows e totais para o relatório de N Verbas."""
    verbas_info = {}
    try:
        r = (supabase.table("tab_rubrica")
             .select("cod_rubr,dsc_rubr,tp_rubr,unid_verba")
             .in_("cod_rubr", v_codes)
             .execute())
        for v in (r.data or []):
            verbas_info[int(v["cod_rubr"])] = v
    except Exception:
        pass

    movs = []
    try:
        r = (supabase.table("tab_mov")
             .select("matricula,cod_verba,qtd,valor")
             .eq("id_empresa", id_empresa)
             .eq("folha", int(anomes) if anomes.isdigit() else 0)
             .eq("folha_tipo", anomes_tipo)
             .eq("situacao", "A")
             .in_("cod_verba", v_codes)
             .execute())
        movs = r.data or []
    except Exception:
        pass

    dados = {}
    for m in movs:
        mat = int(m["matricula"])
        cod = int(m["cod_verba"])
        dados.setdefault(mat, {}).setdefault(cod, {"qtd": 0, "valor": 0})
        dados[mat][cod]["qtd"]   += int(m.get("qtd",   0) or 0)
        dados[mat][cod]["valor"] += int(m.get("valor", 0) or 0)

    nomes = {}
    if dados:
        try:
            r = (supabase.table("tab_cad")
                 .select("matricula,nomer,nome")
                 .eq("id_empresa", id_empresa)
                 .in_("matricula", list(dados.keys()))
                 .execute())
            for f in (r.data or []):
                nm = (f.get("nomer") or f.get("nome") or "").strip()
                nomes[int(f["matricula"])] = nm
        except Exception:
            pass

    totais = {cod: {"qtd": 0, "valor": 0} for cod in v_codes}
    rows   = []
    for mat in dados.keys():
        row = {"matricula": mat, "nome": nomes.get(mat, ""), "verbas": {}}
        for cod in v_codes:
            vd = dados[mat].get(cod, {"qtd": 0, "valor": 0})
            row["verbas"][cod] = {"qtd": vd["qtd"], "valor": vd["valor"],
                                  "val_fmt": _fmt_brl(vd["valor"])}
            totais[cod]["qtd"]   += vd["qtd"]
            totais[cod]["valor"] += vd["valor"]
        rows.append(row)

    if ordem == "nome":
        rows.sort(key=lambda r: r["nome"].upper())
    else:
        rows.sort(key=lambda r: r["matricula"])

    for cod in v_codes:
        totais[cod]["val_fmt"] = _fmt_brl(totais[cod]["valor"])

    verbas_sel = []
    for cod in v_codes:
        info = verbas_info.get(cod, {})
        unid = info.get("unid_verba", "V")
        verbas_sel.append({
            "cod":     cod,
            "dsc":     info.get("dsc_rubr", f"Verba {cod}"),
            "tp":      info.get("tp_rubr", "1"),
            "unid":    unid,
            "tem_qtd": unid in ("H", "D"),
        })

    return verbas_sel, rows, totais


def _nverbas_parse_params():
    """Extrai v_codes e ordem dos query params."""
    v_codes = []
    for k in ("v1", "v2", "v3"):
        v = (request.args.get(k) or "").strip()
        if v and v.isdigit():
            cod = int(v)
            if cod not in v_codes:
                v_codes.append(cod)
    ordem = request.args.get("ordem") or _get_pref("ordem_rel", "mat")
    return v_codes, ordem


def _gerar_nverbas_pdf(verbas_sel, rows, totais, empresa_nm, folha_fmt, tipo_label, cnpj_fmt=""):
    from io import BytesIO
    from datetime import datetime
    from reportlab.platypus import (SimpleDocTemplate, Table, TableStyle,
                                    Paragraph, Spacer)
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle

    buf   = BytesIO()
    page  = landscape(A4)
    agora = datetime.now()
    doc   = SimpleDocTemplate(buf, pagesize=page,
                              leftMargin=1.5*cm, rightMargin=1.5*cm,
                              topMargin=2.0*cm, bottomMargin=1.5*cm)
    W = page[0] - 3*cm

    navy     = colors.HexColor("#0b1f3a")
    yellow   = colors.HexColor("#f5c842")
    lt_gray  = colors.HexColor("#f8fafc")
    border_c = colors.HexColor("#dde3ec")
    c_prov   = colors.HexColor("#166534"); bg_prov = colors.HexColor("#dcfce7")
    c_desc   = colors.HexColor("#991b1b"); bg_desc = colors.HexColor("#fee2e2")
    total_bg = colors.HexColor("#0b1f3a")

    def P(txt, fn="Helvetica", fs=8, col=colors.black, align=0):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, textColor=col,
                            alignment=align, leading=fs+2)
        return Paragraph(str(txt), st)

    # ── Cabeçalho padrão (canvas) ──
    mes_str, ano_str = (folha_fmt.split("/") + [""])[:2]
    meses_pt = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    mes_nm = meses_pt[int(mes_str)] if mes_str.isdigit() and 1 <= int(mes_str) <= 12 else mes_str

    def _draw_header(canvas, doc):
        canvas.saveState()
        xL = doc.leftMargin
        xR = xL + W
        y1 = page[1] - 0.55*cm
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#374151"))
        canvas.drawString(xL, y1, f"{cnpj_fmt}  —  {empresa_nm}" if cnpj_fmt else empresa_nm)
        canvas.drawRightString(xR, y1, agora.strftime("%d/%m/%Y  %H:%M"))
        y2 = y1 - 0.55*cm
        periodo = f"{mes_nm.upper()}/{ano_str}"
        if tipo_label not in ("Normal", "Folha Normal"):
            periodo += f"  ·  {tipo_label.upper()}"
        canvas.setFont("Helvetica-Bold", 12)
        canvas.setFillColor(colors.HexColor("#0b1f3a"))
        canvas.drawString(xL, y2, f"RELAÇÃO DE N VERBAS  —  {periodo}")
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#64748b"))
        canvas.drawRightString(xR, y2, f"Página  {doc.page}")
        canvas.setStrokeColor(colors.HexColor("#0b1f3a"))
        canvas.setLineWidth(0.8)
        canvas.line(xL, y2 - 0.28*cm, xR, y2 - 0.28*cm)
        canvas.restoreState()

    story = []

    # ── Larguras das colunas ──
    col_w = [1.8*cm, 5.5*cm]
    rem   = W - sum(col_w)
    slot  = rem / len(verbas_sel)
    for v in verbas_sel:
        if v["tem_qtd"]:
            col_w += [slot * 0.33, slot * 0.67]
        else:
            col_w.append(slot)

    # ── Linha 0: grupo das verbas ──
    grp_row  = [P(""), P("")]
    grp_cmds = []
    ci = 2
    for v in verbas_sel:
        span   = 2 if v["tem_qtd"] else 1
        c_txt  = c_prov if v["tp"] == "1" else c_desc
        bg_col = bg_prov if v["tp"] == "1" else bg_desc
        grp_row.append(P(f"{v['cod']:04d} — {v['dsc']}", "Helvetica-Bold", 8, c_txt, 2))
        if span == 2:
            grp_row.append(P(""))
            grp_cmds.append(("SPAN",       (ci,0), (ci+1,0)))
        grp_cmds.append(("BACKGROUND", (ci,0), (ci+span-1,0), bg_col))
        ci += span

    # ── Linha 1: sub-cabeçalhos ──
    sub_c = colors.HexColor("#4b5e7a")
    sub_row = [P("MATR.", "Helvetica-Bold", 7, sub_c),
               P("NOME",  "Helvetica-Bold", 7, sub_c)]
    for v in verbas_sel:
        if v["tem_qtd"]:
            sub_row += [P("QTD",   "Helvetica-Bold", 7, sub_c, 2),
                        P("VALOR", "Helvetica-Bold", 7, sub_c, 2)]
        else:
            sub_row.append(P("VALOR", "Helvetica-Bold", 7, sub_c, 2))

    # ── Linhas de dados ──
    data_rows = []
    for row in rows:
        dr = [P(f"{row['matricula']:06d}", "Courier", 8, colors.HexColor("#1e293b")),
              P(row["nome"][:32],          "Helvetica", 8)]
        for v in verbas_sel:
            vd = row["verbas"][v["cod"]]
            if v["tem_qtd"]:
                dr.append(P(str(vd["qtd"]) if vd["qtd"] else "—", "Courier", 7,
                            colors.HexColor("#64748b"), 2))
            val_c = colors.HexColor("#1e293b") if vd["valor"] else colors.HexColor("#cbd5e1")
            dr.append(P(vd["val_fmt"], "Courier-Bold", 8, val_c, 2))
        data_rows.append(dr)

    # ── Linha de total ──
    tot_row = [P("TOTAL",        "Helvetica-Bold", 8, colors.HexColor("#8baac8")),
               P(f"{len(rows)} func.", "Helvetica", 7, colors.HexColor("#8baac8"))]
    for v in verbas_sel:
        t = totais[v["cod"]]
        if v["tem_qtd"]:
            tot_row.append(P(str(t["qtd"]) if t["qtd"] else "—",
                             "Courier", 7, colors.HexColor("#8baac8"), 2))
        tot_row.append(P(t["val_fmt"], "Courier-Bold", 8, yellow, 2))

    all_rows = [grp_row, sub_row] + data_rows + [tot_row]
    n        = len(all_rows)

    tbl = Table(all_rows, colWidths=col_w, repeatRows=2)
    tbl.setStyle(TableStyle([
        ("VALIGN",          (0,0),  (-1,-1), "MIDDLE"),
        ("TOPPADDING",      (0,0),  (-1,-1), 4),
        ("BOTTOMPADDING",   (0,0),  (-1,-1), 4),
        ("BACKGROUND",      (0,1),  (-1,1),  colors.HexColor("#f1f5f9")),
        ("LINEBELOW",       (0,1),  (-1,1),  1,   border_c),
        ("ROWBACKGROUNDS",  (0,2),  (-1,n-2), [colors.white, lt_gray]),
        ("LINEBELOW",       (0,2),  (-1,n-2), 0.5, border_c),
        ("BACKGROUND",      (0,n-1),(-1,n-1), total_bg),
        ("TOPPADDING",      (0,n-1),(-1,n-1), 6),
        ("BOTTOMPADDING",   (0,n-1),(-1,n-1), 6),
        ("BOX",             (0,0),  (-1,-1), 0.5, border_c),
        ("GRID",            (0,1),  (-1,-1), 0.5, border_c),
    ] + grp_cmds))

    story.append(tbl)
    doc.build(story, onFirstPage=_draw_header, onLaterPages=_draw_header)
    buf.seek(0)
    return buf


@app.route("/rel_nverbas")
def rel_nverbas():
    if not session.get("logado"):
        return redirect("/")
    v_codes, ordem = _nverbas_parse_params()
    if not v_codes:
        return redirect("/config_rel_verbas")

    id_empresa  = _get_id_empresa()
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")

    verbas_sel, rows, totais = _nverbas_build(v_codes, id_empresa, anomes, anomes_tipo, ordem)

    folha_fmt  = f"{anomes[4:6]}/{anomes[0:4]}" if len(anomes) == 6 else "—"
    tipo_label = {"N": "Normal", "1": "13º Mês", "A": "Adiant. 13º"}.get(anomes_tipo, anomes_tipo)

    # URL para o PDF com os mesmos parâmetros
    pdf_params = "&".join(f"v{i+1}={c}" for i, c in enumerate(v_codes))
    if ordem != "mat":
        pdf_params += f"&ordem={ordem}"
    pdf_url = f"/rel_nverbas_pdf?{pdf_params}"

    return render_template(
        "F10_Rel_NVerbas.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        nome=session.get("nome", ""),
        folha_fmt=folha_fmt,
        tipo_label=tipo_label,
        verbas=verbas_sel,
        rows=rows,
        totais=totais,
        pdf_url=pdf_url,
        ordem=ordem,
    )


@app.route("/rel_nverbas_pdf")
def rel_nverbas_pdf():
    if not session.get("logado"):
        return redirect("/")
    v_codes, ordem = _nverbas_parse_params()
    if not v_codes:
        return redirect("/config_rel_verbas")

    id_empresa  = _get_id_empresa()
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")

    verbas_sel, rows, totais = _nverbas_build(v_codes, id_empresa, anomes, anomes_tipo, ordem)

    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))
    folha_fmt  = f"{anomes[4:6]}/{anomes[0:4]}" if len(anomes) == 6 else "—"
    tipo_label = {"N": "Normal", "1": "13º Mês", "A": "Adiant. 13º"}.get(anomes_tipo, anomes_tipo)

    buf      = _gerar_nverbas_pdf(verbas_sel, rows, totais, empresa_nm, folha_fmt, tipo_label, cnpj_fmt)
    nome_arq = f"RelNVerbas_{anomes}.pdf"
    from flask import make_response
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{nome_arq}"'
    return resp


@app.route("/visualizar_calculo")
def visualizar_calculo():
    if not session.get("logado"):
        return redirect("/")
    id_empresa = _get_id_empresa()
    funcionarios = []
    try:
        linhas = _calc_etapa1_dados(id_empresa)
        funcionarios = [{"matricula": int(l["matricula"]), "nome": l["nome"],
                         "demitido": False} for l in (linhas or [])]
    except Exception:
        pass
    # Inclui os demitidos do mês da folha (situacao='D' com datarescisao no mês)
    # — não aparecem em _calc_etapa1_dados, mas precisam entrar na lista para
    # visualizar a rescisão calculada.
    try:
        anomes = str(session.get("anomes_atual") or "")
        if len(anomes) == 6 and anomes.isdigit():
            _ano = int(anomes[:4]); _mes = int(anomes[4:6])
            _ult = calendar.monthrange(_ano, _mes)[1]
            ini_int = int(f"{_ano:04d}{_mes:02d}01")
            fim_int = int(f"{_ano:04d}{_mes:02d}{_ult:02d}")
            mats_existentes = {f["matricula"] for f in funcionarios}
            for d in _lista_demitidos_dados(id_empresa, ini_int, fim_int):
                if d["matricula"] not in mats_existentes:
                    funcionarios.append({"matricula": d["matricula"],
                                         "nome": d["nome"], "demitido": True})
            funcionarios.sort(key=lambda f: f["matricula"])
    except Exception:
        pass
    # Modo rescisão: lista apenas os demitidos do mês e auto-carrega os valores.
    modo_rescisao = (request.args.get("modo") == "rescisao")
    if modo_rescisao:
        funcionarios = [f for f in funcionarios if f.get("demitido")]
    sit_map = {"A": ("Aberta","sit-aberta"), "X": ("Aberta","sit-aberta"),
               "C": ("Calculada","sit-calculada"), "F": ("Fechada","sit-fechada")}
    sit_st = str(session.get("anomes_situacao") or "")
    sit_label, sit_class = sit_map.get(sit_st, ("", ""))
    # Permite chegar nesta tela ja com um funcionario pre-selecionado, vindo
    # do Calculo Individual (?matricula=N) — auto-carrega a visualizacao.
    try:
        matricula_inicial = int(request.args.get("matricula") or 0)
    except Exception:
        matricula_inicial = 0
    return render_template(
        "F10_Visualizar_Calculo.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=str(session.get("anomes_atual") or ""),
        folha_sit_label=sit_label,
        folha_sit_class=sit_class,
        funcionarios=funcionarios,
        matricula_inicial=matricula_inicial,
        modo_rescisao=modo_rescisao,
    )


@app.route("/api/visualizar_calculo_dados")
def api_visualizar_calculo_dados():
    if not session.get("logado"):
        return jsonify({"erro": "não autenticado"}), 401
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    folha_tipo  = str(session.get("anomes_tipo") or "N")
    folha_tipo_mov = folha_tipo if folha_tipo in ("F", "R", "A", "1") else "N"

    mats_param = request.args.get("matriculas", "")
    mats = [int(m) for m in mats_param.split(",") if m.strip().isdigit()]
    if not mats or not anomes:
        return jsonify({"erro": "parâmetros inválidos"}), 400
    mats_set = set(mats)

    # rubricas
    rubricas_info = {}
    try:
        for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
            r_rub = (supabase.table("tab_rubrica")
                     .select("cod_rubr, dsc_rubr, tp_rubr, unid_verba, tpn_inc_cp")
                     .eq("id_cliente", cli_id)
                     .execute())
            for row in (r_rub.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod:
                    rubricas_info[cod] = {
                        "tp":     str(row.get("tp_rubr")    or "1"),
                        "dsc":    str(row.get("dsc_rubr")   or ""),
                        "unid":   str(row.get("unid_verba") or "V"),
                        "inc_cp": str(row.get("tpn_inc_cp") or ""),
                    }
    except Exception:
        pass
    for cod, tp in [(1,"1"),(2,"1"),(30,"1"),(31,"1"),(139,"2")]:
        rubricas_info.setdefault(cod, {"tp": tp, "dsc": "", "unid": "V", "inc_cp": ""})
    rubricas_info.setdefault(160, {"tp": "2", "dsc": "Desconto Adiantamento Quinzenal",
                                   "unid": "V", "inc_cp": ""})

    # dados dos funcionários (nome + dtadm + sal_hora + sal_mes + codcateg)
    nomes        = {}
    dtadms       = {}
    sal_hora_map = {}
    sal_mes_map  = {}
    codcateg_map = {}
    try:
        for l in (_calc_etapa1_dados(id_empresa) or []):
            mat = int(l["matricula"])
            nomes[mat]        = l["nome"]
            dtadms[mat]       = str(l.get("dtadm") or "")
            sal_hora_map[mat] = float(l.get("sal_hora") or 0)
            sal_mes_map[mat]  = float(l.get("sal_mes")  or 0)
            codcateg_map[mat] = str(l.get("codcateg") or "")
    except Exception:
        pass
    # Demitidos não vêm de _calc_etapa1_dados (situação 'A'): busca salário do
    # cadastro p/ as matrículas ainda ausentes, senão as verbas H saem com valor 0.
    faltantes = [m for m in mats_set if m not in sal_hora_map]
    if faltantes:
        try:
            r_dem = (supabase.table("tab_cad")
                     .select("matricula, nome, nomer, dtadm, vrsalfx, undsalfixo, qtdhrsmes, codcateg")
                     .eq("id_empresa", id_empresa).in_("matricula", faltantes).execute())
            for f in (r_dem.data or []):
                m = int(f.get("matricula") or 0)
                vrsalfx = int(f.get("vrsalfx") or 0)
                qhm = int(f.get("qtdhrsmes") or 0) or 220
                und = (f.get("undsalfixo") or "M").upper()[:1]
                if und == "H":
                    sh = float(vrsalfx); sm = float(vrsalfx * qhm)
                else:
                    sh = round(vrsalfx / qhm, 4) if qhm else 0.0; sm = float(vrsalfx)
                nomes.setdefault(m, (f.get("nomer") or f.get("nome") or "").strip())
                dtadms.setdefault(m, str(f.get("dtadm") or ""))
                sal_hora_map.setdefault(m, sh)
                sal_mes_map.setdefault(m, sm)
                codcateg_map.setdefault(m, str(f.get("codcateg") or ""))
        except Exception:
            pass

    # dias do mês da folha (para sal_dia das verbas D-type)
    try:
        _ano_f = int(anomes[:4]); _mes_f = int(anomes[4:6])
        dias_mes_folha = calendar.monthrange(_ano_f, _mes_f)[1]
    except Exception:
        dias_mes_folha = 30

    # afastamentos e férias do mês
    def _dt_br(s):
        return f"{s[6:8]}/{s[4:6]}/{s[:4]}" if s and len(s) >= 8 else ""

    afastamentos_mes = {}
    try:
        afastamentos_mes = _calc_etapa2_afastamentos(id_empresa, anomes, id_cliente=id_cliente)
    except Exception:
        pass

    ferias_mes = {}
    try:
        ferias_mes = _calc_etapa2_ferias(id_empresa, anomes)
    except Exception:
        pass

    # Demitidos do mês (situacao='D' com datarescisao no anomes): para eles a
    # folha exibida é a de RESCISÃO (folha_tipo='R'), independente do tipo da
    # folha ativa. Monta o tipo de folha alvo por matrícula e o conjunto de
    # tipos a consultar em tab_total / tab_mov.
    demitidos_mes  = set()
    demissao_map   = {}   # {matricula: datarescisao YYYYMMDD}
    try:
        if len(anomes) == 6 and anomes.isdigit():
            _ano_d = int(anomes[:4]); _mes_d = int(anomes[4:6])
            _ult_d = calendar.monthrange(_ano_d, _mes_d)[1]
            _ini_d = int(f"{_ano_d:04d}{_mes_d:02d}01")
            _fim_d = int(f"{_ano_d:04d}{_mes_d:02d}{_ult_d:02d}")
            for d in _lista_demitidos_dados(id_empresa, _ini_d, _fim_d):
                m = d["matricula"]
                if m in mats_set:
                    demitidos_mes.add(m)
                    demissao_map[m] = d.get("dem_raw") or ""
                    # demitido não vem de _calc_etapa1_dados (situacao='A'):
                    # preenche nome/admissão para o cabeçalho do card.
                    nomes.setdefault(m, d.get("nome") or "")
                    dtadms.setdefault(m, d.get("adm_raw") or "")
    except Exception:
        pass
    tipo_por_mat = {m: ("R" if m in demitidos_mes else folha_tipo_mov) for m in mats_set}
    tipos_query  = sorted(set(tipo_por_mat.values())) or [folha_tipo_mov]

    # lê tab_total do mês para os funcionários selecionados
    totais_data = {}
    try:
        q_tot = (supabase.table("tab_total")
                 .select("matricula, folha_tipo, "
                         "valor_base_inss_semlimite, valor_base_inss_comlimite, "
                         "valor_inss_retido, valor_base_fgts, valor_fgts, "
                         "valor_irrf_basetotal, valor_irrf_basetabela, "
                         "valor_irrf_dependentes, qtd_irrf_dependentes, "
                         "valor_total_proventos, valor_total_descontos, valor_liquido")
                 .eq("id_empresa", id_empresa)
                 .eq("folha", int(anomes))
                 .in_("folha_tipo", tipos_query))
        if id_cliente:
            q_tot = q_tot.eq("id_cliente", id_cliente)
        for reg in (q_tot.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            if mat in mats_set and str(reg.get("folha_tipo") or "N") == tipo_por_mat.get(mat):
                totais_data.setdefault(mat, []).append(reg)
    except Exception:
        pass

    # lê tab_mov pelo tipo de folha alvo de cada funcionário (folha ativa em
    # geral; RESCISÃO='R' para os demitidos do mês): cada tipo de folha
    # (N / F / R / A-adiant.13 / 1-13º) é uma folha à parte, não misturar tipos.
    # (verbas 161-164 são exibidas separadamente após o subtotal — não incluí-las
    #  no cálculo de proventos/descontos, mas listá-las no card)
    mov_data = {}
    erro_query = None
    try:
        q = (supabase.table("tab_mov")
             .select("matricula, cod_verba, qtd, valor, origem, folha_tipo")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .eq("folha", int(anomes))
             .in_("folha_tipo", tipos_query))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        for reg in (q.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            if mat in mats_set and str(reg.get("folha_tipo") or "N") == tipo_por_mat.get(mat):
                mov_data.setdefault(mat, []).append(reg)
    except Exception as e_q:
        erro_query = str(e_q)

    _tipo_ord = {"N": 0, "F": 1, "R": 2}

    # monta resultado por funcionário
    resultado = []
    for mat in sorted(mats):
        # agrupa verbas por folha_tipo
        agg = {}
        for v in mov_data.get(mat, []):
            cod  = int(v.get("cod_verba")  or 0)
            val  = float(v.get("valor")    or 0)
            qtd  = int(v.get("qtd")        or 0)
            ft   = str(v.get("folha_tipo") or "N")
            orig = str(v.get("origem")     or "")
            ri   = rubricas_info.get(cod, {"tp": "1", "dsc": f"Verba {cod:04d}", "unid": "V"})
            formula = ""
            # Verba H: recalcula valor = horas × sal_hora (ignora o que está no banco)
            if ri.get("unid") == "H" and qtd > 0:
                sh  = sal_hora_map.get(mat, 0)
                val = round(qtd / 60 * sh, 4)
                hh_q = qtd // 60; mm_q = qtd % 60
                formula = (f"{hh_q:02d}h{mm_q:02d} × {_fmt_brl(int(sh))}/h"
                           f"  =  {_fmt_brl(int(round(val)))}")
            # Verba D: recalcula valor = qtd_dias × sal_dia
            elif ri.get("unid") == "D" and qtd > 0:
                sm  = sal_mes_map.get(mat, 0)
                sal_dia = round(sm / dias_mes_folha, 4) if dias_mes_folha else 0
                val = round(qtd * sal_dia, 4)
                formula = (f"{qtd} {'dia' if qtd == 1 else 'dias'}"
                           f" × {_fmt_brl(int(round(sal_dia)))}/dia"
                           f"  =  {_fmt_brl(int(round(val)))}")
            else:
                _orig_lbl = {"M": "Lançamento manual", "C": "Calculado automaticamente", "F": "Movimento fixo"}
                formula = _orig_lbl.get(orig, f"Origem: {orig}")
            key  = (cod, ft, orig)
            if key in agg:
                agg[key]["valor"] += val
                agg[key]["qtd"]   += qtd
            else:
                agg[key] = {"cod": cod, "dsc": ri["dsc"] or f"Verba {cod:04d}",
                            "tp": ri["tp"], "unid": ri["unid"],
                            "qtd": qtd, "valor": val, "ft": ft, "orig": orig,
                            "formula": formula}

        todos_verbas = sorted(agg.values(), key=lambda x: (_tipo_ord.get(x["ft"], 9), x["cod"]))

        # ETAPA 9B — verbas automáticas do intermitente (024, 56, 58)
        is_int = codcateg_map.get(mat, "") == "111"
        if is_int:
            val_003 = int(sum(v["valor"] for v in todos_verbas if v["cod"] == 3))
            if val_003 > 0:
                ri_24 = rubricas_info.get(24, {"tp": "1", "dsc": "Repouso Remunerado",      "unid": "V"})
                ri_56 = rubricas_info.get(56, {"tp": "1", "dsc": "13 Salario Intermitente", "unid": "V"})
                ri_58 = rubricas_info.get(58, {"tp": "1", "dsc": "Ferias Intermitentes",    "unid": "V"})

                # 1. Garante verba 024 em todos_verbas antes de calcular base
                dias_uteis_dsr, dias_dsr = _calc_dsr_mes(anomes)
                val_024 = int(round(val_003 / dias_uteis_dsr * dias_dsr)) if dias_uteis_dsr else 0
                fml_024 = (f"{_fmt_brl(val_003)} ÷ {dias_uteis_dsr} dias úteis"
                           f" × {dias_dsr} dias DSR = {_fmt_brl(val_024)}")
                ex_024 = next((v for v in todos_verbas if v["cod"] == 24), None)
                if ex_024:
                    ex_024["formula"] = fml_024
                else:
                    todos_verbas.append({
                        "cod": 24, "dsc": ri_24.get("dsc") or "Repouso Remunerado",
                        "tp": "1", "unid": "V", "qtd": 0, "valor": float(val_024),
                        "ft": "N", "orig": "C", "formula": fml_024,
                    })

                # 2. Base 56/58 = soma de todos proventos que incidem no INSS
                base_56_58 = int(sum(
                    v["valor"] for v in todos_verbas
                    if rubricas_info.get(v["cod"], {}).get("inc_cp") == "11" and v["valor"] > 0
                ))
                dozeavo = base_56_58 // 12
                terco   = dozeavo // 3
                val_56  = dozeavo
                val_58  = dozeavo + terco

                formulas_56_58 = {
                    56: (f"Base INSS: {_fmt_brl(base_56_58)}  ÷ 12"
                         f" = {_fmt_brl(dozeavo)}"),
                    58: (f"Base INSS: {_fmt_brl(base_56_58)}  ÷ 12 + 1/3"
                         f" = {_fmt_brl(dozeavo)} + {_fmt_brl(terco)}"
                         f" = {_fmt_brl(val_58)}"),
                }
                novos_56_58 = {
                    56: {"cod": 56, "dsc": ri_56.get("dsc") or "13 Salario Intermitente",
                         "tp": "1", "unid": "V", "qtd": 0, "valor": float(val_56),
                         "ft": "N", "orig": "C"},
                    58: {"cod": 58, "dsc": ri_58.get("dsc") or "Ferias Intermitentes",
                         "tp": "1", "unid": "V", "qtd": 0, "valor": float(val_58),
                         "ft": "N", "orig": "C"},
                }
                for cod_9b, fml in formulas_56_58.items():
                    ex = next((v for v in todos_verbas if v["cod"] == cod_9b), None)
                    if ex:
                        ex["formula"] = fml
                    else:
                        entry = novos_56_58[cod_9b].copy()
                        entry["formula"] = fml
                        todos_verbas.append(entry)

        # monta seções separadas por tipo de folha
        tipos_presentes = sorted({v["ft"] for v in todos_verbas}, key=lambda t: _tipo_ord.get(t, 9))
        secoes = []
        for ft in tipos_presentes:
            vbs_all    = [v for v in todos_verbas if v["ft"] == ft]
            vbs_adiant = [v for v in vbs_all if int(v["cod"]) in (161, 162, 163, 164)]
            vbs_info   = [v for v in vbs_all if int(v["cod"]) >= 9900]
            vbs        = [v for v in vbs_all
                          if int(v["cod"]) < 9900
                          and int(v["cod"]) not in (161, 162, 163, 164)]
            prov = sum(v["valor"] for v in vbs if v["tp"] == "1")
            desc = sum(v["valor"] for v in vbs if v["tp"] != "1")
            # total do tab_total para este tipo
            tot_reg = next((t for t in totais_data.get(mat, []) if t.get("folha_tipo") == ft), None)
            secoes.append({
                "ft":            ft,
                "verbas":        vbs,
                "verbas_adiant": vbs_adiant,
                "verbas_info":   vbs_info,
                "sub_prov":      prov,
                "sub_desc":      desc,
                "sub_liq":       prov - desc,
                "total_reg":     tot_reg,
            })

        total_prov = sum(s["sub_prov"] for s in secoes)
        total_desc = sum(s["sub_desc"] for s in secoes)

        # info extra: afastamentos e férias do mês
        info_partes = []
        for ev in afastamentos_mes.get(mat, []):
            di = _dt_br(str(ev.get("data1i") or ""))
            df = _dt_br(str(ev.get("data1f") or ""))
            info_partes.append("Afastamento: " + (f"{di} a {df}" if df else f"desde {di}"))
        for ev in ferias_mes.get(mat, []):
            di   = _dt_br(str(ev.get("data1i") or ""))
            df   = _dt_br(str(ev.get("data1f") or ""))
            dias = int(ev.get("ref1") or 0)
            pa_i = _dt_br(str(ev.get("data2i") or ""))
            pa_f = _dt_br(str(ev.get("data2f") or ""))
            txt  = "Férias: " + f"{di} a {df}" + (f" ({dias}d)" if dias else "")
            if pa_i and pa_f:
                txt += f"  ·  Aquisitivo: {pa_i} a {pa_f}"
            info_partes.append(txt)

        sh_emp = sal_hora_map.get(mat, 0)
        resultado.append({
            "matricula":       mat,
            "nome":            nomes.get(mat, f"Matrícula {mat:06d}"),
            "dtadm":           _dt_br(dtadms.get(mat, "")),
            "demitido":        mat in demitidos_mes,
            "dtdemissao":      _dt_br(demissao_map.get(mat, "")),
            "is_intermitente": is_int,
            "sal_hora_fmt":    _fmt_brl(int(sh_emp)) if is_int and sh_emp else "",
            "info_extra":      " · ".join(info_partes),
            "secoes":          secoes,
            "total_prov":      total_prov,
            "total_desc":      total_desc,
            "liquido":         total_prov - total_desc,
        })

    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else anomes
    resp = {"anomes_fmt": anomes_fmt, "funcionarios": resultado}
    if erro_query:
        resp["erro_query"] = erro_query
    return jsonify(resp)


# =========================================================
# FOLHA DE PAGAMENTO — DADOS (compartilhado entre tela e PDF)
# =========================================================
def _folha_pagamento_dados(id_empresa, anomes, anomes_tipo, id_cliente, ordem="mat", cnpj_empresa=""):
    _cnpj_dig = ''.join(c for c in cnpj_empresa if c.isdigit())
    def _clean_fil(v):
        raw = str(v or "").strip()
        dig = ''.join(c for c in raw if c.isdigit())
        return raw if (dig and dig.lstrip("0") and dig != _cnpj_dig) else ""
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"
    ano, mes = anomes[:4], anomes[4:6]
    meses_pt = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    mes_nm   = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    tipo_lbl = {"N":"Folha Normal","F":"Férias","R":"Rescisão",
                "A":"Adiantamento 13°","1":"13° Salário"}.get(anomes_tipo, anomes_tipo)
    anomes_fmt = f"{mes_nm} / {ano}"

    rubricas_info = {}
    try:
        for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
            r = (supabase.table("tab_rubrica")
                 .select("cod_rubr,dsc_rubr,tp_rubr,unid_verba,tpn_inc_cp,tpn_inc_fgts,tpn_inc_irrf")
                 .eq("id_cliente", cli_id).execute())
            for row in (r.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod:
                    rubricas_info[cod] = {
                        "dsc":  str(row.get("dsc_rubr")     or f"Verba {cod:04d}"),
                        "tp":   str(row.get("tp_rubr")      or "1"),
                        "unid": str(row.get("unid_verba")   or "V"),
                        "icp":  str(row.get("tpn_inc_cp")   or ""),
                        "ift":  str(row.get("tpn_inc_fgts") or ""),
                        "iir":  str(row.get("tpn_inc_irrf") or ""),
                    }
    except Exception:
        pass
    _sys_verbs = {1:"Salário",2:"Horas Extras",30:"Férias",31:"13° Sal",
                  101:"INSS",120:"IRRF",139:"FGTS Provisionado"}
    for cod, tp in [(1,"1"),(2,"1"),(30,"1"),(31,"1"),(101,"2"),(120,"2"),(139,"2")]:
        rubricas_info.setdefault(cod, {"dsc":_sys_verbs.get(cod, f"Verba {cod:04d}"),
                                       "tp":tp,"unid":"V","icp":"","ift":"","iir":""})

    # 161-164: lidos em dict próprio (linha "Adiantamento Quinzenal" acima das informativas)
    mov_data    = {}
    adiant_data = {}
    try:
        q = (supabase.table("tab_mov")
             .select("matricula,cod_verba,qtd,valor")
             .eq("id_empresa",  id_empresa)
             .eq("situacao",    "A")
             .eq("folha",       int(anomes))
             .eq("folha_tipo",  folha_tipo_mov))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        for reg in (q.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            if not mat:
                continue
            cod = int(reg.get("cod_verba") or 0)
            if cod in (161, 162, 163, 164):
                adiant_data.setdefault(mat, []).append(reg)
            else:
                mov_data.setdefault(mat, []).append(reg)
    except Exception:
        pass

    func_info = {}
    try:
        r = (supabase.table("tab_cad")
             .select("matricula,nome,nomer,dtadm,vrsalfx,cbofuncao,centrocusto,filial,codcateg")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .execute())
        for f in (r.data or []):
            mat = int(f.get("matricula") or 0)
            if not mat:
                continue
            nome  = str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip()
            cbo   = str(f.get("cbofuncao") or "").strip()
            func_info[mat] = {
                "nome":   nome,
                "dtadm":  str(f.get("dtadm")      or ""),
                "sal":    int(f.get("vrsalfx")     or 0),
                "funcao": f"CBO {cbo}" if cbo else "—",
                "cc":     str(f.get("centrocusto") or "000"),
                "filial": str(f.get("filial")      or ""),
                "cat":    int(f.get("codcateg")     or 0),
            }
    except Exception:
        pass
    if mov_data and not func_info:
        try:
            r2 = (supabase.table("tab_cad")
                  .select("matricula,nome,nomer,dtadm,vrsalfx,codcateg")
                  .eq("id_empresa", id_empresa)
                  .in_("matricula", list(mov_data.keys()))
                  .execute())
            for f in (r2.data or []):
                mat = int(f.get("matricula") or 0)
                if not mat:
                    continue
                func_info[mat] = {
                    "nome":   str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip(),
                    "dtadm":  str(f.get("dtadm") or ""),
                    "sal":    int(f.get("vrsalfx") or 0),
                    "funcao": "—",
                    "cc":     "000",
                    "filial": "",
                    "cat":    int(f.get("codcateg") or 0),
                }
        except Exception:
            pass

    cbos_unicos = list({fi["funcao"].replace("CBO ","") for fi in func_info.values()
                        if fi["funcao"].startswith("CBO ")})
    if cbos_unicos:
        try:
            rc = (supabase.table("tab_aux_funcao_total")
                  .select("cbo_codigo,cbo_nome")
                  .in_("cbo_codigo", cbos_unicos)
                  .execute())
            cbo_nomes = {r["cbo_codigo"]: r["cbo_nome"] for r in (rc.data or []) if r.get("cbo_codigo")}
            for fi in func_info.values():
                if fi["funcao"].startswith("CBO "):
                    cbo = fi["funcao"].replace("CBO ", "")
                    if cbo in cbo_nomes:
                        fi["funcao"] = cbo_nomes[cbo]
        except Exception:
            pass

    # Base IRRF (ja deduzida de INSS + dependentes) lida do tab_total — fonte unica de verdade
    irrf_basetabela = _irrf_basetabela_por_mat(id_empresa, anomes, folha_tipo_mov, id_cliente)

    cc_groups = {}
    for mat in sorted(mov_data.keys()):
        fi = func_info.get(mat, {"nome":f"Matr. {mat:06d}","dtadm":"","sal":0,
                                  "funcao":"—","cc":"000","filial":""})
        agg = {}
        for v in mov_data[mat]:
            cod = int(v.get("cod_verba") or 0)
            val = int(v.get("valor")     or 0)
            qtd = int(v.get("qtd")       or 0)
            ri  = rubricas_info.get(cod, {"dsc":f"Verba {cod:04d}","tp":"1",
                                           "unid":"V","icp":"","ift":"","iir":""})
            if cod in agg:
                agg[cod]["val"] += val; agg[cod]["qtd"] += qtd
            else:
                agg[cod] = {"cod":cod,"dsc":ri["dsc"],"tp":ri["tp"],
                             "unid":ri["unid"],"icp":ri["icp"],"ift":ri["ift"],
                             "iir":ri["iir"],"qtd":qtd,"val":val}
        verbas_all  = sorted(agg.values(), key=lambda x: x["cod"])
        verbas      = [v for v in verbas_all if v["cod"] <= 9900]
        verbas_info = [v for v in verbas_all if v["cod"] >  9900]
        tot_prov = sum(v["val"] for v in verbas if v["tp"] == "1")
        tot_desc = sum(v["val"] for v in verbas if v["tp"] != "1")
        liquido  = tot_prov - tot_desc
        inss_val  = agg.get(101, {}).get("val", 0)
        base_inss = sum(v["val"] for v in verbas if v["tp"]=="1" and v["icp"]=="11")
        base_irrf = irrf_basetabela.get(mat, 0)
        base_fgts = sum(v["val"] for v in verbas if v["tp"]=="1" and v["ift"] in ("11","S"))
        _aliq_fgts = 2 if int(fi.get("cat") or 0) == 103 else 8   # menor aprendiz (cat 103) recolhe 2%
        fgts_val  = agg[139]["val"] if 139 in agg else int(base_fgts * _aliq_fgts) // 100

        # Adiantamento Quinzenal (161-164) — bloco próprio acima das informativas
        adiant_list = []
        for r_ad in adiant_data.get(mat, []):
            cod_ad = int(r_ad.get("cod_verba") or 0)
            val_ad = int(r_ad.get("valor")     or 0)
            if val_ad <= 0:
                continue
            ri_ad = rubricas_info.get(cod_ad, {"dsc": f"Verba {cod_ad:04d}"})
            adiant_list.append({"cod": cod_ad,
                                "dsc": ri_ad.get("dsc") or f"Verba {cod_ad:04d}",
                                "val": val_ad})
        adiant_list.sort(key=lambda x: x["cod"])

        cc_key   = fi["cc"] or "000"
        cc_groups.setdefault(cc_key, []).append({
            "mat":mat, "nome":fi["nome"], "funcao":fi["funcao"],
            "dtadm":fi["dtadm"], "sal":fi["sal"], "filial":fi["filial"],
            "verbas":verbas, "verbas_info":verbas_info,
            "adiant_list": adiant_list,
            "prov":tot_prov, "desc":tot_desc, "liq":liquido,
            "b_inss":base_inss, "b_irrf":base_irrf, "b_fgts":base_fgts, "fgts":fgts_val,
        })

    def _fdt(s):
        return f"{s[6:8]}/{s[4:6]}/{s[:4]}" if s and len(s) >= 8 else "—"

    def _fsal(v):
        return _fmt_brl(v) + "/Mês"

    def _fqtd(qtd, unid):
        if unid == "H" and qtd > 0:
            return f"{qtd // 60}h{qtd % 60:02d}"
        if unid == "D" and qtd > 0:
            return f"{qtd} dia{'s' if qtd != 1 else ''}"
        return ""

    grand_prov = grand_desc = grand_liq = grand_funcs = 0
    cc_list = []
    for cc_code in sorted(cc_groups.keys()):
        funcs = cc_groups[cc_code]
        if ordem == "alfa":
            funcs = sorted(funcs, key=lambda f: f["nome"].upper())
        cc_prov  = sum(f["prov"] for f in funcs)
        cc_desc  = sum(f["desc"] for f in funcs)
        cc_liq   = sum(f["liq"]  for f in funcs)
        grand_prov += cc_prov
        grand_desc += cc_desc
        grand_liq  += cc_liq
        grand_funcs += len(funcs)
        cc_list.append({
            "cc":          cc_code,
            "n_funcs":     len(funcs),
            "cc_prov_fmt": _fmt_brl(cc_prov),
            "cc_desc_fmt": _fmt_brl(cc_desc),
            "cc_liq_fmt":  _fmt_brl(cc_liq),
            "funcs": [{
                "mat":        f"{f['mat']:06d}",
                "nome":       f["nome"],
                "funcao":     f["funcao"],
                "dtadm_fmt":  _fdt(f["dtadm"]),
                "sal_fmt":    _fsal(f["sal"]),
                "filial":     _clean_fil(f["filial"]),
                "prov_fmt":   _fmt_brl(f["prov"]),
                "desc_fmt":   _fmt_brl(f["desc"]),
                "liq_fmt":    _fmt_brl(f["liq"]),
                "liq_ok":     f["liq"] >= 0,
                "b_inss_fmt": _fmt_brl(f["b_inss"]),
                "b_irrf_fmt": _fmt_brl(f["b_irrf"]),
                "b_fgts_fmt": _fmt_brl(f["b_fgts"]),
                "fgts_fmt":   _fmt_brl(f["fgts"]),
                "verbas": [{
                    "cod":      f"{v['cod']:04d}",
                    "dsc":      v["dsc"],
                    "qtd_fmt":  _fqtd(v["qtd"], v["unid"]),
                    "prov_fmt": _fmt_brl(v["val"]) if v["tp"] == "1" else "",
                    "desc_fmt": _fmt_brl(v["val"]) if v["tp"] != "1" else "",
                    "is_prov":  v["tp"] == "1",
                } for v in f["verbas"]],
                "verbas_info": [{
                    "cod":     f"{v['cod']:04d}",
                    "dsc":     v["dsc"],
                    "qtd_fmt": _fqtd(v["qtd"], v["unid"]),
                    "val_fmt": _fmt_brl(v["val"]),
                } for v in f["verbas_info"]],
                "adiant_list": [{
                    "cod":     f"{a['cod']:04d}",
                    "dsc":     a["dsc"],
                    "val_fmt": _fmt_brl(a["val"]),
                } for a in f.get("adiant_list", [])],
            } for f in funcs],
        })

    return {
        "anomes_fmt":  anomes_fmt,
        "tipo_lbl":    tipo_lbl,
        "n_func":      grand_funcs,
        "grand_prov":  _fmt_brl(grand_prov),
        "grand_desc":  _fmt_brl(grand_desc),
        "grand_liq":   _fmt_brl(grand_liq),
        "cc_list":     cc_list,
        "multi_cc":    len(cc_list) > 1,
    }


@app.route("/relatorio_folha")
def relatorio_folha():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    empresa_nm  = str(session.get("empresa_info") or "")
    if not anomes or not id_empresa:
        return redirect("/menu")

    from flask import request as _req
    ordem = _req.args.get("ordem") or _get_pref("ordem_rel", "mat")
    cnpj_empresa = str(session.get("cnpj_empresa") or "")
    d = _folha_pagamento_dados(id_empresa, anomes, anomes_tipo, id_cliente, ordem=ordem, cnpj_empresa=cnpj_empresa)
    return render_template(
        "F10_Rel_Folha_Preview.html",
        versao  = ler_versao(),
        nome    = session.get("nome", ""),
        empresa = empresa_nm,
        ordem   = ordem,
        **d,
    )


# =========================================================
# FOLHA DE PAGAMENTO — RELATÓRIO PDF
# =========================================================
def _gerar_folha_pagamento_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                                empresa_nm, cnpj_fmt, versao, sit_label,
                                nome_usuario="", ordem="mat"):
    from reportlab.platypus import (SimpleDocTemplate, Table, TableStyle,
                                    Paragraph, Spacer, PageBreak, KeepTogether)
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from reportlab.lib.styles import ParagraphStyle
    from io import BytesIO
    from datetime import datetime

    buf            = BytesIO()
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"
    agora          = datetime.now()
    ano, mes       = anomes[:4], anomes[4:6]
    meses_pt       = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                      "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    mes_nm         = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    tipo_lbl       = {"N":"Folha Normal","F":"Férias","R":"Rescisão",
                      "A":"Adiantamento 13°","1":"13° Salário"}.get(anomes_tipo, anomes_tipo)

    # ── PALETA ────────────────────────────────────────────────────
    C_NAVY   = colors.HexColor("#0b1f3a")
    C_DARK   = colors.HexColor("#1e3d5c")
    C_ACCENT = colors.HexColor("#2a7de1")
    C_BG     = colors.HexColor("#f8fafc")
    C_BORD   = colors.HexColor("#dde3ec")
    C_PROV   = colors.HexColor("#166534")
    C_DESC   = colors.HexColor("#991b1b")
    C_LIQOK  = colors.HexColor("#dcfce7")
    C_LIQNG  = colors.HexColor("#fee2e2")
    C_BASES  = colors.HexColor("#eff6ff")
    C_CC_SUB = colors.HexColor("#f0f2f6")

    def _st(name, **kw):
        return ParagraphStyle(name, **kw)

    st_emp_nome = _st("en",  fontName="Helvetica-Bold", fontSize=8.5,  textColor=colors.white)
    st_emp_det  = _st("ed",  fontName="Helvetica",      fontSize=7,    textColor=colors.HexColor("#c8d9ec"))
    st_col_hdr  = _st("ch",  fontName="Helvetica-Bold", fontSize=6.5,  textColor=colors.HexColor("#374151"), alignment=1)
    st_col_hdr_l= _st("chl", fontName="Helvetica-Bold", fontSize=6.5,  textColor=colors.HexColor("#374151"), alignment=0)
    st_col_hdr_r= _st("chr", fontName="Helvetica-Bold", fontSize=6.5,  textColor=colors.HexColor("#374151"), alignment=2)
    st_verba    = _st("vb",  fontName="Helvetica",      fontSize=7.5,  textColor=colors.HexColor("#1e293b"))
    st_cod      = _st("cd",  fontName="Helvetica",      fontSize=7,    textColor=colors.HexColor("#94a3b8"), alignment=1)
    st_qtd      = _st("qt",  fontName="Helvetica",      fontSize=7,    textColor=colors.HexColor("#6b7280"), alignment=1)
    st_prov     = _st("pv",  fontName="Helvetica",      fontSize=7.5,  textColor=C_PROV,  alignment=2)
    st_desc     = _st("dc",  fontName="Helvetica",      fontSize=7.5,  textColor=C_DESC,  alignment=2)
    st_zero     = _st("zr",  fontName="Helvetica",      fontSize=7.5,  textColor=colors.HexColor("#d1d5db"), alignment=2)
    st_tot_lbl  = _st("tl",  fontName="Helvetica-Bold", fontSize=7.5,  textColor=colors.HexColor("#111827"), alignment=2)
    st_tot_pv   = _st("tp",  fontName="Helvetica-Bold", fontSize=7.5,  textColor=C_PROV,  alignment=2)
    st_tot_dc   = _st("td",  fontName="Helvetica-Bold", fontSize=7.5,  textColor=C_DESC,  alignment=2)
    st_liq      = _st("lq",  fontName="Helvetica-Bold", fontSize=8,    textColor=colors.HexColor("#111827"), alignment=2)
    st_base     = _st("bs",  fontName="Helvetica",      fontSize=6.5,  textColor=colors.HexColor("#1e3a5f"))
    st_cc_hdr   = _st("cch", fontName="Helvetica-Bold", fontSize=8.5,  textColor=colors.white)
    st_cc_sub   = _st("ccs", fontName="Helvetica",      fontSize=7,    textColor=colors.HexColor("#374151"))
    st_grand    = _st("gr",  fontName="Helvetica-Bold", fontSize=9,    textColor=colors.HexColor("#111827"))
    st_stat     = _st("st",  fontName="Helvetica",      fontSize=8,    textColor=colors.HexColor("#374151"))

    W = 18.6 * cm
    COLS = [1.3*cm, 9.3*cm, 1.8*cm, 3.1*cm, 3.1*cm]   # Cód | Dsc | Qtd | Prov | Desc

    def _fdt(s):
        return f"{s[6:8]}/{s[4:6]}/{s[:4]}" if s and len(s) >= 8 else "—"

    def _fsal(v, unid):
        txt = _fmt_brl(v)
        return txt + ("/Mês" if unid in ("M","") else "/Hr")

    # ── CARREGA DADOS ─────────────────────────────────────────────
    rubricas_info = {}
    try:
        for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
            r = (supabase.table("tab_rubrica")
                 .select("cod_rubr,dsc_rubr,tp_rubr,unid_verba,tpn_inc_cp,tpn_inc_fgts,tpn_inc_irrf")
                 .eq("id_cliente", cli_id).execute())
            for row in (r.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod:
                    rubricas_info[cod] = {
                        "dsc":  str(row.get("dsc_rubr")     or f"Verba {cod:04d}"),
                        "tp":   str(row.get("tp_rubr")      or "1"),
                        "unid": str(row.get("unid_verba")   or "V"),
                        "icp":  str(row.get("tpn_inc_cp")   or ""),
                        "ift":  str(row.get("tpn_inc_fgts") or ""),
                        "iir":  str(row.get("tpn_inc_irrf") or ""),
                    }
    except Exception:
        pass
    _sys_verbs = {1:"Salário",2:"Horas Extras",30:"Férias",31:"13° Sal",
                  101:"INSS",120:"IRRF",139:"FGTS Provisionado"}
    for cod, tp in [(1,"1"),(2,"1"),(30,"1"),(31,"1"),(101,"2"),(120,"2"),(139,"2")]:
        rubricas_info.setdefault(cod, {"dsc":_sys_verbs.get(cod,f"Verba {cod:04d}"),
                                       "tp":tp,"unid":"V","icp":"","ift":"","iir":""})

    # 161-164 (Adiantamento Quinzenal) são listados em bloco próprio acima das
    # verbas informativas — não compõem os totais (já abatidos via verba 160).
    mov_data    = {}
    adiant_data = {}
    try:
        q = (supabase.table("tab_mov")
             .select("matricula,cod_verba,qtd,valor")
             .eq("id_empresa",  id_empresa)
             .eq("situacao",    "A")
             .eq("folha",       int(anomes))
             .eq("folha_tipo",  folha_tipo_mov))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        for reg in (q.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            if not mat:
                continue
            cod = int(reg.get("cod_verba") or 0)
            if cod in (161, 162, 163, 164):
                adiant_data.setdefault(mat, []).append(reg)
            else:
                mov_data.setdefault(mat, []).append(reg)
    except Exception:
        pass

    func_info = {}
    _cols_cad = "matricula,nome,nomer,dtadm,vrsalfx,cbofuncao,centrocusto,filial,codcateg"
    try:
        r = (supabase.table("tab_cad")
             .select(_cols_cad)
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .execute())
        for f in (r.data or []):
            mat = int(f.get("matricula") or 0)
            if not mat:
                continue
            nome  = str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip()
            cbo   = str(f.get("cbofuncao") or "").strip()
            cargo = f"CBO {cbo}" if cbo else "—"
            func_info[mat] = {
                "nome":   nome,
                "dtadm":  str(f.get("dtadm")      or ""),
                "sal":    int(f.get("vrsalfx")     or 0),
                "unid":   "M",
                "funcao": cargo,
                "cc":     str(f.get("centrocusto") or "000"),
                "filial": str(f.get("filial")      or ""),
                "cat":    int(f.get("codcateg")     or 0),
            }
    except Exception:
        pass
    # fallback: busca pelo menos nome para matrículas sem info
    if mov_data and not func_info:
        try:
            r2 = (supabase.table("tab_cad")
                  .select("matricula,nome,nomer,dtadm,vrsalfx,codcateg")
                  .eq("id_empresa", id_empresa)
                  .in_("matricula", list(mov_data.keys()))
                  .execute())
            for f in (r2.data or []):
                mat = int(f.get("matricula") or 0)
                if not mat:
                    continue
                nome = str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip()
                func_info[mat] = {
                    "nome":   nome,
                    "dtadm":  str(f.get("dtadm")  or ""),
                    "sal":    int(f.get("vrsalfx") or 0),
                    "unid":   "M",
                    "funcao": "—",
                    "cc":     "000",
                    "filial": "",
                    "cat":    int(f.get("codcateg") or 0),
                }
        except Exception:
            pass

    # lookup nomes de função pelo CBO
    cbos_unicos = list({fi["funcao"].replace("CBO ","") for fi in func_info.values()
                        if fi["funcao"].startswith("CBO ")})
    if cbos_unicos:
        try:
            rc = (supabase.table("tab_aux_funcao_total")
                  .select("cbo_codigo,cbo_nome")
                  .in_("cbo_codigo", cbos_unicos)
                  .execute())
            cbo_nomes = {r["cbo_codigo"]: r["cbo_nome"] for r in (rc.data or []) if r.get("cbo_codigo")}
            for fi in func_info.values():
                if fi["funcao"].startswith("CBO "):
                    cbo = fi["funcao"].replace("CBO ", "")
                    if cbo in cbo_nomes:
                        fi["funcao"] = cbo_nomes[cbo]
        except Exception:
            pass

    # Base IRRF (ja deduzida de INSS + dependentes) lida do tab_total — fonte unica de verdade
    irrf_basetabela = _irrf_basetabela_por_mat(id_empresa, anomes, folha_tipo_mov, id_cliente)

    # ── MONTA POR CC ──────────────────────────────────────────────
    cc_groups = {}
    for mat in sorted(mov_data.keys()):
        fi = func_info.get(mat, {"nome":f"Matr. {mat:06d}","dtadm":"","sal":0,
                                  "unid":"M","funcao":"—","cc":"000","filial":""})
        agg = {}
        for v in mov_data[mat]:
            cod = int(v.get("cod_verba") or 0)
            val = int(v.get("valor")     or 0)
            qtd = int(v.get("qtd")       or 0)
            ri  = rubricas_info.get(cod, {"dsc":f"Verba {cod:04d}","tp":"1",
                                           "unid":"V","icp":"","ift":"","iir":""})
            if cod in agg:
                agg[cod]["val"] += val; agg[cod]["qtd"] += qtd
            else:
                agg[cod] = {"cod":cod,"dsc":ri["dsc"],"tp":ri["tp"],
                             "unid":ri["unid"],"icp":ri["icp"],"ift":ri["ift"],
                             "iir":ri["iir"],"qtd":qtd,"val":val}

        verbas_all  = sorted(agg.values(), key=lambda x: x["cod"])
        verbas      = [v for v in verbas_all if v["cod"] <= 9900]
        verbas_info = [v for v in verbas_all if v["cod"] >  9900]
        tot_prov = sum(v["val"] for v in verbas if v["tp"] == "1")
        tot_desc = sum(v["val"] for v in verbas if v["tp"] != "1")
        liquido  = tot_prov - tot_desc

        inss_val  = agg.get(101, {}).get("val", 0)
        base_inss = sum(v["val"] for v in verbas if v["tp"]=="1" and v["icp"]=="11")
        base_irrf = irrf_basetabela.get(mat, 0)
        base_fgts = sum(v["val"] for v in verbas if v["tp"]=="1" and v["ift"] in ("11","S"))
        _aliq_fgts = 2 if int(fi.get("cat") or 0) == 103 else 8   # menor aprendiz (cat 103) recolhe 2%
        fgts_val  = agg[139]["val"] if 139 in agg else int(base_fgts * _aliq_fgts) // 100

        # Adiantamentos quinzenais (verbas 161-164) — linha acima das informativas
        adiant_list = []
        for r_ad in adiant_data.get(mat, []):
            cod_ad = int(r_ad.get("cod_verba") or 0)
            val_ad = int(r_ad.get("valor")     or 0)
            if val_ad <= 0:
                continue
            ri_ad = rubricas_info.get(cod_ad, {"dsc": f"Verba {cod_ad:04d}"})
            adiant_list.append({"cod": cod_ad,
                                "dsc": ri_ad.get("dsc") or f"Verba {cod_ad:04d}",
                                "val": val_ad})
        adiant_list.sort(key=lambda x: x["cod"])

        cc_key = fi["cc"] or "000"
        cc_groups.setdefault(cc_key, []).append({
            "mat":mat,"nome":fi["nome"],"funcao":fi["funcao"],
            "dtadm":fi["dtadm"],"sal":fi["sal"],"unid":fi["unid"],"filial":fi["filial"],
            "verbas":verbas,"verbas_info":verbas_info,
            "adiant_list": adiant_list,
            "prov":tot_prov,"desc":tot_desc,"liq":liquido,
            "b_inss":base_inss,"b_irrf":base_irrf,"b_fgts":base_fgts,"fgts":fgts_val,
        })

    # ── INFORMAÇÃO DO CÁLCULO (capturada antes do callback) ─────
    _qtd_c_rf, _dhc_rf = _get_calc_info(id_empresa, id_cliente, anomes, anomes_tipo)
    if _qtd_c_rf and _dhc_rf:
        _rc_txt = (f"Cálculo n.º {_qtd_c_rf}  —  {_dhc_rf}"
                   f"  —  emitido em {agora.strftime('%d/%m/%Y %H:%M')}")
    else:
        _rc_txt = f"Emitido em {agora.strftime('%d/%m/%Y %H:%M')}"

    # ── CABEÇALHO DE PÁGINA (canvas callback) ────────────────────
    def _draw_header(canvas, doc):
        canvas.saveState()
        xL = doc.leftMargin
        xR = xL + W
        # Linha 1: CNPJ — Razão Social (esq) | data/hora (dir)
        y1 = A4[1] - 0.55*cm
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#374151"))
        canvas.drawString(xL, y1, f"{cnpj_fmt}  —  {empresa_nm}")
        canvas.drawRightString(xR, y1, agora.strftime("%d/%m/%Y  %H:%M"))
        # Linha 2: título do relatório + competência (fonte maior)
        y2 = y1 - 0.55*cm
        periodo = f"{mes_nm.upper()}/{ano}"
        if tipo_lbl != "Folha Normal":
            periodo += f"  ·  {tipo_lbl.upper()}"
        canvas.setFont("Helvetica-Bold", 12)
        canvas.setFillColor(colors.HexColor("#0b1f3a"))
        canvas.drawString(xL, y2, f"FOLHA DE PAGAMENTO  —  {periodo}")
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#64748b"))
        canvas.drawRightString(xR, y2, f"Página  {doc.page}")
        # Separador
        canvas.setStrokeColor(colors.HexColor("#0b1f3a"))
        canvas.setLineWidth(0.8)
        canvas.line(xL, y2 - 0.28*cm, xR, y2 - 0.28*cm)
        # Rodapé: informação do cálculo
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(colors.HexColor("#64748b"))
        canvas.drawString(xL, 0.7*cm, _rc_txt)
        canvas.restoreState()

    # ── MONTA STORY ───────────────────────────────────────────────
    doc = SimpleDocTemplate(buf, pagesize=A4,
                             leftMargin=1.2*cm, rightMargin=1.2*cm,
                             topMargin=2.0*cm, bottomMargin=1.2*cm)
    story = []
    grand_prov = grand_desc = grand_liq = grand_funcs = 0

    # Exibe "Filial:" apenas se houver mais de uma filial
    _filiais_pdf = {str(f.get("filial") or "").strip()
                    for funcs_cc in cc_groups.values() for f in funcs_cc}
    _mostrar_filial = len(_filiais_pdf) > 1
    _cnpj_digits = ''.join(c for c in cnpj_fmt if c.isdigit())

    for cc_code in sorted(cc_groups.keys()):
        funcs = cc_groups[cc_code]
        if ordem == "alfa":
            funcs = sorted(funcs, key=lambda f: f["nome"].upper())
        cc_prov  = cc_desc = cc_liq = 0

        story.append(Spacer(1, 6))

        for func in funcs:
            mat = func["mat"]
            # Header azul: matrícula + nome
            st_emp_nome2 = _st("en2", fontName="Helvetica-Bold", fontSize=8.5, textColor=colors.HexColor("#0b1f3a"))
            fhdr1 = Table([[
                Paragraph(f"{mat:08d}  —  {func['nome']}", st_emp_nome2),
            ]], colWidths=[W])
            fhdr1.setStyle(TableStyle([
                ("TOPPADDING",(0,0),(-1,-1), 5),("BOTTOMPADDING",(0,0),(-1,-1), 4),
                ("LEFTPADDING",(0,0),(-1,-1), 6),
                ("LINEBELOW",(0,0),(-1,-1), 0.8, colors.HexColor("#2a7de1")),
            ]))
            # Sub-header: detalhes
            st_emp_det2 = _st("ed2", fontName="Helvetica", fontSize=7, textColor=colors.HexColor("#64748b"))
            _fil_raw = str(func['filial'] or "").strip()
            _fil_dig = ''.join(c for c in _fil_raw if c.isdigit())
            _fil_val = _fil_raw if (_fil_dig and _fil_dig.lstrip("0") and _fil_dig != _cnpj_digits) else ""
            det = (f"Admissão: {_fdt(func['dtadm'])}  ·  Função: {func['funcao']}"
                   f"  ·  Salário: {_fsal(func['sal'],func['unid'])}"
                   + (f"  ·  Filial: {_fil_val}" if _mostrar_filial and _fil_val else ""))
            fhdr2 = Table([[Paragraph(det, st_emp_det2)]], colWidths=[W])
            fhdr2.setStyle(TableStyle([
                ("BACKGROUND",(0,0),(-1,-1), colors.HexColor("#f8fafc")),
                ("TOPPADDING",(0,0),(-1,-1), 3),("BOTTOMPADDING",(0,0),(-1,-1), 3),
                ("LEFTPADDING",(0,0),(-1,-1), 6),
                ("LINEBELOW",(0,0),(-1,-1), 0.4, colors.HexColor("#dde3ec")),
            ]))

            # Linhas de verbas
            rows = [[
                Paragraph("Cód",       st_col_hdr),
                Paragraph("Descrição", st_col_hdr_l),
                Paragraph("Qtd",       st_col_hdr),
                Paragraph("Proventos", st_col_hdr_r),
                Paragraph("Descontos", st_col_hdr_r),
            ]]
            for v in func["verbas"]:
                if v["unid"] == "H" and v["qtd"] > 0:
                    qtd_txt = f"{v['qtd'] // 60}h{v['qtd'] % 60:02d}"
                elif v["unid"] == "D" and v["qtd"] > 0:
                    qtd_txt = f"{v['qtd']} dia{'s' if v['qtd'] != 1 else ''}"
                else:
                    qtd_txt = ""
                prov_txt = _fmt_brl(v["val"]) if v["tp"] == "1" else ""
                desc_txt = _fmt_brl(v["val"]) if v["tp"] != "1" else ""
                rows.append([
                    Paragraph(f"{v['cod']:04d}", st_cod),
                    Paragraph(v["dsc"],          st_verba),
                    Paragraph(qtd_txt,           st_qtd),
                    Paragraph(prov_txt,          st_prov if prov_txt else st_zero),
                    Paragraph(desc_txt,          st_desc if desc_txt else st_zero),
                ])

            n = len(rows)
            # Total
            rows.append([
                Paragraph("",                        st_tot_lbl),
                Paragraph("",                        st_tot_lbl),
                Paragraph("TOTAL",                   st_tot_lbl),
                Paragraph(_fmt_brl(func["prov"]),    st_tot_pv),
                Paragraph(_fmt_brl(func["desc"]),    st_tot_dc),
            ])
            # Líquido
            rows.append([
                Paragraph("",                        st_liq),
                Paragraph("",                        st_liq),
                Paragraph("LÍQUIDO",                 st_liq),
                Paragraph(_fmt_brl(func["liq"]),     st_liq),
                Paragraph("",                        st_liq),
            ])

            v_tbl = Table(rows, colWidths=COLS)
            ts = TableStyle([
                ("LEFTPADDING",   (0,0),(-1,-1), 3),
                ("RIGHTPADDING",  (0,0),(-1,-1), 3),
                ("TOPPADDING",    (0,0),(-1,-1), 1.5),
                ("BOTTOMPADDING", (0,0),(-1,-1), 1.5),
                ("BACKGROUND",    (0,0),(-1,0),  colors.HexColor("#f3f4f6")),
                ("LINEBELOW",     (0,0),(-1,0),  0.5, C_BORD),
                ("BOX",           (0,0),(-1,-1), 0.5, C_BORD),
                ("INNERGRID",     (0,0),(-1,-1), 0.1, C_BORD),
                ("LINEABOVE",     (0,n),(-1,n),  0.5, C_BORD),
                ("LINEABOVE",     (0,n+1),(-1,n+1), 0.8, colors.HexColor("#374151")),
                ("SPAN", (0,n),(1,n)), ("SPAN", (0,n+1),(1,n+1)),
                ("ALIGN",(0,n),(1,n+1),"RIGHT"),
            ])
            for i in range(1, n):
                if i % 2 == 0:
                    ts.add("BACKGROUND", (0,i),(-1,i), colors.HexColor("#f9fafb"))
            v_tbl.setStyle(ts)

            # Linha de bases
            st_base2 = _st("bs2", fontName="Helvetica", fontSize=6.5, textColor=colors.HexColor("#64748b"))
            b_txt = (f"BASES —  Salário: {_fsal(func['sal'],func['unid'])}   "
                     f"|   INSS: {_fmt_brl(func['b_inss'])}   "
                     f"|   IRRF: {_fmt_brl(func['b_irrf'])}   "
                     f"|   FGTS  Base: {_fmt_brl(func['b_fgts'])}  /  Valor: {_fmt_brl(func['fgts'])}")
            b_tbl = Table([[Paragraph(b_txt, st_base2)]], colWidths=[W])
            b_tbl.setStyle(TableStyle([
                ("LINEABOVE",     (0,0),(-1,-1), 0.4, C_BORD),
                ("TOPPADDING",    (0,0),(-1,-1), 3),
                ("BOTTOMPADDING", (0,0),(-1,-1), 3),
                ("LEFTPADDING",   (0,0),(-1,-1), 6),
            ]))

            elementos = [fhdr1, fhdr2, v_tbl]

            # Adiantamento Quinzenal (verbas 161-164) — acima das informativas
            if func.get("adiant_list"):
                st_ad_hdr = _st("ah", fontName="Helvetica-Bold", fontSize=6.5,
                                textColor=colors.HexColor("#9a3412"))
                st_ad_cod = _st("ac", fontName="Helvetica", fontSize=6.5,
                                textColor=colors.HexColor("#c2410c"))
                st_ad_dsc = _st("ad", fontName="Helvetica", fontSize=6.5,
                                textColor=colors.HexColor("#7c2d12"))
                st_ad_val = _st("av", fontName="Helvetica", fontSize=6.5,
                                textColor=colors.HexColor("#9a3412"), alignment=2)
                ad_rows = [[Paragraph("ADIANTAMENTO QUINZENAL", st_ad_hdr),
                            Paragraph("", st_ad_hdr),
                            Paragraph("", st_ad_hdr),
                            Paragraph("", st_ad_hdr)]]
                for ad in func["adiant_list"]:
                    ad_rows.append([
                        Paragraph(f"{ad['cod']:04d}", st_ad_cod),
                        Paragraph(ad["dsc"],          st_ad_dsc),
                        Paragraph("",                  st_ad_cod),
                        Paragraph(_fmt_brl(ad["val"]), st_ad_val),
                    ])
                COLS_AD = [COLS[0], COLS[1]+COLS[2], COLS[3], COLS[4]]
                ad_tbl = Table(ad_rows, colWidths=COLS_AD)
                ad_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0,0),(-1,-1), 3),
                    ("RIGHTPADDING",  (0,0),(-1,-1), 3),
                    ("TOPPADDING",    (0,0),(-1,-1), 1),
                    ("BOTTOMPADDING", (0,0),(-1,-1), 1),
                    ("BACKGROUND",    (0,0),(-1,0),  colors.HexColor("#fff7ed")),
                    ("LINEABOVE",     (0,0),(-1,0),  0.5, colors.HexColor("#fdba74")),
                    ("LINEBELOW",     (0,0),(-1,0),  0.3, colors.HexColor("#fdba74")),
                    ("ALIGN",         (3,0),(3,-1),  "RIGHT"),
                ]))
                elementos.append(ad_tbl)

            # Verbas informativas (cod > 9900)
            if func.get("verbas_info"):
                st_info_hdr = _st("ih", fontName="Helvetica-Bold", fontSize=6.5,
                                  textColor=colors.HexColor("#64748b"))
                st_info_cod = _st("ic", fontName="Helvetica", fontSize=6.5,
                                  textColor=colors.HexColor("#94a3b8"))
                st_info_dsc = _st("id", fontName="Helvetica", fontSize=6.5,
                                  textColor=colors.HexColor("#475569"))
                st_info_val = _st("iv", fontName="Helvetica", fontSize=6.5,
                                  textColor=colors.HexColor("#64748b"))
                info_rows = [[Paragraph("VERBAS INFORMATIVAS", st_info_hdr),
                              Paragraph("", st_info_hdr),
                              Paragraph("", st_info_hdr),
                              Paragraph("", st_info_hdr)]]
                for vi in func["verbas_info"]:
                    info_rows.append([
                        Paragraph(vi["cod"],     st_info_cod),
                        Paragraph(vi["dsc"],     st_info_dsc),
                        Paragraph(vi["qtd_fmt"], st_info_cod),
                        Paragraph(vi["val_fmt"], st_info_val),
                    ])
                COLS_INFO = [COLS[0], COLS[1]+COLS[2], COLS[3], COLS[4]]
                i_tbl = Table(info_rows, colWidths=COLS_INFO)
                i_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0,0),(-1,-1), 3),
                    ("RIGHTPADDING",  (0,0),(-1,-1), 3),
                    ("TOPPADDING",    (0,0),(-1,-1), 1),
                    ("BOTTOMPADDING", (0,0),(-1,-1), 1),
                    ("LINEABOVE",     (0,0),(-1,0),  0.5, colors.HexColor("#cbd5e1")),
                    ("LINEBELOW",     (0,0),(-1,0),  0.3, C_BORD),
                    ("ALIGN",         (2,0),(-1,-1), "RIGHT"),
                ]))
                elementos.append(i_tbl)

            elementos.extend([b_tbl, Spacer(1, 4)])
            story.append(KeepTogether(elementos))
            cc_prov += func["prov"]; cc_desc += func["desc"]; cc_liq += func["liq"]

        grand_prov += cc_prov; grand_desc += cc_desc
        grand_liq  += cc_liq;  grand_funcs += len(funcs)

    # ── TOTAIS GERAIS ─────────────────────────────────────────────
    story.append(PageBreak())
    story.append(Spacer(1, 6))

    gt_rows = [
        [Paragraph("RESUMO GERAL DA FOLHA", _st("rg", fontName="Helvetica-Bold", fontSize=10,
                    textColor=C_NAVY))],
        [Paragraph(f"{mes_nm}/{ano}  —  {tipo_lbl}  —  {sit_label}", _st("rs", fontName="Helvetica",
                    fontSize=8, textColor=colors.HexColor("#64748b")))],
    ]
    gt_hdr = Table(gt_rows, colWidths=[W])
    gt_hdr.setStyle(TableStyle([
        ("TOPPADDING",    (0,0),(-1,-1), 3),
        ("BOTTOMPADDING", (0,0),(-1,-1), 3),
        ("LEFTPADDING",   (0,0),(-1,-1), 4),
        ("LINEBELOW",     (0,-1),(-1,-1), 1.0, C_NAVY),
    ]))
    story.append(gt_hdr)
    story.append(Spacer(1, 8))

    tot_data = [
        ["Total de Funcionários",    str(grand_funcs)],
        ["Total de Proventos",        _fmt_brl(grand_prov)],
        ["Total de Descontos",        _fmt_brl(grand_desc)],
        ["Valor Líquido Total",       _fmt_brl(grand_liq)],
    ]
    _st_tl = _st("ttl", fontName="Helvetica",      fontSize=9,  textColor=colors.HexColor("#374151"))
    _st_tv = _st("ttv", fontName="Helvetica-Bold", fontSize=9,  textColor=colors.HexColor("#111827"), alignment=2)
    _st_lv = _st("tlv", fontName="Helvetica-Bold", fontSize=10, textColor=C_PROV, alignment=2)
    tot_rows = [[Paragraph(r[0], _st_tl), Paragraph(r[1], _st_tv if i < 3 else _st_lv)]
                for i, r in enumerate(tot_data)]
    tot_tbl = Table(tot_rows, colWidths=[10*cm, 6*cm])
    tot_tbl.setStyle(TableStyle([
        ("LEFTPADDING",   (0,0),(-1,-1), 6),
        ("RIGHTPADDING",  (0,0),(-1,-1), 6),
        ("TOPPADDING",    (0,0),(-1,-1), 5),
        ("BOTTOMPADDING", (0,0),(-1,-1), 5),
        ("BACKGROUND",    (0,0),(-1,-1), C_BG),
        ("LINEBELOW",     (0,0),(-1,-2), 0.3, C_BORD),
        ("LINEABOVE",     (0,-1),(-1,-1),0.5, C_NAVY),
        ("BACKGROUND",    (0,-1),(-1,-1),C_LIQOK),
        ("BOX",           (0,0),(-1,-1), 0.5, C_BORD),
    ]))
    story.append(tot_tbl)

    # ── Linha discreta: número e data do último cálculo ─────────
    try:
        r_ci = (supabase.table("tab_anomes")
                .select("qtd_calculos, data_hora_calculo, situacao")
                .eq("id_empresa", int(id_empresa))
                .eq("ano_mes",    int(anomes))
                .eq("tipo",       anomes_tipo)
                .limit(1).execute())
        row = (r_ci.data or [{}])[0]
        n_calc = int(row.get("qtd_calculos") or 0)
        dhc    = str(row.get("data_hora_calculo") or "")
        dt_fmt = ""
        if dhc:
            try:
                dt_fmt = datetime.fromisoformat(
                    dhc.replace("T", " ").split(".")[0]
                ).strftime("%d/%m/%Y %H:%M")
            except Exception:
                s = "".join(filter(str.isdigit, dhc))
                if len(s) >= 12:
                    dt_fmt = f"{s[6:8]}/{s[4:6]}/{s[:4]} {s[8:10]}:{s[10:12]}"
        if n_calc > 0 and dt_fmt:
            st_calc = _st("ucl", fontName="Helvetica-Oblique", fontSize=6.5,
                          textColor=colors.HexColor("#94a3b8"), alignment=2)
            story.append(Spacer(1, 4))
            story.append(Paragraph(
                f"Último cálculo: N° {n_calc} em {dt_fmt}", st_calc))
    except Exception:
        pass

    doc.build(story, onFirstPage=_draw_header, onLaterPages=_draw_header)
    buf.seek(0)
    return buf


@app.route("/relatorio_folha_pdf")
def relatorio_folha_pdf():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    if not anomes:
        return "Nenhuma folha ativa.", 400

    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(str(session.get("cnpj_empresa") or ""))
    versao     = str(session.get("versao") or "")

    sit_map   = {"A":"Aberta","C":"Calculada","F":"Fechada"}
    anomes_sit = str(session.get("anomes_sit") or "")
    sit_label  = f"Situação: {sit_map.get(anomes_sit, anomes_sit)}"
    nome_usuario = str(session.get("nome") or "")

    from flask import request as _req
    ordem = _req.args.get("ordem") or _get_pref("ordem_rel", "mat")
    buf = _gerar_folha_pagamento_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                                      empresa_nm, cnpj_fmt, versao, sit_label,
                                      nome_usuario, ordem=ordem)
    from flask import make_response
    ano, mes = anomes[:4], anomes[4:6]
    nome_arq = f"FolhaPagamento_{empresa_nm[:20].replace(' ','_')}_{ano}{mes}.pdf"
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{nome_arq}"'
    return resp


# =========================================================
# CONTRACHEQUE — CONFIGURAÇÃO + PDF
# =========================================================

def _gerar_contracheque_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                              empresa_nm, cnpj_fmt, modo="1",
                              matriculas_sel=None, com_assinatura=True):
    from reportlab.pdfgen.canvas import Canvas
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from io import BytesIO
    from datetime import datetime

    buf            = BytesIO()
    W_page, H_page = A4
    agora          = datetime.now()
    ano, mes       = anomes[:4], anomes[4:6]
    meses_pt       = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                      "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    mes_nm         = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    tipo_lbl       = {"N":"Folha Normal","F":"Férias","R":"Rescisão",
                      "A":"Adiantamento 13°","1":"13° Salário"}.get(anomes_tipo, anomes_tipo)
    anomes_fmt     = f"{mes_nm.upper()}/{ano}"
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"

    # ── Número e data do último cálculo (mesmo para todos os stubs) ──
    n_calc_folha = 0
    dt_calc_folha = ""
    try:
        r_ci = (supabase.table("tab_anomes")
                .select("qtd_calculos, data_hora_calculo")
                .eq("id_empresa", int(id_empresa))
                .eq("ano_mes",    int(anomes))
                .eq("tipo",       anomes_tipo)
                .limit(1).execute())
        row = (r_ci.data or [{}])[0]
        n_calc_folha = int(row.get("qtd_calculos") or 0)
        dhc = str(row.get("data_hora_calculo") or "")
        if dhc:
            try:
                dt_calc_folha = datetime.fromisoformat(
                    dhc.replace("T", " ").split(".")[0]
                ).strftime("%d/%m/%Y %H:%M")
            except Exception:
                s = "".join(filter(str.isdigit, dhc))
                if len(s) >= 12:
                    dt_calc_folha = f"{s[6:8]}/{s[4:6]}/{s[:4]} {s[8:10]}:{s[10:12]}"
    except Exception:
        pass

    C_NAVY   = colors.HexColor("#0b1f3a")
    C_BORD   = colors.HexColor("#dde3ec")
    C_PROV   = colors.HexColor("#166534")
    C_DESC   = colors.HexColor("#991b1b")
    C_LIQBG  = colors.HexColor("#dcfce7")
    C_BASEBG = colors.HexColor("#eff6ff")

    def _fdt(s):
        return f"{s[6:8]}/{s[4:6]}/{s[:4]}" if s and len(s) >= 8 else "—"

    def _fbrl(c, dec=2):
        # Valor formatado em padrão BR, SEM o prefixo "R$"
        return f"{c/100:,.{dec}f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _fqtd(qtd, unid):
        if qtd == 999999:          # qtd especial = ignorar (item 5)
            return ""
        if unid == "H" and qtd > 0:
            return f"{qtd // 60}h{qtd % 60:02d}"
        if unid == "D" and qtd > 0:
            return f"{qtd} dia{'s' if qtd != 1 else ''}"
        return ""

    # ── Carrega rubricas ──────────────────────────────────
    rubricas_info = {}
    try:
        for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
            r = (supabase.table("tab_rubrica")
                 .select("cod_rubr,dsc_rubr,tp_rubr,unid_verba,tpn_inc_cp,tpn_inc_fgts,tpn_inc_irrf")
                 .eq("id_cliente", cli_id).execute())
            for row in (r.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod:
                    rubricas_info[cod] = {
                        "dsc":  str(row.get("dsc_rubr")     or f"Verba {cod:04d}"),
                        "tp":   str(row.get("tp_rubr")      or "1"),
                        "unid": str(row.get("unid_verba")   or "V"),
                        "icp":  str(row.get("tpn_inc_cp")   or ""),
                        "ift":  str(row.get("tpn_inc_fgts") or ""),
                        "iir":  str(row.get("tpn_inc_irrf") or ""),
                    }
    except Exception:
        pass
    _sys_verbs = {1:"Salário",2:"Horas Extras",30:"Férias",31:"13° Sal",
                  101:"INSS",120:"IRRF",139:"FGTS Provisionado"}
    for cod, tp in [(1,"1"),(2,"1"),(30,"1"),(31,"1"),(101,"2"),(120,"2"),(139,"2")]:
        rubricas_info.setdefault(cod, {"dsc":_sys_verbs.get(cod,f"Verba {cod:04d}"),
                                       "tp":tp,"unid":"V","icp":"","ift":"","iir":""})

    # ── Carrega movimentos ────────────────────────────────
    # 161-164 (Adiantamento Quinzenal) são exibidos em linha própria antes das bases
    # — não entram no rateio de proventos/descontos (já abatidos via verba 160).
    mov_data    = {}
    adiant_data = {}
    try:
        q = (supabase.table("tab_mov")
             .select("matricula,cod_verba,qtd,valor")
             .eq("id_empresa",  id_empresa)
             .eq("situacao",    "A")
             .eq("folha",       int(anomes))
             .eq("folha_tipo",  folha_tipo_mov))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        for reg in (q.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            if not mat:
                continue
            cod = int(reg.get("cod_verba") or 0)
            if cod in (161, 162, 163, 164):
                adiant_data.setdefault(mat, []).append(reg)
            else:
                mov_data.setdefault(mat, []).append(reg)
    except Exception:
        pass

    # ── Carrega funcionários ──────────────────────────────
    func_info = {}
    try:
        r = (supabase.table("tab_cad")
             .select("matricula,nome,nomer,dtadm,vrsalfx,cbofuncao,centrocusto,filial,codcateg")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .execute())
        for f in (r.data or []):
            mat = int(f.get("matricula") or 0)
            if not mat:
                continue
            nome = str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip()
            cbo  = str(f.get("cbofuncao") or "").strip()
            func_info[mat] = {
                "nome":   nome,
                "dtadm":  str(f.get("dtadm")      or ""),
                "sal":    int(f.get("vrsalfx")     or 0),
                "funcao": f"CBO {cbo}" if cbo else "—",
                "cc":     str(f.get("centrocusto") or "000"),
                "filial": str(f.get("filial")      or ""),
                "cat":    int(f.get("codcateg")     or 0),
            }
    except Exception:
        pass
    cbos_unicos = list({fi["funcao"].replace("CBO ","") for fi in func_info.values()
                        if fi["funcao"].startswith("CBO ")})
    if cbos_unicos:
        try:
            rc = (supabase.table("tab_aux_funcao_total")
                  .select("cbo_codigo,cbo_nome")
                  .in_("cbo_codigo", cbos_unicos).execute())
            cbo_nomes = {r["cbo_codigo"]: r["cbo_nome"] for r in (rc.data or []) if r.get("cbo_codigo")}
            for fi in func_info.values():
                if fi["funcao"].startswith("CBO "):
                    cbo = fi["funcao"].replace("CBO ","")
                    if cbo in cbo_nomes:
                        fi["funcao"] = cbo_nomes[cbo]
        except Exception:
            pass

    # Base IRRF (ja deduzida de INSS + dependentes) lida do tab_total — fonte unica de verdade
    irrf_basetabela = _irrf_basetabela_por_mat(id_empresa, anomes, folha_tipo_mov, id_cliente)

    # ── Monta lista de funcionários com verbas ────────────
    all_funcs = []
    for mat in sorted(mov_data.keys()):
        fi = func_info.get(mat, {"nome":f"Matr. {mat:06d}","dtadm":"","sal":0,
                                  "funcao":"—","cc":"000","filial":""})
        agg = {}
        for v in mov_data[mat]:
            cod = int(v.get("cod_verba") or 0)
            val = int(v.get("valor")     or 0)
            qtd = int(v.get("qtd")       or 0)
            ri  = rubricas_info.get(cod, {"dsc":f"Verba {cod:04d}","tp":"1",
                                           "unid":"V","icp":"","ift":"","iir":""})
            if cod in agg:
                agg[cod]["val"] += val; agg[cod]["qtd"] += qtd
            else:
                agg[cod] = {"cod":cod,"dsc":ri["dsc"],"tp":ri["tp"],
                             "unid":ri["unid"],"icp":ri["icp"],"ift":ri["ift"],
                             "iir":ri["iir"],"qtd":qtd,"val":val}
        verbas_all  = sorted(agg.values(), key=lambda x: x["cod"])
        verbas      = [v for v in verbas_all if v["cod"] <= 9900]
        verbas_info = [v for v in verbas_all if v["cod"] >  9900]
        tot_prov = sum(v["val"] for v in verbas if v["tp"] == "1")
        tot_desc = sum(v["val"] for v in verbas if v["tp"] != "1")
        liquido  = tot_prov - tot_desc
        inss_val  = agg.get(101,{}).get("val",0)
        base_inss = sum(v["val"] for v in verbas if v["tp"]=="1" and v["icp"]=="11")
        base_irrf = irrf_basetabela.get(mat, 0)
        base_fgts = sum(v["val"] for v in verbas if v["tp"]=="1" and v["ift"] in ("11","S"))
        _aliq_fgts = 2 if int(fi.get("cat") or 0) == 103 else 8   # menor aprendiz (cat 103) recolhe 2%
        fgts_val  = agg[139]["val"] if 139 in agg else int(base_fgts * _aliq_fgts) // 100
        # Adiantamentos quinzenais (verbas 161-164) — linha própria antes das bases
        adiant_list = []
        for r_ad in adiant_data.get(mat, []):
            cod_ad = int(r_ad.get("cod_verba") or 0)
            val_ad = int(r_ad.get("valor")     or 0)
            if val_ad <= 0:
                continue
            ri_ad = rubricas_info.get(cod_ad, {"dsc": f"Verba {cod_ad:04d}"})
            adiant_list.append({"cod": cod_ad,
                                "dsc": ri_ad.get("dsc") or f"Verba {cod_ad:04d}",
                                "val": val_ad})
        adiant_list.sort(key=lambda x: x["cod"])

        all_funcs.append({
            "mat":mat,"nome":fi["nome"],"funcao":fi["funcao"],
            "dtadm":fi["dtadm"],"sal":fi["sal"],"filial":fi["filial"],
            "verbas":verbas,"verbas_info":verbas_info,
            "adiant_list": adiant_list,
            "prov":tot_prov,"desc":tot_desc,"liq":liquido,
            "b_inss":base_inss,"b_irrf":base_irrf,"b_fgts":base_fgts,"fgts":fgts_val,
        })

    # Filtra por funcionários selecionados (item 1)
    if matriculas_sel:
        all_funcs = [f for f in all_funcs if f["mat"] in matriculas_sel]
    # Remove funcionários sem proventos nem descontos (item 6)
    all_funcs = [f for f in all_funcs if f["prov"] > 0 or f["desc"] > 0]

    # ── Dimensões de página ───────────────────────────────
    ML = 1.0*cm; MR = 1.0*cm; MT = 0.8*cm; MB = 0.8*cm
    W_stub   = W_page - ML - MR
    H_usable = H_page - MT - MB
    CUT_GAP  = 0.5*cm
    H_half   = (H_usable - CUT_GAP) / 2

    # ── Heights por modo (compact=True → meia-página) ─────
    ROWS = {
        False: {"hdr":42,"emp":26,"col":13,"verb":12,"tot":13,
                "liq":16,"info":10,"base":12,"sig":44},
        True:  {"hdr":34,"emp":20,"col":11,"verb":10,"tot":11,
                "liq":13,"info":9, "base":10,"sig":36},
    }

    def stub_height(func_data, compact, com_sig=True):
        R     = ROWS[compact]
        sig_h = R["sig"] if com_sig else 6
        n_info = (1 + len(func_data["verbas_info"])) if func_data["verbas_info"] else 0
        h_adiant = R["base"] if func_data.get("adiant_list") else 0
        return (R["hdr"] + R["emp"] + R["col"] +
                len(func_data["verbas"]) * R["verb"] +
                R["tot"] + R["liq"] + n_info * R["info"] +
                h_adiant + R["base"] + sig_h)

    _qtd_c_cc, _dhc_cc = _get_calc_info(id_empresa, id_cliente, anomes, anomes_tipo)
    _emitido_cc = agora.strftime("%d/%m/%Y %H:%M")
    if _qtd_c_cc and _dhc_cc:
        _calc_rodape = f"Cálculo n.º {_qtd_c_cc}  —  {_dhc_cc}  —  emitido em {_emitido_cc}"
    else:
        _calc_rodape = f"Emitido em {_emitido_cc}"

    c = Canvas(buf, pagesize=A4)

    def _draw_calc_footer():
        c.saveState()
        c.setFont("Helvetica", 7)
        c.setFillColor(colors.HexColor("#64748b"))
        c.drawString(ML, 0.7*cm, _calc_rodape)
        c.restoreState()

    def finish_page():
        _draw_calc_footer()
        c.showPage()

    def hline(x0, x1, y, color, lw=0.3):
        c.saveState()
        c.setStrokeColor(color)
        c.setLineWidth(lw)
        c.line(x0, y, x1, y)
        c.restoreState()

    def vline(x, y0, y1, color, lw=0.2):
        c.saveState()
        c.setStrokeColor(color)
        c.setLineWidth(lw)
        c.line(x, y0, x, y1)
        c.restoreState()

    def draw_cut_line(y_center):
        c.saveState()
        c.setStrokeColor(colors.HexColor("#94a3b8"))
        c.setLineWidth(0.5)
        c.setDash([3, 5], 0)
        c.line(ML - 0.2*cm, y_center, W_page - MR + 0.2*cm, y_center)
        c.setDash([], 0)
        c.setFont("Helvetica", 7)
        c.setFillColor(colors.HexColor("#94a3b8"))
        c.drawCentredString(W_page / 2, y_center + 2.5, "✂")
        c.restoreState()

    def draw_stub(x0, y_top, w, func_data, compact=False, label_via=None, com_sig=True):
        R   = ROWS[compact]
        PAD = 3 if compact else 5

        FS_TIT = 9   if compact else 11
        FS_EMP = 8   if compact else 9
        FS_DET = 6   if compact else 7
        FS_COL = 5.5 if compact else 6.5
        FS_VRB = 7   if compact else 8
        FS_TOT = 7   if compact else 8
        FS_LIQ = 7.5 if compact else 9
        FS_BSE = 5.5 if compact else 6.5
        FS_SIG = 7   if compact else 8

        W_COD = 0.12 * w
        W_QTD = 0.10 * w
        W_VAL = 0.21 * w
        W_DSC = w - W_COD - W_QTD - 2*W_VAL

        xCOD = x0
        xDSC = x0 + W_COD
        xQTD = x0 + W_COD + W_DSC
        xPRV = x0 + W_COD + W_DSC + W_QTD
        xDSK = x0 + W_COD + W_DSC + W_QTD + W_VAL
        xEND = x0 + w

        y       = y_top
        y_start = y_top
        C_TXT   = colors.HexColor("#111827")
        C_GRAY  = colors.HexColor("#374151")
        C_LGRAY = colors.HexColor("#6b7280")
        C_LINE  = colors.HexColor("#374151")
        HPAD    = 8 if compact else 12   # padding interno do cabeçalho

        def fill_row(row_h, fill_color):
            c.setFillColor(fill_color)
            c.rect(x0, y - row_h, w, row_h, fill=1, stroke=0)

        def text_at(text, fx, fy, font, size, fill, align="left"):
            c.setFont(font, size)
            c.setFillColor(fill)
            if align == "right":
                c.drawRightString(fx, fy, text)
            elif align == "center":
                c.drawCentredString(fx, fy, text)
            else:
                c.drawString(fx, fy, text)

        # ── 1. Cabeçalho — fundo branco, 3 linhas (items 1, 2, 3, 4) ──
        fill_row(R["hdr"], colors.white)
        hline(x0, xEND, y,            C_LINE, 1.0)   # borda superior
        hline(x0, xEND, y - R["hdr"], C_LINE, 1.4)   # borda inferior

        # linha 1 (topo): empresa (esq) | "CONTRACHEQUE" (dir)
        # baseline precisa estar abaixo do cap-height para não transbordar a borda
        y1 = y - FS_TIT - 4          # 4pt gap acima do cap-height
        text_at(empresa_nm[:46], x0+HPAD, y1, "Helvetica-Bold", FS_TIT, C_TXT)
        text_at("CONTRACHEQUE", xEND-HPAD, y1, "Helvetica-Bold", FS_TIT, C_TXT, "right")

        # linha 2 (meio): CNPJ (esq) | mês/ano em destaque (dir)
        y2 = y - R["hdr"] + FS_EMP + 6
        text_at(f"CNPJ: {cnpj_fmt}", x0+HPAD, y2, "Helvetica", FS_DET, C_LGRAY)
        tipo_hdr = "" if anomes_tipo == "N" else f"  ·  {tipo_lbl}"
        text_at(f"{anomes_fmt}{tipo_hdr}", xEND-HPAD, y2,
                "Helvetica-Bold", FS_EMP + (0 if compact else 1), C_TXT, "right")

        # linha 3 (base): VIA label (dir)
        if label_via:
            y3 = y - R["hdr"] + FS_DET + 2
            text_at(f"VIA {label_via}", xEND-HPAD, y3,
                    "Helvetica", FS_DET, C_LGRAY, "right")
        y -= R["hdr"]

        # ── 2. Dados do funcionário — fundo branco (item 3) ─────────
        fill_row(R["emp"], colors.white)
        y_e1 = y - R["emp"] + R["emp"] * 0.60
        text_at(f"{func_data['mat']:08d}  —  {func_data['nome']}",
                x0+PAD, y_e1, "Helvetica-Bold", FS_EMP, C_TXT)
        y_e2 = y - R["emp"] + 4
        det = (f"Admissão: {_fdt(func_data['dtadm'])}   |   "
               f"Função: {func_data['funcao'][:28]}   |   "
               f"Salário: {_fbrl(func_data['sal'])}/Mês")
        text_at(det, x0+PAD, y_e2, "Helvetica", FS_DET, C_LGRAY)
        hline(x0, xEND, y - R["emp"], C_LINE, 0.6)
        y -= R["emp"]

        # ── 3. Cabeçalho colunas ────────────────────────────────────
        fill_row(R["col"], colors.HexColor("#f3f4f6"))
        y_c = y - R["col"] + 3
        text_at("CÓD",       xCOD+W_COD/2,   y_c, "Helvetica-Bold", FS_COL, C_GRAY, "center")
        text_at("DESCRIÇÃO", xDSC+PAD,        y_c, "Helvetica-Bold", FS_COL, C_GRAY)
        text_at("QTD",       xQTD+W_QTD/2,   y_c, "Helvetica-Bold", FS_COL, C_GRAY, "center")
        text_at("PROVENTOS", xPRV+W_VAL-PAD, y_c, "Helvetica-Bold", FS_COL, C_GRAY, "right")
        text_at("DESCONTOS", xDSK+W_VAL-PAD, y_c, "Helvetica-Bold", FS_COL, C_GRAY, "right")
        hline(x0, xEND, y - R["col"], C_LINE, 0.5)
        y -= R["col"]

        # ── 4. Verbas — sem cores de fundo (item 3) ─────────────────
        for v in func_data["verbas"]:
            fill_row(R["verb"], colors.white)
            y_v = y - R["verb"] + 3
            text_at(f"{v['cod']:04d}", xCOD+W_COD/2, y_v, "Helvetica", FS_COL,
                    C_LGRAY, "center")
            text_at(v["dsc"][:46], xDSC+PAD, y_v, "Helvetica", FS_VRB, C_TXT)
            text_at(_fqtd(v["qtd"],v["unid"]), xQTD+W_QTD/2, y_v, "Helvetica", FS_COL,
                    C_LGRAY, "center")
            if v["tp"] == "1":
                text_at(_fbrl(v["val"]), xPRV+W_VAL-PAD, y_v, "Helvetica", FS_VRB,
                        C_TXT, "right")
            else:
                text_at(_fbrl(v["val"]), xDSK+W_VAL-PAD, y_v, "Helvetica", FS_VRB,
                        C_TXT, "right")
            hline(x0, xEND, y - R["verb"], colors.HexColor("#e5e7eb"), 0.2)
            y -= R["verb"]

        # ── 4B. Adiantamentos Quinzenais (verbas 161-164) ───────────
        if func_data.get("adiant_list"):
            hline(x0, xEND, y, C_LINE, 0.5)
            fill_row(R["base"], colors.HexColor("#fff7ed"))
            partes = [f"{a['cod']:04d} {a['dsc'][:24]}: {_fbrl(a['val'])}"
                      for a in func_data["adiant_list"]]
            adiant_txt = "Adiantamento Quinzenal — " + "   |   ".join(partes)
            text_at(adiant_txt, xCOD+PAD, y - R["base"] + 3, "Helvetica",
                    FS_BSE, colors.HexColor("#9a3412"))
            hline(x0, xEND, y - R["base"], C_LINE, 0.3)
            y -= R["base"]

        # ── 5. Bases — logo abaixo das verbas ───────────────────────
        hline(x0, xEND, y, C_LINE, 0.7)
        fill_row(R["base"], colors.HexColor("#f9fafb"))
        bases_txt = (f"Base INSS: {_fbrl(func_data['b_inss'])}   "
                     f"|   Base IRRF: {_fbrl(func_data['b_irrf'])}   "
                     f"|   Base FGTS: {_fbrl(func_data['b_fgts'])}   "
                     f"|   FGTS: {_fbrl(func_data['fgts'])}")
        text_at(bases_txt, xCOD+PAD, y - R["base"] + 3, "Helvetica", FS_BSE, C_LGRAY)
        hline(x0, xEND, y - R["base"], C_LINE, 0.6)
        y -= R["base"]

        # ── 6. Total ─────────────────────────────────────────────────
        fill_row(R["tot"], colors.HexColor("#f3f4f6"))
        y_t = y - R["tot"] + 3
        text_at("TOTAL",             xDSC+PAD,        y_t, "Helvetica-Bold", FS_TOT, C_GRAY)
        text_at(_fbrl(func_data["prov"]), xPRV+W_VAL-PAD, y_t,
                "Helvetica-Bold", FS_TOT, C_TXT, "right")
        text_at(_fbrl(func_data["desc"]), xDSK+W_VAL-PAD, y_t,
                "Helvetica-Bold", FS_TOT, C_TXT, "right")
        y -= R["tot"]

        # ── 7. Líquido ───────────────────────────────────────────────
        hline(x0, xEND, y, C_LINE, 1.2)
        fill_row(R["liq"], colors.HexColor("#f3f4f6"))
        y_l = y - R["liq"] + 3
        text_at("LÍQUIDO A RECEBER", xDSC+PAD, y_l, "Helvetica-Bold", FS_LIQ, C_TXT)
        text_at(_fbrl(func_data["liq"]), xQTD+W_QTD-PAD, y_l,
                "Helvetica-Bold", FS_LIQ, C_TXT, "right")
        hline(x0, xEND, y - R["liq"], C_LINE, 1.0)
        y -= R["liq"]

        # ── 8. Verbas informativas ───────────────────────────────────
        if func_data.get("verbas_info"):
            fill_row(R["info"], colors.white)
            text_at("VERBAS INFORMATIVAS", xDSC+PAD, y - R["info"] + 3,
                    "Helvetica-Bold", FS_COL, C_LGRAY)
            hline(x0, xEND, y - R["info"], colors.HexColor("#e5e7eb"), 0.3)
            y -= R["info"]
            for vi in func_data["verbas_info"]:
                fill_row(R["info"], colors.white)
                y_i = y - R["info"] + 2
                text_at(f"{vi['cod']:04d}", xCOD+W_COD/2, y_i, "Helvetica", FS_COL-0.5,
                        C_LGRAY, "center")
                text_at(vi["dsc"][:46], xDSC+PAD, y_i, "Helvetica", FS_COL, C_GRAY)
                text_at(_fbrl(vi["val"]), xPRV+W_VAL-PAD, y_i, "Helvetica", FS_COL,
                        C_GRAY, "right")
                hline(x0, xEND, y - R["info"], colors.HexColor("#e5e7eb"), 0.2)
                y -= R["info"]

        # ── 9. Assinatura — só funcionário, opcional (item 5) ───────
        sig_h = R["sig"] if com_sig else 6
        fill_row(sig_h, colors.white)
        if com_sig:
            sig_ctr   = x0 + w / 2
            sig_span  = w * 0.36
            sig_y_l   = y - sig_h + 14
            sig_y_n   = y - sig_h + 5
            data_ger  = agora.strftime("%d/%m/%Y  %H:%M")
            hline(sig_ctr - sig_span, sig_ctr + sig_span, sig_y_l, C_LINE, 0.5)
            text_at(func_data["nome"][:60], sig_ctr, sig_y_n,
                    "Helvetica", FS_SIG, C_LGRAY, "center")
            text_at(f"Gerado em {data_ger}", xEND-PAD, y - sig_h + 2,
                    "Helvetica", FS_BSE-0.5, C_LGRAY, "right")
            if n_calc_folha > 0 and dt_calc_folha:
                text_at(f"Cálculo N° {n_calc_folha} em {dt_calc_folha}",
                        x0+PAD, y - sig_h + 2,
                        "Helvetica-Oblique", FS_BSE-0.5, C_LGRAY, "left")
        y -= sig_h

        # ── Borda externa ────────────────────────────────────────────
        used_h = y_start - y
        c.saveState()
        c.setStrokeColor(C_LINE)
        c.setLineWidth(0.8)
        c.rect(x0, y_start - used_h, w, used_h, fill=0, stroke=1)
        # linhas verticais na área de verbas
        n_vb = len(func_data["verbas"])
        if n_vb > 0:
            v_top = y_start - R["hdr"] - R["emp"] - R["col"]
            v_bot = v_top - n_vb * R["verb"]
            c.setLineWidth(0.15)
            c.setStrokeColor(colors.HexColor("#d1d5db"))
            for xv in [xDSC, xQTD, xPRV, xDSK]:
                c.line(xv, v_bot, xv, v_top)
        c.restoreState()

    # ── Posições de página ────────────────────────────────
    y_full    = H_page - MT
    y_top_top = H_page - MT
    y_top_bot = MB + H_half
    y_cut     = MB + H_half + CUT_GAP / 2

    cs = com_assinatura   # alias curto

    if modo == "1":
        for func in all_funcs:
            draw_stub(ML, y_full, W_stub, func, compact=False, com_sig=cs)
            finish_page()

    elif modo == "2S":
        for func in all_funcs:
            h_est = stub_height(func, compact=True, com_sig=cs)
            if h_est > H_half - 4:
                draw_stub(ML, y_full, W_stub, func, compact=False, com_sig=cs)
            else:
                draw_stub(ML, y_top_top, W_stub, func, compact=True,
                          label_via="EMPRESA", com_sig=cs)
                draw_cut_line(y_cut)
                draw_stub(ML, y_top_bot, W_stub, func, compact=True,
                          label_via="FUNCIONÁRIO", com_sig=cs)
            finish_page()

    elif modo == "2D":
        i = 0
        while i < len(all_funcs):
            func1 = all_funcs[i]
            h1 = stub_height(func1, compact=True, com_sig=cs)
            if h1 > H_half - 4:
                draw_stub(ML, y_full, W_stub, func1, compact=False, com_sig=cs)
                finish_page()
                i += 1
            else:
                j = i + 1
                paired = False
                while j < len(all_funcs):
                    func2 = all_funcs[j]
                    h2 = stub_height(func2, compact=True, com_sig=cs)
                    if h2 <= H_half - 4:
                        draw_stub(ML, y_top_top, W_stub, func1, compact=True, com_sig=cs)
                        draw_cut_line(y_cut)
                        draw_stub(ML, y_top_bot, W_stub, func2, compact=True, com_sig=cs)
                        finish_page()
                        all_funcs.pop(j)
                        paired = True
                        break
                    j += 1
                if not paired:
                    draw_stub(ML, y_full, W_stub, func1, compact=False, com_sig=cs)
                    finish_page()
                i += 1

    c.save()
    buf.seek(0)
    return buf


@app.route("/contracheque")
def contracheque():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    empresa_nm  = str(session.get("empresa_info") or "")
    if not anomes:
        return redirect("/menu")
    meses_pt = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    ano, mes  = anomes[:4], anomes[4:6]
    mes_nm    = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    tipo_lbl  = {"N":"Folha Normal","F":"Férias","R":"Rescisão",
                 "A":"Adiantamento 13°","1":"13° Salário"}.get(anomes_tipo, anomes_tipo)
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"

    # Busca funcionários com movimento no período (para seletor)
    funcionarios = []
    try:
        q = (supabase.table("tab_mov")
             .select("matricula")
             .eq("id_empresa", id_empresa)
             .eq("situacao",   "A")
             .eq("folha",      int(anomes))
             .eq("folha_tipo", folha_tipo_mov))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        mats = sorted({int(r["matricula"]) for r in (q.execute().data or [])
                       if r.get("matricula")})
        if mats:
            r2 = (supabase.table("tab_cad")
                  .select("matricula,nome,nomer")
                  .eq("id_empresa", id_empresa)
                  .in_("matricula", mats)
                  .execute())
            nomes_map = {int(r["matricula"]): str(r.get("nome") or r.get("nomer")
                         or f"Matr. {r['matricula']:06d}").strip()
                         for r in (r2.data or []) if r.get("matricula")}
            for mat in mats:
                funcionarios.append({
                    "mat":     mat,
                    "mat_fmt": f"{mat:08d}",
                    "nome":    nomes_map.get(mat, f"Matr. {mat:06d}"),
                })
    except Exception:
        pass

    pasta_salvar = (f"C:\\Folha10-Simples_Contracheque\\{ano}\\{ano}-{mes}\\{int(id_empresa):06d}"
                    if anomes else "")
    return render_template(
        "F10_Contracheque.html",
        versao       = ler_versao(),
        nome         = session.get("nome", ""),
        empresa      = empresa_nm,
        anomes_fmt   = f"{mes_nm} / {ano}",
        tipo_lbl     = tipo_lbl,
        funcionarios = funcionarios,
        pasta_salvar = pasta_salvar,
    )


@app.route("/contracheque_pdf")
def contracheque_pdf():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    if not anomes:
        return "Nenhuma folha ativa.", 400
    empresa_nm  = str(session.get("empresa_info") or "")
    cnpj_fmt    = _fmt_cnpj(str(session.get("cnpj_empresa") or ""))
    modo           = request.args.get("modo", "1")
    if modo not in ("1","2S","2D"):
        modo = "1"
    mats_str       = request.args.getlist("mat")
    matriculas_sel = [int(m) for m in mats_str if m.isdigit()] if mats_str else []
    com_assinatura = request.args.get("assinatura", "1") != "0"

    from flask import make_response
    ano, mes  = anomes[:4], anomes[4:6]
    nome_arq  = f"Contracheque_{empresa_nm[:20].replace(' ','_')}_{ano}{mes}.pdf"

    # ── Gravar um arquivo por funcionário ────────────────────────────
    salvar_ind = request.args.get("salvar_ind", "0") == "1" and modo in ("1", "2S")
    if salvar_ind:
        try:
            ts           = datetime.now().strftime("%Y%m%d_as_%H%M%S")
            cnpj_digits  = "".join(c for c in cnpj_fmt if c.isdigit())
            anomes_pasta = f"{ano}-{mes}"
            pasta        = os.path.join("C:\\Folha10-Simples_Contracheque",
                                        ano, anomes_pasta, f"{int(id_empresa):06d}")
            os.makedirs(pasta, exist_ok=True)

            folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"
            q = (supabase.table("tab_mov")
                 .select("matricula")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao",   "A")
                 .eq("folha",      int(anomes))
                 .eq("folha_tipo", folha_tipo_mov))
            if id_cliente:
                q = q.eq("id_cliente", id_cliente)
            mats_all = sorted({int(r["matricula"]) for r in (q.execute().data or [])
                               if r.get("matricula")})
            if matriculas_sel:
                sel_set  = set(matriculas_sel)
                mats_all = [m for m in mats_all if m in sel_set]

            saved = []
            erros = []
            for mat in mats_all:
                try:
                    buf_i    = _gerar_contracheque_pdf(id_empresa, anomes, anomes_tipo,
                                                       id_cliente, empresa_nm, cnpj_fmt,
                                                       modo, [mat], com_assinatura)
                    pdf_i    = buf_i.read()
                    if len(pdf_i) < 3000:
                        continue  # sem conteúdo (zero proventos/descontos)
                    nome_f   = (f"Folha10_Contracheque_CNPJ_{cnpj_digits}"
                                f"_Folha_{anomes}_Matricula_{mat:06d}_em_{ts}.pdf")
                    caminho  = os.path.join(pasta, nome_f)
                    with open(caminho, "wb") as fh:
                        fh.write(pdf_i)
                    saved.append((mat, caminho))
                except Exception as e_m:
                    erros.append(f"Matrícula {mat:06d}: {e_m}")

            linhas = "".join(
                f'<div class="frow"><span class="mat">{m:06d}</span>'
                f'<span class="pth">{c}</span></div>'
                for m, c in saved)
            erros_html = "".join(f'<div class="err">{e}</div>' for e in erros)
            html_ind = f"""<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">
<title>Contracheques gravados</title>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;600&family=IBM+Plex+Mono:wght@400&display=swap" rel="stylesheet">
<style>
*{{box-sizing:border-box;margin:0;padding:0}}
body{{font-family:'IBM Plex Sans',sans-serif;background:#f0f2f6;padding:40px 24px}}
.box{{background:#fff;border:1px solid #dde3ec;border-radius:12px;padding:32px 36px;max-width:700px;margin:0 auto}}
h2{{font-size:18px;font-weight:600;color:#0b1f3a;margin-bottom:6px}}
.sub{{font-size:13px;color:#64748b;margin-bottom:20px}}
.frow{{display:flex;gap:14px;padding:7px 0;border-bottom:1px solid #f1f5f9;align-items:baseline}}
.frow:last-of-type{{border-bottom:none}}
.mat{{font-family:'IBM Plex Mono',monospace;font-size:12px;color:#2a7de1;flex-shrink:0;width:70px}}
.pth{{font-family:'IBM Plex Mono',monospace;font-size:11px;color:#374151;word-break:break-all}}
.err{{font-size:12px;color:#dc2626;margin-top:6px}}
.btns{{margin-top:24px;display:flex;gap:12px}}
.btn{{display:inline-block;background:#2a7de1;color:#fff;font-family:'IBM Plex Sans',sans-serif;font-size:14px;font-weight:600;padding:9px 24px;border-radius:8px;text-decoration:none}}
.btn-sec{{background:#374151}}
.btn:hover{{opacity:.88}}
</style></head><body>
<div class="box">
<h2>&#128190; {len(saved)} arquivo(s) gravado(s)</h2>
<div class="sub">Pasta: {pasta}</div>
{linhas}
{erros_html}
<div class="btns">
<a class="btn btn-sec" href="/contracheque">&#8592; Voltar</a>
<a class="btn" href="javascript:window.close()">Fechar</a>
</div>
</div></body></html>"""
            return make_response(html_ind, 200, {"Content-Type": "text/html; charset=utf-8"})
        except Exception as e_ind:
            return make_response(f"Erro ao gravar arquivos individuais: {e_ind}", 500)

    buf = _gerar_contracheque_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                                   empresa_nm, cnpj_fmt, modo,
                                   matriculas_sel, com_assinatura)
    pdf_bytes = buf.read()

    # Grava automaticamente no disco
    try:
        import logging as _log
        ts           = datetime.now().strftime("%Y%m%d_as_%H%M%S")
        anomes_pasta = f"{ano}-{mes}"
        pasta_sv     = os.path.join("C:\\Folha10-Simples_Contracheque",
                                    ano, anomes_pasta, f"{int(id_empresa):06d}")
        os.makedirs(pasta_sv, exist_ok=True)
        cnpj_digits  = "".join(c for c in cnpj_fmt if c.isdigit())
        _mat_sfx     = (f"_Matricula_{matriculas_sel[0]:06d}"
                        if len(matriculas_sel) == 1 else "")
        nome_f       = f"Folha10_Contracheque_CNPJ_{cnpj_digits}_Folha_{anomes}{_mat_sfx}_em_{ts}.pdf"
        with open(os.path.join(pasta_sv, nome_f), "wb") as fh:
            fh.write(pdf_bytes)
    except Exception as e_sv:
        _log.warning(f"contracheque_pdf: erro ao salvar no disco: {e_sv}")

    resp = make_response(pdf_bytes)
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{nome_arq}"'
    return resp


# =========================================================
# RECIBO DE ADIANTAMENTO QUINZENAL — TELA + PDF
# =========================================================
def _gerar_recibo_adiantamento_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                                    empresa_nm, cnpj_fmt, modo="1",
                                    matriculas_sel=None, com_assinatura=True,
                                    separar_verba=False):
    """Gera PDF do Recibo de Adiantamento Quinzenal seguindo o padrão visual do
    contracheque. Por padrão consolida todas as verbas 161-164 do funcionário em
    um único recibo; se separar_verba=True, gera um recibo por (matricula, verba)."""
    from reportlab.pdfgen.canvas import Canvas
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    from io import BytesIO
    from datetime import datetime

    buf            = BytesIO()
    W_page, H_page = A4
    agora          = datetime.now()
    ano, mes       = anomes[:4], anomes[4:6]
    meses_pt       = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                      "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    mes_nm         = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    anomes_fmt     = f"{mes_nm.upper()}/{ano}"
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"

    def _fbrl(c, dec=2):
        return f"{c/100:,.{dec}f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _fdt(s):
        return f"{s[6:8]}/{s[4:6]}/{s[:4]}" if s and len(s) >= 8 else "—"

    def _extenso(c):
        # Texto simples sem dependência externa: "(reais e centavos)"
        reais  = c // 100
        cents  = c % 100
        if reais == 0 and cents == 0:
            return "zero real"
        s_r = ("um real" if reais == 1 else f"{reais} reais") if reais else ""
        s_c = ("um centavo" if cents == 1 else f"{cents} centavos") if cents else ""
        if s_r and s_c: return f"{s_r} e {s_c}"
        return s_r or s_c

    # ── Rubricas ──────────────────────────────────────────
    rubricas_info = {}
    try:
        for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
            r = (supabase.table("tab_rubrica")
                 .select("cod_rubr,dsc_rubr")
                 .eq("id_cliente", cli_id).execute())
            for row in (r.data or []):
                cod = int(row.get("cod_rubr") or 0)
                if cod:
                    rubricas_info[cod] = str(row.get("dsc_rubr") or f"Verba {cod:04d}")
    except Exception:
        pass
    for c in VERBAS_ADIANTAMENTO:
        rubricas_info.setdefault(c, f"Adiantamento Quinzenal {c-160}ª")

    # ── Movimentos (apenas 161-164) ───────────────────────
    mov_data = {}
    try:
        q = (supabase.table("tab_mov")
             .select("matricula,cod_verba,valor")
             .eq("id_empresa", id_empresa)
             .eq("situacao",   "A")
             .eq("folha",      int(anomes))
             .eq("folha_tipo", folha_tipo_mov)
             .in_("cod_verba", list(VERBAS_ADIANTAMENTO)))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        for reg in (q.execute().data or []):
            mat = int(reg.get("matricula") or 0)
            cod = int(reg.get("cod_verba") or 0)
            val = int(reg.get("valor")     or 0)
            if mat and cod and val > 0:
                mov_data.setdefault(mat, []).append({"cod": cod, "val": val})
    except Exception:
        pass

    # ── Funcionários ──────────────────────────────────────
    func_info = {}
    try:
        r = (supabase.table("tab_cad")
             .select("matricula,nome,nomer,dtadm,vrsalfx,cbofuncao")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .execute())
        for f in (r.data or []):
            mat = int(f.get("matricula") or 0)
            if not mat:
                continue
            nome = str(f.get("nome") or f.get("nomer") or f"Matr. {mat:06d}").strip()
            cbo  = str(f.get("cbofuncao") or "").strip()
            func_info[mat] = {
                "nome":   nome,
                "dtadm":  str(f.get("dtadm")  or ""),
                "sal":    int(f.get("vrsalfx") or 0),
                "funcao": f"CBO {cbo}" if cbo else "—",
            }
    except Exception:
        pass
    cbos_unicos = list({fi["funcao"].replace("CBO ","") for fi in func_info.values()
                        if fi["funcao"].startswith("CBO ")})
    if cbos_unicos:
        try:
            rc = (supabase.table("tab_aux_funcao_total")
                  .select("cbo_codigo,cbo_nome")
                  .in_("cbo_codigo", cbos_unicos).execute())
            cbo_nomes = {r["cbo_codigo"]: r["cbo_nome"] for r in (rc.data or []) if r.get("cbo_codigo")}
            for fi in func_info.values():
                if fi["funcao"].startswith("CBO "):
                    cbo = fi["funcao"].replace("CBO ", "")
                    if cbo in cbo_nomes:
                        fi["funcao"] = cbo_nomes[cbo]
        except Exception:
            pass

    # ── Lista de stubs (um por recibo a gerar) ────────────
    stubs = []
    for mat in sorted(mov_data.keys()):
        if matriculas_sel and mat not in matriculas_sel:
            continue
        fi = func_info.get(mat, {"nome": f"Matr. {mat:06d}", "dtadm": "",
                                  "sal": 0, "funcao": "—"})
        verbas = sorted(mov_data[mat], key=lambda v: v["cod"])
        if separar_verba and len(verbas) > 1:
            for v in verbas:
                stubs.append({"mat": mat, "fi": fi, "verbas": [v],
                              "total": v["val"]})
        else:
            total = sum(v["val"] for v in verbas)
            stubs.append({"mat": mat, "fi": fi, "verbas": verbas, "total": total})

    # ── Dimensões / cores ─────────────────────────────────
    ML = 1.0*cm; MR = 1.0*cm; MT = 0.8*cm; MB = 0.8*cm
    W_stub   = W_page - ML - MR
    H_usable = H_page - MT - MB
    CUT_GAP  = 0.5*cm
    H_half   = (H_usable - CUT_GAP) / 2

    C_LINE = colors.HexColor("#374151")
    C_TXT  = colors.HexColor("#111827")
    C_GRAY = colors.HexColor("#374151")
    C_LGRAY= colors.HexColor("#6b7280")

    ROWS = {
        False: {"hdr":42,"emp":26,"col":13,"verb":13,"tot":14,
                "txt":40,"sig":44},
        True:  {"hdr":34,"emp":20,"col":11,"verb":11,"tot":12,
                "txt":34,"sig":36},
    }

    def stub_height(stub, compact, com_sig=True):
        R = ROWS[compact]
        sig_h = R["sig"] if com_sig else 6
        return (R["hdr"] + R["emp"] + R["col"] +
                len(stub["verbas"]) * R["verb"] +
                R["tot"] + R["txt"] + sig_h)

    c = Canvas(buf, pagesize=A4)

    _qtd_c, _dhc = _get_calc_info(id_empresa, id_cliente, anomes, anomes_tipo)
    _emit = agora.strftime("%d/%m/%Y %H:%M")
    rod_txt = (f"Cálculo n.º {_qtd_c}  —  {_dhc}  —  emitido em {_emit}"
               if _qtd_c and _dhc else f"Emitido em {_emit}")

    def _draw_rod():
        c.saveState()
        c.setFont("Helvetica", 7)
        c.setFillColor(colors.HexColor("#64748b"))
        c.drawString(ML, 0.7*cm, rod_txt)
        c.restoreState()

    def finish_page():
        _draw_rod()
        c.showPage()

    def hline(x0, x1, y, color, lw=0.3):
        c.saveState()
        c.setStrokeColor(color); c.setLineWidth(lw); c.line(x0, y, x1, y); c.restoreState()

    def draw_cut(y_c):
        c.saveState()
        c.setStrokeColor(colors.HexColor("#94a3b8"))
        c.setLineWidth(0.5); c.setDash([3, 5], 0)
        c.line(ML - 0.2*cm, y_c, W_page - MR + 0.2*cm, y_c)
        c.setDash([], 0)
        c.setFont("Helvetica", 7); c.setFillColor(colors.HexColor("#94a3b8"))
        c.drawCentredString(W_page/2, y_c + 2.5, "✂")
        c.restoreState()

    def draw_stub(x0, y_top, w, stub, compact=False, com_sig=True):
        R   = ROWS[compact]
        PAD = 3 if compact else 5

        FS_TIT = 9   if compact else 11
        FS_EMP = 8   if compact else 9
        FS_DET = 6   if compact else 7
        FS_COL = 5.5 if compact else 6.5
        FS_VRB = 7   if compact else 8
        FS_TOT = 8   if compact else 9
        FS_TXT = 6.5 if compact else 7.5
        FS_SIG = 7   if compact else 8

        W_COD = 0.12 * w
        W_VAL = 0.21 * w
        W_DSC = w - W_COD - W_VAL

        xCOD = x0
        xDSC = x0 + W_COD
        xVAL = x0 + W_COD + W_DSC
        xEND = x0 + w

        y       = y_top
        y_start = y_top
        HPAD    = 8 if compact else 12

        fi    = stub["fi"]
        mat   = stub["mat"]
        verbas= stub["verbas"]
        total = stub["total"]

        def fill_row(row_h, fill_color):
            c.setFillColor(fill_color)
            c.rect(x0, y - row_h, w, row_h, fill=1, stroke=0)

        def text_at(text, fx, fy, font, size, fill, align="left"):
            c.setFont(font, size); c.setFillColor(fill)
            if align == "right":  c.drawRightString(fx, fy, text)
            elif align == "center": c.drawCentredString(fx, fy, text)
            else:                  c.drawString(fx, fy, text)

        # ── 1. Cabeçalho — empresa + título ─────────────────────────
        fill_row(R["hdr"], colors.white)
        hline(x0, xEND, y,            C_LINE, 1.0)
        hline(x0, xEND, y - R["hdr"], C_LINE, 1.4)

        y1 = y - FS_TIT - 4
        text_at(empresa_nm[:46], x0+HPAD, y1, "Helvetica-Bold", FS_TIT, C_TXT)
        text_at("RECIBO DE ADIANTAMENTO", xEND-HPAD, y1, "Helvetica-Bold",
                FS_TIT, C_TXT, "right")

        y2 = y - R["hdr"] + FS_EMP + 6
        text_at(f"CNPJ: {cnpj_fmt}", x0+HPAD, y2, "Helvetica", FS_EMP, C_GRAY)
        text_at(anomes_fmt, xEND-HPAD, y2, "Helvetica-Bold", FS_EMP+1,
                colors.HexColor("#9a3412"), "right")

        y3 = y - R["hdr"] + 4
        text_at("Quinzenal — Adiantamento de Salário", x0+HPAD, y3,
                "Helvetica", FS_DET, C_LGRAY)
        y -= R["hdr"]

        # ── 2. Dados do funcionário ─────────────────────────────────
        fill_row(R["emp"], colors.white)
        y_e1 = y - R["emp"] + R["emp"] * 0.60
        text_at(f"{mat:08d}  —  {fi['nome']}",
                x0+PAD, y_e1, "Helvetica-Bold", FS_EMP, C_TXT)
        y_e2 = y - R["emp"] + 4
        det = (f"Admissão: {_fdt(fi['dtadm'])}   |   "
               f"Função: {fi['funcao'][:32]}   |   "
               f"Salário: {_fbrl(fi['sal'])}/Mês")
        text_at(det, x0+PAD, y_e2, "Helvetica", FS_DET, C_LGRAY)
        hline(x0, xEND, y - R["emp"], C_LINE, 0.6)
        y -= R["emp"]

        # ── 3. Cabeçalho colunas ────────────────────────────────────
        fill_row(R["col"], colors.HexColor("#f3f4f6"))
        y_c = y - R["col"] + 3
        text_at("CÓD",       xCOD+W_COD/2,  y_c, "Helvetica-Bold", FS_COL, C_GRAY, "center")
        text_at("DESCRIÇÃO", xDSC+PAD,       y_c, "Helvetica-Bold", FS_COL, C_GRAY)
        text_at("VALOR",     xVAL+W_VAL-PAD, y_c, "Helvetica-Bold", FS_COL, C_GRAY, "right")
        hline(x0, xEND, y - R["col"], C_LINE, 0.5)
        y -= R["col"]

        # ── 4. Verbas ───────────────────────────────────────────────
        for v in verbas:
            fill_row(R["verb"], colors.white)
            y_v = y - R["verb"] + 3
            text_at(f"{v['cod']:04d}", xCOD+W_COD/2, y_v, "Helvetica", FS_COL,
                    C_LGRAY, "center")
            dsc = rubricas_info.get(v["cod"], f"Verba {v['cod']:04d}")
            text_at(dsc[:50], xDSC+PAD, y_v, "Helvetica", FS_VRB, C_TXT)
            text_at(_fbrl(v["val"]), xVAL+W_VAL-PAD, y_v, "Helvetica", FS_VRB,
                    C_TXT, "right")
            hline(x0, xEND, y - R["verb"], colors.HexColor("#e5e7eb"), 0.2)
            y -= R["verb"]

        # ── 5. Total ────────────────────────────────────────────────
        fill_row(R["tot"], colors.HexColor("#fff7ed"))
        hline(x0, xEND, y, C_LINE, 0.7)
        y_t = y - R["tot"] + 3
        text_at("TOTAL DO ADIANTAMENTO", xDSC+PAD, y_t, "Helvetica-Bold", FS_TOT,
                colors.HexColor("#9a3412"))
        text_at(_fbrl(total), xVAL+W_VAL-PAD, y_t, "Helvetica-Bold", FS_TOT,
                colors.HexColor("#9a3412"), "right")
        hline(x0, xEND, y - R["tot"], C_LINE, 1.0)
        y -= R["tot"]

        # ── 6. Texto do recibo ──────────────────────────────────────
        fill_row(R["txt"], colors.white)
        rec_txt1 = (f"Declaro ter recebido de {empresa_nm[:60]} a importância de "
                    f"{_fbrl(total)} ({_extenso(total)}),")
        rec_txt2 = (f"referente ao Adiantamento Quinzenal do mês de "
                    f"{mes_nm.upper()}/{ano}, dando plena e geral quitação.")
        text_at(rec_txt1, x0+PAD, y - 13, "Helvetica", FS_TXT, C_TXT)
        text_at(rec_txt2, x0+PAD, y - 13 - FS_TXT - 4, "Helvetica", FS_TXT, C_TXT)
        y -= R["txt"]

        # ── 7. Assinatura ───────────────────────────────────────────
        sig_h = R["sig"] if com_sig else 6
        fill_row(sig_h, colors.white)
        if com_sig:
            sig_ctr   = x0 + w / 2
            sig_span  = w * 0.36
            sig_y_l   = y - sig_h + 14
            sig_y_n   = y - sig_h + 5
            data_ger  = agora.strftime("%d/%m/%Y  %H:%M")
            hline(sig_ctr - sig_span, sig_ctr + sig_span, sig_y_l, C_LINE, 0.5)
            text_at(fi["nome"][:60], sig_ctr, sig_y_n,
                    "Helvetica", FS_SIG, C_LGRAY, "center")
            text_at(f"Gerado em {data_ger}", xEND-PAD, y - sig_h + 2,
                    "Helvetica", FS_TXT-0.5, C_LGRAY, "right")
        y -= sig_h

        # ── Borda externa ───────────────────────────────────────────
        used_h = y_start - y
        c.saveState()
        c.setStrokeColor(C_LINE); c.setLineWidth(0.8)
        c.rect(x0, y_start - used_h, w, used_h, fill=0, stroke=1)
        c.restoreState()

    # ── Posições e renderização por modo ──────────────────
    y_full    = H_page - MT
    y_top_top = H_page - MT
    y_top_bot = MB + H_half
    y_cut     = MB + H_half + CUT_GAP / 2
    cs        = com_assinatura

    if not stubs:
        # PDF mínimo com aviso
        c.setFont("Helvetica", 11)
        c.setFillColor(colors.HexColor("#374151"))
        c.drawCentredString(W_page/2, H_page/2,
                            "Nenhum adiantamento quinzenal encontrado para os funcionários selecionados.")
        finish_page()
    elif modo == "1":
        for stub in stubs:
            draw_stub(ML, y_full, W_stub, stub, compact=False, com_sig=cs)
            finish_page()
    elif modo == "2S":
        for stub in stubs:
            h_est = stub_height(stub, compact=True, com_sig=cs)
            if h_est > H_half - 4:
                draw_stub(ML, y_full, W_stub, stub, compact=False, com_sig=cs)
            else:
                draw_stub(ML, y_top_top, W_stub, stub, compact=True, com_sig=cs)
                draw_cut(y_cut)
                draw_stub(ML, y_top_bot, W_stub, stub, compact=True, com_sig=cs)
            finish_page()
    else:  # 2D
        i = 0
        while i < len(stubs):
            s1 = stubs[i]
            h1 = stub_height(s1, compact=True, com_sig=cs)
            if h1 > H_half - 4:
                draw_stub(ML, y_full, W_stub, s1, compact=False, com_sig=cs)
                finish_page(); i += 1; continue
            draw_stub(ML, y_top_top, W_stub, s1, compact=True, com_sig=cs)
            if i + 1 < len(stubs):
                s2 = stubs[i+1]
                h2 = stub_height(s2, compact=True, com_sig=cs)
                if h2 > H_half - 4:
                    draw_cut(y_cut); finish_page()
                    draw_stub(ML, y_full, W_stub, s2, compact=False, com_sig=cs)
                    finish_page(); i += 2; continue
                draw_cut(y_cut)
                draw_stub(ML, y_top_bot, W_stub, s2, compact=True, com_sig=cs)
                i += 2
            else:
                i += 1
            finish_page()

    c.save()
    buf.seek(0)
    return buf


@app.route("/recibo_adiantamento")
def recibo_adiantamento():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    empresa_nm  = str(session.get("empresa_info") or "")
    if not anomes:
        return redirect("/menu")
    meses_pt = ["","Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"]
    ano, mes  = anomes[:4], anomes[4:6]
    mes_nm    = meses_pt[int(mes)] if mes.isdigit() and 1 <= int(mes) <= 12 else mes
    tipo_lbl  = {"N":"Folha Normal","F":"Férias","R":"Rescisão",
                 "A":"Adiantamento 13°","1":"13° Salário"}.get(anomes_tipo, anomes_tipo)
    folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"

    # Funcionários com adiantamento lançado nesta folha (verbas 161-164)
    funcionarios = []
    existe_multi_verba = False
    try:
        q = (supabase.table("tab_mov")
             .select("matricula, cod_verba")
             .eq("id_empresa", id_empresa)
             .eq("situacao",   "A")
             .eq("folha",      int(anomes))
             .eq("folha_tipo", folha_tipo_mov)
             .in_("cod_verba", list(VERBAS_ADIANTAMENTO)))
        if id_cliente:
            q = q.eq("id_cliente", id_cliente)
        regs = q.execute().data or []
        # Agrupa: {mat: {set de verbas}}
        por_mat = {}
        for r in regs:
            mat = int(r.get("matricula") or 0)
            cod = int(r.get("cod_verba") or 0)
            if mat and cod:
                por_mat.setdefault(mat, set()).add(cod)
        mats = sorted(por_mat.keys())
        if mats:
            r2 = (supabase.table("tab_cad")
                  .select("matricula,nome,nomer")
                  .eq("id_empresa", id_empresa)
                  .in_("matricula", mats)
                  .execute())
            nomes_map = {int(r["matricula"]): str(r.get("nome") or r.get("nomer")
                         or f"Matr. {r['matricula']:06d}").strip()
                         for r in (r2.data or []) if r.get("matricula")}
            for mat in mats:
                vbs = sorted(por_mat[mat])
                if len(vbs) > 1:
                    existe_multi_verba = True
                funcionarios.append({
                    "mat":     mat,
                    "mat_fmt": f"{mat:08d}",
                    "nome":    nomes_map.get(mat, f"Matr. {mat:06d}"),
                    "vbs_str": " ".join(f"{c:04d}" for c in vbs),
                })
    except Exception:
        pass

    pasta_salvar = (f"C:\\Folha10-Simples_ReciboAdiantamento\\{ano}\\{ano}-{mes}\\{int(id_empresa):06d}"
                    if anomes else "")
    return render_template(
        "F10_Recibo_Adiantamento.html",
        versao            = ler_versao(),
        nome              = session.get("nome", ""),
        empresa           = empresa_nm,
        anomes_fmt        = f"{mes_nm} / {ano}",
        tipo_lbl          = tipo_lbl,
        funcionarios      = funcionarios,
        existe_multi_verba= existe_multi_verba,
        pasta_salvar      = pasta_salvar,
    )


@app.route("/recibo_adiantamento_pdf")
def recibo_adiantamento_pdf():
    if not session.get("logado"):
        return redirect("/")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    if not anomes:
        return "Nenhuma folha ativa.", 400
    empresa_nm  = str(session.get("empresa_info") or "")
    cnpj_fmt    = _fmt_cnpj(str(session.get("cnpj_empresa") or ""))

    modo = request.args.get("modo", "1")
    if modo not in ("1","2S","2D"):
        modo = "1"
    mats_str       = request.args.getlist("mat")
    matriculas_sel = [int(m) for m in mats_str if m.isdigit()] if mats_str else []
    com_assinatura = request.args.get("assinatura", "1") != "0"
    separar_verba  = request.args.get("separar", "0") == "1"

    from flask import make_response
    ano, mes  = anomes[:4], anomes[4:6]
    nome_arq  = f"ReciboAdiantamento_{empresa_nm[:20].replace(' ','_')}_{ano}{mes}.pdf"

    # Salvar um arquivo por funcionário
    salvar_ind = request.args.get("salvar_ind", "0") == "1" and modo in ("1", "2S")
    if salvar_ind:
        try:
            ts           = datetime.now().strftime("%Y%m%d_as_%H%M%S")
            cnpj_digits  = "".join(c for c in cnpj_fmt if c.isdigit())
            anomes_pasta = f"{ano}-{mes}"
            pasta        = os.path.join("C:\\Folha10-Simples_ReciboAdiantamento",
                                        ano, anomes_pasta, f"{int(id_empresa):06d}")
            os.makedirs(pasta, exist_ok=True)

            folha_tipo_mov = anomes_tipo if anomes_tipo in ("F", "R", "A", "1") else "N"
            q = (supabase.table("tab_mov")
                 .select("matricula")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao",   "A")
                 .eq("folha",      int(anomes))
                 .eq("folha_tipo", folha_tipo_mov)
                 .in_("cod_verba", list(VERBAS_ADIANTAMENTO)))
            if id_cliente:
                q = q.eq("id_cliente", id_cliente)
            mats_all = sorted({int(r["matricula"]) for r in (q.execute().data or [])
                               if r.get("matricula")})
            if matriculas_sel:
                sel_set  = set(matriculas_sel)
                mats_all = [m for m in mats_all if m in sel_set]

            saved = []
            erros = []
            for mat in mats_all:
                try:
                    buf_i = _gerar_recibo_adiantamento_pdf(id_empresa, anomes, anomes_tipo,
                                                           id_cliente, empresa_nm, cnpj_fmt,
                                                           modo, [mat], com_assinatura,
                                                           separar_verba)
                    pdf_i = buf_i.read()
                    if len(pdf_i) < 2000:
                        continue
                    nome_f  = (f"Folha10_ReciboAdiantamento_CNPJ_{cnpj_digits}"
                               f"_Folha_{anomes}_Matricula_{mat:06d}_em_{ts}.pdf")
                    caminho = os.path.join(pasta, nome_f)
                    with open(caminho, "wb") as fh:
                        fh.write(pdf_i)
                    saved.append((mat, caminho))
                except Exception as e_m:
                    erros.append(f"Matrícula {mat:06d}: {e_m}")

            linhas = "".join(
                f'<div class="frow"><span class="mat">{m:06d}</span>'
                f'<span class="pth">{c}</span></div>'
                for m, c in saved)
            erros_html = "".join(f'<div class="err">{e}</div>' for e in erros)
            html_ind = f"""<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">
<title>Recibos gravados</title>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;600&family=IBM+Plex+Mono:wght@400&display=swap" rel="stylesheet">
<style>
*{{box-sizing:border-box;margin:0;padding:0}}
body{{font-family:'IBM Plex Sans',sans-serif;background:#f0f2f6;padding:40px 24px}}
.box{{background:#fff;border:1px solid #dde3ec;border-radius:12px;padding:32px 36px;max-width:700px;margin:0 auto}}
h2{{font-size:18px;font-weight:600;color:#0b1f3a;margin-bottom:6px}}
.sub{{font-size:13px;color:#64748b;margin-bottom:20px}}
.frow{{display:flex;gap:14px;padding:7px 0;border-bottom:1px solid #f1f5f9;align-items:baseline}}
.frow:last-of-type{{border-bottom:none}}
.mat{{font-family:'IBM Plex Mono',monospace;font-size:12px;color:#2a7de1;flex-shrink:0;width:70px}}
.pth{{font-family:'IBM Plex Mono',monospace;font-size:11px;color:#374151;word-break:break-all}}
.err{{font-size:12px;color:#dc2626;margin-top:6px}}
.btns{{margin-top:24px;display:flex;gap:12px}}
.btn{{display:inline-block;background:#2a7de1;color:#fff;font-family:'IBM Plex Sans',sans-serif;font-size:14px;font-weight:600;padding:9px 24px;border-radius:8px;text-decoration:none}}
.btn-sec{{background:#374151}}
.btn:hover{{opacity:.88}}
</style></head><body>
<div class="box">
<h2>&#128190; {len(saved)} arquivo(s) gravado(s)</h2>
<div class="sub">Pasta: {pasta}</div>
{linhas}
{erros_html}
<div class="btns">
<a class="btn btn-sec" href="/recibo_adiantamento">&#8592; Voltar</a>
<a class="btn" href="javascript:window.close()">Fechar</a>
</div>
</div></body></html>"""
            return make_response(html_ind, 200, {"Content-Type": "text/html; charset=utf-8"})
        except Exception as e_ind:
            return make_response(f"Erro ao gravar arquivos individuais: {e_ind}", 500)

    buf = _gerar_recibo_adiantamento_pdf(id_empresa, anomes, anomes_tipo, id_cliente,
                                          empresa_nm, cnpj_fmt, modo,
                                          matriculas_sel, com_assinatura, separar_verba)
    pdf_bytes = buf.read()

    # Grava automaticamente no disco
    try:
        import logging as _log
        ts           = datetime.now().strftime("%Y%m%d_as_%H%M%S")
        anomes_pasta = f"{ano}-{mes}"
        pasta_sv     = os.path.join("C:\\Folha10-Simples_ReciboAdiantamento",
                                    ano, anomes_pasta, f"{int(id_empresa):06d}")
        os.makedirs(pasta_sv, exist_ok=True)
        cnpj_digits  = "".join(c for c in cnpj_fmt if c.isdigit())
        _mat_sfx     = (f"_Matricula_{matriculas_sel[0]:06d}"
                        if len(matriculas_sel) == 1 else "")
        nome_f       = f"Folha10_ReciboAdiantamento_CNPJ_{cnpj_digits}_Folha_{anomes}{_mat_sfx}_em_{ts}.pdf"
        with open(os.path.join(pasta_sv, nome_f), "wb") as fh:
            fh.write(pdf_bytes)
    except Exception as e_sv:
        _log.warning(f"recibo_adiantamento_pdf: erro ao salvar: {e_sv}")

    resp = make_response(pdf_bytes)
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{nome_arq}"'
    return resp


