@app.route("/memoria_calculo")
def memoria_calculo():
    if not session.get("logado"):
        return redirect("/")
    import glob as _glob
    id_empresa  = _get_id_empresa()
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    sit_map     = {"A":("Aberta","sit-aberta"), "X":("Aberta","sit-aberta"),
                   "C":("Calculada","sit-calculada"), "F":("Fechada","sit-fechada")}
    sit_st      = str(session.get("anomes_situacao") or "")
    sit_label, sit_class = sit_map.get(sit_st, ("",""))

    # lista de funcionários ativos
    funcionarios = []
    try:
        linhas = _calc_etapa1_dados(id_empresa)
        for l in (linhas or []):
            funcionarios.append({"matricula": int(l["matricula"]), "nome": l["nome"]})
    except Exception:
        pass

    # descobre quais têm PDF gerado para a folha ativa (local ou Storage).
    # Só as memórias da folha mensal (prefixo Folha10_Memoria_Empresa), não
    # as de férias/adiantamento que ficam na mesma pasta.
    mats_com_pdf = set()
    for fname in _memoria_listar(anomes, id_empresa):
        if (fname.startswith("Folha10_Memoria_Empresa") and "_Ferias_" not in fname
                and "_Rescisao_" not in fname
                and "_Matricula_" in fname and fname.endswith(".pdf")):
            try:
                mats_com_pdf.add(int(fname.split("_Matricula_")[1].split("_")[0]))
            except Exception:
                pass

    for f in funcionarios:
        f["tem_pdf"] = f["matricula"] in mats_com_pdf

    return render_template(
        "F10_Memoria_Calculo.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        folha_tipo_ativa=anomes_tipo,
        folha_sit_label=sit_label,
        folha_sit_class=sit_class,
        funcionarios=funcionarios,
    )


@app.route("/api/memoria_calculo_pdf/<int:matricula>")
def api_memoria_calculo_pdf(matricula):
    if not session.get("logado"):
        return "Sessão expirada", 401
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    if len(anomes) != 6:
        return "Folha ativa não definida", 400
    alvo = f"_Matricula_{matricula:06d}_em_"
    arquivos = sorted(fn for fn in _memoria_listar(anomes, id_empresa)
                      if fn.startswith("Folha10_Memoria_Empresa") and "_Ferias_" not in fn
                      and "_Rescisao_" not in fn
                      and alvo in fn and fn.endswith(".pdf"))
    if not arquivos:
        return "PDF não encontrado para esta matrícula", 404
    nome = arquivos[-1]          # mais recente pelo nome (timestamp no final)
    data = _memoria_ler(anomes, id_empresa, nome)
    if not data:
        return "PDF não encontrado", 404
    from flask import send_file as _send_file
    return _send_file(io.BytesIO(data), mimetype="application/pdf",
                      as_attachment=False, download_name=nome)


@app.route("/api/memoria_rescisao_pdf/<int:matricula>")
def api_memoria_rescisao_pdf(matricula):
    """Abre a memória de cálculo da RESCISÃO (folha_tipo R) do funcionário."""
    if not session.get("logado"):
        return "Sessão expirada", 401
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if len(anomes) != 6:
        return "Folha ativa não definida", 400
    # tab_total R = calculada-e-em-dia. Se foi invalidada por lançamento manual
    # posterior (ou nunca calculada), bloqueia a memória (PDF pode estar obsoleto).
    if not _rescisao_calculada_mats(id_empresa, id_cliente, int(anomes), [matricula]):
        return ("Rescisão PENDENTE de cálculo para este funcionário (houve lançamento "
                "de verba após o cálculo, ou ainda não foi calculada). Recalcule a "
                "rescisão antes de abrir a memória."), 400
    alvo = f"_Matricula_{matricula:06d}_em_"
    arquivos = sorted(fn for fn in _memoria_listar(anomes, id_empresa)
                      if fn.startswith("Folha10_Memoria_Empresa") and "_Rescisao_" in fn
                      and alvo in fn and fn.endswith(".pdf"))
    if not arquivos:
        return ("Memória da rescisão não encontrada para esta matrícula. "
                "Calcule a rescisão para gerar a memória."), 404
    nome = arquivos[-1]          # mais recente pelo nome (timestamp no final)
    data = _memoria_ler(anomes, id_empresa, nome)
    if not data:
        return "PDF não encontrado", 404
    from flask import send_file as _send_file
    return _send_file(io.BytesIO(data), mimetype="application/pdf",
                      as_attachment=False, download_name=nome)


@app.route("/memoria_ferias")
def memoria_ferias():
    if not session.get("logado"):
        return redirect("/")
    import glob as _glob
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    anomes      = str(session.get("anomes_atual") or "")
    sit_map     = {"A":("Aberta","sit-aberta"), "X":("Aberta","sit-aberta"),
                   "C":("Calculada","sit-calculada"), "F":("Fechada","sit-fechada")}
    sit_st      = str(session.get("anomes_situacao") or "")
    sit_label, sit_class = sit_map.get(sit_st, ("",""))

    funcionarios = []
    if len(anomes) == 6:
        try:
            r_ev = (supabase.table("tab_eventos")
                    .select("matricula")
                    .eq("id_cliente", id_cliente)
                    .eq("id_empresa", id_empresa)
                    .eq("op1", 3)
                    .gte("data1i", anomes + "01")
                    .lte("data1i", anomes + "31")
                    .execute())
            mats = list({ev["matricula"] for ev in (r_ev.data or [])})
            if mats:
                r_cad = (supabase.table("tab_cad")
                         .select("matricula, nome, nomer")
                         .eq("id_cliente", id_cliente)
                         .eq("id_empresa", id_empresa)
                         .in_("matricula", mats)
                         .execute())
                for c in sorted(r_cad.data or [], key=lambda x: x.get("matricula") or 0):
                    funcionarios.append({
                        "matricula": int(c["matricula"]),
                        "nome":      (c.get("nomer") or c.get("nome") or "").strip(),
                    })
        except Exception:
            pass

    mats_com_pdf = set()
    for fname in _memoria_listar(anomes, id_empresa):
        if "_Ferias_" in fname and "_Matricula_" in fname and fname.endswith(".pdf"):
            try:
                mats_com_pdf.add(int(fname.split("_Matricula_")[1].split("_")[0]))
            except Exception:
                pass

    for f in funcionarios:
        f["tem_pdf"] = f["matricula"] in mats_com_pdf

    return render_template(
        "F10_Memoria_Calculo.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        folha_tipo_ativa="F",
        folha_sit_label=sit_label,
        folha_sit_class=sit_class,
        funcionarios=funcionarios,
        titulo_pagina="Memória de Cálculo — Férias",
        card_subtitulo="Selecione o funcionário para abrir a memória de cálculo de férias em PDF",
        pdf_endpoint="/api/memoria_ferias_pdf",
    )


@app.route("/api/memoria_ferias_pdf/<int:matricula>")
def api_memoria_ferias_pdf(matricula):
    if not session.get("logado"):
        return "Sessão expirada", 401
    id_empresa = _get_id_empresa()
    anomes     = str(session.get("anomes_atual") or "")
    if len(anomes) != 6:
        return "Folha ativa não definida", 400
    alvo = f"_Matricula_{matricula:06d}_em_"
    arquivos = sorted(fn for fn in _memoria_listar(anomes, id_empresa)
                      if "_Ferias_" in fn and alvo in fn and fn.endswith(".pdf"))
    if not arquivos:
        return "PDF de férias não encontrado para esta matrícula", 404
    nome = arquivos[-1]          # mais recente pelo timestamp no nome (_em_)
    data = _memoria_ler(anomes, id_empresa, nome)
    if not data:
        return "PDF de férias não encontrado", 404
    from flask import send_file as _send_file
    resp = _send_file(io.BytesIO(data), mimetype="application/pdf",
                      as_attachment=False, download_name=nome)
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"]  = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


# rota temporária mantida para compatibilidade — não exposta no menu
@app.route("/api/calcular_folha_etapa1_pdf", methods=["POST"])
def calcular_folha_etapa1_pdf():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente") or 0
    empresa_nm = session.get("empresa_info", "")
    usuario    = session.get("nome", "")
    versao     = ler_versao()

    if len(anomes) != 6:
        return jsonify({"ok": False, "msg": "Folha ativa não definida."})

    yyyy       = anomes[:4]
    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}"

    dest = _memoria_destino(anomes, id_empresa)   # local (Windows) ou Storage (Render)
    if not dest.get("base"):
        return jsonify({"ok": False, "msg": "Não foi possível preparar o destino das memórias."})

    linhas = _calc_etapa1_dados(id_empresa)
    if not linhas:
        return jsonify({"ok": False, "msg": "Nenhum funcionário ativo encontrado."})

    # ── estilos reutilizados em todos os PDFs ──────────────
    st_empresa = ParagraphStyle("pe", fontName="Helvetica-Bold", fontSize=12,
                                alignment=TA_CENTER, spaceAfter=2)
    st_titulo  = ParagraphStyle("pt", fontName="Helvetica-Bold", fontSize=6,
                                alignment=TA_CENTER, spaceAfter=2)
    st_sub     = ParagraphStyle("ps", fontName="Helvetica",      fontSize=9,
                                alignment=TA_CENTER, spaceAfter=0,
                                textColor=colors.HexColor("#64748b"))
    st_etapa   = ParagraphStyle("peta", fontName="Helvetica", fontSize=8,
                                spaceBefore=10, spaceAfter=4,
                                leftIndent=0)
    st_formula = ParagraphStyle("pf", fontName="Helvetica", fontSize=7,
                                spaceAfter=8, textColor=colors.HexColor("#374151"))
    st_rod     = ParagraphStyle("pr",    fontName="Helvetica", fontSize=7,
                                alignment=TA_CENTER,
                                textColor=colors.HexColor("#94a3b8"))
    st_detalhe = ParagraphStyle("pdet",  fontName="Helvetica", fontSize=8,
                                textColor=colors.HexColor("#374151"), leftIndent=0)

    linha_sep_style = TableStyle([
        ("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.HexColor("#e2e8f0")),
        ("TOPPADDING",    (0,0), (-1,-1), 0),
        ("BOTTOMPADDING", (0,0), (-1,-1), 6),
    ])

    salvos = []
    erros  = []
    agora        = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    id_cliente   = session.get("id_cliente")
    afastamentos = _calc_etapa2_afastamentos(id_empresa, anomes, id_cliente=id_cliente)
    ferias       = _calc_etapa2_ferias(id_empresa, anomes)
    faltas       = _calc_etapa5_faltas(id_empresa, anomes, id_cliente=id_cliente)
    _ano_c  = int(anomes[:4]);  _mes_c = int(anomes[4:6])
    _ultdia = ((date(_ano_c + 1, 1, 1) if _mes_c == 12 else date(_ano_c, _mes_c + 1, 1)) - timedelta(days=1)).day
    dt_ini_c = f"{anomes[:4]}{anomes[4:6]}01"
    dt_fim_c = f"{anomes[:4]}{anomes[4:6]}{_ultdia:02d}"

    for l in linhas:
        matr   = int(l["matricula"] or 0)
        nome_f = f"Folha10_Memoria_Empresa_{int(id_empresa):06d}_Folha_{anomes}_Matricula_{matr:06d}.pdf"

        try:
            buf = io.BytesIO()
            doc = SimpleDocTemplate(buf, pagesize=A4,
                                    leftMargin=2.5*cm, rightMargin=2.5*cm,
                                    topMargin=2.5*cm,  bottomMargin=2.5*cm)
            elems = []

            # ── cabeçalho ─────────────────────────────────
            elems.append(Paragraph(empresa_nm, st_empresa))
            elems.append(Paragraph("MEMÓRIA DE CÁLCULO — FOLHA DE PAGAMENTO", st_titulo))
            elems.append(Paragraph(f"Competência: {anomes_fmt}", st_sub))
            elems.append(Spacer(1, 0.1*cm))
            elems.append(Table([[""]], colWidths=[16*cm], style=linha_sep_style))

            # ── identificação do funcionário ───────────────
            st_id = ParagraphStyle("pid", fontName="Helvetica", fontSize=9, leading=11)
            id_tbl = Table([
                [Paragraph(f"<b>Matrícula:</b> {matr:06d}", st_id),
                 Paragraph(f"<b>Nome:</b> {l['nome']}", st_id)],
            ], colWidths=[4*cm, 12*cm])
            id_tbl.setStyle(TableStyle([
                ("TOPPADDING",    (0, 0), (-1, -1), 3),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
            ]))
            elems.append(id_tbl)
            elems.append(Table([[""]], colWidths=[16*cm], style=linha_sep_style))

            # ── guard: admissão após o mês ────────────────
            dtadm_raw = str(l.get("dtadm") or "")
            if len(dtadm_raw) == 8 and dtadm_raw > dt_fim_c:
                msg = (f"ETAPA 0002 — ADMITIDO APÓS ESSA FOLHA — CÁLCULO NÃO SERÁ FEITO"
                       f"   Admissão em {_d_br(dtadm_raw)}")
                msg_tbl = Table([[Paragraph(msg, st_etapa)]], colWidths=[16*cm])
                msg_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 8),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 4),
                ]))
                elems.append(msg_tbl)
                doc.build(elems)
                _salvar_memoria_pdf(dest, nome_f, buf.getvalue())
                salvos.append(nome_f)
                continue

            # ── etapa 1 ────────────────────────────────────
            mmVmm = {}
            mmQmm = {}
            _categ_s2    = str(l.get("codcateg", "")).strip()
            _categ_n2    = int(_categ_s2) if _categ_s2.isdigit() else 0
            is_intermitente = _categ_n2 == 111
            # Cat 700-799 = nao-empregado → pro-labore, sem FGTS. Verba do salario
            # por categoria: 901→7, 721→6, 722→16, 723→86, demais 700-799→6, else 1.
            is_nao_empregado = 700 <= _categ_n2 <= 799
            _cod_sal_mes     = _verba_salario(_categ_n2)
            is_domestico    = 700 <= _categ_n2 <= 799
            if is_intermitente:
                formula_txt = (f"Intermitente (Cat. 111) — Salário Hora cadastrado: {l['sal_hora_fmt']}/h."
                               f"  Salário calculado via Verba 003 (lançamento manual).")
            elif l["tipo"] == "Mensalista":
                formula_txt = (f"Salário Hora = Salário Base / Horas/Mes  =  "
                               f"{l['sal_base_fmt']} / {l['qtdhrsmes']} h  =  {l['sal_hora_fmt']}")
            else:
                formula_txt = (f"Sal. Hora = Sal. Base = {l['sal_hora_fmt']}  |  "
                               f"Sal. Mensal = Sal. Hora x Horas/Mes  =  "
                               f"{l['sal_hora_fmt']} x {l['qtdhrsmes']} h  =  {l['sal_mes_fmt']}")
            etapa_tbl = Table([
                [Paragraph("ETAPA 0001 — CÁLCULO DO SALÁRIO HORA", st_etapa)],
                [Paragraph(formula_txt, st_formula)],
            ], colWidths=[16*cm])
            etapa_tbl.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (0, 1), 0),
                ("BOTTOMPADDING", (0, 1), (0, 1), 4),
            ]))
            elems.append(etapa_tbl)

            # tabela de valores
            dados = [
                ["Tipo de Salário",  "Intermitente" if is_intermitente else l["tipo"]],
                ["Salário Base",     l["sal_base_fmt"]],
                ["Horas / Mês",      f"{l['qtdhrsmes']} h"],
                ["Salário Hora",     l["sal_hora_fmt"]],
                ["Salário Mensal",   "— Verba 003 (manual)" if is_intermitente else l["sal_mes_fmt"]],
            ]
            val_tbl = Table(dados, colWidths=[5*cm, 7*cm])
            val_tbl.setStyle(TableStyle([
                ("FONTNAME",      (0, 0), (0, -1), "Helvetica-Bold"),
                ("FONTNAME",      (1, 0), (1, -1), "Helvetica"),
                ("FONTSIZE",      (0, 0), (-1, -1), 9),
                ("ALIGN",         (1, 0), (1, -1), "RIGHT"),
                ("GRID",          (0, 0), (-1, -1), 0.5, colors.HexColor("#e2e8f0")),
                ("TOPPADDING",    (0, 0), (-1, -1), 5),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
                ("LEFTPADDING",   (0, 0), (-1, -1), 8),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 8),
                ("BACKGROUND",    (0, 0), (0, -1), colors.HexColor("#f8fafc")),
                ("BACKGROUND",    (0, 3), (-1, 3), colors.HexColor("#eff6ff")),
                ("FONTNAME",      (1, 3), (1, 3),  "Helvetica-Bold"),
                ("TEXTCOLOR",     (1, 3), (1, 3),  colors.HexColor("#1e40af")),
                ("BACKGROUND",    (0, 4), (-1, 4), colors.HexColor("#f0fdf4")),
                ("FONTNAME",      (1, 4), (1, 4),  "Helvetica-Bold"),
                ("TEXTCOLOR",     (1, 4), (1, 4),  colors.HexColor("#15803d")),
            ]))
            elems.append(val_tbl)
            if not is_intermitente:
                mmVmm[_cod_sal_mes] = l["sal_mes"]

            # ── etapa 2 — admissão no mês ────────────────
            dias_antes_admissao = 0
            if len(dtadm_raw) == 8 and dtadm_raw[:6] == anomes:
                dias_antes_admissao = int(dtadm_raw[6:8]) - 1
                txt_e2 = (f"ETAPA 0002 — ADMISSÃO NO MÊS DA FOLHA"
                          f"   Admitido em {_d_br(dtadm_raw)}"
                          f"  —  {dias_antes_admissao} "
                          f"{'dia' if dias_antes_admissao == 1 else 'dias'} anteriores à admissão")
            else:
                txt_e2 = "ETAPA 0002 — ADMISSÃO NO MÊS DA FOLHA   Não é o caso"
            e2_adm = Table([[Paragraph(txt_e2, st_etapa)]], colWidths=[16*cm])
            e2_adm.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 4),
            ]))
            elems.append(e2_adm)

            # ── etapa 3 ─────────────────────────────────
            afast_func  = afastamentos.get(matr, [])
            ferias_func = ferias.get(matr, [])
            # 5 colunas: Motivo | Início | Final | Dias Atestado/Férias | Dias INSS
            e2_rows  = [[Paragraph("ETAPA 0003 — CÁLCULO DOS DIAS TRABALHADOS", st_etapa), "", "", "", ""]]
            e2_spans = [("SPAN", (0, 0), (4, 0))]

            # 2.1 — Afastamentos
            if afast_func:
                e2_rows.append([Paragraph("3.1 — Verificação de Afastamentos", st_detalhe), "", "", "", ""])
                e2_spans.append(("SPAN", (0, len(e2_rows)-1), (4, len(e2_rows)-1)))
                atestado_acum = 0
                for af in afast_func:
                    di_raw_orig = af.get("data1i") or ""
                    df_raw      = af.get("data1f") or ""
                    di  = _d_br(di_raw_orig)
                    df  = _d_br(df_raw) or "em aberto"
                    mot = af.get("op2") or ""
                    obs = af.get("campotxt4") or ""
                    if obs:
                        df += f"  Obs: {obs}"
                    d_atst, d_inss, _ = _split_afast_mes(di_raw_orig, df_raw, dt_ini_c, dt_fim_c, atestado_acum)
                    if d_atst is not None:
                        atestado_acum += d_atst
                        cel_atst = Paragraph(f"Dias de Atestado= {d_atst}", st_detalhe)
                        cel_inss = Paragraph(f"Dias pelo INSS= {d_inss}", st_detalhe)
                    else:
                        cel_atst = cel_inss = Paragraph("", st_detalhe)
                    e2_rows.append([
                        Paragraph(f"Motivo: {mot}", st_detalhe),
                        Paragraph(f"Início: {di}", st_detalhe),
                        Paragraph(f"Final: {df}", st_detalhe),
                        cel_atst, cel_inss,
                    ])
            else:
                row_idx = len(e2_rows)
                e2_rows.append([Paragraph(
                    "3.1 — Verificação de Afastamentos   Sem afastamentos no período.",
                    st_detalhe), "", "", "", ""])
                e2_spans.append(("SPAN", (0, row_idx), (4, row_idx)))

            # 2.2 — Férias
            if ferias_func:
                e2_rows.append([Paragraph("3.2 — Verificação de Férias", st_detalhe), "", "", "", ""])
                e2_spans.append(("SPAN", (0, len(e2_rows)-1), (4, len(e2_rows)-1)))
                for fer in ferias_func:
                    di1 = fer.get("data1i") or ""; df1 = fer.get("data1f") or ""
                    total_f = _dias_no_mes(di1, df1, dt_ini_c, dt_fim_c) or 0
                    e2_rows.append([
                        "",
                        Paragraph(f"Início: {_d_br(di1)}", st_detalhe),
                        Paragraph(f"Final: {_d_br(df1) or 'em aberto'}", st_detalhe),
                        Paragraph(f"Dias de Férias= {total_f}", st_detalhe),
                        "",
                    ])
            else:
                row_idx = len(e2_rows)
                e2_rows.append([Paragraph(
                    "3.2 — Verificação de Férias   Sem férias no período.",
                    st_detalhe), "", "", "", ""])
                e2_spans.append(("SPAN", (0, row_idx), (4, row_idx)))

            # 2.3 — Totalização dos dias trabalhados
            dias_mes = _dias_no_mes_total(anomes)
            dias_atestado_total = 0
            dias_inss_total = 0
            for af in afast_func:
                _da, _di, _ = _split_afast_mes(
                    af.get("data1i") or "", af.get("data1f") or "",
                    dt_ini_c, dt_fim_c, dias_atestado_total)
                dias_atestado_total += (_da or 0)
                dias_inss_total += (_di or 0)
            dias_ferias_total = sum(
                _dias_no_mes(fer.get("data1i") or "", fer.get("data1f") or "", dt_ini_c, dt_fim_c) or 0
                for fer in ferias_func)
            dias_trabalhados = max(0, dias_mes - dias_antes_admissao - dias_atestado_total - dias_inss_total - dias_ferias_total)
            tot23_idx = len(e2_rows)
            def _d(n, palavra="dia"):
                return f"{n} {palavra}" if n == 1 else f"{n} {palavra}s"
            partes23 = f"( {dias_mes} dias do mês"
            if dias_antes_admissao > 0:
                partes23 += f" - {_d(dias_antes_admissao)} antes admissão"
            partes23 += (f" - {_d(dias_atestado_total)} atestado"
                         f" - {_d(dias_inss_total)} INSS"
                         f" - {_d(dias_ferias_total)} de férias )")
            linha23 = f"3.3 - Dias Trabalhados no Mês = <b>{dias_trabalhados}</b>   {partes23}"
            e2_rows.append([Paragraph(linha23, st_detalhe), "", "", "", ""])
            e2_spans.append(("SPAN", (0, tot23_idx), (4, tot23_idx)))

            pad_row = 1.5 if (len(afast_func) + len(ferias_func)) > 1 else 2
            etapa2_tbl = Table(e2_rows, colWidths=[2*cm, 3.25*cm, 3.25*cm, 4.25*cm, 3.25*cm])
            etapa2_tbl.setStyle(TableStyle([
                *e2_spans,
                ("VALIGN",        (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
                ("TOPPADDING",    (0, 0), (0, 0), 10),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (-1, -1), pad_row),
                ("BOTTOMPADDING", (0, 1), (-1, -1), pad_row),
            ]))
            elems.append(etapa2_tbl)

            # ── etapa 4 — salário proporcional ────────────────
            _st_e4_zero2 = TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 4),
            ])
            if is_intermitente:
                e4_tbl = Table([[Paragraph(
                    "ETAPA 0004 — CÁLCULO DO SALÁRIO PROPORCIONAL"
                    "   Não aplicável — Intermitente (Cat. 111). Remuneração via Verba 003.",
                    st_etapa)]], colWidths=[16*cm])
                e4_tbl.setStyle(_st_e4_zero2)
            elif dias_trabalhados == 0:
                mmVmm[_cod_sal_mes] = 0
                mmVmm[2] = 0.0
                mmQmm[2] = 0
                e4_tbl = Table([[Paragraph(
                    "ETAPA 0004 — CÁLCULO DO SALÁRIO PROPORCIONAL"
                    "   Rubrica 0002 = ZERO — Porque a quantidade de dias trabalhados = Zero",
                    st_etapa)]], colWidths=[16*cm])
                e4_tbl.setStyle(_st_e4_zero2)
            elif dias_ferias_total >= 30:
                # 30 dias de férias = salário mensal completo pela convenção de 30 dias (CLT)
                # Mês de 31 dias com 30 dias de férias: o dia restante já foi coberto nas férias
                mmVmm[_cod_sal_mes] = 0
                mmVmm[2] = 0.0
                mmQmm[2] = 0
                e4_tbl = Table([[Paragraph(
                    "ETAPA 0004 — CÁLCULO DO SALÁRIO PROPORCIONAL"
                    f"   Rubrica 0002 = ZERO — Férias de {dias_ferias_total} dias já cobrem o salário mensal completo (convenção 30 dias)",
                    st_etapa)]], colWidths=[16*cm])
                e4_tbl.setStyle(_st_e4_zero2)
            elif dias_trabalhados < dias_mes:
                sal_prop = int(l["sal_mes"] * dias_trabalhados / dias_mes)
                mmVmm[_cod_sal_mes] = 0
                mmVmm[2] = sal_prop
                mmQmm[2] = dias_trabalhados
                _st_op2 = ParagraphStyle("op4b", fontName="Helvetica", fontSize=7,
                                         alignment=1, textColor=colors.HexColor("#374151"))
                _cw4b = [2.8*cm, 0.4*cm, 2.2*cm, 0.4*cm, 2.3*cm, 0.4*cm, 1.8*cm]
                form_tbl2 = Table([
                    [Paragraph("Salário Proporcional", st_formula),
                     Paragraph("=", _st_op2),
                     Paragraph("Salário Mensal", st_formula),
                     Paragraph("×", _st_op2),
                     Paragraph("Dias Trabalhados", _st_op2),
                     Paragraph("/", _st_op2),
                     Paragraph("Dias do Mês", _st_op2)],
                    [Paragraph(_fmt_brl(sal_prop), st_formula),
                     Paragraph("=", _st_op2),
                     Paragraph(l["sal_mes_fmt"], st_formula),
                     Paragraph("×", _st_op2),
                     Paragraph(str(dias_trabalhados), _st_op2),
                     Paragraph("/", _st_op2),
                     Paragraph(str(dias_mes), _st_op2)],
                ], colWidths=_cw4b)
                form_tbl2.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 1),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1),
                ]))
                e4_tbl = Table([
                    [Paragraph("ETAPA 0004 — CÁLCULO DO SALÁRIO PROPORCIONAL", st_etapa)],
                    [form_tbl2],
                ], colWidths=[16*cm])
                e4_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 8),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (0, 1), 2),
                    ("BOTTOMPADDING", (0, 1), (0, 1), 4),
                ]))
            else:
                e4_tbl = Table([[Paragraph(
                    "ETAPA 0004 — CÁLCULO DO SALÁRIO PROPORCIONAL   Não é o caso — mês completo trabalhado",
                    st_etapa)]], colWidths=[16*cm])
                e4_tbl.setStyle(_st_e4_zero2)
            elems.append(e4_tbl)

            # ── etapa 5 — faltas no mês ────────────────────
            faltas_func  = faltas.get(matr, [])
            val_dia_f    = 0.0 if is_intermitente else (l["sal_mes"] / dias_mes if dias_mes else 0.0)
            qty_inj      = sum(1 for ft in faltas_func if ft.get("op2") == 1)
            val_falta    = int(val_dia_f * qty_inj)
            mmQmm[139]   = qty_inj
            mmVmm[139]   = val_falta
            if faltas_func:
                e5_rows  = [[Paragraph("ETAPA 0005 — FALTAS NO MÊS", st_etapa), "", ""]]
                e5_spans = [("SPAN", (0, 0), (2, 0))]
                for ft in faltas_func:
                    is_inj = ft.get("op2") == 1
                    tp  = "Injustificada" if is_inj else "Justificada"
                    mot = ft.get("campotxt4") or ""
                    e5_rows.append([
                        Paragraph(f"Data: {_d_br(ft.get('data1i') or '')}", st_detalhe),
                        Paragraph(f"Tipo: {tp}", st_detalhe),
                        Paragraph(f"Motivo: {mot}" if mot else "", st_detalhe),
                    ])
                _st_op5 = ParagraphStyle("op5b", fontName="Helvetica", fontSize=7,
                                         alignment=1, textColor=colors.HexColor("#374151"))
                form5 = Table([
                    [Paragraph("0139-FALTAS", st_detalhe),
                     Paragraph("=", _st_op5),
                     Paragraph("Salário Mensal", st_detalhe),
                     Paragraph("/", _st_op5),
                     Paragraph("Dias do Mês", _st_op5),
                     Paragraph("×", _st_op5),
                     Paragraph("Faltas", _st_op5)],
                    [Paragraph(_fmt_brl(val_falta), st_detalhe),
                     Paragraph("=", _st_op5),
                     Paragraph(l["sal_mes_fmt"], st_detalhe),
                     Paragraph("/", _st_op5),
                     Paragraph(str(dias_mes), _st_op5),
                     Paragraph("×", _st_op5),
                     Paragraph(str(qty_inj), _st_op5)],
                ], colWidths=[2.5*cm, 0.4*cm, 2.5*cm, 0.4*cm, 2.0*cm, 0.4*cm, 1.5*cm])
                form5.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 1),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1),
                ]))
                idx51b = len(e5_rows)
                e5_rows.append([form5, "", ""])
                e5_spans.append(("SPAN", (0, idx51b), (2, idx51b)))
                qty_just = len(faltas_func) - qty_inj
                if qty_just > 0:
                    _dj = "dia" if qty_just == 1 else "dias"
                    idx52 = len(e5_rows)
                    e5_rows.append([Paragraph(
                        f"5.2 - Justificadas: {qty_just} {_dj}   Sem desconto — não incluídas na Rubrica 139",
                        st_detalhe), "", ""])
                    e5_spans.append(("SPAN", (0, idx52), (2, idx52)))
            else:
                e5_rows  = [[Paragraph("ETAPA 0005 — FALTAS NO MÊS   Sem faltas no mês.", st_etapa), "", ""]]
                e5_spans = [("SPAN", (0, 0), (2, 0))]
            e5_tbl = Table(e5_rows, colWidths=[4*cm, 4*cm, 8*cm])
            e5_tbl.setStyle(TableStyle([
                *e5_spans,
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
                ("TOPPADDING",    (0, 0), (0, 0), 10),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (-1, -1), 1.5),
                ("BOTTOMPADDING", (0, 1), (-1, -1), 1.5),
            ]))
            elems.append(e5_tbl)

            # ── rodapé ────────────────────────────────────
            elems.append(Spacer(1, 1*cm))
            elems.append(Paragraph(
                f"Gerado em {agora}  |  Usuario: {usuario}  |  Folha10 Simples {versao}",
                st_rod))

            doc.build(elems)
            _salvar_memoria_pdf(dest, nome_f, buf.getvalue())
            salvos.append(nome_f)

        except Exception as e:
            erros.append({"matricula": matr, "nome": l["nome"], "erro": str(e)})

    return jsonify({
        "ok":    len(erros) == 0,
        "pasta": dest.get("label", ""),
        "total": len(salvos),
        "salvos": salvos,
        "erros":  erros,
    })


# =========================================================
# RESUMO DA FOLHA
# =========================================================
def _resumo_folha_dados(id_empresa, id_cliente, anomes, anomes_tipo):
    """Retorna dict com todos os dados agregados do resumo da folha."""
    # ── Rubricas ──
    # Não filtra situacao: rubricas inativas que tenham movimento no período
    # também precisam ter nome correto. Quando há vários registros para o mesmo
    # cod_rubr (cliente específico + padrão id_cliente=0), o do cliente sobrescreve.
    # Pagina em blocos: Supabase corta em 1000 linhas/chamada por padrão.
    rubr_map = {}
    for cli_id in ([0] + ([id_cliente] if id_cliente else [])):
        offset = 0
        page_sz = 1000
        while True:
            try:
                r_rubr = (supabase.table("tab_rubrica")
                          .select("cod_rubr,dsc_rubr,tp_rubr,tpn_inc_cp,tpn_inc_irrf,tpn_inc_fgts")
                          .eq("id_cliente", cli_id)
                          .range(offset, offset + page_sz - 1)
                          .execute())
                rows = r_rubr.data or []
            except Exception:
                rows = []
            for rb in rows:
                cod = int(rb.get("cod_rubr") or 0)
                if not cod:
                    continue
                rubr_map[cod] = {
                    "dsc":      str(rb.get("dsc_rubr")     or f"Verba {cod:04d}"),
                    "tp":       str(rb.get("tp_rubr")      or "1"),
                    "inc_cp":   str(rb.get("tpn_inc_cp")   or ""),
                    "inc_irrf": str(rb.get("tpn_inc_irrf") or ""),
                    "inc_fgts": str(rb.get("tpn_inc_fgts") or ""),
                }
            if len(rows) < page_sz:
                break
            offset += page_sz
    rubr_map.setdefault(101, {"dsc": "INSS",              "tp": "2", "inc_cp": "", "inc_irrf": "", "inc_fgts": ""})
    rubr_map.setdefault(102, {"dsc": "INSS CONT.INDIVIDUAL", "tp": "2", "inc_cp": "", "inc_irrf": "", "inc_fgts": ""})
    rubr_map.setdefault(120, {"dsc": "IRRF",              "tp": "2", "inc_cp": "", "inc_irrf": "", "inc_fgts": ""})
    rubr_map.setdefault(139, {"dsc": "FGTS Provisionado", "tp": "2", "inc_cp": "", "inc_irrf": "", "inc_fgts": ""})

    # ── Movimento do mês ──
    try:
        r_mov = (supabase.table("tab_mov")
                 .select("cod_verba,valor,matricula")
                 .eq("id_empresa", id_empresa)
                 .eq("folha", int(anomes))
                 .eq("folha_tipo", anomes_tipo)
                 .eq("situacao", "A")
                 .execute())
        mov_rows = r_mov.data or []
    except Exception:
        mov_rows = []

    totais = {}
    todas_mats = set()
    emp_fgts_base = {}   # {matricula: base FGTS em centavos}
    emp_fgts139   = {}   # {matricula: valor rubrica 139 em centavos}
    emp_base_cp   = {}   # {matricula: base INSS (inc_cp=11) em centavos}
    emp_inss      = {}   # {matricula: INSS retido (rubrica 101) em centavos}
    emp_inss102   = {}   # {matricula: INSS pró-labore (rubrica 102) em centavos}
    for rec in mov_rows:
        cod = int(rec.get("cod_verba") or 0)
        val = int(rec.get("valor")     or 0)
        mat = rec.get("matricula")
        todas_mats.add(mat)
        if cod not in totais:
            totais[cod] = {"valor": 0, "mats": set()}
        totais[cod]["valor"] += val
        totais[cod]["mats"].add(mat)
        rb_cod = rubr_map.get(cod, {})
        # inc_fgts: "11" = incide integral; "S" = adiantamento do 13º (verba 17).
        if rb_cod.get("tp") == "1" and rb_cod.get("inc_fgts") in ("11", "S"):
            emp_fgts_base[mat] = emp_fgts_base.get(mat, 0) + val
        if rb_cod.get("tp") == "1" and rb_cod.get("inc_cp") == "11":
            emp_base_cp[mat] = emp_base_cp.get(mat, 0) + val
        if cod == 139:
            emp_fgts139[mat] = emp_fgts139.get(mat, 0) + val
        # 101 = INSS do empregado; 102 = INSS do contribuinte individual
        # (pró-labore). Cada um alimenta o seu quadro.
        if cod == 101:
            emp_inss[mat] = emp_inss.get(mat, 0) + val
        if cod == 102:
            emp_inss102[mat] = emp_inss102.get(mat, 0) + val

    proventos = []
    descontos = []
    informativas = []        # cod > 9900 — não entram nos totais
    total_prov = total_desc = base_inss = base_irrf = base_fgts = 0

    for cod, agg in sorted(totais.items()):
        val     = agg["valor"]
        n_funcs = len(agg["mats"])
        rb      = rubr_map.get(cod, {"dsc": f"Verba {cod:04d}", "tp": "1",
                                     "inc_cp": "", "inc_irrf": "", "inc_fgts": ""})
        linha = {"cod": f"{cod:04d}", "dsc": rb["dsc"], "tp": rb["tp"],
                 "valor_c": val, "valor_fmt": _fmt_brl(val), "n_funcs": n_funcs}
        if cod > 9900:
            informativas.append(linha)
            continue
        if rb["tp"] == "1":
            proventos.append(linha)
            total_prov += val
            if rb["inc_cp"]   == "11": base_inss += val
            if rb["inc_irrf"] == "11": base_irrf += val
            if rb["inc_fgts"] in ("11", "S"): base_fgts += val
        else:
            descontos.append(linha)
            total_desc += val

    liquido  = total_prov - total_desc
    inss_val = totais.get(101, {}).get("valor", 0)
    irrf_val = totais.get(120, {}).get("valor", 0)
    fgts_val = totais.get(139, {}).get("valor", 0)

    # ── Split por categoria: Menor Aprendiz (103) e Contribuintes
    #    Individuais / diretores (700-799, pró-labore) ──
    mats_aprendiz = set()
    mats_ci       = set()
    if todas_mats:
        try:
            r_cat = (supabase.table("tab_cad")
                     .select("matricula,codcateg")
                     .eq("id_empresa", id_empresa)
                     .in_("matricula", list(todas_mats))
                     .execute())
            for row in (r_cat.data or []):
                cat = str(row.get("codcateg") or "").strip()
                if cat == "103":
                    mats_aprendiz.add(row.get("matricula"))
                if cat.isdigit() and 700 <= int(cat) <= 799:
                    mats_ci.add(row.get("matricula"))
        except Exception as e:
            print(f"[resumo_folha] falha ao ler categorias em tab_cad: {e}")

    # Rede de segurança: quem tem a rubrica 102 é CI mesmo que o codcateg
    # esteja em branco no cadastro.
    mats_ci |= set(emp_inss102.keys())

    # O quadro "INSS — Empregado" soma só categorias < 700. O que for CI
    # (diretor/sócio, pró-labore) sai para o quadro próprio.
    base_inss_ci = sum(v for m, v in emp_base_cp.items() if m in mats_ci)
    # O retido do CI vem da rubrica 102 (INSS Cont. Individual); a 101, se
    # houver, também é dele e sai do quadro do empregado.
    inss_ci_101  = sum(v for m, v in emp_inss.items()    if m in mats_ci)
    inss_ci_val  = sum(emp_inss102.values()) + inss_ci_101
    base_inss   -= base_inss_ci
    inss_val    -= inss_ci_101

    base_fgts_8 = sum(v for mat, v in emp_fgts_base.items() if mat not in mats_aprendiz)
    base_fgts_2 = sum(v for mat, v in emp_fgts_base.items() if mat in mats_aprendiz)
    fgts139_8   = sum(v for mat, v in emp_fgts139.items()   if mat not in mats_aprendiz)
    fgts139_2   = sum(v for mat, v in emp_fgts139.items()   if mat in mats_aprendiz)
    fgts8_calc  = (base_fgts_8 * 8) // 100
    fgts2_calc  = (base_fgts_2 * 2) // 100

    def _pct(num, den):
        return f"{num / den * 100:.2f}".replace(".", ",") if den else "0,00"

    # ── Empresa (INSS patronal) ──
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("ind_simples,es08_classtributaria,risco,gps_fpas,gps_fpas_perc,"
                         "gps_saleduc,gps_incra,gps_senai,gps_sesi,"
                         "gps_senac,gps_sesc,gps_sebrae,gps_dpc,gps_senar,"
                         "gps_sest,gps_senat,gps_sesco")
                 .eq("id_empresa", id_empresa)
                 .limit(1).execute())
        emp = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        # Nao engolir calado: se o select quebrar, a empresa vira "Geral" e o
        # patronal aparece indevidamente (foi o que acontecia com class_trib).
        print(f"[resumo_folha] falha ao ler tab_empresa {id_empresa}: {e}")
        emp = {}

    ind_simples = str(emp.get("ind_simples") or "N").upper()
    # A classificacao tributaria do eSocial fica em es08_classtributaria
    # (nao existe coluna class_trib em tab_empresa).
    class_trib  = str(emp.get("es08_classtributaria") or "").zfill(2)
    # Optante pelo Simples Nacional (campo obrigatorio do cadastro) e MEI
    # (classTrib 04) tem a contribuicao patronal, o RAT e os terceiros
    # recolhidos pelo DAS — nada em GPS.
    is_simples_ou_mei = (ind_simples == "S") or (class_trib == "04")
    risco_grau  = int(emp.get("risco") or 0)   # 1=1% 2=2% 3=3%
    rat_pct     = float(risco_grau)             # % numérico direto

    # FAP do ano da folha (op1=34, campotxt1=ano, campotxt2=fator)
    fap_fator = 1.0
    if risco_grau:
        try:
            r_fap = (supabase.table("tab_eventos")
                     .select("campotxt2")
                     .eq("id_empresa", id_empresa)
                     .eq("op1", 34)
                     .eq("campotxt1", anomes[:4])
                     .limit(1).execute())
            if r_fap.data:
                fap_fator = round(float(r_fap.data[0].get("campotxt2") or 1.0), 4)
        except Exception:
            fap_fator = 1.0

    # Base da parte patronal: a CP de 20% incide também sobre o pró-labore dos
    # contribuintes individuais; RAT e terceiros, só sobre empregados.
    base_cp_patronal = base_inss + base_inss_ci

    def _linha_emp(label, pct_float, dec=2, base=None):
        """Monta linha do passo a passo. pct_float em % (ex: 1.5 = 1,5%). dec = casas decimais exibidas."""
        if not pct_float:
            return None
        val_c = round((base_inss if base is None else base) * pct_float / 100)
        return {
            "label": label,
            "pct":   f"{pct_float:.{dec}f}".replace(".", ",") + "%",
            "val":   _fmt_brl(val_c),
            "val_c": val_c,
        }

    inss_emp_linhas = []
    inss_emp_total  = 0

    fpas_perc = float(emp.get("gps_fpas_perc") or 0)

    # Contribuição Patronal (20%) e RAT — nao se aplicam a Simples Nacional
    # nem MEI. Para esses regimes, a contribuicao e recolhida pela DAS, nao
    # pela GPS.
    if not is_simples_ou_mei:
        l = _linha_emp("Contribuição Patronal", 20.0, base=base_cp_patronal)
        if l:
            inss_emp_linhas.append(l)
            inss_emp_total += l["val_c"]

        # RAT ajustado = Grau de Risco × FAP
        rat_ajustado = round(rat_pct * fap_fator, 4)
        if risco_grau and fap_fator != 1.0:
            rat_label = f"RAT — Grau {risco_grau} × FAP {fap_fator:.4f}"
        elif risco_grau:
            rat_label = f"RAT — Grau {risco_grau}"
        else:
            rat_label = "RAT"
        l = _linha_emp(rat_label, rat_ajustado, dec=4)
        if l:
            inss_emp_linhas.append(l)
            inss_emp_total += l["val_c"]

    # Terceiros individuais — somam no total. Para Simples Nacional e MEI,
    # nenhum dos terceiros e devido pela GPS (todos sao recolhidos pela DAS),
    # entao ignoramos o que estiver no cadastro.
    if not is_simples_ou_mei:
        terceiros = [
            ("Salário Educação", "gps_saleduc"), ("INCRA",   "gps_incra"),
            ("SENAI",         "gps_senai"),   ("SESI",    "gps_sesi"),
            ("SENAC",         "gps_senac"),   ("SESC",    "gps_sesc"),
            ("SEBRAE",        "gps_sebrae"),  ("DPC",     "gps_dpc"),
            ("SENAR",         "gps_senar"),   ("SEST",    "gps_sest"),
            ("SENAT",         "gps_senat"),   ("SESCOOP", "gps_sesco"),
        ]
        for label, campo in terceiros:
            pct = float(emp.get(campo) or 0)
            l = _linha_emp(label, pct)
            if l:
                inss_emp_linhas.append(l)
                inss_emp_total += l["val_c"]

    # Simples Nacional / MEI: CP, RAT e terceiros sao substituidos pelo DAS,
    # entao a parte patronal em GPS e zero. Mostramos uma linha explicita em
    # vez de deixar a tabela vazia (parecia falta de cadastro).
    if is_simples_ou_mei:
        inss_emp_linhas.append({
            "label": "Empresa pelo Simples",
            "pct":   "0,00%",
            "val":   _fmt_brl(0),
            "val_c": 0,
        })

    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else anomes
    tipo_desc  = {"N": "Normal", "F": "Férias", "R": "Rescisão",
                  "A": "Adiant. 13º", "1": "13º Salário"}.get(anomes_tipo, anomes_tipo)

    return {
        "anomes_fmt":       anomes_fmt,
        "tipo_desc":        tipo_desc,
        "n_funcionarios":   len(todas_mats),
        "proventos":        proventos,
        "descontos":        descontos,
        "informativas":     informativas,
        "total_prov_c":     total_prov,
        "total_desc_c":     total_desc,
        "liquido_c":        liquido,
        "total_prov":       _fmt_brl(total_prov),
        "total_desc":       _fmt_brl(total_desc),
        "liquido":          _fmt_brl(liquido),
        "liquido_neg":      liquido < 0,
        "base_inss_c":      base_inss,
        "inss_val_c":       inss_val,
        "irrf_val_c":       irrf_val,
        "fgts_val_c":       fgts_val,
        "base_inss":        _fmt_brl(base_inss),
        "inss_val":         _fmt_brl(inss_val),
        "inss_aliq":        _pct(inss_val, base_inss),
        # INSS — Contribuintes Individuais (codCateg 700-799)
        "tem_ci":           len(mats_ci) > 0,
        "n_ci":             len(mats_ci),
        "base_inss_ci":     _fmt_brl(base_inss_ci),
        "inss_ci_val":      _fmt_brl(inss_ci_val),
        "inss_ci_aliq":     _pct(inss_ci_val, base_inss_ci),
        "base_irrf":        _fmt_brl(base_irrf),
        "irrf_val":         _fmt_brl(irrf_val),
        "irrf_aliq":        _pct(irrf_val, base_irrf),
        "tem_aprendiz":     len(mats_aprendiz) > 0,
        "base_fgts_8":      _fmt_brl(base_fgts_8),
        "fgts8_calc":       _fmt_brl(fgts8_calc),
        "fgts8_ok":         abs(fgts139_8 - fgts8_calc) <= 100,
        "fgts8_dif_fmt":    _fmt_brl(abs(fgts139_8 - fgts8_calc)),
        "base_fgts_2":      _fmt_brl(base_fgts_2),
        "fgts2_calc":       _fmt_brl(fgts2_calc),
        "fgts2_ok":         abs(fgts139_2 - fgts2_calc) <= 100,
        "fgts2_dif_fmt":    _fmt_brl(abs(fgts139_2 - fgts2_calc)),
        "fgts_total_calc":  _fmt_brl(fgts8_calc + fgts2_calc),
        # INSS Empresa
        "base_inss_emp":    _fmt_brl(base_cp_patronal),
        "inss_emp_linhas":  inss_emp_linhas,
        "inss_emp_total":   _fmt_brl(inss_emp_total),
        "inss_emp_aliq":    _pct(inss_emp_total, base_cp_patronal),
        "ind_simples":      ind_simples,
        "class_trib":       class_trib,
        "is_simples_ou_mei": is_simples_ou_mei,
        "regime_label": ("MEI" if class_trib == "04"
                         else ("Simples Nacional" if is_simples_ou_mei
                               else "Geral")),
        "gps_fpas":         str(emp.get("gps_fpas") or "—"),
    }


@app.route("/resumo_folha")
def resumo_folha():
    if not session.get("logado"):
        return redirect("/")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    empresa_nm  = str(session.get("empresa_info") or "")
    if not anomes or not id_empresa:
        return redirect("/menu")

    d = _resumo_folha_dados(id_empresa, id_cliente, anomes, anomes_tipo)
    return render_template(
        "F10_Resumo_Folha.html",
        versao   = ler_versao(),
        nome     = session.get("nome", ""),
        empresa  = empresa_nm,
        **d,
    )


@app.route("/resumo_folha_pdf")
def resumo_folha_pdf():
    if not session.get("logado"):
        return redirect("/")
    anomes      = str(session.get("anomes_atual") or "")
    anomes_tipo = str(session.get("anomes_tipo")  or "N")
    id_empresa  = _get_id_empresa()
    id_cliente  = session.get("id_cliente")
    empresa_nm  = str(session.get("empresa_info") or "")
    if not anomes or not id_empresa:
        return "Folha ativa não definida.", 400

    cnpj_fmt   = _fmt_cnpj(str(session.get("cnpj_empresa") or ""))
    d = _resumo_folha_dados(id_empresa, id_cliente, anomes, anomes_tipo)

    # ── ReportLab ──
    buf  = io.BytesIO()
    agora = datetime.now()

    azul   = colors.HexColor("#0b1f3a")
    cinza  = colors.HexColor("#64748b")
    verde  = colors.HexColor("#166534")
    verm   = colors.HexColor("#991b1b")
    borda  = colors.HexColor("#dde3ec")
    fundo  = colors.HexColor("#f8fafc")

    W   = 17.0 * cm
    xL  = 2.0  * cm

    # ── Informação do cálculo (capturada antes do callback) ──
    _qtd_c_rs, _dhc_rs = _get_calc_info(id_empresa, id_cliente, anomes, anomes_tipo)
    if _qtd_c_rs and _dhc_rs:
        _rc_txt_rs = (f"Cálculo n.º {_qtd_c_rs}  —  {_dhc_rs}"
                      f"  —  emitido em {agora.strftime('%d/%m/%Y %H:%M')}")
    else:
        _rc_txt_rs = f"Emitido em {agora.strftime('%d/%m/%Y %H:%M')}"

    # ── Canvas callback — padrão da Folha de Pagamento ──
    def _draw_header(canvas, doc):
        canvas.saveState()
        xR = xL + W
        y1 = A4[1] - 0.55*cm
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#374151"))
        canvas.drawString(xL, y1, f"{cnpj_fmt}  —  {empresa_nm}")
        canvas.drawRightString(xR, y1, agora.strftime("%d/%m/%Y  %H:%M"))
        y2 = y1 - 0.55*cm
        periodo = d["anomes_fmt"]
        if d["tipo_desc"] != "Normal":
            periodo += f"  ·  {d['tipo_desc'].upper()}"
        canvas.setFont("Helvetica-Bold", 12)
        canvas.setFillColor(azul)
        canvas.drawString(xL, y2, f"RESUMO DA FOLHA DE PAGAMENTO  —  {periodo}")
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(cinza)
        canvas.drawRightString(xR, y2, f"Página  {doc.page}")
        canvas.setStrokeColor(azul)
        canvas.setLineWidth(0.8)
        canvas.line(xL, y2 - 0.28*cm, xR, y2 - 0.28*cm)
        # Rodapé: informação do cálculo
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(cinza)
        canvas.drawString(xL, 0.7*cm, _rc_txt_rs)
        canvas.restoreState()

    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=xL, rightMargin=2*cm,
                            topMargin=3.2*cm, bottomMargin=1.8*cm)

    st_secao = ParagraphStyle("psec", fontName="Helvetica-Bold", fontSize=9,
                               spaceBefore=12, spaceAfter=4, textColor=azul)

    larg = doc.width

    def _v(s):
        """Remove o prefixo 'R$ ' de um valor formatado."""
        s = str(s or "")
        return s[3:] if s.startswith("R$ ") else s

    def _tbl_verbas(linhas_v, tp):
        cor_val = verde if tp == "1" else verm
        dados   = [["Cód", "Descrição", "QTD", "Valor Total"]]
        for v in linhas_v:
            dados.append([v["cod"], v["dsc"], str(v["n_funcs"]), _v(v["valor_fmt"])])
        t = Table(dados, colWidths=[1.2*cm, larg-4.4*cm, 1.4*cm, 3.8*cm])
        t.setStyle(TableStyle([
            ("BACKGROUND",   (0,0), (-1,0), fundo),
            ("TEXTCOLOR",    (0,0), (-1,0), cinza),
            ("FONTNAME",     (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,-1), 8),
            ("ALIGN",        (2,0), (-1,-1), "RIGHT"),
            ("ALIGN",        (0,0), (1,-1),  "LEFT"),
            ("LINEBELOW",    (0,0), (-1,0), 0.5, borda),
            ("LINEBELOW",    (0,1), (-1,-1), 0.3, colors.HexColor("#f1f5f9")),
            ("TOPPADDING",   (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",(0,0), (-1,-1), 4),
            ("TEXTCOLOR",    (3,1), (3,-1), cor_val),
            ("FONTNAME",     (3,1), (3,-1), "Helvetica"),
            ("FONTNAME",     (0,1), (0,-1), "Helvetica"),
            ("TEXTCOLOR",    (0,1), (0,-1), cinza),
        ]))
        return t

    def _tbl_trio(label1, val1, sub1, label2, val2, sub2, label3, val3, sub3):
        has_sub = bool(sub1) or bool(sub2) or bool(sub3)
        dados = [[label1, label2, label3], [val1, val2, val3]]
        if has_sub:
            dados.append([sub1, sub2, sub3])
        t = Table(dados, colWidths=[larg/3]*3)
        style = [
            ("FONTNAME",     (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,0), 7),
            ("TEXTCOLOR",    (0,0), (-1,0), cinza),
            ("FONTNAME",     (0,1), (-1,1), "Helvetica-Bold"),
            ("FONTSIZE",     (0,1), (-1,1), 10),
            ("TEXTCOLOR",    (0,1), (-1,1), azul),
            ("ALIGN",        (0,0), (-1,-1), "CENTER"),
            ("VALIGN",       (0,0), (-1,-1), "MIDDLE"),
            ("LINEAFTER",    (0,0), (1,-1), 0.5, borda),
            ("TOPPADDING",   (0,0), (-1,-1), 5),
            ("BOTTOMPADDING",(0,0), (-1,-1), 5),
            ("BOX",          (0,0), (-1,-1), 0.5, borda),
        ]
        if has_sub:
            style += [
                ("FONTNAME",  (0,2), (-1,2), "Helvetica"),
                ("FONTSIZE",  (0,2), (-1,2), 7),
                ("TEXTCOLOR", (0,2), (-1,2), cinza),
            ]
        t.setStyle(TableStyle(style))
        return t

    elems = []

    # Totalizações
    elems.append(Paragraph("TOTALIZAÇÕES", st_secao))
    elems.append(_tbl_trio(
        "FUNCIONÁRIOS", str(d["n_funcionarios"]), "com movimento",
        "TOTAL PROVENTOS", _v(d["total_prov"]), "",
        "TOTAL DESCONTOS", _v(d["total_desc"]), "",
    ))
    liq_label = "LÍQUIDO A PAGAR"
    elems.append(Spacer(1, 0.15*cm))
    t_liq = Table([[liq_label, _v(d["liquido"])]], colWidths=[larg*0.5, larg*0.5])
    t_liq.setStyle(TableStyle([
        ("FONTNAME",     (0,0), (-1,-1), "Helvetica-Bold"),
        ("FONTSIZE",     (0,0), (-1,-1), 10),
        ("TEXTCOLOR",    (0,0), (0,0),  cinza),
        ("TEXTCOLOR",    (1,0), (1,0),  verde if not d["liquido_neg"] else verm),
        ("ALIGN",        (0,0), (0,0),  "LEFT"),
        ("ALIGN",        (1,0), (1,0),  "RIGHT"),
        ("TOPPADDING",   (0,0), (-1,-1), 5),
        ("BOTTOMPADDING",(0,0), (-1,-1), 5),
        ("BOX",          (0,0), (-1,-1), 0.5, borda),
        ("BACKGROUND",   (0,0), (-1,-1), fundo),
    ]))
    elems.append(t_liq)

    # Mesmo grid de colunas da tabela de verbas, para alinhar os totais
    COLS_V = [1.2*cm, larg-4.4*cm, 1.4*cm, 3.8*cm]

    # Proventos
    elems.append(Paragraph("PROVENTOS", st_secao))
    if d["proventos"]:
        elems.append(_tbl_verbas(d["proventos"], "1"))
    t_tp = Table([["", "Total Proventos", "", _v(d["total_prov"])]], colWidths=COLS_V)
    t_tp.setStyle(TableStyle([
        ("FONTNAME",     (0,0), (-1,-1), "Helvetica-Bold"),
        ("FONTSIZE",     (0,0), (-1,-1), 8),
        ("TEXTCOLOR",    (3,0), (3,0), verde),
        ("ALIGN",        (1,0), (1,0), "RIGHT"),
        ("ALIGN",        (3,0), (3,0), "RIGHT"),
        ("TOPPADDING",   (0,0), (-1,-1), 4),
        ("BOTTOMPADDING",(0,0), (-1,-1), 4),
        ("LINEABOVE",    (0,0), (-1,0), 0.8, azul),
    ]))
    elems.append(t_tp)

    # Descontos
    elems.append(Paragraph("DESCONTOS", st_secao))
    if d["descontos"]:
        elems.append(_tbl_verbas(d["descontos"], "2"))
    t_td = Table([["", "Total Descontos", "", _v(d["total_desc"])]], colWidths=COLS_V)
    t_td.setStyle(TableStyle([
        ("FONTNAME",     (0,0), (-1,-1), "Helvetica-Bold"),
        ("FONTSIZE",     (0,0), (-1,-1), 8),
        ("TEXTCOLOR",    (3,0), (3,0), verm),
        ("ALIGN",        (1,0), (1,0), "RIGHT"),
        ("ALIGN",        (3,0), (3,0), "RIGHT"),
        ("TOPPADDING",   (0,0), (-1,-1), 4),
        ("BOTTOMPADDING",(0,0), (-1,-1), 4),
        ("LINEABOVE",    (0,0), (-1,0), 0.8, azul),
    ]))
    elems.append(t_td)

    # Informativas (cód > 9900, não entram nos totais)
    if d.get("informativas"):
        elems.append(Paragraph("VERBAS INFORMATIVAS", st_secao))
        elems.append(Paragraph(
            "<font size=7 color='#64748b'>Códigos &gt; 9900 — não entram nos totais</font>",
            ParagraphStyle("subinf", fontName="Helvetica", fontSize=7,
                           textColor=cinza, spaceAfter=4)))
        roxo = colors.HexColor("#7c3aed")
        dados_inf = [["Cód", "Descrição", "QTD", "Valor Total"]]
        for v in d["informativas"]:
            dados_inf.append([v["cod"], v["dsc"], str(v["n_funcs"]), _v(v["valor_fmt"])])
        t_inf = Table(dados_inf, colWidths=COLS_V)
        t_inf.setStyle(TableStyle([
            ("BACKGROUND",   (0,0), (-1,0), fundo),
            ("TEXTCOLOR",    (0,0), (-1,0), cinza),
            ("FONTNAME",     (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,-1), 8),
            ("ALIGN",        (2,0), (-1,-1), "RIGHT"),
            ("ALIGN",        (0,0), (1,-1),  "LEFT"),
            ("LINEBELOW",    (0,0), (-1,0), 0.5, borda),
            ("LINEBELOW",    (0,1), (-1,-1), 0.3, colors.HexColor("#f1f5f9")),
            ("TOPPADDING",   (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",(0,0), (-1,-1), 4),
            ("TEXTCOLOR",    (3,1), (3,-1), roxo),
            ("FONTNAME",     (3,1), (3,-1), "Helvetica"),
            ("FONTNAME",     (0,1), (0,-1), "Helvetica"),
            ("TEXTCOLOR",    (0,1), (0,-1), cinza),
        ]))
        elems.append(t_inf)

    # INSS — Empregado
    elems.append(Paragraph("RESUMO INSS — EMPREGADO", st_secao))
    elems.append(_tbl_trio(
        "BASE DE CÁLCULO", _v(d["base_inss"]), "verbas com incidência CP",
        "INSS RETIDO (0101)", _v(d["inss_val"]), "cálculo progressivo por faixa",
        "ALÍQUOTA EFETIVA MÉDIA", d["inss_aliq"] + "%", "INSS ÷ base × 100",
    ))

    # INSS — Diretores e Contribuintes Individuais (codCateg 700-799)
    if d.get("tem_ci"):
        elems.append(Paragraph(
            "RESUMO INSS — DIRETORES E CONTRIBUINTES INDIVIDUAIS", st_secao))
        elems.append(Paragraph(
            f"<font size=7 color='#64748b'>Categorias 700–799  ·  {d['n_ci']} pessoa(s)</font>",
            ParagraphStyle("subci", fontName="Helvetica", fontSize=7,
                           textColor=cinza, spaceAfter=4)))
        elems.append(_tbl_trio(
            "BASE DE CÁLCULO", _v(d["base_inss_ci"]), "pró-labore com incidência CP",
            "INSS RETIDO (0102)", _v(d["inss_ci_val"]), "11% até o teto",
            "ALÍQUOTA EFETIVA MÉDIA", d["inss_ci_aliq"] + "%", "INSS ÷ base × 100",
        ))

    # INSS — Empresa (GPS)
    titulo_emp = "RESUMO INSS — EMPRESA (GPS)"
    sub_emp    = f"FPAS {d['gps_fpas']}"
    if d.get("is_simples_ou_mei"):
        sub_emp += (f"  ·  {d['regime_label']} — contribuição patronal, RAT e "
                    f"terceiros recolhidos pelo DAS; nada a recolher em GPS")
    elems.append(Paragraph(titulo_emp, st_secao))
    elems.append(Paragraph(
        f"<font size=7 color='#64748b'>{sub_emp}</font>",
        ParagraphStyle("subemp", fontName="Helvetica", fontSize=7,
                       textColor=cinza, spaceAfter=4)))
    if d["inss_emp_linhas"]:
        dados_emp = [["Componente", "Alíquota", "Valor"]]
        for l in d["inss_emp_linhas"]:
            dados_emp.append([l["label"], l["pct"], _v(l["val"])])
        t_emp = Table(dados_emp, colWidths=[larg-5.5*cm, 1.7*cm, 3.8*cm])
        t_emp.setStyle(TableStyle([
            ("BACKGROUND",   (0,0), (-1,0), fundo),
            ("TEXTCOLOR",    (0,0), (-1,0), cinza),
            ("FONTNAME",     (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,-1), 8),
            ("ALIGN",        (1,0), (-1,-1), "RIGHT"),
            ("ALIGN",        (0,0), (0,-1),  "LEFT"),
            ("LINEBELOW",    (0,0), (-1,0), 0.5, borda),
            ("LINEBELOW",    (0,1), (-1,-1), 0.3, colors.HexColor("#f1f5f9")),
            ("TOPPADDING",   (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",(0,0), (-1,-1), 4),
            ("FONTNAME",     (0,1), (-1,-1), "Helvetica"),
            ("TEXTCOLOR",    (2,1), (2,-1), verde),
        ]))
        elems.append(t_emp)
        t_emp_tot = Table(
            [[f"Total INSS Empresa  (Alíq. Efetiva {d['inss_emp_aliq']}%)",
              _v(d["inss_emp_total"])]],
            colWidths=[larg-3.8*cm, 3.8*cm])
        t_emp_tot.setStyle(TableStyle([
            ("FONTNAME",     (0,0), (-1,-1), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,-1), 8),
            ("TEXTCOLOR",    (0,0), (0,0), cinza),
            ("TEXTCOLOR",    (1,0), (1,0), verde),
            ("ALIGN",        (0,0), (0,0), "RIGHT"),
            ("ALIGN",        (1,0), (1,0), "RIGHT"),
            ("TOPPADDING",   (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",(0,0), (-1,-1), 4),
            ("LINEABOVE",    (0,0), (-1,0), 0.8, azul),
        ]))
        elems.append(t_emp_tot)
    else:
        elems.append(Paragraph(
            "Sem dados de encargos cadastrados na empresa.",
            ParagraphStyle("noenc", fontName="Helvetica-Oblique", fontSize=8,
                           textColor=cinza, alignment=1)))

    # IRRF
    elems.append(Paragraph("RESUMO IRRF", st_secao))
    elems.append(_tbl_trio(
        "BASE BRUTA (inc. IRRF)", _v(d["base_irrf"]), "antes de deduções",
        "IRRF RETIDO (0120)", _v(d["irrf_val"]), "cálculo progressivo por faixa",
        "ALÍQUOTA EFETIVA MÉDIA", d["irrf_aliq"] + "%", "IRRF ÷ base bruta × 100",
    ))

    # FGTS
    elems.append(Paragraph("RESUMO FGTS", st_secao))
    if d["tem_aprendiz"]:
        # 4 células: base8 | fgts8 | base2 | fgts2 — duas linhas de duo
        fgts_dados4 = [
            ["BASE (8%)", "FGTS A RECOLHER 8%", "BASE (2%)", "FGTS A RECOLHER 2%"],
            [_v(d["base_fgts_8"]), _v(d["fgts8_calc"]),
             _v(d["base_fgts_2"]), _v(d["fgts2_calc"])],
        ]
        t4 = Table(fgts_dados4, colWidths=[larg/4]*4)
        t4.setStyle(TableStyle([
            ("FONTNAME",     (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,0), 7),
            ("TEXTCOLOR",    (0,0), (-1,0), cinza),
            ("FONTNAME",     (0,1), (-1,1), "Helvetica-Bold"),
            ("FONTSIZE",     (0,1), (-1,1), 10),
            ("TEXTCOLOR",    (0,1), (-1,1), azul),
            ("ALIGN",        (0,0), (-1,-1), "CENTER"),
            ("VALIGN",       (0,0), (-1,-1), "MIDDLE"),
            ("LINEAFTER",    (0,0), (2,-1), 0.5, borda),
            ("TOPPADDING",   (0,0), (-1,-1), 5),
            ("BOTTOMPADDING",(0,0), (-1,-1), 5),
            ("BOX",          (0,0), (-1,-1), 0.5, borda),
        ]))
        elems.append(t4)
        elems.append(Spacer(1, 0.1*cm))
        t_tot = Table([["TOTAL FGTS A RECOLHER", _v(d["fgts_total_calc"])]],
                      colWidths=[larg*0.5, larg*0.5])
        t_tot.setStyle(TableStyle([
            ("FONTNAME",     (0,0), (-1,-1), "Helvetica-Bold"),
            ("FONTSIZE",     (0,0), (-1,-1), 10),
            ("TEXTCOLOR",    (0,0), (0,0),  cinza),
            ("TEXTCOLOR",    (1,0), (1,0),  azul),
            ("ALIGN",        (0,0), (0,0),  "LEFT"),
            ("ALIGN",        (1,0), (1,0),  "RIGHT"),
            ("TOPPADDING",   (0,0), (-1,-1), 5),
            ("BOTTOMPADDING",(0,0), (-1,-1), 5),
            ("BOX",          (0,0), (-1,-1), 0.5, borda),
            ("BACKGROUND",   (0,0), (-1,-1), fundo),
        ]))
        elems.append(t_tot)
    else:
        elems.append(_tbl_trio(
            "BASE DE CÁLCULO (8%)", _v(d["base_fgts_8"]), "",
            "FGTS A RECOLHER 8%", _v(d["fgts8_calc"]), "",
            "TOTAL FGTS A RECOLHER", _v(d["fgts_total_calc"]), "",
        ))

    doc.build(elems, onFirstPage=_draw_header, onLaterPages=_draw_header)
    buf.seek(0)
    from flask import make_response
    ano, mes = anomes[:4], anomes[4:6]
    nome_arq = f"ResumoFolha_{empresa_nm[:20].replace(' ','_')}_{ano}{mes}.pdf"
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="{nome_arq}"'
    return resp


# =========================================================
# CÁLCULO DE FÉRIAS — TELA DE LISTAGEM
# =========================================================
@app.route("/calc_ferias")
def calc_ferias():
    if not session.get("logado"):
        return redirect("/")

    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    funcionarios = []
    erro_msg     = None

    if not anomes or len(anomes) != 6:
        erro_msg = "Nenhuma Folha Ativa definida. Selecione um mês/ano antes de continuar."
    else:
        try:
            r_ev = (
                supabase.table("tab_eventos")
                .select("matricula, data1i, data1f, ref1, data2i, data2f")
                .eq("id_cliente", id_cliente)
                .eq("id_empresa", id_empresa)
                .eq("op1", 3)
                .gte("data1i", anomes + "01")
                .lte("data1i", anomes + "31")
                .order("matricula")
                .execute()
            )
            eventos = r_ev.data or []

            if eventos:
                mats = list({e["matricula"] for e in eventos})
                r_cad = (
                    supabase.table("tab_cad")
                    .select("matricula, nome, nomer")
                    .eq("id_cliente", id_cliente)
                    .eq("id_empresa", id_empresa)
                    .in_("matricula", mats)
                    .execute()
                )
                nomes = {
                    c["matricula"]: (c.get("nomer") or c.get("nome") or "").strip()
                    for c in (r_cad.data or [])
                }

                def fmt8(s):
                    s = str(s or "")
                    if len(s) == 8:
                        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}"
                    return "—"

                # Busca último cálculo de férias por funcionário (tab_log)
                calc_map = {}
                try:
                    r_log = (supabase.table("tab_log")
                             .select("matricula, data_hora_grava")
                             .eq("id_cliente", id_cliente)
                             .eq("id_empresa", id_empresa)
                             .eq("menu", "CALC_FER")
                             .eq("ano_mes", anomes)
                             .in_("matricula", mats)
                             .order("data_hora_grava", desc=True)
                             .execute())
                    for lg in (r_log.data or []):
                        m = lg.get("matricula")
                        if m and m not in calc_map:
                            calc_map[m] = str(lg.get("data_hora_grava") or "")
                except Exception:
                    pass

                def fmt_dhg(s):
                    # "YYYYMMDD HHMM" → "DD/MM/YYYY HH:MM"
                    s = str(s or "").strip()
                    if len(s) >= 13 and s[8] == " ":
                        return f"{s[6:8]}/{s[4:6]}/{s[0:4]} {s[9:11]}:{s[11:13]}"
                    return ""

                for ev in eventos:
                    mat  = ev["matricula"]
                    dias = int(ev.get("ref1") or 0)
                    if dias == 0 and ev.get("data1i") and ev.get("data1f"):
                        d1 = ev["data1i"]; d2 = ev["data1f"]
                        try:
                            from datetime import date as _d
                            di = _d(int(d1[:4]), int(d1[4:6]), int(d1[6:]))
                            df = _d(int(d2[:4]), int(d2[4:6]), int(d2[6:]))
                            dias = (df - di).days + 1
                        except Exception:
                            pass
                    funcionarios.append({
                        "matricula":   mat,
                        "mat_fmt":     str(mat).zfill(6),
                        "nome":        nomes.get(mat, "—"),
                        "data1i_fmt":  fmt8(ev.get("data1i")),
                        "data1f_fmt":  fmt8(ev.get("data1f")),
                        "data2i_fmt":  fmt8(ev.get("data2i")),
                        "data2f_fmt":  fmt8(ev.get("data2f")),
                        "dias":        dias,
                        "data1i_raw":  str(ev.get("data1i") or ""),
                        "calc_dhg":    fmt_dhg(calc_map.get(mat, "")),
                    })
        except Exception as e:
            erro_msg = f"Erro ao consultar férias: {e}"

    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else ""

    return render_template(
        "F10_Calc_Ferias.html",
        empresa      = session.get("empresa_info", ""),
        nome         = session.get("nome", ""),
        versao       = ler_versao(),
        funcionarios = funcionarios,
        erro_msg     = erro_msg,
        anomes       = anomes,
        anomes_fmt   = anomes_fmt,
    )


def _gerar_memoria_ferias(empresa_nm, cnpj_fmt, anomes, id_empresa, resultados_brutos):
    """Grava PDF de memória de cálculo de férias por funcionário em C:\\Folha10-Simples_Memoria."""
    if not resultados_brutos or len(anomes) != 6:
        return

    anomes_pasta = f"{anomes[:4]}-{anomes[4:6]}"
    dest = _memoria_destino(anomes, id_empresa)   # local (Windows) ou Storage (Render)
    if not dest.get("base"):
        return

    ts = datetime.now().strftime("%Y%m%d_as_%H%M%S")

    st_etapa   = ParagraphStyle("mf_eta",  fontName="Helvetica", fontSize=8,
                                spaceBefore=10, spaceAfter=3, leftIndent=0)
    st_formula = ParagraphStyle("mf_fml",  fontName="Helvetica", fontSize=7,
                                spaceAfter=6, leftIndent=10, textColor=colors.HexColor("#374151"))
    st_detalhe = ParagraphStyle("mf_det",  fontName="Helvetica", fontSize=8,
                                leftIndent=10, textColor=colors.HexColor("#374151"))
    _st_zero = TableStyle([
        ("LEFTPADDING",   (0, 0), (-1, -1), 0),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
        ("TOPPADDING",    (0, 0), (0, 0), 8),
        ("BOTTOMPADDING", (0, 0), (0, 0), 4),
    ])
    _st_op = ParagraphStyle("mf_op", fontName="Helvetica", fontSize=7,
                             alignment=1, textColor=colors.HexColor("#374151"))

    # Mantém só a memória do último cálculo: apaga as memórias de FÉRIAS
    # anteriores desta folha/empresa (não arquiva mais).
    _memoria_apagar(anomes, id_empresa,
                    remover_pred=lambda n: "_Ferias_" in n and n.lower().endswith(".pdf"))

    for r in resultados_brutos:
        mat  = int(r["matricula"])
        nome = r["nome"]
        nome_f  = (f"Folha10_Memoria_Empresa_{int(id_empresa):06d}_Ferias_{anomes}"
                   f"_Matricula_{mat:06d}_em_{ts}.pdf")
        try:
            sal_mes      = int(r["sal_mes"])
            dias         = int(r["dias"])
            dias_abono   = int(r["dias_abono"])
            sal_ferias   = int(r["sal_ferias"])
            terco_const  = int(r["terco_const"])
            abono_val    = int(r["abono_val"])
            terco_abono  = int(r["terco_abono"])
            base_calc    = int(r["base_calc"])
            inss_val     = int(r["inss_val"])
            inss_det     = r.get("inss_det") or []
            ndep         = int(r["ndep"])
            dep_irrf_ded = int(r["dep_irrf_ded"])
            dep_total    = int(r["dep_total"])
            base_irrf    = int(r["base_irrf"])
            irrf_val     = int(r["irrf_val"])
            irrf_info    = r.get("irrf_info")
            total_prov   = int(r["total_prov"])
            total_desc   = int(r["total_desc"])
            liquido      = int(r["liquido"])
            medias_pdf      = r.get("medias_variaveis_pdf") or []
            verbas_med_pesq = r.get("verbas_media_pesquisadas_pdf") or []
            periodo_aq      = r.get("periodo_aq_pdf") or {}
            recs_mov_pdf    = r.get("recs_mov_pdf") or []
            sal_hora_c_pdf  = int(r.get("sal_hora_c_pdf") or 0)
            und_pdf         = str(r.get("und_pdf") or "M").upper()

            buf = io.BytesIO()
            titulo_mem  = f"MEMORIA DE CALCULO — {anomes[4:6]}/{anomes[:4]} — FERIAS — {mat:06d} — {nome}"
            _agora_hf   = datetime.now().strftime("%d/%m/%Y %H:%M")
            _emp_hf     = f"{cnpj_fmt} — {empresa_nm}"

            def _draw_hdr_ferias(canvas, doc,
                                 _t=titulo_mem, _a=_agora_hf, _e=_emp_hf):
                _pdf_num_pagina(canvas, doc)
                canvas.saveState()
                xL = doc.leftMargin
                xR = xL + 17*cm
                y1 = A4[1] - 0.60*cm
                canvas.setFont("Helvetica", 8)
                canvas.setFillColor(colors.HexColor("#374151"))
                canvas.drawString(xL, y1, _e)
                canvas.drawRightString(xR, y1, f"Calculado em {_a}")
                y2 = y1 - 0.50*cm
                canvas.setFont("Helvetica-Bold", 8)
                canvas.drawCentredString(xL + 8.5*cm, y2, _t)
                canvas.setStrokeColor(colors.HexColor("#374151"))
                canvas.setLineWidth(0.5)
                canvas.line(xL, y2 - 0.28*cm, xR, y2 - 0.28*cm)
                canvas.restoreState()

            doc = SimpleDocTemplate(buf, pagesize=A4,
                                    leftMargin=2*cm, rightMargin=2*cm,
                                    topMargin=2.8*cm, bottomMargin=1.5*cm)
            elems = []

            # ── etapa 2 — período de férias ────────────────────────────
            abono_txt = (f"   Abono Pecuniario: {dias_abono} dias" if dias_abono
                         else "   Sem abono pecuniario")
            e2_tbl = Table([
                [Paragraph("ETAPA 0001 - PERIODO DE FERIAS", st_etapa)],
                [Paragraph(
                    f"Periodo: {r.get('data1i_fmt','—')} a {r.get('data1f_fmt','—')}"
                    f"   Dias de Ferias: {dias}{abono_txt}", st_detalhe)],
            ], colWidths=[17*cm])
            e2_tbl.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (0, 1), 0),
                ("BOTTOMPADDING", (0, 1), (0, 1), 4),
            ]))
            elems.append(e2_tbl)

            # ── etapa 3 — médias das verbas variáveis ─────────────────
            _METODO_LABELS = {
                "MAP": "MAP-Periodo Aquisitivo",
                "M12": "M12-Ultimos 12 Meses",
                "MAN": "MAN-Media do Ano",
            }
            e7_rows = [[Paragraph("ETAPA 0002 - MEDIAS DAS VERBAS VARIAVEIS", st_etapa)]]
            if not verbas_med_pesq:
                e7_rows.append([Paragraph(
                    "Nenhuma verba com incidencia em Ferias (inc_ferias = MAP/M12/MAN) cadastrada.",
                    st_detalhe)])
            else:
                _st_v7h   = ParagraphStyle("mf_v7h",   fontName="Helvetica", fontSize=6,
                                           leading=7, textColor=colors.HexColor("#374151"))
                _st_mdate = ParagraphStyle("mf_mdate", fontName="Helvetica", fontSize=5,
                                           leading=6, textColor=colors.HexColor("#374151"))
                _st_mval  = ParagraphStyle("mf_mval",  fontName="Helvetica", fontSize=5,
                                           leading=6, alignment=2, textColor=colors.HexColor("#374151"))
                _st_mline = ParagraphStyle("mf_mline", fontName="Helvetica", fontSize=5,
                                           leading=6, leftIndent=20,
                                           textColor=colors.HexColor("#374151"))
                _sub_m_ts = TableStyle([
                    ("LEFTPADDING",   (0, 0), (0, 0), 20),
                    ("RIGHTPADDING",  (0, 0), (0, 0), 6),
                    ("LEFTPADDING",   (1, 0), (1, 0), 0),
                    ("RIGHTPADDING",  (1, 0), (1, 0), 0),
                    ("TOPPADDING",    (0, 0), (-1, -1), 0),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
                    ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
                ])
                cods_encontrados = {m7["cod"] for m7 in medias_pdf}
                for v7 in verbas_med_pesq:
                    metodo7 = v7.get("metodo", "MAP")
                    mlbl7   = _METODO_LABELS.get(metodo7, metodo7)
                    cod7    = v7["cod"]
                    dsc7    = v7["dsc"]
                    if cod7 in cods_encontrados:
                        m7   = next(m for m in medias_pdf if m["cod"] == cod7)
                        fi_f = m7.get("fi_fmt", "—")
                        ff_f = m7.get("ff_fmt", "—")
                        maq  = m7.get("meses", 0)
                        por_mes7 = m7.get("por_mes") or []
                        e7_rows.append([Paragraph(
                            f"  {cod7:04d} - {dsc7}  [{mlbl7} — {fi_f} a {ff_f} / {maq} meses]",
                            _st_v7h)])
                        if m7.get("tipo") == "H":
                            sh   = m7.get("sal_hora_c", 0)
                            tmin = m7.get("total_min", 0)
                            amin = m7.get("avg_min", 0)
                            ah, am_h = amin // 60, amin % 60
                            vmes_h   = round(amin * sh / 60)
                            for fol, dados in por_mes7:
                                q = dados.get("qtd", 0)
                                qh, qm = q // 60, q % 60
                                s_fol = str(fol)
                                fol_fmt = f"{s_fol[4:6]}/{s_fol[:4]}" if len(s_fol) == 6 else str(fol)
                                sub = Table([[Paragraph(fol_fmt, _st_mdate),
                                              Paragraph(f"{q} min ({qh:02d}:{qm:02d}h)", _st_mval)]],
                                            colWidths=[1.8*cm, 2.2*cm])
                                sub.setStyle(_sub_m_ts)
                                e7_rows.append([sub])
                            e7_rows.append([Paragraph(
                                f'Total: {tmin} min / {maq} meses = {amin} min/mes ({ah:02d}:{am_h:02d}h)'
                                f'  x  {_fmt_brl(sh)[3:]}/h / 60 = {_fmt_brl(vmes_h)[3:]}/mes'
                                f'  x  {dias} dias / 30 = {_fmt_brl(m7["val"])[3:]}',
                                _st_mline)])
                        else:
                            total_aq7 = m7.get("total_aq", 0)
                            for fol, dados in por_mes7:
                                v = dados.get("valor", 0)
                                s_fol = str(fol)
                                fol_fmt = f"{s_fol[4:6]}/{s_fol[:4]}" if len(s_fol) == 6 else str(fol)
                                sub = Table([[Paragraph(fol_fmt, _st_mdate),
                                              Paragraph(_fmt_brl(v)[3:], _st_mval)]],
                                            colWidths=[1.8*cm, 2.2*cm])
                                sub.setStyle(_sub_m_ts)
                                e7_rows.append([sub])
                            e7_rows.append([Paragraph(
                                f'Total {_fmt_brl(total_aq7)[3:]} / {maq} meses'
                                f' = {_fmt_brl(m7["media_mes"])[3:]}/mes'
                                f' x {dias} dias/30 = {_fmt_brl(m7["val"])[3:]}',
                                _st_mline)])
                    else:
                        e7_rows.append([Paragraph(
                            f"  {cod7:04d} - {dsc7}  [{mlbl7}]:   Sem lancamentos no periodo",
                            _st_v7h)])
            e7_tbl = Table(e7_rows, colWidths=[17*cm])
            e7_tbl.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("LEFTPADDING",   (0, 1), (-1, -1), 10),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (-1, -1), 1),
                ("BOTTOMPADDING", (0, 1), (-1, -1), 1),
                ("LEFTPADDING",   (0, 0), (0, 0), 0),
            ]))
            elems.append(e7_tbl)

            # ── etapa 4 — lançamentos digitados ──────────────────────────
            _st_lbl9 = ParagraphStyle("mf_l9", fontName="Helvetica", fontSize=7,
                                      alignment=0, textColor=colors.HexColor("#374151"))
            _st_val9 = ParagraphStyle("mf_v9", fontName="Helvetica", fontSize=7,
                                      alignment=2, textColor=colors.HexColor("#374151"))
            _st_hdr9 = ParagraphStyle("mf_h9", fontName="Helvetica-Bold", fontSize=7,
                                      alignment=1, textColor=colors.HexColor("#374151"))
            if recs_mov_pdf:
                e9_det_rows = [[
                    Paragraph("Cod.", _st_hdr9),
                    Paragraph("Descricao", _st_hdr9),
                    Paragraph("Qtd", _st_hdr9),
                    Paragraph("Valor (R$)", _st_hdr9),
                ]]
                for r9 in recs_mov_pdf:
                    e9_det_rows.append([
                        Paragraph(f"{r9['cod_verba']:04d}", _st_lbl9),
                        Paragraph(r9["dsc"], _st_lbl9),
                        Paragraph(str(r9["qtd"]) if r9["qtd"] else "—", _st_val9),
                        Paragraph(_fmt_brl(r9["valor"]), _st_val9),
                    ])
                e9_det = Table(e9_det_rows, colWidths=[1.5*cm, 10*cm, 2*cm, 3.5*cm])
                e9_det.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 2),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1),
                    ("LINEBELOW",     (0, 0), (-1, 0), 0.3, colors.HexColor("#94a3b8")),
                ]))
                e9_tbl = Table([
                    [Paragraph("ETAPA 0003 - LANCAMENTOS DIGITADOS PARA ESSA FERIAS", st_etapa)],
                    [e9_det],
                ], colWidths=[17*cm])
                e9_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("LEFTPADDING",   (0, 1), (0, 1), 10),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 10),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (0, 1), 2),
                    ("BOTTOMPADDING", (0, 1), (0, 1), 4),
                ]))
            else:
                e9_tbl = Table([
                    [Paragraph("ETAPA 0003 - LANCAMENTOS DIGITADOS PARA ESSA FERIAS", st_etapa)],
                    [Paragraph("Nao houve Lancamentos Digitados para essa Ferias.", st_detalhe)],
                ], colWidths=[17*cm])
                e9_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("LEFTPADDING",   (0, 1), (-1, -1), 10),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 8),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (-1, -1), 2),
                    ("BOTTOMPADDING", (0, 1), (-1, -1), 4),
                ]))
            elems.append(e9_tbl)

            # ── etapa 5 — base de cálculo consolidada ──────────────────
            _soma_medias9a = sum(m.get("val", 0) for m in medias_pdf)
            _st_det5 = ParagraphStyle("mf_d5", fontName="Helvetica", fontSize=6,
                                      leftIndent=10, textColor=colors.HexColor("#374151"))
            e9a_rows = [[Paragraph(
                "ETAPA 0004 - BASE DE CALCULO CONSOLIDADA (INSS / IRRF / FGTS)", st_etapa)]]
            e9a_rows.append([Paragraph(
                f"Ferias ({dias} dias): {_fmt_brl(sal_ferias)}"
                f"   = {_fmt_brl(sal_mes)} x {dias} / 30", _st_det5)])
            e9a_rows.append([Paragraph(
                f"1/3 Constitucional:        {_fmt_brl(terco_const)}"
                f"   = {_fmt_brl(sal_ferias)} / 3", _st_det5)])
            for m9a in medias_pdf:
                e9a_rows.append([Paragraph(
                    f"Media {m9a['cod']:04d} {m9a.get('dsc', '')}:   {_fmt_brl(m9a['val'])}",
                    _st_det5)])
            _bc_formula9a = f"{_fmt_brl(sal_ferias)} + {_fmt_brl(terco_const)}"
            if _soma_medias9a:
                _bc_formula9a += f" + Medias {_fmt_brl(_soma_medias9a)}"
            e9a_rows.append([Paragraph(
                f"Base de Calculo:           {_fmt_brl(base_calc)}"
                f"   ({_bc_formula9a})", _st_det5)])
            if abono_val:
                e9a_rows.append([Paragraph(
                    f"Abono Pecuniario ({dias_abono} dias): {_fmt_brl(abono_val)}"
                    f"   = {_fmt_brl(sal_mes)} x {dias_abono} / 30   (isento de INSS e IRRF)",
                    _st_det5)])
                e9a_rows.append([Paragraph(
                    f"1/3 sobre Abono: {_fmt_brl(terco_abono)}"
                    f"   = {_fmt_brl(abono_val)} / 3   (isento de INSS e IRRF)",
                    _st_det5)])
            e9a_tbl = Table(e9a_rows, colWidths=[17*cm])
            e9a_tbl.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("LEFTPADDING",   (0, 1), (-1, -1), 10),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (0, 0), 8),
                ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                ("TOPPADDING",    (0, 1), (-1, -1), 2),
                ("BOTTOMPADDING", (0, 1), (-1, -1), 2),
                ("LEFTPADDING",   (0, 0), (0, 0), 0),
            ]))
            elems.append(e9a_tbl)

            # ── etapa 6 — INSS ─────────────────────────────────────────
            _st_op10f = ParagraphStyle("op10f", fontName="Helvetica", fontSize=7,
                                       alignment=1, textColor=colors.HexColor("#374151"))
            if inss_det:
                hdr10f_txt = (f"ETAPA 0005 - INSS (Desconto)"
                              f"   Base: {_fmt_brl(base_calc)}")
                det10f_rows = [[
                    Paragraph("Faixa",      _st_op10f),
                    Paragraph("Ate (R$)",   _st_op10f),
                    Paragraph("Aliq.",      _st_op10f),
                    Paragraph("Base Faixa", _st_op10f),
                    Paragraph("Desconto",   _st_op10f),
                ]]
                for idx10f, (lim10f, pct10f, bf10f, vf10f) in enumerate(inss_det, 1):
                    det10f_rows.append([
                        Paragraph(str(idx10f),               _st_op10f),
                        Paragraph(_fmt_brl(lim10f),          _st_op10f),
                        Paragraph(f"{pct10f/100:g}%",        _st_op10f),
                        Paragraph(_fmt_brl(bf10f),           _st_op10f),
                        Paragraph(_fmt_brl(vf10f),           _st_op10f),
                    ])
                det10f_rows.append([
                    Paragraph("", _st_op10f), Paragraph("", _st_op10f),
                    Paragraph("", _st_op10f),
                    Paragraph("Total INSS:", _st_op10f),
                    Paragraph(_fmt_brl(inss_val), _st_op10f),
                ])
                det10f_tbl = Table(det10f_rows, colWidths=[1.5*cm, 3.5*cm, 2*cm, 4*cm, 3*cm])
                det10f_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 2),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1),
                    ("LINEBELOW",     (0, 0), (-1, 0),  0.3, colors.HexColor("#94a3b8")),
                    ("LINEABOVE",     (0, -1), (-1, -1), 0.3, colors.HexColor("#94a3b8")),
                ]))
                e10f_tbl = Table([
                    [Paragraph(hdr10f_txt, st_etapa)],
                    [det10f_tbl],
                ], colWidths=[17*cm])
                e10f_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("LEFTPADDING",   (0, 1), (0, 1), 10),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 10),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (0, 1), 2),
                    ("BOTTOMPADDING", (0, 1), (0, 1), 4),
                ]))
            else:
                e10f_tbl = Table([[Paragraph(
                    "ETAPA 0005 - INSS (Desconto)   Base de calculo = ZERO — sem desconto.",
                    st_etapa)]], colWidths=[17*cm])
                e10f_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 10),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 4),
                ]))
            elems.append(e10f_tbl)

            # ── etapa 7 — IRRF ─────────────────────────────────────────
            if base_irrf <= 0 or irrf_info is None:
                _st_lbl11f = ParagraphStyle("l11f", fontName="Helvetica",
                                            fontSize=7, alignment=0,
                                            textColor=colors.HexColor("#374151"))
                _st_val11f = ParagraphStyle("v11f", fontName="Helvetica",
                                            fontSize=7, alignment=2,
                                            textColor=colors.HexColor("#374151"))
                if base_irrf <= 0:
                    _motivo_irrf = "Base IRRF negativa ou zero apos deducoes — IRRF: ZERO"
                else:
                    _motivo_irrf = (f"Base IRRF ({_fmt_brl(base_irrf)}) abaixo do limite"
                                    " de isencao da tabela — IRRF: ZERO")
                _dep_txt = (f"(-) Dependentes ({ndep} x {_fmt_brl(dep_irrf_ded)})"
                            if ndep else "(-) Dependentes")
                irrf11f_rows_zero = [
                    [Paragraph("Base (Sal.Ferias + 1/3 + Medias)", _st_lbl11f),
                     Paragraph(_fmt_brl(base_calc), _st_val11f)],
                    [Paragraph("(-) INSS", _st_lbl11f),
                     Paragraph(_fmt_brl(inss_val), _st_val11f)],
                    [Paragraph(_dep_txt, _st_lbl11f),
                     Paragraph(_fmt_brl(dep_total), _st_val11f)],
                    [Paragraph("= Base IRRF", _st_lbl11f),
                     Paragraph(_fmt_brl(base_irrf), _st_val11f)],
                    [Paragraph(_motivo_irrf, _st_lbl11f),
                     Paragraph("", _st_val11f)],
                ]
                irrf11f_det_zero = Table(irrf11f_rows_zero, colWidths=[13*cm, 4*cm])
                irrf11f_det_zero.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 3),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 3),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1.5),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1.5),
                    ("LINEBELOW",     (0, 2), (-1, 2), 0.3, colors.HexColor("#94a3b8")),
                    ("LINEABOVE",     (0, 4), (-1, 4), 0.3, colors.HexColor("#94a3b8")),
                ]))
                e11f_tbl = Table([
                    [Paragraph("ETAPA 0006 - IRRF (Desconto)", st_etapa)],
                    [irrf11f_det_zero],
                ], colWidths=[17*cm])
                e11f_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("LEFTPADDING",   (0, 1), (0, 1), 10),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 10),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (0, 1), 2),
                    ("BOTTOMPADDING", (0, 1), (0, 1), 4),
                ]))
            else:
                _st_lbl11f = ParagraphStyle("l11f", fontName="Helvetica",
                                            fontSize=7, alignment=0,
                                            textColor=colors.HexColor("#374151"))
                _st_val11f = ParagraphStyle("v11f", fontName="Helvetica",
                                            fontSize=7, alignment=2,
                                            textColor=colors.HexColor("#374151"))
                _aliq11f, _dedu11f = irrf_info
                irrf11f_rows = [
                    [Paragraph("Base INSS/IRRF (Sal.Ferias + 1/3 + Medias)", _st_lbl11f),
                     Paragraph(_fmt_brl(base_calc), _st_val11f)],
                    [Paragraph("(-) INSS", _st_lbl11f),
                     Paragraph(_fmt_brl(inss_val), _st_val11f)],
                    [Paragraph(
                        f"(-) Dependentes ({ndep} x {_fmt_brl(dep_irrf_ded)})",
                        _st_lbl11f),
                     Paragraph(_fmt_brl(dep_total), _st_val11f)],
                    [Paragraph("= Base IRRF", _st_lbl11f),
                     Paragraph(_fmt_brl(base_irrf), _st_val11f)],
                    [Paragraph(
                        f"Aliquota / Parcela a deduzir: {_aliq11f/100:g}% / {_fmt_brl(_dedu11f)}",
                        _st_lbl11f),
                     Paragraph("", _st_val11f)],
                    [Paragraph("IRRF calculado", _st_lbl11f),
                     Paragraph(_fmt_brl(irrf_val), _st_val11f)],
                ]
                irrf11f_det = Table(irrf11f_rows, colWidths=[13*cm, 4*cm])
                irrf11f_det.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 3),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 3),
                    ("TOPPADDING",    (0, 0), (-1, -1), 1.5),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 1.5),
                    ("LINEBELOW",     (0, 2), (-1, 2), 0.3, colors.HexColor("#94a3b8")),
                    ("LINEABOVE",     (0, 5), (-1, 5), 0.3, colors.HexColor("#94a3b8")),
                ]))
                e11f_tbl = Table([
                    [Paragraph("ETAPA 0006 - IRRF (Desconto)", st_etapa)],
                    [irrf11f_det],
                ], colWidths=[17*cm])
                e11f_tbl.setStyle(TableStyle([
                    ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                    ("LEFTPADDING",   (0, 1), (0, 1), 10),
                    ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                    ("TOPPADDING",    (0, 0), (0, 0), 10),
                    ("BOTTOMPADDING", (0, 0), (0, 0), 2),
                    ("TOPPADDING",    (0, 1), (0, 1), 2),
                    ("BOTTOMPADDING", (0, 1), (0, 1), 4),
                ]))
            elems.append(e11f_tbl)

            # ── totais ─────────────────────────────────────────────────
            st_tot_lbl  = ParagraphStyle("mf_tl",  fontName="Helvetica-Bold", fontSize=9,
                                         alignment=2, textColor=colors.HexColor("#111827"))
            st_tot_val  = ParagraphStyle("mf_tv",  fontName="Helvetica-Bold", fontSize=9,
                                         alignment=2, textColor=colors.HexColor("#111827"))
            st_tot_desc = ParagraphStyle("mf_tdv", fontName="Helvetica-Bold", fontSize=9,
                                         alignment=2, textColor=colors.HexColor("#b91c1c"))
            tot_rows = [
                [Paragraph("Total Proventos:", st_tot_lbl),  Paragraph(_fmt_brl(total_prov), st_tot_val)],
                [Paragraph("Total Descontos:", st_tot_lbl),  Paragraph(_fmt_brl(total_desc), st_tot_desc)],
                [Paragraph("Liquido a Receber:", st_tot_lbl), Paragraph(_fmt_brl(liquido), st_tot_val)],
            ]
            tot_tbl = Table(tot_rows, colWidths=[14.5*cm, 2.5*cm])
            tot_tbl.setStyle(TableStyle([
                ("LEFTPADDING",   (0, 0), (-1, -1), 0),
                ("RIGHTPADDING",  (0, 0), (-1, -1), 0),
                ("TOPPADDING",    (0, 0), (-1, -1), 3),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                ("LINEABOVE",     (0, 0), (-1, 0),  0.75, colors.HexColor("#374151")),
                ("LINEBELOW",     (0, -1), (-1, -1), 0.75, colors.HexColor("#374151")),
            ]))
            elems.append(Spacer(1, 0.5*cm))
            elems.append(tot_tbl)

            doc.build(elems, onFirstPage=_draw_hdr_ferias, onLaterPages=_draw_hdr_ferias)
            _salvar_memoria_pdf(dest, nome_f, buf.getvalue())
        except Exception as e_pdf:
            print(f"[gerar_memoria_ferias] mat={mat} erro: {e_pdf}")


# =========================================================
# CÁLCULO DE FÉRIAS — API
# =========================================================
@app.route("/api/calc_ferias_calcular", methods=["POST"])
def api_calc_ferias_calcular():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    sit = str(session.get("anomes_situacao") or "")
    if sit in ("C", "F"):
        return jsonify({"ok": False, "msg": "Folha está calculada/fechada — reabra para calcular férias."})

    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    if not anomes or len(anomes) != 6:
        return jsonify({"ok": False, "msg": "Folha ativa não definida."})

    empresa_nm = str(session.get("empresa_info") or "")
    cnpj_fmt   = _fmt_cnpj(session.get("cnpj_empresa", ""))

    tabela = _get_tabela_legais(anomes)
    if not tabela:
        return jsonify({"ok": False, "msg": "Tabela legal (INSS/IRRF) não encontrada para este período."})

    data     = request.get_json(force=True) or {}
    mats_req = [int(m) for m in data.get("matriculas", []) if str(m).strip().isdigit() or isinstance(m, int)]

    try:
        q = (
            supabase.table("tab_eventos")
            .select("matricula, data1i, data1f, data2i, data2f, ref1, ref2")
            .eq("id_cliente", id_cliente)
            .eq("id_empresa", id_empresa)
            .eq("op1", 3)
            .gte("data1i", anomes + "01")
            .lte("data1i", anomes + "31")
            .order("matricula")
        )
        if mats_req:
            q = q.in_("matricula", mats_req)
        eventos = q.execute().data or []
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar férias: {e}"})

    if not eventos:
        return jsonify({"ok": False, "msg": "Nenhum funcionário com férias iniciando neste mês."})

    mats = list({ev["matricula"] for ev in eventos})

    try:
        r_cad = (
            supabase.table("tab_cad")
            .select("matricula, nome, nomer, undsalfixo, vrsalfx, qtdhrsmes")
            .eq("id_cliente", id_cliente)
            .eq("id_empresa", id_empresa)
            .in_("matricula", mats)
            .execute()
        )
        cad_map = {c["matricula"]: c for c in (r_cad.data or [])}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar cadastros: {e}"})

    dep_count    = _get_dep_irrf_count(id_empresa)
    dep_irrf_ded = int(tabela.get("irrf_dep_dedu") or 0)

    # ── Verbas de férias no tab_rubrica ────────────────────────────
    try:
        r_rub = (supabase.table("tab_rubrica")
                 .select("cod_rubr, dsc_rubr, tp_rubr, unid_verba, tpn_inc_cp, tpn_inc_irrf, tpf_inc_cp, tpf_inc_irrf, inc_ferias")
                 .in_("id_cliente", [0, id_cliente])
                 .eq("situacao", "A")
                 .order("cod_rubr")
                 .execute())
        rubrics_fc = r_rub.data or []
    except Exception:
        rubrics_fc = []

    # Verbas variáveis que entram na média de férias (MAP/M12/MAN; S=legado)
    _INC_FERIAS_VALIDOS = {"MAP", "M12", "MAN", "S"}
    _verbas_media = [int(r["cod_rubr"]) for r in rubrics_fc
                     if str(r.get("inc_ferias") or "").upper() in _INC_FERIAS_VALIDOS
                     and str(r.get("tp_rubr") or "") == "1"
                     and int(r.get("cod_rubr") or 0) not in (41, 42, 45, 46)]
    # Mapa cod → método (S e MAP são equivalentes; S=legado)
    _verbas_inc_map = {
        int(r["cod_rubr"]): ("MAP" if str(r.get("inc_ferias") or "").upper() in ("S", "MAP")
                             else str(r.get("inc_ferias") or "MAP").upper())
        for r in rubrics_fc if int(r.get("cod_rubr") or 0) in set(_verbas_media)
    }
    # Verbas agrupadas por método para consulta em lote
    _grupos_metodo: dict = {}
    for _c in _verbas_media:
        _grupos_metodo.setdefault(_verbas_inc_map.get(_c, "MAP"), []).append(_c)
    # Verbas em horas (qtd em minutos): usam qty/salario-hora em vez de valor
    _verbas_horas  = {int(r["cod_rubr"]) for r in rubrics_fc
                      if int(r.get("cod_rubr") or 0) in set(_verbas_media)
                      and str(r.get("unid_verba") or "").upper() == "H"}
    _rubr_desc_map = {int(r["cod_rubr"]): (r.get("dsc_rubr") or "").strip() for r in rubrics_fc}

    # Proventos exclusivos de férias: aparecem em férias (tpf_inc_cp != X/N/vazio)
    # e NÃO aparecem em folha normal (tpn_inc_cp == X/vazio).
    # 1.º = sal férias (ex: 0041), 2.º = 1/3 constitucional (ex: 0042).
    # Excluem-se 45/46 (abono pecuniário, tratado separado).
    def _aparece_ferias(r):
        return str(r.get("tpf_inc_cp") or "X") not in ("X", "N", "")
    def _nao_aparece_normal(r):
        return str(r.get("tpn_inc_cp") or "X") in ("X", "")

    prov_ferias = [r for r in rubrics_fc
                   if str(r.get("tp_rubr") or "") == "1"
                   and _aparece_ferias(r)
                   and _nao_aparece_normal(r)
                   and int(r.get("cod_rubr") or 0) not in (45, 46)]
    cod_sal_ferias = int(prov_ferias[0]["cod_rubr"]) if prov_ferias else None
    cod_terco_fc   = int(prov_ferias[1]["cod_rubr"]) if len(prov_ferias) > 1 else None
    def _inc(r, field_ferias, field_normal):
        """Incide em férias? Usa campo férias; se vazio, usa campo normal como fallback."""
        vf = str(r.get(field_ferias) or "")
        if vf not in ("", "X", "N"):
            return True
        vn = str(r.get(field_normal) or "")
        return vn not in ("", "X", "N")
    cod_inss_fc    = next((int(r.get("cod_rubr") or 0) for r in rubrics_fc
                           if str(r.get("tp_rubr") or "") == "2"
                           and _inc(r, "tpf_inc_cp", "tpn_inc_cp")), None)
    # IRRF férias hardcoded em 121, paralelo ao INSS férias hardcoded em 103.
    # Os campos de incidência (tpf/tpn) são idênticos entre verbas férias (47, 103, 121),
    # tornando impossível distingui-las dinamicamente.
    cod_irrf_fc = 121

    folha_tipo_mov = "F"  # férias sempre gravam com tipo F
    folha_int      = int(anomes)

    def _fmt8(s):
        s = str(s or "")
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"

    resultados = []
    for ev in eventos:
        mat = ev["matricula"]
        cad = cad_map.get(mat, {})

        vrsalfx   = int(cad.get("vrsalfx")   or 0)
        qtdhrsmes = int(cad.get("qtdhrsmes")  or 220)
        und       = (cad.get("undsalfixo") or "M").upper()
        nome      = (cad.get("nomer") or cad.get("nome") or "").strip()

        sal_mes    = vrsalfx * qtdhrsmes if und == "H" else vrsalfx
        sal_hora_c = vrsalfx if und == "H" else (round(vrsalfx / qtdhrsmes) if qtdhrsmes else 0)
        dias_abono = int(ev.get("ref2") or 0)

        dias = int(ev.get("ref1") or 0)
        if dias == 0 and ev.get("data1i") and ev.get("data1f"):
            d1, d2 = str(ev["data1i"]), str(ev["data1f"])
            try:
                di = date(int(d1[:4]), int(d1[4:6]), int(d1[6:]))
                df = date(int(d2[:4]), int(d2[4:6]), int(d2[6:]))
                dias = (df - di).days + 1
            except Exception:
                dias = 30

        sal_ferias  = round(sal_mes * dias / 30)
        terco_const = round(sal_ferias / 3)
        abono_val   = round(sal_mes * dias_abono / 30) if dias_abono else 0
        terco_abono = round(abono_val / 3) if abono_val else 0

        # ── Média de verbas variáveis (MAP / M12 / MAN) ─────────────
        medias_variaveis    = {}
        totais_aq_pdf       = {}
        totais_qtd_pdf      = {}
        _verbas_periodo_pdf = {}   # cod -> {fi, ff, meses, fi_fmt, ff_fmt, metodo}
        meses_aq_pdf        = 0    # período MAP (retrocompat.)
        d2i = str(ev.get("data2i") or "")
        d2f = str(ev.get("data2f") or "")
        ano_folha = int(anomes[:4])
        mes_folha = int(anomes[4:6])

        def _periodo_metodo_fc(metodo):
            """Retorna (folha_ini, folha_fim, meses) ou None."""
            if metodo == "MAP":
                if len(d2i) == 8 and len(d2f) == 8:
                    fi = int(d2i[:6]); ff = int(d2f[:6])
                    ai, mi = int(d2i[:4]), int(d2i[4:6])
                    af, mf = int(d2f[:4]), int(d2f[4:6])
                    return fi, ff, max(1, (af - ai) * 12 + (mf - mi) + 1)
                return None
            elif metodo == "M12":
                t_fim = ano_folha * 12 + mes_folha - 2
                if t_fim < 0: t_fim = 0
                t_ini = t_fim - 11
                return (t_ini // 12) * 100 + t_ini % 12 + 1, \
                       (t_fim // 12) * 100 + t_fim % 12 + 1, 12
            elif metodo == "MAN":
                t_fim = ano_folha * 12 + mes_folha - 2
                if t_fim < 0: t_fim = 0
                ff_ano, ff_mes = t_fim // 12, t_fim % 12 + 1
                return ff_ano * 100 + 1, ff_ano * 100 + ff_mes, max(1, ff_mes)
            return None

        def _fmt_anomes_fc(am):
            s = str(am)
            return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else "—"

        _por_mes: dict = {}   # cod -> {folha_anomes: {"valor": X, "qtd": Y}}
        if _verbas_media:
            for metodo, cods in _grupos_metodo.items():
                periodo = _periodo_metodo_fc(metodo)
                if not periodo:
                    continue
                fi, ff, meses = periodo
                if metodo == "MAP":
                    meses_aq_pdf = meses
                try:
                    r_med = (supabase.table("tab_mov")
                             .select("cod_verba, valor, qtd, folha")
                             .eq("id_cliente", id_cliente)
                             .eq("id_empresa", id_empresa)
                             .eq("matricula",  mat)
                             .eq("situacao",   "A")
                             .in_("cod_verba", cods)
                             .gte("folha", fi)
                             .lte("folha", ff)
                             .neq("folha_tipo", "F")
                             .execute())
                    for row in (r_med.data or []):
                        cod    = int(row.get("cod_verba") or 0)
                        folha_r = int(row.get("folha") or 0)
                        valor_r = int(row.get("valor") or 0)
                        qtd_r   = int(row.get("qtd")   or 0)
                        if cod not in _por_mes:
                            _por_mes[cod] = {}
                        if folha_r not in _por_mes[cod]:
                            _por_mes[cod][folha_r] = {"valor": 0, "qtd": 0}
                        _por_mes[cod][folha_r]["valor"] += valor_r
                        _por_mes[cod][folha_r]["qtd"]   += qtd_r
                        if cod in _verbas_horas:
                            totais_qtd_pdf[cod] = totais_qtd_pdf.get(cod, 0) + qtd_r
                        else:
                            totais_aq_pdf[cod] = totais_aq_pdf.get(cod, 0) + valor_r
                    fi_fmt = _fmt_anomes_fc(fi)
                    ff_fmt = _fmt_anomes_fc(ff)
                    for cod in cods:
                        _verbas_periodo_pdf[cod] = {
                            "fi": fi, "ff": ff, "meses": meses,
                            "fi_fmt": fi_fmt, "ff_fmt": ff_fmt, "metodo": metodo,
                        }
                except Exception as e_med:
                    print(f"[calc_ferias] aviso media mat={mat} metodo={metodo}: {e_med}")
            # Médias por valor: total/meses × dias/30
            for cod, total_aq in sorted(totais_aq_pdf.items()):
                _meses = _verbas_periodo_pdf.get(cod, {}).get("meses", 1)
                medias_variaveis[cod] = round(round(total_aq / _meses) * dias / 30)
            # Médias por hora: total_min/meses → avg_min × sal_hora/60 × dias/30
            for cod, total_min in sorted(totais_qtd_pdf.items()):
                _meses = _verbas_periodo_pdf.get(cod, {}).get("meses", 1)
                avg_min = round(total_min / _meses)
                medias_variaveis[cod] = round(round(avg_min * sal_hora_c / 60) * dias / 30)

        # ── Lançamentos manuais (origem='M') existentes para esse funcionário ──
        man_movs = []
        try:
            r_man = (supabase.table("tab_mov")
                     .select("cod_verba, qtd, valor")
                     .eq("id_cliente", id_cliente)
                     .eq("id_empresa", id_empresa)
                     .eq("matricula",  mat)
                     .eq("folha",      folha_int)
                     .eq("folha_tipo", "F")
                     .eq("origem",     "M")
                     .eq("situacao",   "A")
                     .execute())
            man_movs = r_man.data or []
        except Exception:
            man_movs = []

        # Incidência de cada verba manual em INSS/IRRF (usa tpf; fallback tpn)
        _rubr_inc_fc = {}
        for _r in rubrics_fc:
            _cod = int(_r.get("cod_rubr") or 0)
            _tp  = str(_r.get("tp_rubr") or "")
            _vf  = str(_r.get("tpf_inc_cp")   or "")
            _inc_cp   = _vf not in ("X", "N", "")
            if not _inc_cp:
                _inc_cp = str(_r.get("tpn_inc_cp") or "") not in ("X", "N", "")
            _vi  = str(_r.get("tpf_inc_irrf")  or "")
            _inc_irrf = _vi not in ("X", "N", "")
            if not _inc_irrf:
                _inc_irrf = str(_r.get("tpn_inc_irrf") or "") not in ("X", "N", "")
            _rubr_inc_fc[_cod] = {"tp": _tp, "inc_cp": _inc_cp, "inc_irrf": _inc_irrf}

        man_prov_cp = 0
        man_desc_cp = 0
        for _mm in man_movs:
            _cod = int(_mm.get("cod_verba") or 0)
            _val = int(_mm.get("valor")    or 0)
            _inf = _rubr_inc_fc.get(_cod, {})
            if _inf.get("inc_cp"):
                if _inf.get("tp") == "1":
                    man_prov_cp += _val
                elif _inf.get("tp") == "2":
                    man_desc_cp += _val

        # INSS e IRRF: férias + 1/3 + médias de variáveis + manuais que incidem (abono é isento)
        base_calc   = sal_ferias + terco_const + sum(medias_variaveis.values()) + man_prov_cp - man_desc_cp
        inss_val, inss_det, _ = _calc_inss_progressivo(base_calc, tabela)
        fgts_val              = round(base_calc * 8 / 100)

        ndep           = dep_count.get(mat, 0)
        dep_total      = ndep * dep_irrf_ded
        base_irrf      = max(0, base_calc - inss_val - dep_total)
        irrf_val, irrf_info = _calc_irrf(base_irrf, tabela)

        liquido = base_calc - inss_val - irrf_val + abono_val + terco_abono

        # ── Apaga apenas registros calculados (origem='C'); preserva manuais (origem='M') ──
        try:
            (supabase.table("tab_mov")
             .delete()
             .eq("id_cliente", id_cliente)
             .eq("id_empresa", id_empresa)
             .eq("matricula",  mat)
             .eq("folha",      folha_int)
             .eq("folha_tipo", "F")
             .eq("origem",     "C")
             .execute())
        except Exception:
            pass
        try:
            (supabase.table("tab_total")
             .delete()
             .eq("id_cliente", id_cliente)
             .eq("id_empresa", id_empresa)
             .eq("matricula",  mat)
             .eq("folha",      folha_int)
             .eq("folha_tipo", "F")
             .execute())
        except Exception:
            pass

        # ── Monta e insere registros em tab_mov ──────────────────
        base_mov = {
            "id_cliente": id_cliente,
            "id_empresa": id_empresa,
            "situacao":   "A",
            "matricula":  mat,
            "folha":      folha_int,
            "folha_tipo": "F",
            "lote":       0,
            "origem":     "C",
            "controle":   0,
            "os":         0,
        }
        recs_mov = []

        if sal_ferias:
            recs_mov.append({**base_mov, "cod_verba": 41,
                             "qtd": dias, "valor": sal_ferias})
        if terco_const:
            recs_mov.append({**base_mov, "cod_verba": 42,
                             "qtd": 0, "valor": terco_const})
        for cod_v, val_v in sorted(medias_variaveis.items()):
            if val_v:
                recs_mov.append({**base_mov, "cod_verba": cod_v,
                                 "qtd": 0, "valor": val_v})
        if dias_abono and abono_val:
            recs_mov.append({**base_mov, "cod_verba": 45,
                             "qtd": dias_abono, "valor": abono_val})
        if dias_abono and terco_abono:
            recs_mov.append({**base_mov, "cod_verba": 46,
                             "qtd": 0, "valor": terco_abono})
        if inss_val:
            recs_mov.append({**base_mov, "cod_verba": 103,
                             "qtd": 0, "valor": inss_val})
        if cod_irrf_fc and irrf_val:
            recs_mov.append({**base_mov, "cod_verba": cod_irrf_fc,
                             "qtd": 0, "valor": irrf_val})

        _verbas_auto_fc = {41, 42, 45, 46}
        _verbas_auto_fc.update(medias_variaveis.keys())
        if inss_val:
            _verbas_auto_fc.add(103)
        if cod_irrf_fc and irrf_val:
            _verbas_auto_fc.add(cod_irrf_fc)

        print(f"[calc_ferias] mat={mat} base={base_calc} inss={inss_val} irrf={irrf_val} recs={len(recs_mov)} verbas={[r['cod_verba'] for r in recs_mov]}")
        if recs_mov:
            try:
                supabase.table("tab_mov").insert(recs_mov).execute()
            except Exception as e_ins:
                print(f"[calc_ferias] ERRO insert tab_mov mat={mat}: {e_ins}")
                return jsonify({"ok": False, "msg": f"Erro ao gravar movimentos (mat {mat}): {str(e_ins)[:200]}"})

        # ── Insere totais em tab_total (folha_tipo='F') ──────────
        total_prov = sal_ferias + terco_const + abono_val + terco_abono
        total_desc = inss_val + irrf_val
        try:
            rec_tot = {
                "id_cliente":                id_cliente,
                "id_empresa":                id_empresa,
                "matricula":                 mat,
                "folha":                     folha_int,
                "folha_tipo":                "F",
                "valor_base_inss_semlimite": base_calc,
                "valor_base_inss_comlimite": base_calc,
                "valor_inss_retido":         inss_val,
                "valor_base_fgts":           base_calc,
                "valor_fgts":                fgts_val,
                "valor_irrf_basetotal":      base_calc,
                "valor_irrf_basetabela":     base_irrf,
                "valor_irrf_dependentes":    dep_total,
                "qtd_irrf_dependentes":      ndep,
                "valor_salario":             sal_mes,
                "valor_total_proventos":     total_prov,
                "valor_total_descontos":     total_desc,
                "valor_liquido":             liquido,
                "os":                        0,
                "controle":                  0,
            }
            try:
                supabase.table("tab_total").insert(rec_tot).execute()
            except Exception:
                rec_sem_sit = {k: v for k, v in rec_tot.items() if k != "situacao"}
                supabase.table("tab_total").insert(rec_sem_sit).execute()
        except Exception:
            pass

        gravar_log("CALC_FER",
                   f"Férias calculadas: {dias}d sal={_fmt_brl(sal_ferias)} 1/3={_fmt_brl(terco_const)} "
                   f"INSS={_fmt_brl(inss_val)} IRRF={_fmt_brl(irrf_val)} Liq={_fmt_brl(liquido)}",
                   matricula=mat)

        calc_dhg_now = datetime.now().strftime("%d/%m/%Y %H:%M")
        resultados.append({
            "matricula":      mat,
            "mat_fmt":        str(mat).zfill(6),
            "nome":           nome,
            "calc_dhg":       calc_dhg_now,
            "data1i":         str(ev.get("data1i") or ""),
            "data1f":         str(ev.get("data1f") or ""),
            "data1i_fmt":     _fmt8(ev.get("data1i")),
            "data1f_fmt":     _fmt8(ev.get("data1f")),
            "dias":           dias,
            "dias_abono":     dias_abono,
            "sal_mes":        sal_mes,
            "sal_ferias":     sal_ferias,
            "terco_const":    terco_const,
            "abono_val":      abono_val,
            "terco_abono":    terco_abono,
            "base_calc":      base_calc,
            "inss_val":       inss_val,
            "inss_det":       inss_det,
            "fgts_val":       fgts_val,
            "ndep":           ndep,
            "dep_irrf_ded":   dep_irrf_ded,
            "dep_total":      dep_total,
            "base_irrf":      base_irrf,
            "irrf_val":       irrf_val,
            "irrf_info":      irrf_info,
            "total_prov":     total_prov,
            "total_desc":     total_desc,
            "liquido":        liquido,
            "sal_mes_fmt":    _fmt_brl(sal_mes),
            "sal_ferias_fmt": _fmt_brl(sal_ferias),
            "terco_fmt":      _fmt_brl(terco_const),
            "abono_fmt":      _fmt_brl(abono_val) if abono_val else "—",
            "terco_abono_fmt":_fmt_brl(terco_abono) if terco_abono else "—",
            "base_calc_fmt":  _fmt_brl(base_calc),
            "inss_fmt":       _fmt_brl(inss_val),
            "fgts_fmt":       _fmt_brl(fgts_val),
            "dep_fmt":        _fmt_brl(dep_total) if dep_total else "—",
            "base_irrf_fmt":  _fmt_brl(base_irrf),
            "irrf_fmt":       _fmt_brl(irrf_val),
            "liquido_fmt":    _fmt_brl(liquido),
            "medias_variaveis_pdf": [
                {
                    "cod":       cod,
                    "dsc":       _rubr_desc_map.get(cod, f"Verba {cod:04d}"),
                    "tipo":      "H" if cod in _verbas_horas else "V",
                    "metodo":    _verbas_periodo_pdf.get(cod, {}).get("metodo", "MAP"),
                    "fi_fmt":    _verbas_periodo_pdf.get(cod, {}).get("fi_fmt", "—"),
                    "ff_fmt":    _verbas_periodo_pdf.get(cod, {}).get("ff_fmt", "—"),
                    "meses":     _verbas_periodo_pdf.get(cod, {}).get("meses", 0),
                    "total_aq":  totais_aq_pdf.get(cod, 0),
                    "media_mes": (round(totais_aq_pdf[cod] / _verbas_periodo_pdf[cod]["meses"])
                                  if _verbas_periodo_pdf.get(cod, {}).get("meses") and totais_aq_pdf.get(cod) else 0),
                    "total_min": totais_qtd_pdf.get(cod, 0),
                    "avg_min":   (round(totais_qtd_pdf[cod] / _verbas_periodo_pdf[cod]["meses"])
                                  if _verbas_periodo_pdf.get(cod, {}).get("meses") and totais_qtd_pdf.get(cod) else 0),
                    "sal_hora_c": sal_hora_c,
                    "val": val,
                    "por_mes": sorted(_por_mes.get(cod, {}).items()),
                }
                for cod, val in sorted(medias_variaveis.items()) if val
            ],
            "verbas_media_pesquisadas_pdf": [
                {"cod":    cod,
                 "dsc":    _rubr_desc_map.get(cod, f"Verba {cod:04d}"),
                 "tipo":   "H" if cod in _verbas_horas else "V",
                 "metodo": _verbas_inc_map.get(cod, "MAP")}
                for cod in sorted(_verbas_media)
            ],
            "sal_hora_c_pdf": sal_hora_c,
            "und_pdf":        und,
            "periodo_aq_pdf": {
                "d2i": d2i, "d2f": d2f, "meses_aq": meses_aq_pdf,
                "d2i_fmt": _fmt8(d2i) if len(d2i) == 8 else "—",
                "d2f_fmt": _fmt8(d2f) if len(d2f) == 8 else "—",
            },
            "recs_mov_pdf": [
                {
                    "cod_verba": int(m["cod_verba"]),
                    "dsc": _rubr_desc_map.get(int(m["cod_verba"]), f"Verba {int(m['cod_verba']):04d}"),
                    "qtd": m.get("qtd", 0),
                    "valor": int(m.get("valor") or 0),
                }
                for m in man_movs
            ] + [
                {
                    "cod_verba": r["cod_verba"],
                    "dsc": _rubr_desc_map.get(r["cod_verba"], f"Verba {r['cod_verba']:04d}"),
                    "qtd": r.get("qtd", 0),
                    "valor": r["valor"],
                }
                for r in recs_mov
                if r["cod_verba"] not in _verbas_auto_fc
            ],
        })

    try:
        _gerar_memoria_ferias(empresa_nm, cnpj_fmt, anomes, id_empresa, resultados)
    except Exception as e_mem:
        print(f"[gerar_memoria_ferias] erro geral: {e_mem}")

    _CAMPOS_PDF = {"data1i","data1f","sal_mes","sal_ferias","terco_const","abono_val",
                   "terco_abono","base_calc","inss_val","inss_det","fgts_val",
                   "dep_irrf_ded","dep_total","base_irrf","irrf_val","irrf_info",
                   "total_prov","total_desc","liquido",
                   "medias_variaveis_pdf","verbas_media_pesquisadas_pdf",
                   "periodo_aq_pdf","recs_mov_pdf",
                   "sal_hora_c_pdf","und_pdf"}
    resultados_web = [{k: v for k, v in r.items() if k not in _CAMPOS_PDF} for r in resultados]
    return jsonify({"ok": True, "resultados": resultados_web})


# =========================================================
# VISUALIZAR CÁLCULO DE FÉRIAS
# =========================================================
@app.route("/visualizar_calc_ferias")
def visualizar_calc_ferias():
    if not session.get("logado"):
        return redirect("/")

    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else ""

    funcionarios = []
    erro_msg     = None

    if not anomes or len(anomes) != 6:
        erro_msg = "Nenhuma Folha Ativa definida."
    else:
        folha_int = int(anomes)
        try:
            # verbas de tab_mov (folha_tipo='F')
            r_mov = (supabase.table("tab_mov")
                     .select("matricula, cod_verba, qtd, valor")
                     .eq("id_cliente", id_cliente)
                     .eq("id_empresa", id_empresa)
                     .eq("folha",      folha_int)
                     .eq("folha_tipo", "F")
                     .eq("situacao",   "A")
                     .order("matricula")
                     .execute())
            movs = r_mov.data or []
        except Exception as e:
            movs = []
            erro_msg = f"Erro ao buscar movimentos: {e}"

        try:
            r_tot = (supabase.table("tab_total")
                     .select("matricula, valor_total_proventos, valor_total_descontos, valor_liquido, valor_inss_retido, valor_irrf_basetabela")
                     .eq("id_cliente", id_cliente)
                     .eq("id_empresa", id_empresa)
                     .eq("folha",      folha_int)
                     .eq("folha_tipo", "F")
                     .execute())
            totais_map = {t["matricula"]: t for t in (r_tot.data or [])}
        except Exception:
            totais_map = {}

        try:
            mats = list({m["matricula"] for m in movs} | set(totais_map.keys()))
            r_cad = (supabase.table("tab_cad")
                     .select("matricula, nome, nomer")
                     .eq("id_cliente", id_cliente)
                     .eq("id_empresa", id_empresa)
                     .in_("matricula", mats)
                     .execute())
            nomes_map = {c["matricula"]: (c.get("nomer") or c.get("nome") or "").strip()
                         for c in (r_cad.data or [])}
        except Exception:
            nomes_map = {}

        try:
            r_rub = (supabase.table("tab_rubrica")
                     .select("cod_rubr, dsc_rubr, tp_rubr")
                     .in_("id_cliente", [0, id_cliente])
                     .eq("situacao", "A")
                     .execute())
            rubr_map = {int(r["cod_rubr"]): r for r in (r_rub.data or [])}
        except Exception:
            rubr_map = {}

        # agrupa movimentos por matrícula
        from collections import defaultdict
        mov_por_mat = defaultdict(list)
        for m in movs:
            cod  = int(m.get("cod_verba") or 0)
            rubr = rubr_map.get(cod, {})
            tp   = str(rubr.get("tp_rubr") or "1")
            val  = int(m.get("valor") or 0)
            mov_por_mat[m["matricula"]].append({
                "cod":     f"{cod:04d}",
                "dsc":     (rubr.get("dsc_rubr") or "").strip() or f"Verba {cod:04d}",
                "tp":      tp,
                "provento": tp == "1",
                "val_fmt": _fmt_brl(val),
                "qtd":     int(m.get("qtd") or 0),
            })

        for mat in sorted(set(list(mov_por_mat.keys()) + list(totais_map.keys()))):
            tot = totais_map.get(mat, {})
            pv  = int(tot.get("valor_total_proventos") or 0)
            dv  = int(tot.get("valor_total_descontos") or 0)
            lv  = int(tot.get("valor_liquido") or 0)
            verbas = sorted(mov_por_mat.get(mat, []), key=lambda x: x["cod"])
            funcionarios.append({
                "matricula":   mat,
                "mat_fmt":     str(mat).zfill(6),
                "nome":        nomes_map.get(mat, "—"),
                "prov":        [v for v in verbas if v["provento"]],
                "desc":        [v for v in verbas if not v["provento"]],
                "prov_fmt":    _fmt_brl(pv),
                "desc_fmt":    _fmt_brl(dv),
                "liquido_fmt": _fmt_brl(lv),
            })

    return render_template("F10_Visualizar_Calc_Ferias.html",
                           **_ctx_relatorio(),
                           anomes_fmt=anomes_fmt,
                           funcionarios=funcionarios,
                           erro_msg=erro_msg)


# =========================================================
# RECIBO DE FÉRIAS — TELA DE SELEÇÃO
# =========================================================
@app.route("/recibo_ferias")
def recibo_ferias():
    if not session.get("logado"):
        return redirect("/")

    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    funcionarios = []
    erro_msg     = None

    if not anomes or len(anomes) != 6:
        erro_msg = "Nenhuma Folha Ativa definida. Selecione um mês/ano antes de continuar."
    else:
        try:
            r_ev = (
                supabase.table("tab_eventos")
                .select("matricula, data1i, data1f, ref1, data2i, data2f")
                .eq("id_cliente", id_cliente)
                .eq("id_empresa", id_empresa)
                .eq("op1", 3)
                .gte("data1i", anomes + "01")
                .lte("data1i", anomes + "31")
                .order("matricula")
                .execute()
            )
            eventos = r_ev.data or []
            if eventos:
                mats  = list({e["matricula"] for e in eventos})
                r_cad = (
                    supabase.table("tab_cad")
                    .select("matricula, nome, nomer")
                    .eq("id_cliente", id_cliente)
                    .eq("id_empresa", id_empresa)
                    .in_("matricula", mats)
                    .execute()
                )
                nomes = {c["matricula"]: (c.get("nomer") or c.get("nome") or "").strip()
                         for c in (r_cad.data or [])}

                def _f8(s):
                    s = str(s or "")
                    return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else "—"

                for ev in eventos:
                    mat  = ev["matricula"]
                    dias = int(ev.get("ref1") or 0)
                    if not dias and ev.get("data1i") and ev.get("data1f"):
                        d1, d2 = str(ev["data1i"]), str(ev["data1f"])
                        try:
                            di = date(int(d1[:4]), int(d1[4:6]), int(d1[6:]))
                            df = date(int(d2[:4]), int(d2[4:6]), int(d2[6:]))
                            dias = (df - di).days + 1
                        except Exception:
                            pass
                    funcionarios.append({
                        "matricula":  mat,
                        "mat_fmt":    str(mat).zfill(6),
                        "nome":       nomes.get(mat, "—"),
                        "data1i_fmt": _f8(ev.get("data1i")),
                        "data1f_fmt": _f8(ev.get("data1f")),
                        "data2i_fmt": _f8(ev.get("data2i")),
                        "data2f_fmt": _f8(ev.get("data2f")),
                        "dias":       dias,
                    })
        except Exception as e:
            erro_msg = f"Erro ao consultar férias: {e}"

    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}" if len(anomes) == 6 else ""
    return render_template(
        "F10_Recibo_Ferias.html",
        empresa      = session.get("empresa_info", ""),
        nome         = session.get("nome", ""),
        versao       = ler_versao(),
        funcionarios = funcionarios,
        erro_msg     = erro_msg,
        anomes       = anomes,
        anomes_fmt   = anomes_fmt,
    )


