# ADMINISTRADOR — Leads captados pelas landings (pet-shop e futuros nichos)
# =========================================================
@app.route("/admin_leads")
def admin_leads():
    if not session.get("logado"):
        return redirect("/")
    if str(session.get("cpf") or "") != CPF_ADMIN_F10:
        return redirect("/menu")
    try:
        leads = (supabase.table("tab_lead")
                 .select("id, nicho, nome, empresa, whatsapp, email, origem, "
                         "status, whatsapp_ok, datahora")
                 .order("id", desc=True)
                 .limit(500)
                 .execute().data or [])
    except Exception as e:
        print(f"[ADMIN/leads] erro ao ler tab_lead (a tabela existe?): {e}")
        leads = []
    total = len(leads)
    zap_ok = sum(1 for L in leads if L.get("whatsapp_ok"))
    for L in leads:
        L["datahora_fmt"] = _fmt_datahora(L.get("datahora"))
    return render_template(
        "F10_Admin_Leads.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        leads=leads,
        total=total,
        zap_ok=zap_ok,
    )


@app.route("/api/admin_leads/excluir", methods=["POST"])
def api_admin_leads_excluir():
    if not session.get("logado"):
        return jsonify({"ok": False}), 401
    if str(session.get("cpf") or "") != CPF_ADMIN_F10:
        return jsonify({"ok": False}), 403
    data = request.get_json(silent=True) or {}
    try:
        lead_id = int(data.get("id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "msg": "id inválido"}), 400
    try:
        key = os.getenv("SUPABASE_SERVICE_KEY") or SUPABASE_KEY
        headers = {"apikey": key, "Authorization": f"Bearer {key}"}
        r = requests.delete(f"{SUPABASE_URL}/rest/v1/tab_lead?id=eq.{lead_id}",
                            headers=headers, timeout=15)
        if r.status_code in (200, 204):
            return jsonify({"ok": True})
        return jsonify({"ok": False, "msg": f"HTTP {r.status_code}: {r.text[:150]}"}), 500
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)}), 500


