def _mapear_registros_funcao(col_names_orig, rows_raw):
    """Converte rows_raw (dicts Access tabfuncao) para lista de dicts normalizados.
    Retorna lista de {cbo, nome_resumido} — já deduplicada por CBO (primeiro ativo vence).
    Descarta inativos e registros sem CBO.
    """
    cols_lower = {c.lower(): c for c in col_names_orig}

    col_cbo = next((cols_lower[c] for c in cols_lower
                    if c in ('cbo', 'cbofuncao', 'cbo_funcao', 'cbocargo',
                             'cbo_cargo', 'codigocbo', 'cod_cbo')), None)
    col_nom = next((cols_lower[c] for c in cols_lower
                    if c in ('nome', 'nomefuncao', 'nome_funcao', 'nomecargo',
                             'nome_cargo', 'descricao', 'desc', 'cargo')), None)

    vistos = {}   # cbo → dict (dedup: primeiro ativo vence)
    for r in rows_raw:
        sit = str(r.get('situacao') or r.get('Situacao') or '').strip().upper()
        if sit in ('I', 'D', 'INATIVO', 'DELETADO'):
            continue
        cbo = ''.join(filter(str.isdigit, r.get(col_cbo, '') if col_cbo else ''))
        if not cbo:
            continue
        if cbo not in vistos:
            nome = str(r.get(col_nom) or '').strip()[:40] if col_nom else ''
            vistos[cbo] = {'cbo': cbo, 'nome_resumido': nome or cbo}
    return list(vistos.values())


def _imp_funcao_f10(caminho, id_cliente):
    """Importa funções/cargos do Access para tab_funcao_cli.
    Varre TODOS os arquivos da pasta (inclusive FolhaFIX) procurando tabfuncao.
    Deduplicação por CBO: apenas 1 registro por CBO por cliente.
    Retorna (gravados, erros, log).
    """
    import pyodbc, glob as _glob

    log  = []
    grav = err = 0
    pasta = os.path.dirname(caminho)

    # ── Varre TODOS os arquivos da pasta ─────────────────────────────
    todos_arqs = sorted(
        _glob.glob(os.path.join(pasta, '*.mdb')) +
        _glob.glob(os.path.join(pasta, '*.accdb'))
    )
    log.append(f'🗂  Arquivos na pasta: {len(todos_arqs)}')

    # Coleta todos os registros únicos por CBO (primeiro ativo encontrado vence)
    cbo_map = {}   # cbo → {cbo, nome_resumido}
    for arq in todos_arqs:
        nome_arq = os.path.basename(arq)
        tabela_nome, col_names, rows_raw, total, erro, todas_tabs = _ler_tabfuncao_de_arquivo(arq)
        if tabela_nome is None and erro:
            log.append(f'   {nome_arq} → erro: {erro}')
            continue
        if tabela_nome is None:
            log.append(f'   {nome_arq} → sem tabfuncao  [tabelas: {", ".join(todas_tabs) or "(nenhuma)"}]')
            continue
        if erro:
            log.append(f'   {nome_arq} → [{tabela_nome}] erro ao ler: {erro}')
            continue
        if total == 0:
            log.append(f'   {nome_arq} → [{tabela_nome}] vazia')
            continue
        recs = _mapear_registros_funcao(col_names, rows_raw)
        novos = 0
        for rec in recs:
            if rec['cbo'] not in cbo_map:
                cbo_map[rec['cbo']] = rec
                novos += 1
        log.append(f'   {nome_arq} → [{tabela_nome}] {total} brutos → {len(recs)} ativos → {novos} CBOs novos')

    if not cbo_map:
        return 0, 0, log + ['⚠  Nenhuma função encontrada com CBO válido.']

    log.append(f'📋 Total de CBOs únicos coletados: {len(cbo_map)}')

    # ── Carrega mapa CBO → id_funcao_total do Supabase ────────────────
    try:
        ft_rows = (supabase.table('tab_aux_funcao_total')
                   .select('id, cbo_codigo')
                   .execute().data or [])
    except Exception as ex:
        return 0, 1, log + [f'✗ Erro ao consultar tab_aux_funcao_total: {ex}']
    mapa_ft = {str(r['cbo_codigo']).strip(): r['id'] for r in ft_rows}

    # ── Carrega CBOs já existentes para esse cliente ──────────────────
    try:
        ex_rows = (supabase.table('tab_funcao_cli')
                   .select('id, cbo_codigo')
                   .eq('id_cliente', id_cliente)
                   .execute().data or [])
    except Exception as ex:
        return 0, 1, log + [f'✗ Erro ao consultar tab_funcao_cli: {ex}']
    cbo_existente = {str(r['cbo_codigo']).strip(): r['id'] for r in ex_rows}

    # ── Grava cada função ─────────────────────────────────────────────
    for cbo, rec in sorted(cbo_map.items()):
        id_funcao_total = mapa_ft.get(cbo)
        if not id_funcao_total:
            log.append(f'⚠  CBO {cbo} ({rec["nome_resumido"]}) — não encontrado em tab_aux_funcao_total; ignorado')
            err += 1
            continue

        campos = {
            'id_cliente':      id_cliente,
            'id_funcao_total': id_funcao_total,
            'cbo_codigo':     cbo,
            'nome_resumido':  rec['nome_resumido'],
            'cnpj':           '0',
            'situacao':       'A',
        }
        try:
            if cbo in cbo_existente:
                supabase.table('tab_funcao_cli').update(campos).eq('id', cbo_existente[cbo]).execute()
                acao = 'atualizado'
            else:
                supabase.table('tab_funcao_cli').insert(campos).execute()
                acao = 'novo'
            grav += 1
            log.append(f'✓  CBO {cbo}  {rec["nome_resumido"]}  ({acao})')
        except Exception as ex:
            err += 1
            log.append(f'✗  CBO {cbo}  {ex}')

    return grav, err, log


def _imp_verbas_f10(caminho, id_cliente, ini_valid):
    import pyodbc
    try:
        conn = pyodbc.connect(
            f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};'
        )
    except Exception as ex:
        return 0, 1, [f'✗ Conexão com o arquivo: {ex}']

    cur = conn.cursor()
    log = []
    grav = err = 0

    try:
        cur.execute("SELECT * FROM tabverba WHERE situacao='A'")
        cols = [d[0].lower() for d in cur.description]
        rows = cur.fetchall()
    except Exception as ex:
        conn.close()
        return 0, 1, [f'✗ Leitura de tabverba: {ex}']

    # filtra em Python para garantir comparação numérica (campo pode ser Texto no Access)
    rows_import = []
    ignorados   = 0
    for row in rows:
        r = dict(zip(cols, row))
        try:
            cod = int(r.get('codigo') or 0)
        except (ValueError, TypeError):
            cod = 0
        if cod >= 1000:
            rows_import.append(row)
        else:
            ignorados += 1

    log.append(f'📋 tabverba: {len(rows)} registro(s) lido(s) — {len(rows_import)} com código ≥ 1000 / {ignorados} ignorados')

    if not rows_import:
        conn.close()
        return 0, 0, log + ['⚠  Nenhuma verba com código ≥ 1000 encontrada — nada foi alterado no Supabase.']

    try:
        supabase.table('tab_rubrica').delete() \
            .eq('id_cliente', id_cliente).eq('ini_valid', ini_valid).execute()
        log.append(f'🗑  Registros anteriores removidos (cliente {id_cliente}, vigência {ini_valid})')
    except Exception as ex:
        log.append(f'⚠  Não foi possível limpar registros anteriores: {ex}')

    for row in rows_import:
        r = dict(zip(cols, row))
        try:
            cod_int = int(r.get('codigo') or 0)
            inc = (r.get('incidencia') or '     ').ljust(5)
            yn  = lambda c: 'N' if (r.get(c) or 'NAO').upper() in ('NAO','N','') else 'S'
            payload = {
                'id_cliente'       : id_cliente,
                'cod_rubr'         : cod_int,
                'dsc_rubr'         : (r.get('nomec') or '')[:40].strip(),
                'dsc_rubr_resumido': (r.get('nomer') or '')[:20].strip(),
                'tp_rubr'          : '1' if (r.get('sinal') or '+') == '+' else '2',
                'unid_verba'       : r.get('unidade') or 'V',
                'situacao'         : 'A',
                'es03_nat_rubr'    : int(r.get('esocial_tab03') or 0) or None,
                'ini_valid'        : ini_valid,
                'tpn_inc_cp'       : _inc_f10(inc[0]),
                'tpn_inc_fgts'     : _inc_f10(inc[1]),
                'tpn_inc_irrf'     : _inc_f10(inc[2]),
                'tpn_inc_pis'      : _inc_f10(inc[3]),
                'inc_rescisao'     : yn('rescisao'),
                'inc_ferias'       : yn('ferias'),
                'inc_13sal'        : yn('13sal'),
                'inc_adto13'       : yn('13sala'),
            }
            resp = supabase.table('tab_rubrica').insert(payload).execute()
            if resp.data:
                grav += 1
                log.append(f"✓  {payload['cod_rubr']:4d}  {payload['dsc_rubr']}")
            else:
                err += 1
                log.append(f"✗  {payload['cod_rubr']:4d}  sem retorno do Supabase (RLS ou constraint) — campos: {list(payload.keys())}")
        except Exception as ex:
            err += 1
            log.append(f"✗  {r.get('codigo')}  {ex}")

    conn.close()
    return grav, err, log


def _imp_sindicatos_f10(caminho, id_cliente):
    """Importa a tabela de sindicatos (tabsind, no FolhaFIX) para tab_aux_sindicatos.
    Percentuais no Access já estão ×100 (20% = 2000, 20,50% = 2050), MESMO formato
    do Supabase (telaParaBanco) → cópia direta. Reimporta limpo por cliente."""
    import pyodbc
    try:
        conn = pyodbc.connect(
            f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};'
        )
    except Exception as ex:
        return 0, 1, [f'✗ Conexão com o arquivo: {ex}']

    cur = conn.cursor()
    log = []
    grav = err = 0

    tabs = {t.table_name.lower(): t.table_name
            for t in cur.tables(tableType='TABLE') if not t.table_name.startswith('MSys')}
    nome_tab = next((tabs[c] for c in ('tabsind', 'tabsindicato', 'tabsindicatos') if c in tabs), None)
    if not nome_tab:
        conn.close()
        return 0, 1, [f'✗ Tabela de sindicatos (tabsind) não encontrada no FolhaFIX. '
                      f'Tabelas: {", ".join(sorted(tabs))}']

    try:
        cur.execute(f"SELECT * FROM [{nome_tab}] WHERE situacao='A'")
        cols = [d[0].lower() for d in cur.description]
        rows = cur.fetchall()
    except Exception as ex:
        conn.close()
        return 0, 1, [f'✗ Leitura de {nome_tab}: {ex}']

    # Sindicato "NAO SINDICALIZADO / Ministério do Trabalho": comum a todos os clientes,
    # já existe no cadastro. Não deve ser migrado nem removido.
    CNPJ_SIND_COMUM = '37115367003500'

    log.append(f'📋 {nome_tab}: {len(rows)} sindicato(s) ativo(s) lido(s)')
    if not rows:
        conn.close()
        return 0, 0, log + ['⚠  Nenhum sindicato ativo — nada foi alterado no Supabase.']

    # Reimporta limpo: remove sindicatos anteriores deste cliente, PRESERVANDO o comum.
    try:
        supabase.table('tab_aux_sindicatos').delete() \
            .eq('id_cliente', id_cliente).neq('cnpj', CNPJ_SIND_COMUM).execute()
        log.append(f'🗑  Sindicatos anteriores do cliente {id_cliente} removidos (exceto o comum)')
    except Exception as ex:
        log.append(f'⚠  Não foi possível limpar sindicatos anteriores: {ex}')

    def _i(v):
        try:
            return int(v) if v not in (None, '') else None
        except (ValueError, TypeError):
            return None

    def _s(v):
        return (str(v).strip() or None) if v is not None else None

    def _pct100(v):
        # peradianta no Access é percentual INTEIRO (50 = 50%); Supabase guarda ×100
        n = _i(v)
        return n * 100 if n is not None else None

    pulados = 0
    for row in rows:
        r = dict(zip(cols, row))
        nome = (_s(r.get('nome')) or '')[:80]
        cnpj = _s(r.get('cnpj'))
        # pula o sindicato comum (já cadastrado, compartilhado por todos os clientes)
        if (cnpj or '').replace('.', '').replace('/', '').replace('-', '') == CNPJ_SIND_COMUM:
            pulados += 1
            log.append(f'⏭  {nome}  (CNPJ comum — não migrado)')
            continue
        try:
            payload = {
                'id_cliente'                  : id_cliente,
                'situacao'                    : 'A',
                'nome_sindicato'              : nome,
                'cnpj'                        : cnpj,
                'cod_sindicato'               : _s(r.get('codigo')),
                'mes_dissidio'                : _i(r.get('dissidio_mes')),
                'dias_aviso_previo'           : _i(r.get('dias_aviso_previo')),
                'meses_carencia_aviso_previo' : _i(r.get('meses_carencia_avisop')),
                # adiantamento é % inteiro no Access → ×100 p/ o formato do Supabase
                'per_adianta_mes'             : _pct100(r.get('peradianta')),
                # demais percentuais já vêm ×100 no Access = formato do Supabase → cópia direta
                'per_adnoturno'               : _i(r.get('peradicnot')),
                'per_ferias_1_3'              : _i(r.get('perferias3')),
                'per_insalubridade'           : _i(r.get('insalubridade')),
                'per_periculosidade'          : _i(r.get('periculosidade')),
            }
            resp = supabase.table('tab_aux_sindicatos').insert(payload).execute()
            if resp.data:
                grav += 1
                log.append(f"✓  {nome}  (CNPJ {payload['cnpj'] or '-'})")
            else:
                err += 1
                log.append(f"✗  {nome}  sem retorno do Supabase (RLS ou constraint)")
        except Exception as ex:
            err += 1
            log.append(f"✗  {nome}  {ex}")

    if pulados:
        log.append(f'ℹ  {pulados} sindicato(s) comum(ns) ignorado(s) (CNPJ {CNPJ_SIND_COMUM})')
    conn.close()
    return grav, err, log


