    ('01', 'Empresa',              'tabempresas', ['tabempresas', 'tabempresa', 'tabemp']),
    ('02', 'Filiais',              'tabfiliais',  ['tabfilial', 'tabfiliais', 'tab_filial', 'filiais', 'filial']),
