    ('05', 'Rubricas / Verbas',    'tabverba',    ['tabverba']),
    ('06', 'Funcionários',         'tabcad',      ['tabcad', 'tabfunc', 'tabfuncionario']),
    ('07', 'Dependentes',          'tabdep',      ['tabdep', 'tabdependentes', 'tabdependente']),
    ('08', 'Períodos (Ano/Mês)',   'tabfolhas',   ['tabfolhas', 'tabfolha']),
