@app.route('/api/admin_importar_f10/revisar', methods=['POST'])
def api_admin_imp_revisar():
    """Revisão pré-migração: varre TODOS os arquivos Access da pasta (a pasta contém
    um único cliente) e, para cada etapa, verifica se a tabela-fonte existe e tem
    registros. Retorna status por etapa (ok / vazia / fallback / ausente) + resumo.
    Não grava nada — só leitura para o relatório de confirmação."""
    if not session.get('logado'): return jsonify({'ok': False}), 401
    if str(session.get('cpf') or '') != CPF_ADMIN_F10: return jsonify({'ok': False}), 403
    ok_amb, msg_amb = _checar_ambiente_access()
    if not ok_amb:
        return jsonify({'ok': False, 'msg': msg_amb})
    if not os.path.isdir(PASTA_BASES_F10):
        return jsonify({'ok': False, 'msg': f'Pasta não encontrada: {PASTA_BASES_F10}'})
    import pyodbc

    arquivos = [f for f in sorted(os.listdir(PASTA_BASES_F10))
                if f.lower().endswith(('.accdb', '.mdb'))]
    if not arquivos:
        return jsonify({'ok': False, 'msg': 'Nenhum arquivo .accdb/.mdb na pasta'})

    # tabela_lower -> [{arquivo, qtd}, ...]
    ocorrencias = {}
    erros_arq = []
    for fname in arquivos:
        caminho = os.path.join(PASTA_BASES_F10, fname)
        try:
            conn = pyodbc.connect(
                f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
            cur = conn.cursor()
            # Materializa os nomes ANTES de contar: chamar cur.execute() enquanto se
            # itera cur.tables() no MESMO cursor invalida o result-set das tabelas
            # (comportamento do pyodbc) — era isso que fazia quase tudo dar "ausente".
            nomes = [t.table_name for t in cur.tables(tableType='TABLE')
                     if not t.table_name.startswith('MSys')]
            for n in nomes:
                try:
                    cur.execute(f'SELECT COUNT(*) FROM [{n}]')
                    qtd = int(cur.fetchone()[0] or 0)
                except Exception:
                    qtd = -1
                ocorrencias.setdefault(n.lower(), []).append({'arquivo': fname, 'qtd': qtd})
            conn.close()
        except Exception as ex:
            erros_arq.append({'arquivo': fname, 'erro': str(ex)[:200]})

    def _somar(candidatos):
        """Retorna (fonte_real, qtd_total, [arquivos]) do 1º candidato presente."""
        for cand in candidatos:
            if cand in ocorrencias:
                qtd = sum(o['qtd'] for o in ocorrencias[cand] if o['qtd'] > 0)
                arqs = sorted({o['arquivo'] for o in ocorrencias[cand] if o['qtd'] > 0})
                return cand, qtd, arqs
        return None, 0, []

    itens = []
    n_ok = n_aviso = n_bloqueio = 0
    for num, nome, chave, candidatos in _IMP_ETAPAS_REVISAO:
        fonte, qtd, arqs = _somar(candidatos)
        usou_fallback = False
        if fonte is None and chave == 'tabfiliais':
            fonte, qtd, arqs = _somar(['tabempresas', 'tabempresa', 'tabemp'])
            usou_fallback = fonte is not None

        if fonte is None:
            status, n_bloqueio = 'ausente', n_bloqueio + 1
            msg = 'Tabela-fonte não encontrada em nenhum arquivo'
        elif qtd <= 0:
            status, n_aviso = 'vazia', n_aviso + 1
            msg = f'[{fonte}] existe mas sem registros'
        elif usou_fallback:
            status, n_aviso = 'fallback', n_aviso + 1
            msg = f'Sem tabfilial — usará [{fonte}]: {qtd} registro(s)'
        else:
            status, n_ok = 'ok', n_ok + 1
            msg = f'[{fonte}] · {qtd} registro(s) em {len(arqs)} arquivo(s)'

        itens.append({'num': num, 'nome': nome, 'chave': chave, 'fonte': fonte or '',
                      'qtd': qtd, 'arquivos': arqs, 'status': status, 'msg': msg})

    tabelas_encontradas = sorted(
        [{'nome': nl,
          'qtd': max((o['qtd'] for o in ocs), default=0),
          'arquivos': sorted({o['arquivo'] for o in ocs})}
         for nl, ocs in ocorrencias.items()],
        key=lambda x: x['nome'])

    return jsonify({
        'ok': True, 'arquivos': arquivos, 'erros_arquivo': erros_arq, 'itens': itens,
        'tabelas_encontradas': tabelas_encontradas,
        'resumo': {'ok': n_ok, 'avisos': n_aviso, 'bloqueios': n_bloqueio, 'total': len(itens)},
    })


# =========================================================
# ADMINISTRADOR — Emissão de NFS-e (lê clientes da tabNF no Access)
# =========================================================
def _ler_clientes_nf(caminho):
    """Lê a tabela tabNF de um arquivo Access e retorna os clientes para NFS-e.
    Detecção flexível de colunas (nomes variam entre bases).
    Campos por cliente: codigo, nome, valor, empresas, funcionarios, mes."""
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    tabelas = {t.table_name.lower(): t.table_name
               for t in cur.tables(tableType='TABLE')
               if not t.table_name.startswith('MSys')}
    tabela = next((tabelas[c] for c in ('tabcli_nf', 'tabclinf', 'tabnf', 'tab_nf', 'nf',
                                         'notasfiscais', 'tabnotafiscal', 'notafiscal')
                   if c in tabelas), None)
    if not tabela:
        conn.close()
        raise ValueError(f"Tabela TabCLI_NF não encontrada. Tabelas: {', '.join(sorted(tabelas))}")

    cur.execute(f'SELECT * FROM [{tabela}] WHERE 1=0')
    cols = {c[0].lower(): c[0] for c in cur.description}

    def pick(*cands):
        return next((cols[c] for c in cands if c in cols), None)

    mapa = {
        'codigo':       pick('codigo', 'cod', 'id', 'codcli', 'cliente', 'codcliente'),
        'nome':         pick('nome', 'razaosocial', 'razao_social', 'nomecli', 'fantasia', 'cliente_nome'),
        'cnpj':         pick('cnpj_cpf', 'cnpjcpf', 'cpf_cnpj', 'cpfcnpj', 'cnpj', 'cgc', 'inscricao', 'inscr'),
        'valor':        pick('servico_valor', 'servicovalor', 'valor', 'vlr', 'valornf', 'vlrnf', 'vl', 'preco'),
        'empresas':     pick('empresas', 'qtd_empresas', 'qtdempresas', 'nempresas', 'nemp'),
        'funcionarios': pick('funcionarios', 'qtd_funcionarios', 'qtdfuncionarios', 'nfunc', 'funcs'),
        'mes':          pick('mes', 'anomes', 'ano_mes', 'competencia', 'referencia'),
        'celular':      pick('celular_whatsapp', 'celularwhatsapp', 'celular', 'whatsapp'),
    }
    col_sit = pick('situacao', 'situ', 'status')
    presentes = {k: v for k, v in mapa.items() if v}
    if not presentes:
        conn.close()
        raise ValueError(f"Nenhuma coluna reconhecida em [{tabela}]. Colunas: {', '.join(sorted(cols))}")

    chaves = list(presentes.keys())
    sel_cols = [presentes[k] for k in chaves]
    if col_sit:
        sel_cols.append(col_sit)   # situacao vai como última coluna (só p/ filtrar)
    sel_sql = ', '.join(f'[{c}]' for c in sel_cols)
    cur.execute(f'SELECT {sel_sql} FROM [{tabela}]')

    def _num(v):
        # Servico_Valor vem em centavos no Access (827400 = R$ 8.274,00)
        try:
            return round(float(v) / 100.0, 2) if v not in (None, '') else None
        except Exception:
            return None

    def _int(v):
        try:
            return int(float(v)) if v not in (None, '') else None
        except Exception:
            return None

    registros = []
    for row in cur.fetchall():
        # ignora clientes com situacao = 'D' (excluído/desativado)
        if col_sit and str(row[len(chaves)] or '').strip().upper() == 'D':
            continue
        r = {chaves[i]: row[i] for i in range(len(chaves))}
        registros.append({
            'codigo':       str(r.get('codigo') or '').strip(),
            'nome':         str(r.get('nome') or '').strip(),
            'cnpj':         str(r.get('cnpj') or '').strip(),
            'valor':        _num(r.get('valor')),
            'empresas':     _int(r.get('empresas')),
            'funcionarios': _int(r.get('funcionarios')),
            'mes':          str(r.get('mes') or '').strip(),
            'celular':      str(r.get('celular') or '').strip(),
        })
    conn.close()
    registros.sort(key=lambda x: (x['nome'] or x['codigo'] or '').lower())
    return {'tabela': tabela, 'colunas': presentes, 'registros': registros}


def _arquivo_nf():
    """Resolve o arquivo Access que contém a TABNF a partir de PASTA_NF.
    Aceita pasta (procura .accdb/.mdb, preferindo o que tem TABNF) ou arquivo direto.
    Retorna o caminho ou None."""
    p = PASTA_NF
    candidatos = []
    if p and os.path.isfile(p):
        candidatos = [p]
    elif p and os.path.isdir(p):
        candidatos = [os.path.join(p, f) for f in sorted(os.listdir(p))
                      if f.lower().endswith(('.accdb', '.mdb'))]
    else:
        for ext in ('.accdb', '.mdb'):
            if p and os.path.isfile(p + ext):
                candidatos.append(p + ext)
    if not candidatos:
        return None
    if len(candidatos) == 1:
        return candidatos[0]
    # múltiplos arquivos: prefere o que realmente tem a tabela TABNF
    try:
        import pyodbc
        for c in candidatos:
            try:
                conn = pyodbc.connect(f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={c};')
                cur = conn.cursor()
                nomes = {t.table_name.lower() for t in cur.tables(tableType='TABLE')}
                conn.close()
                if any(n in nomes for n in ('tabcli_nf', 'tabclinf', 'tabnf', 'tab_nf', 'nf')):
                    return c
            except Exception:
                continue
    except ImportError:
        pass
    return candidatos[0]


