# Pasta onde os PDFs (DANFSE) das notas são salvos automaticamente.
PASTA_NF_PDF = r'C:\Dropbox\NFs'


def _nfse_nome_pdf(numero, cod, nome_cli):
    """Nome de arquivo do PDF: NFSe_<numero>_<cliente>.pdf (sanitizado)."""
    import unicodedata
    base = f"NFSe_{numero or 'DPS'}_{nome_cli or cod}"
    base = unicodedata.normalize("NFKD", base).encode("ascii", "ignore").decode()
    base = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_")
    return (base[:80] or f"NFSe_{cod}") + ".pdf"


def _nfse_salvar_pdf(nfse_xml, chave, numero, cod, nome_cli):
    """Gera o DANFSE em PDF e salva em PASTA_NF_PDF. Retorna o caminho (ou '')."""
    import nfse_nacional as nfx
    try:
        pdf = nfx.gerar_danfse_pdf(nfse_xml, chave)
        os.makedirs(PASTA_NF_PDF, exist_ok=True)
        caminho = os.path.join(PASTA_NF_PDF, _nfse_nome_pdf(numero, cod, nome_cli))
        with open(caminho, "wb") as f:
            f.write(pdf)
        return caminho
    except Exception:
        return ""


def _nfse_cert_emitente():
    """Retorna (pfx_bytes, senha) do certificado A1 do emitente (tab_empresa id=9)."""
    r = (supabase.table("tab_empresa")
         .select("cert_pfx_b64, cert_senha_enc")
         .eq("id_empresa", NFSE_EMITENTE["id_empresa"]).limit(1).execute())
    if not r.data:
        raise ValueError("Empresa do emitente (id=9) não encontrada.")
    row = r.data[0]
    pfx_b64 = row.get("cert_pfx_b64"); senha_enc = row.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        raise ValueError("Certificado A1 do emitente não configurado.")
    return base64.b64decode(pfx_b64), _cert_decrypt(senha_enc)


def _nfse_cliente_por_cod(caminho, cod):
    """Lê 1 cliente completo da TabCLI_NF pelo CodCLI (para montar o tomador)."""
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    cur.execute("""SELECT CodCLI, CNPJ_CPF, RazaoSocial, email, Endereco_Tipo, Endereco_Rua,
                          Endereco_Numero, Endereco_Complemento, Endereco_Bairro,
                          Endereco_Cidade, Endereco_UF, Endereco_CEP, ISS_Retido
                   FROM TabCLI_NF WHERE CodCLI = ?""", int(cod))
    row = cur.fetchone()
    conn.close()
    if not row:
        return None
    return {
        "cod": row[0], "cnpj_cpf": str(row[1] or "").strip(),
        "nome": str(row[2] or "").strip(), "email": str(row[3] or "").strip(),
        "lgr": f"{str(row[4] or '').strip()} {str(row[5] or '').strip()}".strip(),
        "nro": str(row[6] or "").strip(), "cpl": str(row[7] or "").strip(),
        "bairro": str(row[8] or "").strip(), "ibge": str(row[9] or "").strip(),
        "uf": str(row[10] or "").strip(), "cep": str(row[11] or "").strip(),
        "iss_retido": (str(row[12] or "0").strip() not in ("0", "", "None")),
    }


def _nfse_celular_por_cod(caminho, cod):
    """Retorna (Celular_Whatsapp, RazaoSocial) do cliente na TabCLI_NF pelo CodCLI."""
    import pyodbc
    try:
        conn = pyodbc.connect(
            f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
        cur = conn.cursor()
        cur.execute("SELECT Celular_Whatsapp, RazaoSocial FROM TabCLI_NF WHERE CodCLI = ?", int(cod))
        row = cur.fetchone()
        conn.close()
        if not row:
            return "", ""
        return str(row[0] or "").strip(), str(row[1] or "").strip()
    except Exception:
        return "", ""


_NFSE_CEP_CACHE = {}


def _nfse_ibge_do_cep(cep):
    """Código IBGE (7 díg.) do município do CEP, via ViaCEP. None se não resolver.
    Usado porque a TabCLI_NF grava o NOME da cidade (não o código) em ~66% dos
    clientes; o CEP é a fonte confiável do município (evita E0240)."""
    d = re.sub(r"\D", "", str(cep or ""))
    if len(d) != 8:
        return None
    if d in _NFSE_CEP_CACHE:
        return _NFSE_CEP_CACHE[d]
    ibge = None
    try:
        r = requests.get(f"https://viacep.com.br/ws/{d}/json/", timeout=12, verify=False)
        j = r.json()
        if not j.get("erro"):
            cand = re.sub(r"\D", "", str(j.get("ibge") or ""))
            ibge = cand if len(cand) == 7 else None
    except Exception:
        ibge = None
    _NFSE_CEP_CACHE[d] = ibge
    return ibge


def _nfse_ensure_log(caminho):
    """Cria a tabela de log/contador no NF10.accdb se ainda não existir."""
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    existe = any(t.table_name.lower() == "tabnfse_log"
                 for t in cur.tables(tableType='TABLE'))
    if not existe:
        cur.execute("""CREATE TABLE tabNFSe_Log (
            Id AUTOINCREMENT PRIMARY KEY, Ambiente INTEGER, Serie TEXT(5), nDPS LONG,
            CodCLI LONG, Competencia TEXT(7), Valor DOUBLE, ChaveAcesso TEXT(60),
            idDps TEXT(60), NumNFSe LONG, Status TEXT(20), Mensagem MEMO,
            ArqXML TEXT(255), DataHora TEXT(20))""")
        conn.commit()
    else:
        # garante a coluna NumNFSe em bases criadas antes (ignora se já existe)
        cols = {c.column_name.lower() for c in cur.columns(table="tabNFSe_Log")}
        if "numnfse" not in cols:
            try:
                cur.execute("ALTER TABLE tabNFSe_Log ADD COLUMN NumNFSe LONG")
                conn.commit()
            except Exception:
                pass
    conn.close()


def _nfse_next_ndps(caminho, ambiente, serie):
    """Próximo número de DPS para (ambiente, série) = MAX(nDPS)+1 no log."""
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    cur.execute("SELECT MAX(nDPS) FROM tabNFSe_Log WHERE Ambiente=? AND Serie=?",
                int(ambiente), str(serie))
    row = cur.fetchone()
    conn.close()
    return int(row[0] or 0) + 1


def _nfse_gravar_log(caminho, **kw):
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    cur.execute("""INSERT INTO tabNFSe_Log
        (Ambiente, Serie, nDPS, CodCLI, Competencia, Valor, ChaveAcesso, idDps,
         NumNFSe, Status, Mensagem, ArqXML, DataHora)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        int(kw["ambiente"]), str(kw["serie"]), int(kw["ndps"]), int(kw["cod"]),
        str(kw["competencia"]), float(kw["valor"]), str(kw.get("chave", "")),
        str(kw.get("id_dps", "")), (int(kw["numero"]) if kw.get("numero") else None),
        str(kw["status"]), str(kw.get("mensagem", ""))[:1000],
        str(kw.get("arq_xml", "")), datetime.now().strftime("%Y%m%d %H%M%S"))
    conn.commit()
    conn.close()


def _nfse_post(url, dps_b64, pfx_bytes, senha):
    """POST do DPS (mTLS) no Sefin. Retorna (http_status, dict_json)."""
    import tempfile, os as _os, json as _json
    from cryptography.hazmat.primitives.serialization import (
        pkcs12, Encoding, PrivateFormat, NoEncryption)
    pk, cert, chain = pkcs12.load_key_and_certificates(pfx_bytes, senha.encode())
    cf = tempfile.NamedTemporaryFile(delete=False, suffix=".cert.pem")
    kf = tempfile.NamedTemporaryFile(delete=False, suffix=".key.pem")
    try:
        cf.write(cert.public_bytes(Encoding.PEM))
        for ca in (chain or []):
            cf.write(ca.public_bytes(Encoding.PEM))
        cf.close()
        kf.write(pk.private_bytes(Encoding.PEM, PrivateFormat.TraditionalOpenSSL, NoEncryption()))
        kf.close()
        resp = requests.post(url, json={"dpsXmlGZipB64": dps_b64},
                             cert=(cf.name, kf.name), verify=False, timeout=90,
                             headers={"Content-Type": "application/json",
                                      "Accept": "application/json"})
        try:
            return resp.status_code, resp.json()
        except Exception:
            return resp.status_code, {"erros": [{"Codigo": "HTTP",
                                     "Descricao": f"Resposta não-JSON: {resp.text[:300]}"}]}
    finally:
        _os.unlink(cf.name); _os.unlink(kf.name)


def _cobranca_arquivo(caminho_nf):
    """Access da cobrança (tabCOB2026). Caminho FIXO (ARQUIVO_COBRANCA) — fica em
    pasta própria, NÃO na mesma do NF10/PASTA_NF. caminho_nf é ignorado aqui."""
    return ARQUIVO_COBRANCA


def _cobranca_gravar(caminho_nf, cod, cli, ndps, valor):
    """Grava 1 registro em tabCOB2026 (7 primeiros campos) por NFS-e emitida.

    NF_Numero = PRÓXIMO da sequência PRÓPRIA do tabCOB2026 (MAX+1) — é a PK da
    tabela e NÃO tem relação com o nDPS (que reinicia por ambiente/série).
    Emissao_Data=hoje, dados do cliente vindos da TabCLI_NF (a mesma da emissão)
    e Valor em centavos. Não pode derrubar a emissão já concluída — o chamador
    trata a exceção.
    Retorna (ok, detalhe): detalhe é o NF_Numero gravado ou o motivo da falha."""
    import pyodbc
    alvo = _cobranca_arquivo(caminho_nf)
    if not os.path.isfile(alvo):
        return False, f"Cobranca2026.accdb não encontrado: {alvo}"

    # NomeComsist (apelido interno) = campo Contato da TabCLI_NF, em MAIÚSCULAS.
    contato = ''
    try:
        c2 = pyodbc.connect(
            f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho_nf};')
        cc = c2.cursor()
        cc.execute("SELECT Contato FROM TabCLI_NF WHERE CodCLI = ?", int(cod))
        rr = cc.fetchone()
        c2.close()
        if rr and rr[0] and str(rr[0]).strip() not in ('0', ''):
            contato = str(rr[0]).strip().upper()[:30]
    except Exception:
        pass

    emissao = datetime.now().strftime("%Y%m%d")
    cnpj = _re_digits(cli.get('cnpj_cpf'))[:14]
    razao = str(cli.get('nome') or '').strip()[:60]
    valor_cent = int(round(float(valor) * 100))

    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={alvo};')
    try:
        cur = conn.cursor()
        cur.execute("SELECT MAX(NF_Numero) FROM tabCOB2026")
        maxnf = cur.fetchone()[0]
        prox = (int(re.sub(r"\D", "", str(maxnf))) if maxnf else 0) + 1
        ultimo_erro = None
        for _ in range(30):   # retenta se o NF_Numero já existir (PK duplicada)
            nf_numero = str(prox).zfill(5)[:6]
            try:
                cur.execute(
                    "INSERT INTO tabCOB2026 "
                    "(NF_Numero, Emissao_Data, Cliente_CNPJ, Cliente_Codigo, "
                    " Cliente_RazaoSocial, Cliente_NomeComsist, Valor) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?)",
                    nf_numero, emissao, cnpj, int(cod), razao, contato, valor_cent)
                conn.commit()
                return True, nf_numero
            except pyodbc.IntegrityError as ie:
                ultimo_erro = str(ie)[:120]
                prox += 1
        return False, f"sem NF_Numero livre após 30 tentativas ({ultimo_erro})"
    finally:
        conn.close()


@app.route('/api/admin_nf/emitir', methods=['POST'])
def api_admin_nf_emitir():
    if not session.get('logado'):
        return jsonify({'ok': False, 'msg': 'Sessão expirada.'}), 401
    if str(session.get('cpf') or '') != CPF_ADMIN_F10:
        return jsonify({'ok': False, 'msg': 'Acesso restrito.'}), 403
    import nfse_nacional as nfx

    data = request.get_json(force=True) or {}
    cod = data.get('cod_cli')
    competencia = str(data.get('competencia') or '').strip()          # MM/AAAA
    discr = str(data.get('discriminacao') or '').strip()
    ambiente = int(data.get('ambiente') or 2)                         # 2=restrita, 1=produção
    try:
        valor = float(str(data.get('valor') or '0').replace('.', '').replace(',', '.')) \
            if (',' in str(data.get('valor'))) else float(data.get('valor') or 0)
    except Exception:
        valor = 0.0

    if not cod:
        return jsonify({'ok': False, 'msg': 'Cliente não informado.'})
    if len(_re_digits(competencia)) not in (6,):
        return jsonify({'ok': False, 'msg': 'Competência inválida (use MM/AAAA).'})
    # A competência digitada na tela é do SERVIÇO — pode ser um mês à frente
    # (folha contratada adiantado) e vai no texto da discriminação.
    # Já o dCompet do XML não pode ser futuro: o Sefin rejeita com E0015
    # ("data de competência não pode ser posterior à data de emissão / dhEmi").
    # Por isso o dCompet é SEMPRE o mês de hoje; só a descrição fala do mês do serviço.
    _cd = _re_digits(competencia)
    _cmes = int(_cd[:2])
    if not (1 <= _cmes <= 12):
        return jsonify({'ok': False, 'msg': 'Competência inválida (mês deve ser 01–12).'})
    _hoje = datetime.now(nfx.TZ_BR)
    competencia_xml = f'{_hoje.month:02d}/{_hoje.year}'
    if valor <= 0:
        return jsonify({'ok': False, 'msg': 'Valor da nota inválido.'})

    caminho = _arquivo_nf()
    if not caminho:
        return jsonify({'ok': False, 'msg': 'Arquivo TABNF não encontrado.'})

    cli = _nfse_cliente_por_cod(caminho, cod)
    if not cli:
        return jsonify({'ok': False, 'msg': f'Cliente {cod} não encontrado.'})
    ins = _re_digits(cli['cnpj_cpf'])
    if (not ins) or set(ins) <= {'0'} or set(ins) <= {'9'}:
        return jsonify({'ok': False, 'msg': 'Cliente sem CNPJ/CPF válido — não pode emitir NFS-e.'})

    try:
        pfx_bytes, senha = _nfse_cert_emitente()
    except Exception as ex:
        return jsonify({'ok': False, 'msg': f'Certificado do emitente: {ex}'})

    # Município (IBGE) do tomador: derivado do CEP (fonte confiável), pois a
    # TabCLI_NF grava o nome da cidade na maioria dos casos. Fallback: o valor
    # gravado, se já for um código de 7 dígitos.
    tom_ibge = _nfse_ibge_do_cep(cli['cep'])
    if not tom_ibge:
        _di = re.sub(r"\D", "", cli['ibge'])
        tom_ibge = _di if len(_di) == 7 else ''

    _nfse_ensure_log(caminho)
    serie = "1"
    ndps = _nfse_next_ndps(caminho, ambiente, serie)

    # Regra específica do cliente 000614: emitir com ISS RETIDO pelo tomador à
    # alíquota de 5% (pAliq=5.00 → tpRetISSQN=2). Como a retenção exige o
    # endereço do tomador no DPS (senão E0237), o endereço é fixado aqui para
    # não depender do cadastro. Os demais clientes seguem o cadastro
    # (ISS_Retido da TabCLI_NF) e a parametrização do município.
    _iss_retido = cli['iss_retido']
    _serv_aliquota = None
    try:
        if int(cod) == 614:
            _iss_retido = True
            _serv_aliquota = "5.00"
            cli['lgr']    = "Rua Leão XIII"
            cli['nro']    = "346"
            cli['cpl']    = ""
            cli['bairro'] = "Toto"
            cli['cep']    = "50940230"
            tom_ibge      = "2611606"      # Recife/PE
    except Exception:
        pass

    e = NFSE_EMITENTE
    d = dict(
        ambiente=ambiente, serie=serie, ndps=ndps, competencia=competencia_xml,
        ver_aplic="Folha10-1.0",
        emit_cnpj=e["cnpj"], emit_im=e["im"], emit_email=e["email"],
        emit_op_simp_nac=e["op_simp_nac"], emit_reg_ap_sn=e["reg_ap_sn"],
        emit_reg_esp=e["reg_esp"], emit_ptrib_sn=e["ptrib_sn"], cloc_emi=e["cloc_emi"],
        serv_ctribnac=e["serv_ctribnac"], serv_ctribmun=e["serv_ctribmun"],
        serv_nbs=e["serv_nbs"], serv_local=e["cloc_emi"],
        serv_desc=discr or f"SERVIÇO DE PROCESSAMENTO DE DADOS DA FOLHA DE PAGAMENTO DO MES {competencia}",
        valor=valor, iss_retido=_iss_retido, serv_aliquota=_serv_aliquota,
        tom_cnpj_cpf=cli['cnpj_cpf'], tom_nome=cli['nome'], tom_email=cli['email'],
        tom_ibge=tom_ibge, tom_cep=cli['cep'], tom_lgr=cli['lgr'],
        tom_nro=cli['nro'], tom_cpl=cli['cpl'], tom_bairro=cli['bairro'],
    )

    try:
        xml, iddps = nfx.montar_dps(d)
        xml_ass = nfx.assinar_dps(xml, pfx_bytes, senha)
        ok_xsd, erros_xsd = nfx.validar_xsd(xml_ass)
        if not ok_xsd:
            _nfse_gravar_log(caminho, ambiente=ambiente, serie=serie, ndps=ndps, cod=cod,
                             competencia=competencia, valor=valor, status='ERRO_XSD',
                             mensagem="; ".join(erros_xsd[:5]))
            return jsonify({'ok': False, 'msg': 'DPS reprovado na validação XSD.',
                            'erros': erros_xsd[:5]})
        b64 = nfx.compactar_gzip_b64(xml_ass)
        status, resp = _nfse_post(NFSE_URLS.get(ambiente, NFSE_URLS[2]), b64, pfx_bytes, senha)
    except Exception as ex:
        _nfse_gravar_log(caminho, ambiente=ambiente, serie=serie, ndps=ndps, cod=cod,
                         competencia=competencia, valor=valor, status='ERRO',
                         mensagem=str(ex)[:1000])
        return jsonify({'ok': False, 'msg': f'Falha ao emitir: {ex}'})

    erros = resp.get('erros') or resp.get('Erros') or []
    if erros or status >= 400:
        msgs = [f"{x.get('Codigo','')}: {x.get('Descricao','')}" for x in erros] or \
               [f"HTTP {status}"]
        _nfse_gravar_log(caminho, ambiente=ambiente, serie=serie, ndps=ndps, cod=cod,
                         competencia=competencia, valor=valor, status='REJEITADO',
                         mensagem=" | ".join(msgs))
        return jsonify({'ok': False, 'msg': 'NFS-e rejeitada pelo Sefin.', 'erros': msgs})

    # ── Sucesso: grava XML e log ──
    chave = resp.get('chaveAcesso', '')
    id_dps = resp.get('idDps', '')
    alertas = [f"{x.get('Codigo','')}: {x.get('Descricao','')}"
               for x in (resp.get('alertas') or resp.get('Alertas') or [])]
    arq = ''
    numero = None
    nfse_xml = None
    try:
        import gzip as _gz
        from lxml import etree as _et
        nfse_xml = _gz.decompress(base64.b64decode(resp['nfseXmlGZipB64'])).decode('utf-8')
        # número da NFS-e (nNFSe) — está dentro do XML da nota
        _n = _et.fromstring(nfse_xml.encode('utf-8')).find(
            ".//{http://www.sped.fazenda.gov.br/nfse}nNFSe")
        if _n is not None and _n.text:
            numero = re.sub(r"\D", "", _n.text) or None
        pasta_xml = os.path.join(os.path.dirname(caminho), "NFSe_XML")
        os.makedirs(pasta_xml, exist_ok=True)
        arq = os.path.join(pasta_xml, f"{chave or iddps}.xml")
        with open(arq, "w", encoding="utf-8") as f:
            f.write(nfse_xml)
    except Exception:
        pass

    # DANFSE em PDF salvo automaticamente em C:\Dropbox\NFs
    pdf_arq = ''
    if nfse_xml:
        pdf_arq = _nfse_salvar_pdf(nfse_xml, chave, numero, cod, cli['nome'])

    _nfse_gravar_log(caminho, ambiente=ambiente, serie=serie, ndps=ndps, cod=cod,
                     competencia=competencia, valor=valor, chave=chave, id_dps=id_dps,
                     numero=numero, status='EMITIDA', mensagem=" | ".join(alertas), arq_xml=arq)

    # Registro de cobrança (tabCOB2026) — só para emissão em PRODUÇÃO (amb=1).
    cob_nf = ''          # NF_Numero gravado (vazio se não gravou)
    cob_status = ''      # diagnóstico p/ log/UI: 'OK nf=...' ou 'FALHA: motivo'
    if ambiente == 1:
        # A pasta da cobrança só existe na máquina do Sérgio. Numa máquina de
        # funcionário ela não está lá — então NÃO grava na tabCOB2026 e, em vez
        # disso, avisa o Sérgio por WhatsApp com os dados da NF para ele lançar.
        if not os.path.isdir(PASTA_COBRANCA):
            try:
                valor_fmt = f"{float(valor):,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
                msg = ("*NFS-e emitida — cobrança pendente de lançamento*\n\n"
                       f"Esta NF foi emitida em máquina sem a pasta da cobrança, "
                       f"então NÃO foi gravada na tabCOB2026. Lance manualmente:\n\n"
                       f"• Cliente: {cli.get('nome','')} (cód {cod})\n"
                       f"• CNPJ/CPF: {cli.get('cnpj_cpf','')}\n"
                       f"• Competência: {competencia}\n"
                       f"• Valor: R$ {valor_fmt}\n"
                       f"• NF nº: {numero}\n"
                       f"• Chave: {chave}")
                ok_w, err_w = _enviar_whatsapp_texto(WHATSAPP_AVISO_COBRANCA, msg)
                cob_status = 'PASTA AUSENTE: avisado por WhatsApp' if ok_w \
                    else f'PASTA AUSENTE: falha no WhatsApp: {err_w}'[:200]
            except Exception as _ex:
                cob_status = f'PASTA AUSENTE: erro no aviso: {type(_ex).__name__}: {_ex}'[:200]
        else:
            try:
                ok_cob, det_cob = _cobranca_gravar(caminho, cod, cli, ndps, valor)
                if ok_cob:
                    cob_nf, cob_status = det_cob, f'OK nf={det_cob}'
                else:
                    cob_status = f'FALHA: {det_cob}'
            except Exception as _ex:
                cob_status = f'FALHA: {type(_ex).__name__}: {_ex}'[:200]
    try:
        supabase.table("tab_log").insert({
            "id_cliente": None, "id_empresa": None,
            "cpf_usuario": str(session.get('cpf') or ''), "menu": "NFSE_EMISSAO",
            "observacao": f"NFS-e amb={ambiente} cod={cod} nDPS={ndps} chave={chave} cob[{cob_status}]"[:200],
            "ano_mes": None, "data_hora_grava": datetime.now().strftime("%Y%m%d %H%M"),
        }).execute()
    except Exception:
        pass

    return jsonify({'ok': True, 'chave': chave, 'id_dps': id_dps, 'ndps': ndps,
                    'numero': numero, 'ambiente': ambiente, 'alertas': alertas,
                    'arquivo': os.path.basename(arq),
                    'pdf': os.path.basename(pdf_arq) if pdf_arq else '',
                    'cobranca': cob_nf, 'cobranca_status': cob_status})


def _re_digits(v):
    return re.sub(r"\D", "", str(v or ""))


def _nfse_listar_emitidas(caminho):
    """Lê o tabNFSe_Log e retorna a lista de emissões (mais recentes primeiro),
    com o nome do cliente resolvido pela TabCLI_NF."""
    import pyodbc
    conn = pyodbc.connect(
        f'DRIVER={{Microsoft Access Driver (*.mdb, *.accdb)}};DBQ={caminho};')
    cur = conn.cursor()
    if not any(t.table_name.lower() == "tabnfse_log"
               for t in cur.tables(tableType='TABLE')):
        conn.close()
        return []
    # mapas CodCLI -> RazaoSocial / Celular_Whatsapp
    nomes = {}
    celulares = {}
    try:
        cur.execute("SELECT CodCLI, RazaoSocial, Celular_Whatsapp FROM TabCLI_NF")
        for r in cur.fetchall():
            nomes[int(r[0])] = str(r[1] or "").strip()
            celulares[int(r[0])] = str(r[2] or "").strip()
    except Exception:
        pass
    tem_num = any(c.column_name.lower() == "numnfse"
                  for c in cur.columns(table="tabNFSe_Log"))
    col_num = "NumNFSe" if tem_num else "Null AS NumNFSe"
    cur.execute(f"""SELECT Id, Ambiente, Serie, nDPS, CodCLI, Competencia, Valor,
                          ChaveAcesso, idDps, Status, Mensagem, ArqXML, DataHora, {col_num}
                   FROM tabNFSe_Log ORDER BY Id DESC""")
    regs = []
    for r in cur.fetchall():
        dh = str(r[12] or "")
        if len(dh) >= 13:                      # 'YYYYMMDD HHMMSS' -> 'DD/MM/YYYY HH:MM'
            dh = f"{dh[6:8]}/{dh[4:6]}/{dh[0:4]} {dh[9:11]}:{dh[11:13]}"
        regs.append({
            "id": r[0], "ambiente": r[1], "serie": r[2], "ndps": r[3],
            "cod": r[4], "cliente": nomes.get(int(r[4] or 0), ""),
            "celular": celulares.get(int(r[4] or 0), ""),
            "competencia": r[5], "valor": float(r[6] or 0),
            "chave": str(r[7] or ""), "id_dps": str(r[8] or ""),
            "status": str(r[9] or ""), "mensagem": str(r[10] or ""),
            "tem_xml": bool(r[11]), "data_hora": dh,
            "numero": (r[13] if r[13] not in (None, "") else None),
        })
    conn.close()
    return regs


@app.route('/api/admin_nf/emitidas')
def api_admin_nf_emitidas():
    if not session.get('logado'):
        return jsonify({'ok': False}), 401
    if str(session.get('cpf') or '') != CPF_ADMIN_F10:
        return jsonify({'ok': False}), 403
    caminho = _arquivo_nf()
    if not caminho:
        return jsonify({'ok': False, 'msg': 'Arquivo TABNF não encontrado.'})
    try:
        regs = _nfse_listar_emitidas(caminho)
        return jsonify({'ok': True, 'registros': regs, 'total': len(regs)})
    except Exception as ex:
        return jsonify({'ok': False, 'msg': str(ex)})


@app.route('/api/admin_nf/xml')
def api_admin_nf_xml():
    if not session.get('logado'):
        return jsonify({'ok': False}), 401
    if str(session.get('cpf') or '') != CPF_ADMIN_F10:
        return jsonify({'ok': False}), 403
    chave = _re_digits(request.args.get('chave', ''))
    caminho = _arquivo_nf()
    if not caminho or not chave:
        return "Não encontrado", 404
    arq = os.path.join(os.path.dirname(caminho), "NFSe_XML", f"{chave}.xml")
    if not os.path.isfile(arq):
        return "XML não encontrado para esta chave.", 404
    with open(arq, "r", encoding="utf-8") as f:
        conteudo = f.read()
    baixar = request.args.get('download') == '1'
    disp = 'attachment' if baixar else 'inline'
    return Response(conteudo, mimetype='application/xml',
                    headers={'Content-Disposition': f'{disp}; filename="NFSe_{chave}.xml"'})


