# =========================================================
# ADMINISTRADOR — Copiar base de um cliente para a BASE PARA TESTE (id=6)
# =========================================================
# O cliente id=6 é a BASE PARA TESTE. Esta rotina APAGA todos os dados-filhos
# do cliente 6 e copia a base de UMA empresa de outro cliente para dentro dele —
# assim dá para testar com dados reais sem tocar na base do cliente verdadeiro.
# A empresa em si é REAPROVEITADA (UPDATE) para manter o mesmo id_empresa entre
# cópias; a base de ORIGEM nunca é alterada (só leitura).
CLIENTE_TESTE_ID = 6
_copia_jobs = {}   # job_id → {pct, etapa, step, total_steps, done, resultado}

# Plano de cópia. Cada item descreve uma tabela a copiar do cliente origem:
#   tabela, descrição,
#   pk       = coluna serial (PK) a descartar antes do insert (o banco gera nova),
#   escopo   = 'cli' (filtra só por id_cliente) | 'emp' (id_cliente + id_empresa),
#   id_emp   = como setar id_empresa: 'novo' (id_empresa novo) | 'zero' (0) | None,
#   map_key  = se preenchido, insere linha-a-linha e guarda de-para old_pk->new_pk
#              (usado por outras tabelas que referenciam esta),
#   remaps   = [(campo, map_key)] FKs a reescrever com de-paras já construídos.
# ORDEM IMPORTA: tabelas referenciadas (funcao, filial, cc, sindicato, horario)
# vêm ANTES de quem as referencia (tab_cad, tab_mov_fixo).
_COPIA_PLANO = [
    ("tab_rubrica",        "Rubricas / Verbas",  "id",         "cli", None,   None,      []),
    ("tab_funcao_cli",     "Funções / Cargos",   "id",         "cli", None,   "funcao",  []),
    ("tab_filial",         "Filiais",            "id",         "emp", "novo", "filial",  []),
    ("tab_cc",             "Centros de custo",   "id",         "emp", "novo", "cc",      []),
    ("tab_aux_sindicatos", "Sindicatos",         "id",         "cli", "novo", "sind",    []),
    ("tab_aux_horarios",   "Horários",           "id_horario", "cli", "novo", "horario", []),
    ("tab_tabela_cli",     "Preferências",       "id",         "cli", "novo", None,      []),
    ("tab_rel_gerador",    "Config. relatórios", "id",         "cli", None,   None,      []),
    ("tab_aux_feriados",   "Feriados",           "id",         "cli", "zero", None,      []),
    ("tab_cad",            "Funcionários",       "id",         "emp", "novo", None,
        [("id_tab_horario", "horario")]),
    ("tab_dependentes",    "Dependentes",        "id",         "emp", "novo", None,      []),
    ("tab_anomes",         "Períodos (Ano/Mês)", "id",         "emp", "novo", None,      []),
    ("tab_mov",            "Movimentos",         "id",         "emp", "novo", None,      []),
    ("tab_mov_fixo",       "Movimentos fixos",   "id",         "emp", "novo", None,
        [("id_sindicato", "sind"), ("id_funcao", "funcao"),
         ("id_centrocusto", "cc"), ("id_filial", "filial")]),
    ("tab_total",          "Totais de folha",    "id",         "emp", "novo", None,      []),
    ("tab_esocial",        "Histórico eSocial",  "id_esocial", "emp", "novo", None,      []),
    ("tab_eventos",        "Eventos",            "id",         "emp", "novo", None,      []),
    ("tab_acidente",       "Acidentes (CAT)",    "id",         "emp", "novo", None,      []),
]


# Tabelas que o operador pode filtrar por mês -> (coluna de período, conversor do valor).
# tab_mov/tab_total usam 'folha' (int AAAAMM); tab_esocial usa 'ano_mes' (texto "AAAAMM").
_COPIA_FILTRO_MES = {
    "tab_mov":     ("folha",   int),
    "tab_total":   ("folha",   int),
    "tab_esocial": ("ano_mes", str),
}


def _copia_fetch_all(tabela, filtros, in_filtro=None):
    """Lê TODAS as linhas de uma tabela (paginando de 1000 em 1000) aplicando os
    filtros de igualdade informados. `in_filtro`=(coluna, [valores]) aplica um IN
    (usado para trazer só alguns meses de tab_mov/tab_total). Retorna lista de dicts."""
    linhas, ini, passo = [], 0, 1000
    while True:
        q = supabase.table(tabela).select("*")
        for col, val in filtros.items():
            q = q.eq(col, val)
        if in_filtro:
            q = q.in_(in_filtro[0], in_filtro[1])
        r = q.range(ini, ini + passo - 1).execute()
        lote = r.data or []
        linhas.extend(lote)
        if len(lote) < passo:
            break
        ini += passo
    return linhas


def _copia_insert_lotes(tabela, linhas, tam=500):
    """Insere as linhas em lotes. Retorna quantos foram gravados."""
    gravados = 0
    for i in range(0, len(linhas), tam):
        lote = linhas[i:i + tam]
        supabase.table(tabela).insert(lote).execute()
        gravados += len(lote)
    return gravados


def _copiar_base_para_teste(id_orig, id_emp_orig, job_id, meses=None):
    """Roda em thread: limpa os dados-filhos da BASE PARA TESTE (id=6) e copia a
    empresa escolhida (UPDATE na empresa p/ manter o id_empresa; a origem só é
    lida). Remapeia chaves seriais (id_empresa e FKs). `meses` = folhas (AAAAMM)
    a copiar em tab_mov/tab_total/tab_esocial; None = todos; [] = nenhum."""
    job = _copia_jobs[job_id]
    DEST = CLIENTE_TESTE_ID
    total_steps = 2 + len(_COPIA_PLANO)
    step = 0
    resultados = []
    mapas = {}   # map_key -> {old_pk: new_pk}

    def _avanca(msg):
        nonlocal step
        step += 1
        job['step'] = step
        job['pct'] = int(step / total_steps * 100)
        job['etapa'] = msg

    try:
        # 1) LIMPAR os dados-filhos da BASE PARA TESTE (a empresa é reaproveitada
        # no passo 2, então NÃO entra na limpeza; tab_cliente também não).
        job['etapa'] = 'Limpando a base para teste...'
        for t in [p[0] for p in _COPIA_PLANO]:
            try:
                supabase.table(t).delete().eq("id_cliente", DEST).execute()
            except Exception as ex:
                job.setdefault('avisos', []).append(f"limpar {t}: {str(ex)[:120]}")
        _avanca('Base para teste limpa')

        # 2) EMPRESA — mantém UMA única empresa na base para teste: se já existir,
        # faz UPDATE (preserva o id_empresa); senão, INSERT. Só leitura na origem.
        emp_rows = _copia_fetch_all("tab_empresa",
                                    {"id_cliente": id_orig, "id_empresa": id_emp_orig})
        if not emp_rows:
            raise RuntimeError("Empresa de origem não encontrada")
        emp = dict(emp_rows[0])
        emp.pop("id_empresa", None)
        emp["id_cliente"] = DEST

        existentes = _copia_fetch_all("tab_empresa", {"id_cliente": DEST})
        if existentes:
            novo_emp = existentes[0]["id_empresa"]
            # remove empresas extras da base de teste (deve haver só uma)
            for e in existentes[1:]:
                supabase.table("tab_empresa").delete().eq("id_empresa", e["id_empresa"]).execute()
            supabase.table("tab_empresa").update(emp).eq("id_empresa", novo_emp).execute()
            _avanca(f'Empresa atualizada (id_empresa {novo_emp} reaproveitado)')
        else:
            res = supabase.table("tab_empresa").insert(emp).execute()
            novo_emp = (res.data[0].get("id_empresa") if res.data else None)
            if not novo_emp:
                achou = _copia_fetch_all("tab_empresa", {"id_cliente": DEST, "cnpj": emp.get("cnpj")})
                novo_emp = achou[-1]["id_empresa"] if achou else None
            _avanca(f'Empresa criada (id_empresa {novo_emp})')
        if not novo_emp:
            raise RuntimeError("Não foi possível obter o id_empresa da base para teste")

        # 3) Demais tabelas conforme o plano
        for tab, desc, pk, escopo, id_emp_modo, map_key, remaps in _COPIA_PLANO:
            filtros = {"id_cliente": id_orig}
            if escopo == "emp":
                filtros["id_empresa"] = id_emp_orig

            # tab_mov/tab_total/tab_esocial: aplica o filtro de meses do operador
            in_filtro = None
            if tab in _COPIA_FILTRO_MES and meses is not None:
                col, conv = _COPIA_FILTRO_MES[tab]
                if not meses:               # nenhum mês marcado -> não copia nada aqui
                    resultados.append({"descricao": desc, "gravados": 0})
                    _avanca(f'{desc}: 0 registro(s) (nenhum mês marcado)')
                    continue
                in_filtro = (col, [conv(m) for m in meses])

            linhas = _copia_fetch_all(tab, filtros, in_filtro)

            def _prep(orig):
                """Devolve (old_pk, linha_preparada) — reescreve cliente/empresa/FKs."""
                old = orig.get(pk)
                r2 = dict(orig)
                r2.pop(pk, None)
                r2["id_cliente"] = DEST
                if id_emp_modo == "novo" and "id_empresa" in r2:
                    r2["id_empresa"] = novo_emp
                elif id_emp_modo == "zero" and "id_empresa" in r2:
                    r2["id_empresa"] = 0
                for campo, mk in remaps:
                    v = r2.get(campo)
                    if v is not None and v in mapas.get(mk, {}):
                        r2[campo] = mapas[mk][v]
                return old, r2

            if map_key:
                # linha-a-linha para capturar o de-para old_pk -> new_pk
                mp, n = {}, 0
                for orig in linhas:
                    old, r2 = _prep(orig)
                    ins = supabase.table(tab).insert(r2).execute()
                    new = ins.data[0].get(pk) if ins.data else None
                    if old is not None and new is not None:
                        mp[old] = new
                    n += 1
                mapas[map_key] = mp
            else:
                prep = [_prep(orig)[1] for orig in linhas]
                n = _copia_insert_lotes(tab, prep) if prep else 0

            resultados.append({"descricao": desc, "gravados": n})
            _avanca(f'{desc}: {n} registro(s)')

        job['pct'] = 100
        job['done'] = True
        job['resultado'] = {
            "ok": True, "novo_id_empresa": novo_emp, "itens": resultados,
            "total": sum(r["gravados"] for r in resultados),
            "avisos": job.get('avisos', []),
        }
    except Exception as ex:
        job['pct'] = 100
        job['done'] = True
        job['resultado'] = {"ok": False,
                            "msg": f"{type(ex).__name__}: {str(ex)[:250]}",
                            "itens": resultados}


