@app.route("/informar_adiantamento")
def informar_adiantamento():
    if not session.get("logado"):
        return redirect("/")
    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    folha_tipo = str(session.get("anomes_tipo") or "N").upper()[:1]
    if folha_tipo not in ("N", "F", "R"):
        folha_tipo = "N"

    per_empresa = None
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("per_adiantamento")
                 .eq("id_empresa", id_empresa)
                 .limit(1).execute())
        if r_emp.data:
            per_empresa = r_emp.data[0].get("per_adiantamento")
    except Exception:
        pass

    funcionarios = []
    try:
        r = (supabase.table("tab_cad")
             .select("matricula, nome, nomer, vrsalfx, dtadm, per_adianta, valor_adianta")
             .eq("id_empresa", id_empresa)
             .eq("situacao", "A")
             .order("nomer")
             .execute())
        for f in (r.data or []):
            dtadm_raw = str(f.get("dtadm") or "")
            if len(dtadm_raw) >= 6 and anomes and dtadm_raw[:6] > anomes:
                continue
            nome = (f.get("nome") or f.get("nomer") or "").strip()
            funcionarios.append({
                "matricula":    f.get("matricula"),
                "nome":         nome,
                "vrsalfx":      f.get("vrsalfx") or 0,
                "per_adianta":  f.get("per_adianta"),
                "valor_adianta": f.get("valor_adianta"),
            })
    except Exception:
        pass

    return render_template(
        "F10_Mov_Adiantamento.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        folha_tipo_ativa=folha_tipo,
        per_empresa=per_empresa,
        funcionarios=funcionarios,
    )


@app.route("/api/adiantamento_gravar", methods=["POST"])
def api_adiantamento_gravar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()

    data  = request.get_json(force=True) or {}
    modo  = (data.get("modo") or "").upper()
    itens = data.get("itens") or []

    if modo not in ("E", "P", "V"):
        return jsonify({"ok": False, "msg": "Modo inválido."})
    if not itens:
        return jsonify({"ok": False, "msg": "Nenhum funcionário informado."})

    erros = 0
    for item in itens:
        mat = item.get("matricula")
        if not mat:
            continue

        if modo in ("E", "P"):
            per = item.get("percentual")
            if per is None:
                erros += 1; continue
            per = int(per)
            if not (10 <= per <= 60):
                erros += 1; continue
            campos = {"per_adianta": per, "valor_adianta": None}
        else:
            val = item.get("valor")
            if val is None:
                erros += 1; continue
            val = int(round(float(val)))
            if val <= 0:
                erros += 1; continue
            campos = {"per_adianta": None, "valor_adianta": val}

        try:
            (supabase.table("tab_cad")
             .update(campos)
             .eq("id_empresa", id_empresa)
             .eq("matricula", int(mat))
             .execute())
        except Exception:
            erros += 1

    if erros:
        return jsonify({"ok": False, "msg": f"{erros} registro(s) com erro ao gravar."})
    return jsonify({"ok": True})


@app.route("/api/adiantamento_limpar", methods=["POST"])
def api_adiantamento_limpar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    try:
        (supabase.table("tab_cad")
         .update({"per_adianta": None, "valor_adianta": None})
         .eq("id_empresa", id_empresa)
         .eq("situacao", "A")
         .execute())
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


# =========================================================
# CALCULAR ADIANTAMENTO
# =========================================================
@app.route("/calcular_adiantamento")
def calcular_adiantamento():
    if not session.get("logado"):
        return redirect("/")
    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    folha_tipo = str(session.get("anomes_tipo") or "N").upper()[:1]
    if folha_tipo not in ("N", "F", "R"):
        folha_tipo = "N"

    def _fmt_reais(cents):
        try:
            return "R$ {:,.2f}".format(int(cents) / 100).replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "—"

    ctx = dict(
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        erro_critico=None,
        aviso_verba=False,
        verbas_ocupadas=[],
        verba_usar=None,
        dsc_verba="",
        funcionarios=[],
        sem_adiantamento=0,
        total_com=0,
        total_funcs=0,
        total_fmt="R$ 0,00",
    )
    if not anomes:
        return render_template("F10_Calc_Adiantamento.html", **ctx)

    folha_int = int(anomes)

    # Percentual da empresa
    per_empresa = None
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("per_adiantamento")
                 .eq("id_empresa", id_empresa)
                 .limit(1).execute())
        if r_emp.data:
            per_empresa = r_emp.data[0].get("per_adiantamento")
    except Exception:
        pass

    # Verbas já usadas nesta folha
    verbas_todas = list(VERBAS_ADIANTAMENTO)
    verbas_ocupadas = []
    try:
        r_ocu = (supabase.table("tab_mov")
                 .select("cod_verba")
                 .eq("id_empresa", id_empresa)
                 .eq("folha",      folha_int)
                 .eq("situacao",   "A")
                 .in_("cod_verba", verbas_todas)
                 .execute())
        verbas_ocupadas = list({r["cod_verba"] for r in (r_ocu.data or [])})
    except Exception:
        pass

    verba_usar = next((v for v in verbas_todas if v not in verbas_ocupadas), None)
    if verba_usar is None:
        ctx["erro_critico"] = "Todas as verbas de adiantamento (161–164) já foram utilizadas nesta folha."
        return render_template("F10_Calc_Adiantamento.html", **ctx)

    # Descrição da verba a usar
    dsc_verba = ""
    try:
        r_v = (supabase.table("tab_rubrica")
               .select("dsc_rubr")
               .eq("cod_rubr", verba_usar)
               .limit(1).execute())
        if r_v.data:
            dsc_verba = r_v.data[0].get("dsc_rubr") or ""
    except Exception:
        pass

    # Funcionários ativos
    funcionarios = []
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, vrsalfx, dtadm, per_adianta, valor_adianta")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao",   "A")
                 .order("nomer")
                 .execute())
        for f in (r_cad.data or []):
            dtadm_raw = str(f.get("dtadm") or "")
            dtadm_anomes = (dtadm_raw[:4] + dtadm_raw[5:7]) if len(dtadm_raw) >= 7 else ""
            if dtadm_anomes and dtadm_anomes > anomes:
                continue
            nome      = (f.get("nome") or f.get("nomer") or "").strip()
            vrsalfx   = f.get("vrsalfx") or 0
            per_ind   = f.get("per_adianta")
            val_fixo  = f.get("valor_adianta")

            if val_fixo is not None:
                valor_calc = int(val_fixo)
                modo_desc  = "Valor fixo"
            elif per_ind is not None:
                valor_calc = round(vrsalfx * int(per_ind) / 100)
                modo_desc  = f"{per_ind}% individual"
            elif per_empresa is not None:
                valor_calc = round(vrsalfx * int(per_empresa) / 100)
                modo_desc  = f"{per_empresa}% empresa"
            else:
                valor_calc = None
                modo_desc  = "—"

            funcionarios.append({
                "matricula":  f.get("matricula"),
                "nome":       nome,
                "vrsalfx":    vrsalfx,
                "sal_fmt":    _fmt_reais(vrsalfx),
                "modo_desc":  modo_desc,
                "valor_calc": valor_calc,
                "valor_fmt":  _fmt_reais(valor_calc) if valor_calc is not None else "—",
            })
    except Exception as e:
        ctx["erro_critico"] = f"Erro ao carregar funcionários: {str(e)[:150]}"
        return render_template("F10_Calc_Adiantamento.html", **ctx)

    com_adianta   = [f for f in funcionarios if f["valor_calc"] is not None]
    total_cents   = sum(f["valor_calc"] for f in com_adianta)
    sem_count     = len(funcionarios) - len(com_adianta)

    ctx.update(
        aviso_verba=bool(verbas_ocupadas),
        verbas_ocupadas=sorted(verbas_ocupadas),
        verba_usar=verba_usar,
        dsc_verba=dsc_verba,
        funcionarios=funcionarios,
        sem_adiantamento=sem_count,
        total_com=len(com_adianta),
        total_funcs=len(funcionarios),
        total_fmt=_fmt_reais(total_cents),
    )
    return render_template("F10_Calc_Adiantamento.html", **ctx)


@app.route("/api/calcular_adiantamento", methods=["POST"])
def api_calcular_adiantamento():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if not anomes:
        return jsonify({"ok": False, "msg": "Nenhuma folha ativa."})

    folha_int  = int(anomes)
    folha_tipo = str(session.get("anomes_tipo") or "N").upper()[:1]
    if folha_tipo not in ("N", "F", "R"):
        folha_tipo = "N"

    # Percentual da empresa
    per_empresa = None
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("per_adiantamento")
                 .eq("id_empresa", id_empresa)
                 .limit(1).execute())
        if r_emp.data:
            per_empresa = r_emp.data[0].get("per_adiantamento")
    except Exception:
        pass

    # Verba disponível
    verbas_todas    = list(VERBAS_ADIANTAMENTO)
    verbas_ocupadas = []
    try:
        r_ocu = (supabase.table("tab_mov")
                 .select("cod_verba")
                 .eq("id_empresa", id_empresa)
                 .eq("folha",      folha_int)
                 .eq("situacao",   "A")
                 .in_("cod_verba", verbas_todas)
                 .execute())
        verbas_ocupadas = list({r["cod_verba"] for r in (r_ocu.data or [])})
    except Exception:
        pass

    verba_usar = next((v for v in verbas_todas if v not in verbas_ocupadas), None)
    if verba_usar is None:
        return jsonify({"ok": False, "msg": "Todas as verbas (161–164) já utilizadas nesta folha."})

    # Funcionários e cálculo
    gravados = 0
    erros    = 0
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, vrsalfx, dtadm, per_adianta, valor_adianta")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao",   "A")
                 .execute())
        for f in (r_cad.data or []):
            dtadm_raw = str(f.get("dtadm") or "")
            dtadm_anomes = (dtadm_raw[:4] + dtadm_raw[5:7]) if len(dtadm_raw) >= 7 else ""
            if dtadm_anomes and dtadm_anomes > anomes:
                continue
            vrsalfx  = f.get("vrsalfx") or 0
            per_ind  = f.get("per_adianta")
            val_fixo = f.get("valor_adianta")
            mat      = f.get("matricula")

            if val_fixo is not None:
                valor = int(val_fixo)
            elif per_ind is not None:
                valor = round(vrsalfx * int(per_ind) / 100)
            elif per_empresa is not None:
                valor = round(vrsalfx * int(per_empresa) / 100)
            else:
                continue  # sem adiantamento configurado

            if valor <= 0:
                continue

            try:
                supabase.table("tab_mov").insert({
                    "id_cliente": id_cliente,
                    "id_empresa": id_empresa,
                    "situacao":   "A",
                    "matricula":  int(mat),
                    "folha":      folha_int,
                    "folha_tipo": folha_tipo,
                    "cod_verba":  verba_usar,
                    "qtd":        0,
                    "valor":      valor,
                    "lote":       0,
                    "origem":     "C",
                    "controle":   0,
                    "os":         0,
                }).execute()
                gravados += 1
            except Exception as e_ins:
                return jsonify({"ok": False, "msg": f"Erro mat {mat}: {str(e_ins)[:300]}"})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})

    if erros and not gravados:
        return jsonify({"ok": False, "msg": f"{erros} erro(s) ao gravar. Nenhum adiantamento foi salvo."})
    if erros:
        return jsonify({"ok": True, "gravados": gravados, "verba": verba_usar,
                        "msg": f"{erros} erro(s) parciais."})
    return jsonify({"ok": True, "gravados": gravados, "verba": verba_usar})


# =========================================================
# ADIANTAMENTO DO 13º SALÁRIO  (folha_tipo="A", verba 17)
# Cálculo: perAdianta13% do salário (percentual por empresa, default 50).
# Sem INSS/IRRF. (avos: etapa futura)
# =========================================================
VERBA_ADIANT_13     = 17
VERBA_PERICULOSIDADE = 31


def _get_per_adianta13(id_empresa):
    """Percentual do adiantamento do 13º da empresa (inteiro 10..90, default 50)."""
    try:
        r = (supabase.table("tab_empresa")
             .select("perAdianta13")
             .eq("id_empresa", id_empresa)
             .limit(1).execute())
        p = int((r.data or [{}])[0].get("perAdianta13") or 50)
    except Exception:
        p = 50
    return min(90, max(10, p))


def _sal_mes_adiant13(f):
    """Salário mensal em centavos a partir de um registro de tab_cad.
    Mensalista (undsalfixo≠'H'): vrsalfx. Horista ('H'): vrsalfx × qtdhrsmes."""
    vr  = int(f.get("vrsalfx") or 0)
    und = str(f.get("undsalfixo") or "M").upper()[:1]
    if und == "H":
        try:
            return int(round(vr * float(f.get("qtdhrsmes") or 0)))
        except Exception:
            return 0
    return vr


def _verba_salario(categ_n):
    """Verba do 'salário' (remuneração base) conforme a categoria eSocial.
       901 (estagiário) → 7 (bolsa estágio);
       721 → 6, 722 → 16, 723 → 86 (pró-labore específico por tipo de sócio);
       demais 700-799 (não-empregado / CI / diretor) → 6 (pró-labore);
       empregado geral → 1 (salário)."""
    if categ_n == 901:
        return 7
    if categ_n == 721:
        return 6
    if categ_n == 722:
        return 16
    if categ_n == 723:
        return 86
    if 700 <= categ_n <= 799:
        return 6
    return 1


def _elegivel_adiant13(f):
    """Elegível para 13º / adiantamento do 13º? Exclui o intermitente (categoria
    111) e as categorias >= 700 (pró-labore / CI / sócio / diretor) — não têm 13º."""
    try:
        cat = int(str(f.get("codcateg") or "0").strip() or 0)
    except (TypeError, ValueError):
        cat = 0
    return cat != 111 and cat < 700


def _pericu_adiant13(sal_mes, ev, perc=50):
    """Periculosidade no adiantamento do 13º = perc% da periculosidade do mês.
    ev = evento op1=41 (ou None); ref1 = percentual ×100 (3000 = 30,00%).
    Periculosidade mensal = sal_mes × ref1/10000; adiantamento = perc% disso."""
    if not ev:
        return 0
    ref1 = int(ev.get("ref1") or 0)
    if ref1 <= 0:
        return 0
    return int(sal_mes * ref1 / 10000) * perc // 100


def _verbas_media_adiant13(id_cliente):
    """Verbas (proventos) que entram na MÉDIA do adiantamento do 13º.
    Critério: inc_adto13='S', tp_rubr='1'. Exclui a periculosidade (31), que já
    é lançada à parte. Verba do cliente sobrepõe a global (id_cliente 0).
    Retorna (cods:list[int], verbas_hora:set[int], desc_map:dict)."""
    try:
        r = (supabase.table("tab_rubrica")
             .select("cod_rubr, unid_verba, tp_rubr, inc_adto13, dsc_rubr, id_cliente")
             .in_("id_cliente", [0, id_cliente])
             .execute())
        rows = r.data or []
    except Exception:
        rows = []
    # cliente-específico (id_cliente≠0) sobrepõe a verba global (0) de mesmo código
    by_cod = {}
    for row in sorted(rows, key=lambda x: 0 if int(x.get("id_cliente") or 0) == 0 else 1):
        by_cod[int(row.get("cod_rubr") or 0)] = row
    cods, horas, desc = [], set(), {}
    for cod, row in by_cod.items():
        if (str(row.get("inc_adto13") or "").upper() == "S"
                and str(row.get("tp_rubr") or "") == "1"
                and cod != VERBA_PERICULOSIDADE):
            cods.append(cod)
            if str(row.get("unid_verba") or "").upper() == "H":
                horas.add(cod)
            desc[cod] = (row.get("dsc_rubr") or "").strip()
    return cods, horas, desc


def _medias_adiant13(id_cliente, id_empresa, mat, sal_hora_c,
                     fi, ff, meses, perc, cods_media, verbas_hora, desc_map=None):
    """Médias das verbas variáveis para o adiantamento do 13º de UM funcionário.
    Somente folhas normais (tipo 'N') do ano corrente (fi..ff).
    - Verba em hora: média das horas = soma_qtd/meses (qtd em minutos);
      valor = (média_min/60) × sal_hora; depois × perc%.
    - Verba em valor: soma_valor/meses; depois × perc%.
    Retorna lista de detalhes (só val>0), ordenada por código:
    [{cod, desc, unid, soma_val, soma_qtd, avg_min, base, val}]."""
    desc_map = desc_map or {}
    if not cods_media or meses <= 0:
        return []
    try:
        r = (supabase.table("tab_mov")
             .select("cod_verba, valor, qtd")
             .eq("id_cliente", id_cliente)
             .eq("id_empresa", id_empresa)
             .eq("matricula",  mat)
             .eq("situacao",   "A")
             .eq("folha_tipo", "N")
             .in_("cod_verba", cods_media)
             .gte("folha", fi)
             .lte("folha", ff)
             .execute())
        rows = r.data or []
    except Exception:
        return []
    soma_val, soma_qtd = {}, {}
    for row in rows:
        c = int(row.get("cod_verba") or 0)
        soma_val[c] = soma_val.get(c, 0) + int(row.get("valor") or 0)
        soma_qtd[c] = soma_qtd.get(c, 0) + int(row.get("qtd") or 0)
    detalhe = []
    for c in sorted(set(soma_val) | set(soma_qtd)):
        if c in verbas_hora:
            avg_min = soma_qtd.get(c, 0) / meses
            base    = round(avg_min * sal_hora_c / 60)
            unid    = "H"
        else:
            avg_min = 0
            base    = round(soma_val.get(c, 0) / meses)
            unid    = "V"
        val = int(base) * perc // 100
        if val > 0:
            detalhe.append({
                "cod":      c,
                "desc":     desc_map.get(c, ""),
                "unid":     unid,
                "soma_val": soma_val.get(c, 0),
                "soma_qtd": soma_qtd.get(c, 0),
                "avg_min":  avg_min,
                "base":     base,
                "val":      val,
            })
    return detalhe


def _inc_fgts_adiant13(id_cliente, cods):
    """Mapa {cod_verba: codigo_incidencia_fgts (str, maiúsculo)} das rubricas
    informadas. Verba do cliente (id_cliente≠0) sobrepõe a global (0).
    A verba 17 (ADIANT.13.SALARIO) traz 'S' em tpn_inc_fgts; as demais que
    incidem trazem '11' (incide integralmente)."""
    cods = [int(c) for c in (cods or [])]
    if not cods:
        return {}
    try:
        r = (supabase.table("tab_rubrica")
             .select("cod_rubr, tpn_inc_fgts, id_cliente")
             .in_("id_cliente", [0, id_cliente])
             .in_("cod_rubr", cods)
             .execute())
        rows = r.data or []
    except Exception:
        rows = []
    inc = {}
    for row in sorted(rows, key=lambda x: 0 if int(x.get("id_cliente") or 0) == 0 else 1):
        inc[int(row.get("cod_rubr") or 0)] = str(row.get("tpn_inc_fgts") or "").strip().upper()
    return inc


def _aliq_fgts_adiant13(f):
    """Alíquota de FGTS (%) do funcionário no adiantamento do 13º.
    Menor aprendiz (codcateg 103) recolhe 2%; os demais, 8%."""
    try:
        cat = int(str(f.get("codcateg") or "0").strip() or 0)
    except (TypeError, ValueError):
        cat = 0
    return 2 if cat == 103 else 8


def _fgts_adiant13(inc_fgts, verba_valores, aliq_fgts=8):
    """Base e valor do FGTS do adiantamento do 13º.
    Base = soma dos proventos cujo tpn_inc_fgts indica incidência
    ('S' = adiantamento do 13º; '11' = incide integralmente).
    FGTS = aliq_fgts% da base (8% geral, 2% menor aprendiz).
    Retorna (base_fgts, fgts) em centavos."""
    base = sum(int(v) for cod, v in (verba_valores or {}).items()
               if int(v) > 0 and inc_fgts.get(int(cod), "") in ("S", "11"))
    return int(base), int(base) * int(aliq_fgts) // 100


def _marcar_folha_calculada_adiant13(id_cliente, id_empresa, anomes):
    """Marca a folha de adiantamento do 13º (tipo 'A') como Calculada em
    tab_anomes e incrementa qtd_calculos. Retorna o número do cálculo."""
    n_calc = 1
    try:
        r = (supabase.table("tab_anomes").select("qtd_calculos")
             .eq("id_cliente", id_cliente).eq("id_empresa", id_empresa)
             .eq("ano_mes", int(anomes)).eq("tipo", "A")
             .execute().data or [])
        n_calc = int((r[0].get("qtd_calculos") or 0) if r else 0) + 1
        (supabase.table("tab_anomes").update({
            "situacao":          "C",
            "data_hora_calculo": datetime.now().strftime("%Y%m%d %H%M%S"),
            "qtd_calculos":      n_calc,
        }).eq("id_cliente", id_cliente).eq("id_empresa", id_empresa)
          .eq("ano_mes", anomes).eq("tipo", "A").execute())
    except Exception:
        pass
    return n_calc


def _pdf_memoria_adiant13(empresa_nm, anomes, matr, nome, sal_mes, sal_hora_c,
                          perc, meses, valor, pericu, pericu_pct, pericu_mes,
                          medias_detalhe, total, usuario, versao,
                          base_fgts=0, fgts_val=0, aliq_fgts=8):
    """Bytes de um PDF de memória de cálculo do adiantamento do 13º (1 funcionário)."""
    def _hhmm(mins):
        mins = int(round(mins))
        return f"{mins // 60}h{mins % 60:02d}"

    anomes_fmt = f"{anomes[4:6]}/{anomes[:4]}"
    st_empresa = ParagraphStyle("ae",  fontName="Helvetica-Bold", fontSize=12,
                                alignment=TA_CENTER, spaceAfter=2)
    st_titulo  = ParagraphStyle("at",  fontName="Helvetica-Bold", fontSize=9,
                                alignment=TA_CENTER, spaceAfter=2)
    st_sub     = ParagraphStyle("asb", fontName="Helvetica", fontSize=9,
                                alignment=TA_CENTER, textColor=colors.HexColor("#64748b"))
    st_etapa   = ParagraphStyle("aet", fontName="Helvetica-Bold", fontSize=8,
                                spaceBefore=10, spaceAfter=4)
    st_formula = ParagraphStyle("af",  fontName="Helvetica", fontSize=8,
                                spaceAfter=6, textColor=colors.HexColor("#374151"))
    st_rod     = ParagraphStyle("ar",  fontName="Helvetica", fontSize=7,
                                alignment=TA_CENTER, textColor=colors.HexColor("#94a3b8"))
    st_id      = ParagraphStyle("aid", fontName="Helvetica", fontSize=9, leading=11)
    st_cell    = ParagraphStyle("ac",  fontName="Helvetica", fontSize=7.5,
                                textColor=colors.HexColor("#374151"))
    st_cellr   = ParagraphStyle("acr", parent=st_cell, alignment=TA_RIGHT)
    st_cellb   = ParagraphStyle("acb", fontName="Helvetica-Bold", fontSize=7.5)
    st_cellbr  = ParagraphStyle("acbr", parent=st_cellb, alignment=TA_RIGHT)
    st_total   = ParagraphStyle("atot", fontName="Helvetica-Bold", fontSize=10,
                                alignment=TA_RIGHT, spaceBefore=10)
    linha_sep  = TableStyle([("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.HexColor("#e2e8f0")),
                             ("TOPPADDING", (0, 0), (-1, -1), 0),
                             ("BOTTOMPADDING", (0, 0), (-1, -1), 6)])

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=2.5*cm, rightMargin=2.5*cm,
                            topMargin=2.5*cm, bottomMargin=2.5*cm)
    e = []
    e.append(Paragraph(empresa_nm, st_empresa))
    e.append(Paragraph("MEMÓRIA DE CÁLCULO — ADIANTAMENTO DO 13º SALÁRIO", st_titulo))
    e.append(Paragraph(f"Competência: {anomes_fmt}  ·  Percentual do adiantamento: {perc}%", st_sub))
    e.append(Spacer(1, 0.1*cm))
    e.append(Table([[""]], colWidths=[16*cm], style=linha_sep))

    idt = Table([[Paragraph(f"<b>Matrícula:</b> {matr:06d}", st_id),
                  Paragraph(f"<b>Nome:</b> {nome}", st_id)]], colWidths=[4*cm, 12*cm])
    idt.setStyle(TableStyle([("TOPPADDING", (0, 0), (-1, -1), 3),
                             ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                             ("LEFTPADDING", (0, 0), (-1, -1), 0),
                             ("RIGHTPADDING", (0, 0), (-1, -1), 0)]))
    e.append(idt)
    e.append(Table([[""]], colWidths=[16*cm], style=linha_sep))

    # ETAPA 1 — salário
    e.append(Paragraph("ETAPA 0001 — ADIANTAMENTO SOBRE O SALÁRIO", st_etapa))
    e.append(Paragraph(
        f"Salário do mês {_fmt_brl(sal_mes)} × {perc}% = <b>{_fmt_brl(valor)}</b>  "
        f"(verba {VERBA_ADIANT_13})", st_formula))

    # ETAPA 2 — periculosidade
    e.append(Paragraph("ETAPA 0002 — PERICULOSIDADE", st_etapa))
    if pericu > 0:
        pct_txt = f"{pericu_pct:.2f}".replace(".", ",")
        e.append(Paragraph(
            f"Periculosidade do mês (Salário × {pct_txt}%) = {_fmt_brl(pericu_mes)} × {perc}% "
            f"= <b>{_fmt_brl(pericu)}</b>  (verba {VERBA_PERICULOSIDADE})", st_formula))
    else:
        e.append(Paragraph("Funcionário sem periculosidade ativa no mês.", st_formula))

    # ETAPA 3 — médias das verbas variáveis
    e.append(Paragraph(
        f"ETAPA 0003 — MÉDIAS DAS VERBAS VARIÁVEIS (ano corrente · ÷ {meses} {'mês' if meses == 1 else 'meses'})",
        st_etapa))
    if medias_detalhe:
        rows = [[Paragraph("<b>Verba</b>", st_cellb),
                 Paragraph("<b>Descrição</b>", st_cellb),
                 Paragraph("<b>Acumulado no ano</b>", st_cellbr),
                 Paragraph("<b>Média mensal</b>", st_cellbr),
                 Paragraph(f"<b>Valor ({perc}%)</b>", st_cellbr)]]
        for d in medias_detalhe:
            if d["unid"] == "H":
                acum  = f"{_hhmm(d['soma_qtd'])} · {_fmt_brl(sal_hora_c)}/h"
                media = f"{_hhmm(d['avg_min'])} × {_fmt_brl(sal_hora_c)} = {_fmt_brl(d['base'])}"
            else:
                acum  = _fmt_brl(d["soma_val"])
                media = _fmt_brl(d["base"])
            rows.append([
                Paragraph(f"{d['cod']:04d}", st_cell),
                Paragraph(d["desc"] or "", st_cell),
                Paragraph(acum, st_cellr),
                Paragraph(media, st_cellr),
                Paragraph(_fmt_brl(d["val"]), st_cellr),
            ])
        med_tot = sum(d["val"] for d in medias_detalhe)
        rows.append([Paragraph("", st_cell), Paragraph("<b>Total das médias</b>", st_cellb),
                     Paragraph("", st_cell), Paragraph("", st_cell),
                     Paragraph(f"<b>{_fmt_brl(med_tot)}</b>", st_cellbr)])
        tbl = Table(rows, colWidths=[1.4*cm, 5.6*cm, 4.0*cm, 3.4*cm, 2.6*cm])
        tbl.setStyle(TableStyle([
            ("LINEBELOW",     (0, 0), (-1, 0), 0.6, colors.HexColor("#cbd5e1")),
            ("LINEABOVE",     (0, -1), (-1, -1), 0.6, colors.HexColor("#cbd5e1")),
            ("ROWBACKGROUNDS",(0, 1), (-1, -2), [colors.white, colors.HexColor("#f8fafc")]),
            ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
            ("TOPPADDING",    (0, 0), (-1, -1), 3),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("LEFTPADDING",   (0, 0), (-1, -1), 2),
            ("RIGHTPADDING",  (0, 0), (-1, -1), 2),
        ]))
        e.append(tbl)
    else:
        e.append(Paragraph("Sem verbas variáveis lançadas no ano corrente.", st_formula))

    # ETAPA 4 — FGTS (aliq_fgts% sobre a base incidente; 2% para menor aprendiz)
    e.append(Paragraph("ETAPA 0004 — FGTS", st_etapa))
    if base_fgts > 0:
        apr_txt = "  (menor aprendiz)" if int(aliq_fgts) == 2 else ""
        e.append(Paragraph(
            f"Base de incidência (adiantamento + periculosidade + médias) {_fmt_brl(base_fgts)} × {int(aliq_fgts)}% "
            f"= <b>{_fmt_brl(fgts_val)}</b>{apr_txt}", st_formula))
    else:
        e.append(Paragraph("Sem base de incidência de FGTS neste adiantamento.", st_formula))

    # TOTAL
    e.append(Paragraph(f"TOTAL DO ADIANTAMENTO = {_fmt_brl(total)}", st_total))

    # rodapé
    e.append(Spacer(1, 1*cm))
    e.append(Paragraph(
        f"Gerado em {datetime.now().strftime('%d/%m/%Y %H:%M:%S')}  |  Usuario: {usuario}  |  "
        f"Folha10 Simples {versao}", st_rod))

    doc.build(e)
    return buf.getvalue()


# Memórias de cálculo (folha, adiantamento, férias): pasta local no Windows,
# espelhada no Supabase Storage quando roda no Render (Linux). Mesmo layout
# de subpastas AAAA/AAAA-MM/EMPRESA; o tipo é distinguido pelo nome do arquivo.
_MEM_PREFIXO = "memorias"   # prefixo dentro do bucket _ESOC_BUCKET
# Para TESTAR o caminho do Storage rodando local no Windows: defina MEMORIA_STORAGE=1.
_MEM_FORCAR_STORAGE = os.environ.get("MEMORIA_STORAGE") == "1"


def _memoria_usa_storage():
    """True = grava/lê no Supabase Storage; False = disco local C:\\.
    Storage no Render/Linux; local no Windows — exceto se MEMORIA_STORAGE=1 (teste)."""
    return _MEM_FORCAR_STORAGE or os.name != "nt"


def _memoria_subpasta(anomes, id_empresa):
    return f"{anomes[:4]}/{anomes[:4]}-{anomes[4:6]}/{int(id_empresa):06d}"


def _memoria_pasta_local(anomes, id_empresa):
    return os.path.join("C:\\Folha10-Simples_Memoria", anomes[:4],
                        f"{anomes[:4]}-{anomes[4:6]}", f"{int(id_empresa):06d}")


def _memoria_destino(anomes, id_empresa):
    """Destino das memórias de cálculo.
    Windows local (os.name=='nt') → C:\\Folha10-Simples_Memoria\\AAAA\\AAAA-MM\\EMP.
    Render/Linux → Supabase Storage (bucket esocial-xml, prefixo memorias/...).
    Retorna {"modo","base","label"} — base = onde gravar; label = p/ exibir."""
    if not _memoria_usa_storage():
        pasta = _memoria_pasta_local(anomes, id_empresa)
        try:
            os.makedirs(pasta, exist_ok=True)
        except Exception:
            return {"modo": "local", "base": "", "label": ""}
        return {"modo": "local", "base": pasta, "label": pasta}
    base = f"{_MEM_PREFIXO}/{_memoria_subpasta(anomes, id_empresa)}"
    return {"modo": "storage", "base": base,
            "label": f"Supabase Storage · {_ESOC_BUCKET}/{base}"}


def _salvar_memoria_pdf(dest, nome_arq, pdf_bytes):
    """Grava um PDF de memória no destino (local ou Storage). Retorna True/False."""
    if not dest or not dest.get("base"):
        return False
    if dest["modo"] == "local":
        try:
            with open(os.path.join(dest["base"], nome_arq), "wb") as fh:
                fh.write(pdf_bytes)
            return True
        except Exception:
            return False
    try:
        _supabase_storage.storage.from_(_ESOC_BUCKET).upload(
            path=f"{dest['base']}/{nome_arq}", file=pdf_bytes,
            file_options={"content-type": "application/pdf", "upsert": "true"})
        return True
    except Exception as e:
        print(f"[memoria] ERRO Storage '{dest['base']}/{nome_arq}': {e}")
        return False


def _memoria_listar(anomes, id_empresa):
    """Nomes dos arquivos de memória existentes p/ a folha/empresa (local ou Storage)."""
    if len(str(anomes)) != 6:
        return []
    if not _memoria_usa_storage():
        pasta = _memoria_pasta_local(anomes, id_empresa)
        try:
            return os.listdir(pasta) if os.path.isdir(pasta) else []
        except Exception:
            return []
    base = f"{_MEM_PREFIXO}/{_memoria_subpasta(anomes, id_empresa)}"
    try:
        st = _supabase_storage.storage.from_(_ESOC_BUCKET)
        try:
            itens = st.list(base, {"limit": 1000}) or []   # default do Storage é 100
        except TypeError:
            itens = st.list(base) or []
        return [it.get("name") for it in itens if it.get("name")]
    except Exception:
        return []


def _memoria_ler(anomes, id_empresa, nome_arq):
    """Bytes de um PDF de memória (local ou Storage) ou None."""
    if not _memoria_usa_storage():
        try:
            with open(os.path.join(_memoria_pasta_local(anomes, id_empresa), nome_arq), "rb") as fh:
                return fh.read()
        except Exception:
            return None
    base = f"{_MEM_PREFIXO}/{_memoria_subpasta(anomes, id_empresa)}"
    try:
        return _supabase_storage.storage.from_(_ESOC_BUCKET).download(f"{base}/{nome_arq}")
    except Exception:
        return None


def _memoria_apagar(anomes, id_empresa, remover_pred=None):
    """Apaga memórias existentes da folha/empresa (local ou Storage). Mantém só o
    último cálculo. remover_pred(nome)->bool seleciona quais apagar (default: todas).
    Escopo por tipo (folha/férias/adiant) pelo nome, já que dividem a mesma pasta."""
    if len(str(anomes)) != 6:
        return
    alvo = [n for n in _memoria_listar(anomes, id_empresa)
            if (remover_pred(n) if remover_pred else True)]
    if not alvo:
        return
    if not _memoria_usa_storage():
        pasta = _memoria_pasta_local(anomes, id_empresa)
        for n in alvo:
            try:
                os.remove(os.path.join(pasta, n))
            except Exception:
                pass
    else:
        base = f"{_MEM_PREFIXO}/{_memoria_subpasta(anomes, id_empresa)}"
        try:
            _supabase_storage.storage.from_(_ESOC_BUCKET).remove([f"{base}/{n}" for n in alvo])
        except Exception:
            pass


@app.route("/calcular_adiantamento_13")
def calcular_adiantamento_13():
    if not session.get("logado"):
        return redirect("/")
    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    folha_tipo = str(session.get("anomes_tipo") or "").upper()[:1]

    def _fmt_reais(cents):
        try:
            return "{:,.2f}".format(int(cents) / 100).replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "—"

    ctx = dict(
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        folha_tipo=folha_tipo,
        tipo_ok=(folha_tipo == "A"),
        folha_situacao=(_refresh_situacao_folha() if (anomes and folha_tipo == "A") else ""),
        erro_critico=None,
        verba_usar=VERBA_ADIANT_13,
        dsc_verba="",
        perc_adianta13=50,
        funcionarios=[],
        total_funcs=0,
        total_com=0,
        total_fmt="R$ 0,00",
    )
    if not anomes or folha_tipo != "A":
        return render_template("F10_Calc_Adiantamento_13.html", **ctx)

    # descrição da verba 17
    try:
        r_v = supabase.table("tab_rubrica").select("dsc_rubr").eq("cod_rubr", VERBA_ADIANT_13).limit(1).execute()
        if r_v.data:
            ctx["dsc_verba"] = r_v.data[0].get("dsc_rubr") or ""
    except Exception:
        pass

    # percentual do adiantamento do 13º (por empresa, default 50)
    perc = _get_per_adianta13(id_empresa)
    ctx["perc_adianta13"] = perc

    # periculosidade ativa no mês (op1=41), por funcionário — entra a perc%
    id_cliente = session.get("id_cliente")
    try:
        pericu_map = _calc_etapa7_periculosidade(id_empresa, anomes, id_cliente=id_cliente)
    except Exception:
        pericu_map = {}

    # médias das verbas variáveis (inc_adto13='S') — ano corrente, ÷ mês da folha
    cods_media, verbas_hora, _desc_media = _verbas_media_adiant13(id_cliente)
    inc_fgts = _inc_fgts_adiant13(id_cliente, [VERBA_ADIANT_13, VERBA_PERICULOSIDADE] + cods_media)
    ano_folha = int(anomes[:4]); mes_folha = int(anomes[4:6])
    fi = ano_folha * 100 + 1; ff = int(anomes); meses = mes_folha

    funcionarios = []
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, codcateg, vrsalfx, undsalfixo, qtdhrsmes, dtadm")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao", "A")
                 .order("nomer")
                 .execute())
        for f in (r_cad.data or []):
            dtadm_raw = str(f.get("dtadm") or "")
            dtadm_anomes = (dtadm_raw[:4] + dtadm_raw[5:7]) if len(dtadm_raw) >= 7 else ""
            if dtadm_anomes and dtadm_anomes > anomes:
                continue
            if not _elegivel_adiant13(f):   # exclui cat 111 e >= 700 (sem 13º)
                continue
            nome    = (f.get("nome") or f.get("nomer") or "").strip()
            mat_f   = int(f.get("matricula") or 0)
            sal_mes = _sal_mes_adiant13(f)
            valor   = sal_mes * perc // 100          # perc% do salário
            pericu  = _pericu_adiant13(sal_mes, pericu_map.get(mat_f), perc)
            vrsalfx = int(f.get("vrsalfx") or 0)
            und     = str(f.get("undsalfixo") or "M").upper()[:1]
            qhm     = int(f.get("qtdhrsmes") or 220) or 220
            sal_hora_c = vrsalfx if und == "H" else round(vrsalfx / qhm)
            medias_det = _medias_adiant13(id_cliente, id_empresa, mat_f, sal_hora_c,
                                          fi, ff, meses, perc, cods_media, verbas_hora, _desc_media)
            medias_tot = sum(d["val"] for d in medias_det)
            total_f = valor + pericu + medias_tot
            verba_valores = {VERBA_ADIANT_13: valor, VERBA_PERICULOSIDADE: pericu}
            verba_valores.update({d["cod"]: d["val"] for d in medias_det})
            aliq_fgts = _aliq_fgts_adiant13(f)
            base_fgts, fgts_val = _fgts_adiant13(inc_fgts, verba_valores, aliq_fgts)
            funcionarios.append({
                "matricula":  f.get("matricula"),
                "nome":       nome,
                "sal_fmt":    _fmt_reais(sal_mes),
                "valor_calc": valor,
                "valor_fmt":  _fmt_reais(valor),
                "pericu":     pericu,
                "pericu_fmt": _fmt_reais(pericu) if pericu else "—",
                "medias":     medias_tot,
                "medias_fmt": _fmt_reais(medias_tot) if medias_tot else "—",
                "fgts":       fgts_val,
                "fgts_fmt":   _fmt_reais(fgts_val) if fgts_val else "—",
                "total_fmt":  _fmt_reais(total_f),
            })
    except Exception as e:
        ctx["erro_critico"] = f"Erro ao carregar funcionários: {str(e)[:150]}"
        return render_template("F10_Calc_Adiantamento_13.html", **ctx)

    com = [f for f in funcionarios if (f["valor_calc"] + f["pericu"] + f["medias"]) > 0]
    ctx.update(
        funcionarios=funcionarios,
        total_funcs=len(funcionarios),
        total_com=len(com),
        total_fmt=_fmt_reais(sum(f["valor_calc"] + f["pericu"] + f["medias"] for f in com)),
    )
    return render_template("F10_Calc_Adiantamento_13.html", **ctx)


@app.route("/api/calcular_adiantamento_13", methods=["POST"])
def api_calcular_adiantamento_13():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    if not anomes:
        return jsonify({"ok": False, "msg": "Nenhuma folha ativa."})
    folha_tipo = str(session.get("anomes_tipo") or "").upper()[:1]
    if folha_tipo != "A":
        return jsonify({"ok": False, "msg": "A folha ativa não é do tipo Adiantamento 13º (tipo A)."})

    folha_int = int(anomes)
    perc = _get_per_adianta13(id_empresa)   # percentual do adiantamento do 13º (por empresa)

    # médias das verbas variáveis (inc_adto13='S') — ano corrente, ÷ mês da folha
    cods_media, verbas_hora, _desc_media = _verbas_media_adiant13(id_cliente)
    ano_folha = int(anomes[:4]); mes_folha = int(anomes[4:6])
    fi = ano_folha * 100 + 1; ff = int(anomes); meses = mes_folha

    # incidência de FGTS por verba (verba 17='S'; periculosidade/médias='11')
    inc_fgts = _inc_fgts_adiant13(id_cliente, [VERBA_ADIANT_13, VERBA_PERICULOSIDADE] + cods_media)

    # limpa cálculo anterior desta folha (verba 17/31 + médias, origem calculada)
    try:
        (supabase.table("tab_mov").delete()
         .eq("id_empresa", id_empresa)
         .eq("folha",      folha_int)
         .eq("folha_tipo", "A")
         .in_("cod_verba", [VERBA_ADIANT_13, VERBA_PERICULOSIDADE] + cods_media)
         .eq("origem",     "C")
         .execute())
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao limpar cálculo anterior: {str(e)[:200]}"})

    # limpa totais anteriores (tab_total) desta folha de adiantamento 13
    try:
        q_delt = (supabase.table("tab_total").delete()
                  .eq("id_empresa", id_empresa)
                  .eq("folha",      folha_int)
                  .eq("folha_tipo", "A"))
        if id_cliente:
            q_delt = q_delt.eq("id_cliente", id_cliente)
        q_delt.execute()
    except Exception:
        pass

    # periculosidade ativa no mês (op1=41), por funcionário — entra a perc%
    try:
        pericu_map = _calc_etapa7_periculosidade(id_empresa, anomes, id_cliente=id_cliente)
    except Exception:
        pericu_map = {}

    # pasta das memórias de cálculo (1 PDF por funcionário), espelhando a folha normal
    empresa_nm = str(session.get("empresa_info") or "")
    usuario    = str(session.get("nome") or "")
    versao     = ler_versao()
    # destino das memórias: Windows local → C:\ ; Render → Supabase Storage
    dest = _memoria_destino(anomes, id_empresa)
    memorias = 0

    gravados = 0
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer, codcateg, vrsalfx, undsalfixo, qtdhrsmes, dtadm")
                 .eq("id_empresa", id_empresa)
                 .eq("situacao", "A")
                 .execute())
        for f in (r_cad.data or []):
            dtadm_raw = str(f.get("dtadm") or "")
            dtadm_anomes = (dtadm_raw[:4] + dtadm_raw[5:7]) if len(dtadm_raw) >= 7 else ""
            if dtadm_anomes and dtadm_anomes > anomes:
                continue
            if not _elegivel_adiant13(f):   # exclui cat 111 e >= 700 (sem 13º)
                continue
            sal_mes = _sal_mes_adiant13(f)
            valor   = sal_mes * perc // 100          # perc% do salário
            if valor <= 0:
                continue
            mat    = f.get("matricula")
            pericu = _pericu_adiant13(sal_mes, pericu_map.get(int(mat or 0)), perc)
            vrsalfx = int(f.get("vrsalfx") or 0)
            und     = str(f.get("undsalfixo") or "M").upper()[:1]
            qhm     = int(f.get("qtdhrsmes") or 220) or 220
            sal_hora_c = vrsalfx if und == "H" else round(vrsalfx / qhm)
            medias_det = _medias_adiant13(id_cliente, id_empresa, int(mat or 0), sal_hora_c,
                                          fi, ff, meses, perc, cods_media, verbas_hora, _desc_media)
            medias = {d["cod"]: d["val"] for d in medias_det}
            try:
                supabase.table("tab_mov").insert({
                    "id_cliente": id_cliente,
                    "id_empresa": id_empresa,
                    "situacao":   "A",
                    "matricula":  int(mat),
                    "folha":      folha_int,
                    "folha_tipo": "A",
                    "cod_verba":  VERBA_ADIANT_13,
                    "qtd":        0,
                    "valor":      valor,
                    "lote":       0,
                    "origem":     "C",
                    "controle":   0,
                    "os":         0,
                }).execute()
                gravados += 1
            except Exception as e_ins:
                return jsonify({"ok": False, "msg": f"Erro mat {mat}: {str(e_ins)[:300]}"})

            # Periculosidade (verba 31), quando ativa — perc% da periculosidade do mês
            if pericu > 0:
                try:
                    supabase.table("tab_mov").insert({
                        "id_cliente": id_cliente,
                        "id_empresa": id_empresa,
                        "situacao":   "A",
                        "matricula":  int(mat),
                        "folha":      folha_int,
                        "folha_tipo": "A",
                        "cod_verba":  VERBA_PERICULOSIDADE,
                        "qtd":        0,
                        "valor":      pericu,
                        "lote":       0,
                        "origem":     "C",
                        "controle":   0,
                        "os":         0,
                    }).execute()
                except Exception as e_ins:
                    return jsonify({"ok": False, "msg": f"Erro periculosidade mat {mat}: {str(e_ins)[:300]}"})

            # Médias das verbas variáveis (uma linha por verba, cada uma com seu código)
            for cod_m, val_m in sorted(medias.items()):
                try:
                    supabase.table("tab_mov").insert({
                        "id_cliente": id_cliente,
                        "id_empresa": id_empresa,
                        "situacao":   "A",
                        "matricula":  int(mat),
                        "folha":      folha_int,
                        "folha_tipo": "A",
                        "cod_verba":  cod_m,
                        "qtd":        0,
                        "valor":      val_m,
                        "lote":       0,
                        "origem":     "C",
                        "controle":   0,
                        "os":         0,
                    }).execute()
                except Exception as e_ins:
                    return jsonify({"ok": False, "msg": f"Erro média verba {cod_m} mat {mat}: {str(e_ins)[:300]}"})

            # Totais (tab_total): adiantamento sem INSS/IRRF, COM FGTS (verba 17
            # incide FGTS — tpn_inc_fgts='S'). Proventos = adiant. + pericul. + médias.
            prov_total = valor + pericu + sum(medias.values())
            verba_valores = {VERBA_ADIANT_13: valor, VERBA_PERICULOSIDADE: pericu}
            verba_valores.update(medias)
            aliq_fgts = _aliq_fgts_adiant13(f)
            base_fgts, fgts_val = _fgts_adiant13(inc_fgts, verba_valores, aliq_fgts)
            rec_total = {
                "id_cliente":                id_cliente,
                "id_empresa":                id_empresa,
                "situacao":                  "A",
                "matricula":                 int(mat),
                "folha":                     folha_int,
                "folha_tipo":                "A",
                "valor_base_inss_semlimite": 0,
                "valor_base_inss_comlimite": 0,
                "valor_inss_retido":         0,
                "valor_base_fgts":           int(base_fgts),
                "valor_fgts":                int(fgts_val),
                "valor_irrf_basetotal":      0,
                "valor_irrf_basetabela":     0,
                "valor_irrf_dependentes":    0,
                "qtd_irrf_dependentes":      0,
                "valor_salario":             int(sal_mes),
                "valor_total_proventos":     int(prov_total),
                "valor_total_descontos":     0,
                "valor_liquido":             int(prov_total),
                "os":                        0,
                "controle":                  0,
            }
            try:
                supabase.table("tab_total").insert(rec_total).execute()
            except Exception:
                # tenta sem a coluna situacao (pode não existir na tabela)
                try:
                    supabase.table("tab_total").insert(
                        {k: v for k, v in rec_total.items() if k != "situacao"}).execute()
                except Exception:
                    pass

            # Memória de cálculo — 1 PDF por funcionário (local C:\ ou Storage)
            if dest.get("base"):
                try:
                    ev_p      = pericu_map.get(int(mat or 0))
                    ref1_p    = int(ev_p.get("ref1") or 0) if ev_p else 0
                    pericu_mes = int(sal_mes * ref1_p / 10000) if ref1_p > 0 else 0
                    nome_pdf  = (f.get("nome") or f.get("nomer") or "").strip()
                    pdf_bytes = _pdf_memoria_adiant13(
                        empresa_nm, anomes, int(mat or 0), nome_pdf, sal_mes, sal_hora_c,
                        perc, meses, valor, pericu, ref1_p / 100, pericu_mes,
                        medias_det, prov_total, usuario, versao, base_fgts, fgts_val, aliq_fgts)
                    nome_arq = (f"Folha10_MemoriaAdiant13_Empresa_{int(id_empresa):06d}_"
                                f"Folha_{anomes}_Matricula_{int(mat or 0):06d}.pdf")
                    if _salvar_memoria_pdf(dest, nome_arq, pdf_bytes):
                        memorias += 1
                except Exception:
                    pass
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})

    # marca a folha (tipo 'A') como Calculada em tab_anomes
    n_calc = _marcar_folha_calculada_adiant13(id_cliente, id_empresa, anomes)
    session["anomes_situacao"] = "C"

    return jsonify({"ok": True, "gravados": gravados, "verba": VERBA_ADIANT_13,
                    "pasta": dest.get("label", ""), "memorias": memorias,
                    "n_calculo": n_calc})


@app.route("/api/calcular_adiantamento_13_stream")
def calcular_adiantamento_13_stream():
    """Versão em streaming (SSE) do cálculo do adiantamento do 13º — emite
    progresso por funcionário para a barra de acompanhamento na tela.
    Mesma lógica de gravação de /api/calcular_adiantamento_13."""
    if not session.get("logado"):
        return Response("data: {}\n\n", mimetype="text/event-stream")

    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")
    anomes     = str(session.get("anomes_atual") or "")
    folha_tipo = str(session.get("anomes_tipo") or "").upper()[:1]
    empresa_nm = str(session.get("empresa_info") or "")
    usuario    = str(session.get("nome") or "")
    versao     = ler_versao()

    def _sse_erro(msg):
        payload = json.dumps({"tipo": "erro", "msg": msg}, ensure_ascii=False)
        return Response(f"data: {payload}\n\n", mimetype="text/event-stream")

    if not anomes:
        return _sse_erro("Nenhuma folha ativa.")
    if folha_tipo != "A":
        return _sse_erro("A folha ativa não é do tipo Adiantamento 13º (tipo A).")

    # Rede de segurança: só calcula com a folha Aberta (A/X). Se já está
    # Calculada/Fechada/em cálculo, emite "bloqueio" — o front avisa e (para
    # 'C') oferece reabrir e recalcular, como na folha mensal.
    sit = _refresh_situacao_folha()
    if sit not in ("A", "X"):
        if sit == "P":
            msg = "Folha em cálculo por outro usuário. Aguarde."
        elif sit == "F":
            msg = "Folha Fechada — reabra antes de calcular."
        else:
            msg = "Folha já está calculada."
        payload = json.dumps({"tipo": "bloqueio", "msg": msg, "sit": sit}, ensure_ascii=False)
        return Response(f"data: {payload}\n\n", mimetype="text/event-stream")

    folha_int  = int(anomes)
    perc       = _get_per_adianta13(id_empresa)
    cods_media, verbas_hora, _desc_media = _verbas_media_adiant13(id_cliente)
    inc_fgts   = _inc_fgts_adiant13(id_cliente, [VERBA_ADIANT_13, VERBA_PERICULOSIDADE] + cods_media)
    ano_folha  = int(anomes[:4]); mes_folha = int(anomes[4:6])
    fi = ano_folha * 100 + 1; ff = int(anomes); meses = mes_folha

    q = queue.Queue()

    def _put(obj):
        q.put(json.dumps(obj, ensure_ascii=False))

    def _mov(mat, cod, valor):
        return {"id_cliente": id_cliente, "id_empresa": id_empresa, "situacao": "A",
                "matricula": int(mat), "folha": folha_int, "folha_tipo": "A",
                "cod_verba": cod, "qtd": 0, "valor": valor, "lote": 0,
                "origem": "C", "controle": 0, "os": 0}

    def run():
        try:
            # limpa cálculo anterior (verba 17/31 + médias, origem calculada)
            try:
                (supabase.table("tab_mov").delete()
                 .eq("id_empresa", id_empresa).eq("folha", folha_int).eq("folha_tipo", "A")
                 .in_("cod_verba", [VERBA_ADIANT_13, VERBA_PERICULOSIDADE] + cods_media)
                 .eq("origem", "C").execute())
            except Exception as e:
                _put({"tipo": "erro", "msg": f"Erro ao limpar cálculo anterior: {str(e)[:200]}"})
                return
            # limpa totais anteriores desta folha de adiantamento
            try:
                q_delt = (supabase.table("tab_total").delete()
                          .eq("id_empresa", id_empresa).eq("folha", folha_int).eq("folha_tipo", "A"))
                if id_cliente:
                    q_delt = q_delt.eq("id_cliente", id_cliente)
                q_delt.execute()
            except Exception:
                pass

            try:
                pericu_map = _calc_etapa7_periculosidade(id_empresa, anomes, id_cliente=id_cliente)
            except Exception:
                pericu_map = {}

            # destino das memórias: Windows local → C:\ ; Render → Supabase Storage
            dest = _memoria_destino(anomes, id_empresa)

            r_cad = (supabase.table("tab_cad")
                     .select("matricula, nome, nomer, codcateg, vrsalfx, undsalfixo, qtdhrsmes, dtadm")
                     .eq("id_empresa", id_empresa).eq("situacao", "A").order("nomer").execute())
            elegiveis = []
            for f in (r_cad.data or []):
                dtadm_raw = str(f.get("dtadm") or "")
                dtadm_anomes = (dtadm_raw[:4] + dtadm_raw[5:7]) if len(dtadm_raw) >= 7 else ""
                if dtadm_anomes and dtadm_anomes > anomes:
                    continue
                if not _elegivel_adiant13(f):   # exclui cat 111 e >= 700 (sem 13º)
                    continue
                elegiveis.append(f)

            total     = len(elegiveis)
            gravados  = 0
            memorias  = 0
            total_val = 0
            for idx, f in enumerate(elegiveis, start=1):
                mat  = int(f.get("matricula") or 0)
                nome = (f.get("nome") or f.get("nomer") or "").strip()
                _put({"tipo": "func", "pct": int(idx / total * 100) if total else 100,
                      "matr": f"{mat:06d}", "nome": nome})

                sal_mes = _sal_mes_adiant13(f)
                valor   = sal_mes * perc // 100
                if valor <= 0:
                    continue
                pericu  = _pericu_adiant13(sal_mes, pericu_map.get(mat), perc)
                vrsalfx = int(f.get("vrsalfx") or 0)
                und     = str(f.get("undsalfixo") or "M").upper()[:1]
                qhm     = int(f.get("qtdhrsmes") or 220) or 220
                sal_hora_c = vrsalfx if und == "H" else round(vrsalfx / qhm)
                medias_det = _medias_adiant13(id_cliente, id_empresa, mat, sal_hora_c,
                                              fi, ff, meses, perc, cods_media, verbas_hora, _desc_media)
                medias = {d["cod"]: d["val"] for d in medias_det}

                try:
                    supabase.table("tab_mov").insert(_mov(mat, VERBA_ADIANT_13, valor)).execute()
                    gravados += 1
                except Exception as e_ins:
                    _put({"tipo": "erro", "msg": f"Erro mat {mat}: {str(e_ins)[:300]}"})
                    return
                if pericu > 0:
                    try:
                        supabase.table("tab_mov").insert(_mov(mat, VERBA_PERICULOSIDADE, pericu)).execute()
                    except Exception as e_ins:
                        _put({"tipo": "erro", "msg": f"Erro periculosidade mat {mat}: {str(e_ins)[:300]}"})
                        return
                for cod_m, val_m in sorted(medias.items()):
                    try:
                        supabase.table("tab_mov").insert(_mov(mat, cod_m, val_m)).execute()
                    except Exception as e_ins:
                        _put({"tipo": "erro", "msg": f"Erro média verba {cod_m} mat {mat}: {str(e_ins)[:300]}"})
                        return

                prov_total = valor + pericu + sum(medias.values())
                total_val += prov_total
                verba_valores = {VERBA_ADIANT_13: valor, VERBA_PERICULOSIDADE: pericu}
                verba_valores.update(medias)
                aliq_fgts = _aliq_fgts_adiant13(f)
                base_fgts, fgts_val = _fgts_adiant13(inc_fgts, verba_valores, aliq_fgts)
                rec_total = {
                    "id_cliente": id_cliente, "id_empresa": id_empresa, "situacao": "A",
                    "matricula": int(mat), "folha": folha_int, "folha_tipo": "A",
                    "valor_base_inss_semlimite": 0, "valor_base_inss_comlimite": 0,
                    "valor_inss_retido": 0,
                    "valor_base_fgts": int(base_fgts), "valor_fgts": int(fgts_val),
                    "valor_irrf_basetotal": 0, "valor_irrf_basetabela": 0,
                    "valor_irrf_dependentes": 0, "qtd_irrf_dependentes": 0,
                    "valor_salario": int(sal_mes), "valor_total_proventos": int(prov_total),
                    "valor_total_descontos": 0, "valor_liquido": int(prov_total),
                    "os": 0, "controle": 0,
                }
                try:
                    supabase.table("tab_total").insert(rec_total).execute()
                except Exception:
                    try:
                        supabase.table("tab_total").insert(
                            {k: v for k, v in rec_total.items() if k != "situacao"}).execute()
                    except Exception:
                        pass

                if dest.get("base"):
                    try:
                        ev_p       = pericu_map.get(mat)
                        ref1_p     = int(ev_p.get("ref1") or 0) if ev_p else 0
                        pericu_mes = int(sal_mes * ref1_p / 10000) if ref1_p > 0 else 0
                        pdf_bytes  = _pdf_memoria_adiant13(
                            empresa_nm, anomes, mat, nome, sal_mes, sal_hora_c,
                            perc, meses, valor, pericu, ref1_p / 100, pericu_mes,
                            medias_det, prov_total, usuario, versao, base_fgts, fgts_val, aliq_fgts)
                        nome_arq = (f"Folha10_MemoriaAdiant13_Empresa_{int(id_empresa):06d}_"
                                    f"Folha_{anomes}_Matricula_{mat:06d}.pdf")
                        if _salvar_memoria_pdf(dest, nome_arq, pdf_bytes):
                            memorias += 1
                    except Exception:
                        pass

            # marca a folha (tipo 'A') como Calculada em tab_anomes
            n_calc = _marcar_folha_calculada_adiant13(id_cliente, id_empresa, anomes)

            _put({"tipo": "fim", "pct": 100, "resumo": {
                "gravados": gravados, "verba": VERBA_ADIANT_13, "pasta": dest.get("label", ""),
                "memorias": memorias, "total_funcs": total, "total_valor": total_val,
                "perc": perc, "n_calculo": n_calc}})
        except Exception as e:
            _put({"tipo": "erro", "msg": str(e)[:200]})
        finally:
            q.put(None)

    threading.Thread(target=run, daemon=True).start()

    @stream_with_context
    def generate():
        while True:
            item = q.get()
            if item is None:
                break
            yield f"data: {item}\n\n"

    return Response(generate(), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


# =========================================================
# LISTAGEM DE ADIANTAMENTOS
# =========================================================
VERBAS_ADIANTAMENTO = (161, 162, 163, 164)

@app.route("/listagem_adiantamentos")
def listagem_adiantamentos():
    if not session.get("logado"):
        return redirect("/")
    anomes     = str(session.get("anomes_atual") or "")
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    # Folhas que já têm adiantamentos lançados
    folhas_disponiveis = []
    try:
        r = (supabase.table("tab_mov")
             .select("folha")
             .eq("id_empresa", id_empresa)
             .eq("id_cliente", id_cliente)
             .eq("situacao", "A")
             .in_("cod_verba", list(VERBAS_ADIANTAMENTO))
             .execute())
        vistos = set()
        for row in (r.data or []):
            f = row.get("folha")
            if f and f not in vistos:
                vistos.add(f)
                folhas_disponiveis.append({"folha": f})
        folhas_disponiveis.sort(key=lambda x: x["folha"], reverse=True)
    except Exception:
        pass

    # Garante que a folha atual aparece no seletor, mesmo sem registros
    folha_sel = int(anomes) if anomes else None
    if folha_sel and not any(f["folha"] == folha_sel for f in folhas_disponiveis):
        folhas_disponiveis.insert(0, {"folha": folha_sel})

    return render_template(
        "F10_Rel_Adiantamentos.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        anomes_atual=anomes,
        folha_selecionada=folha_sel,
        folhas_disponiveis=folhas_disponiveis,
    )


@app.route("/api/adiantamento_listagem")
def api_adiantamento_listagem():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    id_cliente = session.get("id_cliente")

    folha_str = request.args.get("folha", "").strip()
    if not folha_str:
        return jsonify({"ok": False, "msg": "Folha não informada."})
    try:
        folha = int(folha_str)
    except ValueError:
        return jsonify({"ok": False, "msg": "Folha inválida."})

    # Registros de adiantamento do tab_mov
    try:
        r_mov = (supabase.table("tab_mov")
                 .select("id, matricula, cod_verba, valor")
                 .eq("id_empresa", id_empresa)
                 .eq("id_cliente", id_cliente)
                 .eq("folha",      folha)
                 .eq("situacao",   "A")
                 .in_("cod_verba", list(VERBAS_ADIANTAMENTO))
                 .order("matricula")
                 .execute())
        registros_raw = r_mov.data or []
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})

    if not registros_raw:
        return jsonify({"ok": True, "registros": []})

    # Nomes dos funcionários
    mats = list({r["matricula"] for r in registros_raw if r.get("matricula")})
    nomes_map = {}
    try:
        r_cad = (supabase.table("tab_cad")
                 .select("matricula, nome, nomer")
                 .eq("id_empresa", id_empresa)
                 .in_("matricula", mats)
                 .execute())
        for f in (r_cad.data or []):
            nomes_map[f["matricula"]] = (f.get("nome") or f.get("nomer") or "").strip()
    except Exception:
        pass

    # Descrições das verbas
    verbas_map = {}
    try:
        r_v = (supabase.table("tab_rubrica")
               .select("cod_rubr, dsc_rubr")
               .in_("cod_rubr", list(VERBAS_ADIANTAMENTO))
               .execute())
        for v in (r_v.data or []):
            verbas_map[v["cod_rubr"]] = v.get("dsc_rubr") or ""
    except Exception:
        pass

    registros = [
        {
            "id":        r["id"],
            "matricula": r["matricula"],
            "nome":      nomes_map.get(r["matricula"], ""),
            "cod_verba": r["cod_verba"],
            "dsc_rubr":  verbas_map.get(r["cod_verba"], ""),
            "valor":     r.get("valor") or 0,
        }
        for r in registros_raw
    ]

    return jsonify({"ok": True, "registros": registros})


@app.route("/api/adiantamento_excluir", methods=["POST"])
def api_adiantamento_excluir():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    data = request.get_json(force=True) or {}
    id_mov = data.get("id")
    if not id_mov:
        return jsonify({"ok": False, "msg": "ID não informado."})
    try:
        (supabase.table("tab_mov")
         .update({"situacao": "D"})
         .eq("id",         int(id_mov))
         .eq("id_empresa", id_empresa)
         .in_("cod_verba", list(VERBAS_ADIANTAMENTO))
         .execute())
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200]})


